INSERT INTO `j7_acymailing_mail` (`mailid`, `subject`, `body`, `altbody`, `published`, `senddate`, `created`, `fromname`, `fromemail`, `replyname`, `replyemail`, `type`, `visible`, `userid`, `alias`, `attach`, `html`, `tempid`, `key`, `frequency`, `params`, `sentby`, `metakey`, `metadesc`, `filter`, `language`, `abtesting`, `thumb`, `summary`, `favicon`, `bccaddresses`) VALUES
(1, 'New Subscriber on your website : {user:email}', '<p>Hello {subtag:name},</p><p>A new user has been created in AcyMailing : </p><blockquote><p>Name : {user:name}</p><p>Email : {user:email}</p><p>IP : {user:ip} </p><p>Subscription : {user:subscription}</p></blockquote>', '', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'notification', 0, NULL, 'notification_created', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL, '', NULL, NULL),
(2, 'A User unsubscribed from all your lists : {user:email}', '<p>Hello {subtag:name},</p><p>The user {user:name} : {user:email} unsubscribed from all your lists</p><p>Subscription : {user:subscription}</p><p>{survey}</p>', '', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'notification', 0, NULL, 'notification_unsuball', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL, '', NULL, NULL),
(3, 'A User unsubscribed : {user:email}', '<p>Hello {subtag:name},</p><p>The user {user:name} : {user:email} unsubscribed from your list</p><p>Subscription : {user:subscription}</p><p>{survey}</p>', '', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'notification', 0, NULL, 'notification_unsub', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL, '', NULL, NULL),
(4, 'A User refuses to receive e-mails from your website : {user:email}', '<p>The User {user:name} : {user:email} refuses to receive any e-mail anymore from your website.</p><p>Subscription : {user:subscription}</p><p>{survey}</p>', '', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'notification', 0, NULL, 'notification_refuse', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL, '', NULL, NULL),
(5, 'New contact from your website : {user:email}', '<p>Hello {subtag:name},</p><p>A user has contacted you : </p><blockquote><p>Name : {user:name}</p><p>Email : {user:email}</p><p>IP : {user:ip} </p><p>Subscription : {user:subscription}</p></blockquote>', '', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'notification', 0, NULL, 'notification_contact', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL, '', NULL, NULL),
(6, 'A user confirm his subscription : {user:email}', '<p>Hello {subtag:name},</p><p>A user has confirmed his subscription in AcyMailing : </p><blockquote><p>Name : {user:name}</p><p>Email : {user:email}</p><p>IP : {user:ip} </p><p>Subscription : {user:subscription}</p></blockquote>', '', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'notification', 0, NULL, 'notification_confirm', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL, '', NULL, NULL),
(7, '{subtag:name|ucfirst}, {trans:PLEASE_CONFIRM_SUB}', '<div style="text-align: center; width: 100%; background-color: #ffffff;">\r\n			<table style="text-align:justify; margin:auto; background-color:#ebebeb; border:1px solid #e7e7e7" border="0" cellspacing="0" cellpadding="0" width="600" align="center" bgcolor="#ebebeb">\r\n			<tbody>\r\n			<tr style="line-height: 0px;">\r\n			<td style="line-height: 0px;" height="38px"><img src="media/com_acymailing/templates/newsletter-4/images/top.png" border="0" alt=" - - - " /></td>\r\n			</tr>\r\n			<tr>\r\n			<td style="text-align:center" width="600">\r\n			<table style="margin:auto;" border="0" cellspacing="0" cellpadding="0" width="520">\r\n			<tbody>\r\n			<tr>\r\n			<td style="background-color: #ffffff; border: 1px solid #dbdbdb; padding: 20px; width: 500px; margin: 15px auto; text-align: left;">\r\n			<h1>Hello {subtag:name|ucfirst},</h1>\r\n			<p>{trans:CONFIRM_MSG}<br /><br />{trans:CONFIRM_MSG_ACTIVATE}</p>\r\n			<br />\r\n			<p style="text-align:center;"><strong>{confirm}{trans:CONFIRM_SUBSCRIPTION}{/confirm}</strong></p>\r\n			</td>\r\n			</tr>\r\n			</tbody>\r\n			</table>\r\n			</td>\r\n			</tr>\r\n			<tr style="line-height: 0px;">\r\n			<td style="line-height: 0px;" height="40px"><img src="media/com_acymailing/templates/newsletter-4/images/bottom.png" border="0" alt=" - - - " /></td>\r\n			</tr>\r\n			</tbody>\r\n			</table>\r\n			</div>', '', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'notification', 0, NULL, 'confirmation', NULL, 1, 1, NULL, NULL, 'a:3:{s:6:"action";s:7:"confirm";s:13:"actionbtntext";s:28:"{trans:CONFIRM_SUBSCRIPTION}";s:9:"actionurl";s:19:"{confirm}{/confirm}";}', NULL, NULL, NULL, NULL, '', NULL, NULL, '', NULL, NULL),
(8, 'AcyMailing Cron Report {mainreport}', '<p>{report}</p><p>{detailreport}</p>', '', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'notification', 0, NULL, 'report', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL, '', NULL, NULL),
(9, 'A Newsletter has been generated : "{subject}"', '<p>The Newsletter issue {issuenb} has been generated : </p><p>Subject : {subject}</p><p>{body}</p>', '', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'notification', 0, NULL, 'notification_autonews', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL, '', NULL, NULL),
(10, 'Modify your subscription', '<p>Hello {subtag:name}, </p><p>You requested some changes on your subscription,</p><p>Please {modify}click here{/modify} to be identified as the owner of this account and then modify your subscription.</p>', '', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'notification', 0, NULL, 'modif', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', NULL, NULL, '', NULL, NULL),
(11, 'А вто и первое письмо', '<h1>Заголовок H1</h1>\r\n<p>Тестирование</p>\r\n<h2>Заголовок h2</h2>\r\n<p>Тестирование</p>\r\n<table style="width: 100%;" border="1">\r\n<tbody>\r\n<tr>\r\n<td>test</td>\r\n<td>test</td>\r\n</tr>\r\n<tr>\r\n<td>test</td>\r\n<td>tets</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<p><img alt="1" src="images/1.png" height="210" width="318" /></p>', 'Заголовок H1\r\nТестирование\r\n\r\n\\Заголовок h2\r\nТестирование', 1, 1386056330, 1382170803, 'ЭмМенеджмент', 'ammanagment@yandex.ru', 'Ирина', 'ammanagment@yandex.ru', 'news', 1, 42, 'emmenedzhemnt', 'a:1:{i:0;O:8:"stdClass":2:{s:8:"filename";s:49:"media/com_acymailing/upload/export_2013-10-19.csv";s:4:"size";i:829;}}', 1, 0, '0c2c2227318326c1f1106e9b56301c7e', NULL, NULL, 42, '', '', NULL, '', NULL, NULL, '', NULL, NULL),
(12, 'А вам бы хотелось  выполнять задачи в РАЗЫ быстрее?! Обучайтесь эффективному Тайм - Менеджменту. ', '<div><b><span style="font-size: 16pt; line-height: 115%; font-family: ''Times New Roman''; color: blue;"><img alt="12345" src="images/12345.jpg" height="106" width="758" /></span></b></div>\r\n<p><b><span style="font-size: 16pt; line-height: 115%; font-family: ''Times New Roman''; color: blue;"><span style="font-size: 12pt;">Тайм-менеджмент для руководителей: организация рабочего времени, делегирование, совещание.&nbsp;&nbsp;</span> <br /></span></b></p>\r\n<div style="text-align: justify;"><strong><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';">Ведущий:</span></strong><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';"><a href="index.php?option=com_content&amp;view=article&amp;id=52:biznes-trener-khabirova-tatyana&amp;catid=2:uncategorised"> Татьяна Хабирова (резюме)</a>, бизнес - тренер по управлению персоналом</span></div>\r\n<p style="text-align: justify;"><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';"><strong>В результате вы </strong>: </span></p>\r\n<ul>\r\n<li>\r\n<p><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';">Будете д<span style="line-height: 115%; font-family: ''Times New Roman''; color: #000000;">остигать цели в РАЗЫ быстрее, на которые раньше уходили месяцы</span></span></p>\r\n</li>\r\n<li>\r\n<p><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';"><span style="line-height: 115%; font-family: ''Times New Roman''; color: #000000;">Научитесь эффективно делегировать задачи сотрудникам, давать и получать обратную связь<br /></span></span></p>\r\n</li>\r\n<li>\r\n<p><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';"><span style="line-height: 115%; font-family: ''Times New Roman''; color: #000000;">Увеличите производительность труда персонала и фактические показатели прибыли.<br /></span></span></p>\r\n</li>\r\n<li>\r\n<p><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';"><span style="line-height: 115%; font-family: ''Times New Roman''; color: #000000;">Включите мотивацию сотрудников.<br /></span></span></p>\r\n</li>\r\n</ul>\r\n<div><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';"><strong>Целевая аудитория</strong>: </span><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';"><span style="font-family: times new roman,times;">руководители и менеджеры высшего и среднего звена.</span><br /></span></div>\r\n<div><span style="font-family: times new roman,times;"><span style="font-size: 12pt; line-height: 115%; color: purple;">&nbsp;</span></span></div>\r\n<div><span style="font-family: times new roman,times;"><span style="font-size: 12pt; line-height: 115%; color: purple;">В программе тренинга:</span></span></div>\r\n<div>&nbsp;\r\n<ul>\r\n<li style="text-align: left;"><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';">Как использовать инструменты тайм-менеджмента: &nbsp; целеполагание, расстановка приоритетов, как сократить «поглотителей времени», какие методы планирования применять (6М, метод </span><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';">ALP</span><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';">, SMART, матрица Эйзенхауэра)</span></li>\r\n</ul>\r\n</div>\r\n<div>\r\n<ul style="margin-top: 0cm;">\r\n<li style="text-align: left;">\r\n<p><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';">Как организовывать работу подчиненных, делегировать полномочия и контролировать выполнение задач, как предоставлять сотруднику развивающую обратную связь </span></p>\r\n</li>\r\n<li style="text-align: left;">\r\n<p><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';">Подготовка и проведение совещаний</span></p>\r\n</li>\r\n<li style="text-align: left;">\r\n<p><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';">Способы структурирования рабочего пространства, организации личных и телефонных переговоров</span></p>\r\n</li>\r\n<li style="text-align: left;">\r\n<p><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';">Разрешение и предотвращение конфликтных ситуации в коллективе</span></p>\r\n</li>\r\n<li style="text-align: left;">\r\n<p><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';">Как сохранять баланс в жизни и находить источники повышения работоспособности</span></p>\r\n</li>\r\n<li>\r\n<p style="text-align: left;"><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';">Методы предупреждения стресса и эмоционального выгорания руководителя</span></p>\r\n</li>\r\n</ul>\r\n</div>\r\n<div style="text-align: justify;"><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';">&nbsp;&nbsp; Для корпоративных клиентов программа составляется с учетом индивидуальных потребностей. Продолжительность тренинга:</span><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';"> 2 дня с 10.00 до 18.00&nbsp; Дата проведения 01-02.02.2014<br /></span></div>\r\n<div style="text-align: justify;"><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';"><span style="font-size: 12pt; font-family: ''Times New Roman''; color: blue;">т. +7 (343) 266-79-85, 328-46-62</span></span><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';"><span style="font-size: 12pt; font-family: ''Times New Roman'';"> </span></span><b><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';"><span style="font-size: 12pt; font-family: ''Times New Roman'';">&nbsp;</span></span></b><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';"><span style="font-size: 12pt; font-family: ''Times New Roman'';"> Более полная программа</span></span><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';"><span style="font-size: 12pt; font-family: ''Times New Roman'';"> <span style="color: #0000ff;"><a href="index.php?option=com_content&amp;view=article&amp;id=50:tajm-menedzhment-trening-dlya-rukovoditelej-organizatsiya-rabochego-vremeni-delegirovanie-soveshchanie&amp;catid=2:uncategorised"><span style="color: #0000ff;">http://эмменеджмент.рф/</span>&nbsp;</a></span></span></span><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';"><span style="font-size: 12pt; font-family: ''Times New Roman'';"><span style="color: #0000ff;">&nbsp;</span></span></span><b><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';"><span style="font-size: 12pt; font-family: ''Times New Roman'';"><span style="color: #0000ff;"> </span></span></span></b></div>\r\n<div style="text-align: justify;"><b><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';">&nbsp;&nbsp;&nbsp;&nbsp; Методика проведения</span></b><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';">: мини-лекции, групповые дискуссии и мозговые штурмы, деловые и ситуационные игры, работа в мини-группах, разбор конкретных ситуаций, практические упражнения по отработке навыков.</span></div>', '', 1, 1390305790, 1387190340, '', '', '', '', 'news', 1, 42, 'a-va-khotelos-by-vypolnyat-tseli-za-nedelyu-na-kotorye-ranshe-ukhodili-mesyatsa', NULL, 1, 0, '0aa67aeacb19ac059be5f6aa80161011', NULL, NULL, 42, '', '', NULL, '', NULL, NULL, '', NULL, NULL),
(13, 'Как составить оптимальный договор и застраховаться от рисков неблагонадежности. Семинар 25-26.01.14', '<p><a href="http://эмменеджмент.рф/"><img alt="12345" src="images/12345.jpg" height="111" width="812" /></a><br /><span style="color: #0000ff;"><span style="font-size: 12pt;"><strong><span style="font-family: times new roman,times;"><span style="font-family: times new roman,times; color: #0000ff;" class="temaname"> </span></span></strong></span></span></p>\r\n<p><span style="color: #0000ff;"><span style="font-size: 12pt;"><strong><span style="font-family: times new roman,times;"><span style="font-family: times new roman,times; color: #0000ff;" class="temaname">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span></span></strong><span style="font-family: times new roman,times;"><span style="font-family: times new roman,times; color: #0000ff;" class="temaname">&nbsp; </span></span></span><span style="font-size: 12pt; font-family: times new roman,times;"><strong><span style="font-size: 14pt;"><span style="font-size: 12pt;">Как составить оптимальный договор и застраховаться от рисков неблагонадежности. Эффективная претензионная и исковая работа.</span></span> <span style="font-size: 14pt;">Нововведения гражданского законодательства в</span> 2013-2014 <span style="font-size: 14pt;">году. <span style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #ff0000;"><strong style="color: #ff0000;"></strong></span> </span></span></strong><br /></span></span></p>\r\n<p><span style="font-size: 12pt; font-family: times new roman,times; color: #000080;"><span style="color: #800080;">Дата проведения</span> 25.01 -26.01.14 <span style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #ff0000;"><strong style="color: #ff0000;"></strong></span> </span><br /></span></p>\r\n<div style="text-align: justify;"><span style="font-size: 12pt; font-family: times new roman,times;">&nbsp;&nbsp;&nbsp;&nbsp; <span style="font-size: 12pt; font-family: times new roman,times;">Семинар&nbsp; "Как составить договор" предназначен <span style="color: #0000ff;">для предпринимателей, менеджеров, специалистов по договорной работе,&nbsp; бухгалтерских служб</span></span><span style="color: #17365d;"><span style="color: #000000;"><span style="color: #0000ff;">.</span> После прохождения курса вы &nbsp;&nbsp;&nbsp;&nbsp;</span> </span></span></div>\r\n<ul style="list-style-type: square;">\r\n<li style="text-indent: 9pt;">\r\n<div><span style="font-family: times new roman,times; font-size: 12pt; color: #000000;">получите знания и навыки составления и проверки договоров любой сложности</span></div>\r\n</li>\r\n<li style="text-indent: 9pt;">\r\n<div><span style="font-family: times new roman,times; font-size: 12pt; color: #000000;">минимизируете риски неблагонадежности</span></div>\r\n</li>\r\n<li>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt; color: #000000;">&nbsp;&nbsp; <span style="font-family: times new roman,times; font-size: 12pt;">сократите дебиторскую задолженность</span> </span></div>\r\n</li>\r\n<li>\r\n<div><span style="color: #000000;"><span style="font-size: 12pt; font-family: times new roman,times;">&nbsp;&nbsp; обретете юридическую самостоятельность и&nbsp; правовую защиту вашего предприятия </span></span><span style="color: #0000ff;"><a style="font-family: times new roman,times; font-size: 12pt;" href="http://эмменеджмент.рф/#call_me"><span style="color: #0000ff;">Отправить заявку</span></a></span></div>\r\n</li>\r\n</ul>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-size: 14pt; font-family: ''Times New Roman'',''serif'';"><span style="font-family: times new roman,times; font-size: 12pt;">&nbsp;&nbsp;&nbsp; </span><span style="color: #800080; font-size: 12pt;">В программе</span></span><br /><strong><span style="color: #0000ff;"></span></strong></span></span></div>\r\n<div style="text-indent: 9pt;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: blue;">Актуальные вопросы заключения, изменения, расторжения договора</span></span></div>\r\n<div><span>•&nbsp;&nbsp; &nbsp;<span style="font-family: times new roman,times; font-size: 12pt;">Проверка полномочий лица, заключающего договор.</span><br /><span style="font-family: times new roman,times; font-size: 12pt;"> •&nbsp;&nbsp; &nbsp;Последствия заключения договора неуполномоченным лицом.</span></span></div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;">•&nbsp;&nbsp;&nbsp; Процедура проверки благонадежности контрагента</span></div>\r\n<div><span style="font-size: 12pt; font-family: times new roman,times;">•&nbsp;&nbsp; &nbsp;Определение существенных условий договора и правовые последствия: примеры судебной практики.<br /> •&nbsp;&nbsp; &nbsp;Актуальные вопросы заключения предварительного договора (протокол о намерениях) на примерах судебных дел.</span></div>\r\n<div><span>•&nbsp;&nbsp; &nbsp;<span style="font-family: times new roman,times; font-size: 12pt;">Построение регламента ведения договорной работы с целью минимизации судебных рисков. </span></span></div>\r\n<div>&nbsp;<span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: blue;">Способы обеспечения и исполнения договорных обязательств</span><br /> •&nbsp;&nbsp; &nbsp;Аванс, залог, задаток: особенности применения, различия, налогообложение.<br /> •&nbsp;&nbsp; &nbsp;Удержание, поручительство и неустойка: судебная практика.<br /> <span style="color: blue;">Особенности гражданско-правовой ответственности по договору:</span></span></div>\r\n<div>&nbsp;<span style="font-size: 12pt; font-family: times new roman,times;">• &nbsp; Штраф, пени, упущенная выгода, в чем разница?</span></div>\r\n<div>&nbsp;<span style="font-size: 12pt; font-family: times new roman,times;">• &nbsp;Законная и договорная неустойка</span></div>\r\n<div>&nbsp;<span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: blue;">Организация эффективной претензионной и исковой работы</span></span></div>\r\n<div>&nbsp;<span style="font-size: 12pt; font-family: times new roman,times;">•&nbsp;&nbsp; &nbsp;Организация претензионной работы. Типы и содержание претензий. Необходимые приложения.<br /> •&nbsp;&nbsp; &nbsp;Перспективы и инструменты внесудебного урегулирования спора.</span></div>\r\n<div>&nbsp;<span style="font-family: times new roman,times; font-size: 12pt;">•&nbsp;&nbsp; Регламентация работы с&nbsp;дебиторской задолженностью компании</span></div>\r\n<div>&nbsp;<span style="font-family: times new roman,times; font-size: 12pt;">•&nbsp;&nbsp; Практические аспекты отправления и&nbsp;доставки претензий.</span></div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #0000ff;"><span style="color: blue;">Практические советы по прекращению договорных обязательств</span><br /> <span style="color: #000000;">•&nbsp;&nbsp; &nbsp;Новация, как способ прекращения обязательств.</span><br /><span style="color: #000000;"> •&nbsp;&nbsp; &nbsp;Прощение долга – практические советы и налоговый аспект.</span><br /><span style="color: #000000;"> •&nbsp;&nbsp; &nbsp;Прекращение обязательств отступным.</span><br /><span style="color: #000000;"> •&nbsp;&nbsp; &nbsp;Судебная практика относительно перемены лиц в обязательстве.</span><br /> <em><span style="color: blue;">Договор поставки, договор аренды и другие</span></em><br /> •&nbsp;&nbsp; &nbsp;<span style="color: #000000;">Правовая позиция судов об исполнении договора как факте его заключения.</span><br /><span style="color: #000000;"> •&nbsp;&nbsp; &nbsp;Приложения к договору: могут ли они содержать существенные условия.</span><br /><span style="color: #000000;"> •&nbsp;&nbsp; &nbsp;Последствия неурегулированности разногласий между сторонами при заключении договора поставки.</span><br /><span style="color: #000000;"> •&nbsp;&nbsp; &nbsp;Проблемы<span style="font-family: times new roman,times;"> отгрузки товара. </span></span><br /><span style="font-family: times new roman,times;"><span style="color: #000000;"> </span><span style="color: #000000;">•&nbsp;&nbsp; &nbsp;Судебная практика по вопросам оплаты товара, несвоевременная оплата, неустойка.</span></span><br /><span style="color: #000000; font-family: times new roman,times;"> •&nbsp;&nbsp; &nbsp;Доказательства и доказывание отгрузки товаров ненадлежащего качества</span></span></span></div>\r\n<div><span style="font-size: 12pt; font-family: times new roman,times;"><span style="font-size: 12pt;"><span style="color: #0000ff;"><span style="color: #000000;">•&nbsp;&nbsp;&nbsp; </span></span></span>Судебная <b><span style="font-family: times new roman,times;">пра</span>ктика по вопросам аренды</b>, скользкие вопросы арендных отношений</span></div>\r\n<div>&nbsp;</div>\r\n<div><b><span style="font-size: 11pt; color: blue;"><span style="font-family: times new roman,times; font-size: 12pt;">Новеллы в гражданском законодательстве в 2013-2014 г.</span><br /> <br /> </span></b></div>\r\n<p style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #000000;">&nbsp;&nbsp;&nbsp; <span style="color: #000000;">Автор программы<strong> Шарунова Ирина Юрьевна,</strong>&nbsp; практикующий юрист, руководитель<span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #000000;"><span style="color: #000000;"><span style="font-size: 12pt; font-family: ''Times New Roman'';"> юридического отдела</span></span></span></span> ООО "<span style="font-size: 12pt; font-family: ''Times New Roman'';">СпецГазПроект", автор программ по гражданскому и трудовому законодательству.</span><br /></span></span></span></p>\r\n<div><span style="color: #ff0000;"><span style="font-family: times new roman,times; font-size: 12pt;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <span style="color: #000000;">Выдается методическая литература. Длительность 2 дня. </span></span><br /></span></div>\r\n<p><span style="color: blue; font-family: Times New Roman; font-size: x-small;" color="blue" face="Times New Roman" size="2"><span style="font-size: 11pt; color: blue;">Место проведения г. Екатеринбург, Ст. Разина 16-412&nbsp; т. <span class="wmi-callto">266-79-85</span></span></span>&nbsp; <span style="font-family: times new roman,times; color: #0000ff;"><span style="font-size: 12pt;"><a target="_blank" class="daria-goto-anchor" data-orig-href="http://xn--d1ababe6aaeff9c5g.xn--p1ai/" data-vdir-href="https://mail.yandex.ru/re.jsx?h=a,E9elZQrY2xUM0Aw8uk0Zsg&amp;l=aHR0cDovL3huLS1kMWFiYWJlNmFhZWZmOWM1Zy54bi0tcDFhaS8" href="http://xn--d1ababe6aaeff9c5g.xn--p1ai/"><span style="color: #0000ff;" color="#ac266c"><span style="color: #ac266c;">http://эмменеджмент.рф/</span></span></a>&nbsp; &nbsp; </span>&nbsp;</span>&nbsp;</p>', '', 1, 1390200198, 1387262302, '', '', '', '', 'news', 1, 42, 'kak-sostavit-optimalnyj-dogovor-novogodnyaya-skidka-10-21-22-12-13', NULL, 1, 0, 'c36a61ac53c2d4bdd36d6cb191e9df5d', NULL, NULL, 42, '', '', NULL, '', NULL, NULL, '', NULL, NULL),
(15, 'Практическое обучение 44-ФЗ и 223 - ФЗ. Семинар по госзакупкам.', '<div><b><span style="font-size: 16pt; line-height: 115%; font-family: ''Times New Roman''; color: blue;"><img alt="12345" src="images/12345.jpg" height="106" width="758" /></span></b></div>\r\n<h1 style="text-align: justify;"><span style="font-size: 14pt;"><span style="color: blue; font-family: times new roman,times;">Практическое обучение 44-</span><span style="color: blue; font-family: times new roman,times;">ФЗ, 223-ФЗ. Семинар по госзакупкам. Контрактная система - новый этап реформирования торго</span><span style="color: blue; font-family: times new roman,times;">в.</span></span></h1>\r\n<div style="text-align: justify;"><span style="font-size: 12pt; color: #000000; font-family: times new roman,times;"><strong>Целевая аудитория</strong>: Руководители и специалисты федеральных, региональных и муниципальных органов власти, бюджетных учреждений, специалисты по госзакупкам,&nbsp; руководители и специалисты тендерных отделов, руководители&nbsp; и специалисты юридических отделов и отделов продаж <strong>компаний-поставщиков (подрядчиков). <span style="font-size: 12pt;"><span style="font-family: times new roman,times;">Дата проведения 08-09.02.2014 с 10 до 18.00.</span></span></strong><br /></span></div>\r\n<p>&nbsp;<strong><span style="font-family: times new roman,times; font-size: 12pt;">Вы получите:</span></strong></p>\r\n<ul>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Практические знания и навыки&nbsp; работы с госзакупками<br /></span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Практика заполнения конкурсной документации</span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Анализ новшеств и типичных ошибок</span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Актуальная методическая литература 44-ФЗ и 223-ФЗ<br /></span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Поэтапная инструкция работы <a href="http://zakupki.gov.ru">http://zakupki.gov.ru</a> </span><span style="font-family: times new roman,times; font-size: 12pt;"><br /></span></li>\r\n</ul>\r\n<p><span style="font-family: times new roman,times; font-size: 12pt;">Обучение проходит в группе до 12 человек. Ваши вложения окупятся сотнями раз.</span></p>\r\n<div style="text-align: justify;"><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman''; color: #000000;"><span style="font-size: 12pt; font-family: ''Times New Roman'';">г. Екатеринбург, ул. Степана Разина 16-412 т. +7 (343) 266-79-85, 328-46-62.</span></span><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';"><span style="font-size: 12pt; font-family: ''Times New Roman'';"> </span></span><b><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';"><span style="font-size: 12pt; font-family: ''Times New Roman'';">&nbsp;</span></span></b><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';"><span style="font-size: 12pt; font-family: ''Times New Roman'';"> Более полная программа</span></span>&nbsp; <a href="index.php?option=com_content&amp;view=article&amp;id=54:44-fz-novaya-kontraktnaya-sistema-obuchenie-seminar-kurs&amp;catid=2:uncategorised"><span style="font-size: 12pt; color: #0000ff;"><span style="font-family: times new roman,times;">http://эмменеджмент.рф/</span></span></a><a href="index.php?option=com_content&amp;view=article&amp;id=54:44-fz-novaya-kontraktnaya-sistema-obuchenie-seminar-kurs&amp;catid=2:uncategorised"><span style="font-size: 12pt;"> </span><span style="color: #0000ff;"><b><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';"><span style="font-size: 12pt; font-family: ''Times New Roman'';"> </span></span></b></span></a></div>\r\n<div style="text-align: justify;"><b><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';">&nbsp;&nbsp;&nbsp;&nbsp; Методика проведения</span></b><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';">: информационные лекции, групповые дискуссии, деловые и ситуационные игры, работа в мини-группах, разбор конкретных ситуаций, практические упражнения&nbsp; по отработке навыков.</span></div>', '', 1, 1390911874, 1390809015, '', '', '', '', 'news', 1, 42, 'a-va-khotelos-by-vypolnyat-tseli-za-nedelyu-na-kotorye-ranshe-ukhodili-mesyatsa', NULL, 1, 0, '77fde37e97890c91b7c1fe2fd0c8acdc', NULL, NULL, 42, '', '', NULL, '', NULL, NULL, '', NULL, NULL),
(14, 'Новогодняя Скидка 10%!  до 31.12.13 на программы эффективного обучения. Сделайте себе подарок!', '<p><a href="http://эмменеджмент.рф/"><img alt="12345" src="images/12345.jpg" height="122" width="824" /></a><br /><span style="color: #0000ff;"><span style="font-size: 12pt;"><strong><span style="font-family: times new roman,times;"><span style="font-family: times new roman,times; color: #0000ff;" class="temaname"> </span></span></strong></span></span></p>\r\n<div style="text-align: justify;"><span style="color: navy;"><span style="font-size: 12pt;"><strong><span style="font-family: times new roman,times;"><span style="font-family: times new roman,times; color: #0000ff;" class="temaname">&nbsp;</span></span></strong></span><span style="font-size: 12pt; font-family: times new roman,times;">Центр эффективного обучения «ЭмМенеджмент» проводит курсы и тренинги для руководителей, финансовых менеджеров, бухгалтеров, юристов, экономистов, кадровых менеджеров и дает возможность: </span></span><span style="font-family: times new roman,times; font-size: 12pt;"><b><span style="color: purple;">приобрести необходимые знания и навыки, узнать нововведения специализации, увидеть и увеличить потенциал и прибыль вашей организации</span>.<span style="color: navy;"> </span></b><span style="color: navy;"></span></span></div>\r\n<p style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"><b><span style="color: purple;">&nbsp;</span></b><strong><span style="color: red;">НОВОГОДНЯ АКЦИЯ на стоимость ОБУЧЕНИЯ&nbsp; до 31 декабря 2013 скидка 10%</span></strong><b><span style="color: purple;"></span></b></span></p>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"><b><span style="color: purple;">&nbsp;&nbsp; </span><span style="color: #993366;">Курсы и тренинги ПРОДАЖИ</span></b></span></div>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;"><span style="font-family: times new roman,times; font-size: 12pt;"><a href="http://эмменеджмент.рф/obrazovanie/kursy-po-prodazham/2-uncategorised/48-trening-uspeshnykh-peregovorov-i-prodazh"><span style="color: #0000ff;">Тренинг успешных переговоров и продаж</span></a></span></span></div>\r\n<div style="text-align: justify;"><span style="color: #0000ff; font-family: times new roman,times; font-size: 12pt;"><a href="http://эмменеджмент.рф/obrazovanie/kursy-po-prodazham/2-uncategorised/41-aktivnye-prodazhi-obuchenie"><span style="color: #0000ff;">Тренинг Активные продажи</span></a></span></div>\r\n<div style="text-align: justify;"><span style="color: #0000ff; font-family: times new roman,times; font-size: 12pt;"><a href="http://эмменеджмент.рф/obrazovanie/kursy-po-prodazham/2-uncategorised/33-kurs-menedzher-po-prodazham-bazovyj-obuchenie"><span style="color: #0000ff;">Курс Менеджер по продажам </span></a></span></div>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;"><a href="http://эмменеджмент.рф/obrazovanie/kursy-po-prodazham/2-uncategorised/39-tekhnologii-raboty-s-trudnymi-klientami"><span style="color: #0000ff;">Тренинг Технологии работы с «трудными» клиентами</span></a></span><br /><span style="color: #0000ff; font-family: times new roman,times; font-size: 12pt;"><a href="http://эмменеджмент.рф/obrazovanie/kursy-po-prodazham/2-uncategorised/37-kak-stat-masterom-telefonnykh-prodazh"><span style="color: #0000ff;">Тренинг Как стать Мастером телефонных продаж</span></a></span></div>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"><b><span style="color: purple;">&nbsp; </span></b></span></div>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"><b><span style="color: purple;">&nbsp;&nbsp; Курсы и тренинги УПРАВЛЕНИЕ ПЕРСОНАЛОМ</span></b></span></div>\r\n<div style="text-align: jus