INSERT INTO `j7_arigenerictemplate` (`TemplateId`, `BaseTemplateId`, `TemplateName`, `Value`, `Created`, `CreatedBy`, `Modified`, `ModifiedBy`) VALUES
(1, 1, 'Base Template', '<div align="center">\r\n<p>Dear, {$UserName}! You have <span style="text-transform: lowercase;">{$Passed}</span> quiz ''{$QuizName}''.</p>\r\n</div>\r\n<table border="0" style="border: 1px solid #cccccc; width: 100%;">\r\n<tbody>\r\n<tr><th class="sectiontableheader" colspan="2" style="text-align: center;">Результаты</th></tr>\r\n<tr>\r\n<td style="text-align: left; width: 50%; white-space: nowrap;">Результат :</td>\r\n<td style="text-align: left;">{$UserScore} / {$MaxScore}</td>\r\n</tr>\r\n<tr>\r\n<td style="text-align: left; white-space: nowrap;">Percentage :</td>\r\n<td style="text-align: left;">{$PercentScore} %</td>\r\n</tr>\r\n<tr>\r\n<td style="text-align: left; white-space: nowrap;">Пройден :</td>\r\n<td style="text-align: left;">{$Passed}</td>\r\n</tr>\r\n<tr>\r\n<td style="text-align: left; white-space: nowrap;"><span style="white-space: nowrap;">Начало</span>&nbsp;:</td>\r\n<td style="text-align: left;">{$StartDate}</td>\r\n</tr>\r\n<tr>\r\n<td style="text-align: left; white-space: nowrap;">Конец :</td>\r\n<td style="text-align: left;">{$EndDate}</td>\r\n</tr>\r\n<tr>\r\n<td style="text-align: left; white-space: nowrap;">Потраченное время :</td>\r\n<td style="text-align: left;">{$SpentTime}</td>\r\n</tr>\r\n<tr>\r\n<td>Passed Percentage :</td>\r\n<td>{$PassedScore} %</td>\r\n</tr>\r\n</tbody>\r\n</table>', '2008-02-10 10:52:47', 62, '2012-02-27 22:25:54', 42);
