(1, 33, 'Новости', 'novosti', '<h1><span style="color: #174f3b;"><strong><span style="font-family: arial black,avant garde; font-size: 14pt;">&nbsp;</span></strong><span style="font-family: times new roman,times; color: #0000ff;"><strong><span style="font-size: 14pt;">Новости</span></strong></span></span></h1>\r\n<p><span style="color: #3366ff;">\r\n<table border="0">\r\n<tbody>\r\n<tr>\r\n<td><span style="color: #000000;"><span style="font-size: 12pt; font-family: times new roman,times;"><a href="images/2323.doc"><span style="color: #000000;">Отмена вмененного налога начнется с 2018 года</span></a></span><span style="font-size: 12pt; font-family: times new roman,times;">&nbsp;</span></span></td>\r\n</tr>\r\n<tr>\r\n<td><a href="images/%20%20%20.doc"><span style="color: #000000; font-size: 12pt; font-family: times new roman,times;"><span style="color: #000000;">Новый закон о бухучёте с 2013 года – дополнительная финансовая нагрузка на малый бизнес</span></span></a></td>\r\n</tr>\r\n<tr>\r\n<td><a href="images/21.doc"><span style="color: #000000; font-size: 12pt; font-family: times new roman,times;"><span class="l"><span style="color: #000000;">Измененная счет-фактура со 2 квартала 2012</span></span></span></a></td>\r\n</tr>\r\n<tr>\r\n<td><a href="images/212.doc"><span style="color: #000000; font-size: 12pt; font-family: times new roman,times;"><span class="l"><span style="color: #000000;">Снижение ставки страховых взносов в 2012 году</span></span></span></a></td>\r\n</tr>\r\n<tr>\r\n<td><span style="font-family: times new roman,times;"><a href="images/373.doc"><span style="font-size: 12pt; color: #000000;"><span class="l">Новые правила кассовой дисциплины с 2012 года</span></span></a><a href="http://base.consultant.ru/cons/cgi/online.cgi?req=doc;base=LAW;n=122311"><span style="color: #000000; font-size: 12pt;"><span class="l"><span style="color: #000000;"><br data-mce-bogus="1" /></span></span></span></a></span></td>\r\n</tr>\r\n<tr>\r\n<td><span style="font-family: times new roman,times;"><a href="images/030408.doc"><span style="color: #000000; font-size: 12pt;"><span class="l"><span style="color: #000000;">Вычеты по НДФЛ</span></span></span></a><a href="http://base.consultant.ru/cons/cgi/online.cgi?req=doc;base=LAW;n=124020"><span style="color: #000000; font-size: 12pt;"><span class="l"><span style="color: #000000;"><br data-mce-bogus="1" /></span></span></span></a></span></td>\r\n</tr>\r\n<tr>\r\n<td><span style="font-family: times new roman,times;"><a href="images/1111.doc"><span style="color: #000000; font-size: 12pt;"><span class="l"><span style="color: #000000;">Новые формы бухгалтерской отчетности</span></span></span></a><a href="http://base.consultant.ru/cons/cgi/online.cgi?req=doc;base=LAW;n=123561"><span style="color: #000000; font-size: 12pt;"><span class="l"><span style="color: #000000;"><br data-mce-bogus="1" /></span></span></span></a></span></td>\r\n</tr>\r\n<tr>\r\n<td><span style="font-family: times new roman,times;"><a href="images/182.doc"><span style="color: #000000; font-size: 12pt;"><span class="l"><span style="color: #000000;">Новые КБК</span></span></span></a><a href="http://base.consultant.ru/cons/cgi/online.cgi?req=doc;base=LAW;n=124620"><span style="color: #000000; font-size: 12pt;"><span class="l"><span style="color: #000000;"><br data-mce-bogus="1" /></span></span></span></a></span></td>\r\n</tr>\r\n<tr>\r\n<td><span style="font-family: times new roman,times; font-size: 12pt; color: #000000;"><a href="images/4.XLS"><span style="color: #000000;">Новая форма отчета в ФСС за 1 квартал 2012</span></a></span></td>\r\n</tr>\r\n<tr>\r\n<td><span style="font-family: times new roman,times; font-size: 12pt; color: #000000;"><a href="images/prikaz_4_fss_2012_pril_1.doc"><span style="color: #000000;"> ФСС новые шифры страхователей</span></a></span></td>\r\n</tr>\r\n<tr>\r\n<td><span style="font-family: times new roman,times; font-size: 14pt;"><span style="color: #000000;"><a href="images/0107121.doc"><span style="font-size: 12pt; color: #000000;">Патентная система с 2013 г.</span></a></span> <br /></span></td>\r\n</tr>\r\n<tr>\r\n<td><span style="font-family: arial black,avant garde; font-size: 14pt;"><span style="color: #000000; font-family: times new roman,times;"><a href="images/0107122.doc"><span style="font-size: 12pt; color: #000000;">Переход на ЕНВД&nbsp; с 2013г. в добровольном порядке</span></a></span><br /></span></td>\r\n</tr>\r\n<tr>\r\n<td><span style="font-family: times new roman,times;"><a href="images/0107213.doc"><span style="font-size: 14pt;"><span style="color: #000000;"><span style="font-size: 12pt; color: #000000;">Упрощенная система с 2013 г.</span></span></span></a></span></td>\r\n</tr>\r\n<tr>\r\n<td></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</span></p>\r\n<p><span style="color: #3366ff;">&nbsp;</span></p>', '', 1, 2, '2012-02-25 07:35:09', 42, '', '2012-09-13 16:04:34', 42, 0, '0000-00-00 00:00:00', '2012-02-25 07:35:09', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":null,"urlatext":"","targeta":"","urlb":null,"urlbtext":"","targetb":"","urlc":null,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 36, 44, 'Новости налогообложение 2012, изменения в налоговом учете, новый закон о бухгалтерском учете', 'Новости налогообложение', 1, 1899, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(2, 34, 'Аутсорсинг бухучета, юридические услуг', 'autsorsing-bukhucheta-yuridicheskie-uslugi', '<h1 class="caption" style="text-align: left;"><strong>Преимущества о</strong>рганизации - аутсорсера</h1>\r\n<p>Смысл аутсорсинга сводится к следующему&nbsp; &rarr;&nbsp; сосредоточьте все ресурсы на том виде деятельности, который является основным для вашей организации, и передайте остальные поддерживающие или сопутствующие функции профессиональному партнеру.<span style="font-family: arial,helvetica,sans-serif;"><img style="float: right; margin: 0px 0px 10px 10px;" src="images/images6.jpg" alt="images6" width="164" height="71" /></span></p>\r\n<p class="caption"><strong><span style="font-family: arial,helvetica,sans-serif;">Привлечение организации-аутсорсера имеет ряд преимуществ:</span></strong></p>\r\n<ul>\r\n<li>поскольку организация- заказчик передает аутсорсеру часть функций, то он имеет возможность сконцентрировать все внимание на основной деятельности организации. Кроме того, ранее задействованные ресурсы организации можно перераспределить и инвестировать в поддержку основного бизнеса.</li>\r\n<li>нередко услуги организации-аутсорсера обходятся дешевле, чем работы своими силами. В рыночных условиях успех обеспечен тем организациям, которые ведут свой бизнес наиболее эффективным способом, при этом снижая затраты и сохраняя высокое качество товаров и услуг.</li>\r\n<li>возможность сокращения штата организации.</li>\r\n<li>более качественное выполнение отдельных функций организации специализированными фирмами.&nbsp;&nbsp;&nbsp;</li>\r\n</ul>\r\n<p>Для успешного ведения бизнеса вовсе не обязательно, выполнять все непрофильные функции, связанные с основным видом деятельности организации, или с управлением компанией, своим персоналом, можно возложить ведение этих процессов и на специализированную организацию. Под аутсорсингом понимается передача на договорной основе непрофильных функций субъекта внешним исполнителям, специализирующимся в конкретной области и обладающим знаниями, опытом, техническим оснащением.&nbsp;&nbsp;&nbsp;&nbsp;</p>\r\n<p>Передача части работ на аутсорсинг позволяет сократить издержки, так как зачастую услуги аутсорсера стоят намного дешевле, чем содержание собственного персонала. Исходя из своих целей и имеющихся ресурсов, каждая организация сама решает отдавать ту или иную часть собственного бизнеса на аутсорсинг, или выполнять ее самостоятельно.</p>', '', -2, 2, '2012-02-25 07:35:28', 42, '', '2018-05-29 07:45:18', 42, 42, '2018-06-04 05:15:17', '2012-02-25 07:35:28', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"0","link_titles":"0","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 68, 43, 'бухгалтерский учет ведение Екатеринбург, консультация по бухучету, налогам, юридическая консультация, юридическая помощь', 'Преимущества аутсорсинга бухгалтерского учета', 1, 5646, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(9, 46, 'Курсы бухгалтеров', 'kursy-nachinayushchikh-bukhgalterov-ekaterinburg', '<h1 style="text-align: center;"><span style="font-family: Pro;">Бухгалтерские курсы в {city_d}. Обучение бухгалтерскому учету, налогам, 1С: Бухгалтерия + 1С: ЗУП</span></h1>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><span style="color: #000000;"><strong>Для кого курсы:</strong>&nbsp;начинающий&nbsp;</span>бухгалтер,&nbsp; бухгалтер, экономист, финансовый директор, руководитель, предприниматель и&nbsp; всем&nbsp; кому важно понимания бухгалтерии и налогообложения</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>Ведущие:</strong>&nbsp;</span></p>\r\n<p><span style="font-family: Pro;"><!-- noindex --></span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><a href="index.php?option=com_content&amp;view=article&amp;id=105&amp;catid=2&amp;Itemid=112" rel="nofollow">Поплавская Юлия Олеговна</a>&nbsp;-&nbsp; практикующий главный бухгалтер, финансовый директор</span><br /><span style="font-family: Pro; font-size: 10pt;"><a href="index.php?option=com_content&amp;view=article&amp;id=159&amp;catid=11&amp;Itemid=170" rel="nofollow">Сокол Маргарита Геннадьевна</a> - главный государственный налоговый инспектор<br /><a href="index.php?option=com_content&amp;view=article&amp;id=160&amp;catid=11&amp;Itemid=170" rel="nofollow">Прокопьева Зоя Александровна&nbsp;</a><span style="font-size: 13.3333px;">- главный государственный налоговый инспектор<br /></span></span></p>\r\n<p><span style="font-family: Pro;"><!--/ noindex --></span></p>\r\n<h2 style="text-align: center;"><span style="color: #000000; font-family: Pro; font-size: 10pt;"><strong>Пройдя наши курсы бухгалтеров вы:</strong> </span></h2>\r\n<table>\r\n<tbody>\r\n<tr>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Получите знания и навыки по бухгалтерскому учету, научитесь работать в программе 1С Бухгалтерия&nbsp;</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Поймёте, как заполняются налоговые декларации и рассчитываются налоги</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Сможете составлять бухгалтерскую отчетность и работать как бухгалтером, так и&nbsp; бухгалтером со сдачей отчетности</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Узнаете о нововведениях и разберёте типичные ошибки</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Как руководитель - поймёте все тонкости и узкие моменты налогообложения</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Как предприниматель -&nbsp; узнаете, как&nbsp;вести бухгалтерию компании и подбирать квалифицированных бухгалтеров&nbsp;</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p style="text-align: center;"><span style="font-family: Pro;"><a onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="color: #000000; font-family: Pro; font-size: 13.3333px; background-color: inherit;">Выдается удостоверение о повышении квалификации.&nbsp;Разработано в соответствии с Профстандартами&nbsp; Министерства труда и социальной защиты РФ от 22.12.2014 № 1061н&nbsp;</span></p>\r\n<p><span style="font-family: Pro;"><a href="#"><img src="images/Udostoverenie_oblozhka.jpg" alt="бухгалтерские курсы для начинающих" width="45%" height="261" />&nbsp;&nbsp;</a>&nbsp; <a href="#"><img src="images/udostoverenie_buhgalteriya.jpg" alt="бухгалтерские курсы на удостоверение" width="45%" height="261" /></a></span></p>\r\n<hr />\r\n<p style="text-align: left;"><span style="font-family: Pro;"><strong><span style="font-size: 12pt;">Фрагмент обучения</span></strong> </span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro;"><iframe style="background-image: url(''img/iframe.png''); display: block; margin-left: auto; margin-right: auto;" src="https://www.youtube.com/embed/LILWUvKnCB8" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen"></iframe></span></p>\r\n<hr />\r\n<p style="text-align: left;"><span style="font-size: 12pt; font-family: Pro;"><strong>Программа бучения бухгалтеров: бухучет, налоги + 1С</strong> </span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p><span style="font-family: Pro;">Учет предприятия на практических примерах + бухгалтерская, налоговая отчетность: ОСНО, УСНО, ЕНВД +&nbsp; 1С: Бухгалтерия + 1С: ЗУП</span></p>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 67px;">\r\n<td style="background-color: #f7f7f7; height: 67px; width: 19.7362%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>1.&nbsp;Методика учета</strong></span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 67px; width: 75.2638%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">1) Виды учета и их отличия: статистический, управленческий, бухгалтерский, налоговый</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">2) Правовая основа бухгалтерского учета, &nbsp;баланс предприятия,&nbsp; строение балансовых счетов, счета аналитические и синтетические, план счетов</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">3) Закон о Бухгалтерском учете 402 ФЗ, как основа&nbsp;механизма регулирования бухгалтерского учета</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">4) Положения&nbsp; о бухгалтерском учете (ПБУ)</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">5) Учетная политика в целях налогового и бухгалтерского учета.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 19.7362%; height: 14px;"><span style="font-size: 10pt; font-family: Pro;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 75.2638%; height: 14px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 137px;">\r\n<td style="background-color: #f7f7f7; height: 137px; width: 19.7362%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>2. Порядок ведения объектов учета</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 137px; width: 75.2638%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">1) Учет уставного капитала. Минимальный уставный капитал. Назначение добавочного и резервного капитала</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">2) Учет денежных средств, учет операций по расчетному счету. Ревизия кассы</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">3) Учет расчетов с подотчетными лицами, покупателями и поставщиками. Нормируемые подотчетные суммы. Командировка</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">4) Учет материально - производственных запасов. Инвентаризация&nbsp;</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">5) Учет и оценка основных средств и нематериальных активов. Новые критерии НМА и ОС, отличия</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">6) Учет оплаты труда и страховых взносов. Системы оплаты труда, премии, удержания. Пособия. Расчет больничных</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">7) Учет затрат на производство. Методы оптимизации затрат. Распределение косвенных затрат</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">8) Учет готовой продукции и операций по ее реализации. Определение финансового результата</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">9) Учет будущих периодов, сомнительной задолженности. Виды резервов, право создавать</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 19.7362%; height: 14px;"><span style="font-size: 10pt; font-family: Pro;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 75.2638%; height: 14px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 56px;">\r\n<td style="background-color: #f7f7f7; height: 56px; width: 19.7362%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong><span lang="EN-US">3. Расчёт финансового результата и составление бухгалтерской отчетности</span></strong> </span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 56px; width: 75.2638%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">1) Учет финансовых результатов</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">2) Бухгалтерская отчетность (баланс, отчет о прибылях и убытках и другие формы отчетности).Закон о Бухгалтерском учете 402 ФЗ, как основа&nbsp;механизма регулирования бухгалтерского учета</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">3) Практические задачи и заполнение бухгалтерской отчетности</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 19.7362%; height: 14px;"><span style="font-size: 10pt; font-family: Pro;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 75.2638%; height: 14px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 134px;">\r\n<td style="background-color: #f7f7f7; height: 134px; width: 19.7362%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>4. Налоги и налоговая отчетность. Заполнение налоговых деклараций на примерах.</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 134px; width: 75.2638%;">\r\n<p><span style="font-family: Pro;">1) Налог на добавленную стоимость</span></p>\r\n<p><span style="font-family: Pro;">2) Налог на прибыль</span></p>\r\n<p><span style="font-family: Pro;">3) Налог на имущество</span></p>\r\n<p><span style="font-family: Pro;">4) Транспортный налог</span></p>\r\n<p><span style="font-family: Pro;">5) Земельный налог</span></p>\r\n<p style="font-weight: 400;"><span style="font-family: Pro;"><strong>Нововведения с 2019 г.&nbsp;<br /></strong><strong>Налог на доходы физических лиц, вычеты стандартные и имущественные</strong></span></p>\r\n<p><span style="font-family: Pro;">- Льготы по налогообложению, пониженные ставки по страховым взносам- Выбор оптимальных систем налогообложения- Нормируемые расходы в целях налогообложения- Практические задачи и составление деклараций в ИФНС- Типичные ошибки&nbsp; при составление отчетности- Новации в налоговом учете</span></p>\r\n<p style="font-weight: 400;"><span style="font-family: Pro;"><strong>СПЕЦИАЛЬНЫЕ РЕЖИМЫ НАЛОГООБЛОЖЕНИЯ:</strong></span></p>\r\n<p style="font-weight: 400;"><span style="font-family: Pro;">УСНО, ЕНВД, патентная система</span></p>\r\n<p><span style="font-family: Pro;">1) Смена налогового режима, порядок перехода</span></p>\r\n<p><span style="font-family: Pro;">2) Порядок ведения книги учета доходов и расходов</span></p>\r\n<p><span style="font-family: Pro;">3) Совмещение спецрежимов</span></p>\r\n<p><span style="font-family: Pro;">4) Преимущества и недостатки УСНО&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 19.7362%; height: 14px;"><span style="font-size: 10pt; font-family: Pro;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 75.2638%; height: 14px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 110.688px;">\r\n<td style="background-color: #f7f7f7; height: 110.688px; width: 19.7362%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>5. Практика работы в программе 1С: Бухгалтерия 8.3</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 110.688px; width: 75.2638%;">\r\n<p><span style="font-family: Pro;">1) Ввод реквизитов организации и&nbsp; учетная политика по бухгалтерскому и налоговому учету</span></p>\r\n<p><span style="font-family: Pro;">2) Справочник «номенклатура» и «контрагенты». Для чего нужны справочники?</span></p>\r\n<p><span style="font-family: Pro;">3) Учет кассовых&nbsp; и банковских операций операций. Расчеты с подотчетными лицами. Правильность оформления.</span></p>\r\n<p><span style="font-family: Pro;">4) Учет торговых и производственных операций</span></p>\r\n<p><span style="font-family: Pro;">5) Учет основных средств, Начисление амортизации, амортизационная премия</span></p>\r\n<p><span style="font-family: Pro;">6) Зарплата и кадровый учет, отчетность по страховым взносам и ФСС&nbsp;</span></p>\r\n<p><span style="font-family: Pro;">7) Операции по завершению месяца, регламентированная отчетность - бухгалтерская&nbsp;и налоговая отчетность. НДС, прибыль, НДФ<span style="font-size: 10pt;">Л</span></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 19.7362%; height: 14px;"><span style="font-size: 10pt; font-family: Pro;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 75.2638%; height: 14px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 120px;">\r\n<td style="background-color: #f7f7f7; height: 120px; width: 19.7362%;"><span style="font-size: 10pt; font-family: Pro;"><strong>6. Расчёт оплаты труда, основы кадрового делопроизводства 1С: ЗУП</strong></span></td>\r\n<td style="background-color: #f7f7f7; height: 120px; width: 75.2638%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">1) Прием, увольнение, карточка сотрудника</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">2) Исчисление среднего заработка. 922 Постановление РФ.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">3) Отпуска. Основной отпуск: порядок предоставления</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">4) Пособие по временной нетрудоспособности и в связи с материнством.&nbsp;</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">5) Расчёт командировочных</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 19.7362%; height: 14px;"><span style="font-size: 10pt; font-family: Pro;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 75.2638%; height: 14px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 95%; background-color: #f7f7f7; height: 14px;" colspan="2"><span style="font-size: 10pt; font-family: Pro;"><strong>7.&nbsp;Основы составления договоров и основы аудиторской деятельности</strong></span></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<hr />\r\n<p><span style="font-size: 12pt; font-family: Pro;"><strong>Формат базового курса бухгалтеров:&nbsp;</strong> </span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro;">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;• <strong>Вечерняя группа.</strong> 2 месяца по вторникам, четвергам, пятницам с 19.00 до 21.30&nbsp;</span></p>\r\n<p><span style="font-family: Pro;">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;•&nbsp;<strong>Группы выходного дня.</strong> 2 месяца по субботам и воскресеньям с 10.00 до 14.00</span></p>\r\n<p><span style="font-family: Pro;">&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;•&nbsp;<strong>Дистанционное обучение</strong>: видео-лекции, аттестационные работы продолжительностью 2 месяца<span style="background-color: inherit; color: inherit; font-size: 1rem;"><br /></span></span></p>\r\n<hr />\r\n<p><span style="font-family: Pro;">&nbsp;<strong><span style="font-size: 12pt;">&nbsp;Акции и скидки:</span></strong> </span></p>\r\n<p>&nbsp;</p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit; color: inherit; font-size: 1rem;">•&nbsp;</span>Скидка 10%&nbsp;при оплате за 4 недели до обучения.&nbsp;&nbsp;</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit; color: inherit; font-size: 1rem;">•&nbsp;</span>Скидка 5%&nbsp;при оплате за 2 недели до обучения.</span></p>\r\n<p>&nbsp;</p>\r\n<p style="text-align: center;"><span style="font-family: Pro;"><a style="text-align: center;" onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<hr />\r\n<p><span style="font-family: Pro;"><span style="font-size: 12pt;"><span style="font-family: Pro; font-size: 12pt;"><b>Почему стоит пройти курсы бухгалтеров в </b></span><span style="font-family: Pro;"><span style="font-size: 16px;"><b>{city_d}</b></span></span><span style="font-family: Pro; font-size: 12pt;"><b>&nbsp;в ЭмМенеджмент?</b></span></span> </span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">Данный курс позволит вам повысить квалификацию, найти&nbsp; достойную работу, повысить свой личный доход за счет знаний и умений в различных объектах бухгалтерского налогового учета, минимизировать налоговые риски, оптимизировать налогообложение.&nbsp;</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">Залог успеха&nbsp; − комплексное&nbsp;освещение всех аспектов финансового учета. Именно поэтому при составлении программы&nbsp;преподаватели традиционно уделяют внимание следующим вопросам:</span></p>\r\n<ul>\r\n<li><span style="font-size: 10pt; font-family: Pro;">бухгалтерский учет и аудит;</span></li>\r\n<li><span style="font-size: 10pt; font-family: Pro;">налоги, налоговая отчетность, системы налогообложения;</span></li>\r\n<li><span style="font-size: 10pt; font-family: Pro;">правовое регулирование деятельности физических и юридических лиц;</span></li>\r\n<li style="text-align: left;"><span style="font-size: 10pt; font-family: Pro;">основы экономики предприятия&nbsp;</span></li>\r\n</ul>\r\n<hr />\r\n<p><strong><span style="font-family: Pro; font-size: 12pt;">О нас</span></strong></p>\r\n<p><span style="font-family: Pro;"><iframe style="background-image: url(''img/iframe.png''); display: block; margin-left: auto; margin-right: auto;" src="https://www.youtube.com/embed/yx3VnN5bh2k" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture"></iframe></span></p>', '', 1, 11, '2012-02-27 14:47:14', 42, '', '2019-04-25 08:15:10', 42, 0, '0000-00-00 00:00:00', '2012-02-27 14:47:14', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 341, 4, 'Курсы бухгалтеров для начинающих, Бухгалтерские курсы, Бухгалтерские курсы в Екатеринбурге, бухгалтерский учет обучение, курсы бухгалтерского учета', 'Бухгалтерские курсы для начинающих в Екатеринбурге. Очно и дистанционно. От эксперта-практика. Обучение бухгалтерский учет, 1С, налоги. Скидки до 15% - Звоните. ', 1, 67515, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(213, 411, 'Дистанционные курсы управления закупками и запасами', 'дистанционные-курсы-управления-закупками-и-запасами', '<h1 style="text-align: center;">Дистанционное обучение логистике. Управление закупками и запасами, курсы товарная логистика</h1>\r\n<p><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>Целевая аудитория:</strong>&nbsp;специалисты по закупкам, &nbsp;руководители отделов&nbsp;закупок, руководители отдела продаж, коммерческие директора</span></p>\r\n<p style="text-align: center;"><span style="font-family: arial, helvetica, sans-serif;"><strong>Вы получите:</strong></span></p>\r\n<table style="width: 734px;">\r\n<tbody>\r\n<tr style="height: 66px;">\r\n<td style="width: 411px; height: 66px;">\r\n<ul>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Практические навыки по организации и оптимизации закупок товара</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 355px; height: 66px;">\r\n<ul>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">&nbsp;Научитесь рассчитывать оптимальное количество&nbsp;товарного запаса</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr style="height: 49.3438px;">\r\n<td style="width: 411px; height: 49.3438px;">\r\n<ul>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Увеличите прибыль за счет&nbsp;лучших предложений поставок товара</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 355px; height: 49.3438px;">\r\n<ul>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">&nbsp; Научитесь вести продуктивные переговоры&nbsp;</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p style="text-align: center;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><a href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<p style="text-align: center;"><span style="font-family: arial, helvetica, sans-serif;"><strong>В ПРОГРАММЕ</strong></span></p>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 50%; text-align: center; height: 15px;" colspan="2">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>УПРАВЛЕНИЕ ЗАКУПКАМИ И ЗАПАСАМИ, ТОВАРНАЯ ЛОГИСТИКА</strong></span></p>\r\n</td>\r\n</tr>\r\n<tr style="background-color: #f5f5f5; height: 191px;">\r\n<td style="width: 10%; height: 191px;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>1. Управление запасами и закупками</strong></span></p>\r\n</td>\r\n<td style="width: 40%; height: 191px;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>1)</strong>&nbsp;Показатели эффективности Службы закупа.&nbsp;Влияние целевых показателей Службы закупа(снабжения) на операционные цели Компании.<br /></span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>2)&nbsp;</strong>Риск &ndash; менеджмент в закупочной логистике.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>3)</strong>&nbsp;Бюджетирование в закупках. Показатели планирование бюджета.&nbsp;</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>4)&nbsp;</strong>Совокупные затраты на закупку и уровень запасов: влияние этих показателей на финансовые результаты компании.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>5)&nbsp;</strong>Методы прогнозирования оценки потребностей в запасах.&nbsp;<br /></span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-size: 10pt;"><strong><span style="font-family: arial, helvetica, sans-serif;">ПРАКТИКА: Расчет потребности в запасах</span></strong></span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>6)</strong>&nbsp;Неликвид. Как избежать? Что делать при образовании неликвида?</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 10%; height: 15px;">&nbsp;</td>\r\n<td style="width: 40%; height: 15px;">&nbsp;</td>\r\n</tr>\r\n<tr style="background-color: #f5f5f5; height: 309px;">\r\n<td style="width: 10%; height: 309px;">\r\n<p><span style="font-size: 10pt;"><strong><span style="font-family: arial, helvetica, sans-serif;">2. Формирование и анализ запасов и закупок</span></strong></span></p>\r\n</td>\r\n<td style="width: 40%; height: 309px;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>1)</strong>&nbsp;Определение потребности в товаре, планирование и прогнозирование потребности.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>2)</strong>&nbsp;Точка заказа.&nbsp;Текущий, страховой, сезонный&nbsp;тип запасов.&nbsp;</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>3)</strong>&nbsp;Нормирование запасов, определения величины рабочего, резервного запасов. Способы расчета нормативов.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">ПРАКТИКА: Расчет коэффициентов оборачиваемости, точки запаса, нормативов запасов.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>4)</strong>&nbsp;Принцип Парето и классификация по методу&nbsp;А<span lang="EN-US">BC.</span></span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>5)</strong>&nbsp;Использование метода&nbsp;<span lang="EN-US">XYZ</span>&nbsp;для группировки номенклатуры и управления запасами товарно-материальных ценностей.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>6)</strong>&nbsp;Структура товарного запаса: основные, временные, вынужденные.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>7)</strong>&nbsp;Алгоритм совмещения АВС &ndash; XYZ анализа.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-size: 10pt;"><strong><span style="font-family: arial, helvetica, sans-serif;">ПРАКТИКА: АВС анализ на основе результатов деятельности.&nbsp;</span></strong></span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-size: 10pt;"><strong><span style="font-family: arial, helvetica, sans-serif;">ПРАКТИКА: расчет в Excel, совмещение ABC-XYZ анализ + товарная матрица.</span></strong></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 10%; height: 15px;">&nbsp;</td>\r\n<td style="width: 40%; height: 15px;">&nbsp;</td>\r\n</tr>\r\n<tr style="background-color: #f5f5f5; height: 106px;">\r\n<td style="width: 10%; height: 106px;">\r\n<p><strong><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">3. Управление портфелем поставщиков</span></strong></p>\r\n</td>\r\n<td style="width: 40%; height: 106px;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>1)</strong>&nbsp;Как правильно подобрать потенциальных поставщиков?&nbsp;&nbsp;Анализ потенциальных поставщиков.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>2)</strong>&nbsp; Алгоритм и основные методы выбора поставщика:&nbsp;</span><span style="font-size: 10pt;"><strong><span style="font-family: arial, helvetica, sans-serif;">ПРАКТИКА: метод рейтинговых оценок, метод оценки затрат, &nbsp;метод категорий и предпочтений.</span></strong></span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>3)</strong>&nbsp;Оценка существующих поставщиков. Перераспределения объема поставок между поставщиками</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 10%; height: 15px;">&nbsp;</td>\r\n<td style="width: 40%; height: 15px;">&nbsp;</td>\r\n</tr>\r\n<tr style="background-color: #f5f5f5; height: 114.656px;">\r\n<td style="width: 10%; height: 114.656px;">\r\n<p><span style="font-size: 10pt;"><strong><span style="font-family: arial, helvetica, sans-serif;">4.&nbsp;Договорные отношения с поставщиками</span></strong></span></p>\r\n</td>\r\n<td style="width: 40%; height: 114.656px;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>1)&nbsp;</strong>Договор поставки как инструмент снижения рисков.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>2)</strong>&nbsp; Порядок заключения договора поставки товаров. Основные составляющие договора. Ответственность сторон по договору поставки.</span></p>\r\n<p><span style="font-size: 10pt;"><strong><span style="font-family: arial, helvetica, sans-serif;">ПРАКТИКА: анализ договора поставки, корректировка существующего договора</span></strong></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 10%; height: 15px;">&nbsp;</td>\r\n<td style="width: 40%; height: 15px;">&nbsp;</td>\r\n</tr>\r\n<tr style="background-color: #f5f5f5; height: 236px;">\r\n<td style="width: 10%; height: 236px;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>5. Переговоры с поставщиками</strong></span></p>\r\n</td>\r\n<td style="width: 40%; height: 236px;">\r\n<p>&nbsp;<span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>1)</strong>&nbsp;Коммуникация в деловом общении: типичные ошибки и их последствия.<strong>&nbsp;Карта переговоров.</strong></span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>2)</strong>&nbsp;Условия переговорного процесса. Стратегии ведения переговоров.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>3)</strong>&nbsp;Позиционный и принципиальный подход в переговорах.<strong>&nbsp;Анализ эффективности основных стратегий ведения переговоров.</strong></span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>4)</strong>&nbsp;Подготовка и планирование переговоров. Анализ факторов ситуации и поведения участников.&nbsp;Типы клиентов</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>5) Разработка сценария&nbsp; переговоров</strong>. Этапы переговорного процесса. Установление контакта, как представиться и понравиться. Правила задавания вопросов, выявление скрытых потребностей, убеждение в переговорах, аргументация и контраргументация, завершение переговоров.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>6)</strong>&nbsp;Эмоциональная составляющая в переговорах.<strong>&nbsp;Жесткие переговоры.&nbsp;Кремлевская методика</strong></span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>7) Психологические средства влияния. Нужда в переговорах</strong></span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>8)</strong>&nbsp;Психологические особенности обмена уступками и обсуждения условий.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>9) Правила эффективной аргументации,</strong>&nbsp;убеждение при сопротивлении. Техники работы с сомнениями.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>10)</strong>&nbsp;Методы конструктивного поведения. Противодействие неконструктивному поведению.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>11) Манипуляция. Как распознать манипуляцию.</strong>&nbsp;</span><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Методы противодействия манипуляциям</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-size: 10pt;"><strong><span style="font-family: arial, helvetica, sans-serif;">Практика: Переговоры и манипуляции в переговорах - &laquo;разбор полетов&raquo; (моделирование и анализ реальных ситуаций взаимодействия с поставщиками.</span></strong></span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>Формат обучения: </strong>дистанционно</span>&nbsp;3 недели, видео - лекции, практические работы, обратная связь от преподавателя.</p>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 4px; background-color: #f5f5f5;">\r\n<td style="width: 24.359%; height: 4px; text-align: center;">\r\n<p style="text-align: center;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong><span style="color: #800000;">ВЕДУЩИЕ</span></strong></span></p>\r\n</td>\r\n<td style="width: 71.641%; height: 4px;">\r\n<p style="text-align: center;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong><span style="color: #800000;">МАКАРОВА ЮЛИЯ ОЛЕГОВНА</span></strong></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 24.359%; height: 15px; text-align: center;"><img src="images/Makarova_JO.jpg" alt="" width="86" height="113" /></td>\r\n<td style="width: 71.641%; height: 15px;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Практикующий бизнес-тренер в области&nbsp; коммуникаций&nbsp;и управленческого консалтинга.&nbsp;</span></p>\r\n<p style="font-weight: 400;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><b><strong>Более 15 лет&nbsp;практической работы,</strong></b>&nbsp;более 1000 часов проведенных тренингов.</span></p>\r\n<p style="font-weight: 400;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Опыт тренинговой и преподавательской деятельности&nbsp;<b><strong>более&nbsp;10 лет.&nbsp;&nbsp;</strong></b></span></p>\r\n<p style="font-weight: 400;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">Автор программ обучения: &nbsp;переговоры в закупках,&nbsp;многоуровневые продажи, управление персоналом</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 24.359%; height: 15px; text-align: center;">&nbsp;</td>\r\n<td style="width: 71.641%; height: 15px;">\r\n<p style="text-align: center;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">&nbsp;<strong><span style="color: #800000; font-family: arial, helvetica, sans-serif;">НИКОЛАЕВ ВЛАДИМИР АРКАДЬЕВИЧ</span></strong></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 24.359%; height: 15px; text-align: center;"><img src="images/Nikolaev_VA.jpg" alt="" width="89" height="116" /></td>\r\n<td style="width: 71.641%; height: 15px;">&nbsp;<span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>Эксперт-практик в сфере закупок и логистики</strong></span>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">-&nbsp;<strong>Более 15 лет</strong>&nbsp;опыта работы в сфере управления закупками, складом и транспортом</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">-&nbsp;<strong>Более&nbsp;3&nbsp;лет&nbsp;</strong>преподавательской деятельности.&nbsp;</span></p>\r\n<p><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">Директор по логистике, автор программ обучения:&nbsp;управление закупками, оптимизация товарного ассортимента, складская логистика, Управление и организация транспортно - логистической деятельности</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><iframe width="560" height="315" src="https://www.youtube.com/embed/usHoL-a7NAc" frameborder="0" allowfullscreen="allowfullscreen" data-link="https://www.youtube.com/watch?v=usHoL-a7NAc"></iframe></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>Выдается удостоверение.</strong></span></p>\r\n<p>&nbsp;<a href="#"><img src="images/udostoverenie_logista.jpg" alt="" width="365" height="258" /></a></p>', '', -2, 17, '2018-03-06 09:33:19', 42, '', '2018-03-06 10:31:11', 42, 0, '0000-00-00 00:00:00', '2018-03-06 09:33:19', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 2, 1, '', '', 1, 0, '{}', 0, '*', ''),
(151, 252, 'Структура и органы управления образовательной организацией', 'структура-и-органы-управления-образовательной-организацией', '<h1><span style="font-size: 12.16px;">Структура и органы управления образовательной организацией</span></h1>\r\n<table style="font-size: 12.16px; width: 798px;">\r\n<tbody>\r\n<tr style="height: 52px;">\r\n<td style="width: 157px; height: 52px;">\r\n<p><span style="font-size: 10pt;">Структура организации</span></p>\r\n</td>\r\n<td style="width: 637px; height: 52px;">\r\n<p><span style="font-size: 10pt;">Основное подразделение</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 45px;">\r\n<td style="width: 157px; height: 45px;"><span style="font-size: 10pt;">Органы управления образовательной организацией</span></td>\r\n<td style="width: 637px; height: 45px;"><span style="font-size: 10pt;">Директор</span></td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 157px; height: 15px;"><span style="font-size: 10pt;">Адрес подразделения:</span></td>\r\n<td style="width: 637px; height: 15px;"><span style="font-size: 10pt;">620142 г. Екатеринбург, Степана Разина дом 16 офис 412</span></td>\r\n</tr>\r\n<tr style="height: 38px;">\r\n<td style="width: 157px; height: 38px;">\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong><span style="font-size: 10pt;">Директор</span></strong></span></p>\r\n</td>\r\n<td style="width: 637px; height: 38px;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>Тимофеева Ирина Аркадьевна</strong></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 129.438px;">\r\n<td style="width: 157px; height: 129.438px;">&nbsp;</td>\r\n<td style="width: 637px; height: 129.438px;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>Образование высшее: </strong></span></p>\r\n<p><span style="font-size: 10pt;">2001 - 2005 гг., УГТУ &ndash; УПИ, финансы и кредит</span></p>\r\n<p><span style="font-size: 10pt;">1998 - 2000 гг., НТГМК, экономика</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>Дополнительное:</strong></span></p>\r\n<p><span style="font-size: 10pt;">2011 г. Маркетинг и&nbsp;продвижение</span></p>\r\n<p><span style="font-size: 10pt;">2011 г. Активные продажи</span></p>\r\n<p><span style="font-size: 10pt;">2012 г. Управление персоналом, коучинг</span></p>\r\n<p><span style="font-size: 10pt;"><span style="font-size: 13.3333px;">2013 г. Личная эффективность</span></span></p>\r\n<p><span style="font-size: 10pt;"><span style="font-size: 13.3333px;">2014 г. СПИН - продажи</span></span></p>\r\n<p><span style="font-size: 10pt;"><span style="font-size: 13.3333px;">2016 г. Стратегический менеджмент</span></span></p>\r\n<p><span style="font-size: 10pt;"><span style="font-family: arial, helvetica, sans-serif;">&nbsp;</span></span></p>\r\n<p><span style="font-size: 10pt;"><span style="font-family: arial, helvetica, sans-serif;"><strong>- с 2012&nbsp;года</strong> </span>Директор, преподаватель центра эффективного обучения ЭмМенеджмент</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<p class="MsoNormal" style="text-align: center;" align="center">&nbsp;</p>\r\n<p>&nbsp;</p>', '', 1, 2, '2017-01-17 23:45:35', 42, '', '2018-11-27 13:28:50', 42, 42, '2019-04-16 04:52:23', '2017-01-17 18:53:35', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 18, 6, '', '', 1, 3322, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(152, 253, 'Документы', 'документы', '<h1 style="text-align: center;">&nbsp;&nbsp;Документы</h1>\r\n<p><span style="font-family: tahoma, arial, helvetica, sans-serif; font-size: 10pt;">Образовательная деятельность Центра осуществляется на основании лицензии Серия 66ЛО1 №0003556 &nbsp;№ 17679 выдана Министерство общего и профессионального образования Свердловской области&nbsp;ИНН 6679996150 КПП 667101001 ОГРН 1126600000570</span></p>\r\n<p><span style="font-family: tahoma, arial, helvetica, sans-serif; font-size: 10pt;">Лицензия с приложением <a href="images/Litsenzia_small.pdf" rel="alternate">скачать</a></span></p>\r\n<p><span style="font-family: tahoma, arial, helvetica, sans-serif; font-size: 10pt;">Свидетельства о регистрации <a href="images/svidetelstva.pdf" rel="alternate">скачать</a> &nbsp;&nbsp;</span></p>\r\n<p class="MsoNormal" style="text-align: justify;"><span style="font-family: tahoma, arial, helvetica, sans-serif; font-size: 10pt;">Устав Образовательной организации <a href="images/ustav1.pdf" rel="alternate">скачать</a></span></p>\r\n<p class="MsoNormal" style="text-align: justify;"><span style="font-size: 10pt; line-height: 115%; font-family: tahoma, arial, helvetica, sans-serif;">План финансово-хозяйственной деятельности <a href="images/finplan2017.pdf" rel="alternate">скачать</a></span></p>\r\n<p class="MsoNormal" style="text-align: justify;"><span style="font-size: 10pt; line-height: 115%; font-family: tahoma, arial, helvetica, sans-serif;">Положение по аттестации &nbsp;и правила внутреннего распорядка слушателей&nbsp;<a href="images/Pologenie_slushateli.pdf" rel="alternate">скачать</a></span></p>\r\n<p class="MsoNormal" style="text-align: justify;"><span style="font-size: 10pt; line-height: 115%; font-family: tahoma, arial, helvetica, sans-serif;">Правила внутреннего трудового распорядка работников <a href="images/pravila_trudovoi_rasporyadok.pdf" rel="alternate">скачать</a></span></p>\r\n<p class="MsoNormal" style="text-align: justify;"><span style="font-size: 10pt; line-height: 115%; font-family: tahoma, arial, helvetica, sans-serif;">Правила оказания платных образовательных услуг <a href="images/pravila_okazania_uslug.pdf" rel="alternate">скачать</a></span></p>\r\n<p class="MsoNormal" style="text-align: justify;"><span style="font-size: 10pt; line-height: 115%; font-family: tahoma, arial, helvetica, sans-serif;">Правила приема и отчисления слушателей <a href="images/pravila-priema-i-otchislenia.pdf" rel="alternate">скачать</a></span></p>\r\n<p class="MsoNormal" style="text-align: justify;"><span style="font-size: 10pt; line-height: 115%; font-family: tahoma, arial, helvetica, sans-serif;">Отчет о результатах самообследования <a href="images/samoobsledovanie.pdf" rel="alternate">скачать</a></span></p>\r\n<p class="MsoNormal" style="text-align: justify;"><span style="font-size: 10pt; line-height: 115%; font-family: tahoma, arial, helvetica, sans-serif;">Образец договора <a href="images/dogovor.pdf" rel="alternate">скачать</a></span></p>\r\n<p class="MsoNormal" style="text-align: justify;"><span style="font-size: 10pt; line-height: 115%; font-family: tahoma, arial, helvetica, sans-serif;">Стоимость образовательных услуг<a href="images/price280818.pdf" rel="alternate"> скачать</a></span></p>\r\n<p class="MsoNormal" style="text-align: justify;"><span style="font-size: 10pt; line-height: 115%; font-family: tahoma, arial, helvetica, sans-serif;">Бланк удостоверений <a href="images/udostoverenie.pdf" rel="alternate">скачать</a>&nbsp;&nbsp;</span></p>', '', 1, 2, '2017-01-17 18:54:45', 42, '', '2018-08-28 09:05:45', 42, 42, '2019-04-15 12:11:17', '2017-01-17 18:57:08', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 36, 46, '', '', 1, 8695, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(3, 35, '*Обучение в Екатеринбурге. Курсы повышения квалификации. ', 'kursy-povysheniya-kvalifikatsii-bukhgaltera', '<h1 style="text-align: center;">*Обучение в Екатеринбурге. Курсы повышения квалификации, профессиональная переподготовка, тренинги и семинары</h1>\r\n<p><img style="display: block; margin-left: auto; margin-right: auto;" src="images/obuchenie.jpg" alt="" width="809" height="164" /></p>\r\n<p><span style="background-color: #fefefe; font-size: 10pt; font-family: arial, helvetica, sans-serif;">Курсы повышения квалификации и дополнительное образование дают возможность получения смежной профессии, усовершенствования своих знаний в конкретном вопросе, решение наболевших вопросов. Кроме того, тренинги и курсы повышения квалификации зачастую являются обязательным требованием не только работодателя, но и конкретных сфер деятельности.</span></p>\r\n<p class="MsoNormalCxSpMiddle" style="mso-add-space: auto; line-height: 150%; mso-outline-level: 1; background: #FEFEFE; margin: 15.0pt 0cm 15.0pt 0cm;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Программы обучения в нашем Центре постоянно обновляются с учетом ежегодных изменений в законодательстве, в курсе которых Вам необходимо быть, чтобы оставаться профессионально востребованным.</span></p>\r\n<p class="MsoNormalCxSpMiddle" style="mso-add-space: auto; line-height: 150%; mso-outline-level: 1; background: #FEFEFE; margin: 15.0pt 0cm 15.0pt 0cm;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Сегодняшнее время требует постоянного усовершенствования знаний. Именно для этого и разрабатывается обучение и курсы повышения квалификации, профессиональной переподготовки,&nbsp; семинары и тренинги.</span></p>\r\n<p><span style="font-size: 10pt; line-height: 115%; font-family: arial, helvetica, sans-serif; color: #351e07; background: #fefefe;">Обучение в центре &laquo;ЭмМенеджмент&raquo;&nbsp;максимально практически направлено на соответствие тенденциям рынка труда Екатеринбурга. Преподаватели обучают слушателей по новейшим технологиям для наилучшего и эффективного восприятия информации.</span></p>\r\n<p><span style="font-size: 10pt; line-height: 115%; font-family: arial, helvetica, sans-serif; color: #351e07; background: #fefefe;"><img style="display: block; margin-left: auto; margin-right: auto;" src="images/obuchenie-2.jpg" alt="" width="814" height="165" /></span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><span style="font-size: 18pt;"><strong><span style="color: #ff0000;">!</span></strong></span> Что &nbsp;выбрать&nbsp;</span><a style="font-family: arial, helvetica, sans-serif; font-size: 10pt;" href="index.php?option=com_content&amp;view=article&amp;id=123&amp;catid=17&amp;Itemid=112">Профессиональная переподготовка по профстандарту или второе высшее?</a><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">&nbsp;И&nbsp;что такое&nbsp;</span><a style="font-family: arial, helvetica, sans-serif; font-size: 10pt;" href="index.php?option=com_content&amp;view=article&amp;id=119&amp;catid=17&amp;Itemid=112">Профстандарт</a><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">?</span></p>\r\n<h3><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt; color: #000000;"><strong>Виды программ:</strong></span></h3>\r\n<ul>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">программы повышение квалификации</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">программы подготовки специальностям</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">профессиональная&nbsp;переподготовка</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">семинары и круглые столы</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">тренинги</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">корпоративное обучение</span></li>\r\n</ul>\r\n<p>&nbsp;</p>', '', 1, 17, '2012-02-25 07:36:09', 42, '', '2017-01-12 08:12:50', 42, 42, '2019-04-15 12:10:40', '2012-02-25 07:36:09', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 289, 9, 'программы обучения, курсы повышения квалификации, семинары в Екатеринбурге. ОБУЧЕНИЕ - ТРЕНИНГИ  и КУРСЫ повышения квалификации В ЕКАТЕРИНБУРГЕ', 'ОБУЧЕНИЕ - ТРЕНИНГИ  и КУРСЫ повышения квалификации В ЕКАТЕРИНБУРГЕ. Курсы обучения от ЭмМенеджмент - доступные и эффективные программы. ', 1, 8594, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(4, 36, 'О нас', 'о-нас', '<h1 style="text-align: center;">&nbsp; &nbsp; Сведения об образовательной организации&nbsp;</h1>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>Наша миссия&nbsp;</strong></span>- Доступность, эффективность и своевременность новых знаний в деятельность предприятий и каждого человека.</p>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>Основные направления деятельности:</strong></span></p>\r\n<p style="text-align: left;"><!-- [if !supportLists]--><span style="font-family: arial, helvetica, sans-serif;"><strong>1.&nbsp;</strong></span>&nbsp;Курсы повышения квалификации и профессиональной переподготовки. &nbsp;На сегодняшний день в нашем центре ведется обучение по 11 направлениям. &nbsp;</p>\r\n<p><!-- [if !supportLists]--><span style="font-family: arial, helvetica, sans-serif;"><strong>2.&nbsp;</strong></span>&nbsp;Корпоративные программы, в которых обучение строится исходя из специфики работы компаний-заказчиков, их целей и задач.</p>\r\n<p><!-- [if !supportLists]--><span style="font-family: arial, helvetica, sans-serif;"><strong>3.&nbsp;</strong></span>&nbsp;Дистанционное обучение по различным направлениям.</p>\r\n<p>Мы непрерывно следим за изменениями в законодательстве и требованиями рынка в разных областях. Поэтому программы всех наших курсов регулярно обновляются и содержат только самые актуальные знания. Существенную часть программы любого из курсов составляет практическая работа, что позволяет осваивать материал максимально эффективно.</p>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>Наши преподаватели</strong></span> – успешные практики, готовые делиться своим многолетним опытом и раскрывать профессиональные секреты.</p>\r\n<p>Образовательная деятельность Центра осуществляется на основании лицензии Серия 66ЛО1 №0003556 &nbsp;№ 17679 выдана Министерство общего и профессионального образования Свердловской области&nbsp;ИНН 6679996150 КПП 667101001 ОГРН 1126600000570</p>\r\n<ol>\r\n<li class="MsoNormal" style="text-align: justify;"><a href="index.php?option=com_content&amp;view=article&amp;id=150&amp;catid=2&amp;Itemid=112">Основные сведения об организации</a></li>\r\n<li><a href="index.php?option=com_content&amp;view=article&amp;id=151&amp;catid=2&amp;Itemid=112">Структура и органы управления образовательной организацией</a></li>\r\n<li><a href="index.php?option=com_content&amp;view=article&amp;id=152&amp;catid=2&amp;Itemid=112">Документы</a></li>\r\n<li><a href="index.php?option=com_content&amp;view=article&amp;id=158&amp;catid=2&amp;Itemid=112">Образование</a></li>\r\n<li><a href="index.php?option=com_content&amp;view=article&amp;id=153&amp;catid=2&amp;Itemid=112">Образовательные стандарты</a></li>\r\n<li><a href="http://xn--d1ababe6aaeff9c5g.xn--p1ai/prepodavateli" rel="alternate">Руководство. Педагогический (научно-педагогический) состав</a></li>\r\n<li><a href="index.php?option=com_content&amp;view=article&amp;id=154&amp;catid=2&amp;Itemid=112">Материально-техническое обеспечение </a></li>\r\n<li><a href="index.php?option=com_content&amp;view=article&amp;id=171&amp;catid=17&amp;Itemid=108">Стипендии и иные виды материальной поддержки</a></li>\r\n<li><a href="index.php?option=com_content&amp;view=article&amp;id=173&amp;catid=17&amp;Itemid=108">Платные образовательные услуги</a></li>\r\n<li><a href="index.php?option=com_content&amp;view=article&amp;id=156&amp;catid=2&amp;Itemid=112">Финансово - хозяйственная деятельность</a></li>\r\n<li><a href="index.php?option=com_content&amp;view=article&amp;id=172&amp;catid=17&amp;Itemid=108">Вакантные места для приема (перевода)</a></li>\r\n</ol>\r\n<p><a href="#"><img src="images/1-min.jpg" alt="свидетельство фнс эмменеджмент" width="148" height="204" /></a>&nbsp;<a href="#"><img src="images/2-min.jpg" alt="свидетельство о регистрации эмменеджмент" width="146" height="202" /></a>&nbsp;<a href="#"><img src="images/3-min.jpg" alt="свидетельство о регистрации центра эмменеджмент" width="146" height="202" /></a>&nbsp;<a href="#"><img src="images/4-min.jpg" alt="свидетельство о постановке на учет эмменеджмент" width="145" height="200" /></a></p>\r\n<p><a href="#"><img src="images/5-min.jpg" alt="лицензия государственная эмменеджмент" width="150" height="208" /></a>&nbsp;<a href="#"><img src="images/6-min.jpg" alt="свидетельство эмменеджмент" width="149" height="207" /></a>&nbsp;<a href="#"><img src="images/7-min.jpg" alt="организация эмменеджмент" width="150" height="208" /></a></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>', '', 1, 17, '2012-02-25 07:36:36', 42, '', '2019-04-15 09:06:38', 42, 42, '2019-04-15 11:10:03', '2012-02-25 07:36:36', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 101, 12, '', '', 1, 26115, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(5, 37, 'Компания', 'kompaniya', '<h1 style="margin-top: 0px; margin-right: 0px; margin-bottom: 0.7em; margin-left: 0px; line-height: 1.4em; font-size: 2em; color: #dc2d21; font-family: Arial, Geneva, sans-serif; text-align: left; background-color: #f3f3f3; padding: 0px;">Компания</h1>', '', 1, 2, '2012-02-25 07:36:46', 42, '', '0000-00-00 00:00:00', 0, 42, '2019-04-16 05:04:01', '2012-02-25 07:36:46', '0000-00-00 00:00:00', '', '', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":""}', 1, 42, '', '', 1, 1150, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
