n="false"\r\n   UnhideWhenUsed="false" Name="Medium Grid 3 Accent 6"/>\r\n  <w:LsdException Locked="false" Priority="70" SemiHidden="false"\r\n   UnhideWhenUsed="false" Name="Dark List Accent 6"/>\r\n  <w:LsdException Locked="false" Priority="71" SemiHidden="false"\r\n   UnhideWhenUsed="false" Name="Colorful Shading Accent 6"/>\r\n  <w:LsdException Locked="false" Priority="72" SemiHidden="false"\r\n   UnhideWhenUsed="false" Name="Colorful List Accent 6"/>\r\n  <w:LsdException Locked="false" Priority="73" SemiHidden="false"\r\n   UnhideWhenUsed="false" Name="Colorful Grid Accent 6"/>\r\n  <w:LsdException Locked="false" Priority="19" SemiHidden="false"\r\n   UnhideWhenUsed="false" QFormat="true" Name="Subtle Emphasis"/>\r\n  <w:LsdException Locked="false" Priority="21" SemiHidden="false"\r\n   UnhideWhenUsed="false" QFormat="true" Name="Intense Emphasis"/>\r\n  <w:LsdException Locked="false" Priority="31" SemiHidden="false"\r\n   UnhideWhenUsed="false" QFormat="true" Name="Subtle Reference"/>\r\n  <w:LsdException Locked="false" Priority="32" SemiHidden="false"\r\n   UnhideWhenUsed="false" QFormat="true" Name="Intense Reference"/>\r\n  <w:LsdException Locked="false" Priority="33" SemiHidden="false"\r\n   UnhideWhenUsed="false" QFormat="true" Name="Book Title"/>\r\n  <w:LsdException Locked="false" Priority="37" Name="Bibliography"/>\r\n  <w:LsdException Locked="false" Priority="39" QFormat="true" Name="TOC Heading"/>\r\n </w:LatentStyles>\r\n</xml><![endif]--><!-- [if gte mso 10]>\r\n<style>\r\n /* Style Definitions */\r\n table.MsoNormalTable\r\n	{mso-style-name:"Обычная таблица";\r\n	mso-tstyle-rowband-size:0;\r\n	mso-tstyle-colband-size:0;\r\n	mso-style-noshow:yes;\r\n	mso-style-priority:99;\r\n	mso-style-parent:"";\r\n	mso-padding-alt:0cm 5.4pt 0cm 5.4pt;\r\n	mso-para-margin:0cm;\r\n	mso-para-margin-bottom:.0001pt;\r\n	mso-pagination:widow-orphan;\r\n	font-size:10.0pt;\r\n	font-family:"Calibri","sans-serif";}\r\n</style>\r\n<![endif]--></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><b style="mso-bidi-font-weight: normal;">КТО ПРОВОДИТ ?</b></span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: justify; line-height: normal; tab-stops: 222.2pt;">Команда единомышленников:&nbsp;инструктора и тренеры курса, которые проводят упражнения и непосредственно работают с участниками.&nbsp;&nbsp;Бизнес-тренеры, <b style="mso-bidi-font-weight: normal;">с многолетним опытом ведения программ личностного развития и корпоративных обучающих программ.</b></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>ГДЕ ЭТО ПРОИСХОДИТ?</strong></span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: justify; line-height: normal; tab-stops: 222.2pt;">Летом курс проводится в лесу – это отличный день для корпоративного отдыха на свежем воздухе! Шашлыки, костер, и природа. Зимой курс обычно проводится на спортивных базах за городом, часть упражнений в спортзале, а часть на улице.<span style="mso-spacerun: yes;">&nbsp;&nbsp;</span></p>\r\n<p>&nbsp;</p>', '', 1, 18, '2015-08-21 12:39:09', 42, '', '2019-04-15 11:38:35', 42, 0, '0000-00-00 00:00:00', '2015-08-21 12:39:09', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 38, 2, '', '', 1, 24908, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(111, 188, 'вторая услуга', 'вторая-услуга', '<p>текст второй услуги</p>', '', -2, 11, '2016-05-30 07:28:23', 61, '', '0000-00-00 00:00:00', 0, 0, '0000-00-00 00:00:00', '2016-05-30 07:28:23', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 1, 0, '', '', 1, 56, '', 0, '*', '');
INSERT INTO `j7_content` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(115, 198, 'Курсы сметчика, обучение сметное дело', 'курсы-сметчика,-обучение-сметное-дело-гранд-смета', '<h1 style="text-align: center;"><span style="font-family: Pro;">Обучение сметчиков в {city_d}. Курсы сметного дела. Гранд - смета</span></h1>\r\n<p style="text-align: center;"><span style="font-family: Pro;">{img; /images/kurs_smetchikov3.jpg; /images/kurs_smetchikov2.jpg; /images/kurs_smetchikov.jpg; Курсы сметного дела, обучение Гранд-смете}</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>Целевая аудитория:&nbsp;</strong>специалисты и руководители строительных организаций.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>Ведущий:&nbsp;</strong><a href="index.php?option=com_content&amp;view=article&amp;id=117&amp;catid=2&amp;Itemid=112">Дубова Наталья Сергеевна</a>&nbsp;-&nbsp;руководитель проектного - сметного отдела.</span></p>\r\n<p style="text-align: center;"><span style="font-size: 10pt; font-family: Pro;"><strong>Наше обучение сметчиков это:</strong> </span></p>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 39.3438px;">\r\n<td style="width: 50%;">\r\n<ul style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;">\r\n<li><span style="font-family: Pro; font-size: 10pt;">Работа над практическими навыками сметной стоимости</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 50%;">\r\n<ul style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;">\r\n<li><span style="font-family: Pro; font-size: 10pt;">80% практики работы в программе Гранд Смета</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 50%;">\r\n<ul style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;">\r\n<li><span style="font-family: Pro; font-size: 10pt;">Анализ новшеств&nbsp;на 2018 г., типичные ошибки при работе со сметой</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-size: 10pt; font-family: Pro;">&nbsp;Более&nbsp;8 видов смет: ремонт, монтаж, строительство и другие</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p style="text-align: center;"><span style="font-family: Pro; font-size: 10pt;"><a onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">Выдается удостоверение о повышении квалификации. Программа разработана&nbsp;в соответствии с Профстандартом.</span></span></p>\r\n<p><span style="font-family: Pro;"><a href="#"><img src="images/Udostoverenie_oblozhka.jpg" alt="обучение гранд смета удостоверение" width="45%" height="261" />&nbsp;&nbsp;</a>&nbsp;<a href="#"><img src="images/udostoverenie_smetchika.jpg" alt="обучение сметному делу" width="45%" height="261" /></a></span></p>\r\n<hr />\r\n<h2><span style="font-size: 10pt;"><strong><span style="font-family: Pro;">Фрагмент обучения сметному делу</span></strong></span></h2>\r\n<p style="text-align: center;"><span style="font-family: Pro;"><iframe src="https://www.youtube.com/embed/FyWfZTj-NDU" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen" data-link="https://www.youtube.com/watch?v=FyWfZTj-NDU"></iframe></span></p>\r\n<hr />\r\n<p style="text-align: left;"><span style="font-family: Pro; font-size: 12pt;"><strong>Программа курса:</strong></span></p>\r\n<table style="width: 92.6042%;">\r\n<tbody>\r\n<tr style="background-color: #f5f5f5; height: 268px;">\r\n<td style="width: 18%; height: 268px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>1. Система ценообразования и сметного нормирования в строительстве</strong></span></p>\r\n</td>\r\n<td style="width: 67.6927%; height: 268px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1) Виды сметных нормативов.&nbsp;Структура государственных элементных сметных&nbsp; норм.&nbsp;Структура единичных расценок&nbsp; ТЕР, ГСН, ЕНиР, ТСЦ, СЦП и др.сборники.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Нормативные документы, действующие в&nbsp; строительстве.&nbsp;Порядок составления и формы сметной&nbsp; документации.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) Группа сборников на строительные работы. Составление сметы на отделочные работы.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4) Общие сведения о системе ценообразования и сметного нормирования.&nbsp;Сметные нормы и сметные нормативы.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">5) Общие положения по определению стоимости строительства. Методы определения стоимости строительства.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">6) Порядок составления сметной документации: состав и формы сметной документации, понятие «накладные расходы», «сметная прибыль».</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">7) Информационная база "Гранд - СтройИнфо".&nbsp;Поиск документов, сортировка и отбор.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 18%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 67.6927%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 85.6927%; height: 15px;" colspan="2">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">2. Составление смет различными видами и методами. Работа в&nbsp;программе Гранд-Смета Версия&nbsp;8</span></strong> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 18%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2.1. Составление локальных смет базисным методом</strong></span></p>\r\n</td>\r\n<td style="width: 67.6927%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1) Выбор сборника, &nbsp;состав информации по расценкам. Способы поиска расценок в базе.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Действия с элементами строительства, параметры и структура локальной сметы, способы&nbsp; добавления позиций в смету. Состав информации по расценкам.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3)&nbsp;Структура сметной стоимости строительства, порядок определения её элементов:</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">- сметная стоимость материалов;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">- затраты на оплату труда рабочих;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">- затраты на эксплуатацию.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 18%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 67.6927%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 18%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">2.2. Составление локальных систем базисно-индексным методом</span></strong> </span></p>\r\n</td>\r\n<td style="width: 67.6927%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1) Способы замены ресурсов, действия с неучтенными материалами.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Подведение итогов по смете.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) Накладные расходы и сметная прибыль: привязка к виду работ, использование укрупненных норм, применение поправочных коэффициентов.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4) Лимитированные затраты.&nbsp;Добавление и удаление лимитированных затрат.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">5) Индексы пересчета в текущие цены: виды индексов, ввод и применение индексов вручную.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">6) Ввод в смету стоимости в текущих ценах.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">7) Применение коэффициентов.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">8) Работа с корректирующими позициями.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 18%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 67.6927%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 18%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>2.3. Ресурсный метод</strong> </span></p>\r\n</td>\r\n<td style="width: 67.6927%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">1) Ведомость ресурсов сметы.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">2) Работа с ценником: создание, использование, автоматическая загрузка цен.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">3) Проверка результатов. Подготовка и печать ресурсных смет.&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 18%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 67.6927%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 10.6598px; background-color: #f5f5f5;">\r\n<td>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>2.4. Виды смет, применение индексов и коэффициентов</strong></span></p>\r\n</td>\r\n<td>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">1)&nbsp;Составление&nbsp;сметы на отделочные работы.&nbsp;</span><span style="font-size: 10pt;">.</span></span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2)&nbsp;Составление&nbsp;сметы на ремонтные работы.&nbsp;Группа сборников на ремонтные работы.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3)&nbsp;Коэффициенты для учета особых условий производства работ.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4)&nbsp;Cоставление&nbsp;сметы на проектные работы.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">5)&nbsp;Порядок определения&nbsp;сметной&nbsp;стоимости демонтажа&nbsp; конструкций и устройств.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">6)&nbsp;Группа сборников на монтажные работы, пусконаладочные работы.&nbsp;Составление сметы на монтаж оборудования, пусконаладочные работы, новое строительство.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #ffffff; width: 18%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; width: 67.6927%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 18%; height: 15px;"><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">2.5. Учет выполненных работ</span></strong> </span></td>\r\n<td style="width: 67.6927%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">1)&nbsp;Ввод выполненных объемов.&nbsp;Просмотр итогов выполнения работ.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">2)&nbsp;Подготовка и печать актов выполненных работ.&nbsp;КС2, КС3, КС - 6, ведомость дефектов и др.&nbsp;Формат сметы в Excel.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 18%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 67.6927%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 18%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2.6. Экспертиза сметы</strong></span></p>\r\n</td>\r\n<td style="width: 67.6927%; height: 15px;"><span style="font-size: 10pt; font-family: Pro;">&nbsp;На что обращать внимание при проверке. Типичные ошибки и последствия</span></td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 18%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 67.6927%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 18%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2.7. Составление объектных смет и свободных сметных расчетов</strong></span></p>\r\n</td>\r\n<td style="width: 67.6927%; height: 15px;"><span style="font-family: Pro;">&nbsp;<span style="font-size: 10pt;">Практика составления&nbsp;&nbsp;объектных смет и свободных сметных расчетов</span></span></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span style="font-family: Pro;"><strong style="text-indent: -9pt; background-color: inherit; color: inherit; font-family: inherit; font-size: 12pt;">Формат:</strong></span></p>\r\n<p>&nbsp;</p>\r\n<ul>\r\n<li><span style="font-family: Pro;">Дневное обучение с 09.00 до 16.45 &nbsp;- 5 дней&nbsp; &nbsp; 60 часов (45 очных + 15 самостоятельная работа)</span></li>\r\n<li><span style="font-family: Pro;">Вечернее: 2 раза в неделю, вторник, четверг с 18.30 -21.30,&nbsp; 5&nbsp;недель 100 часов (45 очных + 55 часов самостоятельная работа)</span></li>\r\n<li><span style="font-family: Pro;">Дистанционное -&nbsp;онлайн обучение (просмотр онлайн - лекций, практические работы, обратная связь от преподавателя)&nbsp;5 недель - 100 часов</span></li>\r\n</ul>\r\n<hr />\r\n<p><span style="font-family: Pro;">&nbsp;<strong><span style="font-size: 12pt;">Акции и скидки:</span></strong> </span></p>\r\n<p>&nbsp;</p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit; color: inherit; font-size: 1rem;">•&nbsp;</span>Скидка 10%&nbsp;при оплате за 4 недели до обучения.&nbsp;&nbsp;</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit; color: inherit; font-size: 1rem;">•&nbsp;</span>Скидка 5%&nbsp;при оплате за 2 недели до обучения.</span></p>\r\n<p>&nbsp;</p>\r\n<p style="text-align: center;"><span style="font-family: Pro;"><a onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<hr />\r\n<p>&nbsp;</p>\r\n<table>\r\n<tbody>\r\n<tr>\r\n<td style="border-color: #ffffff; background-color: #f5f5f5; text-align: center;">\r\n<p><span style="font-family: Pro; font-size: 12pt;"><strong>&nbsp; &nbsp; &nbsp; Ведущий</strong></span></p>\r\n</td>\r\n<td style="border-color: #ffffff; background-color: #f5f5f5; text-align: center;"><span style="font-size: 12pt;"><strong><span style="font-family: Pro;">Дубова Наталья Сергеевна</span></strong> </span></td>\r\n</tr>\r\n<tr>\r\n<td style="border-color: #ffffff; background-color: #f5f5f5; text-align: center; vertical-align: middle;"><span style="font-family: Pro; font-size: 10pt;"><img style="font-family: verdana, geneva, sans-serif; font-size: 13.3333px; background-color: #ffffff; display: block; margin-left: auto; margin-right: auto;" src="images/Dubova_NS.JPG" alt="преподаватель по гранд смете и сметному делу" width="104" height="135" /></span></td>\r\n<td style="border-color: #ffffff; background-color: #ffffff;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">-&nbsp;Более 8 лет&nbsp;опыта работы преподавателем</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">-&nbsp;Более 13 лет&nbsp;опыта работы в сметном деле</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">- Руководитель проектного-сметного отдела ООО "Мега-Строй" &nbsp;&nbsp;&nbsp;&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">- Проектная работа с компаниями г. Екатеринбурга</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">Разработаны и проводятся программы обучения сметному делу и Гранд-Смете</span></p>\r\n<p><span style="font-family: Pro;"><strong>Трудовая деятельность:</strong></span></p>\r\n<p><span style="font-family: Pro;">2011 г. - по настоящее время &nbsp;- ООО «Мега-Строй»&nbsp;&nbsp;Руководитель проектно-сметного отдела</span></p>\r\n<p><span style="font-family: Pro;">2010 - 2011 гг. ООО «Севергазстройизыскания»&nbsp;Руководитель проектно-сметного отдела</span></p>\r\n<p><span style="font-family: Pro;">2009&nbsp;-&nbsp;2010 гг. - ООО «Мега-Строй»&nbsp;&nbsp;Ведущий инженер-сметчик&nbsp;</span></p>\r\n<p><span style="font-family: Pro;">2006 - 2009 гг. - ООО «Инвестиционно - Строительная Компания Унистрой-Альянс»&nbsp;Инженер-сметчик</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<hr />\r\n<p><span style="color: #333333; font-family: Pro;"><span style="font-size: 16px;"><b>О нас</b></span></span></p>\r\n<p><iframe style="background-image: url(''img/iframe.png''); display: block; margin-left: auto; margin-right: auto;" src="https://www.youtube.com/embed/yx3VnN5bh2k" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture"></iframe></p>', '', 1, 22, '2016-06-20 05:46:06', 42, '', '2019-04-26 05:27:03', 42, 0, '0000-00-00 00:00:00', '2016-06-20 05:46:06', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 136, 0, 'Курсы сметчика, обучение гранд смета, обучение сметное дело, курсы сметное дело', 'Курсы сметного дела. Очно и дистанционно. От экспертов-практиков. Обучение сметчиков. Скидки до 15% ', 1, 27614, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(127, 223, 'Доброчасова Наталья Геннадьевна', 'доброчасова-наталья-геннадьевна', '<h1 class="MsoNormal" style="text-align: left;">&nbsp; &nbsp;&nbsp; &nbsp; Доброчас<img style="float: left;" src="images/DSC0062413.jpg" width="108" height="127" />ова Наталья Геннадьевна&nbsp;</h1>\r\n<p><span style="color: #351e07; font-family: Pro; font-size: 14px; line-height: 21px; text-align: justify; background-color: #fefefe;">&nbsp; &nbsp; &nbsp; - &nbsp;</span>Проектная работа по разработке маркетинговых стратегий и мероприятий с компаниями г. Екатеринбурга</p>\r\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; - &nbsp;Опыт работы Директором отдела&nbsp;маркетинга более 10 лет</p>\r\n<p>&nbsp;&nbsp; &nbsp;&nbsp; -&nbsp; Опыт работы преподавателем более 3&nbsp;лет</p>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong><span lang="EN-US">&nbsp; Образование&nbsp;</span>Высшее:&nbsp;</strong></span>Уральский государственный экономический университет, 1996 г. Менеджмент</p>\r\n<p><strong><span lang="EN-US" style="font-family: arial, helvetica, sans-serif;">Образование дополнительное;</span></strong></p>\r\n<ul>\r\n<li class="MsoNormal">2015&nbsp;"Как стать № 1" курс Игоря Манна</li>\r\n<li>2015 Академия "СИНЕРГИЯ" (Москва), лидерство</li>\r\n<li>2012&nbsp;&laquo;Управление ассортиментом на основе категорийного менеджмента&raquo;&nbsp;СТК, Основы категорийного менеджмента</li>\r\n<li>2011&nbsp;&laquo;Самоменеджмент&raquo; 2 ступени&nbsp;Центр новых возможностей, Лидерство, саморазвитие</li>\r\n<li>2010&nbsp;&laquo;Управленческие поединки&raquo; по методике В.Тарасова&nbsp;СТК, навыки переговоров&nbsp;</li>\r\n<li>2007&nbsp;&laquo;Конкурентная разведка&raquo;&nbsp;УГТУ-УПИ, бизнес-разведка в интернете</li>\r\n<li>2006&nbsp;&laquo;Директор по маркетингу&raquo;&nbsp;Русская школа управления, г.Москва, управление маркетингом</li>\r\n</ul>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong><span lang="EN-US">Опыт работы:</span></strong></span></p>\r\n<p>2014 - 2015 Комек Машинери, ООО Директор департамента маркетинга</p>\r\n<p>2010 - 2014 Холдинг &laquo;Сантехкомплект&raquo;&nbsp;Москва.&nbsp;Директор по маркетингу</p>\r\n<p>2006 - 2010 ЗАО "УЦСК "Сантехкомплект-Урал&raquo; &nbsp;Директор по маркетингу и закупу</p>\r\n<p>2004 - 2006 Консалтинговая компания &laquo;Активные формы&raquo;&nbsp;&nbsp;Директор аналитического департамента</p>\r\n<p>2002 - 2004 Холдинг &laquo;СКМ&raquo; управляющая компания.&nbsp;&nbsp;Аналитик&nbsp;</p>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong><span lang="EN-US">Ключевые навыки:</span></strong></span></p>\r\n<ul>\r\n<li class="MsoNormal">Разработка и контроль маркетинговых проектов</li>\r\n<li class="MsoNormal">Создание &laquo;лидеров рынка в отрасли&raquo;</li>\r\n<li class="MsoNormalCxSpMiddle">Бюджетное управление</li>\r\n<li class="MsoNormalCxSpMiddle">Стратегическое планирование</li>\r\n<li class="MsoNormalCxSpMiddle">Разработка и внедрение системы&nbsp; мотивации персонала</li>\r\n<li class="MsoNormalCxSpMiddle">Проведение сессий стратегического планирования</li>\r\n</ul>\r\n<p class="MsoNormal">&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p class="MsoNormal"><span lang="EN-US" style="font-size: 11.0pt; font-family: ''Arial'',''sans-serif''; mso-ansi-language: EN-US;">&nbsp;</span></p>', '', -2, 17, '2016-08-10 09:59:24', 42, '', '2018-05-29 07:51:21', 42, 0, '0000-00-00 00:00:00', '2016-08-10 09:59:24', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 17, 11, '', '', 1, 2292, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(102, 179, 'Ваши выгоды обучения в ЭмМенеджмент 44 ФЗ', 'наши-преимущества-обучения', '<h1><span style="font-size: 10pt;">Преимущества обучения в ЭмМенеджмент<strong><span style="font-family: arial,helvetica,sans-serif;"><br /></span></strong></span></h1>\r\n<p><span style="color: black;"><span style="mso-list: Ignore;">1.<span style="font: 7.0pt ''Times New Roman'';">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><span style="color: black;">Практические <span style="mso-spacerun: yes;">&nbsp;</span>навыки&nbsp; работы (80% времени практики).</span></p>\r\n<p><span style="color: black;"><span style="mso-list: Ignore;">2.<span style="font: 7.0pt ''Times New Roman'';">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><span style="color: black;">Заполнение закупочной документации на примере <span style="font-family: arial,helvetica,sans-serif;"><b style="mso-bidi-font-weight: normal;">вашего предприятия.</b></span></span></p>\r\n<p><span style="color: black;"><span style="mso-list: Ignore;">3.<span style="font: 7.0pt ''Times New Roman'';">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><span style="color: black;">Преподаватели<span style="mso-spacerun: yes;">&nbsp; </span>- практики:<b style="mso-bidi-font-weight: normal;"><span style="font-family: arial,helvetica,sans-serif;"> руководители и аудиторы государственных и коммерческих закупок.&nbsp;</span></b></span><b style="mso-bidi-font-weight: normal;"><span style="font-family: arial,helvetica,sans-serif;">Получение только актуальной и нужной информации</span></b></p>\r\n<p><span style="color: black; mso-bidi-font-weight: bold;"><span style="mso-list: Ignore;">4.<span style="font: 7.0pt ''Times New Roman'';">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><span style="color: black; mso-bidi-font-weight: bold;">Анализ новшеств с&nbsp;учетом изменений&nbsp;на 2017 г.</span></p>\r\n<p><span style="color: black; mso-bidi-font-weight: bold;"><span style="mso-list: Ignore;">5.<span style="font: 7.0pt ''Times New Roman'';">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><span style="color: black; mso-bidi-font-weight: bold;">Минимизация рисков, типичных ошибок 44-ФЗ и 223-ФЗ.</span></p>\r\n<p><span style="color: black;"><span style="mso-list: Ignore;">6.<span style="font: 7.0pt ''Times New Roman'';">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><span style="color: black; mso-bidi-font-weight: bold;">Ср</span><span style="color: black;">оки, требования, споры, а также арбитражная практика и практика ФАС по 44-ФЗ и 223-ФЗ.</span></p>\r\n<p><span style="mso-list: Ignore;">7.<span style="font: 7.0pt ''Times New Roman'';">&nbsp; &nbsp;&nbsp;</span></span><span style="color: black;">Научитесь работать на&nbsp; <a href="http://www.zakupki.gov.ru/epz/main/public/home.html" rel="alternate">http://zakupki.gov.ru/ </a></span>(специальный тренажер-личный кабинет заказчика),&nbsp; <a href="http://sberbank-ast.ru/">http://sberbank-ast.ru/</a><span style="color: #1d4e77;"> - </span>проведение электронного аукциона.</p>\r\n<p><span style="mso-list: Ignore;">8.<span style="font: 7.0pt ''Times New Roman'';">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Специально разработанный раздаточный материал, повышающий эффективность обучения</p>\r\n<p><span style="mso-list: Ignore;">9.<span style="font: 7.0pt ''Times New Roman'';">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span>Отличная обратная связь от слушателей после обучения.</p>\r\n<p><span style="mso-list: Ignore;">10.<span style="font: 7.0pt ''Times New Roman'';">&nbsp;&nbsp; </span></span>Группы до 15 человек, индивидуальный подход к слушателям.</p>\r\n<p><span style="color: black;"><span style="mso-list: Ignore;">11.<span style="font: 7.0pt ''Times New Roman'';"> &nbsp; </span></span></span>Кофе - паузы, удобная транспортная развязка, комфортная аудитория.</p>\r\n<p><span style="mso-list: Ignore;">12.<span style="font: 7.0pt ''Times New Roman'';">&nbsp; </span></span>Отзывы можно посмотреть на нашем сайте&nbsp;<a href="http://эмменеджмент.рф/otzyvy" rel="alternate">ЭмМенеджмент</a> или на <a href="http://ekaterinburg.flamp.ru/firm/ehmmenedzhment_uchebnyjj_centr-1267165676715801" rel="alternate">www.flamp.ru</a></p>\r\n<p>13.&nbsp;Документ после обучения&nbsp; - удостоверение, диплом о профпереподготовке, &nbsp;дающие право на работу.</p>', '', -2, 16, '2015-08-21 17:18:45', 42, '', '2017-08-18 13:40:51', 42, 0, '0000-00-00 00:00:00', '2015-08-21 17:18:45', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 22, 6, '', '', 1, 21201, '', 0, '*', ''),
(105, 182, 'Поплавская Юлия Олеговна', 'субботина-юлия-олеговна', '<h1 style="text-align: center;"><span style="color: #003366; font-family: Pro;">Поплавская Юлия Олеговна</span></h1>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 23.3398px;">\r\n<td style="width: 10%; height: 23.3398px;"><span style="font-family: Pro;"><img src="images/Poplavskaya1.jpg" alt="преподаватель курсов по бухгалтерии" /></span></td>\r\n<td style="width: 82%; height: 23.3398px;">\r\n<p><span style="font-family: Pro;">Практикующий главный бухгалтер,&nbsp; преподаватель. Специализация - повышение квалификации и профессиональная переподготовка бухгалтеров,&nbsp; руководителей предприятий, менеджеров и экономистов.</span></p>\r\n<p><span style="font-family: Pro;"><strong>20&nbsp;летний опыт работы</strong> по специализации финансов</span><br /><span style="font-family: Pro;"><strong>17 летний опыт работы</strong> преподавателем</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="height: 15px; width: 92%;" colspan="2">\r\n<p><span style="font-family: Pro; color: #800000;"><strong>Разработаны и проведены программы:</strong></span></p>\r\n<p><span style="font-family: Pro;">- Собственная методика "Эффективный бухгалтерский учет"</span></p>\r\n<p><span style="font-family: Pro;">-&nbsp;Налогообложение, отчетность, типичные ошибки</span></p>\r\n<p><span style="font-family: Pro;">-&nbsp;Практика трансформации МСФО</span></p>\r\n<p><span style="font-family: Pro;">-&nbsp;Контроль и ревизия, внутренний аудит</span></p>\r\n<p><span style="font-family: Pro;">-&nbsp;Постановка бухгалтерского и управленческого учета</span></p>\r\n<p><span style="font-family: Pro;">-&nbsp;Анализ финансовой деятельности предприятия</span></p>\r\n<p><span style="font-family: Pro;">-&nbsp;Постановка эффективного документооборота на предприятии 1: С "Предприятие"</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro; color: #800000;"><strong>Образование высшее:</strong></span></p>\r\n<p><span style="font-family: Pro;">1993 -1998 г. Иркутская государственная экономическая академия, Бухгалтерский учет и аудит, экономист</span></p>\r\n<p><span style="font-family: Pro;">2003 -2005 г.&nbsp;Иркутский государственный университет Юридический институт, юрист</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro; color: #800000;"><strong>Образование дополнительное:</strong></span></p>\r\n<p><span style="font-family: Pro;">2012 г.&nbsp; Международные стандарты финансовой отчетности, главный бухгалтер по МСФО</span></p>\r\n<p><span style="font-family: Pro;">2008 г. &nbsp;Институт профессиональных бухгалтеров, аттестат профессионального главного бухгалтера</span></p>\r\n<p><span style="font-family: Pro;">с 2000 - 2016 г. семинары &nbsp;по налоговой отчетности, бухгалтерскому учету</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro; color: #800000;"><strong>Трудовая деятельность:</strong></span></p>\r\n<p><span style="font-family: Pro;">- &nbsp;с 2016 г. - ООО "Южная управляющая компания", главный бухгалтер</span></p>\r\n<p><span style="font-family: Pro;">-&nbsp; 2006 - 2014 гг. предприятие уранового холдинга ОАО "Хиагда", главный бухгалтер</span></p>\r\n<p><span style="font-family: Pro;">- 2004 - 2005 гг. &nbsp;ООО "МАТиК" финансовый директор</span></p>\r\n<p><span style="font-family: Pro;">- 2000 - 2004 гг.&nbsp;ООО ВЦ «РАКУРС» преподаватель, главный бухгалтер</span></p>\r\n<p><span style="font-family: Pro;">- преподавательская деятельность с 2000 г.</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p><br /><span style="font-family: Pro;"></span></p>', '', 1, 11, '2015-11-25 12:33:07', 42, '', '2019-04-26 09:48:32', 42, 0, '0000-00-00 00:00:00', '2015-11-25 12:33:07', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 100, 10, '', '', 1, 27922, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(192, 389, 'Курсы директора по маркетингу', 'директор-по-маркетингу-диплом-о-переподготовке-2', '<h1 style="text-align: center;"><span style="font-family: Pro;">Курсы директора по маркетингу в&nbsp;{city_d}. МВА-программа. Диплом о переподготовке</span></h1>\r\n<p><span style="font-family: Pro;">Курсы директор по маркетингу ориентированы на специалистов и руководителей подразделений и организаций, менеджеров по развитию, предпринимателей.</span></p>\r\n<p>&nbsp;</p>\r\n<p><strong style="font-family: Pro; background-color: inherit; color: inherit; font-size: 1rem;"><span style="margin: 0px; padding: 0px;">Ведущие курса:</span></strong></p>\r\n<p><span style="font-family: Pro;"><!-- noindex --></span></p>\r\n<p><span style="font-family: Pro;"><a href="index.php?option=com_content&amp;view=article&amp;id=175&amp;catid=26">Иванова Татьяна Владимировна</a>&nbsp;-&nbsp;специалист по разработке маркетинговых стратегий, директор по маркетингу</span><br /><span style="font-family: Pro;"><a href="index.php?option=com_content&amp;view=article&amp;id=149&amp;catid=26">Попов Дмитрий Павлович</a> - специалист в области интернет-коммуникаций</span><br /><span style="font-family: Pro;"><a href="http://xn--d1ababe6aaeff9c5g.xn--p1ai/obrazovanie/%D0%BC%D0%B5%D0%BD%D0%B5%D0%B4%D0%B6%D0%BC%D0%B5%D0%BD%D1%82/210-%D0%B1%D0%B8%D0%B7%D0%BD%D0%B5%D1%81-%D1%82%D1%80%D0%B5%D0%BD%D0%B5%D1%80-%D0%BC%D0%B0%D0%BA%D0%B0%D1%80%D0%BE%D0%B2%D0%B0-%D1%8E%D0%BB%D0%B8%D1%8F-%D0%BE%D0%BB%D0%B5%D0%B3%D0%BE%D0%B2%D0%BD%D0%B0" rel="nofollow">Макарова Юлия Олеговна</a> -&nbsp;тренер по стратегическому развитию, управленческим компетенциям, деловым коммуникациям и продажам</span><br /><span style="font-family: Pro;"><a href="index.php?option=com_content&amp;view=article&amp;id=53&amp;catid=14">Романова Ульяна Владимировна</a>&nbsp;- финансовый директор, специалист в области финансового менеджмента</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 12pt;"><strong>Модули обучения:</strong></span><span style="font-size: 10pt;"><strong><br /></strong></span>1. Эффективный маркетинг и продвижение&nbsp;</span><br /><span style="font-family: Pro;">2. Стратегический и организационный менеджмент</span><br /><span style="font-family: Pro;">3. Управление продажами</span><br /><span style="font-family: Pro;">4. Финансовый менеджмент</span></p>\r\n<p style="text-align: center;"><a style="font-size: 1rem; font-family: Pro; text-align: center;" onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>Выдаётся диплом о переподготовке:</p>\r\n<p><a href="#"><img src="images/slider/shablon_diploma.jpg" alt="обучение директор по маркетингу" width="30%" height="250" />&nbsp;&nbsp;</a><a href="#"><img src="images/slider/shablon_diploma_vnutri.jpg" alt="курсы директора по маркетингу" width="30%" height="250" />&nbsp;&nbsp;</a><a href="#"><img src="images/slider/директор_по_маркетингу.jpg" alt="диплом директора по маркетингу" width="30%" height="250" /></a></p>\r\n<hr />\r\n<h2><span style="font-family: Pro; font-size: 10pt;"><strong>Программа обучения на директора по маркетингу:</strong></span></h2>\r\n<table style="width: 93.9179%;">\r\n<tbody>\r\n<tr style="height: 16px; background-color: #ffffff;">\r\n<td style="height: 16px; width: 91.9179%;" colspan="2"><span style="font-family: Pro; font-size: 12pt;"><strong style="color: #a22521;">Модуль 1. Эффективный маркетинг и&nbsp;продвижение</strong></span></td>\r\n</tr>\r\n</tbody>\r\n<tbody>\r\n<tr style="height: 191.587px;">\r\n<td style="background-color: #f7f7f7; height: 191.587px; width: 17%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>1. Маркетинговый аудит положения компании на рынке</strong></span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 191.587px; width: 74.9179%;">\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">1) Как определить место компании на рынке?&nbsp;</span><span style="font-size: 10pt;">Ресурсы и способности вашей компании</span></span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Целевая аудитория и сегментирование клиентов. Определение основных сегментов аудитории.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) Позиционирование&nbsp;товара. Определяем конкурентные преимущества.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4) Анализ конкурентов и бенчмаркетинг. Как использовать конкурентов в достижении собственных целей.&nbsp;&nbsp;SWOT- анализ.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">5) Инновационный маркетинг - как непрерывное совершенствование продуктов, услуг</span></p>\r\n<p><span style="font-family: Pro;"><em><span style="font-size: 10pt;">Практика: проводим маркетинговый аудит положения компании на рынке и сегментируем клиентов. </span></em> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 17%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 74.9179%; height: 14px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 137px;">\r\n<td style="background-color: #f7f7f7; height: 137px; width: 17%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2.&nbsp;Маркетинговые исследования. Взаимосвязь стратегии компании с маркетинговыми исследованиями</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 137px; width: 74.9179%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1) Для чего именно нам нужно проведение исследований? Анализ и эффективные стратегии</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Выбираем инструменты исследований: количественные и качественные исследования, полевые и кабинетные. Социологические и маркетинговые. Где искать данные, чтобы сэкономить на исследованиях и повысить их эффективность?</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) Использование маркетинговых исследований и маркетинговой информации в компании. Как сэкономить на исследованиях и включить в маркетинг каждого сотрудника компании?</span></p>\r\n<p><span style="font-family: Pro;"><em><span style="font-size: 10pt;">Практика: проводим исследования и определяем маркетинговую стратегию&nbsp; </span></em> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 17%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 74.9179%; height: 14px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 151px;">\r\n<td style="background-color: #f7f7f7; height: 151px; width: 17%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong><span lang="EN-US">3.&nbsp;Торговый маркетинг&nbsp;</span></strong> </span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 151px; width: 74.9179%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1) Категорийный менеджмент&nbsp;и прибыльность товаров. Принцип Паретто. АВС анализ и матрица БКГ</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Принципы управления ассортиментной матрицей.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) УТП (уникальное торговое предложение). Как правильно определить свою уникальность? Какие признаки могут стать преимуществом вашего товара или услуги, а какие нет. &nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4) Ассортиментная политика компании. &nbsp;Как заработать на расширении ассортимента?&nbsp;</span></p>\r\n<p><span style="font-family: Pro;"><em><span style="font-size: 10pt;">Практика: формируем&nbsp; ассортиментную матрицу </span></em> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 17%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 74.9179%; height: 14px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 134px;">\r\n<td style="background-color: #f7f7f7; height: 134px; width: 17%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>4.&nbsp;Ценообразование и управление ассортиментом</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 134px; width: 74.9179%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1)&nbsp;Ценообразование и ценовая стратегия. Как сформировать стоимость товара при разных позициях на рынке?&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2)&nbsp;Управление товарным ассортиментов на промышленных рынках и в сфере услуг</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">Практика: Формируем&nbsp;УТП&nbsp;вашей компании с рыночным обоснованием&nbsp; и &nbsp;продвижением.</span></p>\r\n<p><span style="font-family: Pro;"><em><span style="font-size: 10pt;">Практика: Определяем способы повышения клиентоориентированности вашей компании. </span></em> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 17%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 74.9179%; height: 14px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 243px;">\r\n<td style="background-color: #f7f7f7; height: 243px; width: 17%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>5.&nbsp;Интегрированные маркетинговые коммуникации. Реклама и продвижение</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 243px; width: 74.9179%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1) Инструменты продвижения. Их возможности и недостатки. Современные технологии управления взаимоотношениями с клиентами.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Нейромаркетинг. Прямой маркетинг. &nbsp;Ивент-маркетинг. Public Relations.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) Понятия «бренд» и «брендинг». &nbsp;Чем бренд отличается от товара. Как создать бренд.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4) Подходы к оценке эффективности рекламных кампаний.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">5) Элементы бренда: как управлять популярностью торговой марки.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">6) Определение точек контакта с существующими и потенциальными клиентами.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">7) CRM. &nbsp;Как выстраивать взаимоотношения с клиентами с помощью современных автоматизированных систем.<br /></span></p>\r\n<p><span style="font-family: Pro;"><em><span style="font-size: 10pt;">Практика: считаем эффективность рекламных компаний </span></em> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 17%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 74.9179%; height: 14px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 120px;">\r\n<td style="background-color: #f7f7f7; height: 120px; width: 17%;"><span style="font-family: Pro; font-size: 10pt;"><strong>6.&nbsp;Медиапланирование</strong></span></td>\r\n<td style="background-color: #f7f7f7; height: 120px; width: 74.9179%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1)&nbsp;Медиапланирование. Эффективная частота размещения рекламы по разным каналам продвижения.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2)&nbsp;Бюджетирование рекламных кампаний. &nbsp;Как эффективно распределять бюджеты, чтобы получать максимальный результат.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3)&nbsp;Подходы к оценке эффективности рекламных кампаний.</span></p>\r\n<p><span style="font-family: Pro;"><em><span style="font-size: 10pt;">Практика: составляем медиа-план </span></em> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 17%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 74.9179%; height: 14px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 91.9179%; background-color: #f7f7f7; height: 14px;" colspan="2"><span style="font-family: Pro; font-size: 10pt;"><strong>7.&nbsp;Формирование маркетингового плана вашей компании.</strong></span></td>\r\n</tr>\r\n<tr style="height: 14px; background-color: #ffffff;">\r\n<td style="width: 91.9179%; height: 14px; background-color: #ffffff;" colspan="2">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 91.9179%; height: 14px; text-align: center;" colspan="2">\r\n<p style="color: #a22521;"><span style="font-size: 12pt;"><span style="font-family: Pro;"><strong style="color: #000000;">Интернет-маркетинг</strong> </span></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 10px;">\r\n<td style="background-color: #f7f7f7; height: 10px; width: 17%;"><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">8.&nbsp;SEO: базовые основы и практические инструменты</span></strong> </span></td>\r\n<td style="background-color: #f7f7f7; height: 10px; width: 74.9179%;">\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;"><strong><span style="color: #800000;">Что&nbsp; изучите:</span> </strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Алгоритмы работы поисковых систем. Анализ поисковых запросов. Факторы, влияющие на ранжирование сайтов</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Сбор семантического ядра и его кластеризация. Изучение сервиса Wordstat.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Размещение контента на сайте: текстов, инфографика, заполнение метатегов, подбор изображений, видео.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">SEO-копирайтинг: правила написания продающих текстов в соответствии с алгоритмами поисковых систем.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Внутренняя перелинковка страниц. Схемы перелинковки.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Внешняя оптимизация сайта. Подбор площадок для размещения ссылок.</span></li>\r\n</ol>\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Какие навыки получите:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Сбор семантического ядра, кластеризация ключевых фраз.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Работа с сервисом Wordstat.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Подготовка технических заданий на SEO-копирайтинг.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Выбор подходящих площадок для внешней оптимизации.</span></li>\r\n</ol></td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="background-color: #ffffff; height: 14px; width: 17%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; height: 14px; width: 74.9179%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 10px;">\r\n<td style="background-color: #f7f7f7; height: 10px; width: 17%;"><span style="font-family: Pro; font-size: 10pt;"><strong>9.&nbsp;</strong><strong>Контекстная реклама: основы размещения рекламы в Яндекс и&nbsp;</strong><strong>Google</strong></span></td>\r\n<td style="background-color: #f7f7f7; height: 10px; width: 74.9179%;">\r\n<p style="text-align: justify;"><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Что освоите:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Виды рекламных кампаний.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Использование ключевых фраз: подбор подходящих, фильтрация минус-фраз.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Создание рекламных кампаний в Яндекс Директ и Google Adwords: регистрация в личном кабинете, базовые настройки, создание рекламных объявлений.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Изучение факторов, влияющих на стоимость клика.</span></li>\r\n</ol>\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Какие навыки&nbsp; получите:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Грамотный подбор ключевых фраз и составление эффективных объявлений.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Настройка рекламной кампании в личном кабинете Яндекс Директ и Google Adwords.</span></li>\r\n</ol></td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="background-color: #ffffff; height: 13px; width: 17%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; height: 13px; width: 74.9179%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 10px;">\r\n<td style="background-color: #f7f7f7; height: 10px; width: 17%;"><span style="font-family: Pro;"><strong><span style="font-size: 10pt;"><span lang="EN-US">10. Системы аналитики. Изучение Яндекс Метрики.</span></span> </strong> </span></td>\r\n<td style="background-color: #f7f7f7; height: 10px; width: 74.9179%;">\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Что&nbsp; проработаете:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Показатели, которые необходимо отслеживать.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Регистрация в Яндекс Метрике, знакомство с личным кабинетом.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Изучение отчетов в системе аналитики.</span></li>\r\n</ol>\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Какие&nbsp; навыки получите:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Понимание основных отчетов и показателей.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Настройка целей системе аналитики.</span></li>\r\n</ol></td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="background-color: #ffffff; height: 13px; width: 17%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; height: 13px; width: 74.9179%;"><span style="font-family: Pro;">&nbsp;&nbsp;</span></td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="background-color: #f7f7f7; height: 13px; width: 17%;"><span style="font-family: Pro;"><strong><span style="font-size: 10pt;"><span lang="EN-US">11.&nbsp;SMM. Работа в социальных сетях: Facebook, ВКонтакте, Instagram.</span></span> </strong> </span></td>\r\n<td style="background-color: #f7f7f7; height: 13px; width: 74.9179%;">\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Что изучите:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-size: 10pt; font-family: Pro;">Обзор возможностей социальных сетей.</span></li>\r\n<li><span style="font-size: 10pt; font-family: Pro;">Стратегии позиционирования.</span></li>\r\n<li><span style="font-size: 10pt; font-family: Pro;">Виды сообществ в каждой из социальных сетей.</span></li>\r\n<li><span style="font-size: 10pt; font-family: Pro;">Формирование контент-плана.</span></li>\r\n<li><span style="font-size: 10pt; font-family: Pro;">Знакомство с сервисами автопостинга (SMM Planner), сбора целевой аудитории (Церебро Таргет).</span></li>\r\n<li><span style="font-size: 10pt; font-family: Pro;">Бесплатные методы продвижения.</span></li>\r\n<li><span style="font-size: 10pt; font-family: Pro;">Запуск таргетированной рекламы в Facebook, ВКонтакте, Instagram.</span></li>\r\n</ol>\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Какие навыки&nbsp; получите:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-size: 10pt; font-family: Pro;">Создание сообщества для Вашего бизнеса.&nbsp;</span></li>\r\n<li><span style="font-size: 10pt; font-family: Pro;">Работа в программах автопостинга и сбора целевой аудитории.</span></li>\r\n<li><span style="font-size: 10pt; font-family: Pro;">Настройка таргетированной рекламы в каждой из социальных сетей: Facebook, ВКонтакте, Instagram.</span></li>\r\n</ol></td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="background-color: #ffffff; height: 13px; width: 17%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; height: 13px; width: 74.9179%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="background-color: #f7f7f7; height: 13px; width: 17%;"><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">12.&nbsp;Продвижение видео-канала на You-Tube.</span></strong> </span></td>\r\n<td style="background-color: #f7f7f7; height: 13px; width: 74.9179%;">\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Что&nbsp; рассмотрите:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Виды видео-контента и особенности его подготовки.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Запуск видео-канала на You-Tube, базовые настройки.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Разработка стратегии ведения канала.&nbsp;</span></li>\r\n</ol>\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Какие практические навыки:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Запуск видео-канала на You-Tube.</span></li>\r\n<li style="text-align: left;"><span style="font-family: Pro; font-size: 10pt;">Базовые настройки канала для эффективного продвижения.</span></li>\r\n</ol></td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="background-color: #ffffff; height: 13px; width: 17%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; height: 13px; width: 74.9179%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="background-color: #f7f7f7; height: 13px; width: 17%;"><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">13.&nbsp;E-mail маркетинг: основы работы и запуск продающих рассылок.</span></strong> </span></td>\r\n<td style="background-color: #f7f7f7; height: 13px; width: 74.9179%;">\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Что&nbsp; освоите:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Сбор базы подписчиков – основные инструменты и сервисы.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Обзор основных инструментов для рассылок: плюсы и минусы.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Типы рассылок и выбор эффективной стратегии.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Создание цепочки писем и особенности формирования контента.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Знакомство с сервисом для рассылок Send Pulse.</span></li>\r\n</ol>\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Какие навыки получите:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Создание продающего электронного письма.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Настройка сервиса Send Pulse.</span></li>\r\n</ol></td>\r\n</tr>\r\n</tbody>\r\n<tbody>\r\n<tr style="height: 15px;">\r\n<td style="background-color: #ffffff;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 17%; height: 15px; background-color: #f5f5f5;"><span style="font-family: Pro;">&nbsp;<strong>Проектная работа</strong></span></td>\r\n<td style="width: 74.9179%; height: 15px; background-color: #f5f5f5;"><span style="font-family: Pro;">&nbsp;Разработка и совершенствование маркетинговой стратегии на предприятии</span></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<table style="width: 93.9442%;">\r\n<tbody>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="height: 15px; width: 17%;"><span style="font-family: Pro;"></span></td>\r\n<td style="height: 15px; width: 74.023%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 16px; background-color: #ffffff;">\r\n<td style="height: 16px; width: 91.023%;" colspan="2"><span style="font-family: Pro; font-size: 12pt;"><strong style="color: #a22521;">Модуль 2.&nbsp; Продажи и переговоры в маркетинге</strong></span></td>\r\n</tr>\r\n<tr style="height: 190px; background-color: #f5f5f5;">\r\n<td style="height: 190px; width: 17%;">\r\n<p><span style="font-family: Pro;"><strong>1. Поиск клиентов. Как искать клиентов?</strong>&nbsp;</span></p>\r\n</td>\r\n<td style="height: 190px; width: 74.023%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1) Взаимосвязь отдела продаж и отдела маркетинга.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Сбор информации о бизнесе клиента и конкурентах.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) "Холодные" и "теплые" звонки (ключевые фразы). Правильная постановка целей, сценарии звонка.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4) Контакт с клиентом. Универсальные приемы установления контакта. Практика установления контакта.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">5) Как управлять воронкой продаж. Воронка как инструмент анализа эффективности работы менеджера.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">6) Лучшие способы поиска новых клиентов.</span></p>\r\n<p><span style="font-family: Pro;"><em><span style="font-size: 10pt;">Практика:&nbsp;разработки коммерческих предложений, скриптов продаж, "продающих" текстов.</span></em> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="height: 15px; width: 17%;"><span style="font-family: Pro;"></span></td>\r\n<td style="height: 15px; width: 74.023%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 87px; background-color: #f5f5f5;">\r\n<td style="height: 87px; width: 17%;">\r\n<p><span style="font-family: Pro;"><strong>2. Правильные вопросы,&nbsp;выявление потребностей</strong></span></p>\r\n</td>\r\n<td style="height: 87px; width: 74.023%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">1) Правильные вопросы для выявления потребности, зачем задавать вопросы?</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">2) Развитие диалога: управляем беседой и клиентом при помощи вопросов.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="height: 15px; width: 17%;"><span style="font-family: Pro;"></span></td>\r\n<td style="height: 15px; width: 74.023%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 101px; background-color: #f5f5f5;">\r\n<td style="height: 101px; width: 17%;">\r\n<p><span style="font-family: Pro;"><strong>3. Презентация компании, товара</strong></span></p>\r\n</td>\r\n<td style="height: 101px; width: 74.023%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">1) Покупательские мотивы, модель перевода свойств в выгоду.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">2) Способы обоснования цены, аргументируем цена&nbsp;&nbsp;- выгода.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">3) 6 лучших способов для выгодной презентации цены.&nbsp;</span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p><span style="font-family: Pro;"><em><span style="font-size: 10pt;">Практика выявления мотивов и формирования выгод клиента.&nbsp;</span></em> </span></p>\r\n<p><span style="font-family: Pro;"><em><span style="font-size: 10pt;">Практика разработки презентационных материалов.</span></em> </span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="height: 15px; width: 17%;"><span style="font-family: Pro;"></span></td>\r\n<td style="height: 15px; width: 74.023%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 130px; background-color: #f5f5f5;">\r\n<td style="height: 130px; width: 17%;">\r\n<p><span style="font-family: Pro;"><strong>4.&nbsp;Преодоление реакций клиента. Работа с возражениями</strong>&nbsp;</span></p>\r\n</td>\r\n<td style="height: 130px; width: 74.023%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1)&nbsp;Причины возникновения возражений:&nbsp;&nbsp;цена, отговорки.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Модель обработки возражений, применение тактики аргументации.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) 10 правил работы с возражениями клиентов.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4) Скрипты на главные возражение «дорого», «я подумаю», «нет денег».&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="height: 15px; width: 17%;"><span style="font-family: Pro;"></span></td>\r\n<td style="height: 15px; width: 74.023%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 101px; background-color: #f5f5f5;">\r\n<td style="height: 101px; width: 17%;">\r\n<p><span style="font-family: Pro;"><strong>5. Завершение сделки, диалога.&nbsp;Как завершить диалог, чтобы &nbsp;клиент купил товар?</strong></span></p>\r\n</td>\r\n<td style="height: 101px; width: 74.023%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">1)&nbsp;Сигналы готовности клиента к покупке приемы.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">2) Этап завершения сделки, тонкости доведения сделки до результата.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">3) Скрипты на завершение сделки.&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="height: 15px; width: 17%;"><span style="font-family: Pro;"></span></td>\r\n<td style="height: 15px; width: 74.023%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 101px; background-color: #f5f5f5;">\r\n<td style="height: 101px; width: 17%;">\r\n<p><span style="font-family: Pro;"><strong>6. Формирование потребностей – СПИН</strong></span></p>\r\n</td>\r\n<td style="height: 101px; width: 74.023%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1)&nbsp;Модель СПИН как гибкая система продаж.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2)&nbsp;Вопросы – СПИН.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3)&nbsp;Как работает СПИН?</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="height: 15px; width: 17%;"><span style="font-family: Pro;"></span></td>\r\n<td style="height: 15px; width: 74.023%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 72px; background-color: #f5f5f5;">\r\n<td style="height: 72px; width: 17%;">\r\n<p><span style="font-family: Pro;"><strong>7. Алгоритм продажи с крупными клиентами, важные этапы ведения деловой беседы</strong></span></p>\r\n</td>\r\n<td style="height: 72px; width: 74.023%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">1) Как вести себя с крупными клиентами, особенности продажи.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">2) Умение правильно строить отношения.&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="height: 15px; width: 17%;"><span style="font-family: Pro;"></span></td>\r\n<td style="height: 15px; width: 74.023%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 44px; background-color: #f5f5f5;">\r\n<td style="height: 44px; width: 17%;">\r\n<p><span style="font-family: Pro;"><strong>8. Кросс-продажи</strong></span></p>\r\n</td>\r\n<td style="height: 44px; width: 74.023%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">Как они повышают прибыль?&nbsp;</span></p>\r\n<p><span style="font-family: Pro;"><em><span style="font-size: 10pt;">Практика разработки дополнительных предложений для клиентов.</span></em> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 16px; background-color: #f5f5f5;">\r\n<td style="background-color: #ffffff; height: 16px; width: 17%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; height: 16px; width: 74.023%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 17px; background-color: #f5f5f5;">\r\n<td style="height: 17px; width: 17%;">\r\n<p><span style="font-family: Pro;"><strong>9. Постановка целей, личная эффективность</strong></span></p>\r\n</td>\r\n<td style="height: 17px; width: 74.023%;"><span style="font-size: 10pt; font-family: Pro;">Личная эффективность. Целеполагание в «SMART»- формате.&nbsp;</span></td>\r\n</tr>\r\n<tr style="height: 17px; background-color: #f5f5f5;">\r\n<td style="background-color: #ffffff;">&nbsp;</td>\r\n<td style="background-color: #ffffff;">&nbsp;</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span style="font-size: 12pt; font-family: Pro;"><strong style="color: #a22521;">Модуль 3. Стратегия, тактика и операционное управление</strong></span></p>\r\n<table style="width: 94.2075%;">\r\n<tbody>\r\n<tr style="height: 233px; background-color: #f5f5f5;">\r\n<td style="width: 12.6857%; height: 233px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>1. Оперативное управление персоналом: постановка задачи, делегирование, проведение совещаний, мотивация и контроль</strong> </span></p>\r\n</td>\r\n<td style="width: 71.3143%; height: 233px;">\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">1)&nbsp;Ручное управление или регулярный менеджмент. Стадии развития компании и управления в организации. Зачем нужна регламентация бизнес процессов? Ключевые&nbsp;функции менеджмента</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">2)&nbsp;Как организовывать работу подчиненных, делегировать полномочия и контролировать выполнение задач. Кому можно делегировать?</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro;"><span style="font-size: 10pt;">Постановка задач,&nbsp;алгоритм постановки задач.&nbsp;&nbsp;Как эффективно поставить задачу и&nbsp; получить результат выполнения?<br /></span><span style="font-size: 10pt;">Обратная связь.&nbsp;Как предоставлять сотруднику развивающую обратную связь? виды и правила обратной&nbsp;связи.<br />Как ругать сотрудника, чтобы улучшились результаты</span></span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">3)&nbsp;Планирование:&nbsp;расстановка приоритетов, линейное планирование, сложное планирование.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">4) Контроль: функции контроля, определение количества точек контроля, анализ причин несоответствия плана и фактическим результатам.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">5)&nbsp;Подготовка и проведение совещаний.&nbsp;Причины неэффективного совещания.&nbsp;Техники&nbsp;принятия решений&nbsp;на совещании.&nbsp;</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">4) Как мотивировать на результат,&nbsp;что движет сотрудниками.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">Уровни зрелости сотрудника. Искать готового или адаптировать под&nbsp; себя. Материальная и нематериальная мотивация. Система сбалансированных&nbsp; показателей&nbsp; и KPI, связь со стратегической картой</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 12.6857%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 71.3143%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.6857%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>2. Проектный&nbsp;<br />менеджмент</strong> </span></p>\r\n</td>\r\n<td style="width: 71.3143%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">Функционал менеджера проекта. Процессы&nbsp; проекта: инициация, планирование,&nbsp;исполнение, мониторинг, контроль, завершение проекта. Виды проектов. Разница от текущей деятельности. Что влияет на успешность проекта?Управление и снижение рисков, как часть проекта.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #ffffff; width: 12.6857%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; width: 71.3143%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.6857%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>3. Тайм - менеджмент. Личная эффективность</strong> </span></p>\r\n</td>\r\n<td style="width: 71.3143%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1)&nbsp;Инструменты принятия решений. Техники и методы принятия управленческих решений</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2)&nbsp;Как использовать инструменты тайм-менеджмента:&nbsp; целеполагание, расстановка приоритетов.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3)&nbsp;Как сократить «поглотителей времени»?</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4)&nbsp;Какие методы планирования применять (6М, метод ALP, SMART, матрица Эйзенхауэра).&nbsp; Проактивная и реактивная позиция руководителя. Индивидуальный тип восприятия времени.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">5)&nbsp;Способы структурирования рабочего пространства, организация&nbsp;рабочего времени.&nbsp;</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro; font-size: 10pt;">- Как сохранять баланс в жизни и находить источники повышения работоспособности.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro; font-size: 10pt;">- Методы предупреждения стресса и эмоционального выгорания руководителя.&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #ffffff; width: 12.6857%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; width: 71.3143%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.6857%; height: 15px;"><span style="font-size: 10pt; font-family: Pro;"><span style="font-size: 10pt;"><b>4.Эмоциональный&nbsp;</b></span><span style="font-size: 13.3333px;"><b>интеллект</b></span><span style="font-size: 10pt;"><b>, как повышение уровня руководства</b></span> </span></td>\r\n<td style="width: 71.3143%; height: 15px;">\r\n<p><span style="font-family: Pro;"><em><span style="font-size: 10pt;">1.Что дает Эмоциональный интеллект в области повышения качества руководства и эффективности компании в целом </span></em> </span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">Управление людьми на основе эмоционального&nbsp; интеллекта. Значимость эмоционального интеллекта для различных профессий и бизнес-задач</span></p>\r\n<p><span style="font-family: Pro;"><em><span style="font-size: 10pt;">2. Эмоциональная компетентность руководителя </span></em> </span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">Как использовать эмоции в бизнесе. Как распознать свое эмоциональное состояние и изменить его в зависимости от задач. Формирование благоприятного делового контакта.&nbsp;<br /></span><span style="font-size: 10pt;">Как грамотно использовать энергию «негативных» эмоций?&nbsp;</span><span style="font-size: 10pt;">- Практика Отработка навыков управления эмоциями в ситуациях взаимодействия с другими людьми<br /></span><span style="font-size: 10pt;">Эмоции женщин и эмоции мужчин – гендерные различия</span></span></p>\r\n<p><span style="font-family: Pro;"><em><span style="font-size: 10pt;">3. Эмоциональный интеллект, как инструмент для решения сложных ситуаций в бизнес-среде</span></em> </span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">Эмоции положительно влияющие &nbsp;и отрицательно влияющие на эффективность деятельности<br /></span><span style="font-size: 10pt;">Индивидуальные особенности мотивации персонала. Эмоции в основе мотивации.</span></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #ffffff; width: 12.6857%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; width: 71.3143%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.6857%; height: 15px;"><span style="font-size: 10pt; font-family: Pro;"><strong>5.Власть и лидерство</strong> </span></td>\r\n<td style="width: 71.3143%; height: 15px; text-align: justify;">\r\n<p><span style="font-family: Pro;"><em><span style="font-size: 10pt;">1. Создание и управление эффективных команд</span></em> </span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">Как подбирать членов команды? Коммуникации в командах как инструмент эффективного лидера.&nbsp;</span><span style="font-size: 10pt;">Практика: Развитие навыков лидерского взаимодействия с подчиненными</span></span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">Техники работы с эмоциями при решении командных задач:&nbsp;н</span><span style="font-size: 10pt;">астройки на успех.&nbsp;</span></span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">Рациональный и интуитивный подход в принятии решений.&nbsp;Трудные решения и эмоции.</span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">Обратная связь через аргументацию, включающую&nbsp;разные виды</span><span style="font-size: 10pt;">&nbsp;с</span><span style="font-size: 10pt;">остояний</span><span style="font-size: 10pt;">&nbsp;сотрудников. Предотвращение конфликтных ситуаций.</span></span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">Эмоциональный интеллект и развитие других.&nbsp;Коучинг в развитии эмоционального интеллекта.&nbsp;</span></p>\r\n<p><span style="font-family: Pro;"><em><span style="font-size: 10pt;">2. Харизма лидера. Спонтанное поведение.&nbsp; </span></em><span style="font-size: 10pt;">Приемы развития харизмы</span></span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">Эффективные коммуникации.&nbsp;Имидж лидера. Поза, жесты, речь.&nbsp;Пластика движений, жестикуляция, голосовые режимы, тембр голоса, интонация.&nbsp;</span><span style="font-size: 10pt;">Практика: Приемы эффективного общения.&nbsp;</span></span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">Концепции лидерства.</span><span style="font-size: 10pt;">Ситуационные модели лидерства</span><span style="font-size: 10pt;">&nbsp;Практика: Определение собственного стиля лидерства: предпочитаемый стиль влияния и зоны развития. Определение и выбор оптимального стиля управления</span></span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">Лидер и группа.&nbsp;</span><span style="font-size: 10pt;">Законы групповой динамики. Управление групповой динамикой.&nbsp;Инструмент лидера - искусство говорить публично</span></span></p>\r\n<p><span style="font-family: Pro;"><em><span style="font-size: 10pt;">3. Власть. </span></em><span style="font-size: 10pt;"><strong>&nbsp;</strong>Внутренняя сила. Технологии и искусство доминирования. Принципы формирования общественного мнения.&nbsp;</span><span style="font-size: 10pt;">&nbsp;Власть личности, власть положения, власть знания. Какой тип власти применять в конкретной ситуации?&nbsp;</span><span style="font-size: 10pt;">Практика: Выбор собственного типа власти.</span><span style="font-size: 10pt;"><br /></span></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #ffffff; width: 12.6857%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; width: 71.3143%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.6857%; height: 15px;"><span style="font-size: 10pt; font-family: Pro;"><strong>6. Оперативное планирование или как обеспечить продвижение к обозначенным целям всеми сотрудниками</strong> </span></td>\r\n<td style="width: 71.3143%; height: 15px;">\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">1)&nbsp;Оперативные цели и планы. Введение контрольных показателей.<br /></span><span style="font-size: 10pt;">2)&nbsp;Достижение результата. Система планирования, как инструмент достижения результата.&nbsp;<br /></span><span style="font-size: 10pt;">3)&nbsp;Уровни планирования от стратегии к тактике. Мониторинг и изучение. Анализ планирования и результатов с учетом их влияния на показатели оперативных, тактических и стратегических планов.<br /></span><span style="font-size: 10pt;">4)&nbsp;Составляем план дальнейших действий.<br /></span><span style="font-size: 10pt;">5)&nbsp;Подводим итоги.</span></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #ffffff; width: 12.6857%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; width: 71.3143%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.6857%; height: 15px;"><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">7. Формирование стратегии развития сотрудника, подразделения, компании&nbsp;</span></strong> </span></td>\r\n<td style="width: 71.3143%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1)&nbsp;Новые уровни развития. План, цель, стратегия. Эффективный&nbsp;баланс: жесткое&nbsp; планирование и гибкое реагирование на изменения.&nbsp;&nbsp;Уровни планирования. Цикл процесса планирования.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2)&nbsp;Аудит действующих целей и стратегии. Разрабатываем&nbsp; План развития&nbsp;сотрудника, подразделения, компании.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #ffffff; width: 12.6857%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; width: 71.3143%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.6857%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>8. Что делать для реализации стратегии?</strong> </span></p>\r\n</td>\r\n<td style="width: 71.3143%; height: 15px;">\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro; font-size: 10pt;">1)&nbsp;Стратегические цели и стратегический план сотрудников, подразделений и компании. Тактические цели.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro; font-size: 10pt;">2)&nbsp;Выбор стратегии движения. Вопросы стратегического прогнозирования.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro; font-size: 10pt;"><span lang="EN-US">3)&nbsp;</span>Оцениваем реальную ситуацию, ресурсы сотрудников,&nbsp;компании.&nbsp;<span lang="EN-US">SWOT -&nbsp;</span>анализ сотрудников и компании. Разные виды SWOT анализа: линейный и перекрестный.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro;"><span style="font-size: 10pt;">4)&nbsp;Разработка карты стратегии – интегрируем &nbsp;составляющие сбалансированной системы показателей&nbsp;</span><span style="font-size: 10pt;">финансы, клиенты, процессы, персонал. Разрабатываете карту на вашем предприятии.<br /></span><span style="font-size: 10pt;">- Определяем стратегическую цель в финансовых показателях.<br /></span><span style="font-size: 10pt;">- Определяем бизнес процессы, что&nbsp;обеспечит достижение финансовых целей.<br /></span><span style="font-size: 10pt;">- Выявляем внутренние бизнес-процессы для реализации целей и доводим их до совершенства.<br /></span><span style="font-size: 10pt;">- Определяем стратегическую роль персонала.&nbsp;<em>Совершенствуем&nbsp;систему обучения и развития персонала.</em></span></span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro; font-size: 10pt;">5)&nbsp;Для чего нужен пессимистический сценарий? Составляем пессимистический и&nbsp; оптимистический сценарии.&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #ffffff;">&nbsp;</td>\r\n<td style="background-color: #ffffff;">&nbsp;</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span style="font-family: Pro; font-size: 12pt;"><strong style="color: #a22521;">Модуль 4. Финансы предприятия</strong></span></p>\r\n<table style="width: 93.8652%;">\r\n<tbody>\r\n<tr style="height: 152px;">\r\n<td style="background-color: #f7f7f7; height: 152px; width: 14.3266%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>1. Экономика предприятия</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 152px; width: 70.6734%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1) Точка безубыточности. Анализ безубыточности</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Ключевой расчет маржинальной прибыли, чистой прибыли. Зачем делить на постоянные и переменные расходы</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) Ключевые показатели эффективности предприятия,&nbsp; EBITDA, ROE</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4) Анализ финансовых результатов деятельности. Взаимосвязь с отчетом денежных средств. Операционная, финансовая и инвестиционная деятельность зачем разделять?</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">5) Анализ эффективности использования&nbsp; оборотных средств&nbsp;-&nbsp;оборачиваемость.&nbsp; Нормирование материальных и трудовых ресурсов</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">&nbsp; <em>-&nbsp;Практические задания точки безубыточности и валовой маржи. Определение наиболее рентабельных проектов, видов деятельности, продукции</em></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="background-color: #ffffff; height: 13px; width: 14.3266%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; height: 13px; width: 70.6734%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 49px;">\r\n<td style="background-color: #f7f7f7; height: 49px; width: 14.3266%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>2. Организация аналитического учета затрат</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 49px; width: 70.6734%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1) Бухгалтерский план счетов, с использованием которых осуществляется учет затрат на производство. Группировка балансовых статей, баланс предприятия, строение балансовых счетов.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Затраты по статьям калькуляции. Учет отдельных видов затрат. Система " Директ - костинг" Стандарт - костинг, Cost-killing</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) Специфика и области применения различных методов учета производственных затрат: позаказного, котлового, попередельного.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4) Классификация расходов и затрат,&nbsp; формирующих себестоимость продукции,&nbsp; их отличия. Прямые и косвенные расходы. Как рассчитать себестоимость продукции и&nbsp;распределить косвенные расходы</span></p>\r\n<p><span style="font-family: Pro;"><em><span style="font-size: 10pt;">-&nbsp;Практические задания по расчету себестоимости и цены. Оптимизация затрат.</span></em> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 2px;">\r\n<td style="background-color: #ffffff; height: 2px; width: 14.3266%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; height: 2px; width: 70.6734%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 177px;">\r\n<td style="background-color: #f7f7f7; height: 177px; width: 14.3266%;"><span style="font-family: Pro; font-size: 10pt;"><strong>3.&nbsp;&nbsp; Финансовая отчетность. Методы финансового анализа</strong></span></td>\r\n<td style="background-color: #f7f7f7; height: 177px; width: 70.6734%;">\r\n<p><span style="font-family: Pro;"><em>Для чего нужен финансовый анализ на всех этапах развития компании?&nbsp;Какие финансовые показатели составляются и анализируется на разных жизненных циклах организации.</em></span></p>\r\n<p><span style="font-family: Pro;">1) Финансовый анализ, как метод оценки текущего и перспективного финансового состояния предприятия: трендовый, факторный, метод цепных подстановок, горизонтальный, вертикальный</span></p>\r\n<p><span style="font-family: Pro;">2) Анализируем бухгалтерский баланс, в чем отличие от управленческого баланса. Признаки хорошего баланса</span></p>\r\n<p><span style="font-family: Pro;">3) Особенности составления отчета о прибылях и убытках, отличие от Бюджета доходов и расходов</span></p>\r\n<p><span style="font-family: Pro;">4) Коэффициенты финансового анализа: платежеспособность и ликвидность, коэффициент инвестирования, 10 коэффициентов&nbsp; финансовой устойчивости&nbsp;и деловой активности.</span></p>\r\n<p><span style="font-family: Pro;">5)&nbsp;Оптимизация&nbsp;операционного и&nbsp;финансового цикла . Управление&nbsp;материальными запасами, дебиторской задолженностью - АВС анализ. Регламент работы с дебиторкой<br /></span></p>\r\n<span style="font-family: Pro; font-size: 10pt;"><em>- Кейс по анализу финансовой отчетности</em></span></td>\r\n</tr>\r\n<tr style="height: 2px;">\r\n<td style="background-color: #ffffff; height: 2px; width: 14.3266%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; height: 2px; width: 70.6734%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 181px;">\r\n<td style="background-color: #f7f7f7; height: 181px; width: 14.3266%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>4. Финансовый менеджмент - Управление инвестициями</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 181px; width: 70.6734%;">\r\n<p><span style="font-family: Pro;"><em><span style="font-size: 10pt;">Показатели для расчета эффективности инвестиционного проекта. Стратегии управления инвестициями </span></em> </span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">2) Чистый дисконтированный доход,&nbsp; (NPV),&nbsp;&nbsp;</span><span style="font-size: 10pt;">Индекс рентабельности инвестиций (PI).&nbsp;</span><span style="font-size: 10pt;">&nbsp;Внутренняя норма доходности (IRR).</span><span style="font-size: 10pt;">&nbsp;Срок окупаемости инвестиций (PP)<br /></span></span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) Управление заемным капиталом. как рост дополнительной прибыли и развития организации</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4) Стоимость капитала: ее составляющие и методы оценки.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">5) Ликвидность и способы ее оценки. Оптимальное соотношение структуры баланса&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><em>-&nbsp;Практические задания по расчету оценки инвестиционных проектов</em>&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="background-color: #ffffff; height: 13px; width: 14.3266%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; height: 13px; width: 70.6734%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 53.3855px;">\r\n<td style="background-color: #f7f7f7; height: 53.3855px; width: 14.3266%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>5. Эффективная финансово – экономическая служба</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 53.3855px; width: 70.6734%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1) Требования к финансовой отчетности для руководителей.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Принципы учетной политики управленческого учета.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) Чтение и интерпретации финансовых отчетов. Практикум по подготовке и использованию финансовой отчетности</span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">4) Функции финансового управляющего.&nbsp;</span><span style="font-size: 10pt;">Распределение функций финансово-экономической службы.</span></span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">5) Показатели эффективности финансовой службы.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 3px;">\r\n<td style="background-color: #ffffff; height: 3px; width: 14.3266%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; height: 3px; width: 70.6734%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 9px;">\r\n<td style="background-color: #f7f7f7; height: 9px; width: 14.3266%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>6.&nbsp;&nbsp; Бизнес-план – первый план компании. Структура&nbsp;и особенности инвест. проекта</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 9px; width: 70.6734%;">\r\n<p><span style="font-family: Pro;">1)&nbsp;Анализ рынка и маркетинговая стратегия. Выбор сегмента рынка. Анализ конкурентных преимуществ. Прогнозы объемов продаж - план продаж.</span></p>\r\n<p><span style="font-family: Pro;">2) Производственный план. Общий подход к организации производства</span></p>\r\n<p><span style="font-family: Pro;">3) Финансовый план. Бюджетирование, как составная часть финансового планирования</span></p>\r\n<p><span style="font-family: Pro;">4) Оценка рисков проекта.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 16px;">\r\n<td style="background-color: #ffffff; height: 16px; width: 14.3266%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; height: 16px; width: 70.6734%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 9px;">\r\n<td style="background-color: #f7f7f7; height: 9px; width: 14.3266%;">\r\n<p><span style="font-family: Pro;"><strong>7.&nbsp;</strong><strong>Бюджетирование – как часть системы управления предприятием.</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 9px; width: 70.6734%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1) Сущность бюджетного управления, бюджет в системе планов предприятия;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Постановка системы бюджетного управления:&nbsp; определение участников процесса бюджетного управления,&nbsp; определение центров финансовой ответственности, учета (ЦФО, ЦФУ);</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) Подходы к построению системы бюджетирования на предприятии;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4) Регламентация системы бюджетирования на предприятии. Бюджетная система:&nbsp; Система бюджетов на предприятии: Бюджет продаж, бюджет производства, бюджет накладных расходов, бюджет доходов и расходов, бюджет движения денежных средств.&nbsp; Взаимосвязь основных плановых и отчетных форм между собой. Контроль исполнения бюджетов – ключевая функция системы бюджетного управления.&nbsp; Анализ исполнения бюджета.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">&nbsp;-&nbsp;<em>Практические задания по разработке бюджетов, контроль и анализ. Причины невыполнения бюджетов.</em></span></p>\r\n<p><span style="font-family: Pro;"><em><span style="font-size: 10pt;">5)&nbsp;Практические примеры построения бюджетирования и управленческого в Excel.&nbsp;Создание сложных формул и выявление ошибок. Условия в формулах,&nbsp;сводные таблицы</span></em> </span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<hr />\r\n<p><strong><span style="font-family: Pro; font-size: 12pt;">Формат курса</span></strong></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">•&nbsp;Очное обучение. Продолжительность:&nbsp;6 месяцев, 2-3 раза в неделю, понедельник, среда, пятница с 18.30 до 21.30, суббота с 10 до 14.00</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">•&nbsp;Дистанционное обучение: видео-лекции, аттестационные работы</span></p>\r\n<hr />\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 12pt;">Акции и скидки:</span></strong> </span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit; color: inherit; font-size: 1rem;">•&nbsp;</span>Скидка 10%&nbsp;при оплате за 4 недели до обучения.&nbsp;&nbsp;</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit; color: inherit; font-size: 1rem;">•&nbsp;</span>Скидка 5%&nbsp;при оплате за 2 недели до обучения.</span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p style="text-align: center;"><span style="font-family: Pro;"><a onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<hr />\r\n<p><span style="color: #333333; font-family: Pro;"><span style="font-size: 16px;"><b>О нас</b></span></span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p><span style="font-family: Pro;"><iframe style="background-image: url(''img/iframe.png''); display: block; margin-left: auto; margin-right: auto;" src="https://www.youtube.com/embed/yx3VnN5bh2k" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture"></iframe></span></p>', '', 1, 26, '2017-07-13 13:29:33', 42, '', '2019-04-30 05:24:40', 42, 0, '0000-00-00 00:00:00', '2017-07-13 13:32:16', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 51, 2, 'Обучение директор по маркетингу', 'Курсы директор по маркетингу. Обучение по программе профессиональной переподготовки на диплом . Продолжительность 6 месяцев', 1, 4099, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(205, 402, 'Обучение маркетингу и интернет продвижению Дистанционно', 'обучение-маркетингу-и-интернет-продвижению-дистанционно', '<h1 style="text-align: center;">Эффективный маркетинг и интернет продвижение. Дистанционное обучение</h1>\r\n<p><strong><span style="font-family: arial, helvetica, sans-serif;">Формат обучения:</span></strong>&nbsp;видео-лекции с живых занятий, онлайн-консультации с преподавателями, практические задания с обратной связью.</p>\r\n<p style="text-align: center;"><strong><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">НА ОБУЧЕНИИ ВЫ НАУЧИТЕСЬ:</span></strong></p>\r\n<table class="stack" style="width: 100%; background-color: #ffffff;" border="0">\r\n<tbody>\r\n<tr style="height: 25px;">\r\n<td style="width: 48.6496%;">\r\n<ul>\r\n<li>\r\n<p><strong><span style="font-family: arial, helvetica, sans-serif;">Увеличивать&nbsp;продажи</span></strong>&nbsp;на 20-120% и более&nbsp;<span style="font-family: arial, helvetica, sans-serif;"><strong>при минимальных вложениях на интернет продвижение</strong></span></p>\r\n</li>\r\n</ul>\r\n</td>\r\n<td style="width: 48.3504%;">\r\n<ul>\r\n<li>Выявлять перспективные направления развития компании и выстраивать&nbsp;<span style="font-family: arial, helvetica, sans-serif;"><strong>эффективную маркетинговую стратегию</strong></span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr style="height: 25px;">\r\n<td style="width: 48.6496%;">\r\n<ul>\r\n<li>Определять&nbsp;настоящее&nbsp;<strong><span style="font-family: arial, helvetica, sans-serif;">Уникальное торговое предложение</span></strong>&nbsp;именно&nbsp;вашего продукта</li>\r\n</ul>\r\n</td>\r\n<td style="width: 48.3504%;">\r\n<ul>\r\n<li>Результативно использовать&nbsp;<span style="font-family: arial, helvetica, sans-serif;"><strong>бесплатные и малобюджетные способы продвижения</strong></span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr style="height: 25.0313px;">\r\n<td style="width: 48.6496%;">\r\n<ul>\r\n<li>Самостоятельно настраивать&nbsp;<span style="font-family: arial, helvetica, sans-serif;"><strong>эффективную рекламу в поисковых системах Яндекс и Google</strong></span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 48.3504%;">\r\n<ul>\r\n<li>Создавать и вести&nbsp;<span style="font-family: arial, helvetica, sans-serif;"><strong>"продающие" аккаунты</strong></span>&nbsp;и настраивать&nbsp;<span style="font-family: arial, helvetica, sans-serif;"><strong>таргетированную рекламу</strong></span>&nbsp;в соц. сетях</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr style="height: 23px;">\r\n<td style="width: 48.6496%;">\r\n<ul>\r\n<li>\r\n<p>Управлять&nbsp;<span style="font-family: arial, helvetica, sans-serif;"><strong>клиентоориентированностью&nbsp;</strong></span></p>\r\n</li>\r\n</ul>\r\n</td>\r\n<td style="width: 48.3504%;">\r\n<ul>\r\n<li>&nbsp;Проводить&nbsp;<span style="font-family: arial, helvetica, sans-serif;"><strong>маркетинговые исследования</strong></span>&nbsp;и грамотно использовать их результаты в продвижении&nbsp;</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p style="text-align: center;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><a onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<p style="text-align: center;"><iframe src="https://www.youtube.com/embed/D_xXNiGbTlA" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen" data-link="https://www.youtube.com/watch?v=D_xXNiGbTlA"></iframe></p>\r\n<p style="text-align: center;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>ПРОГРАММА КУРСА</strong></span></p>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 231px;">\r\n<td style="background-color: #f7f7f7; height: 231px; width: 20.5084%;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>1. Маркетинговый аудит положения компании на рынке</strong></span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 231px; width: 75.4916%;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">1) Как определить место компании на рынке?&nbsp;</span><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Ресурсы и способности вашей компании</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">2) Целевая аудитория и сегментирование клиентов. Определение основных сегментов аудитории.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">3) Позиционирование&nbsp;товара. Определяем конкурентные преимущества.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">4) Анализ конкурентов и бенчмаркетинг. Как использовать конкурентов в достижении собственных целей.&nbsp;&nbsp;SWOT- анализ.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">5) Инновационный маркетинг - как непрерывное совершенствование продуктов, услуг</span></p>\r\n<p><span style="font-size: 10pt;"><strong><span style="font-family: arial, helvetica, sans-serif;">Практика: проводим маркетинговый аудит положения компании на рынке и сегментируем клиентов.</span></strong> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 20.5084%; height: 14px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 75.4916%; height: 14px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"></span></td>\r\n</tr>\r\n<tr style="height: 137px;">\r\n<td style="background-color: #f7f7f7; height: 137px; width: 20.5084%;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>2.&nbsp;Маркетинговые исследования. Взаимосвязь стратегии компании с маркетинговыми исследованиями</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 137px; width: 75.4916%;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">1) Для чего именно нам нужно проведение исследований? Анализ и эффективные стратегии</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">2) Выбираем инструменты исследований: количественные и качественные исследования, полевые и кабинетные. Социологические и маркетинговые. Где искать данные, чтобы сэкономить на исследованиях и повысить их эффективность?</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">3) Использование маркетинговых исследований и маркетинговой информации в компании. Как сэкономить на исследованиях и включить в маркетинг каждого сотрудника компании?</span></p>\r\n<p><span style="font-size: 10pt;"><strong><span style="font-family: arial, helvetica, sans-serif;">Практика: проводим исследования и определяем маркетинговую стратегию&nbsp;</span></strong> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 20.5084%; height: 14px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 75.4916%; height: 14px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"></span></td>\r\n</tr>\r\n<tr style="height: 151px;">\r\n<td style="background-color: #f7f7f7; height: 151px; width: 20.5084%;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong><span lang="EN-US">3.&nbsp;Торговый маркетинг&nbsp;</span></strong> </span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 151px; width: 75.4916%;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">1) Категорийный менеджмент&nbsp;и прибыльность товаров. Принцип Паретто. АВС анализ и матрица БКГ</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">2) Принципы управления ассортиментной матрицей.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">3) УТП (уникальное торговое предложение). Как правильно определить свою уникальность? Какие признаки могут стать преимуществом вашего товара или услуги, а какие нет. &nbsp;</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">4) Ассортиментная политика компании. &nbsp;Как заработать на расширении ассортимента?&nbsp;</span></p>\r\n<p><span style="font-size: 10pt;"><strong><span style="font-family: arial, helvetica, sans-serif;">Практика: формируем&nbsp; ассортиментную матрицу</span></strong> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 20.5084%; height: 14px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 75.4916%; height: 14px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"></span></td>\r\n</tr>\r\n<tr style="height: 134px;">\r\n<td style="background-color: #f7f7f7; height: 134px; width: 20.5084%;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>4.&nbsp;Ценообразование и управление ассортиментом</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 134px; width: 75.4916%;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">1)&nbsp;Ценообразование и ценовая стратегия. Как сформировать стоимость товара при разных позициях на рынке?&nbsp;</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">2)&nbsp;Управление товарным ассортиментов на промышленных рынках и в сфере услуг</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Практика: Формируем&nbsp;УТП&nbsp;вашей компании с рыночным обоснованием&nbsp; и &nbsp;продвижением.</span></p>\r\n<p><span style="font-size: 10pt;"><strong><span style="font-family: arial, helvetica, sans-serif;">Практика: Определяем способы повышения клиентоориентированности вашей компании.</span></strong> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 20.5084%; height: 14px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 75.4916%; height: 14px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"></span></td>\r\n</tr>\r\n<tr style="height: 243px;">\r\n<td style="background-color: #f7f7f7; height: 243px; width: 20.5084%;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>5.&nbsp;Интегрированные маркетинговые коммуникации. Реклама и продвижение</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 243px; width: 75.4916%;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">1) Инструменты продвижения. Их возможности и недостатки. Современные технологии управления взаимоотношениями с клиентами.&nbsp;</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">2) Нейромаркетинг. Прямой маркетинг. &nbsp;Ивент-маркетинг. Public Relations.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">3) Понятия «бренд» и «брендинг». &nbsp;Чем бренд отличается от товара. Как создать бренд.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">4) Подходы к оценке эффективности рекламных кампаний.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">5) Элементы бренда: как управлять популярностью торговой марки.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">6) Определение точек контакта с существующими и потенциальными клиентами.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">7) CRM. &nbsp;Как выстраивать взаимоотношения с клиентами с помощью современных автоматизированных систем.<br /></span></p>\r\n<p><span style="font-size: 10pt;"><strong><span style="font-family: arial, helvetica, sans-serif;">Практика: считаем эффективность рекламных компаний</span></strong> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 20.5084%; height: 14px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 75.4916%; height: 14px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"></span></td>\r\n</tr>\r\n<tr style="height: 120px;">\r\n<td style="background-color: #f7f7f7; height: 120px; width: 20.5084%;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>6.&nbsp;Медиапланирование</strong></span></td>\r\n<td style="background-color: #f7f7f7; height: 120px; width: 75.4916%;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">1)&nbsp;Медиапланирование. Эффективная частота размещения рекламы по разным каналам продвижения.&nbsp;</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">2)&nbsp;Бюджетирование рекламных кампаний. &nbsp;Как эффективно распределять бюджеты, чтобы получать максимальный результат.&nbsp;</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">3)&nbsp;Подходы к оценке эффективности рекламных кампаний.</span></p>\r\n<p><span style="font-size: 10pt;"><strong><span style="font-family: arial, helvetica, sans-serif;">Практика: составляем медиа-план</span></strong> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 20.5084%; height: 14px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 75.4916%; height: 14px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"></span></td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 96%; background-color: #f7f7f7; height: 14px;" colspan="2"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>7.&nbsp;Формирование маркетингового плана вашей компании.</strong></span></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 14px;">\r\n<td style="width: 96%; height: 14px; text-align: center;" colspan="2"><span style="font-size: 10pt;"><strong><span style="font-family: arial, helvetica, sans-serif;">ИНТЕРНЕТ-МАРКЕТИНГ</span></strong> </span></td>\r\n</tr>\r\n<tr style="height: 10px;">\r\n<td style="background-color: #f7f7f7; height: 10px; width: 20.5084%;"><strong><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">8.&nbsp;SEO: базовые основы и практические инструменты</span></strong></td>\r\n<td style="background-color: #f7f7f7; height: 10px; width: 75.4916%;">\r\n<p style="text-align: justify;"><span style="font-size: 10pt;"><strong><span style="font-family: arial, helvetica, sans-serif;"><span style="color: #800000;">Что&nbsp; изучите:</span></span> </strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Алгоритмы работы поисковых систем. Анализ поисковых запросов. Факторы, влияющие на ранжирование сайтов</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Сбор семантического ядра и его кластеризация. Изучение сервиса Wordstat.</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Размещение контента на сайте: текстов, инфографика, заполнение метатегов, подбор изображений, видео.</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">SEO-копирайтинг: правила написания продающих текстов в соответствии с алгоритмами поисковых систем.</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Внутренняя перелинковка страниц. Схемы перелинковки.</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Внешняя оптимизация сайта. Подбор площадок для размещения ссылок.</span></li>\r\n</ol>\r\n<p><span style="font-size: 10pt; color: #800000;"><strong><span style="font-family: arial, helvetica, sans-serif;">Какие навыки получите:</span></strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Сбор семантического ядра, кластеризация ключевых фраз.</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Работа с сервисом Wordstat.</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Подготовка технических заданий на SEO-копирайтинг.</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Выбор подходящих площадок для внешней оптимизации.</span></li>\r\n</ol></td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="background-color: #ffffff; height: 14px; width: 20.5084%;">&nbsp;</td>\r\n<td style="background-color: #ffffff; height: 14px; width: 75.4916%;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 10px;">\r\n<td style="background-color: #f7f7f7; height: 10px; width: 20.5084%;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>9.&nbsp;</strong><strong>Контекстная реклама: основы размещения рекламы в Яндекс и&nbsp;</strong><strong>Google</strong></span></td>\r\n<td style="background-color: #f7f7f7; height: 10px; width: 75.4916%;">\r\n<p style="text-align: justify;"><span style="font-size: 10pt; color: #800000;"><strong><span style="font-family: arial, helvetica, sans-serif;">Что освоите:</span></strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Виды рекламных кампаний.</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Использование ключевых фраз: подбор подходящих, фильтрация минус-фраз.</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Создание рекламных кампаний в Яндекс Директ и Google Adwords: регистрация в личном кабинете, базовые настройки, создание рекламных объявлений.</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Изучение факторов, влияющих на стоимость клика.</span></li>\r\n</ol>\r\n<p><span style="font-size: 10pt; color: #800000;"><strong><span style="font-family: arial, helvetica, sans-serif;">Какие навыки&nbsp; получите:</span></strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Грамотный подбор ключевых фраз и составление эффективных объявлений.</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Настройка рекламной кампании в личном кабинете Яндекс Директ и Google Adwords.</span></li>\r\n</ol></td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="background-color: #ffffff; height: 13px; width: 20.5084%;">&nbsp;</td>\r\n<td style="background-color: #ffffff; height: 13px; width: 75.4916%;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 10px;">\r\n<td style="background-color: #f7f7f7; height: 10px; width: 20.5084%;"><strong><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><span lang="EN-US">10. Системы аналитики. Изучение Яндекс Метрики.</span></span></strong></td>\r\n<td style="background-color: #f7f7f7; height: 10px; width: 75.4916%;">\r\n<p><span style="font-size: 10pt; color: #800000;"><strong><span style="font-family: arial, helvetica, sans-serif;">Что&nbsp; проработаете:</span></strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Показатели, которые необходимо отслеживать.</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Регистрация в Яндекс Метрике, знакомство с личным кабинетом.</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Изучение отчетов в системе аналитики.</span></li>\r\n</ol>\r\n<p><span style="font-size: 10pt; color: #800000;"><strong><span style="font-family: arial, helvetica, sans-serif;">Какие&nbsp; навыки получите:</span></strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Понимание основных отчетов и показателей.</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Настройка целей системе аналитики.</span></li>\r\n</ol></td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="background-color: #ffffff; height: 13px; width: 20.5084%;">&nbsp;</td>\r\n<td style="background-color: #ffffff; height: 13px; width: 75.4916%;">&nbsp;&nbsp;</td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="background-color: #f7f7f7; height: 13px; width: 20.5084%;"><strong><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><span lang="EN-US">11.&nbsp;SMM. Работа в социальных сетях: Facebook, ВКонтакте, Instagram.</span></span></strong></td>\r\n<td style="background-color: #f7f7f7; height: 13px; width: 75.4916%;">\r\n<p><span style="font-size: 10pt; color: #800000;"><strong><span style="font-family: arial, helvetica, sans-serif;">Что изучите:</span></strong> </span></p>\r\n<ol>\r\n<li><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">Обзор возможностей социальных сетей.</span></li>\r\n<li><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">Стратегии позиционирования.</span></li>\r\n<li><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">Виды сообществ в каждой из социальных сетей.</span></li>\r\n<li><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">Формирование контент-плана.</span></li>\r\n<li><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">Знакомство с сервисами автопостинга (SMM Planner), сбора целевой аудитории (Церебро Таргет).</span></li>\r\n<li><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">Бесплатные методы продвижения.</span></li>\r\n<li><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">Запуск таргетированной рекламы в Facebook, ВКонтакте, Instagram.</span></li>\r\n</ol>\r\n<p><span style="font-size: 10pt; color: #800000;"><strong><span style="font-family: arial, helvetica, sans-serif;">Какие навыки&nbsp; получите:</span></strong> </span></p>\r\n<ol>\r\n<li><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">Создание сообщества для Вашего бизнеса.&nbsp;</span></li>\r\n<li><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">Работа в программах автопостинга и сбора целевой аудитории.</span></li>\r\n<li><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">Настройка таргетированной рекламы в каждой из социальных сетей: Facebook, ВКонтакте, Instagram.</span></li>\r\n</ol></td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="background-color: #ffffff; height: 13px; width: 20.5084%;">&nbsp;</td>\r\n<td style="background-color: #ffffff; height: 13px; width: 75.4916%;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="background-color: #f7f7f7; height: 13px; width: 20.5084%;"><strong><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">12.&nbsp;Продвижение видео-канала на You-Tube.</span></strong></td>\r\n<td style="background-color: #f7f7f7; height: 13px; width: 75.4916%;">\r\n<p><span style="font-size: 10pt; color: #800000;"><strong><span style="font-family: arial, helvetica, sans-serif;">Что&nbsp; рассмотрите:</span></strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Виды видео-контента и особенности его подготовки.</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Запуск видео-канала на You-Tube, базовые настройки.</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Разработка стратегии ведения канала.&nbsp;</span></li>\r\n</ol>\r\n<p><span style="font-size: 10pt; color: #800000;"><strong><span style="font-family: arial, helvetica, sans-serif;">Какие практические навыки:</span></strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Запуск видео-канала на You-Tube.</span></li>\r\n<li style="text-align: left;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Базовые настройки канала для эффективного продвижения.</span></li>\r\n</ol></td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="background-color: #ffffff; height: 13px; width: 20.5084%;">&nbsp;</td>\r\n<td style="background-color: #ffffff; height: 13px; width: 75.4916%;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="background-color: #f7f7f7; height: 13px; width: 20.5084%;"><strong><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">13.&nbsp;E-mail маркетинг: основы работы и запуск продающих рассылок.</span></strong></td>\r\n<td style="background-color: #f7f7f7; height: 13px; width: 75.4916%;">\r\n<p><span style="font-size: 10pt; color: #800000;"><strong><span style="font-family: arial, helvetica, sans-serif;">Что&nbsp; освоите:</span></strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Сбор базы подписчиков – основные инструменты и сервисы.</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Обзор основных инструментов для рассылок: плюсы и минусы.</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Типы рассылок и выбор эффективной стратегии.</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Создание цепочки писем и особенности формирования контента.</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Знакомство с сервисом для рассылок Send Pulse.</span></li>\r\n</ol>\r\n<p><span style="font-size: 10pt; color: #800000;"><strong><span style="font-family: arial, helvetica, sans-serif;">Какие навыки получите:</span></strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Создание продающего электронного письма.</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Настройка сервиса Send Pulse.</span></li>\r\n</ol></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span style="font-family: arial, helvetica, sans-serif;">Дистанционные курсы маркетинга и интернет-продвижения&nbsp;рассчитаны на&nbsp;8 недель. За это время Вы изучите маркетинговый аудит, позиционирование, инструменты продвижения, оценку эффективности.</span></p>\r\n<table style="width: 99.7868%;">\r\n<tbody>\r\n<tr style="height: 17px;">\r\n<td style="width: 44%; height: 17px; text-align: center;" colspan="2">\r\n<p style="text-align: center;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif; color: #800000;"><strong>ВЕДУЩИЕ КУРСА:</strong></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 17px;">\r\n<td style="width: 10%; height: 741.813px; background-color: #f5f5f5; text-align: center;" rowspan="2">\r\n<p>&nbsp;</p>\r\n<p><img style="display: block; margin-left: auto; margin-right: auto;" src="images/Ananiena_NA.JPG" alt="маркетинг дистанционно" width="87" height="114" /></p>\r\n</td>\r\n<td style="width: 34%; height: 17px; background-color: #f5f5f5; text-align: center;">\r\n<p style="text-align: left;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif; color: #800000;"><strong>АНАНЬИНА НАТАЛЬЯ АЛЕКСАНДРОВНА</strong></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 724.813px;">\r\n<td style="background-color: #f5f5f5; width: 34%; height: 724.813px;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Эксперт-практик в области&nbsp;маркетинга.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">- &nbsp;Опыт работы&nbsp;в маркетинге&nbsp;<strong>более 15 лет</strong>.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">-&nbsp; Опыт работы преподавателем&nbsp;<strong>более 10&nbsp;лет</strong>.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"></span><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>Высшее образование:</strong></span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><span lang="EN-US">2017 г. — OU Business School LINK (</span>МИМ ЛИНК<span lang="EN-US">)</span><span lang="EN-US">,&nbsp;</span>МВА</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">2011 г. — OU Business School LINK (МИМ ЛИНК), корпоративный менеджер + стратегия (мини-МВА), профессиональный диплом в области менеджмента Великобритании</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">2003 г. — Государственный университет управления, ФДО, Российско-голландская программа «Маркетинговое образование в России» (РИМА-А)</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">2000 г. — Уральский государственный экономический университет (СИНХ), Менеджмент и МЭО, Менеджер</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>Дополнительное образование:</strong></span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">2014 г. -&nbsp;Управление инновациями на предприятии&nbsp;</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">2012 г. -&nbsp;Создание и развитие бизнеса в Интернет</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">2009 г. -&nbsp;Маркетинг и управление качеством</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">2008-2009 гг. -&nbsp;Система внутрифирменного бюджетирования<br /></span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">2004 г. -&nbsp;Эффективная реклама</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">2003 г. - Анатомия бренда</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>Трудовая деятельность:</strong></span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">2014 - 2015 гг. - руководитель корпоративных проектов,&nbsp;ООО «Арсенал Успеха»,&nbsp;промышленный&nbsp;&nbsp; и управленческий консалтинг</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">2012 г. - по настоящее время - ведущий преподаватель ЕАСИ</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">2008 - 2013 гг. -&nbsp;консультант по совершенствованию коммерческой деятельности и инновациям, бизнес-тренер, "Успех и бизнес", маркетинговый и управленческий консалтинг</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">2010 - 2011 гг. - директор по маркетингу и продажам, ООО "Роспан"</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">2008 - 2009 гг. - директор по маркетингу, "Хладокомбинат №3"</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">2005 г. - 2008 гг. - руководитель департамента открытых проектов, ООО "Центр Оргпром"</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 17px;">\r\n<td style="width: 44%; height: 17px; background-color: #ffffff; text-align: center;" colspan="2">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 17px;">\r\n<td style="width: 10%; height: 40px; background-color: #f5f5f5; text-align: center;" rowspan="2">\r\n<p>&nbsp;</p>\r\n<p><img style="display: block; margin-left: auto; margin-right: auto;" src="images/Lopatin_VV.jpg" alt="обучение маркетингу дистанционно" width="84" height="107" /></p>\r\n</td>\r\n<td style="width: 34%; height: 17px; background-color: #f5f5f5; text-align: center;">\r\n<p style="text-align: left;"><span style="color: #800000;"><strong><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">ЛОПАТИН ВИТАЛИЙ ВЯЧЕСЛАВОВИЧ</span></strong> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 23px;">\r\n<td style="width: 34%; height: 23px; background-color: #f5f5f5; text-align: center;">\r\n<p style="text-align: left;"><strong><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">Специалист в области интернет-коммуникаций&nbsp;</span></strong></p>\r\n<p style="text-align: left;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">-&nbsp;<strong>Более 8 лет</strong>&nbsp;опыта работы в интернет-маркетинге и IT-технологий, реализовано более 300 успешных проектов по поисковой оптимизации, контекстной рекламе и smm-продвижению.</span></p>\r\n<p style="text-align: left;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">-&nbsp;<strong>Более 10 лет</strong>&nbsp;опыта работы в маркетинге.</span></p>\r\n<p style="text-align: left;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">-&nbsp;<strong>Более 7&nbsp;лет</strong>&nbsp;- руководитель компании, предоставляющей услуги в сфере интернет-маркетинга и IT.</span></p>\r\n<p style="text-align: left;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>В числе клиентов:</strong>&nbsp;Уральский банк реконструкции и развития, West Call, Региональная трубная компания, Гардиан, Урал Шталь, служба доставки "Пицца Сан", группа компаний "Элеком", УралПак, строительная компания "АСК-Строй", дачный поселок "Красная поляна", ДИА-Строй.</span></p>\r\n<p style="text-align: left;">&nbsp;</p>\r\n<p style="text-align: left;"><strong><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">Высшее образование:</span></strong></p>\r\n<p style="text-align: left;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">2005 г. - УГТУ-УПИ, "Экономика и управление предприятием"</span></p>\r\n<p style="text-align: left;"><strong><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">Дополнительное образование:&nbsp;</span></strong></p>\r\n<p style="text-align: left;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">2008 - 2016 гг. - вебинары и семинары по продвижению Яндекс Директ,&nbsp;Google AdWords и другие</span></p>\r\n<p style="text-align: left;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">2009 г. - Повышение квалификации&nbsp;«HTML программированию»</span></p>\r\n<p style="text-align: left;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">2008&nbsp;г. - Тренинг «Малобюджетное продвижение товаров и услуг»&nbsp;</span></p>\r\n<p style="text-align: left;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">2007 г. - Тренинг «Лидер продаж»</span></p>\r\n<p style="text-align: left;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">2006 г. - Повышение квалификации&nbsp;«Маркетинг и организационно-у<wbr />правленческое планирование»</span></p>\r\n<p style="text-align: left;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"></span></p>\r\n<p style="text-align: left;"><strong><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">Трудовая деятельность:</span></strong></p>\r\n<p style="text-align: left;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">С&nbsp;2009 г. по настоящее время - руководитель компании&nbsp;"Апдейт", специализирующейся на интернет-продвижении и it-технологиях.</span></p>\r\n<p style="text-align: left;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">2008 - 2009 гг. - специалист по маркетингу ООО “Стройгеотехника<wbr />”. Реклама и маркетинг в сегменте B2B.</span></p>\r\n<p style="text-align: left;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">2006 - 2008 гг. - руководитель отдела маркетинга ГП “ПромСредМаш”. Маркетинговые исследования, реклама, разработка стратегии и планирование маркетинговой деятельности машиностроительн<wbr />ых предприятий, входящих в группу.</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>', '', 1, 26, '2017-10-25 07:48:14', 42, '', '2019-04-16 04:57:27', 42, 42, '2019-04-24 11:37:50', '2017-10-25 07:48:14', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 22, 3, 'курсы маркетинга дистанционно, онлайн обучение маркетингу', 'Дистанционные курсы маркетинга и интернет-продвижения за 7 недель. Стоимость 19 000 руб.', 1, 2533, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(109, 186, 'Диплом о переподготовке "Специалист по кадрам"', 'диплом-о-переподготовке-«трудовое-право-и-кадровое-делопроизводство-на-предприятие»-квалификация-«инспектор-по-кадрам»', '<h1 style="text-align: center;"><span style="font-family: Pro;">Переподготовка на диплом по программе «Трудовое право и кадровое делопроизводство на предприятии»</span></h1>\r\n<p><span style="font-family: Pro;"><strong>Целевая аудитория:&nbsp;</strong>специалист по кадрам, специалист по трудовому праву, менеджер по персоналу,&nbsp; руководитель по управлению персоналом.</span></p>\r\n<p><span style="font-family: Pro;"><strong>Ведущие:&nbsp;</strong> <a href="index.php?option=com_content&amp;view=article&amp;id=106&amp;catid=2&amp;Itemid=112">Шарунова Ирина Юрьевна&nbsp;</a>- руководитель кадровой структуры компании "Спецгазпроект", аудитор по трудовым вопросам</span></p>\r\n<p>&nbsp;</p>\r\n<p style="text-align: center;"><span style="font-family: Pro;"><a onclick="yaCounter15669946.reachGoal (''ostavitzayavky''); return true;" href="#zakaz" rel="alternate">ОТПРАВИТЬ ЗАЯВКУ</a></span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;"><span style="line-height: 15.808px;">Выдается диплом о переподготовке&nbsp;</span></span> </span><span style="background-color: inherit; font-size: 13.3333px;"><span style="font-family: Pro;">с присвоением квалификации&nbsp; "Специалист по кадрам" или "Специалист по управлению персоналом"</span></span><span style="font-size: 10pt;"><span style="line-height: 15.808px;"></span></span></p>\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;"><span style="line-height: 15.808px;"><a href="#"><img src="images/shablon_diploma.jpg" alt="обучение специалист по кадрам" width="30%" height="186" /></a>&nbsp;<a href="#"><img src="images/shablon_diploma_vnutri.jpg" alt="курсы специалист по кадрам" width="30%" height="186" /></a>&nbsp;<a href="#"><img src="images/diplom_kadrovika.jpg" alt="диплом специалиста по кадрам" width="30%" height="186" /></a></span></span> </strong> </span></p>\r\n<hr />\r\n<p style="text-align: left;"><strong><span style="font-family: Pro; font-size: 12pt;">Фрагмент обучения</span></strong></p>\r\n<p>&nbsp;</p>\r\n<p style="text-align: center;"><span style="font-family: Pro;"><iframe src="https://www.youtube.com/embed/l0hNlRUB4Ew" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen" data-link="https://www.youtube.com/watch?v=l0hNlRUB4Ew"></iframe></span></p>\r\n<hr />\r\n<p style="text-align: left;"><span style="font-family: Pro; font-size: 12pt;"><strong>Программа курса:</strong></span></p>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 337px; background-color: #f5f5f5;">\r\n<td style="width: 26%; height: 337px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">1. Прием на работу. Установление трудовых правоотношений</span></strong> </span></p>\r\n</td>\r\n<td style="width: 70%; height: 337px; text-align: justify;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong>&nbsp;Поэтапная процедура оформления приема сотрудника на работу. Типичные ошибки при трудоустройстве.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong>&nbsp;Штатное расписание и штатная расстановка,&nbsp; назначение, отличия, корректность заполнения?</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>3)</strong>&nbsp;Трудовой договор - содержание, порядок и сроки заключения.&nbsp; Перечень документов, предъявляемые работником в целях заключения трудового договора. Совместители. Испытательный срок.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>4)</strong>&nbsp;Гражданско-правовой договор. Отличие от трудового договора и документальное обеспечение.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>5)</strong>&nbsp;Особенности оформления договоров о материальной ответственности работников. Обязательность&nbsp; их заключения.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>6)</strong>&nbsp;Срочные и бессрочные договора. Сроки трудовых договоров. Ограничения заключения «срочных» договоров. Особенности срока трудовых отношений с совместителями. Особенности оформления трудовых договоров с руководителями.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>7)</strong>&nbsp;Документооборот приема. Особенности оформления документов с генеральными директорами нескольких компаний. Особенности оформления на работу иностранцев, инвалидов, несовершеннолетних. Кому нельзя отказать в приеме на работу.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>8)</strong>&nbsp;Применение профстандартов на практике. Этапы внедрения профстандартов в организации.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro; font-size: 10pt;"><em>- Практические задания: оформление на работу, разработка трудового договора.</em></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 26%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 70%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 143px; background-color: #f5f5f5;">\r\n<td style="width: 26%; height: 143px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">2. Функции кадровой службы организации. Ключевые нормативные и правовые акты (положения), регулирующие трудовые правоотношения</span></strong> </span></p>\r\n</td>\r\n<td style="width: 70%; height: 143px;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong>&nbsp;Правила внутреннего трудового распорядка как основной регламент.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong>&nbsp;Положение об охране труда и технике безопасности.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>3)</strong>&nbsp;Положение о работе с персональными данными.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>4)</strong>&nbsp;Должностные инструкции работников - разработка корректных инструкций.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><em>- Практические задания по разработке должностных инструкций, правил и положений.</em></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 26%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 70%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 26%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>3. Изменение трудового договора</strong></span></p>\r\n</td>\r\n<td style="width: 70%; height: 15px;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong>&nbsp;Перевод и перемещение: в чем отличие перевода от перемещения.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong>&nbsp;Схематичное документирование переводов.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>3)</strong>&nbsp;Предназначение: докладных записок, служебных записок; заявлений; дополнительного соглашения; приказов).</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 26%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 70%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 26%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">4. Правовое регулирование рабочего времени, режима рабочего времени. Отпуска</span></strong> </span></p>\r\n</td>\r\n<td style="width: 70%; height: 15px;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong>&nbsp;Рабочее время и время отдыха (нормальная и сокращенная продолжительность рабочего времени, неполное рабочее время; сверхурочная работа; ненормированный рабочий день; суммированный учет рабочего времени).</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong>&nbsp;Табель учета и график рабочего времени,&nbsp; в чем разница?&nbsp;</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>3)</strong>&nbsp;Отпуска. Виды, оформление графика, приказов, заявлений, отзывов из отпуска. Льготные категории по времени предоставления отпуска. Особенности оформления отпусков льготным категориям работников. Спорные вопросы предоставления отпуска новым сотрудникам. Больничный во время отпуска. Перенос отпуска. Какие части и каких отпусков можно получить деньгами. Особенности расчета отпускных у работников, которые часто берут «отпуск за свой счет». Учебные отпуска.&nbsp;</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>4)</strong>&nbsp;Несчастный случай на производстве. Что должен знать кадровик</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><em>- Практические задания по расчету графиков, отпусков и больничных &nbsp; Служебная командировка.</em></span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>5)</strong>&nbsp;Порядок направления в служебную командировку - докладная записка, служебное задание и отчет о служебном задании; - приказ о направлении в командировку; - командировочное удостоверение; - ведение журналов учета.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>6)</strong>&nbsp;Какие возмещаются расходы работнику; подтверждающие документы; сроки предоставления документов и отчетность.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>7)</strong>&nbsp;Положение о служебных командировках и служебных поездках.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15.3438px;">\r\n<td style="width: 26%; height: 15.3438px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 70%; height: 15.3438px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 26%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">5. Система нормирования - технология управления производительностью труда</span></strong> </span></p>\r\n</td>\r\n<td style="width: 70%; height: 15px; text-align: justify;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong>&nbsp;Структура системы нормирования на предприятии. Документы, регламентирующие процесс нормирования.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong>&nbsp;Классификация норм труда. Нормативы затрат труда и методы нормирования. Нормируемая величина денежных средств, направляемых на оплату труда.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>3)</strong>&nbsp;Фотография рабочего дня и хронометраж – основные инструменты каждого руководителя.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>4)</strong>&nbsp;Потери рабочего времени. По организационно-техническим причинам, связанные с нарушением трудовой дисциплины.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>5)</strong>&nbsp;Особенности ненормированного труда:</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">- Ненормированный труд и его свойства.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">- Ненормированный рабочий день. Цель установления и основание для использования. Порядок компенсации. Ненормированный рабочий день и сверхурочная работа.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro; font-size: 10pt;"><strong>6)</strong>&nbsp;Заработная плата при сменном режиме труда. Особенности суммированного учета:</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro; font-size: 10pt;">- Особенность повременной оплаты при сменном режиме труда.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro; font-size: 10pt;">- Заработная плата за согласованную продолжительность работы в смене и ее превышение над федеральной нормой рабочего времени.&nbsp;</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro; font-size: 10pt;">- Вахта. Продолжительность вахты. Междусменный и междувахтовый отдых.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 26%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 70%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 26%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>6. Правовое поле системы вознаграждений в организации</strong></span></p>\r\n</td>\r\n<td style="width: 70%; height: 15px;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong>&nbsp;Постоянная и переменная часть. Взаимосвязь штатного расписания, норм труда и должностных обязанностей. Принципы и ограничения при необходимости изменений.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong>&nbsp;Условия оплаты труда, включаемые в трудовой договор. Положение об оплате труда, премировании.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>3)</strong>&nbsp;Поощрение работников. Дисциплинарные взыскания.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">- Поощрение работников - основание; - поэтапная инструкция и документирование поощрения (формы представления, приказа).</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">- Дисциплинарные взыскания - виды в соответствии с действующим законодательством; - вопросы законности наложения штрафа на работников.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 26%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 70%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 26%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">7. Ответственность работодателя (кадровика, руководителя отдела персонала, бухгалтера, генерального директора) и трудовые споры</span></strong> </span></p>\r\n</td>\r\n<td style="width: 70%; height: 15px; text-align: justify;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong>&nbsp;Дисциплинарная ответственность. Особенности оформления дисциплинарных взысканий. Документы, наделяющие полномочиями расследовать факты нарушения дисциплины.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong>&nbsp;Материальная ответственность. Судебная практика взыскания ущерба в полном объеме. Взыскание затрат на дорогостоящее обучение.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>3)</strong>&nbsp;Административная и уголовная ответственность. Проверки Государственной инспекции труда. Минимизация рисков обращения работников в надзорно-контрольные органы.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>4)</strong>&nbsp;Предупреждение конфликтов, приводящих к обращениям граждан в надзорно-контрольные органы. Этика поведения специалистов HR при спорных и конфликтных ситуациях.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro; font-size: 10pt;">&nbsp;<em>- Обзор судебной практики по вопросам расторжения трудовых договоров по инициативе работодателя.</em></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 26%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 70%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 26%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">8. Аттестация работников</span></strong> </span></p>\r\n</td>\r\n<td style="width: 70%; height: 15px;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong>&nbsp;Аттестация – сходство и различие с оценкой. Цели и задачи аттестации.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong>&nbsp;Правовые основы проведения аттестационных мероприятий, алгоритм проведения аттестационных мероприятий.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>3)</strong>&nbsp;Сроки проведения, график. Подготовка к аттестации. Мероприятия, документы, характеристика аттестуемого.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>4)</strong>&nbsp;Регламентация аттестации работников внутренними нормативными документами компании. Разработка «Положения об аттестации».</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>5)</strong>&nbsp;Аттестационная комиссия, состав, обязанности, протокол, работа комиссии, вынесение решения.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>6)</strong>&nbsp;Выводы аттестационной комиссии, обжалование решения аттестационной комиссии, лица, не проходящие аттестацию.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>7)</strong>&nbsp;Оценка деловых и личных качеств работника, правовые последствия аттестации.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>8)</strong>&nbsp;Изменение условий трудового договора по итогам аттестации (перевод,&nbsp;перемещение, изменение оплаты труда и т.д.).</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>9)</strong>&nbsp;Увольнение по итогам аттестации, ответственность работодателя за нарушение прав работника при проведении аттестации.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 26%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 70%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 26%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>9. Прекращение трудовых правоотношений, документирование. Сокращение</strong></span></p>\r\n</td>\r\n<td style="width: 70%; height: 15px;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong>&nbsp;Прекращение трудового договора по - инициативе работника; - инициативе работодателя; - по соглашению сторон; - обстоятельствам, не зависящим от воли сторон.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong>&nbsp;Процедура&nbsp; увольнения в зависимости от оснований прекращения трудового договора.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>3)</strong>&nbsp;Сокращение численности и сокращение штата:&nbsp; - процедура уведомления работников о сокращении; - процедуры предложения вакансий; - гарантии работника при увольнении по сокращению численности или штата работников.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 26%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 70%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 26%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>10. Трудовая книжка. Организация кадрового делопроизводства</strong></span></p>\r\n</td>\r\n<td style="width: 70%; height: 15px;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong>&nbsp;Трудовая книжка работника: учет, ведение, хранение.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong>&nbsp;Личная карточка работника: - обязательность заполнения&nbsp;&nbsp; - внесение записей в период работы и при увольнении - порядок учета и хранения.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>3)</strong>&nbsp;Личное дело работника.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><em>- Практические задания заполнение трудовой книжки и личного дела.</em></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 26%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 70%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 26%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>11. Текущее и архивное хранение кадровой документации</strong></span></p>\r\n</td>\r\n<td style="width: 70%; height: 15px;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong>&nbsp;Требования к формированию дел в делопроизводстве организации и подготовка передачи дел в ведомственный архив.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong>&nbsp;Особенности сроков хранения дел по личному составу организаций.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>3)</strong>&nbsp;Требования к заполнению формы номенклатуры дел.&nbsp;</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>4)</strong>&nbsp;Порядок составления и утверждения номенклатуры дел организации.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 26%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 70%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 26%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">12. Воинский учет</span></strong> </span></p>\r\n</td>\r\n<td style="width: 70%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong>&nbsp;Положение о воинском учете.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong>&nbsp;Картотека личных дел, обязательность предоставления данных.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro; font-size: 10pt;"><em>- Заполнение обязательной отчетности по воинскому учету.</em></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 26%; height: 15px;"><span style="font-family: Pro; font-size: 10pt;"><em>&nbsp;</em></span></td>\r\n<td style="width: 70%; height: 15px;"><span style="font-family: Pro; font-size: 10pt;"><em>&nbsp;</em></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 26%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">13. Работа в программе 1С: Зарплата и управление персоналом 8</span></strong> </span></p>\r\n</td>\r\n<td style="width: 70%; height: 15px;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong>&nbsp;Начальная настройка программы. Начальное заполнение справочных данных.Заполнение основных реквизитов организации.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">- Ввод сведений об организации.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">- Заполнение основных справочников.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong>&nbsp;Штатное расписание. Ввод кадровой информации.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">- Формирование и изменение штатного расписания предприятия.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">- Карточки физических лицах, основные данные.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">- Прием на работу сотрудника. Перевод. Увольнение.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>3)</strong>&nbsp;Ввод больничного листа. Оформление отпуска.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">- Ввод больничного листа. Проверка больничного листа, что необходимо заполнять кадровику.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">- Оформление отпуска: очередной, без сохранения оплаты труда,&nbsp; дополнительный.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">- Учет рабочего времени. График, табель рабочего&nbsp; времени.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">- Формирование отчетов. Списочная численность.&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 26%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">14. Проектная работа</span></strong> </span></p>\r\n</td>\r\n<td style="width: 70%; height: 15px;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong>Разработка и совершенствование системы кадрового документооборота на&nbsp; предприятии</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span style="font-size: 12pt;"><strong><span style="font-family: Pro;">Формат:</span></strong> </span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">•&nbsp;<strong>Очное обучение. </strong>Продолжительность:<strong>&nbsp;</strong>4 недели&nbsp;- понедельник и среда &nbsp;с 18.30&nbsp; до 21.30, суббота с 10.00 до 14.00 +&nbsp;5 недель заочно (проектная работа).&nbsp;&nbsp;Методы проведения:&nbsp;мини-лекции, групповые дискуссии, разбор конкретных ситуаций, практические упражнения по отработке навыков.&nbsp;Количество&nbsp; человек в группе ограничено! до 12 слушателей.</span></p>\r\n<p><span style="font-family: Pro;">&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;•&nbsp;<strong>Дистанционное обучение:</strong>&nbsp;видео-лекции, аттестационные работы с обратной связью от преподавателя</span></p>\r\n<hr />\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 12pt;">Акции и скидки:</span></strong> </span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit; color: inherit; font-size: 1rem;">•&nbsp;</span>Скидка 10%&nbsp;при оплате за 3 недели до обучения.&nbsp;&nbsp;</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit; color: inherit; font-size: 1rem;">•&nbsp;</span>Скидка 5%&nbsp;при оплате за 2 недели до обучения.</span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p style="text-align: center;"><span style="font-family: Pro;"><a onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<hr />\r\n<p>&nbsp;</p>\r\n<table>\r\n<tbody>\r\n<tr>\r\n<td style="border-color: #ffffff; background-color: #f5f5f5; text-align: center; vertical-align: middle;">\r\n<p><strong style="color: inherit; font-family: Pro; font-size: 16px;">&nbsp; &nbsp; &nbsp; &nbsp;Ведущий</strong>&nbsp;</p>\r\n</td>\r\n<td style="border-color: #ffffff; background-color: #f5f5f5; text-align: center;">\r\n<p><span style="font-family: Pro;"><span style="font-size: 16px;"><b>Шарунова Ирина Юрьевна</b></span></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="border-color: #ffffff; background-color: #f5f5f5; text-align: center; vertical-align: middle;"><img src="images/ззззз.PNG" alt="обучение кадровиков и специалистов по кадрам" width="95" height="122" /></td>\r\n<td style="border-color: #ffffff; background-color: #f5f5f5;">\r\n<p><strong><span style="font-family: Pro;">Специалист по кадрам. Преподаватель-практик</span></strong><span style="color: #351e07; font-family: arial; background-color: #fefefe;">.</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">- Руководитель-аудитор кадрового и юридического отдела "СпецГазПроект"</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">- Более 10 лет опыта работы по специализации.</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">- Более 8 лет успешной работы преподавателем.</span></p>\r\n<p><strong><span style="font-family: Pro;">Образование высшее:</span></strong></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">2002-2008 гг. УГПУ,&nbsp; Учитель права</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">2008-2011 гг. УРГЮА, Правовое обеспечение экономической деятельности предприятия, юрист</span></p>\r\n<p><strong><span style="font-family: Pro;">Дополнительное образование:</span></strong></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">2016 г. Педагогика и методика обучения, повышение квалификации&nbsp;</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">2015 г. Повышение квалификации "Навыки активного обучения слушателей".</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">2014 г. Курсы&nbsp; 1: С Зарплата и управление персоналом</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">2013 г. Повышение&nbsp; квалификации&nbsp; "Трудовые споры". Москва</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<hr />\r\n<p><span style="font-family: Pro;"><span style="color: #333333;"><span style="font-size: 16px;"><b>О нас</b></span></span> </span></p>\r\n<p>&nbsp;</p>\r\n<p><iframe style="background-image: url(''img/iframe.png''); display: block; margin-left: auto; margin-right: auto;" src="https://www.youtube.com/embed/yx3VnN5bh2k" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture"></iframe></p>', '', 1, 25, '2016-04-04 07:55:49', 42, '', '2019-04-30 05:13:04', 42, 0, '0000-00-00 00:00:00', '2016-04-04 07:55:49', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 84, 0, 'Диплом специалист по кадрам, диплом кадровик, диплом по кадрам', 'Диплом специалиста по кадрам УЦ ЭмМенеджмент. Продолжительность  260 часов. Стоимость 27. 000 руб.', 1, 14417, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(106, 183, 'Шарунова Ирина Юрьевна трудовое право', 'шарунова-ирина-юрьевна-трудовое-право', '<h1 style="text-align: center;"><span style="font-family: Pro;">Шарунова Ирина Юрьевна</span></h1>\r\n<table style="width: 93.177%;">\r\n<tbody>\r\n<tr style="height: 82.4375px;">\r\n<td style="height: 82.4375px; width: 10.2294%;"><span style="font-family: Pro;"><img src="images/Sharunova_IU.jpg" alt="преподаватель по кадрову делопроизводству" width="97" height="128" /></span></td>\r\n<td style="height: 82.4375px; width: 75.7706%;">\r\n<p><span style="font-family: Pro;">Практическая деятельность: руководитель-аудитор кадрового и юридического отдела "СпецГазПроект"</span></p>\r\n<p><span style="font-family: Pro;"><strong>Более 10&nbsp;лет</strong> опыта работы по специализации.</span></p>\r\n<p><span style="font-family: Pro;"><strong>Более 7&nbsp;лет</strong>&nbsp;успешной работы преподавателем.</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span style="font-family: Pro; color: #800000;"><strong>Разработаны и проведены программы:</strong></span></p>\r\n<ul>\r\n<li><span style="font-family: Pro;">Трудовое право и кадровое делопроизводство</span></li>\r\n<li><span style="font-family: Pro;">Новации в трудовом праве</span></li>\r\n<li><span style="font-family: Pro;">Аудит кадрового делопроизводства</span></li>\r\n<li><span style="font-family: Pro;">Гражданское, процессуальное законодательство</span></li>\r\n<li><span style="font-family: Pro;">Программы повышения квалификации для Специалистов отдела кадров</span></li>\r\n<li><span style="font-family: Pro;">Проведение аудита кадрового делопроизводства</span></li>\r\n<li><span style="font-family: Pro;">Кадровый менеджмент</span></li>\r\n<li><span style="font-family: Pro;">Практика трудовых споров</span></li>\r\n</ul>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p><span style="color: #800000; font-family: Pro;"><strong>Образование высшее:</strong></span></p>\r\n<p><span style="font-family: Pro;">2002-2008 гг. УГПУ, &nbsp;Учитель права</span></p>\r\n<p><span style="font-family: Pro;">2008-2011 гг. УРГЮА, Правовое обеспечение экономической деятельности предприятия, юрист</span></p>\r\n<p><span style="color: #800000; font-family: Pro;"><strong>Дополнительное образование:</strong></span></p>\r\n<ul>\r\n<li><span style="font-family: Pro;">2016 г. Педагогика и методика обучения, повышение квалификации г. Екатеринбург</span></li>\r\n<li><span style="font-family: Pro;">2015 г. Повышение квалификации "Навыки активного обучения слушателей". Екатеринбург</span></li>\r\n<li><span style="font-family: Pro;">2014 г. Курсы&nbsp; 1: С Зарплата и управление персоналом</span></li>\r\n<li><span style="font-family: Pro;">2013 г. Повышение&nbsp; квалификации&nbsp; "Трудовые споры". Москва</span></li>\r\n<li><span style="font-family: Pro;">2009 - 2015 гг. - семинары &nbsp;по изменениям&nbsp; &nbsp;в трудовом законодательстве". Екатеринбург</span></li>\r\n</ul>', '', 1, 25, '2015-12-01 10:11:06', 42, '', '2019-04-26 09:56:20', 42, 0, '0000-00-00 00:00:00', '2015-12-01 10:11:06', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 32, 1, '', '', 1, 9350, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(118, 201, 'МВА обучение. Управление бизнес - процессами', 'мва-обучение-управление-бизнес-процессами', '<h1 style="text-align: center;"><span style="font-family: Pro;">Обучение менеджменту предприятия {city_d}. Управление бизнес -&nbsp;процессами организации. Программа МВА&nbsp;</span></h1>\r\n<p style="text-align: left;"><span style="font-family: Pro;"><strong>Целевая аудитория</strong><span style="font-size: 10pt;"><strong>:&nbsp;</strong>специалисты и руководители подразделений и организаций, менеджеры по развитию, предприниматели</span></span></p>\r\n<p><span style="margin: 0px; padding: 0px; font-family: Pro;"><strong style="margin: 0px; padding: 0px;">Ведущие:</strong></span></p>\r\n<p><span style="font-family: Pro;"><!-- noindex --></span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><a href="http://xn--d1ababe6aaeff9c5g.xn--p1ai/obrazovanie/%D0%BC%D0%B5%D0%BD%D0%B5%D0%B4%D0%B6%D0%BC%D0%B5%D0%BD%D1%82/210-%D0%B1%D0%B8%D0%B7%D0%BD%D0%B5%D1%81-%D1%82%D1%80%D0%B5%D0%BD%D0%B5%D1%80-%D0%BC%D0%B0%D0%BA%D0%B0%D1%80%D0%BE%D0%B2%D0%B0-%D1%8E%D0%BB%D0%B8%D1%8F-%D0%BE%D0%BB%D0%B5%D0%B3%D0%BE%D0%B2%D0%BD%D0%B0" rel="nofollow">Макарова Юлия Олеговна</a> -&nbsp;тренер по стратегическому развитию, управленческим компетенциям, продажам и переговорам</span><br /><span style="font-size: 10pt; font-family: Pro;"><a href="index.php?option=com_content&amp;view=article&amp;id=175&amp;catid=26" rel="nofollow">Ананьина Наталья Александровна</a> -&nbsp;специалист по разработке маркетинговых стратегий, директор по маркетингу</span><br /><span style="font-size: 10pt; font-family: Pro;"><a href="http://xn--d1ababe6aaeff9c5g.xn--p1ai/2-uncategorised/53-biznes-trener-nasonova-nadezhda-yurevna" rel="nofollow">Насонова Надежда Юрьевна&nbsp;</a>- финансовый директор, специалист в области финансового менеджмента</span><br /><span style="font-size: 10pt; font-family: Pro;"><a href="http://xn--d1ababe6aaeff9c5g.xn--p1ai/2-uncategorised/71-trener-putilova-marina" rel="nofollow">Путилова Марина Владимировна</a>&nbsp;- тренер, руководитель службы управления персоналом &nbsp;</span></p>\r\n<p><span style="font-family: Pro;"><!--/ noindex --></span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro;"><strong>Модули обучения:</strong><span style="font-size: 10pt;"><strong><br /></strong></span>1. Стратегический и организационный менеджмент</span><br /><span style="font-family: Pro;">2. Маркетинг и продвижение</span><br /><span style="font-family: Pro;">3. Управление продажами</span><br /><span style="font-family: Pro;">4. Управление персоналом</span><br /><span style="font-family: Pro;">5. Финансовый менеджмент</span></p>\r\n<p style="text-align: center;"><span style="font-family: Pro;"><a onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<p>&nbsp;</p>\r\n<p><a href="#"><img src="images/slider/shablon_diploma.jpg" alt="управление бизнес процессами mba " width="30%" height="250" />&nbsp;</a> <a href="#"><img src="images/slider/shablon_diploma_vnutri.jpg" alt="обучение управлению бизнес процессами" width="30%" height="250" />&nbsp;</a> <a href="#"><img src="images/slider/менеджмент_предприятия.jpg" alt="курсы по менеджменту предприятия" width="30%" height="250" /></a></p>\r\n<hr />\r\n<p style="text-align: left;"><span style="font-family: Pro; font-size: 12pt;"><strong>Программа курса</strong></span></p>\r\n<p style="text-align: left;"><span style="font-family: Pro; font-size: 12pt;"><strong style="color: #a22521;">Модуль 1. Стратегический и организационный менеджмент</strong></span></p>\r\n<table style="width: 99.8934%;">\r\n<tbody>\r\n<tr style="height: 233px; background-color: #f5f5f5;">\r\n<td style="width: 14.5775%; height: 233px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>1. Оперативное управление персоналом: постановка задачи, делегирование, проведение совещаний, мотивация и контроль</strong> </span></p>\r\n</td>\r\n<td style="width: 76.4225%; height: 233px;">\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>1)&nbsp;</strong>Ручное управление или регулярный менеджмент. Стадии развития компании и управления в организации. Зачем нужна регламентация бизнес процессов? Ключевые&nbsp;функции менеджмента</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong>&nbsp;Как организовывать работу подчиненных, делегировать полномочия и контролировать выполнение задач. Кому можно делегировать?</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro;"><span style="font-size: 10pt;"><strong>Постановка задач,</strong>&nbsp;алгоритм постановки задач.&nbsp;&nbsp;Как эффективно поставить задачу и&nbsp; получить результат выполнения?<br /></span><span style="font-size: 10pt;"><strong>Обратная связь.</strong>&nbsp;Как предоставлять сотруднику развивающую обратную связь? виды и правила обратной&nbsp;связи.<br />Как ругать сотрудника, чтобы улучшились результаты</span></span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>3)</strong>&nbsp;<strong>Планирование:</strong>&nbsp;расстановка приоритетов, линейное планирование, сложное планирование.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>4) Контроль</strong>: функции контроля, определение количества точек контроля, анализ причин несоответствия плана и фактическим результатам.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>5)</strong>&nbsp;<strong>Подготовка и проведение совещаний.</strong>&nbsp;Причины неэффективного совещания.&nbsp;Техники&nbsp;принятия решений&nbsp;на совещании.&nbsp;</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>4) Как мотивировать на результат,&nbsp;</strong>что движет сотрудниками.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">Уровни зрелости сотрудника. Искать готового или адаптировать под&nbsp; себя. Материальная и нематериальная мотивация. Система сбалансированных&nbsp; показателей&nbsp; и KPI, связь со стратегической картой</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 14.5775%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 76.4225%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 14.5775%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>2. Проектный&nbsp;<br />менеджмент</strong> </span></p>\r\n</td>\r\n<td style="width: 76.4225%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">Функционал менеджера проекта. Процессы&nbsp; проекта: инициация, планирование,&nbsp;исполнение, мониторинг, контроль, завершение проекта. Виды проектов. Разница от текущей деятельности. Что влияет на успешность проекта?Управление и снижение рисков, как часть проекта.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #ffffff; width: 14.5775%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; width: 76.4225%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 14.5775%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>3. Тайм - менеджмент. Личная эффективность</strong> </span></p>\r\n</td>\r\n<td style="width: 76.4225%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>1)&nbsp;</strong>Инструменты принятия решений. Техники и методы принятия управленческих решений</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong>&nbsp;Как использовать инструменты тайм-менеджмента:&nbsp; целеполагание, расстановка приоритетов.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>3)</strong>&nbsp;Как сократить «поглотителей времени»?</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>4)</strong>&nbsp;Какие методы планирования применять (6М, метод ALP, SMART, матрица Эйзенхауэра).&nbsp; Проактивная и реактивная позиция руководителя. Индивидуальный тип восприятия времени.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>5)</strong>&nbsp;Способы структурирования рабочего пространства, организация&nbsp;рабочего времени.&nbsp;</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro; font-size: 10pt;">- Как сохранять баланс в жизни и находить источники повышения работоспособности.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro; font-size: 10pt;">- Методы предупреждения стресса и эмоционального выгорания руководителя.&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #ffffff; width: 14.5775%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; width: 76.4225%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 14.5775%; height: 15px;"><span style="font-size: 10pt; font-family: Pro;"><span style="font-size: 10pt;"><b>4.Эмоциональный&nbsp;</b></span><span style="font-size: 13.3333px;"><b>интеллект</b></span><span style="font-size: 10pt;"><b>, как повышение уровня руководства</b></span> </span></td>\r\n<td style="width: 76.4225%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>1.Что дает Эмоциональный интеллект в области повышения качества руководства и эффективности компании в целом</strong> </span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">Управление людьми на основе эмоционального&nbsp; интеллекта. Значимость эмоционального интеллекта для различных профессий и бизнес-задач</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>2. Эмоциональная компетентность руководителя</strong> </span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">Как использовать эмоции в бизнесе. Как распознать свое эмоциональное состояние и изменить его в зависимости от задач. Формирование благоприятного делового контакта.&nbsp;<br /></span><span style="font-size: 10pt;">Как грамотно использовать энергию «негативных» эмоций?&nbsp;</span><span style="font-size: 10pt;">- Практика Отработка навыков управления эмоциями в ситуациях взаимодействия с другими людьми<br /></span><span style="font-size: 10pt;">Эмоции женщин и эмоции мужчин – гендерные различия</span></span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;"><strong>3. Эмоциональный интеллект, как инструмент для решения сложных ситуаций в бизнес-среде</strong> </span><span style="font-size: 10pt;"><br /></span><span style="font-size: 10pt;">Эмоции положительно влияющие &nbsp;и отрицательно влияющие на эффективность деятельности<br /></span><span style="font-size: 10pt;">Индивидуальные особенности мотивации персонала. Эмоции в основе мотивации.</span></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #ffffff; width: 14.5775%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; width: 76.4225%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 14.5775%; height: 15px;"><span style="font-size: 10pt; font-family: Pro;"><strong>5.Власть и лидерство</strong> </span></td>\r\n<td style="width: 76.4225%; height: 15px; text-align: justify;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>1. Создание и управление эффективных команд</strong></span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">Как подбирать членов команды? Коммуникации в командах как инструмент эффективного лидера.&nbsp;</span><span style="font-size: 10pt;">Практика: Развитие навыков лидерского взаимодействия с подчиненными</span></span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">Техники работы с эмоциями при решении командных задач:&nbsp;н</span><span style="font-size: 10pt;">астройки на успех.&nbsp;</span></span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">Рациональный и интуитивный подход в принятии решений.&nbsp;Трудные решения и эмоции.</span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">Обратная связь через аргументацию, включающую&nbsp;разные виды</span><span style="font-size: 10pt;">&nbsp;с</span><span style="font-size: 10pt;">остояний</span><span style="font-size: 10pt;">&nbsp;сотрудников. Предотвращение конфликтных ситуаций.</span></span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">Эмоциональный интеллект и развитие других.&nbsp;Коучинг в развитии эмоционального интеллекта.&nbsp;</span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;"><strong>2. Харизма лидера. Спонтанное поведение.&nbsp;</strong> </span><span style="font-size: 10pt;">Приемы развития харизмы</span></span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">Эффективные коммуникации.&nbsp;Имидж лидера. Поза, жесты, речь.&nbsp;Пластика движений, жестикуляция, голосовые режимы, тембр голоса, интонация.&nbsp;</span><span style="font-size: 10pt;">Практика: Приемы эффективного общения.&nbsp;</span></span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">Концепции лидерства.</span><span style="font-size: 10pt;">Ситуационные модели лидерства</span><span style="font-size: 10pt;">&nbsp;Практика: Определение собственного стиля лидерства: предпочитаемый стиль влияния и зоны развития. Определение и выбор оптимального стиля управления</span></span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">Лидер и группа.&nbsp;</span><span style="font-size: 10pt;">Законы групповой динамики. Управление групповой динамикой.&nbsp;Инструмент лидера - искусство говорить публично</span></span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;"><strong>3. Власть.</strong> </span><span style="font-size: 10pt;"><strong>&nbsp;</strong>Внутренняя сила. Технологии и искусство доминирования. Принципы формирования общественного мнения.&nbsp;</span><span style="font-size: 10pt;">&nbsp;Власть личности, власть положения, власть знания. Какой тип власти применять в конкретной ситуации?&nbsp;</span><span style="font-size: 10pt;">Практика: Выбор собственного типа власти.</span><span style="font-size: 10pt;"><br /></span></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #ffffff; width: 14.5775%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; width: 76.4225%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 14.5775%; height: 15px;"><span style="font-size: 10pt; font-family: Pro;"><strong>6. Оперативное планирование или как обеспечить продвижение к обозначенным целям всеми сотрудниками</strong> </span></td>\r\n<td style="width: 76.4225%; height: 15px;">\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;"><strong>1)</strong>&nbsp;Оперативные цели и планы. Введение контрольных показателей.<br /></span><span style="font-size: 10pt;"><strong>2)</strong>&nbsp;Достижение результата. Система планирования, как инструмент достижения результата.&nbsp;<br /></span><span style="font-size: 10pt;"><strong>3)</strong>&nbsp;Уровни планирования от стратегии к тактике. Мониторинг и изучение. Анализ планирования и результатов с учетом их влияния на показатели оперативных, тактических и стратегических планов.<br /></span><span style="font-size: 10pt;"><strong>4)</strong>&nbsp;Составляем план дальнейших действий.<br /></span><span style="font-size: 10pt;"><strong>5)</strong>&nbsp;Подводим итоги.</span></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #ffffff; width: 14.5775%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; width: 76.4225%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 14.5775%; height: 15px;"><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">7. Формирование стратегии развития сотрудника, подразделения, компании&nbsp;</span></strong> </span></td>\r\n<td style="width: 76.4225%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong>&nbsp;Новые уровни развития. План, цель, стратегия. Эффективный&nbsp;баланс: жесткое&nbsp; планирование и гибкое реагирование на изменения.&nbsp;&nbsp;Уровни планирования. Цикл процесса планирования.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong>&nbsp;Аудит действующих целей и стратегии. Разрабатываем&nbsp; План развития&nbsp;сотрудника, подразделения, компании.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #ffffff; width: 14.5775%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; width: 76.4225%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 14.5775%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>8. Что делать для реализации стратегии?</strong> </span></p>\r\n</td>\r\n<td style="width: 76.4225%; height: 15px;">\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong>&nbsp;Стратегические цели и стратегический план сотрудников, подразделений и компании. Тактические цели.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong>&nbsp;Выбор стратегии движения. Вопросы стратегического прогнозирования.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro; font-size: 10pt;"><span lang="EN-US"><strong>3)</strong>&nbsp;</span>Оцениваем реальную ситуацию, ресурсы сотрудников,&nbsp;компании.&nbsp;<span lang="EN-US">SWOT -&nbsp;</span>анализ сотрудников и компании. Разные виды SWOT анализа: линейный и перекрестный.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro;"><span style="font-size: 10pt;"><strong>4)</strong>&nbsp;Разработка карты стратегии – интегрируем &nbsp;составляющие сбалансированной системы показателей&nbsp;</span><span style="font-size: 10pt;">финансы, клиенты, процессы, персонал. Разрабатываете карту на вашем предприятии.<br /></span><span style="font-size: 10pt;">- Определяем стратегическую цель в финансовых показателях.<br /></span><span style="font-size: 10pt;">- Определяем бизнес процессы, что&nbsp;обеспечит достижение финансовых целей.<br /></span><span style="font-size: 10pt;">- Выявляем внутренние бизнес-процессы для реализации целей и доводим их до совершенства.<br /></span><span style="font-size: 10pt;">- Определяем стратегическую роль персонала.&nbsp;<strong>Совершенствуем&nbsp;систему обучения и развития персонала.</strong></span></span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro; font-size: 10pt;"><strong>5)</strong>&nbsp;Для чего нужен пессимистический сценарий? Составляем пессимистический и&nbsp; оптимистический сценарии.&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #ffffff;">&nbsp;</td>\r\n<td style="background-color: #ffffff;">&nbsp;</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 48%; height: 15px;" colspan="2"><span style="font-family: Pro; font-size: 12pt;"><strong style="color: #a22521;">Модуль 2. Эффективный маркетинг и реклама</strong></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong style="font-family: arial, helvetica, sans-serif; font-size: 13.3333px;">1.&nbsp;Маркетинговый<br /> аудит положения<br /> компании на рынке</strong></span></p>\r\n</td>\r\n<td style="width: 38%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong> Как определить место компании на рынке?</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong> Цели и миссия компании.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>3)</strong> Макросреда и микросреда компании. Ресурсы и способности вашей компании</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>4)</strong> Целевая аудитория и сегментирование клиентов.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>5)</strong> Позиционирование&nbsp;товара. Определяем конкурентные преимущества.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>6)</strong> Анализ конкурентов и бенчмаркетинг.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>7)</strong> SWOT- анализ.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 10%; height: 15px;"><span style="font-size: 10pt; font-family: Pro;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 38%; height: 15px;"><span style="font-size: 10pt; font-family: Pro;"><strong>&nbsp;</strong></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2. Стратегии компании&nbsp;и <br />маркетинговые<br /> исследования</strong></span></p>\r\n</td>\r\n<td style="width: 38%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong> Для чего именно нам нужно проведение исследований.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong> инструменты исследований.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>3)</strong> Использование маркетинговых исследований и маркетинговой информации в компании.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 10%; height: 15px;"><span style="font-size: 10pt; font-family: Pro;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 38%; height: 15px;"><span style="font-size: 10pt; font-family: Pro;"><strong>&nbsp;</strong></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>3. <span lang="EN-US">Торговый маркетинг</span></strong> </span></p>\r\n</td>\r\n<td style="width: 38%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong> Основы категорийного менеджмента.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong> Принципы управления ассортиментной матрицей.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>3)</strong> уникальное торговое предложение. &nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>4)</strong> Ассортиментная политика компании. &nbsp;Как заработать на расширении ассортимента?</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 10%; height: 15px;"><span style="font-size: 10pt; font-family: Pro;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 38%; height: 15px;"><span style="font-size: 10pt; font-family: Pro;"><strong>&nbsp;</strong></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>4. Ценообразование <br />и управление ассортиментом</strong></span></p>\r\n</td>\r\n<td style="width: 38%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong>&nbsp;Ценообразование и ценовая стратегия.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong>&nbsp;Управление товарным ассортиментом.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 10%; height: 15px;"><span style="font-size: 10pt; font-family: Pro;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 38%; height: 15px;"><span style="font-size: 10pt; font-family: Pro;"><strong>&nbsp;</strong></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>5.</strong><strong> Интегрированные <br />маркетинговые<br /> коммуникации.&nbsp;</strong></span></p>\r\n</td>\r\n<td style="width: 38%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong> Инструменты продвижения. Их возможности и недостатки.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong> Нейромаркетинг. Прямой маркетинг. &nbsp;Ивент-маркетинг. Public Relations.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>3)</strong> Понятия «бренд» и «брендинг». Как управлять популярностью торговой марки.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>4)</strong> Подходы к оценке эффективности рекламных кампаний.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #ffffff; height: 15px; width: 10%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; height: 15px; width: 38%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>6.&nbsp;Интернет-маркетинг</strong></span></p>\r\n</td>\r\n<td style="width: 38%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong> Базовые аспекты интернет-маркетинга.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2)&nbsp;</strong><span lang="EN-US">SEO</span>&nbsp;(поисковое) продвижение.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><span lang="EN-US"><strong>3)</strong>&nbsp;</span>Контекстная реклама.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>4)&nbsp;</strong><span lang="EN-US">SMM</span>-продвижение. &nbsp;Как с минимальным бюджетом развиться в соц. сетях.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>5)</strong>&nbsp;<span lang="EN-US">E</span>-<span lang="EN-US">mail</span>-маркетинг.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>6)</strong>&nbsp;Продвижение видео-контента.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 9px; background-color: #ffffff;">\r\n<td style="width: 10%; height: 9px;"><span style="font-family: Pro;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 38%; height: 9px;"><span style="font-family: Pro;"><strong>&nbsp;</strong></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 48%; height: 15px;" colspan="2"><span style="font-family: Pro; font-size: 12pt;"><strong style="color: #a22521;">Модуль 3. Управление персоналом</strong></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px; background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">1. Актуальные методики <br />подбора и оценки <br />потенциала кандидатов</span></strong> &nbsp;</span></p>\r\n</td>\r\n<td style="width: 38%; height: 15px; background-color: #f5f5f5;"><span style="font-family: Pro;"><strong style="font-family: arial, helvetica, sans-serif; font-size: 10pt; text-align: justify;">1)</strong><span style="font-size: 10pt; text-align: justify;">Рекрутинг: актуальные и новые подходы к подбору персонала.&nbsp;Профиль должности, для чего и как разрабатывается? &nbsp;</span></span>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>2)&nbsp;</strong>Эффективная реклама вакансий, составление «работающего» объявления, примеры удачных и неудачных рекламных модулей.&nbsp;</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>3)&nbsp;</strong>Источники поиска персонала. Прямой поиск. Когда он необходим? Создание легенд и работа с ними. Headhunting - Технология привлечения «голов» под заказ.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>4)</strong>&nbsp;Методы оценки компетенций кандидата. Анализ резюме кандидата. Телефонное интервью. Анализ документов и биографических фактов. Метод экспресс-диагностики (оценка по первому впечатлению). Автобиография кандидата как метод оценки. Метод интервью по компетенциям. Метод самопрезентации кандидата. Контент-анализ речи кандидата. Метод экспертной оценки. Психологическое тестирование.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">- Психологический портрет сотрудника на основе метода «LAB-profile</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">- Коммуникативная компетентность; IQ и EQ (эмоциональный интеллект)</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">- Проективные вопросы. Проективное и ситуационное интервью. Тесты. Методы ухода от социально желательных ответов</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">- Тестирование кандидатов: Тесты Рокича, Роттера, Томаса, Герчикова, методика КОС</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">- Оценка достоверности информации. Как узнать когда кандидат лжет.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><em>- Практические задания кейсы по разработке профиля должности.</em>&nbsp;<em>&nbsp;</em></span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><em>- Разработка компетенций должностей</em>&nbsp;<em>&nbsp;- Анализ удачных и неудачных вакансий.</em></span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><em>- Кейсовое интервью и анализ правильности принятия решения при&nbsp; выборе финального кандидата.</em></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 38%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">2. Коучинг и адаптация <br />персонала</span></strong> </span></p>\r\n</td>\r\n<td style="width: 38%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>1)</strong> Система и оценка управления адаптацией в организации.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>2)</strong> Коучинг и наставничество как основные инструменты адаптации.&nbsp;Коучинг - правильные вопросы для развития потенциала сотрудников.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 38%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;"><strong>3. Обучение и развитие <br />персонала&nbsp; - затраты <br />или вложение в <br />развитие организации?</strong></span>&nbsp;</span></p>\r\n</td>\r\n<td style="width: 38%; height: 15px;"><span style="font-family: Pro;"><strong style="font-family: arial, helvetica, sans-serif; font-size: 10pt; text-align: justify;">1)</strong><span style="font-size: 10pt; text-align: justify;">Организация и поощрение роста квалификации и развития сотрудников по недостающим у них компетенциям.</span></span>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong>&nbsp;Система обучения и развития персонала организации. Виды и методы обучения.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>3)</strong>&nbsp;Сбор и анализ потребностей в обучении персонала. Методы сбора потребности в обучении. Анализ и систематизация потребностей в обучении, сопоставление&nbsp;согласованность со стратегическими приоритетами.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>4)</strong>&nbsp;Планирование и организация обучения и развития персонала. Бюджетирование затрат на обучение и развитие персонала.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>5)</strong>&nbsp;Точки контроля процесса обучения, оценка эффективности системы обучения и обученного персонала. Современные подходы к оценке эффективности обучения.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>6)</strong>&nbsp;Составление планов развития внутреннего потенциала сотрудников. Развитие эмоционального интеллекта.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro; font-size: 10pt;"><em>- Практика оценки потребностей в обучении и расчет эффективности от обучения</em></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 38%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro;"><strong>4. Мотивация. Как увеличивать<br /> прибыль предприятия, <br />внедряя эффективную <br />мотивационную систему?</strong></span></p>\r\n</td>\r\n<td style="width: 38%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong> Трудовая мотивация персонала. Внешние и внутренние мотиваторы. Мотивационные механизмы. Демотивация персонала, устранение демотивирующих факторов.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong> Различная мотивация и циклы развития организации. Принципы эффективной компенсационной политики. Что необходимо для создания успешной системы оплаты труда. Недостатки денег в качестве основного мотиватора.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>3)</strong> Ценности поколения X, ценности поколения Y. Они совместимы? К чему стремятся люди Y, и можем ли мы это им дать, чтобы обеспечить необходимые инновации?</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 38%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro;"><strong>5. Оценка персонала или <br />поддерживаем в тонусе<br /> квалификацию персонала</strong></span></p>\r\n</td>\r\n<td style="width: 38%; height: 15px;"><span style="font-family: Pro;"><strong style="font-family: arial, helvetica, sans-serif; font-size: 10pt; text-align: justify;">1)</strong><span style="font-size: 10pt; text-align: justify;">Оценка и аттестация персонала. Цель создания системы оценки и аттестации персонала. Требования к системе оценки. Регулярность и периодичность оценочных процедур. Связь процессов оценки и обучения.</span></span>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong>&nbsp;Современные методы оценки персонала в компании. Оценка по служебным функциям, м<b>етод 360, 540 градусов, метод экспертных оценок, независимых судей.</b></span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>3) Технология Ассессмент-центр -</strong>&nbsp;современная технология оценки персонала. Анализ кадрового потенциала организации.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>4)</strong>&nbsp;Практика: кейс&nbsp; оценки&nbsp; - Ассессмент - центр – технология, позволяющая в короткие сроки получить достоверную информацию о личностно-деловых качествах сотрудников.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 38%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">6. Корпоративная культура,<br /> как она влияет на рост и <br />развитие компании?</span></strong> </span></p>\r\n</td>\r\n<td style="width: 38%; height: 15px;"><span style="font-family: Pro;"><strong style="font-family: arial, helvetica, sans-serif; font-size: 10pt; text-align: justify;">1)</strong><span style="font-size: 10pt; text-align: justify;">Анализ существующей ситуации в компании, инструменты анализа.</span></span>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong>&nbsp;Изменение организационной культуры: новые ценностные приоритеты, кодекс компании, поддерживающие мероприятия.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>3)</strong>&nbsp;Правила разработки мероприятий, способствующих формированию (коррекции существующей) корпоративной культуры.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>4)</strong>&nbsp;Документальное описание корпоративной культуры компании. Разработка положения (политики) по корпоративной культуре в компании.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro; font-size: 10pt;"><i>- Практика: «Разработка&nbsp; корпоративной культуры».</i></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 38%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>7.&nbsp;Личная эффективность</strong></span></p>\r\n</td>\r\n<td style="width: 38%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>1)</strong> Личная эффективность. Целеполагание в «SMART» - формате. Методы планирования. Инструменты тайм-менеджмента. Инвентаризация рабочего времени.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>2)</strong> Конфликтология. Управление организационным конфликтом. Виды, причины, стадии развития конфликта. Стили поведения в конфликте. Этапы разрешения и способы урегулирования конфликта. Методы профилактики конфликтов.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>3)</strong> Стресс-менеджмент. Причины и симптомы стрессового напряжения. Способы сохранения и восстановления эмоционального равновесия и работоспособности. Антистресс - профилактика. Организационный стресс и результативность команды.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 38%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 48%; height: 15px;" colspan="2"><span style="font-family: Pro; font-size: 12pt;"><strong style="color: #a22521;">Модуль 4. Продажи и переговоры</strong></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">1. Поиск клиентов. Как искать клиентов?</span></strong>&nbsp;</span></p>\r\n</td>\r\n<td style="width: 38%; height: 15px;"><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong> Сбор информации о бизнесе клиента и конкурентах.&nbsp;</span>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>2)</strong> Подготовка к "холодным" и "теплым" звонкам (ключевые фразы). Правильная постановка целей, сценарии звонка.&nbsp;</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>3)</strong> Контакт с клиентом. Универсальные приемы установления контакта. Практика установления контакта.&nbsp;</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>4)</strong> Как управлять воронкой продаж. Воронка как инструмент анализа эффективности работы менеджера.&nbsp;</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>5)</strong> Лучшие способы поиска новых клиентов.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 38%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2. Правильные вопросы,&nbsp;<br />выявление потребностей</strong></span></p>\r\n</td>\r\n<td style="width: 38%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong> Правильные вопросы для выявления потребности, зачем задавать вопросы?</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong> Развитие диалога: управляем беседой и клиентом при помощи вопросов.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 38%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">3. Презентация компании, <br />товара</span></strong> </span></p>\r\n</td>\r\n<td style="width: 38%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong><span style="color: black;">1)</span> <span style="color: black; font-weight: normal;">Покупательские мотивы, модель перевода свойств в выгоду.</span></strong> </span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong><span style="color: black; font-weight: normal;"><strong>2)</strong> Способы обоснования цены, аргументируем цена&nbsp;&nbsp;- выгода.</span></strong> </span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong><span style="color: black; font-weight: normal;"><strong>3)</strong> 6 лучших способов для выгодной презентации цены.&nbsp;</span></strong> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 38%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;"><strong>4.&nbsp;Работа с возражениями</strong></span>&nbsp;</span></p>\r\n</td>\r\n<td style="width: 38%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong><span style="font-weight: normal;"><strong>1)</strong>&nbsp;</span><span style="color: black; font-weight: normal;">Причины возникновения возражений:&nbsp;&nbsp;цена, отговорки.</span></strong> </span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong><span style="color: black; font-weight: normal;"><strong>2)</strong> Модель обработки возражений, применение тактики аргументации.</span></strong> </span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong><span style="color: black; font-weight: normal;"><strong>3)</strong> 10 правил работы с возражениями клиентов.</span></strong> </span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong><span style="color: black; font-weight: normal;"><strong>4)</strong> Скрипты на главные возражение «дорого», «я подумаю», «нет денег».&nbsp;</span></strong> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 38%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro;"><strong>5. Завершение сделки, диалога.<br />&nbsp;Как завершить <br />диалог, чтобы &nbsp;клиент<br /> купил товар?</strong></span></p>\r\n</td>\r\n<td style="width: 38%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong><span style="font-weight: normal;"><strong>1)</strong>&nbsp;</span><span style="color: black; font-weight: normal;">Сигналы готовности клиента к покупке приемы.</span></strong> </span></p>\r\n<p><span style="color: black; font-size: 10pt; font-family: Pro;"><strong>2)</strong> Этап завершения сделки, тонкости доведения сделки до результата.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong><span style="color: black; font-weight: normal;"><strong>3)</strong> Скрипты на завершение сделки.&nbsp;</span></strong> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 38%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>6. Особенности ведения<br /> телефонных переговоров</strong></span></p>\r\n</td>\r\n<td style="width: 38%; height: 15px;"><span style="font-size: 10pt; font-family: Pro;"><strong>1)&nbsp;<span style="color: black; font-weight: normal;">Способы преодоления «секретарского барьера» и выхода на ЛПР (лицо, принимающее решение).</span></strong> </span>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong><span style="color: black; font-weight: normal;"><strong>2)</strong> Какие вопросы имеет смысл задавать клиенту во время «холодного звонка».</span></strong> </span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong><span style="color: black; font-weight: normal;"><strong>3)</strong> Особенности ведения телефонных продаж.</span></strong> </span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong><span style="color: black; font-weight: normal;"><strong>4)</strong> Ключевые подходы к продажам по телефону.</span></strong> </span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong><span style="color: black; font-weight: normal;"><strong>5)</strong> Приемы и техники эмоционального настроя на холодный звонок.</span></strong> </span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong><span style="color: black; font-weight: normal;"><strong>6)</strong> Работа с тембром, громкостью, четкостью речи. Методики управления голосом. Факторы звучания голоса.</span></strong> </span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong><span style="color: black; font-weight: normal;"><strong>7)</strong> Как эффективно начать контакт.</span></strong> </span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong><span style="color: black; font-weight: normal;"><strong>8)</strong> Сложности при телефонном общении.</span></strong> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 38%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">7. Алгоритм продажи с<br /> крупными клиентами, <br />важные этапы ведения<br /> деловой беседы</span></strong> </span></p>\r\n</td>\r\n<td style="width: 38%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>1)</strong> Как вести себя с крупными клиентами, особенности продажи.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>2)</strong> Умение правильно строить отношения.&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 38%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>8.&nbsp;Техника СПИН-продаж. <br />Работа со сложными<br /> клиентами</strong></span></p>\r\n</td>\r\n<td style="width: 38%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong><span style="color: #351e07;">Модель СПИН как гибкая система продаж.</span></span></p>\r\n<p><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-family: Pro; font-size: 10pt;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-weight: bold;">2)</span>&nbsp;Вопросы – СПИН.</span></p>\r\n<p style="box-sizing: inherit; margin: 5px 0px; padding: 0px; color: #351e07; font-family: Pro; font-size: 14px;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-family: Pro; font-size: 10pt;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-weight: bold;">3)</span>&nbsp;Как работает СПИН? Практика задавания вопросов для принятия клиентом решения о покупке.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 38%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr>\r\n<td colspan="2"><span style="font-size: 12pt;"><strong><span style="font-family: Pro; color: #a22521;">Модуль 5. Финансовый менеджмент&nbsp;</span></strong> </span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>1. Экономика предприятия</strong></span></p>\r\n</td>\r\n<td style="width: 38%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong> Точка безубыточности. Анализ безубыточности.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong> Ключевой расчет маржинальной прибыли, чистой прибыли.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>3)</strong> Ключевые показатели эффективности предприятия,&nbsp; EBITDA, ROE.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>4)</strong> Анализ финансовых результатов деятельности.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 38%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;"><strong>2. Организация <br />аналитического </strong></span><span style="font-size: 10pt;"><strong>учета<br /> затрат</strong></span></span></p>\r\n</td>\r\n<td style="width: 38%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>1)</strong> Бухгалтерский план счетов, с использованием которых осуществляется учет затрат на производство. Группировка балансовых статей, баланс предприятия,&nbsp; строение балансовых счетов.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>2)</strong> Затраты по статьям калькуляции. Учет отдельных видов затрат. Система " Директ - костинг".</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>3)</strong> Специфика и области применения различных методов учета производственных затрат: позаказного, котлового, попередельного.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 38%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">3. Финансовая отчетность. </span></strong> </span></p>\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">Финансовый анализ</span></strong> </span></p>\r\n</td>\r\n<td style="width: 38%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>1)</strong> Финансовый анализ, как метод оценки текущего и перспективного финансового состояния предприятия: трендовый, факторный, метод цепных подстановок, горизонтальный, вертикальный.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>2)</strong> Анализируем бухгалтерский баланс, в чем отличие от управленческого баланса.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>3)</strong> Особенности составления отчета о прибылях и убытках, отличие от Бюджета доходов и расходов.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>4)</strong> Коэффициенты финансового анализа: платежеспособность и&nbsp;ликвидность, &nbsp;коэффициент инвестирования, коэффициенты финансовой устойчивости, деловой активности.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 38%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">4. Управление<br /> инвестициями</span></strong> </span></p>\r\n</td>\r\n<td style="width: 38%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>1)</strong> Основные показатели, используемые для расчетов эффективности инвестиционного проекта.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>2)</strong> Чистый дисконтированный доход (NPV), индекс рентабельности инвестиций, внутренняя норма доходности.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>3)</strong> Срок окупаемости инвестиций. Резерв безопасности проекта.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>4)</strong> Управление заемным капиталом. Эффект финансового рычага.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>5)</strong> Стоимость капитала: ее составляющие и методы оценки.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>6)</strong> Ликвидность и способы ее оценки.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 38%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>5. Бизнес-план – первый план компании.&nbsp;</strong></span></p>\r\n</td>\r\n<td style="width: 38%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>1)</strong> Производственный план. Общий подход к организации производства.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>2)</strong> Финансовый план. Бюджетирование, как составная часть финансового планирования.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>3)</strong> Оценка рисков.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 38%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>6. Бюджетирование – как <br />часть системы управления<br /> предприятием</strong></span></p>\r\n</td>\r\n<td style="width: 38%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>1)</strong> Постановка системы бюджетного управления:&nbsp; определение участников процесса бюджетного управления,&nbsp; определение центров финансовой ответственности, учета (ЦФО, ЦФУ).</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>2)</strong> Бюджетная система:&nbsp; Система бюджетов на предприятии: Бюджет продаж, бюджет производства, бюджет накладных расходов, бюджет доходов и расходов, бюджет движения денежных средств.&nbsp; Взаимосвязь основных плановых и отчетных форм между собой. Контроль исполнения бюджетов – ключевая функция системы бюджетного управления.&nbsp; Анализ исполнения бюджета.<br /></span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>3)</strong>&nbsp;Изучение наиболее востребованных формул и функций Excel для построения бюджетов.&nbsp;</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>4)</strong>&nbsp;Практические задания в Excel и 1С "Бухгалтерия".</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>&nbsp;Практические примеры построения&nbsp; бюджетов в программе Excel – программа для управленческого учета и системы бюджетирования на предприятии</strong></span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span style="font-size: 12pt; font-family: Pro;"><strong>Формат:</strong></span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro;"><span style="margin: 0px; padding: 0px; color: #000000; line-height: normal;"><strong style="margin: 0px; padding: 0px;">Продолжительность :&nbsp;</strong></span><span style="font-size: 10pt; background-color: inherit; color: inherit;">&nbsp;6 месяцев</span><span style="color: #000000; line-height: normal;">,&nbsp;</span><span style="font-size: 10pt; background-color: inherit; color: inherit;">2 - 3 раза в неделю, понедельник, среда с 18.30 до 21.30, суббота с 10 до 14.00</span><br /></span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">Формы обучения - &nbsp; включают&nbsp; в себя: информационные модули, дискуссии и мозговые штурмы, ролевые игры и упражнения, «разбор полетов» (моделирование и анализ реальных ситуаций взаимодействия).</span></p>\r\n<hr />\r\n<p><span style="font-family: Pro;">&nbsp;<strong><span style="font-size: 12pt;">Акции и скидки:</span></strong></span></p>\r\n<p>&nbsp;</p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">•&nbsp;Скидка 10%&nbsp;при оплате за&nbsp;3 недели до обучения.&nbsp;&nbsp;</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">•&nbsp;Скидка 5%&nbsp;при оплате за 2 недели до обучения.</span></p>\r\n<p>&nbsp;</p>\r\n<p style="text-align: center;"><span style="font-family: Pro;"><a onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>', '', 1, 23, '2016-06-30 09:01:24', 42, '', '2019-04-30 05:41:10', 42, 0, '0000-00-00 00:00:00', '2016-06-30 09:01:24', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 130, 4, 'управление бизнес процессами обучение, курсы по менеджменту предприятия, mba бизнес процессы образование', 'Курсы по менеджменту предприятия, управление бизнес процессами. От экспертов практиков. Скидки до 15%', 1, 7978, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(121, 208, 'Стратегическая сессия, стратегическое планирование тренинг  - курс', 'стратегическая-сессия,-стратегическое-планирование-тренинг-курс', '<h1 style="text-align: center;">Тренинг - курс стратегического планирования</h1>\r\n<p><img src="images/strategicheskoe_planirovanie.jpg" alt="" /></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>Целевая аудитория курса:&nbsp;&nbsp;</strong></span>"ключевые" сотрудники,&nbsp; руководители подразделений и&nbsp;организаций.</p>\r\n<h3 style="text-align: center;"><span style="font-family: arial, helvetica, sans-serif; color: #000000; font-size: 10pt;"><strong>ВЫ ПОЛУЧИТЕ НА ОБУЧЕНИИ:</strong></span></h3>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 54.875px;">\r\n<td style="width: 48.4274%; height: 54.875px;">\r\n<ul>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Сформируете видение миссии и стратегии развития Вашей компании</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 49.5726%; height: 54.875px;">\r\n<ul style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;">\r\n<li><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">Разработаете стратегический план. Определите стратегические, тактические цели</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr style="height: 54px;">\r\n<td style="width: 48.4274%; height: 54px;">\r\n<ul style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;">\r\n<li><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">Выработаете единое информационное поле и единый подход к развитию бизнеса</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 49.5726%; height: 54px;">\r\n<ul>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Оптимизируете бизнес-процессы компании</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p style="text-align: center;"><a onclick="yaCounter15669946.reachGoal (''ostavitzayavky''); return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></p>\r\n<p style="text-align: center;"><strong><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">ПРОГРАММА</span></strong></p>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 78px; background-color: #f5f5f5;">\r\n<td style="width: 33%; height: 78px;">\r\n<p><strong><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">1.&nbsp;</span></strong><strong><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Формирование стратегии развития компании</span></strong></p>\r\n</td>\r\n<td style="width: 64%; height: 78px;">\r\n<p><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>1)</strong> Что важнее: планировать или гибко реагировать на изменения? Цель и план. Уровни планирования. Цикл процесса планирования.</span></p>\r\n<p><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>2)</strong></span><span style="font-family: arial, helvetica, sans-serif; font-size: 13.3333px;"></span><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Аудит действующей миссии и стратегии. Разрабатываем &nbsp;видение будущего компании.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 33%; height: 15px;">&nbsp;</td>\r\n<td style="width: 64%; height: 15px;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 418px; background-color: #f5f5f5;">\r\n<td style="width: 33%; height: 418px;">\r\n<p><strong><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">2. Как перевести миссию на уровень стратегических целей компании? Как определить тактические задачи для реализации стратегии?</span></strong></p>\r\n</td>\r\n<td style="width: 64%; height: 418px;">\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>1)</strong> Разработка стратегических целей и стратегических планов. Тактические цели.</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>2)</strong> Разработка карты стратегии – интегрируем миссию в четыре составляющие сбалансированной системы показателей:</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">- Определяем стратегическую цель компании в финансовых показателях.</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">- Определяем, какое предложение потребительской ценности клиентам обеспечит достижение финансовых целей.</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">- Выявляем внутренние бизнес-процессы для реализации финансовых и клиентских целей и доводим их до совершенства.</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">- Определяем стратегическую роль нематериальных активов компании, приводим в соответствие с предыдущими уровнями. Совершенствуем стратегию обучения и развития персонала.</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>3) Выбор стратегии движения компании.</strong>&nbsp;Анализ внешней среды и внутренних ресурсов компании. Вопросы стратегического прогнозирования.</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><span lang="EN-US"><strong>4)</strong> SWOT-</span>анализ. Оцениваем конкурентоспособность товара или услуги компании на рынке с помощью анализа внутренней и внешней среды организации.</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">- Определяем сильные и слабые стороны.</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">- Определяем угрозы и возможности.&nbsp;</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">- Составляем матрицу&nbsp;<span lang="EN-US">SWOT&nbsp;</span>анализа.</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">- Делаем выводы и разрабатываем стратегию.&nbsp;</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;">&nbsp;<span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>5)</strong> Составляем оптимистический и пессимистический сценарии развития.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 33%; height: 15px;">&nbsp;</td>\r\n<td style="width: 64%; height: 15px;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 33%; height: 15px;"><strong><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">3. Как обеспечить продвижение к обозначенным целям всеми сотрудниками?</span></strong></td>\r\n<td style="width: 64%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>1)</strong> Оперативные цели и планы. Введение контрольных показателей.</span></p>\r\n<p><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>2)</strong> Осуществление плана. Система управления. Как эффективно поставить задачу и проконтролировать выполнение?</span></p>\r\n<p><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>3)</strong> Мониторинг и изучение. Анализ планирования и результатов с учетом их влияния на показатели оперативных, тактических и стратегических планов.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 33%; height: 15px;">&nbsp;</td>\r\n<td style="width: 64%; height: 15px;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 15.875px; background-color: #f5f5f5;">\r\n<td style="width: 33%; height: 15.875px;">\r\n<p><strong><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">4. Что дальше?&nbsp;</span></strong></p>\r\n</td>\r\n<td style="width: 64%; height: 15.875px;">\r\n<p><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>1)</strong> Составляем план дальнейших действий.</span></p>\r\n<p><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>2)</strong> Подводим итоги сессии.</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>Продолжительность: 1 вариант</strong></span> 2,5&nbsp;&nbsp;недели,&nbsp;2 раза в неделю, понедельник, среда с 18.30 до 21.30<br />&nbsp;<span style="font-family: arial, helvetica, sans-serif;"><strong>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 2 вариант </strong>- 2 дня, суббота - воскресенье с 09.00 до 17.00 &nbsp; Стоимость 11000 руб</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>Формы обучения:</strong></span> информационные модули, дискуссии и мозговые штурмы, ролевые &nbsp;упражнения, «разбор полетов» (моделирование и анализ реальных ситуаций взаимодействия).&nbsp;</p>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 15.9688px; background-color: #f5f5f5;">\r\n<td style="width: 26.9231%; height: 15.9688px; text-align: center;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong><span style="color: #800000;">ВЕДУЩИЙ ТРЕНИНГА</span></strong> </span></td>\r\n<td style="width: 71.5812%; height: 15.9688px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong><span style="color: #800000;">ХАБИРОВА ТАТЬЯНА ВАЛЕРЬЕВНА</span></strong> </span></td>\r\n</tr>\r\n<tr style="height: 15.9688px; background-color: #f5f5f5;">\r\n<td style="width: 26.9231%; height: 15px; text-align: center;"><img src="images/DSC0056721.jpg" alt="" width="86" height="129" /></td>\r\n<td style="width: 71.5812%; height: 15px;">\r\n<p><strong><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Тренер по стратегическому развитию и управленческим компетенциям.&nbsp;</span></strong></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Проведение сборных и корпоративных программа, проектов по направлениям:&nbsp;</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">- Базовые управленческие навыки, командообразование, сессии стратегического планирования.&nbsp;</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">- Коммуникативная компетентность: технологии работы с рекламациями и конфликтами, профессиональное телефонное общение.&nbsp;</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">- Личная эффективность: тайм-менеджмент (управление временем), стресс-менеджмент.&nbsp;</span></p>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>', '', 1, 23, '2016-08-01 08:04:20', 42, '', '2019-02-28 09:34:34', 42, 0, '0000-00-00 00:00:00', '2016-08-01 08:04:20', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 60, 3, '', '', 1, 2258, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(122, 209, 'Обучение маркетингу и интернет-маркетингу', 'обучение-маркетингу-и-интернет-продвижению', '<h1 style="text-align: center;"><span style="font-family: Pro;">Эффективный маркетинг и интернет-продвижение в&nbsp;{city_d}</span></h1>\r\n<p style="text-align: center;"><span style="font-family: Pro;">{img; /images/kursi_marketing3.jpg; /images/kursi_marketing2.jpg; /images/kursi_marketing.jpg; Обучение маркетологов}</span></p>\r\n<p style="text-align: left;"><span style="font-size: 10pt; font-family: Pro;">Обучение маркетингу и интернет маркетингу ориентировано на начинающих маркетологов, специалистов и руководителей по продажам и продвижению товара, владельцев малого и среднего бизнеса</span></p>\r\n<p style="text-align: center;"><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">ПРОЙДЯ НАШИ КУРСЫ, ВЫ НАУЧИТЕСЬ:</span></strong> </span></p>\r\n<table border="0">\r\n<tbody>\r\n<tr>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Увеличивать&nbsp;продажи на 20-120% и более при минимальных вложениях</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Выявлять перспективные направления развития компании и выстраивать эффективную маркетинговую стратегию</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Определять Уникальное торговое предложение&nbsp;вашего продукта&nbsp;</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Результативно использовать бесплатные и малобюджетные способы продвижения</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Самостоятельно настраивать&nbsp;эффективную рекламу в поисковых системах Яндекс и Google</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Создавать и вести "продающие" аккаунты и настраивать рекламу в соц. сетях</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Управлять&nbsp;репутацией компании</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Проводить&nbsp;маркетинговые исследования&nbsp;и грамотно использовать их в продвижении&nbsp;</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p style="text-align: center;"><span style="font-size: 10pt; font-family: Pro;"><a onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<hr />\r\n<p style="text-align: left;"><span style="font-family: Pro; font-size: 12pt;"><strong>Программа курса</strong></span></p>\r\n<p><strong><span style="font-family: Pro; color: #a22521;">&nbsp;<span style="font-size: 12pt;">Маркетинг</span></span></strong></p>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 194.24px;">\r\n<td style="background-color: #f7f7f7; height: 194.24px; width: 14.6761%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>1. Маркетинговый аудит положения компании на рынке</strong></span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 194.24px; width: 80.3239%;">\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">1) Как определить место компании на рынке?&nbsp;</span><span style="font-size: 10pt;">Ресурсы и способности вашей компании</span></span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Целевая аудитория и сегментирование клиентов. Определение основных сегментов аудитории.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) Позиционирование&nbsp;товара. Определяем конкурентные преимущества.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4) Анализ конкурентов и бенчмаркетинг. Как использовать конкурентов в достижении собственных целей.&nbsp;&nbsp;SWOT- анализ.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">5) Инновационный маркетинг - как непрерывное совершенствование продуктов, услуг</span></p>\r\n<p><span style="font-family: Pro;"><em><span style="font-size: 10pt;">Практика: проводим маркетинговый аудит положения компании на рынке и сегментируем клиентов. </span></em> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 14.6761%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 80.3239%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"></span></td>\r\n</tr>\r\n<tr style="height: 137px;">\r\n<td style="background-color: #f7f7f7; height: 137px; width: 14.6761%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2.&nbsp;Маркетинговые исследования. Взаимосвязь стратегии компании с маркетинговыми исследованиями</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 137px; width: 80.3239%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1) Для чего именно нам нужно проведение исследований? Анализ и эффективные стратегии</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Выбираем инструменты исследований: количественные и качественные исследования, полевые и кабинетные. Социологические и маркетинговые. Где искать данные, чтобы сэкономить на исследованиях и повысить их эффективность?</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) Использование маркетинговых исследований и маркетинговой информации в компании. Как сэкономить на исследованиях и включить в маркетинг каждого сотрудника компании?</span></p>\r\n<p><span style="font-family: Pro;"><em><span style="font-size: 10pt;">Практика: проводим исследования и определяем маркетинговую стратегию&nbsp; </span></em> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 14.6761%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 80.3239%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"></span></td>\r\n</tr>\r\n<tr style="height: 151px;">\r\n<td style="background-color: #f7f7f7; height: 151px; width: 14.6761%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong><span lang="EN-US">3.&nbsp;Торговый маркетинг&nbsp;</span></strong> </span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 151px; width: 80.3239%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1) Категорийный менеджмент&nbsp;и прибыльность товаров. Принцип Паретто. АВС анализ и матрица БКГ</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Принципы управления ассортиментной матрицей.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) УТП (уникальное торговое предложение). Как правильно определить свою уникальность? Какие признаки могут стать преимуществом вашего товара или услуги, а какие нет. &nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4) Ассортиментная политика компании. &nbsp;Как заработать на расширении ассортимента?&nbsp;</span></p>\r\n<p><span style="font-family: Pro;"><em><span style="font-size: 10pt;">Практика: формируем&nbsp; ассортиментную матрицу </span></em> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 14.6761%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 80.3239%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"></span></td>\r\n</tr>\r\n<tr style="height: 134px;">\r\n<td style="background-color: #f7f7f7; height: 134px; width: 14.6761%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>4.&nbsp;Ценообразование и управление ассортиментом</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 134px; width: 80.3239%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1)&nbsp;Ценообразование и ценовая стратегия. Как сформировать стоимость товара при разных позициях на рынке?&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2)&nbsp;Управление товарным ассортиментов на промышленных рынках и в сфере услуг</span></p>\r\n<p><span style="font-family: Pro;"><em><span style="font-size: 10pt;">Практика: Формируем&nbsp;УТП&nbsp;вашей компании с рыночным обоснованием&nbsp; и &nbsp;продвижением. </span></em> </span></p>\r\n<p><span style="font-family: Pro;"><em><span style="font-size: 10pt;">Практика: Определяем способы повышения клиентоориентированности вашей компании. </span></em> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 14.6761%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 80.3239%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"></span></td>\r\n</tr>\r\n<tr style="height: 243px;">\r\n<td style="background-color: #f7f7f7; height: 243px; width: 14.6761%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>5. Маркетинговые коммуникации.&nbsp;</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 243px; width: 80.3239%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1) Инструменты продвижения. Их возможности и недостатки. Современные технологии управления взаимоотношениями с клиентами.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Нейромаркетинг. Прямой маркетинг. &nbsp;Ивент-маркетинг. Public Relations.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) Понятия «бренд» и «брендинг». &nbsp;Чем бренд отличается от товара. Как создать бренд.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4) Подходы к оценке эффективности рекламных кампаний.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">5) Элементы бренда: как управлять популярностью торговой марки.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">6) Определение точек контакта с существующими и потенциальными клиентами.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">7) CRM. &nbsp;Как выстраивать взаимоотношения с клиентами с помощью современных автоматизированных систем.<br /></span></p>\r\n<p><span style="font-family: Pro;"><em><span style="font-size: 10pt;">Практика: считаем эффективность рекламных компаний </span></em> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 14.6761%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 80.3239%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"></span></td>\r\n</tr>\r\n<tr style="height: 120px;">\r\n<td style="background-color: #f7f7f7; height: 120px; width: 14.6761%;"><span style="font-family: Pro; font-size: 10pt;"><strong>6.&nbsp;Медиа планирование</strong></span></td>\r\n<td style="background-color: #f7f7f7; height: 120px; width: 80.3239%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1)&nbsp;Медиапланирование. Эффективная частота размещения рекламы по разным каналам продвижения.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2)&nbsp;Бюджетирование рекламных кампаний. &nbsp;Как эффективно распределять бюджеты, чтобы получать максимальный результат.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3)&nbsp;Подходы к оценке эффективности рекламных кампаний.</span></p>\r\n<p><span style="font-family: Pro;"><em><span style="font-size: 10pt;">Практика: составляем медиа-план </span></em> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 14.6761%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 80.3239%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"></span></td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 95%; background-color: #f7f7f7; height: 14px;" colspan="2"><span style="font-family: Pro; font-size: 10pt;"><strong>7.&nbsp;Формирование маркетингового плана вашей компании.</strong></span></td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 14.6761%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 80.3239%; height: 14px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 14.6761%; height: 14px;" colspan="2">&nbsp; <iframe style="background-image: url(''../img/iframe.png''); font-family: Pro; display: block; margin-left: auto; margin-right: auto;" src="https://www.youtube.com/embed/FnzVl_MZhYQ" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen" data-link="https://www.youtube.com/watch?v=FnzVl_MZhYQ"></iframe></td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 95%; height: 14px; text-align: center;" colspan="2">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 95%; height: 14px; text-align: left;" colspan="2"><span style="font-size: 12pt; font-family: Pro;"><strong style="color: #a22521;">Интернет-маркетинг</strong> </span></td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 95%; height: 14px; text-align: left;" colspan="2">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 10px;">\r\n<td style="background-color: #f7f7f7; height: 10px; width: 14.6761%;"><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">8.&nbsp;SEO: практические инструменты</span></strong> </span></td>\r\n<td style="background-color: #f7f7f7; height: 10px; width: 80.3239%;">\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;"><strong><span style="color: #800000;">Что&nbsp; изучите:</span> </strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Алгоритмы работы поисковых систем. Анализ поисковых запросов. Факторы, влияющие на ранжирование сайтов</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Сбор семантического ядра и его кластеризация. Изучение сервиса Wordstat.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Размещение контента на сайте: текстов, инфографика, заполнение метатегов, подбор изображений, видео.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">SEO-копирайтинг: правила написания продающих текстов в соответствии с алгоритмами поисковых систем.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Внутренняя перелинковка страниц. Схемы перелинковки.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Внешняя оптимизация сайта. Подбор площадок для размещения ссылок.</span></li>\r\n</ol>\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Какие навыки получите:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Сбор семантического ядра, кластеризация ключевых фраз.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Работа с сервисом Wordstat.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Подготовка технических заданий на SEO-копирайтинг.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Выбор подходящих площадок для внешней оптимизации.</span></li>\r\n</ol></td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="background-color: #ffffff; height: 14px; width: 14.6761%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; height: 14px; width: 80.3239%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 10px;">\r\n<td style="background-color: #f7f7f7; height: 10px; width: 14.6761%;"><span style="font-family: Pro; font-size: 10pt;"><strong>9.&nbsp;</strong><strong>Контекстная реклама: основы размещения рекламы в Яндекс и&nbsp;</strong><strong>Google</strong></span></td>\r\n<td style="background-color: #f7f7f7; height: 10px; width: 80.3239%;">\r\n<p style="text-align: justify;"><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Что освоите:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Виды рекламных кампаний.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Использование ключевых фраз: подбор подходящих, фильтрация минус-фраз.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Создание рекламных кампаний в Яндекс Директ и Google Adwords: регистрация в личном кабинете, базовые настройки, создание рекламных объявлений.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Изучение факторов, влияющих на стоимость клика.</span></li>\r\n</ol>\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Какие навыки&nbsp; получите:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Грамотный подбор ключевых фраз и составление эффективных объявлений.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Настройка рекламной кампании в личном кабинете Яндекс Директ и Google Adwords.</span></li>\r\n</ol></td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="background-color: #ffffff; height: 13px; width: 14.6761%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; height: 13px; width: 80.3239%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 10px;">\r\n<td style="background-color: #f7f7f7; height: 10px; width: 14.6761%;"><span style="font-family: Pro;"><strong><span style="font-size: 10pt;"><span lang="EN-US">10. Системы аналитики. Изучение Яндекс Метрики.</span></span> </strong> </span></td>\r\n<td style="background-color: #f7f7f7; height: 10px; width: 80.3239%;">\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Что&nbsp; проработаете:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Показатели, которые необходимо отслеживать.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Регистрация в Яндекс Метрике, знакомство с личным кабинетом.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Изучение отчетов в системе аналитики.</span></li>\r\n</ol>\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Какие&nbsp; навыки получите:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Понимание основных отчетов и показателей.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Настройка целей системе аналитики.</span></li>\r\n</ol></td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="background-color: #ffffff; height: 13px; width: 14.6761%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; height: 13px; width: 80.3239%;"><span style="font-family: Pro;">&nbsp;&nbsp;</span></td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="background-color: #f7f7f7; height: 13px; width: 14.6761%;"><span style="font-family: Pro;"><strong><span style="font-size: 10pt;"><span lang="EN-US">11.&nbsp;SMM. Работа в социальных сетях: Facebook, ВКонтакте, Instagram.</span></span> </strong> </span></td>\r\n<td style="background-color: #f7f7f7; height: 13px; width: 80.3239%;">\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Что изучите:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-size: 10pt; font-family: Pro;">Обзор возможностей социальных сетей.</span></li>\r\n<li><span style="font-size: 10pt; font-family: Pro;">Стратегии позиционирования.</span></li>\r\n<li><span style="font-size: 10pt; font-family: Pro;">Виды сообществ в каждой из социальных сетей.</span></li>\r\n<li><span style="font-size: 10pt; font-family: Pro;">Формирование контент-плана.</span></li>\r\n<li><span style="font-size: 10pt; font-family: Pro;">Знакомство с сервисами автопостинга (SMM Planner), сбора целевой аудитории (Церебро Таргет).</span></li>\r\n<li><span style="font-size: 10pt; font-family: Pro;">Бесплатные методы продвижения.</span></li>\r\n<li><span style="font-size: 10pt; font-family: Pro;">Запуск таргетированной рекламы в Facebook, ВКонтакте, Instagram.</span></li>\r\n</ol>\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Какие навыки&nbsp; получите:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-size: 10pt; font-family: Pro;">Создание сообщества для Вашего бизнеса.&nbsp;</span></li>\r\n<li><span style="font-size: 10pt; font-family: Pro;">Работа в программах автопостинга и сбора целевой аудитории.</span></li>\r\n<li><span style="font-size: 10pt; font-family: Pro;">Настройка таргетированной рекламы в каждой из социальных сетей: Facebook, ВКонтакте, Instagram.</span></li>\r\n</ol></td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="background-color: #ffffff; height: 13px; width: 14.6761%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; height: 13px; width: 80.3239%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="background-color: #f7f7f7; height: 13px; width: 14.6761%;"><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">12.&nbsp;Продвижение видео-канала на YouTube.</span></strong> </span></td>\r\n<td style="background-color: #f7f7f7; height: 13px; width: 80.3239%;">\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Что&nbsp; рассмотрите:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Виды видео-контента и особенности его подготовки.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Запуск видео-канала на YouTube, базовые настройки.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Разработка стратегии ведения канала.&nbsp;</span></li>\r\n</ol>\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Какие практические навыки:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Запуск видео-канала на YouTube.</span></li>\r\n<li style="text-align: left;"><span style="font-family: Pro; font-size: 10pt;">Базовые настройки канала для эффективного продвижения.</span></li>\r\n</ol></td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="background-color: #ffffff; height: 13px; width: 14.6761%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; height: 13px; width: 80.3239%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="background-color: #f7f7f7; height: 13px; width: 14.6761%;"><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">13.&nbsp;E-mail маркетинг: основы работы и запуск продающих рассылок.</span></strong> </span></td>\r\n<td style="background-color: #f7f7f7; height: 13px; width: 80.3239%;">\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Что&nbsp; освоите:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Сбор базы подписчиков – основные инструменты и сервисы.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Обзор основных инструментов для рассылок: плюсы и минусы.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Типы рассылок и выбор эффективной стратегии.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Создание цепочки писем и особенности формирования контента.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Знакомство с сервисом для рассылок Send Pulse.</span></li>\r\n</ol>\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Какие навыки получите:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Создание продающего электронного письма.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Настройка сервиса Send Pulse.</span></li>\r\n</ol></td>\r\n</tr>\r\n<tr style="background-color: #ffffff;">\r\n<td style="background-color: #ffffff;">&nbsp;</td>\r\n<td style="background-color: #ffffff;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="width: 14.6761%; height: 13px; background-color: #ffffff;" colspan="2"><iframe src="https://www.youtube.com/embed/6y0ZuxcwCeg" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture" style="background-image: url(''../img/iframe.png''); font-family: Pro; display: block; margin-left: auto; margin-right: auto;"></iframe></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<hr />\r\n<p><strong><span style="font-family: Pro; font-size: 12pt;">Формат обучения</span></strong></p>\r\n<p>&nbsp;</p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="font-size: 10pt;">•&nbsp;<strong>Очно</strong>. Продолжительность:&nbsp;</span><span style="font-size: 13.3333px; background-color: inherit; color: inherit;">6,5 недель, 3 раза в неделю, понедельник, среда, пятница с 18.30 до 21.30</span></span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="font-size: 10pt;"></span><span style="font-size: 10pt;">•&nbsp;<strong>Дистанционно</strong>: видео-лекции, аттестационные работы с обратной связью от преподавателя</span></span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-size: 13.3333px; font-family: Pro;">Формы обучения: информационные модули, дискуссии и мозговые штурмы, моделирование и анализ реальных ситуаций, практика самостоятельной работы</span></p>\r\n<hr />\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 12pt;">Акции и скидки:</span></strong> </span></p>\r\n<p>&nbsp;</p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit; color: inherit; font-size: 1rem;">•&nbsp;</span>Скидка 10%&nbsp;при оплате за 4 недели до обучения.&nbsp;&nbsp;</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit; color: inherit; font-size: 1rem;">•&nbsp;</span>Скидка 5%&nbsp;при оплате за 2 недели до обучения.</span></p>\r\n<p>&nbsp;</p>\r\n<p style="text-align: center;"><span style="font-family: Pro;"><a onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<hr />\r\n<p><span style="font-family: Pro;"></span></p>\r\n<table style="width: 100%; background-color: #ffffff;">\r\n<tbody>\r\n<tr style="height: 17px;">\r\n<td style="width: 10%; height: 17px; background-color: #f5f5f5; text-align: center;">\r\n<p style="text-align: center;"><span style="font-family: Pro;"><strong><span style="color: #800000;">ВЕДУЩИЙ</span></strong> </span></p>\r\n</td>\r\n<td style="width: 35%; height: 17px; background-color: #f5f5f5; text-align: left;">\r\n<p class="header" style="text-align: center;" data-qa="resume-personal-name"><span style="font-size: 10pt; font-family: Pro;"><strong><span style="color: #800000;">ИВАНОВА ТАТЬЯНА ВЛАДИМИРОВНА</span> </strong> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 17px;">\r\n<td style="width: 10%; height: 17px; background-color: #f5f5f5; text-align: center; vertical-align: middle;">\r\n<p><span style="font-family: Pro;"><img style="display: block; margin-left: auto; margin-right: auto;" src="images/prepodavatel_po_marketingy2.jpg" alt="обучение маркетингу" width="117" height="133" /></span></p>\r\n</td>\r\n<td style="width: 35%; height: 17px; background-color: #f5f5f5; text-align: center;">\r\n<p style="text-align: left;"><strong><span lang="EN-US" style="font-size: 10pt; font-family: Pro;">Эксперт-практик в области маркетинговых коммуникаций</span></strong></p>\r\n<p style="text-align: left; padding-left: 30px;"><span lang="EN-US" style="font-size: 10pt; font-family: Pro;">• Опыт работы в маркетинге&nbsp;<strong>более 14 лет</strong> </span></p>\r\n<p style="text-align: left; padding-left: 30px;"><span lang="EN-US" style="font-size: 10pt; font-family: Pro;"><span style="text-align: center; color: inherit; font-family: inherit; font-size: 1rem;">•&nbsp;</span>Опыт работы преподавателем&nbsp;<strong>более&nbsp;3 лет</strong> </span></p>\r\n<p style="text-align: left; padding-left: 30px;"><span style="font-size: 10pt; font-family: Pro;"><span style="text-align: center; color: inherit; font-family: inherit; font-size: 1rem;">•&nbsp;</span>Директор рекламного агентства, в числе клиентов:&nbsp;Coca-Cola, Loreal,&nbsp;Johnson &amp; Johnson, Метро, М.Видео, УБРиР, Леруа Мерлен,&nbsp;Nivea и другие</span></p>\r\n<p style="text-align: left;"><span style="font-family: Pro; font-size: 10pt;"><strong>Трудовая деятельность:</strong></span></p>\r\n<p style="text-align: left; padding-left: 30px;"><span style="font-family: Pro; font-size: 10pt;">2013 - по настоящее&nbsp;время&nbsp; директор филиала&nbsp;федерального рекламного агентства "Хорошие люди"</span></p>\r\n<p style="text-align: left; padding-left: 30px;"><span style="font-family: Pro; font-size: 10pt;">2008 - 2013 г.&nbsp;&nbsp;Зам. директора по маркетингу&nbsp;ТК "Агора" строительные и отделочные материалы оптовая и розничная&nbsp;торговля&nbsp;</span></p>\r\n<p style="text-align: left; padding-left: 30px;"><span style="font-family: Pro; font-size: 10pt;">2007&nbsp;- 2008&nbsp;г. -&nbsp;Руководитель отдела маркетинга и рекламы "Оникс" и "Цифра",&nbsp;сеть магазинов бытовой техники и электроники</span></p>\r\n<p style="text-align: left; padding-left: 30px;"><span style="font-family: Pro; font-size: 10pt;">2004 - 2007 г. - Зам. руководителя отд. маркетинга и рекламы, Федеральный дистрибьютор НТС «Градиент»,&nbsp;оптовая торговля косметикой</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<table style="width: 100%; background-color: #ffffff;">\r\n<tbody>\r\n<tr style="height: 17px;">\r\n<td style="width: 10%; height: 17px; background-color: #f5f5f5; text-align: center;">\r\n<p style="text-align: center;"><span style="font-family: Pro;"><strong><span style="color: #800000;">ВЕДУЩИЙ</span></strong> </span></p>\r\n</td>\r\n<td style="width: 35%; height: 17px; background-color: #f5f5f5; text-align: left;">\r\n<p class="header" style="text-align: center;" data-qa="resume-personal-name"><span style="font-size: 10pt; font-family: Pro;"><strong><span style="color: #800000;">ПОПОВ ДМИТРИЙ ПАВЛОВИЧ</span> </strong> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 17px;">\r\n<td style="width: 10%; height: 17px; background-color: #f5f5f5; text-align: center; vertical-align: middle;">\r\n<p><span style="font-family: Pro;"><img style="display: block; margin-left: auto; margin-right: auto;" src="images/popov_dmitri-2.jpg" alt="обучение маркетингу в екатеринбурге" width="113" height="149" /></span></p>\r\n</td>\r\n<td style="width: 35%; height: 17px; background-color: #f5f5f5; text-align: center;">\r\n<p style="text-align: left;"><strong><span style="font-family: Pro;">Специалист в области интернет коммуникаций,&nbsp;</span><span style="text-align: center; color: inherit; font-family: Pro; font-size: 10pt;">кандидат социологических наук</span></strong></p>\r\n<p style="text-align: left; padding-left: 30px;"><span style="font-family: Pro;"><span style="text-align: center; color: inherit; font-family: inherit; font-size: 1rem;">•&nbsp;</span>Более&nbsp;8 лет&nbsp;опыта работы в интернет-маркетинге</span></p>\r\n<p style="text-align: left; padding-left: 30px;"><span style="font-family: Pro;"><span style="text-align: center; color: inherit; font-family: inherit; font-size: 1rem;">•&nbsp;</span>Более&nbsp;5&nbsp;лет&nbsp;опыта работы&nbsp; преподавателем и бизнес - тренером</span></p>\r\n<p style="text-align: left; padding-left: 30px;"><span style="font-family: Pro;"><span style="text-align: center; color: inherit; font-family: inherit; font-size: 1rem;">•&nbsp;</span>Более 3 лет&nbsp;- руководитель проектов&nbsp;в сфере интернет-маркетинга и it-технологий</span></p>\r\n<p style="text-align: left;"><span style="font-family: Pro; font-size: 10pt;"><strong>Трудовая деятельность:</strong></span></p>\r\n<p style="text-align: left; padding-left: 30px;"><span style="font-family: Pro;">С&nbsp;2017 г. по настоящее время - Руководитель Web-студии федеральной компании Первый Бит,&nbsp; специализирующейся на интернет-продвижении и it-технологиях.</span></p>\r\n<p style="text-align: left; padding-left: 30px;"><span style="font-family: Pro;">2015 - 2016 гг. - руководитель проектов создания с нуля интернет - магазинов: строительство, косметика, продукты</span></p>\r\n<p style="text-align: left; padding-left: 30px;"><span style="font-family: Pro;">2011&nbsp;- 2014&nbsp;гг. - предпринимательская деятельность&nbsp; в интернет маркетинге и продажах.&nbsp;Руководитель, интернет-маркетолог, SEO - специалист, копирайтер</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>', '', 1, 26, '2016-08-01 08:11:31', 42, '', '2019-04-26 06:51:27', 42, 0, '0000-00-00 00:00:00', '2016-08-01 08:11:31', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 405, 5, 'Интернет маркетинг обучение Екатеринбург, Маркетинг обучение, Курсы интернет маркетинга в Екатеринбурге, Маркетинг и реклама обучение', 'Обучение маркетингу и интернет-маркетингу в Екатеринбурге. Очно и дистанционно. От экспертов-практиков. Скидки до 15%', 1, 14565, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(120, 205, 'Специалист в области планово-экономического обеспечения строительного производства', 'специалист-в-области-планово-экономического-обеспечения-строительного-производства-диплом-по-профстандарту', '<h1><span style="font-family: Pro;">Специалист в области планово-экономического обеспечения строительного производства. Диплом по профстандарту в {city_d}</span></h1>\r\n<p><span style="font-family: Pro;"><strong>Целевая аудитория:</strong>&nbsp;специалисты и руководители строительных организаций, финансовые менеджеры, работники планово-экономического отдела, бухгалтер, главный бухгалтер, экономист, сметчик</span></p>\r\n<p><span style="font-family: Pro;"><strong>Ведущие:&nbsp;</strong></span></p>\r\n<p><span style="font-family: Pro;"><!-- noindex --></span></p>\r\n<p><span style="font-family: Pro;"><a href="index.php?option=com_content&amp;view=article&amp;id=53&amp;catid=14">Романова Ульяна Владимировна</a>&nbsp;- руководитель финансового отдела, преподаватель</span><br /><span style="font-family: Pro;"><a href="index.php?option=com_content&amp;view=article&amp;id=117&amp;catid=2&amp;Itemid=112" rel="nofollow">Дубова Наталья Сергеевна</a>&nbsp;-&nbsp;руководитель проектного - сметного отдела</span></p>\r\n<p>&nbsp;</p>\r\n<p style="font-size: 12.16px; line-height: 15.808px; text-align: center;"><span style="font-size: 12pt; font-family: Pro;"><strong>На наших курсах вы разберете следующие моменты:</strong></span></p>\r\n<table>\r\n<tbody>\r\n<tr>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Корректный расчет себестоимости</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Анализ новшеств за 2018-2019 гг.&nbsp;</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Анализ хозяйственной деятельности</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Освоение системного подхода в принятии управленческих решений, связанных с бюджетированием и&nbsp;инвест-планированием</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Плановое и системное поступление денежных средств</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Оптимизацию затрат, бизнес-процессов</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p style="font-size: 12.16px; line-height: 15.808px; text-align: center;"><span style="font-family: Pro;"><a style="font-size: 13px;" onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro;">Выдается диплом о профпереподготовке. Курс&nbsp;разработан в соответствии с Профстандартом 983н: "Специалист в области планово-экономического обеспечения строительного&nbsp;производства"</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-size: 10pt; font-family: Pro;"><a href="#"><img src="images/shablon_diploma.jpg" alt="диплом сметное дело" width="30%" height="183" /></a>&nbsp;<a href="#"><img src="images/shablon_diploma_vnutri.jpg" alt="профпереподготовка сметное дело " width="30%" height="183" /></a>&nbsp;<a href="#"><img src="images/diplom_smetchika.jpg" alt="профпереподготовка сметчика диплом" width="30%" height="183" /></a></span></p>\r\n<hr />\r\n<p><span style="font-family: Pro;">&nbsp;<span style="font-size: 12pt;"><strong>Программа обучения</strong></span></span></p>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr>\r\n<td style="width: 97%; text-align: left;" colspan="3"><span style="font-family: Pro; font-size: 12pt;"><strong style="color: #a22521;">Модуль 1. Сметное ценообразование. Гранд-смета</strong>&nbsp;</span></td>\r\n</tr>\r\n<tr style="background-color: #f5f5f5;">\r\n<td style="width: 29.5855%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><b>1. Система ценообразования и сметного нормирования в строительстве</b></span></p>\r\n</td>\r\n<td style="width: 67.4145%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1)&nbsp;Виды сметных нормативов.&nbsp;Структура государственных элементных сметных&nbsp; норм.&nbsp;Структура единичных расценок&nbsp; ТЕР, ФЕР, ТСЦ, СЦП и др.сборники.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Нормативные документы, действующие в&nbsp; строительстве.&nbsp;Порядок составления и формы сметной&nbsp; документации.&nbsp;</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">3) Группа сборников на строительные работы. Составление сметы на отделочные работы.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">4) Общие сведения о системе ценообразования и сметного нормирования.&nbsp;Сметные нормы и сметные нормативы.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">5) Общие положения по определению стоимости строительства. Методы определения стоимости строительства.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">6) Порядок составления сметной документации: состав и формы сметной документации, понятие «накладные расходы», «сметная прибыль».</span></p>\r\n</td>\r\n<td style="width: 67.4145%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr>\r\n<td style="background-color: #ffffff;">&nbsp;</td>\r\n<td style="background-color: #ffffff;">&nbsp;</td>\r\n<td style="background-color: #ffffff;">&nbsp;</td>\r\n</tr>\r\n<tr style="background-color: #f5f5f5;">\r\n<td style="width: 29.5855%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2. Методы определения сметной стоимости строительства</strong></span></p>\r\n</td>\r\n<td style="width: 67.4145%;"><span style="font-family: Pro; font-size: 10pt;">1)<span style="background-color: #f5f5f5;">Составление&nbsp;</span>сметы на отделочные работы.&nbsp;</span>\r\n<p style="background-color: #f5f5f5;"><span style="font-family: Pro; font-size: 10pt;">2)&nbsp;Структура сметной стоимости строительства, порядок определения её элементов:</span></p>\r\n<p style="background-color: #f5f5f5;"><span style="font-family: Pro; font-size: 10pt;">- сметная стоимость материалов;</span></p>\r\n<p style="background-color: #f5f5f5;"><span style="font-family: Pro; font-size: 10pt;">- затраты на оплату труда рабочих;</span></p>\r\n<p style="background-color: #f5f5f5;"><span style="font-family: Pro; font-size: 10pt;">- затраты на эксплуатацию.</span></p>\r\n<p style="background-color: #f5f5f5;"><span style="font-family: Pro; font-size: 10pt;">3)&nbsp;Составление&nbsp;сметы на ремонтные работы.&nbsp;Группа сборников на ремонтные работы.</span></p>\r\n<p style="background-color: #f5f5f5;"><span style="font-family: Pro; font-size: 10pt;">4)&nbsp;Коэффициенты для учета особых условий производства работ.</span></p>\r\n<p style="background-color: #f5f5f5;"><span style="font-family: Pro; font-size: 10pt;">5)&nbsp;Cоставление&nbsp;сметы на проектные работы.</span></p>\r\n<p style="background-color: #f5f5f5;"><span style="font-family: Pro; font-size: 10pt;">6)&nbsp;Порядок определения&nbsp;сметной&nbsp;стоимости демонтажа&nbsp; конструкций и устройств.</span></p>\r\n<p style="background-color: #f5f5f5;"><span style="font-family: Pro; font-size: 10pt;">7)&nbsp;Группа сборников на монтажные работы, пусконаладочные работы.&nbsp;Составление сметы на монтаж оборудования, пусконаладочные работы, новое строительство.</span></p>\r\n</td>\r\n<td style="width: 67.4145%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr>\r\n<td style="background-color: #ffffff;">&nbsp;</td>\r\n<td style="background-color: #ffffff;">&nbsp;</td>\r\n<td style="background-color: #ffffff;">&nbsp;</td>\r\n</tr>\r\n<tr style="background-color: #f5f5f5;">\r\n<td style="width: 29.5855%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>3. Работа в программе Гранд Смета</strong></span></p>\r\n</td>\r\n<td style="width: 67.4145%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">1) Выбор сборника, &nbsp;состав информации по расценкам. Способы поиска расценок в базе.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">2) Действия с элементами строительства, параметры и структура локальной сметы, способы&nbsp; добавления позиций в смету.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">3) Состав информации по расценкам.Применения коэффициентов.&nbsp;</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">4) Составление локальных смет базисно - индексным методом.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">5) Способы замены ресурсов, действия с неучтенными материалами.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">6) Подведение итогов по смете.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">7) Накладные расходы и сметная прибыль: привязка к виду работ, использование укрупненных норм, применение поправочных коэффициентов.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">8) Лимитированные затраты.&nbsp;Добавление и удаление лимитированных затрат.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">9) Индексы пересчета в текущие цены: виды индексов, ввод и применение индексов вручную.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">10) Ввод в смету стоимости в текущих ценах.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">11) Применение коэффициентов на демонтажные работы.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">12) Работа с корректирующими позициями.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">13) Ресурсный метод. Ведомость ресурсов сметы.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">14) Работа с ценником: создание, использование, автоматическая загрузка цен.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">15) Проверка результатов. Подготовка и печать ресурсных смет.&nbsp;</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">16) Учет выполненных работ.&nbsp;Ввод выполненных объемов.&nbsp;Просмотр итогов выполнения работ.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">17) Подготовка и печать актов выполненных работ.&nbsp;</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">18) Подготовка и печать актов выполненных работ.&nbsp;КС2, КС3, КС - 6а ведомость дефектов и др.&nbsp;Формат сметы в Excel. &nbsp;</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">19) Операции с документами.&nbsp;Экспертиза сметы.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">20) Автоматический пересчет сметы.&nbsp;Составление объектных смет и сводных сметных расчетов.</span></p>\r\n</td>\r\n<td style="width: 67.4145%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr>\r\n<td style="width: 29.5855%; text-align: left;" colspan="3">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 29.5855%; text-align: left;" colspan="3"><span style="font-family: Pro;"><span style="font-size: 10pt;"><strong style="color: #a22521;">&nbsp;<span style="font-size: 12pt;">Модуль 2. Экономика и финансы</span></strong></span><span style="font-size: 12pt;"></span></span></td>\r\n</tr>\r\n<tr style="background-color: #f5f5f5;">\r\n<td style="width: 29.5855%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>1. Экономика предприятия</strong></span></p>\r\n</td>\r\n<td style="width: 67.4145%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1) Точка безубыточности. Анализ безубыточности.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Ключевой расчет маржинальной прибыли, чистой прибыли.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">3) Ключевые показатели эффективности предприятия,&nbsp; EBITDA, ROE.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">4) Анализ финансовых результатов деятельности.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">5) Анализ эффективности использования&nbsp; оборотных средств (оборачиваемость, материалоемкость). Нормирование.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">6) Анализ &nbsp;эффективности использования трудовых ресурсов (выработка, трудоемкость)</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro; font-size: 10pt;"><em>-&nbsp;Практические задания точки безубыточности и валовой маржи. Определение наиболее рентабельных проектов, видов деятельности, продукции.</em></span></p>\r\n</td>\r\n<td style="width: 67.4145%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr>\r\n<td style="width: 29.5855%;">&nbsp;</td>\r\n<td style="width: 67.4145%;">&nbsp;</td>\r\n<td style="width: 67.4145%;">&nbsp;</td>\r\n</tr>\r\n<tr style="background-color: #f5f5f5;">\r\n<td style="width: 29.5855%;"><span style="font-size: 10pt; font-family: Pro;"><strong>2. Организация аналитического учета затрат</strong></span></td>\r\n<td style="width: 67.4145%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">1) Бухгалтерский план счетов, с использованием которых осуществляется учет затрат на производство. Группировка балансовых статей, баланс предприятия,&nbsp; строение балансовых счетов.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">2) Затраты по статьям калькуляции. Учет отдельных видов затрат. Система " Директ - костинг".</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">3) Специфика и области применения различных методов учета производственных затрат: позаказного, котлового, попередельного.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">4) Классификация расходов и затрат,&nbsp; формирующих себестоимость продукции,&nbsp; их отличия.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro; font-size: 10pt;">-&nbsp;<i>Практические задания по расчету себестоимости и цены. Оптимизация затрат.</i>&nbsp;&nbsp;&nbsp;</span></p>\r\n</td>\r\n<td style="width: 67.4145%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr>\r\n<td style="width: 29.5855%;">&nbsp;</td>\r\n<td style="width: 67.4145%;">&nbsp;</td>\r\n<td style="width: 67.4145%;">&nbsp;</td>\r\n</tr>\r\n<tr style="background-color: #f5f5f5;">\r\n<td style="width: 29.5855%;"><span style="font-family: Pro; font-size: 10pt;"><strong>3. Финансовая отчетность. Основные методы финансового анализа</strong></span></td>\r\n<td style="width: 67.4145%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">1) Финансовый анализ, как метод оценки текущего и перспективного финансового состояния предприятия: трендовый, факторный, метод цепных подстановок, горизонтальный, вертикальный.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">2) Анализируем бухгалтерский баланс, в чем отличие от управленческого баланса.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">3) Особенности составления отчета о прибылях и убытках, отличие от Бюджета доходов и расходов.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">4) Коэффициенты финансового анализа: платежеспособность и&nbsp;ликвидность, &nbsp;коэффицииент инвестирования, коэффициенты финансовой устойчивости, деловой активности.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-size: 10pt; font-family: Pro;"><em>- Кейс по анализу финансовой отчетности.</em></span></p>\r\n</td>\r\n<td style="width: 67.4145%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr>\r\n<td style="width: 29.5855%;">&nbsp;</td>\r\n<td style="width: 67.4145%;">&nbsp;</td>\r\n<td style="width: 67.4145%;">&nbsp;</td>\r\n</tr>\r\n<tr style="background-color: #f5f5f5;">\r\n<td style="width: 29.5855%;"><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">4. Управление инвестициями</span></strong></span></td>\r\n<td style="width: 67.4145%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">1) Основные показатели, используемые для расчетов эффективности инвестиционного проекта.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">2) Чистый дисконтированный доход (NPV), индекс рентабельности инвестиций, внутренняя норма доходности.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">3) Срок окупаемости инвестиций. Резерв безопасности проекта.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">4) Управление заемным капиталом. Эффект финансового рычага.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">5) Стоимость капитала: ее составляющие и методы оценки.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">6) Ликвидность и способы ее оценки.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro; font-size: 10pt;"><i>- Практические задания по расчету оценки инвестиционных проектов</i>&nbsp;&nbsp;&nbsp;5. Эффективная финансово – экономическая служба.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-size: 10pt; font-family: Pro;">7) Требования к финансовой отчетности для руководителей.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-size: 10pt; font-family: Pro;">8) Принципы учетной политики управленческого учета.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-size: 10pt; font-family: Pro;">9) Чтение и интерпретации финансовых отчетов.&nbsp;</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-size: 10pt; font-family: Pro;">10) Функции финансового управляющего.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-size: 10pt; font-family: Pro;">11) Распределение функций финансово-экономической службы.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-size: 10pt; font-family: Pro;">12) Показатели эффективности финансовой службы.</span></p>\r\n</td>\r\n<td style="width: 67.4145%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr>\r\n<td style="width: 29.5855%;">&nbsp;</td>\r\n<td style="width: 67.4145%;">&nbsp;</td>\r\n<td style="width: 67.4145%;">&nbsp;</td>\r\n</tr>\r\n<tr style="background-color: #f5f5f5;">\r\n<td style="width: 29.5855%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>5. Бизнес-план - первый план компании. Как получить желаемый результат и не потерять вложенные средства, при реализации нового инвестиционного проекта</strong> </span></p>\r\n</td>\r\n<td style="width: 67.4145%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">1) Описание продукции и предприятия.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">2) Анализ рынка и маркетинговая стратегия. Выбор сегмента рынка. Анализ конкурентных преимуществ.&nbsp;Прогнозы объемов продаж - план продаж.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">3) Производственный план. Общий подход к организации производства.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">4) Финансовый план. Бюджетирование, как составная часть финансового планирования.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">5) Оценка рисков.</span></p>\r\n</td>\r\n<td style="width: 67.4145%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr>\r\n<td style="width: 29.5855%;">&nbsp;</td>\r\n<td style="width: 67.4145%;">&nbsp;</td>\r\n<td style="width: 67.4145%;">&nbsp;</td>\r\n</tr>\r\n<tr style="background-color: #f5f5f5;">\r\n<td style="width: 29.5855%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>6. Бюджетирование - как учесть системы управления предприятием</strong></span></p>\r\n</td>\r\n<td style="width: 67.4145%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">1) Сущность бюджетного управления, бюджет в системе планов предприятия.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">2) Постановка системы бюджетного управления:&nbsp; определение участников процесса бюджетного управления,&nbsp; определение центров финансовой ответственности, учета (ЦФО, ЦФУ).</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">3) Подходы к построению системы бюджетирования на предприятии.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">4) Регламентация системы бюджетирования на предприятии. Бюджетная система:&nbsp; Система бюджетов на предприятии: Бюджет продаж, бюджет производства, бюджет накладных расходов, бюджет доходов и расходов, бюджет движения денежных средств.&nbsp; Взаимосвязь основных плановых и отчетных форм между собой. Контроль исполнения бюджетов – ключевая функция системы бюджетного управления.&nbsp; Анализ исполнения бюджета.</span></p>\r\n<p style="margin: 0cm 0cm 0.0001pt;"><span style="font-family: Pro; font-size: 10pt;">-&nbsp;<i>Практические задания по разработке бюджетов, контроль и анализ. Причины невыполнения бюджетов.</i></span></p>\r\n</td>\r\n<td style="width: 67.4145%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr>\r\n<td style="width: 29.5855%;">&nbsp;</td>\r\n<td style="width: 67.4145%;">&nbsp;</td>\r\n<td style="width: 67.4145%;">&nbsp;</td>\r\n</tr>\r\n<tr style="background-color: #f5f5f5;">\r\n<td style="width: 29.5855%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>7. Практические примеры построения бюджетов в программе Excel - программа для управленческого учета и системы бюджетирования на предприятии</strong></span></p>\r\n</td>\r\n<td style="width: 67.4145%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1. Изучение&nbsp;наиболее востребованных&nbsp;формул и функций Excel&nbsp;для построения бюджетов.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2. Практические задания в&nbsp;Excel&nbsp;и 1 С «Бухгалтерия».</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-size: 10pt; font-family: Pro;">Работа с данными&nbsp;в&nbsp;Excel:</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-size: 10pt; font-family: Pro;">- поиск и замена данных, сортировка по значениям одного столбца, формату, &nbsp;столбцам, диапазону</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-size: 10pt; font-family: Pro;">- установка фильтра и работа с ним,&nbsp;отбор по значению, формату, условию, по ячейке</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-size: 10pt; font-family: Pro;">Сводные таблицы:</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-size: 10pt; font-family: Pro;">- форматирование сводной таблицы</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-size: 10pt; font-family: Pro;">- модификация таблицы</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-size: 10pt; font-family: Pro;">Поисковые, справочные и информационные функции. Базовые поисковые функции:</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-size: 10pt; font-family: Pro;">- вертикальный поиск ВПР() и горизонтальный поиск ГПР()</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-size: 10pt; font-family: Pro;">Создание сложных формул и выявление ошибок. Условия в формулах:</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-size: 10pt; font-family: Pro;">- построение условных формул: ЕСЛИ()</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-size: 10pt; font-family: Pro;">- расчет условных сумм с одним критерием СУММЕСЛИ()</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-size: 10pt; font-family: Pro;">Описательные имена для ссылок на ячейки:</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-size: 10pt; font-family: Pro;">- создание и использование именованного диапазона</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-size: 10pt; font-family: Pro;">- управление именованными диапазонами</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-size: 10pt; font-family: Pro;">Работа с текстом - Объединение строк текста: СЦЕПИТЬ()</span></p>\r\n</td>\r\n<td style="width: 67.4145%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><strong><span style="font-family: Pro; font-size: 12pt;">Формат курса:</span></strong></p>\r\n<p>&nbsp;</p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="font-size: 10pt;">•&nbsp;Очно</span>. Продолжительность:&nbsp;2,5-4 месяца.</span></p>\r\n<p>&nbsp;</p>\r\n<hr />\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 12pt;">Акции и скидки:</span></strong></span></p>\r\n<p>&nbsp;</p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit; color: inherit; font-size: 1rem;">•&nbsp;</span>Скидка 10%&nbsp;при оплате за 4 недели до обучения.&nbsp;&nbsp;</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit; color: inherit; font-size: 1rem;">•&nbsp;</span>Скидка 5%&nbsp;при оплате за 2 недели до обучения.</span></p>\r\n<p>&nbsp;</p>\r\n<p style="text-align: center;"><a style="font-size: 13px;" onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></p>\r\n<hr />\r\n<p><span style="color: #333333; font-family: Pro;"><span style="font-size: 16px;"><b>О нас</b></span></span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro;"><iframe style="background-image: url(''img/iframe.png''); display: block; margin-left: auto; margin-right: auto;" src="https://www.youtube.com/embed/yx3VnN5bh2k" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture"></iframe></span></p>', '', 1, 22, '2016-07-26 14:27:38', 42, '', '2019-04-26 05:32:42', 42, 0, '0000-00-00 00:00:00', '2016-07-26 14:27:38', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 59, 0, '', '', 1, 6667, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(108, 185, 'Диплом Контрактный управляющий. Специалист в сфере закупок. Переподготовка по 44 ФЗ ', 'диплом-о-переподготовке-44-фз-контрактный-управляющий-специалист-в-сфере-закупок', '<h1 style="text-align: center;"><span style="font-family: Pro;">Диплом о переподготовке по 44 ФЗ "Контрактная система в сфере закупок", с присвоением квалификации по профстандарту</span></h1>\r\n<p><span style="font-family: Pro;"><strong>Целевая аудитория:</strong> Руководители и специалисты государственных учреждений, тендерных отделов, контрактный управляющий.</span></p>\r\n<p>&nbsp;</p>\r\n<p style="text-align: center;"><span style="font-family: Pro;"><strong>Наши курсы включают в себя:</strong></span></p>\r\n<table>\r\n<tbody>\r\n<tr>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Практические знания и навыки&nbsp; работы с закупками</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Практику заполнения закупочной документации, план - график, анализ ошибок</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Работу в личном кабинете заказчика&nbsp;zakupki.gov.ru</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Анализ новшеств 2019 г.,&nbsp;типичные ошибки 44-ФЗ и 223-ФЗ от эксперта - практика</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Работу на сайтах&nbsp;&nbsp;zakupki.gov.ru&nbsp;&nbsp;sberbank-ast.ru&nbsp;&nbsp;</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Сроки, требования, споры, обжалование и арбитражная практика 44-ФЗ и 223-ФЗ</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Основы экономики и ценообразования&nbsp;товаров, работ, услуг.&nbsp;Деловые переговоры, конфликты</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Основы бюджетной&nbsp;системы, антимонопольного законодательства</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p style="text-align: center;"><span style="font-family: Pro; font-size: 10pt;"><a onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><span style="font-family: Pro;">Выдается диплом о переподготовке. Разработано в соответствии с Профстандартом 625н</span><span style="font-size: 10pt;"><a href="http://xn--d1ababe6aaeff9c5g.xn--p1ai/obrazovanie/kursy-yurista"><br /></a></span></span></p>\r\n<p><strong><span style="font-size: 10pt;"><a href="#"><img src="images/shablon_diploma.jpg" alt="обучение контрактных управляющих" width="33%" height="182" /></a>&nbsp;<a href="#"><img src="images/shablon_diploma_vnutri.jpg" alt="переподготовка контрактный управляющий диплом" width="33%" height="182" /></a>&nbsp;<a href="#"><img src="images/diplom_44fz_223fz.jpg" alt="курсы по 44 фз" width="33%" height="182" /></a></span></strong></p>\r\n<hr />\r\n<p>&nbsp;</p>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 27px;">\r\n<td style="background-color: #ffffff; height: 27px; width: 96%;" colspan="2"><span style="font-family: Pro;"><strong>МОДУЛЬ 1. Контрактная система</strong></span></td>\r\n</tr>\r\n<tr style="height: 60px;">\r\n<td style="background-color: #f7f7f7; height: 60px; width: 20.3783%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>1.&nbsp;Законодательное регулирование</strong></span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 60px; width: 75.6217%;">\r\n<p><span style="font-family: Pro;">1) Система и структура госзакупок: планирование - обоснование - закупка, способы закупки - исполнение контракта - контроль&nbsp;</span></p>\r\n<p><span style="font-family: Pro;">2) Федеральный закон № 44-ФЗ «О контрактной системе в сфере закупок товаров, работ, услуг для обеспечения государственных и муниципальных нужд»</span></p>\r\n<p><span style="font-family: Pro;">3) Гражданский кодекс, Бюджетный кодекс, Федеральный закон № 135-ФЗ «О защите конкуренции»</span></p>\r\n<p><span style="font-family: Pro;">4) Постановления Правительства РФ, Указы Президента РФ, нормативные и методические документы Минэкономразвития России и иных федеральных органов исполнительной власти</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 20.3783%; height: 14px;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 75.6217%; height: 14px;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 137px;">\r\n<td style="background-color: #f7f7f7; height: 137px; width: 20.3783%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>2. Общие вопросы</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 137px; width: 75.6217%;">\r\n<p><span style="font-family: Pro;">1) Особенности планов закупок, планов-графиков на 2019 год</span></p>\r\n<p><span style="font-family: Pro;">2) Обоснование закупок. Признание закупки необоснованной</span></p>\r\n<p><span style="font-family: Pro;">3) Условия выбора метода определения начальной максимальной цены. Способы ее расчета.</span></p>\r\n<p><span style="font-family: Pro;">4) Требования к участникам закупки: основные и дополнительные. Условия допуска к участию в закупках. Анализ «типичных» ошибок</span></p>\r\n<p><span style="font-family: Pro;">5) Антидемпинговые меры в контрактной системе</span></p>\r\n<p><span style="font-family: Pro;">6) Система способов определения поставщиков (подрядчиков, исполнителей) в контрактной системе: сравнительная характеристика, условия применения и особенности</span></p>\r\n<p><span style="font-family: Pro;">7) Правила описания объекта закупки в соответствии с законом № 44-ФЗ</span></p>\r\n<p><span style="font-family: Pro;">8) Обеспечение заявок на конкурсах и аукционах. Размер и формы</span></p>\r\n<p><span style="font-family: Pro;">9) Требования к банковской гарантии. Реестр банковских гарантий</span></p>\r\n<p><span style="font-family: Pro;">10) Обеспечение исполнения контракта. Размер и формы</span></p>\r\n<p><span style="font-family: Pro;">11) Закупки у субъектов малого предпринимательства</span></p>\r\n<p><span style="font-family: Pro;">12) Признание процедур несостоявшимися. Отмена процедур</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 20.3783%; height: 14px;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 75.6217%; height: 14px;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 151px;">\r\n<td style="background-color: #f7f7f7; height: 151px; width: 20.3783%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong><span lang="EN-US">3.&nbsp;Проведение госзакупок</span></strong> </span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 151px; width: 75.6217%;">\r\n<p><span style="font-family: Pro;">1)&nbsp;Выбор способа закупки: обоснование, условия применения определенного способа.</span></p>\r\n<p><span style="font-family: Pro;">2)&nbsp;Порядок подготовки документации для проведения закупки (ее содержание)</span></p>\r\n<p><span style="font-family: Pro;">3) Порядок подготовки технического задания: содержание, алгоритм согласования</span></p>\r\n<p><span style="font-family: Pro;">4) Порядок проведения конкурсов и аукционов&nbsp;</span></p>\r\n<p><span style="font-family: Pro;">5) Порядок проведения запросов котировок и запросов&nbsp;предложений</span></p>\r\n<p><span style="font-family: Pro;">6) Закупка у единственного поставщика (исполнителя, подрядчика). Алгоритм осуществления закупки у единственного поставщика</span></p>\r\n<p><span style="font-family: Pro;">7) Права и обязанности заказчика, специализированной организации при проведении закупки</span></p>\r\n<p><span style="font-family: Pro;">8) Условия допуска к проведению торгов участников</span></p>\r\n<p><span style="font-family: Pro;">9) Критерии и порядок оценки заявок</span></p>\r\n<p><span style="font-family: Pro;">10) Возможные типичные ошибки участников торгов, необходимые действия по минимизации рисков.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 20.3783%; height: 14px;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 75.6217%; height: 14px;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 134px;">\r\n<td style="background-color: #f7f7f7; height: 134px; width: 20.3783%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>4.&nbsp;Контракт</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 134px; width: 75.6217%;">\r\n<p><span style="font-family: Pro;">1) Понятия договора, контракта. Виды контрактов. Библиотека типовых контрактов</span></p>\r\n<p><span style="font-family: Pro;">2)&nbsp;Банковское сопровождение контрактов</span></p>\r\n<p><span style="font-family: Pro;">3) Существенные условия контракта. Требования к структуре и содержанию контракта. Приложения</span></p>\r\n<p><span style="font-family: Pro;">4)&nbsp;Порядок приемки товаров, работ, услуг</span></p>\r\n<p><span style="font-family: Pro;">5) Ответственность сторон по контракту: пени и штрафы, новые правила определения</span></p>\r\n<p><span style="font-family: Pro;">6) Правила и порядок изменения контракта. Дополнительные соглашения</span></p>\r\n<p><span style="font-family: Pro;">7)&nbsp;Правила и порядок расторжения контракта. Алгоритм одностороннего отказа от исполнения контракта</span></p>\r\n<p><span style="font-family: Pro;">8) Уклонение поставщика от подписания контракта. Отказ от заключения контракта заказчиком</span></p>\r\n<p><span style="font-family: Pro;">9) Реестр контрактов</span></p>\r\n<p><span style="font-family: Pro;">10) Отчет об исполнении контракта (этапа исполнения контракта): подготовка и размещение в ЕИС (на ООС)</span></p>\r\n<p><span style="font-family: Pro;">11) Экспертиза исполнения контракта.&nbsp;Виды экспертиз. Требования к экспертному заключению. Требования к экспертам и экспертным организациям</span></p>\r\n<p><span style="font-family: Pro;">&nbsp;- Как внести нужные изменения (увеличить цену) в уже заключенный контракт?</span><br /><span style="font-family: Pro;">&nbsp;- Что делать, если сторона не выполняет своих обязательств?</span><br /><span style="font-family: Pro;">&nbsp;- Процедура расторжения контракта - почему, как, в каких случаях?</span><br /><span style="font-family: Pro;">&nbsp;- Как минимизировать или вовсе избежать штрафных санкций?</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 20.3783%; height: 14px;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 75.6217%; height: 14px;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 127px;">\r\n<td style="background-color: #f7f7f7; height: 127px; width: 20.3783%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>5.&nbsp;Контроль, аудит, мониторинг, обжалование</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 127px; width: 75.6217%;">\r\n<p><span style="font-family: Pro;">1) Защита интересов заказчиков и поставщиков. Противодействие недобросовестным действиям заказчиков и поставщиков</span></p>\r\n<p><span style="font-family: Pro;">2) Способы защиты от недобросовестных поставщиков</span></p>\r\n<p><span style="font-family: Pro;">3) Реестр недобросовестных поставщиков. Порядок внесения информации</span></p>\r\n<p><span style="font-family: Pro;">4) Практика контроля центрального аппарата и территориальных органов ФАС России. Плановые и внеплановые проверки</span></p>\r\n<p><span style="font-family: Pro;">5) Порядок подачи и рассмотрения жалоб. Результаты обжалования</span></p>\r\n<p><span style="font-family: Pro;">7) Анализ типичных&nbsp;нарушений заказчиков, комиссий. Практические примеры</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 20.3783%; height: 14px;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 75.6217%; height: 14px;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 107.851px;">\r\n<td style="background-color: #f7f7f7; height: 107.851px; width: 20.3783%;"><span style="font-size: 10pt; font-family: Pro;"><strong>6.&nbsp;Практика в ЕИС</strong></span></td>\r\n<td style="background-color: #f7f7f7; height: 107.851px; width: 75.6217%;">\r\n<p><span style="font-family: Pro;">1) Формирование и размещение плана закупок</span></p>\r\n<p><span style="font-family: Pro;">2) Детальная подготовка технического задания</span></p>\r\n<p><span style="font-family: Pro;">3) Распорядительная документации по процедурам закупок - конкурса, аукциона, запроса котировок, запроса предложений.</span></p>\r\n<p><span style="font-family: Pro;">4) Рассмотрение документации для проведения торгов, личный кабинет заказчика&nbsp;zakupki.gov.ru&nbsp;</span></p>\r\n<p><span style="font-family: Pro;">5) Аукционная и конкурсная документации для проведения процедуры закупки</span></p>\r\n<p><span style="font-family: Pro;">6) Проверка&nbsp;извещения и заявки, подписание контракта и отчетность по контракту</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 27px;">\r\n<td style="background-color: #ffffff; height: 27px; width: 96%;" colspan="2">\r\n<p>&nbsp;<span style="font-family: Pro;"><strong>МОДУЛЬ 2.&nbsp;Основы экономики и ценообразования (видео-лекции, самостоятельные работы)</strong></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 60px;">\r\n<td style="background-color: #f7f7f7; height: 60px; width: 20.3783%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>1.&nbsp;Экономика предприятия</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 60px; width: 75.6217%;">\r\n<p><span style="font-family: Pro;">1) Показатели финансовых результатов. Классификация постоянных и переменных затрат. Точка безубыточности.</span></p>\r\n<p><span style="font-family: Pro;">2) Ключевой расчет маржинальной прибыли, чистой прибыли</span></p>\r\n<p><span style="font-family: Pro;">3) Ключевые показатели эффективности предприятия,&nbsp; EBITDA, ROE</span></p>\r\n<p><span style="font-family: Pro;">4) Анализ финансовых результатов деятельности</span></p>\r\n<p><span style="font-family: Pro;">5) Анализ эффективности использования&nbsp; оборотных средств. Нормирование.</span></p>\r\n<p><span style="font-family: Pro;">6) Анализ &nbsp;эффективности использования трудовых ресурсов.&nbsp;</span></p>\r\n<p><span style="font-family: Pro;"><em>-&nbsp;Практические задания точки безубыточности и валовой маржи. Определение наиболее рентабельных проектов, видов деятельности, продукции</em></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 20.3783%; height: 14px;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><em><strong>&nbsp;</strong></em></span></td>\r\n<td style="width: 75.6217%; height: 14px;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><em>&nbsp;</em></span></td>\r\n</tr>\r\n<tr style="height: 137px;">\r\n<td style="background-color: #f7f7f7; height: 137px; width: 20.3783%;">\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;"><strong>2.&nbsp;</strong></span><span style="font-size: 10pt;"><strong>Учет затрат </strong></span><span style="font-size: 10pt;"><strong>и ценообразование</strong></span></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 137px; width: 75.6217%;">\r\n<p><span style="font-family: Pro;">1) Бухгалтерский учет, группировка балансовых статей, баланс предприятия,&nbsp; строение балансовых счетов.</span></p>\r\n<p><span style="font-family: Pro;">2) Затраты по статьям калькуляции. Учет отдельных видов затрат.&nbsp;</span></p>\r\n<p><span style="font-family: Pro;">3) Классификация расходов и затрат,&nbsp; формирующих себестоимость продукции,&nbsp; их отличия</span></p>\r\n<p><span style="font-family: Pro;">4) Различные методы ценообразования&nbsp;</span></p>\r\n<p><span style="font-family: Pro;"><em>-&nbsp;Практические задания по расчету себестоимости и цены. Оптимизация затрат. &nbsp;</em></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 22.955px;">\r\n<td style="background-color: #ffffff;" colspan="2">\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro;"><strong>МОДУЛЬ 3. Деловые переговоры, конфликты (видео-лекции и самостоятельная работа)</strong></span></p>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr style="height: 22.955px;">\r\n<td style="background-color: #ffffff;" colspan="2"><span style="font-family: Pro;"><strong>МОДУЛЬ 4. Основы бюджетной системы и антимонопольного законодательства (тест)</strong></span></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<hr />\r\n<p><span style="font-family: Pro;"><strong style="text-indent: -9pt; background-color: inherit; color: inherit; font-family: inherit; font-size: 12pt;">Формат обучения:</strong></span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p><span style="font-family: Pro;"><strong style="color: #a22521;">Варианты очного обучения:</strong><span style="background-color: inherit;"><br /></span></span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit;">•&nbsp; 44 ФЗ - 260 учебных часа (40 очных часов). Рекомендуемое количество очных часов Минобрнауки,&nbsp;<br />&nbsp;</span>Очно<strong>:&nbsp; с 27.05 - 31.05.19&nbsp;</strong> с 09.00 до 16.30&nbsp; -&nbsp; 5&nbsp; дней. Стоимость&nbsp; со скидкой от 22 500 руб.</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit; color: inherit; font-size: 1rem;">•&nbsp;&nbsp;</span>44 ФЗ + 223 ФЗ&nbsp; - 295 учебных часов&nbsp; (48 очных часов). Рекомендуемое количество очных часов Минобрнауки,&nbsp;</span><br /><span style="font-family: Pro;">&nbsp;Очно:&nbsp;<strong> с 27.05 - 01.06.19&nbsp;</strong> с 09.00 до 16.30 - 6&nbsp; дней. Стоимость со скидкой от 24 300 руб.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span></p>\r\n<p><span style="font-family: Pro;"><strong style="color: #a22521;">Дистанционное обучение:</strong>&nbsp;видео-лекции, аттестационные работы</span></p>\r\n<hr />\r\n<p>&nbsp;<span style="font-family: Pro;"><strong><span style="font-size: 12pt;">Акции и скидки:</span></strong> </span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit; color: inherit; font-size: 1rem;">•&nbsp;</span><strong style="color: #a22521;">Скидка 10%</strong>&nbsp;при оплате за 3 недели до обучения.&nbsp;&nbsp;</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit; color: inherit; font-size: 1rem;">•&nbsp;</span><strong style="color: #a22521;">Скидка 5%</strong>&nbsp;при оплате за 2 недели до обучения.</span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p style="text-align: center;"><span style="font-family: Pro;"><a onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<hr />\r\n<table>\r\n<tbody>\r\n<tr>\r\n<td style="background-color: #f5f5f5; color: #333333; vertical-align: middle; text-align: center;"><span style="font-size: 12pt; font-family: Pro;"><strong>Преподаватель&nbsp;</strong></span></td>\r\n<td style="background-color: #f5f5f5; color: #333333; vertical-align: middle; text-align: center;">\r\n<p style="color: #333333; background-color: #f5f5f5; vertical-align: middle; text-align: center;"><span style="font-size: 12pt; font-family: Pro;"><strong>Рогожникова Елена Сергеевна</strong> </span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="background-color: #f5f5f5; vertical-align: middle;"><span style="font-family: Pro;"><img style="display: block; margin-left: auto; margin-right: auto;" src="images/DSC002712.jpg" alt="диплом по 44 и 223 фз" width="110" height="136" /></span></td>\r\n<td style="background-color: #f5f5f5;">\r\n<p><strong><span style="color: inherit; font-family: Pro; font-size: 10pt;">Начальник тендерного и юридического отдела</span></strong></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">• 15 летний опыт работы по специализации&nbsp;</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">•&nbsp;Опыт работы преподавателем по госзакупкам более 9 лет&nbsp; &nbsp;</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">•&nbsp;Опыт работы в ФАС специалистом отдела контроля госзаказов</span></p>\r\n<p><strong><span style="font-family: Pro;">Разработаны и проведены программы:</span></strong></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">• Базовые учебные программы для Заказчиков и Участников по 44-ФЗ, 223-ФЗ</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">•&nbsp;275 - ФЗ, Гособоронзаказ</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">•&nbsp;Тендер - менеджер, закупки по 223 ФЗ</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">• И другие</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<hr />\r\n<p><span style="font-family: Pro;"><span style="font-size: 12pt;"><b>О нас</b></span>&nbsp;</span>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p><iframe style="background-image: url(''img/iframe.png''); display: block; margin-left: auto; margin-right: auto;" src="https://www.youtube.com/embed/yx3VnN5bh2k" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture"></iframe></p>\r\n<p>&nbsp;</p>', '', 1, 16, '2016-02-15 14:27:45', 42, '', '2019-04-25 07:24:39', 42, 0, '0000-00-00 00:00:00', '2016-02-15 14:27:45', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 228, 4, 'Диплом Контрактный управляющий, обучение специалист в сфере закупок по 44 фз', 'Диплом Контрактный управляющий. Переподготовка по 44 ФЗ специалист в сфере закупок. Стоимость 26.000 руб. Продолжительность 260 часов', 1, 19467, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(107, 184, 'Бизнес-планирование', 'бизнес-планирование-обучение', '<h1 style="text-align: justify;"><!-- [if gte mso 9]><xml>\r\n <o:OfficeDocumentSettings>\r\n  <o:AllowPNG/>\r\n </o:OfficeDocumentSettings>\r\n</xml><![endif]--></h1>\r\n<h1><span style="font-family: Pro;">Как написать бизнес план? – Пройдите курсы бизнес-планирования&nbsp;в {city_d}</span></h1>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>Целевая аудитория: </strong>руководители, финансовые менеджеры, работники планово-экономического отдела, бухгалтер, главный бухгалтер</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>Ведущий</strong><strong>:</strong>&nbsp;<a href="index.php?option=com_content&amp;view=article&amp;id=53&amp;catid=14">Романова Ульяна Владимировна</a>&nbsp;- руководитель финансового отдела, преподаватель</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">Для того чтобы получить желаемый результат и не потерять вложенные средства при реализации нового инвестиционного проекта (создание нового бизнеса, расширение имеющегося) необходимо тщательно проработать и спрогнозировать развитие событий на всех этапах его развития. В рамках прединвестиционного планирования составляется такой документ, как бизнес-план.</span></p>\r\n<p>&nbsp;</p>\r\n<p style="text-align: center;"><span style="font-size: 10pt; font-family: Pro;"><a onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><span style="font-family: Pro;">Стоимость:&nbsp;14000 руб.&nbsp;Выдается удостоверение о повышении квалификации</span><br /></span></p>\r\n<p>&nbsp;&nbsp; <a href="#"><img src="images/Udostoverenie_oblozhka.jpg" alt="бизнес план удостоверение" width="45%" height="261" />&nbsp;&nbsp;</a>&nbsp; <a href="#"><img src="images/udostoverenie_business-planirovanie.jpg" alt="бизнес план удостоверение обучение" width="45%" height="261" /></a></p>\r\n<hr />\r\n<p>&nbsp;<span style="font-family: Pro; font-size: 12pt;"><strong>Программа обучения:</strong></span></p>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 181px;">\r\n<td style="background-color: #f7f7f7; height: 181px; width: 22.8632%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>1.&nbsp; Управление инвестициями</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 181px; width: 75.641%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1) Основные показатели, используемые для расчетов эффективности инвестиционного проекта</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Чистый дисконтированный доход (NPV)</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) Индекс рентабельности инвестиций</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4) Внутренняя норма доходности</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">5) Срок окупаемости инвестиций</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">6) Управление заемным капиталом</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">7) Стоимость капитала: ее составляющие и методы оценки.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">8) Ликвидность и способы ее оценки</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong><em>-&nbsp;Практические задания по расчету оценки инвестиционных проектов</em></strong>&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="background-color: #ffffff; height: 13px; width: 22.8632%;">&nbsp;</td>\r\n<td style="background-color: #ffffff; height: 13px; width: 75.641%;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 42px;">\r\n<td style="background-color: #f7f7f7; height: 42px; width: 22.8632%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2. Бизнес-план – первый план компании.</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 42px; width: 75.641%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1) Описание продукции и предприятия</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Анализ рынка и маркетинговая стратегия. Выбор сегмента рынка. Анализ конкурентных преимуществ. Прогнозы объемов продаж - план продаж.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) Производственный план. Общий подход к организации производства</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4) Финансовый план. Бюджетирование, как составная часть финансового планирования</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">5) Оценка рисков.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 3px;">\r\n<td style="background-color: #ffffff; height: 3px; width: 22.8632%;">&nbsp;</td>\r\n<td style="background-color: #ffffff; height: 3px; width: 75.641%;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 9px;">\r\n<td style="background-color: #f7f7f7; height: 9px; width: 22.8632%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>3.&nbsp;</strong><strong>Бюджетирование – как часть системы управления предприятием.</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 9px; width: 75.641%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1) Сущность бюджетного управления, бюджет в системе планов предприятия;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Постановка системы бюджетного управления:&nbsp; определение участников процесса бюджетного управления,&nbsp; определение центров финансовой ответственности, учета (ЦФО, ЦФУ);</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) Подходы к построению системы бюджетирования на предприятии;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4) Регламентация системы бюджетирования на предприятии. Бюджетная система:&nbsp; Система бюджетов на предприятии: Бюджет продаж, бюджет производства, бюджет накладных расходов, бюджет доходов и расходов, бюджет движения денежных средств.&nbsp; Взаимосвязь основных плановых и отчетных форм между собой. Контроль исполнения бюджетов – ключевая функция системы бюджетного управления.&nbsp; Анализ исполнения бюджета.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">&nbsp;<strong>-&nbsp;<em>Практические задания по разработке бюджетов, контроль и анализ. Причины невыполнения бюджетов.</em></strong></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 3.30226px;">\r\n<td style="background-color: #ffffff; height: 3.30226px; width: 22.8632%;">&nbsp;</td>\r\n<td style="background-color: #ffffff; height: 3.30226px; width: 75.641%;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 9px;">\r\n<td style="background-color: #f7f7f7; height: 9px; width: 22.8632%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>5.&nbsp;</strong><strong>Практические примеры построения&nbsp; бюджетов в программе Excel&nbsp;</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 9px; width: 75.641%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><em>1) Изучение</em>&nbsp;<em>наиболее востребованных&nbsp;формул и функций Excel</em>&nbsp;для построения бюджетов.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><em>2) Практические задания в&nbsp;</em><em>Excel</em><em>&nbsp;и 1 С «Бухгалтерия».</em></span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">&nbsp;Создание сложных формул и выявление ошибок. Условия в формулах,&nbsp;сводные таблицы</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">1) Поиск и замена данных, сортировка по значениям одного столбца, формату, нескольким столбцам, части диапазона</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Установка фильтра и работа с ним</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) Отбор по значению, формату, условию, по ячейке, отбор наибольших и наименьших значений, отказ от отбора</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">4) Создание сводной таблицы</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">5) Форматирование сводной таблицы</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">6) Модификация таблицы</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">7) Вертикальный поиск ВПР() и горизонтальный поиск ГПР()</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">8) Расчет и подсчет указанных ячеек: СЧЕТЕСЛИ()</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span style="font-size: 12pt;"><strong><span style="font-family: Pro;">Формат курса</span></strong> </span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro;">&nbsp; &nbsp; &nbsp; &nbsp;<span style="font-size: 10pt;">&nbsp;&nbsp;•&nbsp;Очное обучение. Продолжительность:&nbsp;</span><span style="font-size: 13.3333px; background-color: inherit; color: inherit;">4 недели, 2 раза в неделю, понедельник и среда с 18.30 до 21.30</span></span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;•&nbsp;Дистанционное обучение. Формат: видео-лекции, аттестационные работы</span></p>\r\n<hr />\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 12pt;">Акции и скидки:</span></strong> </span></p>\r\n<p>&nbsp;</p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit; color: inherit; font-size: 1rem;">•&nbsp;</span>Скидка 10%&nbsp;при оплате за 4 недели до обучения.&nbsp;&nbsp;</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit; color: inherit; font-size: 1rem;">•&nbsp;</span>Скидка 5%&nbsp;при оплате за 2 недели до обучения.</span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p style="text-align: center;"><span style="font-family: Pro;"><a href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<hr />\r\n<table>\r\n<tbody>\r\n<tr>\r\n<td style="border-color: #ffffff; background-color: #f5f5f5; text-align: center;">\r\n<p><span style="font-family: Pro; font-size: 12pt;"><strong>Ведущий</strong></span></p>\r\n</td>\r\n<td style="border-color: #ffffff; background-color: #f5f5f5; text-align: center;">\r\n<p><span style="font-family: Pro; font-size: 12pt;"><b>Романова Ульяна Владимировна</b></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="border-color: #ffffff; background-color: #f5f5f5; text-align: center; vertical-align: middle;"><span style="font-family: Pro;"><img style="background-color: #ffffff;" src="images/pomanova3.jpg" alt="как написать бизнес план" width="93" height="114" /></span></td>\r\n<td style="border-color: #ffffff; background-color: #ffffff;">\r\n<p><span style="font-family: Pro;">Высококвалифицированный специалист в области финансов, преподаватель</span></p>\r\n<p><span style="font-family: Pro;">Опыт работы преподавателем более&nbsp;3 лет</span></p>\r\n<p><span style="font-family: Pro;">15-летний опыт&nbsp;работы по специализации</span></p>\r\n<p><span style="font-family: Pro;"><strong>Трудовая деятельность:</strong></span></p>\r\n<p><span style="font-family: Pro;">с 2016 г. по&nbsp; настоящее время - руководитель группы&nbsp;бюджетирования и казначейства&nbsp;ГК Сторинг</span></p>\r\n<p><span style="font-family: Pro;">2012 - 2014&nbsp;г. - Финансовый директор успешного проекта сети фитнесс-клубов DriveFitnes</span></p>\r\n<p><span style="font-family: Pro;">2007 - 2011 г. - Финансовый директор, главный бухгалтер оптово-розничной компании Россахар</span></p>\r\n<p><span style="font-family: Pro;">2006 - 2007 г. - главный бухгалтер Уралтемпстрой</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<hr />\r\n<p><span style="color: #333333; font-family: Pro;"><span style="font-size: 16px;"><b>О нас</b></span></span></p>\r\n<p><iframe style="background-image: url(''img/iframe.png''); display: block; margin-left: auto; margin-right: auto;" src="https://www.youtube.com/embed/yx3VnN5bh2k" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture"></iframe></p>', '', 1, 14, '2016-01-27 09:46:47', 42, '', '2019-04-25 07:39:12', 42, 0, '0000-00-00 00:00:00', '2016-01-27 09:46:47', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 51, 2, 'как создать бизнес план, как написать бизнес план, как сделать бизнес план, бизнес план написание', 'Как создать бизнес-план? Мы научим! Курсы бизнес-планирования в Екатеринбурге. Очно и дистанционно. Записывайтесь', 1, 22541, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(241, 448, 'Профессия специалист по тендерам (торгам), что за работа: функционал и зарплата', 'профессия-специалист-по-тендерам-торгам-,-что-за-работа-требования-и-зарплата', '<h1>Профессия&nbsp;специалист по тендерам (торгам), уровень зарплаты и требования к&nbsp;работе</h1>\r\n<p><span style="font-size: 10pt;">Заработная плата на рынке специалиста электронных торгов колеблется&nbsp; от 30.000 до 50.000 рублей. В привязке к процентам от выигранных тендеров будет составлять до 150&nbsp;000 рублей. Опыт работы во многом влияет на уровень оплаты. Профессия специалиста по&nbsp;тендерам предусматривает&nbsp;в основном знание законодательства и практический опыт по закупкам 44 ФЗ и 223 ФЗ, а также:</span></p>\r\n<p><span style="font-size: 10pt;"><strong>Какие же требования&nbsp; предъявляют работодатели для данной вакансии:</strong></span></p>\r\n<ul>\r\n<li><span style="font-size: 10pt;">законченное высшее образование</span></li>\r\n<li><span style="font-size: 10pt;">навыки делового общения</span></li>\r\n<li><span style="font-size: 10pt;">аналитические способности, внимательность, умение работать с большими массивами данных</span></li>\r\n<li><span style="font-size: 10pt;">знание законодательства в сфере закупок (223 и 44-ФЗ), наличие документа по проф.обучению</span></li>\r\n<li><span style="font-size: 10pt;">опыт работы с площадками</span></li>\r\n<li><span style="font-size: 10pt;">знание и ведение тендерной документации и прочего документооборота</span></li>\r\n</ul>\r\n<p><span style="font-size: 10pt;"><strong>Какой функционал:</strong></span></p>\r\n<ul>\r\n<li><span style="font-size: 10pt;">составление и ведение Плана закупок и отчетности по нему</span></li>\r\n<li><span style="font-size: 10pt;">аккредитация на электронных площадках (государственных, коммерческих)</span></li>\r\n<li><span style="font-size: 10pt;">ежедневный мониторинг&nbsp; на поиск тендеров</span></li>\r\n<li><span style="font-size: 10pt;">подготовка полного пакета необходимых документов</span></li>\r\n<li><span style="font-size: 10pt;">участие в тендере (аукцион, вскрытие котировок,&nbsp;конкурсы и т.п.)</span></li>\r\n<li><span style="font-size: 10pt;">заключение договоров по результатам процедур, ведение отчетности по тендерным процедурам</span></li>\r\n</ul>\r\n<p><span style="font-size: 10pt;">Что же делать, тому кто решил осваивать данную профессию с нуля, как принять решение о целесообразности обучения:</span></p>\r\n<h2><span style="font-size: 10pt;">&nbsp; &nbsp; 1. Часто задаваемый вопрос, а получиться ли у меня работать и трудоустроиться&nbsp;менеджером по тендерам</span></h2>\r\n<p><span style="font-size: 10pt;"><strong><em>Однозначный ответ &laquo;ДА&raquo;</em></strong></span></p>\r\n<ul>\r\n<li><span style="font-size: 10pt;">Если Вы хотите переквалифицироваться в менеджера по тендерам и в то же время вам нравиться учетная, расчетная, аналитическая работа с цифрами и законодательством</span></li>\r\n</ul>\r\n<p><span style="font-size: 10pt;"><em><strong>&nbsp;Однозачный ответ &laquo;НЕТ&raquo;&nbsp;</strong></em></span></p>\r\n<ul>\r\n<li><span style="font-size: 10pt;">если Вы хотите работать в государственных и коммерческих закупках, но к расчетной, учетной и аналитической работе у вас не приязнь. Вам показаны эти курсы только, если вы будете косвенно связаны с тендерами, например принятие решений&nbsp; на участие в закупке или организацию поставки.</span></li>\r\n</ul>\r\n<h2><span style="font-size: 10pt;">&nbsp; &nbsp; &nbsp;2. Какое должно быть образование&nbsp;для работы&nbsp;специалиста по тендерам (торгам) для прохождения курсов?</span></h2>\r\n<p><span style="font-size: 10pt;">Обучение&nbsp; в нашем центре ЭмМенеджмент - лицензированное, дополнительно профессиональное, рассчитано на людей у которых есть средне &ndash; специальное или высшее образование,&nbsp;любой &nbsp;квалификации.</span></p>\r\n<p><span style="font-size: 10pt;">Легче будет осваиваться курсы &nbsp;при наличии профессионального юридического или экономического образования,&nbsp; а также или с минимальным опытом работы в закупках.&nbsp; Но!!! На практике очень много людей учаться и работают с разным образованием в специфике 44 ФЗ и&nbsp; 223 ФЗ.</span></p>\r\n<h2><span style="font-size: 10pt;">&nbsp; &nbsp; 3.&nbsp; Профессиональное образование - переподготовка на&nbsp;профессию специалиста по тендерам:</span></h2>\r\n<p><span style="font-size: 10pt;">Для специализации и наибольшей эффективности в работе Вы можете получить профессиональное образование - диплом специалиста по закупкам. В образование будет входить все необходимые требования работодателей для данной должности:</span></p>\r\n<ul>\r\n<li><span style="font-size: 10pt;">Практика заполнения закупочной документации, план - график, анализ ошибок</span></li>\r\n<li><span style="font-size: 10pt;">Сроки, требования, споры, обжалование и арбитражная практика 44-ФЗ и 223-ФЗ</span></li>\r\n<li><span style="font-size: 10pt;">Работа на сайте zakupki.gov.ru&nbsp;&nbsp;&ndash; мониторинг и анализ информации и работа в личном кабинете заказчика</span></li>\r\n<li><span style="font-size: 10pt;">Работа на сайте sberbank-ast.ru&nbsp;&nbsp;- личный кабинет поставщика и проведение электронных торгов</span></li>\r\n<li><span style="font-size: 10pt;">Основы бюджетной&nbsp;системы, антимонопольного законодательства</span></li>\r\n<li><span style="font-size: 10pt;">Базовые знания по переговорам и конфликтам, этика делового общения</span></li>\r\n<li><span style="font-size: 10pt;">Основы ценообразования для принятия решений&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; <a href="http://xn--d1ababe6aaeff9c5g.xn--p1ai/obrazovanie/kursy-yurista">Смотрите&nbsp; программы обучения и расписание</a></span></li>\r\n</ul>\r\n<p><span style="font-size: 10pt;">Большое преимущество в&nbsp;нашем обучение вы можете увидеть закупку с двух сторон: со стороны поставщика и заказчика. Это дает результаты в понимании как работать со второй стороной и предотвратить заранее все непредвиденные конфликтные ситуации.</span></p>\r\n<p><span style="font-size: 10pt;">Наши документы об образовании котируются на рынке труда, одобрены Министерством Юстиции и Министерством образования</span></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>', '', 1, 16, '2018-07-17 13:33:45', 42, '', '2018-08-29 12:16:02', 42, 42, '2019-02-28 09:38:23', '2018-07-17 13:33:45', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 18, 0, 'работа специалист по торгам, заработная плата специалист по торгам', 'На рынке труда  зарплата специалиста по тендерам колеблется  от 30.000 до 50.000 рублей в зависимости от опыта работы. ', 1, 1198, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(242, 450, 'Профессия маркетолога: что это за работа, обязанности и зарплата', 'профессия-маркетолога-что-это-за-работа,-обязанности-и-зарплата', '<h1><strong><span style="font-family: arial, helvetica, sans-serif;">Маркетолог: что это за профессия? Функционал, обязанности и зарплата</span></strong></h1>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Кто такой маркетолог и чем он занимается? Сегодня на эту тему в сети можно найти огромное количество материалов. Однако далеко не все они дадут полное понимание обязанностей представителей данной профессии.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Большинство руководителей, нанимающие специалистов по маркетингу, тоже далеко не всегда знают, чего хотят: не могут сформулировать должным образом требования в описании вакансий и потом грамотно поставить задачи перед сотрудником.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Изучив сайты вакансий, можно сделать вывод, что чаще всего в функционал маркетолога входят:</span></p>\r\n<ul>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Аудит рынка: анализ конкурентов и других факторов, которые могут повлиять на развитие компании.</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Разработка маркетинговой стратегии.</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Формирование позитивного имиджа компании.</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Подготовка рекламных материалов для разных типов информационных носителей (от сайта компании до печатной рекламы).</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Работа с необходимыми инструментами онлайн и офлайн-продвижения.</span></li>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Взаимодействие с подрядчиками.</span></li>\r\n</ul>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">На самом же деле ведущую роль в работе маркетолога имеют продажи. В современном мире в условиях высокой конкуренции хороший маркетолог должен в первую очередь способствовать увеличению продаж в компании. Это можно делать разными способами: правильно оформив сайт, наладив систему лояльности, подобрав правильные инструменты продвижения, сформулировав привлекательное УТП &ndash; перечислены только некоторые из доступных инструментов, способствующих увеличению спроса.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Нужно признать, что классическое вузовское образование тоже не дает студентам должного отношения к профессии. Большинство выпускников считают, что их главная функция &ndash; это формирование или поддержание положительного имиджа. В институтах, да и на многих профессиональных курсах, редко даются практические навыки, позволяющие влиять на финансовые показатели.&nbsp;</span></p>\r\n<h2><span style="font-size: 10pt;"><strong><span style="font-family: arial, helvetica, sans-serif;">Зарплата маркетолога</span></strong></span></h2>\r\n<p style="text-align: justify;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Еще один вопрос, который всех интересует - сколько зарабатывает маркетолог? Уровень дохода напрямую зависит от сферы бизнеса и квалификации специалиста. Судя по сайтам вакансий, зарплата маркетолога может достигать&nbsp;150 тысяч рублей и это не предел.&nbsp;</span></p>\r\n<p style="text-align: justify;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Курсы в центре эффективного обучения &laquo;ЭмМенеджмент&raquo; учитывают современные требования рынка и заточены на практическое освоение инструментов маркетинга. Полную программу можно посмотреть <a href="http://xn--d1ababe6aaeff9c5g.xn--p1ai/obrazovanie/%D0%BC%D0%B0%D1%80%D0%BA%D0%B5%D1%82%D0%B8%D0%BD%D0%B3-%D0%B8-%D0%BF%D1%80%D0%BE%D0%B4%D0%B2%D0%B8%D0%B6%D0%B5%D0%BD%D0%B8%D0%B5">на сайте</a>.</span></p>', '', 1, 26, '2018-07-19 12:22:21', 42, '', '2018-08-29 12:31:14', 42, 0, '0000-00-00 00:00:00', '2018-07-19 12:25:26', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 13, 1, 'профессия маркетолога, чем занимается маркетолог', 'Профессия маркетолога востребована на рынке труда. Заработная плата специалистов по маркетингу может варьироваться от 30 000 до 100 000 руб. и более', 1, 36, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(155, 256, 'Подкорытова Галина Валентиновна', 'подкорытова-галина-валентиновна', '<h1 style="text-align: left;">&nbsp; &nbsp;<span style="font-family: arial, helvetica, sans-serif;">Подко<img style="float: left;" src="images/podkorytova.jpg" alt="" width="99" height="124" />рытова Галина Валентиновна,&nbsp;&nbsp;член Гильдии управляющих документацией.</span></h1>\r\n<p>&nbsp; &nbsp; - Автор статей для журнала &laquo;Современные технологии в делопроизводстве&raquo;, &nbsp;&laquo;Хороший секретарь&raquo;, ЕСМ журнал<br />&nbsp; &nbsp; - Автор методического пособия &laquo;Документационное обеспечение управления&raquo;. Рецензия&nbsp;УГЭУ.<br />&nbsp; &nbsp; - Разработчик Инструкций по делопроизводству, Положения о методическом Совете<br />&nbsp; &nbsp; - Многолетний стаж в области работы с документами</p>\r\n<p dir="ltr"><span style="font-family: arial, helvetica, sans-serif;"><strong>Разработаны и проведены программы&nbsp;2016-2004 гг.&nbsp;</strong></span></p>\r\n<ul>\r\n<li class="MsoNormal" style="text-align: justify;">Документационное обеспечение управления</li>\r\n<li class="MsoNormal" style="text-align: justify;">Управление персоналом отдела делопроизводства</li>\r\n<li class="MsoNormal" style="text-align: justify;">Деловой протокол и этикет</li>\r\n<li class="MsoNormal" style="text-align: justify;">Кадровое делопроизводство</li>\r\n<li class="MsoNormal" style="text-align: justify;">Новая редакция национального стандарта ГОСТ &laquo;Требования к оформлению ОРД&raquo;</li>\r\n<li class="MsoNormal" style="text-align: justify;">Внедрение электронного документооборота</li>\r\n</ul>\r\n<p style="text-align: left;">&nbsp;Проведение семинаров в рамках корпоративного обучения: ФГУП &laquo;Октябрь&raquo;, МПО &laquo;АВИСМА&raquo;, ОАО &laquo;Уралхиммаш&raquo;, ОАО &laquo;Сургутнефтегаз&raquo;, УГМК, ЕМУП &laquo;СУЭРЖ&raquo;, ОАО &laquo;Лукойлпермьнефтеоргсинтез&raquo; и т.д.</p>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>Образование высшее:</strong></span></p>\r\n<p>2011 г. &nbsp;ВНИИДАД, Москва, &nbsp;Документоведение и документационное обеспечение управления, &nbsp;документовед</p>\r\n<p>1990&nbsp;г. &nbsp;УГТУ - УПИ, инженер</p>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>Дополнительное образование:</strong></span></p>\r\n<ul>\r\n<li>2013 г. Участие в работе конференции ВНИИДАД &laquo;Управление документацией&raquo;, Москва</li>\r\n<li>2012 г. Участие во Всероссийском профессиональном форуме &laquo;Эффективный документооборот в органах власти и самоуправления&raquo;, Москва</li>\r\n<li>2011 г. Участие&nbsp; в&nbsp;&nbsp;конгрессе &ndash; практикуме &laquo;Инфодокум&raquo; 2011&raquo; - Эффективный документооборот в в органах государственной власти, Москва&nbsp;</li>\r\n<li><span style="font-variant-numeric: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: ''Times New Roman'';">&nbsp;</span>2010г.&nbsp;<!--[endif]-->&laquo;Управление &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;документами &nbsp;&nbsp;&nbsp;&nbsp;на &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;основе &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;ГОСТ &nbsp;Р ИСО15489-2007&raquo;, Москва, ВНИИДАД</li>\r\n<li>2009 г. Участие &nbsp;&nbsp;в &nbsp;&nbsp;<span lang="EN-US">VII</span> &nbsp;&nbsp;конгрессе &ndash; практикуме &laquo;Инфодокум&raquo; &nbsp;- Эффективный документооборот в управлении бизнесом. Москва</li>\r\n<li>2009 г. &laquo;Актуальные вопросы работы архива<span style="font-size: 12.16px; text-indent: 28.8px;">&raquo;</span></li>\r\n<li>2008 г. Участие в форуме &laquo;DIRECTUM&raquo;, Москва</li>\r\n<li>2008 г. Практический опыт разработки и внедрения СМК на предприятиях в соответствии с требованиями стандартов <span lang="EN-US">ISO</span>&raquo;, ЕПТП, Екатеринбург,&nbsp;</li>\r\n<li>2007 г.&laquo;Эффективная работа службы документационного обеспечения управления&raquo;, Санкт-Петербургский университет сервиса и экономики&raquo;</li>\r\n<li>2004 г. &laquo;Совершенствование документооборота и делопроизводства на предприятии&raquo;, Российская академия государственной службы при президенте РФ. Международный институт &laquo;Восток-Запад&raquo;,&nbsp; Москва,</li>\r\n<li>2001 г. &laquo;Помощник руководителя ХХ<span lang="EN-US">I</span> века&raquo;, г. Челябинск</li>\r\n</ul>\r\n<p class="MsoNormal" style="text-align: justify;"><span style="font-family: ''arial black'', sans-serif;"><b>Опыт работы:</b></span></p>\r\n<p class="MsoNormal" style="text-align: justify;">2016 - 2010 гг.<b>&nbsp;-&nbsp;</b>Начальник отдела делопроизводства ООО &laquo;ФИНЭКС Качество&raquo; (предпроектное обследование предприятий перед внедрением системы электронного документооборота, разработка стандартов по делопроизводству для предприятий, ведение кадрового делопроизводства).&nbsp;</p>\r\n<p class="MsoNormal" style="text-align: justify;">2010 - 2006 гг. -&nbsp;Начальник отдела делопроизводства машиностроительного завода&nbsp;</p>\r\n<p class="MsoNormal" style="text-align: justify;">2007 - 2008 г<strong>.</strong> руководитель проекта внедрения системы электронного документооборота (СЭД) &laquo;Директум&raquo;. Система эксплуатируется на предприятии по настоящее время.</p>\r\n<p class="MsoNormal" style="text-align: justify;">2006 - 2002 гг. -&nbsp;управляющий делами строительной компании&nbsp;</p>\r\n<p>2006 - 2005 гг. - &nbsp;начальник контрольно-аналитического отдела ОАО &laquo;СвердНИИХиммаш&raquo;&nbsp;</p>\r\n<p class="MsoNormal" style="text-align: justify;">2002 - 1996 гг. -&nbsp;референт генерального&nbsp; директора ЕМУП &laquo;СУЭРЖ&raquo;, ЕМУП &laquo;Исеть-95&raquo;. Автор технического задания на разработку программы автоматизированного учета документооборота, контроля исполнения документов, протоколирования совещаний и контроля исполнения решений для ЕМУП &laquo;Исеть-95&raquo;, ЕМУП &laquo;СУЭРЖ&raquo;.&nbsp;</p>\r\n<p class="MsoNormal" style="text-align: justify;">&nbsp;</p>\r\n<p class="MsoNormal" style="text-align: justify;">&nbsp;</p>', '', 1, 24, '2017-01-23 13:57:58', 42, '', '2017-01-24 13:49:29', 42, 42, '2019-04-16 04:52:46', '2017-01-23 09:19:05', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"right","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 30, 0, '', '', 1, 3096, '', 0, '*', ''),
(119, 204, 'Профстандарт', 'профстандарт', '<h1 style="text-align: left;">Профессиональные стандарты применяются:</h1>\r\n<ul>\r\n<li style="text-align: justify;"><span style="font-family: arial, helvetica, sans-serif;"><strong>работодателями</strong></span> при формировании <span style="font-family: arial, helvetica, sans-serif;"><strong>кадровой политики</strong> </span>и в управлении персоналом, <span style="font-family: arial, helvetica, sans-serif;"><strong>при организации обучения и аттестации работников, разработке должностных инструкций,</strong> </span>тарификации работ, присвоении тарифных разрядов работникам и установлении систем оплаты труда с учетом особенностей организации производства, труда и управления</li>\r\n<li style="text-align: justify;"><span style="font-family: arial, helvetica, sans-serif;"><strong>образовательными организациями</strong></span> профессионального образования <span style="font-family: arial, helvetica, sans-serif;"><strong>при разработке профессиональных образовательных программ</strong></span></li>\r\n</ul>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>Профессиональный стандарт</strong></span> &ndash; это характеристика квалификации, необходимой работнику для осуществления определенного вида профессиональной деятельности (ст. 195.1 ТК РФ)</p>\r\n<p style="text-align: justify;"><img style="float: left; margin: 0px 10px;" src="images/8888111.gif" alt="" width="33" height="42" />В соответствии с&nbsp;<span style="font-size: 12.16px; line-height: 15.808px;">N 122-ФЗ&nbsp;</span>&nbsp;и ФЗ&nbsp;№ 273 "Об образовании в Российской Федерации" применение профессиональных стандартов работодателями <span style="font-family: arial, helvetica, sans-serif;"><strong>с 1 июля 2016 г.</strong></span> <strong><span style="font-family: arial, helvetica, sans-serif;">станет обязательным</span></strong>&nbsp;<span style="font-size: 12.16px; line-height: 15.808px;">&nbsp;</span>&nbsp;&nbsp;в случаях, когда с выполнением соответствующей работы связано <span style="font-family: arial, helvetica, sans-serif;"><strong>наличие льгот, гарантий и ограничений,</strong></span> либо если соответствующие требования уже установлены<span style="font-family: arial, helvetica, sans-serif;"><strong> ТК РФ, другими федеральными законами, иными нормативными правовыми актами Российской Федерации.</strong></span></p>\r\n<p style="text-align: justify;">Принятые профстандарты в сфере АУП</p>\r\n<address>Специалист в сфере закупок</address><address><a href="images/ekspert.pdf" rel="alternate">Эксперт в сфере закупок<br /></a><a href="images/personal.pdf" rel="alternate">Специалист по управлению персоналом</a></address><address><a href="images/buhgalter.pdf" rel="alternate">Бухгалтер</a></address><address><a href="images/planovoekonom.pdf" rel="alternate">Специалист в области планово-экономического обеспечения строительного&nbsp;производства</a><br /><a href="images/dokument.pdf" rel="alternate">Специалист по документационному &nbsp;и организационному обеспечению</a></address><address><a href="images/strategia.pdf" rel="alternate">Специалист по стратегическому и тактическому планированию и организации производства</a></address><address><a href="http://xn--d1ababe6aaeff9c5g.xn--p1ai/images/logist.pdf" rel="alternate">Специалист по логистике на транспорте</a></address>', '', 1, 17, '2016-07-07 12:33:04', 42, '', '2018-11-27 13:11:01', 42, 42, '2019-04-15 12:10:00', '2016-07-07 12:33:04', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 33, 8, '', '', 1, 10131, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(110, 187, 'Новая услуга', 'новая-услуга', '<p>текст услуги</p>', '', -2, 11, '2016-05-30 07:11:03', 61, '', '2016-05-30 07:11:07', 61, 42, '2018-06-04 04:55:08', '2016-05-30 07:11:03', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 2, 1, '', '', 1, 55, '', 0, '*', ''),
(117, 200, 'Дубова Наталья Сергеевна', 'дубова-наталья-сергеевна', '<h1><span style="font-family: Pro;">Дубова Наталья Сергеевна</span></h1>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 82px;">\r\n<td style="height: 82px; width: 10%;"><span style="font-family: Pro; font-size: 10pt;"><img src="images/Dubova_NS.JPG" alt="преподаватель по гранд смете и сметному делу" width="104" height="135" /></span></td>\r\n<td style="height: 82px; width: 86%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">-&nbsp;<strong>Более 8 лет</strong> опыта работы преподавателем</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">- <strong>Более 13 лет</strong> опыта работы в сметном деле</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">- Руководитель проектного - сметного отдела ООО "Мега - Строй" &nbsp;&nbsp;&nbsp;&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">- Проектная работа с компаниями г. Екатеринбурга</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">Разработаны и проводятся программы обучения сметному делу и Гранд-Смете</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="height: 15px; width: 96%;" colspan="2">\r\n<p><span style="font-family: Pro; color: #800000; font-size: 10pt;"><strong>Высшее образование:</strong></span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">1999 - 2004 гг. - УРГУПС, Экономика и управление на предприятии, Экономист менеджер</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2012 - 2013 гг. - УРГУПС, Промышленное и гражданское строительство</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro; color: #800000; font-size: 10pt;"><strong>Дополнительное образование:&nbsp;</strong></span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2016 г. Педагогика и методика обучения, повышение квалификации г. Екатеринбург</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2006 г. Гранд-Смета и экономика&nbsp;ценообразования в строительстве</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro; color: #800000; font-size: 10pt;"><strong>Трудовая деятельность:</strong></span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">&nbsp;2011 г. - по настоящее время &nbsp;- ООО «Мега-Строй»&nbsp;&nbsp;Руководитель проектно-сметного отдела</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">&nbsp;2010 - 2011 гг. ООО «Севергазстройизыскания»&nbsp;Руководитель проектно-сметного отдела</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2009&nbsp;-&nbsp;2010 гг. - ООО «Мега-Строй»&nbsp;&nbsp;Ведущий инженер-сметчик&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2006 - 2009 гг. - ООО «Инвестиционно - Строительная Компания Унистрой-Альянс»&nbsp;Инженер-сметчик</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2005 - 2006 гг. - Строительная компания ООО «НПО Строй»&nbsp;Экономист - сметчик</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>', '', 1, 22, '2016-06-22 08:46:20', 42, '', '2019-04-26 09:57:09', 42, 0, '0000-00-00 00:00:00', '2016-06-22 08:46:20', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 43, 1, '', '', 1, 10628, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(123, 210, 'Профессиональная переподготовка или второе высшее?', 'второе-высшее-или-профессиональная-переподготовка', '<h1>Профессиональная переподготовка или&nbsp;в<span style="line-height: 15.808px;">торое высшее</span><span style="line-height: 1.3em;">?</span></h1>\r\n<p style="text-align: justify;">Профессиональная переподготовка&nbsp;открывает новые перспективы и становится альтернативой второму высшему образованию.&nbsp;Дополнительное профессиональное образование становится все более <span style="font-family: arial, helvetica, sans-serif;"><strong>необходимым в связи в введением профстандартов.&nbsp;&nbsp;</strong></span>В условиях растущей конкуренции на рынке&nbsp;труда требуются специалисты смежных профессий, востребована профессиональная многозадачность.</p>\r\n<p style="text-align: justify;"><img style="float: left; margin: 0px 10px;" src="images/8888111.gif" alt="" width="24" height="31" />Профпереподготовка открывает возможности: имея <span style="font-family: arial, helvetica, sans-serif;"><strong>один диплом</strong></span> о высшем &nbsp;или среднем профессиональном, начальном профессиональном образовании можно пройти&nbsp; &nbsp;профпереподготовку <span style="font-family: arial, helvetica, sans-serif;"><strong>и получить диплом о новой квалификации.&nbsp; </strong></span>Если вы&nbsp;в данный момент учитесь на диплом о первом образовании, то получите документ о профпереподготовке&nbsp; при получении базового диплома.</p>\r\n<p style="text-align: justify;">Дипломы о профессиональной переподготовке дают то же самое, что и второе высшее&nbsp;-&nbsp;<span style="font-family: arial, helvetica, sans-serif;"><strong>дополнительную специальность</strong></span>, которая ложится на базу Вашего основного образования.&nbsp;Главное отличие диплома о профессиональной переподготовке от диплома о втором высшем образовании - это срок обучения по профессиональной переподготовке составляет <span style="font-family: arial, helvetica, sans-serif;"><strong>от 250 академических часов.</strong></span></p>\r\n<p><img style="float: left; margin: 0px 10px;" src="images/8888111.gif" alt="" width="24" height="31" /></p>\r\n<p style="text-align: justify;"><span style="font-family: arial, helvetica, sans-serif;"><strong>И так вы тратите меньше времени и, соответственно, &nbsp;денег,</strong></span>&nbsp;а по итогу выпускники и того, и другого имеют одинаковую квалификацию и могут претендовать на одни и те же должности.&nbsp;Ещё одним отличием&nbsp;от второго высшего образования&nbsp;является <span style="font-family: arial, helvetica, sans-serif;"><strong>более узкий подбор дисциплин, необходимый только для данной сферы деятельности.&nbsp;&nbsp;</strong></span></p>\r\n<p style="text-align: justify;">Программы профпереподготовки насыщенны только специальными дисциплинами, которые необходимы для профессиональной деятельности. В программах нет ничего лишнего,&nbsp;&nbsp;все направлено на получение компетенций, которые необходимы специалисту <span style="font-family: arial, helvetica, sans-serif;"><strong>&nbsp;для работы "здесь и сейчас".&nbsp;</strong></span>Наши программы отличаются:</p>\r\n<p style="text-align: justify;"><span style="font-family: arial, helvetica, sans-serif;"><strong>&nbsp;1. Практической составляющей&nbsp; </strong></span></p>\r\n<p style="text-align: justify;"><span style="font-family: arial, helvetica, sans-serif;"><strong>&nbsp;2.&nbsp;Повышенными требованиями к преподавательскому составу </strong></span></p>\r\n<p style="text-align: justify;"><span style="font-family: arial, helvetica, sans-serif;"><strong>&nbsp;3.&nbsp;Специализацией&nbsp;программ</strong></span></p>', '', 1, 17, '2016-08-01 13:15:35', 42, '', '2018-02-20 07:52:42', 42, 42, '2019-04-15 12:20:31', '2016-08-01 13:15:35', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 16, 7, '', '', 1, 8182, '', 0, '*', '');
INSERT INTO `j7_content` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(128, 224, 'Сессия стратегического планирования', 'сессия-стратегического-планирования', '<h1 style="text-align: center;" align="center">Сессия стратегического планирования,&nbsp;стратегическое управление и &nbsp;развитие&nbsp;компании</h1>\r\n<p class="hide-for-small-only"><img src="images/strategicheskoe_planirovanie.jpg" alt="обучение стратегическому планированию" /></p>\r\n<p><span style="font-family: tahoma, arial, helvetica, sans-serif;"><strong>Целевая аудитория:&nbsp;</strong>собственники бизнеса,&nbsp;руководители подразделений,&nbsp;ключевые сотрудники</span></p>\r\n<p class="MsoNormal"><span style="font-family: tahoma, arial, helvetica, sans-serif;"><strong>В результате:</strong></span></p>\r\n<ul>\r\n<li><span style="font-family: tahoma, arial, helvetica, sans-serif;">Сформируете видение миссии и стратегии развития компании.</span></li>\r\n<li><span style="font-family: tahoma, arial, helvetica, sans-serif;">Разработаете стратегический план. Определить стратегические, тактические и оперативные цели</span></li>\r\n<li><span style="font-family: tahoma, arial, helvetica, sans-serif;">Выработаете единое информационное поле и единый подход ТОП-менеджеров к развитию бизнеса</span></li>\r\n<li><span style="font-family: tahoma, arial, helvetica, sans-serif;">Оптимизируете&nbsp;бизнес-процессы компании</span></li>\r\n<li><span style="font-family: tahoma, arial, helvetica, sans-serif;">Сплотите управленческую команду и способствуете развитию корпоративной культуры</span></li>\r\n</ul>\r\n<p><span style="font-family: tahoma, arial, helvetica, sans-serif;"><strong>В программе:</strong></span></p>\r\n<p><span style="font-size: 10pt; font-family: tahoma, arial, helvetica, sans-serif;"><strong>1. &nbsp;Формирование&nbsp;миссии и стратегии развития компании.</strong></span></p>\r\n<ul>\r\n<li><span style="font-family: tahoma, arial, helvetica, sans-serif;">Что важнее: планировать или гибко реагировать на изменения? Цель и план. Уровни планирования. Цикл процесса планирования.</span></li>\r\n<li><span style="font-family: tahoma, arial, helvetica, sans-serif;">Разрабатываем миссию и видение будущего компании.</span></li>\r\n</ul>\r\n<p><span style="font-family: tahoma, arial, helvetica, sans-serif;"><strong>2. Как &nbsp; перевести миссию на уровень стратегических целей компании? Как определить тактические задачи для реализации стратегии?</strong></span></p>\r\n<p><span style="font-family: tahoma, arial, helvetica, sans-serif;">Стратегические цели и стратегический план. Тактические цели.</span></p>\r\n<p><span style="font-family: tahoma, arial, helvetica, sans-serif;">Разработка карты стратегии – интегрируем миссию в четыре составляющие сбалансированной системы показателей:</span></p>\r\n<ul>\r\n<li><span style="font-family: tahoma, arial, helvetica, sans-serif;">Определяем стратегическую цель компании в финансовых показателях.</span></li>\r\n<li><span style="font-family: tahoma, arial, helvetica, sans-serif;">Определяем, какое предложение потребительской ценности клиентам обеспечит достижение финансовых целей.</span></li>\r\n<li><span style="font-family: tahoma, arial, helvetica, sans-serif;">Выявляем внутренние бизнес-процессы для реализации финансовых и клиентских целей и доводим их до совершенства.</span></li>\r\n<li><span style="font-family: tahoma, arial, helvetica, sans-serif;">Определяем стратегическую роль нематериальных активов компании, приводим в соответствие с предыдущими уровнями. Совершенствуем стратегию обучения и развития персонала.</span></li>\r\n</ul>\r\n<p><span style="font-family: tahoma, arial, helvetica, sans-serif;">Выбор стратегии движения компании. Анализ внешней среды и внутренних ресурсов компании. Вопросы стратегического прогнозирования.</span></p>\r\n<p><span style="font-family: tahoma, arial, helvetica, sans-serif;"><span lang="EN-US">SWOT</span> анализ. Оцениваем конкурентоспособность товара или услуги компании на рынке с помощью анализа внутренней и внешней среды организации.</span></p>\r\n<ul>\r\n<li><span style="font-family: tahoma, arial, helvetica, sans-serif;">Определяем сильные и слабые стороны</span></li>\r\n<li><span style="font-family: tahoma, arial, helvetica, sans-serif;">Определяем угрозы и возможности</span></li>\r\n<li><span style="font-family: tahoma, arial, helvetica, sans-serif;">Составляем матрицу <span lang="EN-US">SWOT </span>анализа</span></li>\r\n<li><span style="font-family: tahoma, arial, helvetica, sans-serif;">Делаем выводы и разрабатываем стратегию</span></li>\r\n</ul>\r\n<p><span style="font-family: tahoma, arial, helvetica, sans-serif;">Составляем оптимистический и пессимистический сценарии развития.</span></p>\r\n<p><span style="font-family: tahoma, arial, helvetica, sans-serif;"><strong>3.&nbsp;<!--[endif]-->Как обеспечить продвижение к обозначенным целям всеми сотрудниками?</strong></span></p>\r\n<ul>\r\n<li><span style="font-family: tahoma, arial, helvetica, sans-serif;">Оперативные цели и планы. Введение контрольных показателей.</span></li>\r\n<li><span style="font-family: tahoma, arial, helvetica, sans-serif;">Осуществление плана. Система управления. Как эффективно поставить задачу и проконтролировать выполнение?</span></li>\r\n<li><span style="font-family: tahoma, arial, helvetica, sans-serif;">Мониторинг и изучение. Анализ планирования и результатов с учетом их влияния на показатели оперативных, тактических и стратегических планов.</span></li>\r\n</ul>\r\n<p><span style="font-family: tahoma, arial, helvetica, sans-serif;"><!-- [if !supportLists]--><strong>4.&nbsp; &nbsp;<!--[endif]-->Что дальше?</strong></span></p>\r\n<ul>\r\n<li><span style="font-family: tahoma, arial, helvetica, sans-serif;">Составляем план дальнейших действий.</span></li>\r\n<li><span style="font-family: tahoma, arial, helvetica, sans-serif;">Подводим итоги сессии.</span></li>\r\n</ul>\r\n<p><span style="font-family: tahoma, arial, helvetica, sans-serif;"><strong>Методы проведения:</strong>&nbsp;Мозговые штурмы, фасилитации, презентации менеджеров, работа в мини-группах</span></p>\r\n<p class="MsoNormal"><span style="font-family: tahoma, arial, helvetica, sans-serif;"><strong>Продолжительность</strong>: 2 - 4&nbsp;дня</span></p>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 4.8125px; background-color: #f5f5f5;">\r\n<td style="width: 25.6795%; height: 4.8125px;">\r\n<p style="text-align: center;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong><span style="color: #800000;">ВЕДУЩИЙ ТРЕНИНГА</span></strong> </span></p>\r\n</td>\r\n<td style="width: 71.3205%; height: 4.8125px;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong><span style="color: #800000;">МАКАРОВА ЮЛИЯ ОЛЕГОВНА</span></strong> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 25.6795%; height: 15px;"><img style="display: block; margin-left: auto; margin-right: auto;" src="images/Makarova_JO.jpg" alt="курсы по стратегическому планированию" width="94" height="124" /></td>\r\n<td style="width: 71.3205%; height: 15px;">\r\n<p><strong><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Тренер по стратегическому развитию и управленческим компетенциям.&nbsp;</span></strong></p>\r\n<p><strong><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Более 15 лет практического опыта, более 1000 часов проведенных тренингов.</span></strong></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Проведение сборных и корпоративных программ, проектов по направлениям:&nbsp;</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">&nbsp;- Управленческие навыки, командообразование, сессии стратегического планирования.&nbsp;</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">&nbsp;- Коммуникативная компетентность: технологии работы с рекламациями и конфликтами, профессиональное общение.&nbsp;</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">&nbsp;- Личная эффективность: тайм-менеджмент (управление временем), стресс-менеджмент.&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>', '', 1, 7, '2016-08-12 05:38:59', 42, '', '2019-04-15 12:59:20', 42, 0, '0000-00-00 00:00:00', '2016-08-12 05:38:59', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 25, 1, '', '', 1, 4989, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(129, 226, 'test', 'test', '<p>Текст</p>\r\n<p>Текст текс</p>', '', -2, 2, '2016-08-18 12:17:38', 61, '', '2016-08-18 12:17:38', 0, 42, '2018-06-04 04:54:58', '2016-08-18 12:17:38', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 1, 44, '', '', 1, 0, '{}', 0, '*', '');
INSERT INTO `j7_content` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(130, 227, 'Директор по персоналу', 'директор-по-персоналу', '<h1 style="line-height: 15.808px; text-align: center;"><span style="font-family: Pro; font-size: 12pt;">Директор по персоналу. Диплом о переподготовке по программе МВА.&nbsp;</span></h1>\r\n<p><span style="font-family: Pro;"><strong>Целевая аудитория:&nbsp;&nbsp;</strong>менеджер по персоналу,&nbsp; руководитель по управлению персоналом, директор по персоналу</span></p>\r\n<p><span style="font-family: Pro;"><strong>Ведущие:&nbsp;&nbsp;</strong></span></p>\r\n<p><span style="font-family: Pro;"><!-- noindex --></span></p>\r\n<p><span style="font-family: Pro;"><a href="index.php?option=com_content&amp;view=article&amp;id=71&amp;catid=2&amp;Itemid=112" rel="nofollow">Путилова Марина Владимировна</a>&nbsp; - руководитель службы Управления персоналом Запсибэлектроинжиниринг.</span><br /><span style="font-family: Pro;"><a href="index.php?option=com_content&amp;view=article&amp;id=106&amp;catid=2&amp;Itemid=112" rel="nofollow">Шарунова Ирина Юрьевна&nbsp;</a>- руководитель кадровой структуры компании "Спецгазпроект", аудитор по трудовым вопросам.</span><br /><span style="font-family: Pro;"><a href="index.php?option=com_content&amp;view=article&amp;id=210&amp;catid=23" rel="nofollow">Макарова Юлия Олеговна</a>&nbsp;- бизнес - тренер по&nbsp; управленческим компетенциям.</span><br /><span style="font-family: Pro;"><a href="index.php?option=com_content&amp;view=article&amp;id=53&amp;catid=14">Романова Ульяна Владимировна</a>-&nbsp;преподаватель, финансовый директор&nbsp;</span></p>\r\n<p><span style="font-family: Pro;"><!--/ noindex --></span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-size: 10pt;"><strong><span style="font-family: Pro;">МОДУЛИ ОБУЧЕНИЯ:</span></strong></span></p>\r\n<p class="MsoNormal" style="font-size: 12.16px; line-height: 15.808px;"><span style="font-family: Pro; font-size: 10pt;">1. Управление персоналом&nbsp;</span></p>\r\n<p class="MsoNormal" style="font-size: 12.16px; line-height: 15.808px;"><span style="font-family: Pro; font-size: 10pt;">2. Трудовое право и кадровое делопроизводство</span></p>\r\n<p class="MsoNormal" style="font-size: 12.16px; line-height: 15.808px;"><span style="font-family: Pro; font-size: 10pt;">3.&nbsp;Финансовый менеджмент</span></p>\r\n<p class="MsoNormal" style="font-size: 12.16px; line-height: 15.808px;"><span style="font-family: Pro; font-size: 10pt;">4.&nbsp;Стратегический &nbsp;и организационный менеджмент</span><span style="font-size: 10pt; font-family: Pro;"><strong style="font-family: arial, helvetica, sans-serif; font-size: 13.3333px; line-height: 15.808px;"><br /></strong></span></p>\r\n<p>&nbsp;</p>\r\n<p style="text-align: center;"><span style="font-family: Pro;"><a href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<p>&nbsp;</p>\r\n<p><a href="#"><img src="images/slider/shablon_diploma.jpg" alt="обучение на директора по персоналу" width="30%" height="250" />&nbsp;&nbsp;</a> <a href="#"><img src="images/slider/shablon_diploma_vnutri.jpg" alt="курсы директора по персоналу" width="30%" height="250" />&nbsp;&nbsp;</a> <a href="#"><img src="images/slider/специалист_по_управлению_персоналом.jpg" alt="специалист по управлению персоналом обучение" width="30%" height="250" /></a></p>\r\n<hr />\r\n<p><span style="font-size: 12pt; font-family: Pro;">&nbsp;<strong>Программа курса</strong></span></p>\r\n<table style="width: 99.4675%;">\r\n<tbody>\r\n<tr>\r\n<td colspan="2"><span style="font-size: 10pt;"><strong><span style="font-family: Pro; color: #a22521;">МОДУЛЬ 1.&nbsp;УПРАВЛЕНИЕ ПЕРСОНАЛОМ</span></strong></span></td>\r\n</tr>\r\n<tr style="height: 425px; background-color: #f5f5f5;">\r\n<td>\r\n<p><strong><span style="font-family: Pro;">1. Как подбирать эффективных </span></strong><br /><strong><span style="font-family: Pro;">сотрудников? Актуальные методики </span></strong><br /><strong><span style="font-family: Pro;">подбора и оценки потенциала</span></strong><br /><strong><span style="font-family: Pro;"> кандидатов</span></strong></p>\r\n</td>\r\n<td style="width: 39.2305%; height: 425px;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">1) Рекрутинг: актуальные и новые подходы к подбору персонала.&nbsp;Профиль должности, для чего и как разрабатывается?&nbsp;</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">2) Эффективная реклама вакансий, составление «работающего» объявления, примеры удачных и неудачных рекламных модулей.&nbsp;</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">3) Источники поиска персонала. Прямой поиск. Когда он необходим? Создание легенд и работа с ними. Headhunting - Технология привлечения «голов» под заказ.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">4) Методы оценки компетенций кандидата. Анализ резюме кандидата. Телефонное интервью. Анализ документов и биографических фактов. Метод экспресс-диагностики (оценка по первому впечатлению). Автобиография кандидата как метод оценки. Метод интервью по компетенциям. Метод самопрезентации кандидата. Контент-анализ речи кандидата. Метод экспертной оценки. Психологическое тестирование.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">5) Психологический портрет сотрудника на основе метода «LAB-profile.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">6) Коммуникативная компетентность; IQ и EQ (эмоциональный интеллект).</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">7) Проективные вопросы. Проективное и ситуационное интервью. Тесты. Методы ухода от социально желательных ответов</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">8) Тестирование кандидатов: Тесты Рокича, Роттера, Томаса, Герчикова, методика КОС.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">9) Оценка достоверности информации. Как узнать, когда кандидат лжет.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><em>- Практические задания кейсы по разработке профиля должности.</em>&nbsp;<em>&nbsp;</em></span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><em>- Разработка компетенций должностей</em>&nbsp;<em>&nbsp;- Анализ удачных и неудачных вакансий.</em></span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><em>- Кейсовое интервью и анализ правильности принятия решения выбора кандидата.</em></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 39.2305%; height: 15px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2.&nbsp;Коучинг и адаптация персонала</strong></span></p>\r\n</td>\r\n<td style="width: 39.2305%; height: 15px;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">1) Система управления адаптацией в организации.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">2) Коучинг и наставничество как основные инструменты адаптации.&nbsp;Коучинг - правильные вопросы для развития потенциала сотрудников.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">3) Оценка эффективности адаптационных процедур.</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><em>-&nbsp; Практические задания и кейсы по адаптации персонала.</em></span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><em>-&nbsp; Практика коучинга персонала и самокоучинг.</em></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 39.2305%; height: 15px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>3. Обучение и развитие персонала <br />- затраты или вложение в развитие организации?</strong></span></p>\r\n</td>\r\n<td style="width: 39.2305%; height: 15px;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">1) Анализ и систематизация потребностей в обучении, сопоставление со стратегическими приоритетами.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">2) Точки контроля процесса обучения, оценка эффективности системы обучения и обученного персонала. Современный подход в оценке эффективности обучения.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">3) Составление планов развития внутреннего потенциала сотрудников.&nbsp;</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">4) Корпоративный университет - как эффективный инструмент развития бизнеса.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">5) Кадровый резерв: построение системы. Развитие управленческих компетенций.&nbsp;</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">6) Карьера. Планирование и управление карьерой. Ротация. Организация конкурсов на внутренние вакансии.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 39.2305%; height: 15px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>4. Мотивация. Как увеличить прибыль предприятия, внедряя эффективную мотивационную систему.</strong></span></p>\r\n</td>\r\n<td style="width: 39.2305%; height: 15px; text-align: justify;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1) Создание эффективной системы мотивации в организации (от принципа «почему» к принципу «за что»).&nbsp;&nbsp;Виды мотивации:&nbsp;материальная и нематериальная.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Трудовая мотивация персонала. Внешние и внутренние мотиваторы. Мотивационные механизмы. Демотивация персонала, устранение демотивирующих факторов.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">3) Выявление мотивов сотрудника&nbsp;(или кандидата на этапе подбора).&nbsp;Причины пассивности персонала.&nbsp;Выясняем&nbsp;нематериальную мотивацию персонала:&nbsp;Карта мотиваторов.&nbsp;Мотивация "ОТ" и "К". Мотивация Процесс - Результат. Негативное стимулирование.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">4) Различная мотивация и циклы развития организации. Принципы эффективной компенсационной политики. Что необходимо для создания успешной системы оплаты труда. Недостатки денег в качестве мотиватора.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">5) Стимулирующая система оплаты труда:&nbsp;сколько и когда платить. Индивидуальные и коллективные показатели. Причины неудач многих систем оплаты труда. Бюджет ФОТ.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">6) Принципы эффективной системы премирования. Переменная часть оплаты труда в привязке к результату.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">7) Управление эффективностью персонала через ключевые&nbsp;показатели эффективности (KPI),&nbsp;грейдирование, управление по целям (МВО), матрицы функциональных обязанностей (МФО), категорирование персонала.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">8) Ценности поколения X, ценности поколения Y. Они совместимы? К чему стремятся люди Y, и можем ли мы это им дать, чтобы обеспечить необходимые инновации?</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">9) Как повысить лояльность, удовлетворенность сотрудников? Как максимально вовлечь их в жизнь компании, чтобы представители разных поколений чувствовали себя важными и нужными?</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-family: Pro; font-size: 10pt;"><em>-&nbsp; Практика: кейс&nbsp; Выясняем нематериальную мотивацию персонала. Карта мотиваторов. Мотивационный профиль.&nbsp;</em></span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-family: Pro; font-size: 10pt;"><em>-&nbsp; Практика Тестирование кандидатов:&nbsp; тест Герчикова, методика КОС,&nbsp; 11 баллов.</em></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 39.2305%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td>\r\n<p><strong><span style="font-family: Pro;">5. Оценка персонала или </span></strong><br /><strong><span style="font-family: Pro;">поддерживаем в тонусе </span></strong><br /><strong><span style="font-family: Pro;">квалификацию персонала</span></strong></p>\r\n</td>\r\n<td style="width: 39.2305%; height: 15px;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">1) Оценка и аттестация персонала. Цель создания системы оценки и аттестации персонала. Требования к системе оценки. Регулярность и периодичность оценочных процедур. Связь процессов оценки и обучения.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">2) План разработки и реализации системы оценки. Процедуры оценки.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">3) Современные методы оценки персонала в компании. Оценка по служебным функциям, метод 360, 570 градусов, метод экспертных оценок, независимых судей.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">4) Технология Ассессмент-центр -&nbsp;современная технология оценки персонала. Анализ кадрового потенциала организации.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">5) Использование профиля компетенций для оценки потенциала сотрудников. Выявление кандидатов в кадровый резерв.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">6) Аттестация как метод оценки персонала.&nbsp;Цели, методы и результаты аттестации.</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><em>-&nbsp; Практика: кейс&nbsp; оценки&nbsp; - Ассессмент - центр -технология позволяющая в короткие сроки получить достоверную информацию о личностно деловых качествах сотрудников.</em></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 39.2305%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">6. Корпоративная культура и ее <br />влияние </span></strong><strong><span style="font-size: 10pt;">на рост компании</span></strong></span></p>\r\n</td>\r\n<td style="width: 39.2305%; height: 15px;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">1) Анализ существующей ситуации в компании, инструменты анализа.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">2) Изменение организационной культуры: новые ценностные приоритеты, кодекс компании, поддерживающие мероприятия.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">3) Правила разработки мероприятий, способствующих формированию (коррекции существующей) корпоративной культуры.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">4) Документальное описание корпоративной культуры компании. Разработка положения (политики) по корпоративной культуре в компании.</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px; text-align: justify;"><span style="font-size: 10pt; font-family: Pro;"><i>- Практика: «Разработка&nbsp; корпоративной культуры».</i></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 39.2305%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>7. Личная эффективность<br /><br /></strong></span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n</td>\r\n<td style="width: 39.2305%; height: 15px;"><span style="font-family: Pro; font-size: 10pt;">1) Личная эффективность. Целеполагание в «SMART»- формате. Методы планирования. Инструменты тайм-менеджмента. Инвентаризация рабочего времени.</span>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">2) Конфликтология. Управление организационным конфликтом. Виды, причины, стадии развития конфликта. Стили поведения в конфликте. Этапы разрешения и способы урегулирования конфликта. Методы профилактики конфликтов.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">3) Стресс-менеджмент. Причины и симптомы стрессового напряжения. Способы сохранения и восстановления эмоционального равновесия и работоспособности. Антистресс - профилактика. Организационный стресс и результативность команды.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="background-color: #ffffff;">\r\n<td style="width: 10%; height: 15px;">&nbsp;</td>\r\n<td style="width: 39.2305%; height: 15px;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 49.2305%; height: 15px;" colspan="2"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="color: #a22521; width: 49.2305%; height: 15px;" colspan="2"><strong><span style="font-family: Pro;">МОДУЛЬ 2. ТРУДОВОЕ ПРАВО И КАДРОВОЕ ДЕЛОПРОИЗВОДСТВО</span></strong><span style="font-size: 10pt; color: #a22521;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">1. Прием на работу (установление<br /> трудовых отношений)</span></strong> </span></p>\r\n</td>\r\n<td style="width: 39.2305%; height: 15px;">\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">1)&nbsp;Поэтапная процедура оформления приема сотрудника на работу. Типичные ошибки при трудоустройстве.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">2) Штатное расписание и штатная расстановка,&nbsp; назначение, отличия, корректность заполнения?</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">3) Трудовой договор - содержание, порядок и сроки заключения.&nbsp; Перечень документов, предъявляемые работником в целях заключения трудового договора. Совместители. Испытательный срок.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">4) Гражданско-правовой договор. Отличие от трудового договора и документальное обеспечение.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">5) Особенности оформления договоров о материальной ответственности работников. Обязательность их заключения.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">6) Срочные и бессрочные договора. Сроки трудовых договоров. Ограничения заключения «срочных» договоров. Особенности срока трудовых отношений с совместителями. Особенности оформления трудовых договоров с руководителями.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">7) Документооборот приема. Особенности оформления документов с генеральными директорами нескольких компаний. Особенности оформления на работу иностранцев, инвалидов, несовершеннолетних. Кому нельзя отказать в приеме на работу.</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px; text-align: justify;"><span style="font-size: 10pt; font-family: Pro;"><em>- Практические задания: оформление на работу, разработка трудового договора</em></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 39.2305%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>2. Функции кадровой службы<br /> организации. Ключевые нормативные правовые акты регулирующие<br /> трудовые&nbsp;отношения</strong></span></p>\r\n</td>\r\n<td style="width: 39.2305%; height: 15px;">\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">1) Правила внутреннего трудового распорядка, как основной регламент.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">2) Положение об охране труда и технике безопасности.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">3) Положение о работе с персональными данными.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">4) Должностные инструкции работников -&nbsp; разработка корректных инструкций.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; line-height: 15.808px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><em>- Практические задания по разработке должностных инструкций, правил и положений.</em></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 39.2305%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>3. Изменение трудового договора</strong></span></p>\r\n</td>\r\n<td style="width: 39.2305%; height: 15px; text-align: justify;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1) Перевод и перемещение: в чем отличие перевода от перемещения.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Схематичное документирование переводов.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">3) Предназначение: докладных записок, служебных записок; заявлений; дополнительного соглашения; приказов).</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 39.2305%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>4. Правовое регулирование рабочего<br /> времени, режима рабочего времени.<br /> Отпуска</strong></span></p>\r\n</td>\r\n<td style="width: 39.2305%; height: 15px; text-align: justify;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">1) Рабочее время и время отдыха (нормальная и сокращенная продолжительность рабочего времени, неполное рабочее время; сверхурочная работа; ненормированный рабочий день; суммированный учет рабочего времени).</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">2) Табель учета и график рабочего времени, в чем разница?&nbsp;</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">3) Отпуска. Виды, оформление графика, приказов, заявлений, отзывов из отпуска. Льготные категории по времени предоставления отпуска. Особенности оформления отпусков льготным категориям работников. Спорные вопросы предоставления отпуска новым сотрудникам. Больничный во время отпуска. Перенос отпуска. Какие части и каких отпусков можно получить деньгами. Особенности расчета отпускных у работников, которые часто берут «отпуск за свой счет». Учебные отпуска.</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-size: 10pt; font-family: Pro;"><em>- Практические задания по расчету графиков, отпусков и больничных &nbsp; Служебная командировка</em></span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-size: 10pt; font-family: Pro;">4) Порядок направления в служебную командировку - докладная записка, служебное задание и отчет о служебном задании; - приказ о направлении в командировку; - командировочное удостоверение; - ведение журналов учета.</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-size: 10pt; font-family: Pro;">5) Какие возмещаются расходы работнику; подтверждающие документы; сроки предоставления документов и отчетность.</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-size: 10pt; font-family: Pro;">6) Положение о служебных командировках и служебных поездках.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 39.2305%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">5. Система нормирования - <br />технология управления <br />производительностью <br />труда</span></strong> </span></p>\r\n</td>\r\n<td style="width: 39.2305%; height: 15px; text-align: justify;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">1) Структура системы нормирования на предприятии. Документы, регламентирующие процесс нормирования.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">2) Классификация норм труда. Нормативы затрат труда и методы нормирования. Нормируемая величина денежных средств, направляемых на оплату труда.&nbsp;</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">3) Фотография рабочего дня и хронометраж – основные инструменты каждого руководителя.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">4) Потери рабочего времени. По организационно-техническим причинам, связанные с нарушением трудовой дисциплины.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">5) Особенности ненормированного труда:</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">- ненормированный рабочий день; цель установления и основание для использования. Порядок компенсации. Ненормированный рабочий день и сверхурочная работа.</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-size: 10pt; font-family: Pro;">6) Заработная плата при сменном режиме труда. Особенности суммированного учета.</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-size: 10pt; font-family: Pro;">- особенность повременной оплаты при сменном режиме труда;</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-size: 10pt; font-family: Pro;">- заработная плата за согласованную продолжительность работы в смене и ее превышение над федеральной нормой рабочего времени;</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-size: 10pt; font-family: Pro;">- вахта; продолжительность вахты, междусменный и междувахтовый отдых.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 39.2305%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">6. Правовое поле системы<br /> вознаграждений в организации</span></strong> </span></p>\r\n</td>\r\n<td style="width: 39.2305%; height: 15px;">\r\n<p style="background-color: #f5f5f5; text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">1)&nbsp;Постоянная и переменная часть. Взаимосвязь штатного расписания, норм труда и должностных обязанностей. Принципы и ограничения при необходимости изменений.</span></p>\r\n<p style="background-color: #f5f5f5; text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">2)&nbsp;Условия оплаты труда, включаемые в трудовой договор. Положение об оплате труда, премировании.</span></p>\r\n<p style="background-color: #f5f5f5; text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">3)&nbsp;Поощрение работников. Дисциплинарные взыскания</span></p>\r\n<p style="background-color: #f5f5f5; text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">- поощрение работников - основание;</span></p>\r\n<p style="background-color: #f5f5f5; text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">- поэтапная инструкция и документирование поощрения (формы представления, приказа);</span></p>\r\n<p style="background-color: #f5f5f5; text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">- дисциплинарные взыскания - виды в соответствии с действующим законодательством;</span></p>\r\n<p style="background-color: #f5f5f5; text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">- вопросы законности наложения штрафа на работников.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 39.2305%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>7. Ответственность&nbsp;работодателя <br />(кадровика, руководителя отдела<br /> персонала, бухгалтера, генерального директора)<br /> и трудовые споры</strong></span></p>\r\n</td>\r\n<td style="width: 39.2305%; height: 15px;">\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">1) Дисциплинарная ответственность. Особенности оформления дисциплинарных взысканий. Документы, наделяющие полномочиями расследовать факты нарушения дисциплины. </span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">2) Материальная ответственность. Судебная практика взыскания ущерба в полном объеме. Взыскание затрат на дорогостоящее обучение.&nbsp;</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">3) Административная и уголовная ответственность. Проверки Государственной инспекции труда. Минимизация рисков обращения работников в надзорно-контрольные органы.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">4) Предупреждение конфликтов, приводящих к обращениям граждан в надзорно-контрольные органы. Этика поведения специалистов HR при спорных и конфликтных ситуациях.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro;"><em><span style="font-size: 10pt;">-&nbsp;Обзор судебной практики по вопросам расторжения трудовых договоров по инициативе работодателя.</span></em> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 39.2305%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>8. Аттестация работников</strong></span></p>\r\n</td>\r\n<td style="width: 39.2305%; height: 15px;">\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">1) Аттестация – сходство и различие с оценкой. Цели и задачи аттестации.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">2) Правовые основы проведения аттестационных мероприятий, алгоритм проведения аттестационных мероприятий.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">3) Сроки проведения, график. Подготовка к аттестации. Мероприятия, документы, характеристика аттестуемого.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">4) Регламентация аттестации работников внутренними нормативными документами компании. Разработка «Положения об аттестации».</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">5) Аттестационная комиссия, состав, обязанности, протокол, работа комиссии, вынесение решения.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">6) Выводы аттестационной комиссии, обжалование решения аттестационной комиссии, лица, не проходящие аттестацию.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">7) Оценка деловых и личных качеств работника, правовые последствия аттестации.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">8) Изменение условий трудового договора по итогам аттестации (перевод, &nbsp;перемещение, изменение оплаты труда и т.д.).</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">9) Увольнение по итогам аттестации, ответственность работодателя за нарушение прав работника при проведении аттестации.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 39.2305%; height: 15px;"><span style="font-family: Pro;">&nbsp;&nbsp;</span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">9.&nbsp;Трудовая книжка,&nbsp; организация<br />кадрового делопроизводства</span></strong> </span></p>\r\n</td>\r\n<td style="width: 39.2305%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1) Трудовая книжка работника: учет, ведение, хранение.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Личная карточка работника: - обязательность заполнения&nbsp;&nbsp; - внесение записей в период работы и при увольнении - порядок учета и хранения.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">3) Личное дело работника.</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-family: Pro; font-size: 10pt;"><em>- Практические задания заполнение трудовой книжки и личного дела.</em></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 39.2305%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">10.&nbsp;Текущее&nbsp; и&nbsp; архивное хранение<br /> кадровой документации</span></strong> </span></p>\r\n</td>\r\n<td style="width: 39.2305%; height: 15px;">\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">1) Требования к формированию дел в делопроизводстве организации и подготовка передачи дел в ведомственный архив.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">2) Особенности сроков хранения дел по личному составу организаций.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">3) Требования к заполнению формы номенклатуры дел.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">4) Порядок составления и утверждения номенклатуры дел организации.&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 39.2305%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td><strong><span style="font-family: Pro;">11. Воинский учет</span></strong></td>\r\n<td style="width: 39.2305%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">1) Положение о воинском учете.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">2) Картотека личных дел, обязательность предоставления данных.</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-size: 10pt; font-family: Pro;"><em>- Заполнение обязательной отчетности по воинскому учету.</em></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 39.2305%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">12.&nbsp; 1С: Зарплата и управление<br /> персоналом 8</span></strong> </span></p>\r\n</td>\r\n<td style="width: 39.2305%; height: 15px;"><span style="font-family: Pro;"><span style="font-size: 10pt;">Работа в программе 1С: Зарплата и управление персоналом 8</span></span></td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 10%; height: 15px;">&nbsp;</td>\r\n<td style="width: 39.2305%; height: 15px;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 39.2305%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr>\r\n<td colspan="2"><strong><span style="font-family: Pro; color: #a22521;">МОДУЛЬ 3. ФИНАНСОВЫЙ МЕНЕДЖМЕНТ</span></strong></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">1. Экономика предприятия</span></strong> </span></p>\r\n</td>\r\n<td style="width: 39.2305%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">1) Точка безубыточности. Анализ безубыточности.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">2) Ключевой расчет маржинальной прибыли, чистой прибыли.&nbsp;</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">3) Ключевые показатели эффективности предприятия,&nbsp; EBITDA, ROE.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">4) Анализ финансовых результатов деятельности.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 39.2305%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2. Организация аналитического <br />учета затрат</strong></span></p>\r\n</td>\r\n<td style="width: 39.2305%; height: 15px;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">1) Бухгалтерский план счетов, с использованием которых осуществляется учет затрат на производство. Группировка балансовых статей, баланс предприятия,&nbsp; строение балансовых счетов.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">2) Затраты по статьям калькуляции. Учет отдельных видов затрат. Система "Директ - костинг".</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">3)&nbsp;Специфика и области применения различных методов учета производственных затрат: позаказного, котлового, попередельного.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 39.2305%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">3. Бизнес-план – первый план <br />компании.&nbsp;</span></strong> </span></p>\r\n</td>\r\n<td style="width: 39.2305%; height: 15px;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">1) Описание продукции и предприятия.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">2) Анализ рынка и маркетинговая стратегия. Выбор сегмента рынка. Анализ конкурентных преимуществ. Прогнозы объемов продаж - план продаж.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">3) Производственный план. Общий подход к организации производства.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">4) Финансовый план. Бюджетирование, как составная часть финансового планирования.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">5) Оценка рисков.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 10%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 39.2305%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 2px; background-color: #f5f5f5;">\r\n<td style="width: 10%; height: 2px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>4. Бюджетирование – как часть<br /> системы управления предприятием</strong></span></p>\r\n</td>\r\n<td style="width: 39.2305%; height: 2px;">\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">1) Постановка системы бюджетного управления:&nbsp; определение участников процесса бюджетного управления,&nbsp; определение центров финансовой ответственности, учета (ЦФО, ЦФУ).&nbsp;</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">2) Бюджетная система:&nbsp; Система бюджетов на предприятии: Бюджет продаж, бюджет производства, бюджет накладных расходов, бюджет доходов и расходов, бюджет движения денежных средств.&nbsp; Взаимосвязь основных плановых и отчетных форм между собой. Контроль исполнения бюджетов – ключевая функция системы бюджетного управления.&nbsp; Анализ исполнения бюджета.<br />Практические примеры построения &nbsp;бюджетов в программе Excel – программа для управленческого учета и системы бюджетирования на предприятии<br /></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #ffffff; height: 15px; width: 10%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; height: 15px; width: 39.2305%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 16px; background-color: #f5f5f5;">\r\n<td colspan="2"><strong><span style="font-family: Pro; color: #a22521;">МОДУЛЬ 4. СТРАТЕГИЧЕСКИЙ И ОРГАНИЗАЦИОННЫЙ МЕНЕДЖМЕНТ</span></strong></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<table style="width: 97.446%;">\r\n<tbody>\r\n<tr style="height: 233px; background-color: #f5f5f5;">\r\n<td style="width: 18%; height: 233px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>1. Оперативное управление персоналом: постановка задачи, делегирование, проведение совещаний, мотивация и контроль</strong> </span></p>\r\n</td>\r\n<td style="width: 71.9102%; height: 233px;">\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">1)&nbsp;Ручное управление или регулярный менеджмент. Стадии развития компании и управления в организации. Зачем нужна регламентация бизнес процессов? Ключевые&nbsp;функции менеджмента</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">2)&nbsp;Как организовывать работу подчиненных, делегировать полномочия и контролировать выполнение задач. Кому можно делегировать?</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro;"><span style="font-size: 10pt;">Постановка задач,&nbsp;алгоритм постановки задач.&nbsp;&nbsp;Как эффективно поставить задачу и&nbsp; получить результат выполнения?<br /></span><span style="font-size: 10pt;">Обратная связь.&nbsp;Как предоставлять сотруднику развивающую обратную связь? виды и правила обратной&nbsp;связи.<br />Как ругать сотрудника, чтобы улучшились результаты</span></span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">3)&nbsp;Планирование:&nbsp;расстановка приоритетов, линейное планирование, сложное планирование.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">4) Контроль: функции контроля, определение количества точек контроля, анализ причин несоответствия плана и фактическим результатам.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">5)&nbsp;Подготовка и проведение совещаний.&nbsp;Причины неэффективного совещания.&nbsp;Техники&nbsp;принятия решений&nbsp;на совещании.&nbsp;</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">4) Как мотивировать на результат,&nbsp;что движет сотрудниками.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">Уровни зрелости сотрудника. Искать готового или адаптировать под&nbsp; себя. Материальная и нематериальная мотивация. Система сбалансированных&nbsp; показателей&nbsp; и KPI, связь со стратегической картой</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 18%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 71.9102%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 18%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>2. Проектный&nbsp;<br />менеджмент</strong> </span></p>\r\n</td>\r\n<td style="width: 71.9102%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">Функционал менеджера проекта. Процессы&nbsp; проекта: инициация, планирование,&nbsp;исполнение, мониторинг, контроль, завершение проекта. Виды проектов. Разница от текущей деятельности. Что влияет на успешность проекта?Управление и снижение рисков, как часть проекта.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #ffffff; width: 18%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; width: 71.9102%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 18%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>3. Тайм - менеджмент. Личная эффективность</strong> </span></p>\r\n</td>\r\n<td style="width: 71.9102%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1)&nbsp;Инструменты принятия решений. Техники и методы принятия управленческих решений</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2)&nbsp;Как использовать инструменты тайм-менеджмента:&nbsp; целеполагание, расстановка приоритетов.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3)&nbsp;Как сократить «поглотителей времени»?</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4)&nbsp;Какие методы планирования применять (6М, метод ALP, SMART, матрица Эйзенхауэра).&nbsp; Проактивная и реактивная позиция руководителя. Индивидуальный тип восприятия времени.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">5)&nbsp;Способы структурирования рабочего пространства, организация&nbsp;рабочего времени.&nbsp;</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro; font-size: 10pt;">- Как сохранять баланс в жизни и находить источники повышения работоспособности.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro; font-size: 10pt;">- Методы предупреждения стресса и эмоционального выгорания руководителя.&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #ffffff; width: 18%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; width: 71.9102%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 18%; height: 15px;"><span style="font-size: 10pt; font-family: Pro;"><span style="font-size: 10pt;"><b>4.Эмоциональный&nbsp;</b></span><span style="font-size: 13.3333px;"><b>интеллект</b></span><span style="font-size: 10pt;"><b>, как повышение уровня руководства</b></span> </span></td>\r\n<td style="width: 71.9102%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">1.Что дает Эмоциональный интеллект в области повышения качества руководства и эффективности компании в целом </span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">Управление людьми на основе эмоционального&nbsp; интеллекта. Значимость эмоционального интеллекта для различных профессий и бизнес-задач</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">2. Эмоциональная компетентность руководителя </span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">Как использовать эмоции в бизнесе. Как распознать свое эмоциональное состояние и изменить его в зависимости от задач. Формирование благоприятного делового контакта.&nbsp;<br /></span><span style="font-size: 10pt;">Как грамотно использовать энергию «негативных» эмоций?&nbsp;</span><span style="font-size: 10pt;">- Практика Отработка навыков управления эмоциями в ситуациях взаимодействия с другими людьми<br /></span><span style="font-size: 10pt;">Эмоции женщин и эмоции мужчин – гендерные различия</span></span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">3. Эмоциональный интеллект, как инструмент для решения сложных ситуаций в бизнес-среде </span><span style="font-size: 10pt;"><br /></span><span style="font-size: 10pt;">Эмоции положительно влияющие &nbsp;и отрицательно влияющие на эффективность деятельности<br /></span><span style="font-size: 10pt;">Индивидуальные особенности мотивации персонала. Эмоции в основе мотивации.</span></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #ffffff; width: 18%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; width: 71.9102%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 18%; height: 15px;"><span style="font-size: 10pt; font-family: Pro;"><strong>5.Власть и лидерство</strong> </span></td>\r\n<td style="width: 71.9102%; height: 15px; text-align: justify;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">1. Создание и управление эффективных команд</span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">Как подбирать членов команды? Коммуникации в командах как инструмент эффективного лидера.&nbsp;</span><span style="font-size: 10pt;">Практика: Развитие навыков лидерского взаимодействия с подчиненными</span></span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">Техники работы с эмоциями при решении командных задач:&nbsp;н</span><span style="font-size: 10pt;">астройки на успех.&nbsp;</span></span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">Рациональный и интуитивный подход в принятии решений.&nbsp;Трудные решения и эмоции.</span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">Обратная связь через аргументацию, включающую&nbsp;разные виды</span><span style="font-size: 10pt;">&nbsp;с</span><span style="font-size: 10pt;">остояний</span><span style="font-size: 10pt;">&nbsp;сотрудников. Предотвращение конфликтных ситуаций.</span></span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">Эмоциональный интеллект и развитие других.&nbsp;Коучинг в развитии эмоционального интеллекта.&nbsp;</span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">2. Харизма лидера. Спонтанное поведение.&nbsp; </span><span style="font-size: 10pt;">Приемы развития харизмы</span></span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">Эффективные коммуникации.&nbsp;Имидж лидера. Поза, жесты, речь.&nbsp;Пластика движений, жестикуляция, голосовые режимы, тембр голоса, интонация.&nbsp;</span><span style="font-size: 10pt;">Практика: Приемы эффективного общения.&nbsp;</span></span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">Концепции лидерства.</span><span style="font-size: 10pt;">Ситуационные модели лидерства</span><span style="font-size: 10pt;">&nbsp;Практика: Определение собственного стиля лидерства: предпочитаемый стиль влияния и зоны развития. Определение и выбор оптимального стиля управления</span></span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">Лидер и группа.&nbsp;</span><span style="font-size: 10pt;">Законы групповой динамики. Управление групповой динамикой.&nbsp;Инструмент лидера - искусство говорить публично</span></span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">3. Власть. </span><span style="font-size: 10pt;">&nbsp;Внутренняя сила. Технологии и искусство доминирования. Принципы формирования общественного мнения.&nbsp;</span><span style="font-size: 10pt;">&nbsp;Власть личности, власть положения, власть знания. Какой тип власти применять в конкретной ситуации?&nbsp;</span><span style="font-size: 10pt;">Практика: Выбор собственного типа власти.</span><span style="font-size: 10pt;"><br /></span></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #ffffff; width: 18%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; width: 71.9102%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 18%; height: 15px;"><span style="font-size: 10pt; font-family: Pro;"><strong>6. Оперативное планирование или как обеспечить продвижение к обозначенным целям всеми сотрудниками</strong> </span></td>\r\n<td style="width: 71.9102%; height: 15px;">\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">1)&nbsp;Оперативные цели и планы. Введение контрольных показателей.<br /></span><span style="font-size: 10pt;">2)&nbsp;Достижение результата. Система планирования, как инструмент достижения результата.&nbsp;<br /></span><span style="font-size: 10pt;">3)&nbsp;Уровни планирования от стратегии к тактике. Мониторинг и изучение. Анализ планирования и результатов с учетом их влияния на показатели оперативных, тактических и стратегических планов.<br /></span><span style="font-size: 10pt;">4)&nbsp;Составляем план дальнейших действий.<br /></span><span style="font-size: 10pt;">5)&nbsp;Подводим итоги.</span></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #ffffff; width: 18%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; width: 71.9102%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 18%; height: 15px;"><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">7. Формирование стратегии развития сотрудника, подразделения, компании&nbsp;</span></strong> </span></td>\r\n<td style="width: 71.9102%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1)&nbsp;Новые уровни развития. План, цель, стратегия. Эффективный&nbsp;баланс: жесткое&nbsp; планирование и гибкое реагирование на изменения.&nbsp;&nbsp;Уровни планирования. Цикл процесса планирования.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2)&nbsp;Аудит действующих целей и стратегии. Разрабатываем&nbsp; План развития&nbsp;сотрудника, подразделения, компании.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #ffffff; width: 18%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; width: 71.9102%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 18%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>8. Что делать для реализации стратегии?</strong> </span></p>\r\n</td>\r\n<td style="width: 71.9102%; height: 15px;">\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro; font-size: 10pt;">1)&nbsp;Стратегические цели и стратегический план сотрудников, подразделений и компании. Тактические цели.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro; font-size: 10pt;">2)&nbsp;Выбор стратегии движения. Вопросы стратегического прогнозирования.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro; font-size: 10pt;"><span lang="EN-US">3)&nbsp;</span>Оцениваем реальную ситуацию, ресурсы сотрудников,&nbsp;компании.&nbsp;<span lang="EN-US">SWOT -&nbsp;</span>анализ сотрудников и компании. Разные виды SWOT анализа: линейный и перекрестный.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro;"><span style="font-size: 10pt;">4)&nbsp;Разработка карты стратегии – интегрируем &nbsp;составляющие сбалансированной системы показателей&nbsp;</span><span style="font-size: 10pt;">финансы, клиенты, процессы, персонал. Разрабатываете карту на вашем предприятии.<br /></span><span style="font-size: 10pt;">- Определяем стратегическую цель в финансовых показателях.<br /></span><span style="font-size: 10pt;">- Определяем бизнес процессы, что&nbsp;обеспечит достижение финансовых целей.<br /></span><span style="font-size: 10pt;">- Выявляем внутренние бизнес-процессы для реализации целей и доводим их до совершенства.<br /></span><span style="font-size: 10pt;">- Определяем стратегическую роль персонала.&nbsp;Совершенствуем&nbsp;систему обучения и развития персонала.</span></span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px;"><span style="font-family: Pro; font-size: 10pt;">5)&nbsp;Для чего нужен пессимистический сценарий? Составляем пессимистический и&nbsp; оптимистический сценарии.&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span style="font-size: 12pt; font-family: Pro;"><strong>Формат обучения:</strong></span></p>\r\n<p style="color: #a22521;"><span style="font-family: Pro;"><strong style="color: #000000;">Очно: Продолжительно 6 месяцев. Расписание:</strong></span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><strong>1&nbsp;модуль</strong>: понедельник и среда&nbsp; с 18.30 до 21.30, 3 субботы с 10.00 до 14.00. &nbsp;</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><strong>2&nbsp;модуль:</strong>&nbsp;вторник. четверг, пятница&nbsp;с 18.30&nbsp; до 21.30&nbsp;</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><strong>3&nbsp;модуль:</strong> понедельник, среда, пятница с 18.30&nbsp; до 21.30. </span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><strong>4&nbsp;модуль:</strong> понедельник, среда &nbsp;с 18.30&nbsp; до 21.30 суббота с 10.00 до 16.00. Выдается методическая литература.&nbsp; &nbsp;</span></p>\r\n<p style="color: #000000;"><span style="font-family: Pro;"><strong>Дистанционно</strong>: видео-лекции, аттестационные работы продолжительностью 2 месяца<span style="background-color: inherit; color: inherit; font-size: 1rem;"><br /></span></span></p>\r\n<hr />\r\n<p><span style="font-family: Pro;">&nbsp;<strong><span style="font-size: 12pt;">&nbsp;Акции и скидки:</span></strong> </span></p>\r\n<p>&nbsp;</p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit; color: inherit; font-size: 1rem;">•&nbsp;</span>Скидка 10%&nbsp;при оплате за 4 недели до обучения.&nbsp;&nbsp;</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit; color: inherit; font-size: 1rem;">•&nbsp;</span>Скидка 5%&nbsp;при оплате за 2 недели до обучения.</span></p>\r\n<p>&nbsp;</p>\r\n<p style="text-align: center;"><span style="font-family: Pro;"><a onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<hr />\r\n<p><strong><span style="font-family: Pro; font-size: 12pt;">О нас</span></strong></p>\r\n<p><span style="font-family: Pro;"><iframe style="background-image: url(''img/iframe.png''); display: block; margin-left: auto; margin-right: auto;" src="https://www.youtube.com/embed/yx3VnN5bh2k" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture"></iframe></span></p>', '', 1, 19, '2016-08-18 18:28:19', 42, '', '2019-04-30 06:01:36', 42, 0, '0000-00-00 00:00:00', '2016-08-18 18:28:19', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 84, 62, '', '', 1, 6177, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(132, 229, 'Управление взаимоотношениями с клиентами', 'управление-взаимоотношениями-с-клиентами', '<h1>Управление взаимоотношениями с клиентами</h1>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-family: arial, helvetica, sans-serif;"><strong>Целевая аудитория:&nbsp;</strong></span>менеджер по маркетингу, менеджер по рекламе, маркетолог - аналитик,&nbsp;немаркетологи:&nbsp;специалисты и руководители по продажам и продвижению товара.</p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-family: arial, helvetica, sans-serif;"><strong>Ведущий:</strong>&nbsp;</span>&nbsp;<a href="http://xn--d1ababe6aaeff9c5g.xn--p1ai/17-http-%D1%8D%D0%BC%D0%BC%D0%B5%D0%BD%D0%B5%D0%B4%D0%B6%D0%BC%D0%B5%D0%BD%D1%82-%D1%80%D1%84-obrazovanie/127-%D0%B4%D0%BE%D0%B1%D1%80%D0%BE%D1%87%D0%B0%D1%81%D0%BE%D0%B2%D0%B0-%D0%BD%D0%B0%D1%82%D0%B0%D0%BB%D1%8C%D1%8F-%D0%B3%D0%B5%D0%BD%D0%BD%D0%B0%D0%B4%D1%8C%D0%B5%D0%B2%D0%BD%D0%B0">Доброчасова Наталья Геннадьевна</a>&nbsp; - специалист по разработке маркетинговых стратегий, директор по маркетингу</p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-family: arial, helvetica, sans-serif;"><strong><span lang="EN-US">В программе</span></strong></span></p>\r\n<ul style="font-size: 12.16px; line-height: 15.808px;">\r\n<li><span lang="EN-US">Эффективная организация рекламы &nbsp;в компании &nbsp;</span></li>\r\n<li><span lang="EN-US">Продвижение сайта, SEO - оптимизация</span></li>\r\n<li>Контекстная реклама: яндекс - директ,&nbsp;<span lang="EN-US">&nbsp;</span>гугл - адвордс<span lang="EN-US">&nbsp;</span></li>\r\n<li>Реклама в социальных сетях</li>\r\n<li>Бюджетирование и планирование рекламных мероприятий</li>\r\n</ul>\r\n<p style="font-size: 12.16px; line-height: 15.808px;">- Расчет эффективности&nbsp; рекламной кампании, расчет бюджета рекламы</p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-family: arial, helvetica, sans-serif;"><strong>Продолжительность:</strong></span>&nbsp;&nbsp;3&nbsp;занятия, понедельник, среда с 18.30 до 21.30, суббота с 10 до 14.00 &nbsp;Стоимость 6500&nbsp;</p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-family: arial, helvetica, sans-serif;"><strong>Формы обучения:</strong></span>&nbsp;информационные модули, дискуссии и мозговые штурмы, ролевые упражнения, &laquo;разбор полетов&raquo; (моделирование и анализ реальных ситуаций взаимодействия).</p>', '', 0, 2, '2016-08-20 17:00:20', 42, '', '2018-05-31 09:42:02', 42, 42, '2018-06-04 05:31:40', '2016-08-20 17:00:20', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 3, 45, '', '', 1, 568, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(131, 228, 'Обучение  маркетингу и рекламе', 'обучение-маркетингу-и-рекламе', '<h1><span lang="EN-US" style="font-family: Pro;">Обучение маркетингу и рекламе в {city_d}. Инструменты эффективного маркетинга.</span></h1>\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 8pt;"><span style="font-size: 10pt;">Целевая аудитория</span>:</span><span style="font-size: 10pt;">&nbsp;&nbsp;</span></strong><span style="font-size: 10pt;">менеджер по маркетингу, менеджер по рекламе, маркетолог-аналитик, специалисты и руководители по продажам и продвижению товара.</span></span></p>\r\n<h2 style="text-align: center;"><strong style="color: inherit; font-size: 1rem; font-family: pro; text-align: center;"><span style="font-size: 10pt;">Пройдя наши курсы маркетинга, вы научитесь:</span></strong><span style="font-size: 10pt;"></span></h2>\r\n<table style="background-color: #f5f5f5;">\r\n<tbody>\r\n<tr style="background-color: #ffffff;">\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;"><strong>&nbsp;</strong>Проводить маркетинговый аудит и исследования</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">&nbsp;Сегментировать целевую аудиторию и клиентов</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr style="background-color: #ffffff;">\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro; text-align: start;">Позиционировать товар</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;"><span>Анализам&nbsp;</span><span lang="EN-US">SWOT</span><span>,&nbsp;</span><span lang="EN-US">ABC</span></span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr style="background-color: #ffffff;">\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Ценообразованию и управлению ассортиментом</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Рекламе и продвижению</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p style="text-align: center;"><span style="font-family: Pro;"><a style="text-align: center;" onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<hr />\r\n<p><span style="font-size: 12pt;"><strong><span style="font-family: Pro;">Фрагмент обучения маркетингу:</span></strong></span></p>\r\n<p>&nbsp;</p>\r\n<p><iframe style="background-image: url(''../img/iframe.png''); font-family: Pro;" src="https://www.youtube.com/embed/FnzVl_MZhYQ" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture"></iframe></p>\r\n<hr />\r\n<p style="text-align: left;"><span style="font-family: Pro; font-size: 12pt;"><strong>Программа&nbsp;курса</strong></span></p>\r\n<p>&nbsp;</p>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 231px;">\r\n<td style="background-color: #f7f7f7; height: 231px; width: 20.5084%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>1. Маркетинговый аудит положения компании на рынке</strong></span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 231px; width: 75.4916%;">\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">1) Как определить место компании на рынке?&nbsp;</span><span style="font-size: 10pt;">Ресурсы и способности вашей компании</span></span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Целевая аудитория и сегментирование клиентов. Определение основных сегментов аудитории.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) Позиционирование&nbsp;товара. Определяем конкурентные преимущества.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4) Анализ конкурентов и бенчмаркетинг. Как использовать конкурентов в достижении собственных целей.&nbsp;&nbsp;SWOT- анализ.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">5) Инновационный маркетинг - как непрерывное совершенствование продуктов, услуг</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">Практика: проводим маркетинговый аудит положения компании на рынке и сегментируем клиентов.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 20.5084%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 75.4916%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"></span></td>\r\n</tr>\r\n<tr style="height: 137px;">\r\n<td style="background-color: #f7f7f7; height: 137px; width: 20.5084%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2.&nbsp;Маркетинговые исследования. Взаимосвязь стратегии компании с маркетинговыми исследованиями</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 137px; width: 75.4916%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1) Для чего именно нам нужно проведение исследований? Анализ и эффективные стратегии</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Выбираем инструменты исследований: количественные и качественные исследования, полевые и кабинетные. Социологические и маркетинговые. Где искать данные, чтобы сэкономить на исследованиях и повысить их эффективность?</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) Использование маркетинговых исследований и маркетинговой информации в компании. Как сэкономить на исследованиях и включить в маркетинг каждого сотрудника компании?</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">Практика: проводим исследования и определяем маркетинговую стратегию&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 20.5084%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 75.4916%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"></span></td>\r\n</tr>\r\n<tr style="height: 151px;">\r\n<td style="background-color: #f7f7f7; height: 151px; width: 20.5084%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong><span lang="EN-US">3.&nbsp;Торговый маркетинг&nbsp;</span></strong> </span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 151px; width: 75.4916%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1) Категорийный менеджмент&nbsp;и прибыльность товаров. Принцип Паретто. АВС анализ и матрица БКГ</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Принципы управления ассортиментной матрицей.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) УТП (уникальное торговое предложение). Как правильно определить свою уникальность? Какие признаки могут стать преимуществом вашего товара или услуги, а какие нет. &nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4) Ассортиментная политика компании. &nbsp;Как заработать на расширении ассортимента?&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">Практика: формируем&nbsp; ассортиментную матрицу</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 20.5084%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 75.4916%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"></span></td>\r\n</tr>\r\n<tr style="height: 134px;">\r\n<td style="background-color: #f7f7f7; height: 134px; width: 20.5084%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>4.&nbsp;Ценообразование и управление ассортиментом</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 134px; width: 75.4916%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1)&nbsp;Ценообразование и ценовая стратегия. Как сформировать стоимость товара при разных позициях на рынке?&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2)&nbsp;Управление товарным ассортиментов на промышленных рынках и в сфере услуг</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">Практика: Формируем&nbsp;УТП&nbsp;вашей компании с рыночным обоснованием&nbsp; и &nbsp;продвижением.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">Практика: Определяем способы повышения клиентоориентированности вашей компании.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 20.5084%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 75.4916%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"></span></td>\r\n</tr>\r\n<tr style="height: 243px;">\r\n<td style="background-color: #f7f7f7; height: 243px; width: 20.5084%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>5.&nbsp;Интегрированные маркетинговые коммуникации. Реклама и продвижение</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 243px; width: 75.4916%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1) Инструменты продвижения. Их возможности и недостатки. Современные технологии управления взаимоотношениями с клиентами.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Нейромаркетинг. Прямой маркетинг. &nbsp;Ивент-маркетинг. Public Relations.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) Понятия «бренд» и «брендинг». &nbsp;Чем бренд отличается от товара. Как создать бренд.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4) Подходы к оценке эффективности рекламных кампаний.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">5) Элементы бренда: как управлять популярностью торговой марки.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">6) Определение точек контакта с существующими и потенциальными клиентами.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">7) CRM. &nbsp;Как выстраивать взаимоотношения с клиентами с помощью современных автоматизированных систем.<br /></span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">Практика: считаем эффективность рекламных компаний</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 20.5084%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 75.4916%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"></span></td>\r\n</tr>\r\n<tr style="height: 120px;">\r\n<td style="background-color: #f7f7f7; height: 120px; width: 20.5084%;"><span style="font-family: Pro; font-size: 10pt;"><strong>6.&nbsp;Медиапланирование</strong></span></td>\r\n<td style="background-color: #f7f7f7; height: 120px; width: 75.4916%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1)&nbsp;Медиапланирование. Эффективная частота размещения рекламы по разным каналам продвижения.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2)&nbsp;Бюджетирование рекламных кампаний. &nbsp;Как эффективно распределять бюджеты, чтобы получать максимальный результат.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3)&nbsp;Подходы к оценке эффективности рекламных кампаний.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">Практика: составляем медиа-план</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 20.5084%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 75.4916%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"></span></td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 96%; background-color: #f7f7f7; height: 14px;" colspan="2"><span style="font-family: Pro; font-size: 10pt;"><strong>7.&nbsp;Формирование маркетингового плана вашей компании.</strong></span></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<hr />\r\n<p><strong><span style="font-family: Pro; font-size: 12pt;">Формат курса </span></strong></p>\r\n<p>&nbsp;</p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">•&nbsp;<strong>Очное обучение.&nbsp;</strong>Продолжительность:&nbsp;3,5 недели, 3 раза в неделю, понедельник, среда, пятница с 18.30 до 21.30.&nbsp;</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">•&nbsp;<strong>Дистанционное обучение</strong>: видео-лекции, аттестационные работы</span></p>\r\n<hr />\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 12pt;">Акции и скидки:</span></strong></span></p>\r\n<p>&nbsp;</p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">•&nbsp;<strong>Скидка 10%</strong>&nbsp;при оплате за 4 недели до обучения.&nbsp;&nbsp;</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">•&nbsp;<strong>Скидка 5%</strong>&nbsp;при оплате за 2 недели до обучения.</span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p style="text-align: center;"><span style="font-family: Pro;"><a onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<hr />\r\n<p><span style="font-family: Pro;"></span></p>\r\n<table style="color: inherit; font-family: inherit; font-size: 1rem; width: 100%;">\r\n<tbody>\r\n<tr style="height: 17px;">\r\n<td style="width: 10%; height: 17px; background-color: #f5f5f5; text-align: center;">\r\n<p><span style="font-family: Pro; font-size: 12pt;"><strong><span style="color: #800000;">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Ведущий</span></strong> </span></p>\r\n</td>\r\n<td style="width: 35%; height: 17px; background-color: #f5f5f5;">\r\n<p class="header" style="text-align: left;" data-qa="resume-personal-name"><span style="font-size: 12pt; font-family: Pro;"><strong><span style="color: #800000;">Иванова Татьяна Владимировна</span> </strong> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 17px;">\r\n<td style="width: 10%; height: 17px; background-color: #f5f5f5; text-align: center;">\r\n<p><span style="font-family: Pro;"><img style="display: block; margin-left: auto; margin-right: auto;" src="images/prepodavatel_po_marketingy2.jpg" alt="обучение маркетингу и рекламе" width="132" height="151" /></span></p>\r\n</td>\r\n<td style="width: 35%; height: 17px; background-color: #f5f5f5; text-align: center;">\r\n<p style="text-align: left;"><strong><span lang="EN-US" style="font-size: 10pt; font-family: Pro;">Эксперт-практик в области маркетинговых коммуникаций</span></strong></p>\r\n<p style="text-align: left; padding-left: 30px;"><span lang="EN-US" style="font-size: 10pt; font-family: Pro;">-&nbsp;Опыт работы в маркетинге&nbsp;более 14 лет </span></p>\r\n<p style="text-align: left; padding-left: 30px;"><span lang="EN-US" style="font-size: 10pt; font-family: Pro;">-&nbsp;Опыт работы преподавателем&nbsp;более&nbsp;3 лет </span></p>\r\n<p style="text-align: left; padding-left: 30px;"><span style="font-size: 10pt; font-family: Pro;">&nbsp;- Директор рекламного агентства, в числе клиентов:&nbsp;Coca-Cola, Loreal,&nbsp;Johnson &amp; Johnson, Метро, М.Видео, УБРИР, Леруа Мерлен, Нивея и другие</span></p>\r\n<p style="text-align: left;"><span style="font-family: Pro; font-size: 10pt;"><strong>Трудовая деятельность:</strong></span></p>\r\n<p style="text-align: left; padding-left: 30px;"><span style="font-family: Pro; font-size: 10pt;">2012 - по настоящее&nbsp;время&nbsp; директор филиала&nbsp;федерального рекламного агентства "Хорошие люди"</span></p>\r\n<p style="text-align: left; padding-left: 30px;"><span style="font-family: Pro; font-size: 10pt;">2008 - 2013 г.&nbsp;&nbsp;Зам. директора по маркетингу&nbsp;ТК "Агора" строительные и отделочные материалы оптовая и розничная&nbsp;торговля&nbsp;</span></p>\r\n<p style="text-align: left; padding-left: 30px;"><span style="font-family: Pro; font-size: 10pt;">2007&nbsp;- 2008&nbsp;г. -&nbsp;Руководитель отдела маркетинга и рекламы "Оникс" и "Цифра",&nbsp;сеть магазинов бытовой техники и электроники</span></p>\r\n<p style="text-align: left; padding-left: 30px;"><span style="font-family: Pro; font-size: 10pt;">2004 - 2007 г. - Зам. руководителя отд. маркетинга и рекламы, Федеральный дистрибьютор НТС «Градиент»</span>&nbsp;</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<hr />\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 12pt;">О нас</span></strong></span></p>\r\n<p><span style="font-family: Pro;"><iframe style="background-image: url(''img/iframe.png''); display: block; margin-left: auto; margin-right: auto;" src="https://www.youtube.com/embed/yx3VnN5bh2k" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen" data-link="https://www.youtube.com/watch?v=yx3VnN5bh2k"></iframe></span></p>', '', 1, 26, '2016-08-20 16:51:37', 42, '', '2019-04-26 06:52:54', 42, 42, '2019-04-26 07:48:37', '2016-08-20 16:51:37', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 65, 6, 'маркетинг курсы, маркетинг обучение, курсы маркетинга и рекламы, обучение маркетологов', 'Обучение маркетингу и рекламе. Очно и дистанционно. От экспертов-практиков. Курсы маркетологов. Скидки до 15%', 1, 6570, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(134, 231, 'Эксперт в сфере закупок. Обучение на диплом', 'эксперт-в-сфере-закупок', '<h1 style="text-align: center;"><span style="font-family: Pro;">Диплом о переподготовке.&nbsp;Эксперт в сфере закупок</span></h1>\r\n<p style="font-size: 12.16px;"><span style="font-size: 10pt; font-family: Pro;"><strong style="color: #000000; font-size: 10pt; background-color: inherit;">Целевая аудитория:</strong><span style="color: #000000; font-size: 10pt; background-color: inherit;"> Руководители и специалисты&nbsp; государственных учреждений, тендерных отделов, контрактный управляющий.</span> </span></p>\r\n<p>&nbsp;</p>\r\n<p style="text-align: center;"><span style="color: #000000; font-family: Pro; font-size: 12pt;"><strong>Наши курсы включают в себя:</strong></span></p>\r\n<table>\r\n<tbody>\r\n<tr>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Практические знания и навыки&nbsp; работы с закупками,&nbsp;70% практика</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Практику заполнения аукционной и конкурсной документации, анализ ошибок</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Анализ изменений на 2019 г. &nbsp;и типичных ошибок</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Сроки, требования, споры, обжалование и арбитражная практика 44-ФЗ</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Работу на&nbsp;&nbsp;zakupki.gov.ru&nbsp;&nbsp;sberbank-ast.ru</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Основы экономики и ценообразования товаров, работ, услуг</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Основы бюджетной&nbsp;системы, антимонопольного законодательства</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Методики консультирования и экспертизы в сфере закупок</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p style="text-align: center;"><span style="font-size: 10pt; font-family: Pro;"><a onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-size: 10pt; background-color: inherit; color: inherit; font-family: Pro;">Выдается диплом о переподготовке. Разработано в соответствии с Профстандартом</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong><span style="font-size: 10pt;"><a href="#"><img src="images/shablon_diploma.jpg" alt="обучение эксперт в сфере закупок" width="33%" height="185" /></a>&nbsp;<a href="#"><img src="images/shablon_diploma_vnutri.jpg" alt="диплом в сфере закупок" width="33%" height="185" /></a>&nbsp;<a href="#"><img src="images/Diplom_Ekspert_v_sfere_zakupok.jpg" alt="курсы на эксперта в сфере закупок" width="33%" height="185" /></a></span></strong> </span></p>\r\n<hr />\r\n<p>&nbsp;</p>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 27px;">\r\n<td style="background-color: #ffffff; height: 27px; width: 98.9856%;" colspan="2"><span style="font-family: Pro;"><strong>МОДУЛЬ 1. Контрактная система</strong></span></td>\r\n</tr>\r\n<tr style="height: 60px;">\r\n<td style="background-color: #f7f7f7; height: 60px; width: 21.4457%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>1. <b>Основные положения законодательства РФ, регулирующие деятельность по осуществлению закупок, в том числе:</b></strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 60px; width: 77.5399%;">\r\n<p><span style="font-family: Pro;"><span style="color: #000000; font-size: 10pt;">1)&nbsp;Система и структура госзакупок: планирование - обоснование - закупка, способы закупки - исполнение контракта - контроль&nbsp;<br /><br /></span><span style="color: #000000; font-size: 10pt;">2) Гражданский кодекс, Бюджетный кодекс, Федеральный закон&nbsp; № 135-ФЗ «О защите конкуренции», ФЗ&nbsp; № 44-ФЗ «О контрактной системе в сфере закупок товаров, работ, услуг для обеспечения государственных и муниципальных нужд»</span></span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">3) Постановления Правительства РФ, Указы Президента РФ, нормативные и методические документы Минэкономразвития России и иных федеральных органов исполнительной власти</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 21.4457%; height: 14px;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 77.5399%; height: 14px;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 137px;">\r\n<td style="background-color: #f7f7f7; height: 137px; width: 21.4457%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>2. <b>Общие вопросы осуществления закупок в контрактной системе.</b></strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 137px; width: 77.5399%;">\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">1) Особенности планов закупок, планов-графиков на 2019 год</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">2) Обоснование закупок. Признание закупки необоснованной</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">3) Условия выбора метода определения начальной максимальной цены. Способы ее расчета.</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">4) Требования к участникам закупки: основные и дополнительные. Условия допуска к участию в закупках. Анализ «типичных» ошибок</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">5) Антидемпинговые меры в контрактной системе</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">6) Система способов определения поставщиков (подрядчиков, исполнителей) в контрактной системе: сравнительная характеристика, условия применения и особенности</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">7) Правила описания объекта закупки в соответствии с законом № 44-ФЗ</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">8) Обеспечение заявок на конкурсах и аукционах. Размер и формы</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">9) Требования к банковской гарантии. Реестр банковских гарантий</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">10) Обеспечение исполнения контракта. Размер и формы</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">11) Закупки у субъектов малого предпринимательства</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">12) Признание процедур несостоявшимися. Отмена процедур.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 21.4457%; height: 14px;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 77.5399%; height: 14px;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 151px;">\r\n<td style="background-color: #f7f7f7; height: 151px; width: 21.4457%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong><span lang="EN-US">3. <b>Проведение закупок</b></span></strong> </span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 151px; width: 77.5399%;">\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">1) Выбор закупки: обоснование, условия применения определенного способа.</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">2) Порядок подготовки документации для проведения закупки (ее содержание)</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">3) Порядок подготовки технического задания: содержание, алгоритм согласования</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">4) Порядок проведения конкурсов, конкурсов с ограниченным участием, двухэтапных конкурсов</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">5) Порядок проведения открытых аукционов в электронной форме</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">6) Порядок проведения запросов котировок</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">7) Порядок проведения запросов предложений</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">8) Закупка у единственного поставщика (исполнителя, подрядчика). Алгоритм осуществления закупки у единственного поставщика</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">9) Права и обязанности заказчика, специализированной организации при проведении закупки</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">10) Условия допуска к проведению торгов участников</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">11) Критерии и порядок оценки заявок</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">12) Возможные типичные ошибки участников торгов, необходимые действия по минимизации рисков.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 21.4457%; height: 14px;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 77.5399%; height: 14px;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 134px;">\r\n<td style="background-color: #f7f7f7; height: 134px; width: 21.4457%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>4. <b>Государственный и муниципальный контракт.</b></strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 134px; width: 77.5399%;">\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">1) Понятия договора, контракта. Виды контрактов. Библиотека типовых контрактов</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">2) Банковское сопровождение контрактов</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">3) Существенные условия контракта. Требования к структуре и содержанию контракта. Приложения</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">4) Порядок приемки товаров, работ, услуг</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">5) Ответственность сторон по контракту: пени и штрафы, новые правила определения</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">6) Правила и порядок изменения контракта. Дополнительные соглашения</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">7) Правила и порядок расторжения контракта. Алгоритм одностороннего отказа от исполнения контракта</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">8) Уклонение поставщика от подписания контракта. Отказ от заключения контракта заказчиком</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">9) Реестр контрактов</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">10) Отчет об исполнении контракта (этапа исполнения контракта): подготовка и размещение в ЕИС (на ООС)</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">11) Экспертиза исполнения контракта.&nbsp;Виды экспертиз. Требования к экспертному заключению. Требования к экспертам и экспертным организациям</span></p>\r\n<p style="font-size: 12.16px;"><span style="font-size: 10pt; font-family: Pro;"><em><span style="color: #000000;">&nbsp;- Оптимальное содержание контракта для Заказчика/Поставщика?</span></em> </span><br /><span style="font-size: 10pt; font-family: Pro;"><em><span style="color: #000000;">&nbsp;- Как внести нужные изменения ( увеличить цену) в уже заключенный контракт?</span></em> </span><br /><span style="font-size: 10pt; font-family: Pro;"><em><span style="color: #000000;">&nbsp;- Что делать, если сторона не выполняет своих обязательств?</span></em> </span><br /><span style="font-size: 10pt; font-family: Pro;"><em><span style="color: #000000;">&nbsp;- Процедура расторжения контракта - почему, как, в каких случаях?</span></em> </span><br /><span style="font-size: 10pt; font-family: Pro;"><em><span style="color: #000000;">&nbsp;- Как минимизировать или вовсе избежать штрафных санкций?</span></em> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 21.4457%; height: 14px;"><span style="font-size: 10pt;"><em><span style="font-family: arial, helvetica, sans-serif;"><strong>&nbsp;</strong></span></em> </span></td>\r\n<td style="width: 77.5399%; height: 14px;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 127px;">\r\n<td style="background-color: #f7f7f7; height: 127px; width: 21.4457%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>5. <b>Контроль, мониторинг и аудит в сфере закупок. Обжалование.</b></strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 127px; width: 77.5399%;">\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">1) Защита интересов заказчиков и поставщиков. Противодействие недобросовестным действиям заказчиков и поставщиков</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">2) Способы защиты от недобросовестных поставщиков</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">3) Реестр недобросовестных поставщиков. Порядок внесения информации</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">4) Практика контроля центрального аппарата и территориальных органов ФАС России. Плановые и внеплановые проверки</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">5) Порядок подачи и рассмотрения жалоб. Результаты обжалования</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">6) Анализ типичных&nbsp;нарушений заказчиков, комиссий. Практические примеры</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 21.4457%; height: 14px;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 77.5399%; height: 14px;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 107px;">\r\n<td style="background-color: #f7f7f7; height: 107px; width: 21.4457%;"><span style="font-size: 10pt; font-family: Pro;"><strong>6. <b>Практикум на Электронных площадках</b></strong></span></td>\r\n<td style="background-color: #f7f7f7; height: 107px; width: 77.5399%;">\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">1) Формирование и размещение плана закупок</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">2) Детальная подготовка технического задания</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">3) Подготовка распорядительной документации по процедурам закупок (конкурса, аукциона, запроса котировок, запроса предложений, создании комиссий и др.)</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">4) Рассмотрение документации для проведения торгов, личный кабинет заказчика &nbsp;</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">5) Алгоритм размещения аукционной и конкурсной документации для проведения процедуры закупки</span></p>\r\n<p><span style="font-family: Pro; color: #000000; font-size: 10pt;">6) Алгоритм размещения &nbsp;извещения и подачи заявки, подписание контракта и отчетность по контракту</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 16px;">\r\n<td style="background-color: #ffffff; height: 16px; width: 21.4457%;">&nbsp;</td>\r\n<td style="background-color: #ffffff; height: 16px; width: 77.5399%;">&nbsp;</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 27px;">\r\n<td style="background-color: #ffffff; height: 27px; width: 96%;" colspan="2"><span style="font-family: Pro;"><strong>МОДУЛЬ 2.&nbsp;Основы экономики и ценообразования (видео-лекции, самостоятельные работы)</strong></span></td>\r\n</tr>\r\n<tr style="height: 60px;">\r\n<td style="background-color: #f7f7f7; height: 60px; width: 20.3783%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>1.&nbsp;Экономика предприятия</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 60px; width: 75.6217%;">\r\n<p><span style="font-family: Pro;"><strong>1)</strong>&nbsp;Показатели финансовых результатов. Классификация постоянных и переменных затрат. Точка безубыточности.</span></p>\r\n<p><span style="font-family: Pro;"><strong>2)</strong>&nbsp;Ключевой расчет маржинальной прибыли, чистой прибыли</span></p>\r\n<p><span style="font-family: Pro;"><strong>3)</strong>&nbsp;Ключевые показатели эффективности предприятия</span></p>\r\n<p><span style="font-family: Pro;"><strong>4)</strong>&nbsp;Анализ финансовых результатов деятельности</span></p>\r\n<p><span style="font-family: Pro;"><strong>5)</strong>&nbsp;Анализ эффективности использования&nbsp; оборотных средств. Нормирование.</span></p>\r\n<p><span style="font-family: Pro;"><strong>6)</strong>&nbsp;Анализ &nbsp;эффективности использования трудовых ресурсов.&nbsp;</span></p>\r\n<p><span style="font-family: Pro;"><em>-&nbsp;Практические задания точки безубыточности и валовой маржи. Определение наиболее рентабельных проектов, видов деятельности, продукции</em></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 20.3783%; height: 14px;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><em><strong>&nbsp;</strong></em></span></td>\r\n<td style="width: 75.6217%; height: 14px;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><em>&nbsp;</em></span></td>\r\n</tr>\r\n<tr style="height: 137px;">\r\n<td style="background-color: #f7f7f7; height: 137px; width: 20.3783%;">\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;"><strong>2. У</strong></span><span style="font-size: 10pt;"><strong>чет затрат&nbsp;</strong></span><span style="font-size: 10pt;"><strong>и ценообразование</strong></span></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 137px; width: 75.6217%;">\r\n<p><span style="font-family: Pro;"><strong>1)</strong>&nbsp;Бухгалтерский учет, группировка балансовых статей, баланс предприятия,&nbsp; строение балансовых счетов.</span></p>\r\n<p><span style="font-family: Pro;"><strong>2)</strong>&nbsp;Затраты по статьям калькуляции. Учет отдельных видов затрат.&nbsp;</span></p>\r\n<p><span style="font-family: Pro;"><strong>3)</strong>&nbsp;Классификация расходов и затрат,&nbsp; формирующих себестоимость продукции,&nbsp; их отличия</span></p>\r\n<p><span style="font-family: Pro;"><strong>4)</strong>&nbsp;Различные методы ценообразования&nbsp;</span></p>\r\n<p><span style="font-family: Pro;"><em>-&nbsp;Практические задания по расчету себестоимости и цены. Оптимизация затрат. &nbsp;</em></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 22.955px;">\r\n<td style="background-color: #ffffff;" colspan="2">\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro;"><strong>МОДУЛЬ 3. Деловые переговоры, конфликты (видео-лекции и самостоятельная работа)</strong></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 22.955px;">\r\n<td style="background-color: #ffffff;" colspan="2">\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro;"><strong>МОДУЛЬ 4. Основы бюджетной системы и антимонопольного и гражданского законодательства (тест)</strong></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 22.955px;">\r\n<td style="background-color: #ffffff;" colspan="2">\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro;"><strong>МОДУЛЬ 5. Экспертиза и консультирование в сфере закупок (экзамен, тест и самостоятельная работа)</strong></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 22.955px;">\r\n<td style="background-color: #ffffff;" colspan="2">\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro;"><b>МОДУЛЬ 6. Менеджмент и управление персоналом (<strong>видео-лекции и самостоятельная работа)</strong></b></span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<hr />\r\n<p><span style="font-family: Pro;"><strong style="text-indent: -9pt; background-color: inherit; color: inherit; font-family: inherit; font-size: 12pt;">Формат курсов по переподготовке на эксперта в сфере закупок:</strong></span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p><span style="font-family: Pro;">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;<strong style="color: #a22521;">Очное обучение:</strong></span></p>\r\n<p style="padding-left: 90px;"><span style="font-family: Pro;">• 44 ФЗ - 500 учебных часов (40 очных).С&nbsp;09.00 до 16.30 - 5&nbsp; дней с 09.00 до 16.30&nbsp; &nbsp; &nbsp;</span></p>\r\n<p style="padding-left: 90px;"><span style="font-family: Pro;">•&nbsp;44 ФЗ + 223 ФЗ&nbsp; - 500 учебных часов&nbsp; (48 очных).&nbsp;С 09.00 до 17.00 - 6&nbsp; дней с 09.00 до 16.30&nbsp;</span></p>\r\n<p><span style="font-family: Pro;">&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;<strong style="color: #a22521;">Дистанционное обучение:</strong>&nbsp;видео-лекции, аттестационные работы</span></p>\r\n<hr />\r\n<p><span style="font-family: Pro;">&nbsp;<strong><span style="font-size: 12pt;">Акции и скидки:</span></strong> </span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><strong style="color: #a22521;">Скидка 10%</strong>&nbsp;при оплате за 3 недели до обучения.&nbsp;&nbsp;</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><strong style="color: #a22521;">Скидка 5%</strong>&nbsp;при оплате за 2 недели до обучения.</span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p style="text-align: center;"><span style="font-family: Pro;"><a onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<hr />\r\n<p>&nbsp;</p>\r\n<table style="color: inherit; font-family: inherit; font-size: 1rem;">\r\n<tbody>\r\n<tr>\r\n<td style="background-color: #f5f5f5; color: #333333; vertical-align: middle; text-align: center;"><span style="font-size: 12pt; font-family: Pro;"><strong>Преподаватель&nbsp;</strong></span></td>\r\n<td style="background-color: #f5f5f5; color: #333333; vertical-align: middle; text-align: center;">\r\n<p style="color: #333333; background-color: #f5f5f5; vertical-align: middle; text-align: center;"><span style="font-size: 12pt; font-family: Pro;"><strong>Рогожникова Елена Сергеевна</strong></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="background-color: #f5f5f5; vertical-align: middle;"><span style="font-family: Pro;"><img style="display: block; margin-left: auto; margin-right: auto;" src="images/DSC002712.jpg" alt="переподготовка эксперт в сфере госзакупок" width="110" height="136" /></span></td>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-size: 10pt;"><strong><span style="color: inherit; font-family: Pro;">Начальник тендерного и юридического отдела.&nbsp;</span></strong> </span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro; font-size: 10pt;">• 15 летний опыт работы по специализации&nbsp;</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro; font-size: 10pt;">•&nbsp;Опыт работы преподавателем по госзакупкам более 9 лет&nbsp; &nbsp;</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro; font-size: 10pt;">•&nbsp;Опыт работы в ФАС специалистом отдела контроля госзаказов</span></p>\r\n<p><span style="font-size: 10pt;"><strong><span style="font-family: Pro;">Разработаны и проведены программы:</span></strong> </span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro; font-size: 10pt;">• Базовые учебные программы для Заказчиков и Участников по 44-ФЗ, 223-ФЗ</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro; font-size: 10pt;">•&nbsp;275 - ФЗ, Гособоронзаказ</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro; font-size: 10pt;">•&nbsp;Тендер - менеджер, закупки по 223 ФЗ</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro; font-size: 10pt;">• И другие</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<hr />\r\n<p><span style="font-size: 12pt; font-family: Pro;"><b>О нас</b></span></p>\r\n<p>&nbsp;</p>\r\n<p><iframe style="background-image: url(''img/iframe.png''); display: block; margin-left: auto; margin-right: auto;" src="https://www.youtube.com/embed/yx3VnN5bh2k" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture"></iframe></p>', '', 1, 16, '2016-09-13 11:42:01', 42, '', '2019-04-25 07:26:45', 42, 42, '2019-04-29 12:20:12', '2016-09-13 11:42:01', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 84, 14, 'Эксперт в сфере закупок диплом, обучение на эксперта в сфере закупок', 'Эксперт в сфере закупок 44 ФЗ диплом. Программа 310 часов. Стоимость 26 000 руб.', 1, 7690, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(137, 234, 'Диплом Специалист по документационному обеспечению', 'диплом-специалист-по-документационному-обеспечению', '<h1 style="text-align: center;" align="center"><span style="font-family: Pro;">Переподготовка на диплом "Специалист по документационному &nbsp;и организационному обеспечению" в&nbsp;{city_d}</span></h1>\r\n<p><span style="font-family: Pro;"><strong>Целевая аудитория:&nbsp;</strong>специалисты по документационному и организационному обеспечению, юрист, гос. служащие, кадровые работники.</span></p>\r\n<p><span style="font-family: Pro;"><strong>Ведущие:&nbsp;</strong></span></p>\r\n<p><span style="font-family: Pro;"><!-- noindex --></span></p>\r\n<p><span style="font-family: Pro;"><a href="index.php?option=com_content&amp;view=article&amp;id=155&amp;catid=24&amp;Itemid=226" rel="nofollow">Подкорытова Галина Валентиновна</a> - опыт работы руководителем отдела делопроизводства более 20 лет.</span><br /><span style="font-family: Pro;"><a href="index.php?option=com_content&amp;view=article&amp;id=210&amp;catid=23" rel="nofollow">Макарова Юлия Олеговна</a>&nbsp;- тренер по деловым коммуникациям и управленческим компетенциям.</span></p>\r\n<p>&nbsp;</p>\r\n<p style="text-align: center;"><span style="font-family: Pro;"><strong><span style="font-size: 12pt;">На наших курсах вы научитесь:&nbsp;</span></strong> </span></p>\r\n<table>\r\n<tbody>\r\n<tr>\r\n<td>\r\n<ul>\r\n<li><span style="font-family: Pro;">Эффективной организации документооборота и работы офиса&nbsp; &nbsp;&nbsp;</span></li>\r\n</ul>\r\n</td>\r\n<td>\r\n<ul>\r\n<li><span style="font-family: Pro;">Видам и требования управленческой документации</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<ul>\r\n<li><span style="font-family: Pro;">Психологии делового общения</span></li>\r\n</ul>\r\n</td>\r\n<td>\r\n<ul>\r\n<li><span style="font-family: Pro;">Внедрению электронного документооборота</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<p style="font-size: 12.16px; text-align: center;"><span style="font-family: Pro;"><a href="#zakaz" rel="alternate">ОТПРАВИТЬ ЗАЯВКУ</a></span></p>\r\n<p>&nbsp;</p>\r\n<p style="font-size: 12.16px; text-align: left;"><span style="font-family: Pro; font-size: 10pt;"><span style="line-height: 1.3em;">Выдается диплом о переподготовке. Программа разработана по Профстандарту 276&nbsp;</span><a style="font-family: arial, helvetica, sans-serif; font-size: 10pt; line-height: 1.3em;" href="http://xn--d1ababe6aaeff9c5g.xn--p1ai/images/dokument.pdf" rel="alternate">Специалист по документационному &nbsp;и организационному обеспечению</a></span></p>\r\n<p style="font-size: 12.16px; text-align: justify;"><span style="font-family: Pro;">&nbsp;,&nbsp; <a href="#"><img src="images/shablon_diploma.jpg" alt="диплом по профстандарту 276 н" width="30%" height="173" /></a>&nbsp;&nbsp; <a href="#"><img src="images/shablon_diploma_vnutri.jpg" alt="обучение документообеспечению" width="30%" height="173" /></a>&nbsp;&nbsp; <a href="#"><img src="images/diplom_secretarya.jpg" alt="кадровое делопроизводство обучение" width="30%" height="171" /></a></span></p>\r\n<hr />\r\n<p><span style="font-family: Pro;">&nbsp;<span style="font-size: 12pt;"><strong>Программа обучения</strong></span></span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 89px; background-color: #f5f5f5;">\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">1. Нормативно-правовая база</span></strong> </span></p>\r\n</td>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">1</span><span style="font-size: 10pt;">)&nbsp;Нормативно-правовая база делопроизводства. Регламентация&nbsp;работы службы.&nbsp;Зачем нужны регламенты и как оформлять?</span></span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">2)&nbsp;Последние новшества и ожидаемые изменения в нормативной базе.</span>&nbsp;ГОСТ &nbsp;7.0.97-2016 с 01.07.2018 (взамен ГОСТ Р 6.30-2003).&nbsp;<span style="font-size: 10pt;">Организационно-распорядительная документация. Требования к оформлению документов</span></span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3)&nbsp;Источники информации по организации делопроизводства, необходимые в работе.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15.8125px;">\r\n<td style="width: 28.1068%; height: 15.8125px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 68.8932%; height: 15.8125px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2. Виды и требования к управленческой документации</strong></span></p>\r\n</td>\r\n<td style="background-color: #f5f5f5;">\r\n<p style="text-align: left;"><span style="font-size: 10pt; font-family: Pro;">1)&nbsp;Зона ответственности специалиста по документационному обеспечению.&nbsp;&nbsp;Для чего нужна и как определить?&nbsp;</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">2)&nbsp;Требования к оформлению документов. Бланки документов. Схема движения документов.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">3)&nbsp;Назначение и подготовка документов различных систем документации:</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">- организационные документы;</span><br /><span style="font-size: 10pt; font-family: Pro;">- распорядительные документы как форма реализации управленческих решений&nbsp;(приказы, указания,&nbsp; распоряжения, протоколы);</span><br /><span style="font-size: 10pt; font-family: Pro;">- деловая переписка как средство обеспечения внешнего взаимодействия; культура делового письма;&nbsp;оформление деловых писем и их разновидности;</span><br /><span style="font-size: 10pt; font-family: Pro;">- документы внутренней переписки (служебные, докладные, объяснительные записки,&nbsp;заявки);</span><br /><span style="font-size: 10pt; font-family: Pro;">- особенности оформления и организации работы с договорной документацией&nbsp;и иные виды ОРД.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">-&nbsp;Практика составления организационных документов.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 28.1068%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 68.8932%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>3. Организация эффективного документооборота</strong></span></p>\r\n</td>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1)&nbsp;Способы и организация приема и отправки документов. Оптимальные маршруты движения документов в организации. Формы регистрации документов. Отличие регистрации от учета документов.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2)&nbsp;Организация работы с документами внутренней переписки.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3)&nbsp;Организация контроля исполнения документов и поручений.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4)&nbsp;Управление рисками как способ их минимизации и повышения эффективности&nbsp; в работе с документами.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><em style="box-sizing: inherit; margin: 0px; padding: 0px; color: #351e07; font-family: Pro; font-size: 14px; text-align: left;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-size: 10pt;">- Практика оформления журналов регистрации документов</span></em> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 28.1068%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 68.8932%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">4. Разработка локальных нормативных актов по документационному обеспечению управления</span></strong> </span></p>\r\n</td>\r\n<td style="background-color: #f5f5f5;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">1)&nbsp;Общая характеристика документов.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">2)&nbsp;Порядок разработки, утверждения и введения в действие.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">3)&nbsp;Виды, общая характеристика, назначение документов. Значение&nbsp; раздела «Термины и определения».</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><em style="box-sizing: inherit; margin: 0px; padding: 0px; color: #351e07; font-family: Pro; font-size: 14px; text-align: left;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-size: 10pt;">- Практика разработки локальных актов</span></em> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 28.1068%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 68.8932%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="background-color: #f5f5f5;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-weight: bold; color: #0a0a0a; font-family: Pro; font-size: 13.3333px;">5. Основы кадрового делопроизводства</span></td>\r\n<td style="background-color: #f5f5f5;">\r\n<p class="MsoNormal" style="box-sizing: inherit; margin: 5px 0px 0.0001pt; padding: 0px; text-align: justify; color: #351e07; font-family: Pro; font-size: 14px; line-height: normal;"><span style="font-family: Pro;"><span style="box-sizing: inherit; margin: 0px; padding: 0px;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-size: 10pt;">1)</span></span><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-size: 10pt;">&nbsp;Классификация кадровых документов. Виды кадровых документов: штатное расписание, заявление, приказ, трудовой договор, должностная инструкция и т.д.</span></span></p>\r\n<p class="MsoNormal" style="box-sizing: inherit; margin: 5px 0px 0.0001pt; padding: 0px; text-align: justify; color: #351e07; font-family: Pro; font-size: 14px; line-height: normal;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-size: 10pt; font-family: Pro;"><span style="box-sizing: inherit; margin: 0px; padding: 0px;"><span style="box-sizing: inherit; margin: 0px; padding: 0px;">2)</span></span>&nbsp;Поэтапные процедуры оформления приема и увольнения сотрудников. Типичные ошибки документирования процедур приема и увольнения.</span></p>\r\n<p class="MsoNormal" style="box-sizing: inherit; margin: 5px 0px 0.0001pt; padding: 0px; text-align: justify; color: #351e07; font-family: Pro; font-size: 14px; line-height: normal;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-size: 10pt; font-family: Pro;"><span style="box-sizing: inherit; margin: 0px; padding: 0px;"><span style="box-sizing: inherit; margin: 0px; padding: 0px;">3)</span></span>&nbsp;Документирование предоставления отпусков работникам. График отпусков.</span></p>\r\n<p class="MsoNormal" style="box-sizing: inherit; margin: 5px 0px 0.0001pt; padding: 0px; text-align: justify; color: #351e07; font-family: Pro; font-size: 14px; line-height: normal;"><span style="font-family: Pro;"><span style="box-sizing: inherit; margin: 0px; padding: 0px;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-size: 10.5pt;">4)&nbsp;</span></span><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-size: 10pt;">Трудовая книжка работника: учет, правила внесения записей. Обеспечение сохранности трудовых книжек.</span></span></p>\r\n<p class="MsoNormal" style="box-sizing: inherit; margin: 5px 0px 0.0001pt; padding: 0px; text-align: justify; color: #351e07; font-family: Pro; font-size: 14px; line-height: normal;"><span style="font-family: Pro;"><span style="box-sizing: inherit; margin: 0px; padding: 0px;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-size: 10pt;">5)</span></span><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-size: 10pt;">&nbsp;Личная карточка работника: - обязательность заполнения&nbsp;&nbsp; - внесение записей в периоды работы. Учет и хранение личных карточек.</span></span></p>\r\n<p style="box-sizing: inherit; margin: 5px 0px; padding: 0px; text-align: justify; color: #351e07; font-family: Pro; font-size: 14px;"><span style="font-family: Pro;"><i style="box-sizing: inherit; margin: 0px; padding: 0px;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-size: 10pt; line-height: 15.3333px;">- Практика&nbsp;заполнения кадровых документов</span></i> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 28.1068%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 68.8932%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">6. Вопросы внедрения электронного документооборота в организации как средство оптимизации работы с документами</span></strong> </span></p>\r\n</td>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1)&nbsp;Критерии готовности предприятия к внедрению СЭД.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2)&nbsp;Роль предпроектного обследования организации делопроизводства предприятия.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3)&nbsp;Проблемы этапов внедрения системы электронного документооборота.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><em style="box-sizing: inherit; margin: 0px; padding: 0px; color: #351e07; font-size: 13.3333px;">- Как выбрать &nbsp;СЭД. Примеры систем. Разбор&nbsp;систем электронного документооборота на примере программы Директум.</em></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 28.1068%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 68.8932%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>7. Систематизация документов и организация их хранения. Архив</strong></span></p>\r\n</td>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1)&nbsp;Основные признаки формирования дел.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2)&nbsp;Требования к составлению номенклатуры дел, определение сроков хранения документов.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3)&nbsp;Включение электронных документов в номенклатуру дел.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4)&nbsp;Организация текущего хранения документов.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">5)&nbsp;Подготовка и обработка дел к передаче на архивное хранение.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 28.1068%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 68.8932%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>8. Секретарь в структуре управления</strong></span></p>\r\n</td>\r\n<td style="background-color: #f5f5f5;">\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">1)&nbsp;Роль секретаря - помощника руководителя, как участника процесса документационного обеспечения управления предприятием.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">2)&nbsp;Функции и должностные обязанности секретаря.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">3)&nbsp;Деловые и личностные характеристики современного секретаря.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">4)&nbsp;Имидж секретаря, соответствующий имиджу организации.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">5)&nbsp;Техническое оснащение и организация рабочего места в приемной.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">6)&nbsp;Рациональное планирование рабочего времени секретаря.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">7)&nbsp;Совершенствование взаимодействия руководителя и секретаря за счет участия в планировании, рациональном распределении рабочего времени руководителя&nbsp; и расстановки приоритетов.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 28.1068%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 68.8932%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">9. Подготовка и проведение коллегиальных мероприятий и переговоров</span></strong> </span></p>\r\n</td>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1)&nbsp;Организация переговоров и деловых приемов. Протокол деловых встреч и переговоров.&nbsp;Правила проведения деловых переговоров и протокольных мероприятий.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2)&nbsp;Технология общения с иностранными партнерами: программа пребывания иностранной делегации.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3)&nbsp;Подготовка помещения для проведения переговоров, встреча в аэропорту, рассадка в автомобиле, размещение в гостинице.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4)&nbsp;Порядок оформления документов для командировки и отчетных документов по командировке руководителя. Приказ о служебной командировке, служебное задание, командировочное удостоверение.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">5)&nbsp;Подготовка и&nbsp; порядок проведения коллегиальных мероприятий. Оперативные совещания. Документирование решений коллегиальных мероприятия.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 28.1068%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 68.8932%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>10. Организация личных приемов руководителя</strong></span></p>\r\n</td>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1)&nbsp;Правила организации приема посетителей. Порядок записи на прием.&nbsp;Подготовка к приему и его проведение.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2)&nbsp;Документирование результатов личного приема.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3)&nbsp;Правила сервировки чайного стола.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4)&nbsp;Стандарты и рекомендации по оборудованию офисных помещений. Основы эргономики офиса и флористики.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 28.1068%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 68.8932%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>10. Психология делового общения. Основы конфликтологии</strong></span></p>\r\n</td>\r\n<td style="background-color: #f5f5f5;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">1)&nbsp;Конфликтология. Управление организационным конфликтом. Виды, причины, стадии развития конфликта. Стили поведения в конфликте. Этапы разрешения и способы урегулирования конфликта. Методы профилактики конфликтов.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">2)&nbsp;Стресс-менеджмент. Причины и симптомы стрессового напряжения. Способы сохранения и восстановления эмоционального равновесия и работоспособности. Антистресс - профилактика.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">3)&nbsp;Условия переговорного процесса. Стратегии ведения переговоров.&nbsp;Анализ эффективности основных стратегий ведения переговоров</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">4)&nbsp;&nbsp;Инструменты тайм - менеджмента</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">5)&nbsp;Подготовка и планирование переговоров. Анализ факторов ситуации и поведения участников.&nbsp;</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">6)&nbsp;Правила разработки сценария&nbsp; переговоров. Этапы переговорного процесса.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">7)&nbsp;Конструктивное поведение. Противодействие неконструктивному поведению.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="background-color: #ffffff;">\r\n<td style="background-color: #ffffff;">&nbsp;</td>\r\n<td style="background-color: #ffffff;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>11. Проектная работа</strong></span></p>\r\n</td>\r\n<td style="background-color: #f5f5f5;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">Разработка и совершенствование системы документооборота на предприятии</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<hr />\r\n<p><strong><span style="font-family: Pro; font-size: 12pt;">Формат курса: </span></strong></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">•&nbsp;Очно. Продолжительность:&nbsp;2,5 месяца,&nbsp;2-3 раза в неделю:&nbsp;вторник, четверг, пятница с 18.30 до 21.30</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">•&nbsp;Дистанционно. Продолжительность: 3,5 месяца: видео-лекции, выполнение практических заданий, обратная связь от преподавателя</span></p>\r\n<hr />\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 12pt;">Акции и скидки:</span></strong> </span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit; color: inherit; font-size: 1rem;">•&nbsp;</span>Скидка 10%&nbsp;при оплате за 4 недели до обучения.&nbsp;&nbsp;</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit; color: inherit; font-size: 1rem;">•&nbsp;</span>Скидка 5%&nbsp;при оплате за 2 недели до обучения.</span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p style="text-align: center;"><span style="font-family: Pro;"><a onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<hr />\r\n<p><span style="color: #333333; font-family: Pro;"><span style="font-size: 16px;"><b>О нас</b></span></span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p><span style="font-family: Pro;"><iframe style="background-image: url(''img/iframe.png''); display: block; margin-left: auto; margin-right: auto;" src="https://www.youtube.com/embed/yx3VnN5bh2k" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture"></iframe></span></p>\r\n<p style="font-size: 12.16px; text-align: justify;"><span style="font-family: Pro;"></span></p>', '', 1, 24, '2016-09-26 11:33:38', 42, '', '2019-04-25 12:50:12', 42, 0, '0000-00-00 00:00:00', '2016-09-26 11:33:38', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 73, 2, 'Диплом секретарь, диплом документовед, диплом специалист по документационному обеспечению', 'Диплом специалист по документационному обеспечению - секретарь. Программа 260 часов. Стоимость от 24 300 руб.', 1, 7876, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(138, 235, 'Организация хранения документов, обучение архивное дело', 'архив,-обучение-архивное-дело', '<h1><span style="font-family: Pro;">Систематизация документов и организация их хранения. Архив.</span></h1>\r\n<p><span style="font-family: Pro;"><strong>Целевая аудитория:&nbsp;</strong>специалисты по документационному и организационному обеспечению, юрист, гос. служащие, кадровые работники</span></p>\r\n<p><span style="font-family: Pro;"><strong>Ведущий</strong>: <a href="index.php?option=com_content&amp;view=article&amp;id=155&amp;catid=24&amp;Itemid=226">Подкорытова Галина Валентиновна</a> - опыт работы руководителем отдела делопроизводства более 20 лет</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro; font-size: 12pt;"><strong>В программе:</strong></span></p>\r\n<ul>\r\n<li><span style="font-family: Pro;">Основные признаки формирования дел</span></li>\r\n<li><span style="font-family: Pro;">Требования к составлению номенклатуры дел, определение сроков хранения документов</span></li>\r\n<li><span style="font-family: Pro;">Включение электронных документов в номенклатуру дел</span></li>\r\n<li><span style="font-family: Pro;">Организация текущего хранения документов.</span></li>\r\n<li><span style="font-family: Pro;">Подготовка и обработка дел к передаче на архивное хранение.</span></li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro;"><strong>Продолжительность:&nbsp; </strong>2 дня, &nbsp;вторник, четверг с 18.30 до 21.30. Стоимость 4800 руб.</span></p>\r\n<p><span style="font-family: Pro;"><strong>Формы обучения:</strong>&nbsp;информационные модули, дискуссии, моделирование и анализ реальных ситуаций взаимодействия.</span></p>\r\n<p>&nbsp;</p>\r\n<p style="text-align: center;"><a style="font-family: Pro; text-align: center;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></p>', '', 1, 24, '2016-09-26 11:43:40', 42, '', '2019-04-25 12:57:17', 42, 0, '0000-00-00 00:00:00', '2016-09-26 11:43:40', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 18, 45, 'обучение архивное дело, курсы архив', 'Обучение архивное дело. 1 День', 1, 5193, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(139, 236, 'Курсы интернет-маркетинга', 'интернет-маркетинг-обучение', '<h1 class="MsoNormal"><span style="font-family: Pro;">Обучение интернет-маркетологов в {city_d}. Практический курс</span></h1>\r\n<p style="text-align: center;"><span style="font-family: Pro;">{img; /images/obuchenie_internet-marketing3.jpg; /images/obuchenie_internet-marketing2.jpg; /images/obuchenie_internet-marketing.jpg; Обучение интернет-маркетингу, курсы интернет-маркетологов}</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro;">На сегодняшний день актуальны&nbsp;5 инструментов продвижения в интернете&nbsp;это: SEO,&nbsp;Контекстная реклама,&nbsp;SMM,&nbsp;Youtube,&nbsp;Е-mail рассылки</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro;">В зависимости&nbsp; от вида бизнеса у вас будут преобладать разные каналы привлечения клиентов. Для эффективного продвижения нужно использовать все инструменты. Вы можете пройти обучение интернет-маркетингу самостоятельно, но получить серьезные, практические знания в короткие сроки можно только, пройдя курс у профессионалов.&nbsp;</span></p>\r\n<h2 style="text-align: center;"><span style="font-size: 10pt; font-family: Pro;"><strong>Пройдя курсы интернет-маркетолога вы:</strong></span></h2>\r\n<table style="width: 96.2687%;">\r\n<tbody>\r\n<tr style="height: 60px;">\r\n<td style="width: 44.778%; height: 60px;">\r\n<ul>\r\n<li>\r\n<p><span style="font-family: Pro; font-size: 10pt;">Изучите принципы SEO-оптимизации для быстрого запуска собственного бизнеса и вывода сайта в «ТОП»&nbsp;</span></p>\r\n</li>\r\n</ul>\r\n</td>\r\n<td style="width: 47.222%; height: 60px;">\r\n<ul>\r\n<li><span style="font-size: 10pt; font-family: Pro;">Научитесь размещать контекстную рекламу в Яндекс Директ и Google Adwords,&nbsp; оптимизируете затраты</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr style="height: 58.2188px;">\r\n<td style="width: 44.778%; height: 58.2188px;">\r\n<ul>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Освоите профессиональные сервисы, которыми пользуются SEO и SMM специалисты.</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 47.222%; height: 58.2188px;">\r\n<ul>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Узнаете, как продвигать свой видео-канал на YouTube и привлекать подписчиков.</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr style="height: 20px;">\r\n<td style="width: 44.778%; height: 20px;">\r\n<ul>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Научитесь создавать таргетированную рекламу в социальных сетях с максимальной эффективностью.</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 47.222%; height: 20px;">\r\n<ul>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Поймете, как с помощью SMM и e-mail маркетинга повысить лояльность к бренду и привлекать новых клиентов.</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p style="text-align: center;"><span style="font-family: Pro; font-size: 10pt;"><a onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<hr />\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 12pt;">&nbsp;Кому следует пройти обучение:</span></strong></span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<ul>\r\n<li style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">Новичкам в онлайн-бизнесе и начинающим интернет-маркетологам. Курс охватывает широкий спектр базовых тем для комплексного изучения разных областей интернет-маркетинга.</span></li>\r\n<li style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">Фрилансерам. После практической программы обучения интернет маркетингу Вы сможете предлагать свои услуги и зарабатывать в интернете</span></li>\r\n<li style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">Руководителям интернет-магазинов или компаний, которые стремятся организовать канал продаж в сети Интернет. Вы откроете для себя новые каналы привлечения клиентов.</span></li>\r\n<li style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><span style="font-size: 10pt;">Предпринимателям, которые хотят понять основы онлайн-бизнеса и контролировать деятельность подрядчиков в области SEO, SMM.</span></span></li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro;"><iframe style="background-image: url(''../img/iframe.png''); display: block; margin-left: auto; margin-right: auto;" src="https://www.youtube.com/embed/6y0ZuxcwCeg" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen" allow="autoplay; encrypted-media"></iframe></span></p>\r\n<hr />\r\n<h3><span style="font-family: Pro;">&nbsp;<span style="font-size: 12pt; color: #800000;"><strong style="color: #333333;">Программа обучения</strong></span><span style="font-size: 12pt;"><strong>&nbsp;интернет-маркетингу</strong></span></span></h3>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<table style="width: 98.7207%; background-color: #f5f5f5; height: 5px;">\r\n<tbody>\r\n<tr style="height: 115px; background-color: #f5f5f5;">\r\n<td style="width: 14%; height: 115px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">1) Практические инструменты&nbsp;SEO&nbsp;</span></strong></span></p>\r\n</td>\r\n<td style="width: 78.3015%; height: 115px;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">SEO-оптимизация – одна из основ в интернет-маркетинге, так как служит для продвижения интернет-магазинов, корпоративных сайтов. Грамотная внутренняя и внешняя оптимизация позволят Вам опередить конкурентов и привлекать большое количество клиентов из органического поиска без лишних затрат на рекламные кампании.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong><span style="color: #800000;">&nbsp; &nbsp; &nbsp; Что&nbsp; изучите:</span> </strong> </span></p>\r\n<p><span style="font-size: 10pt; color: #000000; font-family: Pro;">1) Актуальные тренды интернет-маркетинга</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2)&nbsp;Алгоритмы работы поисковых систем. Анализ поисковых запросов. Факторы, влияющие на ранжирование сайтов</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) Сбор семантического ядра и его кластеризация. Изучение сервиса Wordstat.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4)&nbsp;Размещение контента на сайте: текстов, инфографика, заполнение метатегов, подбор изображений, видео.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">5)&nbsp;SEO-копирайтинг: правила написания продающих текстов в соответствии с алгоритмами поисковых систем.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">6)&nbsp;Внутренняя перелинковка страниц. Схемы перелинковки.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">7)&nbsp;Внешняя оптимизация сайта. Подбор площадок для размещения ссылок.</span></p>\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>&nbsp; &nbsp; &nbsp;Какие навыки получите:</strong> </span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">1)&nbsp;Сбор семантического ядра, кластеризация ключевых фраз.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2)&nbsp;Работа с сервисом Wordstat.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3)&nbsp;Подготовка технических заданий на SEO-копирайтинг.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4)&nbsp;Выбор подходящих площадок для внешней оптимизации.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 14%; height: 15px; background-color: #ffffff;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 78.3015%; height: 15px; background-color: #ffffff;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 14%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2)&nbsp;</strong><strong>Контекстная реклама: основы размещения рекламы в Яндекс и </strong><strong>Google</strong></span></p>\r\n</td>\r\n<td style="width: 78.3015%; height: 15px;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">Контекстная реклама – эффективный инструмент для продажи товаров и услуг в конкурентных нишах. Грамотное ведение рекламных кампаний позволит сэкономить бюджет и привлекать только целевых посетителей на сайт.</span></p>\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>&nbsp; &nbsp; &nbsp;Что освоите:</strong> </span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">1) Виды рекламных кампаний.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Использование ключевых фраз: подбор подходящих, фильтрация минус-фраз.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) Создание рекламных кампаний в Яндекс Директ и Google Adwords: регистрация в личном кабинете, базовые настройки, создание рекламных объявлений.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4) Изучение факторов, влияющих на стоимость клика.</span></p>\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>&nbsp; &nbsp; Какие навыки&nbsp; получите:</strong> </span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">1) Грамотный подбор ключевых фраз и составление эффективных объявлений.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2)&nbsp;Настройка рекламной кампании в личном кабинете Яндекс Директ и Google Adwords.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 14%; height: 15px; background-color: #ffffff;"><span style="font-family: Pro; font-size: 10pt;"></span></td>\r\n<td style="width: 78.3015%; height: 15px; background-color: #ffffff;"><span style="font-family: Pro; font-size: 10pt;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 14%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;"><span lang="EN-US">3) Системы аналитики. Изучение Яндекс Метрики.</span></span></strong></span></p>\r\n</td>\r\n<td style="width: 78.3015%; height: 15px;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">Грамотная аналитика различных показателей в интернет-маркетинге позволяет улучшить работу сайта, его удобство для пользователей, оценивать затраты на рекламу и SEO, их эффективность и окупаемость инвестиций.</span></p>\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>&nbsp; &nbsp; Что&nbsp; проработаете:</strong> </span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">1. Показатели, которые необходимо отслеживать.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2. Регистрация в Яндекс Метрике, знакомство с личным кабинетом.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3. Изучение отчетов в системе аналитики.</span></p>\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>&nbsp; &nbsp; &nbsp;Какие&nbsp; навыки получите:</strong> </span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">1. Понимание основных отчетов и показателей.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2. Настройка целей системе аналитики.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 14%; height: 15px; background-color: #ffffff;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 78.3015%; height: 15px; background-color: #ffffff;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 14%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;"><span lang="EN-US">4) SMM. Работа в социальных сетях: Facebook, ВКонтакте, Instagram.</span></span></strong></span></p>\r\n</td>\r\n<td style="width: 78.3015%; height: 15px;">\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;">Социальные сети позволяют воздействовать на широкую аудиторию, повышать узнаваемость бренда, продвигать товары и услуги. Грамотное позиционирование групп или страниц в Facebook, ВКонтакте, Instagram обеспечит постоянный приток новых клиентов или партнеров.</span></p>\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>&nbsp; &nbsp; Что изучите:</strong> </span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">1) Возможности соц. сетей, виды сообществ&nbsp;</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">2) Стратегии позиционирования,</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">3)&nbsp;Формирование контент-плана.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">4)&nbsp;Знакомство с сервисами автопостинга (SMM Planner), сбора целевой аудитории (Церебро Таргет).</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">5)&nbsp;Бесплатные методы продвижения.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">6)&nbsp;Запуск таргетированной рекламы в Facebook, ВКонтакте, Instagram.</span></p>\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>&nbsp; &nbsp; Какие навыки&nbsp; получите:</strong> </span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">1) Создание сообщества для Вашего бизнеса.&nbsp;</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">2) Работа в программах автопостинга и сбора целевой аудитории.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">3) Настройка таргетированной рекламы в каждой из социальных сетей: Facebook, ВКонтакте, Instagram.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 14%; height: 15px; background-color: #ffffff;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 78.3015%; height: 15px; background-color: #ffffff;"><span style="font-family: Pro; font-size: 10pt;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 14%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">5) Продвижение канала на YouTube.</span></strong></span></p>\r\n</td>\r\n<td style="width: 78.3015%; height: 15px;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">Создание видео-контента стало сегодня популярным способом рассказать о своей компании, товарах, услугах, как производиться товар, его характеристики.&nbsp; Все это увеличивает лояльность к бренду, увеличивает количество посетителей сайта&nbsp;и приводит новых клиентов.</span></p>\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Что&nbsp; рассмотрите:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Виды видео-контента и особенности его подготовки.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Запуск видео-канала на YouTube, базовые настройки.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Разработка стратегии ведения канала.&nbsp;</span></li>\r\n</ol>\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Какие практические навыки:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Запуск видео-канала на YouTube.</span></li>\r\n<li style="text-align: left;"><span style="font-family: Pro; font-size: 10pt;">Базовые настройки канала для эффективного продвижения.</span></li>\r\n</ol></td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 14%; height: 15px; background-color: #ffffff;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 78.3015%; height: 15px; background-color: #ffffff; text-align: left;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 14%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">6) E-mail маркетинг: основы работы и запуск продающих рассылок.</span></strong></span></p>\r\n</td>\r\n<td style="width: 78.3015%; height: 15px; text-align: left;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">E-mail маркетинг – один из наиболее эффективных инструментов для формирования потенциальной клиентской базы, выстраивания коммуникаций с текущими клиентами, повышения лояльности к бренду.</span></p>\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Что&nbsp; освоите:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Сбор базы подписчиков – основные инструменты и сервисы.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Обзор основных инструментов для рассылок: плюсы и минусы.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Типы рассылок и выбор эффективной стратегии.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Создание цепочки писем и особенности формирования контента.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Знакомство с сервисом для рассылок Send Pulse.</span></li>\r\n</ol>\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Какие навыки получите:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Создание продающего электронного письма.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Настройка сервиса Send Pulse.</span></li>\r\n</ol></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<hr />\r\n<p><strong><span style="font-family: Pro; font-size: 12pt;">Формат обучение интернет-маркетологов:</span></strong></p>\r\n<p>&nbsp;</p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">•&nbsp;<strong style="color: #a22521;">Очное обучение.</strong> Продолжительность:&nbsp;3&nbsp;недели, 2-3 раза в неделю, понедельник, среда, пятница с 18.30 до 21.30.&nbsp; 9&nbsp;занятий&nbsp;</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">•&nbsp;<strong style="color: #a22521;">Дистанционное обучение.&nbsp;</strong>Продолжительность:&nbsp;3 недели. Видео-лекции, аттестационные работы</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro;">Занятия состоят из теоретической и практической частей. Вы познакомитесь с базовыми понятиями интернет-маркетинга, изучите реальные кейсы по различным направлениям онлайн-продаж. В рамках практического обучения Вы научитесь освоите специальные программы для грамотного SEO-продвижения сайтов, ведения групп в социальных сетях ВКонтакте, Facebook и Instagram. Отдельный блок – аналитика показателей с помощью Яндекс Метрики и Google Analytics. Вы поймете, какие показатели следует отслеживать, как повысить конверсию на своих ресурсах.</span></p>\r\n<p><span style="text-align: justify; font-family: Pro;">Благодаря практической направленности курса «Интернет-маркетинг» Вы быстро освоите основные инструменты и сможете начать работу в онлайн-пространстве прямо во время обучения.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro;"><iframe style="background-image: url(''../img/iframe.png''); display: block; margin-left: auto; margin-right: auto;" src="https://www.youtube.com/embed/12JUaN00bp4" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen" data-link="https://www.youtube.com/watch?v=12JUaN00bp4"></iframe></span></p>\r\n<hr />\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 12pt;">Акции и скидки:</span></strong></span></p>\r\n<p>&nbsp;</p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">•&nbsp;<strong>Скидка 10%</strong>&nbsp;при оплате за 4 недели до обучения.&nbsp;&nbsp;</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">•&nbsp;<strong>Скидка 5%</strong>&nbsp;при оплате за 2 недели до обучения.</span></p>\r\n<p>&nbsp;</p>\r\n<p style="text-align: center;"><span style="font-family: Pro;"><a href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<hr />\r\n<table style="background-color: #f5f5f5;">\r\n<tbody>\r\n<tr>\r\n<td>\r\n<p style="color: #333333; text-align: center;"><span style="font-family: Pro; font-size: 12pt;"><strong>Ведущий</strong></span></p>\r\n</td>\r\n<td style="color: #333333; text-align: center;">\r\n<p style="color: #333333; text-align: center;" data-qa="resume-personal-name"><span style="font-family: Pro; font-size: 12pt;"><strong style="color: #333333;">Попов Дмитрий Павлович</strong></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="text-align: center; vertical-align: middle;">\r\n<p><span style="font-family: Pro;"><img src="images/popov_dmitri-2.jpg" alt="обучение интернет маркетингу" width="113" height="149" /></span></p>\r\n</td>\r\n<td>\r\n<p><strong><span style="font-family: Pro;">-Специалист в области интернет коммуникаций</span></strong></p>\r\n<p><span style="font-family: Pro;">-&nbsp;Более&nbsp;8 лет&nbsp;опыта работы в интернет-маркетинге</span></p>\r\n<p><span style="font-family: Pro;">-&nbsp;Более&nbsp;5&nbsp;лет&nbsp;опыта работы&nbsp; преподавателем и бизнес - тренером</span></p>\r\n<p><span style="font-family: Pro;">-&nbsp;Более 3 лет&nbsp;- руководитель проектов&nbsp;в сфере интернет-маркетинга и it-технологий</span></p>\r\n<p><strong><span style="font-family: Pro;">Высшее образование:</span></strong></p>\r\n<p><span style="font-family: Pro;">2005 - 2010&nbsp;г. - УАГС, Экономика и управление предприятием</span></p>\r\n<p><span style="font-family: Pro;">2010 - 2013 г. -&nbsp;УАГС, кандидат социологических наук.</span></p>\r\n<p><span style="font-family: Pro;"><strong>Дополнительное образование</strong>:&nbsp;</span></p>\r\n<p><span style="font-family: Pro;">2010 - 2018 гг. - вебинары, семинары, блоги по продвижению SEO, Яндекс Директ,&nbsp;Google AdWords, SMM, копирайтинг</span></p>\r\n<p><span style="font-family: Pro;">2014 г. - Повышение квалификации&nbsp;«SEO для бизнеса»</span></p>\r\n<p><span style="font-family: Pro;">2013 г. - Тренинги «ТОП-Эксперт»&nbsp;</span></p>\r\n<p><span style="font-family: Pro;">2012 г. - Тренинг «Лидер продаж»</span></p>\r\n<p><strong><span style="font-family: Pro;">Трудовая деятельность:</span></strong></p>\r\n<p><span style="font-family: Pro;">С&nbsp;2017 г. по настоящее время -&nbsp; Руководитель Web-студии федеральной компании Первый Бит,&nbsp; специализирующейся на интернет-продвижении и it-технологиях.</span></p>\r\n<p><span style="font-family: Pro;">2015 - 2016 гг. - руководитель проектов создания с нуля интернет - магазинов: строительство, косметика, продукты</span></p>\r\n<p><span style="font-family: Pro;">2011&nbsp;- 2014&nbsp;гг. - предпринимательская деятельность&nbsp; в интернет маркетинге и продажах.&nbsp;Руководитель, интернет-маркетолог, SEO - специалист, копирайтер</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span style="font-family: Pro;"></span></p>', '', 1, 26, '2016-11-16 09:31:12', 42, '', '2019-04-26 07:32:40', 42, 0, '0000-00-00 00:00:00', '2016-11-16 09:31:12', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 245, 7, 'курсы интернет-маркетинга, обучение интернет маркетингу, курсы интернет маркетологов', 'Обучение интернет-маркетингу. Очно и дистанционно. От экспертов-практиков. Курсы интернет-маркетологов. Скидки до 15%', 1, 12408, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(140, 237, 'Курсы по снабжению и закупкам', 'управление-закупками-и-запасами', '<div>\r\n<h1 class="MsoNormal"><span style="font-family: Pro;">Обучение снабжению и закупкам в {city_d}. Курсы по товарной логистике</span></h1>\r\n</div>\r\n<p><span style="font-family: Pro;">&nbsp;<span style="font-size: 10pt;"><strong>Целевая аудитория:</strong>&nbsp;специалисты по закупкам, &nbsp;руководители отделов&nbsp;закупок, руководители отдела продаж, коммерческие директора</span>&nbsp;</span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p style="text-align: center;"><span style="font-size: 12pt; font-family: Pro;"><strong>Вы научитесь:</strong></span></p>\r\n<table>\r\n<tbody>\r\n<tr>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Организации и оптимизации закупок товара</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Рассчитывать оптимальное количество&nbsp;товарного запаса</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Увеличивать прибыль за счет&nbsp;лучших предложений поставок товара</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Вести продуктивные переговоры&nbsp;</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p style="text-align: center;"><span style="font-size: 10pt; font-family: Pro;"><a onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">Выдается удостоверение по программе "Управление закупками и запасами. Товарная логистика"</span></p>\r\n<p><span style="font-family: Pro;"><a href="#"><img src="images/Udostoverenie_oblozhka.jpg" alt="менеджер по закупкам и запасам удостоверение" width="45%" height="261" />&nbsp;&nbsp;</a>&nbsp; <a href="#"><img src="images/udostoverenie_logista.jpg" alt="управление закупками и запасами удовстоверение" width="45%" height="261" /></a></span></p>\r\n<hr />\r\n<p><strong><span style="font-family: Pro; font-size: 12pt;">&nbsp;Фрагмент обучения:</span></strong></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro;"><iframe style="background-image: url(''../img/iframe.png''); display: block; margin-left: auto; margin-right: auto;" src="https://www.youtube.com/embed/usHoL-a7NAc" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen" data-link="https://www.youtube.com/watch?v=usHoL-a7NAc"></iframe></span></p>\r\n<hr />\r\n<h2 style="text-align: left;"><span style="font-size: 10pt; font-family: Pro;"><strong>Программа курса по управлению закупками и запасами:</strong></span></h2>\r\n<table>\r\n<tbody>\r\n<tr>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;"><strong>1. Управление запасами и закупками</strong></span></p>\r\n</td>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;">1) Показатели эффективности Службы закупа.&nbsp;Влияние целевых показателей Службы закупа(снабжения) на операционные цели Компании.</span></p>\r\n<p><span style="font-family: Pro;">2)&nbsp;Риск – менеджмент в закупочной логистике.</span></p>\r\n<p><span style="font-family: Pro;">3) Бюджетирование в закупках. Показатели планирование бюджета.&nbsp;</span></p>\r\n<p><span style="font-family: Pro;">4)&nbsp;Совокупные затраты на закупку и уровень запасов: влияние этих показателей на финансовые результаты компании.</span></p>\r\n<p><span style="font-family: Pro;">5)&nbsp;Методы прогнозирования оценки потребностей в запасах.&nbsp;</span></p>\r\n<p><span style="font-family: Pro;"><em>Практика: Расчет потребности в запасах</em></span></p>\r\n<p><span style="font-family: Pro;">6) Неликвид. Как избежать? Что делать при образовании неликвида?</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 200px;">&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;"><strong>2. Формирование и анализ запасов и закупок</strong></span></p>\r\n</td>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;">1)&nbsp;Определение потребности в товаре, планирование и прогнозирование потребности.</span></p>\r\n<p><span style="font-family: Pro;">2)&nbsp;Точка заказа.&nbsp;Текущий, страховой, сезонный&nbsp;тип запасов.&nbsp;</span></p>\r\n<p><span style="font-family: Pro;">3)&nbsp;Нормирование запасов, определения величины рабочего, резервного запасов. Способы расчета нормативов.</span></p>\r\n<p><span style="font-family: Pro;"><em>Практика: расчет коэффициентов оборачиваемости, точки запаса, нормативов запасов.</em></span></p>\r\n<p><span style="font-family: Pro;">4)&nbsp;Принцип Парето и классификация по методу&nbsp;А<span lang="EN-US">BC.</span></span></p>\r\n<p><span style="font-family: Pro;">5)&nbsp;Использование метода&nbsp;<span lang="EN-US">XYZ</span>&nbsp;для группировки номенклатуры и управления запасами товарно-материальных ценностей.</span></p>\r\n<p><span style="font-family: Pro;">6)&nbsp;Структура товарного запаса: основные, временные, вынужденные.</span></p>\r\n<p><span style="font-family: Pro;">7)&nbsp;Алгоритм совмещения АВС – XYZ анализа.</span></p>\r\n<p><span style="font-family: Pro;"><em>Практика: АВС анализ на основе результатов деятельности.&nbsp;</em></span></p>\r\n<p><span style="font-family: Pro;"><em>Практика: расчет в Excel, совмещение ABC-XYZ анализ + товарная матрица.</em></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 200px;">&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;"><strong>3. Управление портфелем поставщиков</strong></span></p>\r\n</td>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;">1)&nbsp;Как правильно подобрать потенциальных поставщиков?&nbsp;&nbsp;Анализ потенциальных поставщиков.</span></p>\r\n<p><span style="font-family: Pro;">2)&nbsp; Алгоритм и основные методы выбора поставщика:&nbsp;Практика: метод рейтинговых оценок, метод оценки затрат, &nbsp;метод категорий и предпочтений</span></p>\r\n<p><span style="font-family: Pro;">3) Оценка существующих поставщиков. Перераспределения объема поставок между поставщиками</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 200px;">&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;"><strong>4.&nbsp;Договорные отношения с поставщиками</strong></span></p>\r\n</td>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;">1)&nbsp;Договор поставки как инструмент снижения рисков.</span></p>\r\n<p><span style="font-family: Pro;">2)&nbsp; Порядок заключения договора поставки товаров. Основные составляющие договора. Ответственность сторон по договору поставки.</span></p>\r\n<p><span style="font-family: Pro;"><em>Практика: анализ договора поставки, корректировка существующего договора</em></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 200px;">&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;"><strong>5. Переговоры с поставщиками</strong></span></p>\r\n</td>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;">1) Коммуникация в деловом общении: типичные ошибки и их последствия.&nbsp;Карта переговоров.</span></p>\r\n<p><span style="font-family: Pro;">2) Условия переговорного процесса. Стратегии ведения переговоров.</span></p>\r\n<p><span style="font-family: Pro;">3) Позиционный и принципиальный подход в переговорах.&nbsp;Анализ эффективности основных стратегий ведения переговоров.</span></p>\r\n<p><span style="font-family: Pro;">4) Подготовка и планирование переговоров. Анализ факторов ситуации и поведения участников.&nbsp;Типы клиентов</span></p>\r\n<p><span style="font-family: Pro;">5) Разработка сценария&nbsp; переговоров. Этапы переговорного процесса. Установление контакта, как представиться и понравиться. Правила задавания вопросов, выявление скрытых потребностей, убеждение в переговорах, аргументация и контраргументация, завершение переговоров.</span></p>\r\n<p><span style="font-family: Pro;">6) Эмоциональная составляющая в переговорах.&nbsp;Жесткие переговоры.&nbsp;Кремлевская методика</span></p>\r\n<p><span style="font-family: Pro;">7) Психологические средства влияния. Нужда в переговорах</span></p>\r\n<p><span style="font-family: Pro;">8) Психологические особенности обмена уступками и обсуждения условий.</span></p>\r\n<p><span style="font-family: Pro;">9) Правила эффективной аргументации,&nbsp;убеждение при сопротивлении. Техники работы с сомнениями.</span></p>\r\n<p><span style="font-family: Pro;">10) Методы конструктивного поведения. Противодействие неконструктивному поведению.</span></p>\r\n<p><span style="font-family: Pro;">11) Манипуляция. Как распознать манипуляцию.&nbsp;Методы противодействия манипуляциям</span></p>\r\n<p><span style="font-family: Pro;"><em>Практика: Переговоры и манипуляции в переговорах - «разбор полетов» (моделирование и анализ реальных ситуаций взаимодействия с поставщиками.</em></span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<h3><span style="font-size: 12pt; font-family: Pro;"><strong>Формат обучения:</strong> </span></h3>\r\n<p>&nbsp;</p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">•&nbsp;<strong>Очное обучение.</strong>&nbsp;Продолжительность -&nbsp;2&nbsp;дня: суббота &nbsp;- воскресенье&nbsp;с 09.00 до 18.00 &nbsp;+ 2&nbsp;недели на выполнение самостоятельных работ на закрепление материала. Форма: информационные модули, дискуссии и мозговые штурмы, моделирование и анализ реальных ситуаций, практика.</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">•&nbsp;<strong>Дистанционное обучение.</strong>&nbsp;Продолжительность: 3 недели,&nbsp;видео-лекции, аттестационные работы, обратная связь от преподавателя</span></p>\r\n<p>&nbsp;</p>\r\n<table>\r\n<tbody>\r\n<tr>\r\n<td style="background-color: #f5f5f5;"><span style="font-family: Pro;">Если кроме управления закупками и запасами, вам требуется обучения работе с тендерами, 44-ФЗ и 223-ФЗ, пожалуйста, выбирайте нашу&nbsp;<a href="http://эмменеджмент.рф/obrazovanie/закупки-и-логистика/146-курсы-менеджер-по-закупкам">следующую программу обучения</a>.</span><br /><br /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<hr />\r\n<p><span style="font-family: Pro;">&nbsp;<strong><span style="font-size: 12pt;">Акции и скидки:</span></strong> </span></p>\r\n<p>&nbsp;</p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit; color: inherit; font-size: 1rem;">•&nbsp;</span>Скидка 10%&nbsp;при оплате за 4 недели до обучения.&nbsp;&nbsp;</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit; color: inherit; font-size: 1rem;">•&nbsp;</span>Скидка 5%&nbsp;при оплате за 2 недели до обучения.</span></p>\r\n<p>&nbsp;</p>\r\n<p style="text-align: center;"><span style="font-family: Pro;"><a onclick="yaCounter15669946.reachGoal (''ostavitzayavky''); return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<hr />\r\n<p>&nbsp;</p>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 4px; background-color: #f5f5f5;">\r\n<td style="width: 24.359%; height: 4px; text-align: center;">\r\n<p style="text-align: center;"><span style="font-size: 10pt; font-family: Pro;"><strong><span style="color: #800000;">ВЕДУЩИЕ</span></strong> </span></p>\r\n</td>\r\n<td style="width: 71.641%; height: 4px;">\r\n<p style="text-align: center;"><span style="font-size: 10pt; font-family: Pro;"><strong><span style="color: #800000;">МАКАРОВА ЮЛИЯ ОЛЕГОВНА</span></strong> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 24.359%; height: 15px; text-align: center;"><span style="font-family: Pro;"><img src="images/Makarova_JO.jpg" alt="" width="86" height="113" /></span></td>\r\n<td style="width: 71.641%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">Практикующий бизнес-тренер в области&nbsp; коммуникаций&nbsp;и управленческого консалтинга.&nbsp;</span></p>\r\n<p style="font-weight: 400;"><span style="font-size: 10pt; font-family: Pro;"><b><strong>Более 15 лет&nbsp;практической работы,</strong></b>&nbsp;более 1000 часов проведенных тренингов.</span></p>\r\n<p style="font-weight: 400;"><span style="font-size: 10pt; font-family: Pro;">Опыт тренинговой и преподавательской деятельности&nbsp;<b><strong>более&nbsp;10 лет.&nbsp;&nbsp;</strong></b></span></p>\r\n<p style="font-weight: 400;"><span style="font-size: 10pt; font-family: Pro;">Автор программ обучения: &nbsp;переговоры в закупках,&nbsp;многоуровневые продажи, управление персоналом</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 24.359%; height: 15px; text-align: center;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 71.641%; height: 15px;">\r\n<p style="text-align: center;"><span style="font-size: 10pt; font-family: Pro;">&nbsp;<strong><span style="color: #800000;">НИКОЛАЕВ ВЛАДИМИР АРКАДЬЕВИЧ</span></strong> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 24.359%; height: 15px; text-align: center;"><span style="font-family: Pro;"><img src="images/Nikolaev_VA.jpg" alt="" width="89" height="116" /></span></td>\r\n<td style="width: 71.641%; height: 15px;"><span style="font-family: Pro;">&nbsp;<span style="font-size: 10pt;"><strong>Эксперт-практик в сфере закупок и логистики</strong></span></span>\r\n<p><span style="font-size: 10pt; font-family: Pro;">-&nbsp;<strong>Более 15 лет</strong>&nbsp;опыта работы в сфере управления закупками, складом и транспортом</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">-&nbsp;<strong>Более&nbsp;3&nbsp;лет&nbsp;</strong>преподавательской деятельности.&nbsp;</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">Директор по логистике, автор программ обучения:&nbsp;управление закупками, оптимизация товарного ассортимента, складская логистика, Управление и организация транспортно - логистической деятельности</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<hr />\r\n<p><span style="font-family: Pro;"><b style="font-size: 16px; color: #333333; font-family: georgia, palatino; background-color: inherit;">О нас</b></span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro;"><iframe style="background-image: url(''img/iframe.png''); display: block; margin-left: auto; margin-right: auto;" src="https://www.youtube.com/embed/yx3VnN5bh2k" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture"></iframe></span></p>', '', 1, 27, '2016-11-16 09:56:42', 42, '', '2019-04-26 09:06:21', 42, 0, '0000-00-00 00:00:00', '2016-11-16 09:56:42', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 174, 6, 'курсы менеджера по закупку, курсы закупочного менеджера, обучение товарной логистике, обучение снабжение', 'Курсы снабжения и закупок. Очно и дистанционно. От экспертов-практиков.обучение менеджеров. Скидки до 15% - Звоните. ', 1, 13003, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(141, 238, 'Переподготовка экономика и управление на предприятии', 'экономист,-диплом-о-профессиональной-переподготовке', '<h1><span style="font-family: Pro;">Переподготовка на Диплом «Экономист» - управление экономикой предприятия в&nbsp;{city_d}</span></h1>\r\n<p><span style="font-family: Pro;"><!-- noindex --></span></p>\r\n<p style="font-size: 12.16px;"><span style="font-size: 10pt; font-family: Pro;"><strong>Ведущие:</strong>&nbsp;</span></p>\r\n<p style="font-size: 12.16px;"><span style="font-size: 10pt; font-family: Pro;"><a href="index.php?option=com_content&amp;view=article&amp;id=53&amp;catid=14">Романова Ульяна Владимировна</a>&nbsp;- руководитель финансового отдела, преподаватель</span><br /><span style="font-size: 10pt; font-family: Pro;"><a href="index.php?option=com_content&amp;view=article&amp;id=159&amp;catid=11&amp;Itemid=170" rel="nofollow">Сокол Маргарита Геннадьевна</a> - главный государственный налоговый инспектор.</span><br /><span style="font-size: 10pt; font-family: Pro;"><a href="index.php?option=com_content&amp;view=article&amp;id=105&amp;catid=2&amp;Itemid=112" rel="nofollow">Поплавская Юлия Олеговна</a>&nbsp;- практикующий главный бухгалтер, финансовый директор.</span></p>\r\n<p>&nbsp;</p>\r\n<p style="font-size: 12.16px; text-align: center;"><span style="font-size: 10pt; font-family: Pro;"><a onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p style="font-size: 12.16px;"><span style="font-size: 10pt; font-family: Pro;">Выдается диплом о переподготовке <a href="http://эмменеджмент.рф/obrazovanie/kursy-bukhgalterskogo-ucheta" rel="alternate"><br /></a> </span></p>\r\n<p style="font-size: 12.16px;"><span style="font-size: 10pt; font-family: Pro;"><a href="#"><img src="images/shablon_diploma.jpg" alt="обучение на экономиста" width="30%" height="182" /></a>&nbsp;<a href="#"><img src="images/shablon_diploma_vnutri.jpg" alt="курсы по экономике" width="30%" height="183" /></a>&nbsp;<a href="#"><img src="images/Diplom_economista.jpg" alt="обучение на диплом экономиста" width="30%" height="183" /></a></span></p>\r\n<hr />\r\n<p><span style="font-family: Pro;">&nbsp;<strong><span style="font-size: 12pt;">Программа обучения</span></strong> </span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong style="color: #a22521;">Модуль&nbsp;<strong>1</strong>. Обучение бухгалтерскому учету, налогам и&nbsp;1С: Бухгалтерия</strong> </span></p>\r\n<table>\r\n<tbody>\r\n<tr>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;"><strong>1. Методика бухгалтерского учета</strong></span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n</td>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;">1) Понятия, виды хозяйственного учета, правовая основа бухучета, балансовый метод отражения информации, группировка балансовых статей, баланс предприятия,&nbsp; строение балансовых счетов, счета аналитические и синтетические, план счетов</span><br /><span style="font-family: Pro;">2) Закон о Бухгалтерском учете 402 ФЗ: бухгалтерские документы, классификация документов, требования, предъявляемые к составлению документов</span><br /><span style="font-family: Pro;">3) Инвентаризация (понятие, случаи проведения, сроки, виды)</span><br /><span style="font-family: Pro;">4) Законодательная база о Бухгалтерском учете, ПБУ (положения&nbsp; о бухучете), учетная политика в целях налогового и бухгалтерского учета</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 30%;">&nbsp;</td>\r\n<td style="width: 70%;">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;"><strong>2. Порядок ведения объектов бухгалтерского учета</strong></span></p>\r\n</td>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;">1)&nbsp;Учет уставного капитала. Минимальный уставный капитал. Назначение добавочного и резервного капитала</span><br /><span style="font-family: Pro;">2) Учет денежных средств, учет операций по расчетному счету. Ревизия кассы</span><br /><span style="font-family: Pro;">3) Учет расчетов с подотчетными лицами, покупателями и поставщиками. Нормируемые подотчетные суммы. Командировка.</span><br /><span style="font-family: Pro;">4) Учет материально - производственных запасов. Инвентаризация</span><br /><span style="font-family: Pro;">5) Учет и оценка основных средств и нематериальных активов. Новые критерии НМА и ОС, отличия</span><br /><span style="font-family: Pro;">6) Учет оплаты труда и страховых взносов. Системы оплаты труда, премии, удержания. Пособия. Расчет больничных</span><br /><span style="font-family: Pro;">7) Учет затрат на производство. Методы оптимизации затрат. Распределение косвенных затрат</span><br /><span style="font-family: Pro;">8) Учет готовой продукции и операций по ее реализации. Определение финансового результата</span><br /><span style="font-family: Pro;">9) Учет будущих периодов, сомнительной задолженности. Виды резервов, право создавать</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 30%;">&nbsp;</td>\r\n<td style="width: 70%;">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;"><strong><span lang="EN-US">3. Расчет финансового результата и составление бухгалтерской отчетности</span></strong> </span></p>\r\n</td>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;">1) Учет финансовых результатов</span></p>\r\n<p><span style="font-family: Pro;">2)&nbsp;Бухгалтерская отчетность (баланс, отчет о прибылях и убытках и другие формы отчетности)</span></p>\r\n<p><span style="font-family: Pro;"><em>- Практические задачи и заполнение бухгалтерской отчетности</em></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 30%;">&nbsp;</td>\r\n<td style="width: 70%;">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;"><strong>4. Налоги, налоговая отчетность</strong></span></p>\r\n</td>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;"><strong>Общая система налогообложения.</strong>&nbsp;Расчет и заполнение деклараций на практических примерах</span></p>\r\n<p><span style="font-family: Pro;">- налог на добавленную стоимость</span></p>\r\n<p><span style="font-family: Pro;">- налог на прибыль</span></p>\r\n<p><span style="font-family: Pro;">- налог на имущество</span></p>\r\n<p><span style="font-family: Pro;">- транспортный налог</span></p>\r\n<p><span style="font-family: Pro;">- земельный</span></p>\r\n<p><span style="font-family: Pro;"><strong>Отчетность&nbsp;по&nbsp;страховым&nbsp;взносам,&nbsp;единая&nbsp;отчетность</strong></span><br /><span style="font-family: Pro;"><strong>Налог на доходы физических лиц, вычеты стандартные и имущественные</strong></span></p>\r\n<p><span style="font-family: Pro;">- Льготы по налогообложению, пониженные ставки по страховым взносам.</span><br /><span style="font-family: Pro;">- Выбор оптимальных систем налогообложения</span><br /><span style="font-family: Pro;">- Нормируемые расходы в целях налогообложения</span><br /><span style="font-family: Pro;">- Практические задачи и составление деклараций в ИФНС</span><br /><span style="font-family: Pro;">- Типичные ошибки&nbsp; при составление отчетности</span><br /><span style="font-family: Pro;">- Новации в налоговом учете</span></p>\r\n<p><span style="font-family: Pro;">&nbsp;<strong>Специальные режимы налогообложения:</strong></span></p>\r\n<p><span style="font-family: Pro;">&nbsp;УСНО, ЕНВД, патентная система</span></p>\r\n<p><span style="font-family: Pro;">- смена налогового режима, порядок перехода</span></p>\r\n<p><span style="font-family: Pro;">- порядок ведения книги учета доходов и расходов</span></p>\r\n<p><span style="font-family: Pro;">- совмещение спецрежимов</span></p>\r\n<p><span style="font-family: Pro;">- преимущества и недостатки УСНО&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 30%;">&nbsp;</td>\r\n<td style="width: 70%;">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;"><strong>5. Практические занятия в программе 1С, все участки учета, отчетность налоговая и бухгалтерская</strong></span></p>\r\n</td>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;">1)&nbsp;Ввод реквизитов организации и учетная политика по бухгалтерскому и налоговому учету</span></p>\r\n<p><span style="font-family: Pro;">2)&nbsp;Справочник «номенклатура» и «контрагенты». Для чего нужны справочники?</span></p>\r\n<p><span style="font-family: Pro;">3)&nbsp;Учет кассовых&nbsp; и банковских операций операций. Расчеты с подотчетными лицами. Правильность оформления.</span></p>\r\n<p><span style="font-family: Pro;">4)&nbsp;Учет торговых и производственных операций</span></p>\r\n<p><span style="font-family: Pro;">5)&nbsp;Учет основных средств, Начисление амортизации, амортизационная премия</span></p>\r\n<p><span style="font-family: Pro;">6)&nbsp;Зарплата и кадровый учет, отчетность по страховым взносам и ФСС&nbsp;</span></p>\r\n<p><span style="font-family: Pro;">7)&nbsp;Операции по завершению месяца, регламентированная отчетность - бухгалтерская&nbsp;и налоговая отчетность. НДС, прибыль, НДФЛ</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 30%;">&nbsp;</td>\r\n<td style="width: 70%;">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td style="background-color: #f5f5f5;"><span style="font-family: Pro;"><strong>6.&nbsp;Расчет оплаты труда. Основы кадрового делопроизводства, работа в 1:С ЗУП</strong></span></td>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;">1) Прием, увольнение, карточка сотрудника</span></p>\r\n<p><span style="font-family: Pro;">2) Исчисление среднего заработка. 922 Постановление РФ</span></p>\r\n<p><span style="font-family: Pro;">3) Отпуска. Основной отпуск: порядок предоставления</span></p>\r\n<p><span style="font-family: Pro;">4) Пособие по временной нетрудоспособности и в связи с материнством</span></p>\r\n<p><span style="font-family: Pro;">5) Расчёт командировочных</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 100px;">&nbsp;</td>\r\n<td style="width: 100px;">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 100px; background-color: #f5f5f5;" colspan="2"><span style="font-family: Pro;"><strong>7.&nbsp;Основы составления договоров и&nbsp; основы аудиторской деятельности</strong></span></td>\r\n</tr>\r\n<tr>\r\n<td style="width: 100px;" colspan="2">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td colspan="2">\r\n<p><span style="font-family: Pro;"></span><span style="font-size: 10pt; font-family: Pro;"><strong><span style="color: #a22521;">Модуль&nbsp;2. Финансы предприятия</span></strong> </span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="background-color: #f7f7f7;">\r\n<p><span style="font-family: Pro;"><strong>1. Основы экономики предприятия</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7;">\r\n<p><span style="font-family: Pro;">1) Точка безубыточности. Анализ безубыточности</span></p>\r\n<p><span style="font-family: Pro;">2) Ключевой расчет маржинальной прибыли, чистой прибыли</span></p>\r\n<p><span style="font-family: Pro;">3) Ключевые показатели эффективности предприятия,&nbsp; EBITDA, ROE</span></p>\r\n<p><span style="font-family: Pro;">4) Анализ финансовых результатов деятельности</span></p>\r\n<p><span style="font-family: Pro;">5) Анализ эффективности использования&nbsp; оборотных средств (оборачиваемость, материалоемкость). Нормирование</span></p>\r\n<p><span style="font-family: Pro;">6) Анализ &nbsp;эффективности использования трудовых ресурсов (выработка, трудоемкость)</span></p>\r\n<p><span style="font-family: Pro;"><em>&nbsp; -&nbsp;Практические задания точки безубыточности и валовой маржи. Определение наиболее рентабельных проектов, видов деятельности, продукции</em></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td style="background-color: #f7f7f7;">\r\n<p><span style="font-family: Pro;"><strong>2. Организация аналитического учета затрат</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7;">\r\n<p><span style="font-family: Pro;">1) Бухгалтерский план счетов, с использованием которых осуществляется учет затрат на производство. Группировка балансовых статей, баланс предприятия,&nbsp; строение балансовых счетов.</span></p>\r\n<p><span style="font-family: Pro;">2) Затраты по статьям калькуляции. Учет отдельных видов затрат. Система " Директ - костинг"</span></p>\r\n<p><span style="font-family: Pro;">3) Специфика и области применения различных методов учета производственных затрат: позаказного, котлового, попередельного.</span></p>\r\n<p><span style="font-family: Pro;">4) Классификация расходов и затрат,&nbsp; формирующих себестоимость продукции,&nbsp; их отличия</span></p>\r\n<p><span style="font-family: Pro;">-&nbsp;Практические задания по расчету себестоимости и цены. Оптимизация затрат.</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td style="background-color: #f7f7f7;">\r\n<p><span style="font-family: Pro;"><strong>3. Финансовый менеджмент - Управление инвестициями</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7;">\r\n<p><span style="font-family: Pro;">1) Основные показатели, используемые для расчетов эффективности инвестиционного проекта</span></p>\r\n<p><span style="font-family: Pro;">2) Чистый дисконтированный доход (NPV)</span></p>\r\n<p><span style="font-family: Pro;">3) Индекс рентабельности инвестиций</span></p>\r\n<p><span style="font-family: Pro;">4) Внутренняя норма доходности</span></p>\r\n<p><span style="font-family: Pro;">5) Срок окупаемости инвестиций</span></p>\r\n<p><span style="font-family: Pro;">6) Управление заемным капиталом</span></p>\r\n<p><span style="font-family: Pro;">7) Стоимость капитала: ее составляющие и методы оценки.</span></p>\r\n<p><span style="font-family: Pro;">8) Ликвидность и способы ее оценки</span></p>\r\n<p><span style="font-family: Pro;"><em>-&nbsp;Практические задания по расчету оценки инвестиционных проектов&nbsp;</em></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td style="background-color: #f7f7f7;">\r\n<p><span style="font-family: Pro;"><strong>4. Эффективная финансово – экономическая служба</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7;">\r\n<p><span style="font-family: Pro;">1) Требования к финансовой отчетности для руководителей.</span></p>\r\n<p><span style="font-family: Pro;">2) Принципы учетной политики управленческого учета.</span></p>\r\n<p><span style="font-family: Pro;">3) Чтение и интерпретации финансовых отчетов. Практикум по подготовке и использованию финансовой отчетности</span></p>\r\n<p><span style="font-family: Pro;">4) Функции финансового управляющего.</span></p>\r\n<p><span style="font-family: Pro;">5) Распределение функций финансово-экономической службы.</span></p>\r\n<p><span style="font-family: Pro;">6) Показатели эффективности финансовой службы.</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td style="background-color: #f7f7f7;">\r\n<p><span style="font-family: Pro;"><strong>5.&nbsp;Бюджетирование – как часть системы управления предприятием.</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7;">\r\n<p><span style="font-family: Pro;">1) Сущность бюджетного управления, бюджет в системе планов предприятия;</span></p>\r\n<p><span style="font-family: Pro;">2) Постановка системы бюджетного управления:&nbsp; определение участников процесса бюджетного управления,&nbsp; определение центров финансовой ответственности, учета (ЦФО, ЦФУ);</span></p>\r\n<p><span style="font-family: Pro;">3) Подходы к построению системы бюджетирования на предприятии;</span></p>\r\n<p><span style="font-family: Pro;">4) Регламентация системы бюджетирования на предприятии. Бюджетная система:&nbsp; Система бюджетов на предприятии: Бюджет продаж, бюджет производства, бюджет накладных расходов, бюджет доходов и расходов, бюджет движения денежных средств.&nbsp; Взаимосвязь основных плановых и отчетных форм между собой. Контроль исполнения бюджетов – ключевая функция системы бюджетного управления.&nbsp; Анализ исполнения бюджета.</span></p>\r\n<p><span style="font-family: Pro;"><em>&nbsp;-&nbsp;Практические задания по разработке бюджетов, контроль и анализ. Причины невыполнения бюджетов.</em></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td style="background-color: #f7f7f7;">\r\n<p><span style="font-family: Pro;"><strong>6.&nbsp;Финансовая отчетность. Основные методы финансового анализа</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7;">\r\n<p><span style="font-family: Pro;">1) Финансовый анализ, как метод оценки текущего и перспективного финансового состояния предприятия: трендовый, факторный, метод цепных подстановок, горизонтальный, вертикальный</span></p>\r\n<p><span style="font-family: Pro;">2) Анализируем бухгалтерский баланс, в чем отличие от управленческого баланса</span></p>\r\n<p><span style="font-family: Pro;">3) Особенности составления отчета о прибылях и убытках, отличие от Бюджета доходов и расходов</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td style="background-color: #f7f7f7;">\r\n<p><span style="font-family: Pro;"><strong>7.&nbsp;Практические примеры построения&nbsp; бюджетов в программе Excel – программа для управленческого учета и системы бюджетирования на предприятии.</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7;">\r\n<p><span style="font-family: Pro;">1) Изучение&nbsp;наиболее востребованных&nbsp;формул и функций Excel&nbsp;для построения бюджетов.</span></p>\r\n<p><span style="font-family: Pro;">2) Практические задания в&nbsp;Excel&nbsp;и 1С «Бухгалтерия».</span></p>\r\n<p><span style="font-family: Pro;">&nbsp;Создание сложных формул и выявление ошибок. Условия в формулах,&nbsp;сводные таблицы</span></p>\r\n<p><span style="font-family: Pro;">1) Поиск и замена данных, сортировка по значениям одного столбца, формату, нескольким столбцам, части диапазона</span></p>\r\n<p><span style="font-family: Pro;">2) Установка фильтра и работа с ним</span></p>\r\n<p><span style="font-family: Pro;">3) Отбор по значению, формату, условию, по ячейке, отбор наибольших и наименьших значений, отказ от отбора</span></p>\r\n<p><span style="font-family: Pro;">4) Создание сводной таблицы.&nbsp;Форматирование сводной таблицы.&nbsp;Модификация таблицы</span></p>\r\n<p><span style="font-family: Pro;">5) Вертикальный поиск ВПР() и горизонтальный поиск ГПР()</span></p>\r\n<p><span style="font-family: Pro;">6) Расчет и подсчет указанных ячеек: СЧЕТЕСЛИ()</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<table style="color: inherit; font-family: inherit; font-size: 1rem; width: 100%;">\r\n<tbody>\r\n<tr style="height: 3px;">\r\n<td style="width: 30%; height: 3px; background-color: #f7f7f7;"><span style="font-family: Pro; font-size: 10pt;"><strong>Проектная работа</strong></span></td>\r\n<td style="width: 70%; height: 3px; background-color: #f7f7f7;"><span style="font-size: 10pt; font-family: Pro;">Анализ и разработка показателей по финансовому анализу</span></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span style="font-size: 12pt;"><strong><span style="font-family: Pro;">Формат курса</span></strong> </span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="font-size: 10pt;">•&nbsp;Очное обучение.&nbsp;</span><span style="font-size: 13.3333px; background-color: inherit; color: inherit;">Продолжительность: 4 месяца, 2 - 3 раза в неделю вечером или в выходной день.&nbsp;</span></span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro; font-size: 10pt; background-color: inherit; color: inherit;">•&nbsp;Дистанционное обучение. Формат: видео-лекции, аттестационные работы</span></p>\r\n<hr />\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 12pt;">Акции и скидки:</span></strong> </span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit; color: inherit; font-size: 1rem;">•&nbsp;</span>Скидка 10%&nbsp;при оплате за 4 недели до обучения.&nbsp;&nbsp;</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit; color: inherit; font-size: 1rem;">•&nbsp;</span>Скидка 5%&nbsp;при оплате за 2 недели до обучения.</span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p style="text-align: center;"><span style="font-family: Pro;"><a onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<hr />\r\n<p><span style="color: #333333; font-family: Pro;"><span style="font-size: 16px;"><b>О нас</b></span></span></p>\r\n<p><span style="font-family: Pro;"><iframe style="background-image: url(''img/iframe.png''); display: block; margin-left: auto; margin-right: auto;" src="https://www.youtube.com/embed/yx3VnN5bh2k" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture"></iframe></span></p>\r\n<p style="font-size: 12.16px;"><span style="font-family: Pro;"></span></p>', '', 1, 14, '2016-11-20 17:41:31', 42, '', '2019-04-30 05:06:19', 42, 0, '0000-00-00 00:00:00', '2016-11-20 17:41:31', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 42, 12, 'переподготовка экономика и управление на предприятии, переподготовка на экономиста, переподготовка экономика предприятий, профессиональная переподготовка экономика', 'Обучение на диплом о переподготовке «Экономист». Переподготовка экономика и управление на предприятии. Очно и дистанционно. Скидки до 15% - Звоните ', 1, 7993, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(187, 291, 'Тренинг для администраторов', 'тренинг-продаж-для-администраторов', '<h1 style="text-align: justify;" align="center"><span style="font-size: 15.0pt;">Обучение администраторов, увеличение продаж и клиентоориентированности</span></h1>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>Результат тренинга</strong> </span>– это обращения потенциального клиента в постоянного клиента.</p>\r\n<p>Как правило администратор одновременно должен быть, как хорошим коммуникатором, так организатором. Администратор чаще &nbsp;консультирует клиента,&nbsp;но продавать не всегда получается.&nbsp;Если вы хотите&nbsp;продавать услугу ЗДЕСЬ &nbsp;и СЕЙЧАС,&nbsp;понимать клиентов и мотивировать их вернуться снова, то данный тренинг поможет вам получить необходимые навыки.</p>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>Кому необходим:</strong></span><span style="font-size: 10pt;"></span>администраторы гостиниц, клиник, салонов, ресторанов.&nbsp;</p>\r\n<p style="text-align: center;"><strong><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">ВЫ ПОЛУЧИТЕ:</span></strong></p>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 37px;">\r\n<td style="width: 46%; height: 37px;">\r\n<ul>\r\n<li>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Увеличите &nbsp;продажи и клиетоориентированность&nbsp;</span></p>\r\n</li>\r\n</ul>\r\n</td>\r\n<td style="width: 49%; height: 37px;">\r\n<ul>\r\n<li>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Получите навыки <strong>работы с трудными клиентами</strong></span></p>\r\n</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr style="height: 1.03125px;">\r\n<td style="width: 46%; height: 1.03125px;">\r\n<ul>\r\n<li>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Разовьете&nbsp;навыки <strong>установления контактов</strong>,&nbsp;<strong>выявления потребностей</strong> и <strong>проведения презентаций</strong></span></p>\r\n</li>\r\n</ul>\r\n</td>\r\n<td style="width: 49%; height: 1.03125px;">\r\n<ul>\r\n<li>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Приобретете&nbsp;навыки <strong>эффективной коммуникации</strong>&nbsp;</span></p>\r\n</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p style="text-align: center;"><a title="Нажмите, чтобы оформить заказ" onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></p>\r\n<p style="text-align: center;"><strong><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">ПРОГРАММА ТРЕНИНГА</span></strong></p>\r\n<table style="width: 100%; background-color: #ffffff;">\r\n<tbody>\r\n<tr style="height: 156px;">\r\n<td style="background-color: #f5f5f5; width: 27.476%;">\r\n<p>1. Подготовка к&nbsp;контакту</p>\r\n</td>\r\n<td style="background-color: #f5f5f5; width: 71.033%;">\r\n<p>Роль и значение администратора. Образ администратора</p>\r\n<p>Организация высокоэффективных продаж. Основные правила продаж администраторов;</p>\r\n<p>Деловой этикет. Этика и психология обслуживания;</p>\r\n<p>Язык тела, жестов, сила улыбки;</p>\r\n<p>Как эффективно спрашивать и отвечать, наблюдать и слушать</p>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>- Тренируем вступление в контакт с покупателем</strong></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 98.5091%;" colspan="2">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 93px;">\r\n<td style="background-color: #f5f5f5; width: 27.476%;">\r\n<p>2.&nbsp;Техника продаж</p>\r\n</td>\r\n<td style="background-color: #f5f5f5; width: 71.033%;">\r\n<p>Первое общение с клиентом</p>\r\n<p>Как правильно задавать вопросы клиентам и какие;</p>\r\n<p>Консультации с целью формирования заказа. Направляющие вопросы.</p>\r\n<p>Способы презентации цены. Разговор на языке выгод</p>\r\n<p>Как отвечать на вопросы клиентов</p>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>- Практика: Выявляем&nbsp;потребности клиентов, проводим презентацию, &nbsp;отвечаем правильно на вопросы</strong></span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>- Как довести до продажи? Сценарии и практика &nbsp;получения оплаты, заключение договора</strong></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 27.476%;">&nbsp;</td>\r\n<td style="width: 71.033%;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 90px;">\r\n<td style="background-color: #f5f5f5; width: 27.476%;">\r\n<p>3.&nbsp;Типы клиентов и методы работы с ними</p>\r\n</td>\r\n<td style="background-color: #f5f5f5; width: 71.033%;">\r\n<p>Психологический портрет гостя. Как определить и работать с ними.</p>\r\n<p>Особенности работы с VIP гостями.&nbsp;</p>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>- Практика моделирования&nbsp;ситуаций с клиентами</strong></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 27.476%;">&nbsp;</td>\r\n<td style="width: 71.033%;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="background-color: #f5f5f5; width: 27.476%;">\r\n<p>4.&nbsp;Работа с недовольными клиентами</p>\r\n</td>\r\n<td style="background-color: #f5f5f5; width: 71.033%;">\r\n<p>Амортизация конфликтного поведения</p>\r\n<p>Стили поведения в конфликте, стратегии и тактики. Скрипты поведения в конфликте.</p>\r\n<p>Управление конфликтами. Самоуправление.</p>\r\n<p>Как справиться со своими эмоциями, как нейтрализовать эмоции клиента</p>\r\n<p><strong style="font-family: arial, helvetica, sans-serif;"><span style="font-family: arial, helvetica, sans-serif;">-</span> Основные ошибки при принятии жалоб</strong></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>- Техники выравнивания напряжения</strong></span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<!-- [if gte mso 9]><xml>\r\n <o:OfficeDocumentSettings>\r\n  <o:TargetScreenSize>800x600</o:TargetScreenSize>\r\n </o:OfficeDocumentSettings>\r\n</xml><![endif]-->\r\n<p class="MsoNormal" style="text-align: justify;">Практические навыки обязательно отрабатываются на ваших &nbsp;товарах и обязательно с учетом вашей специфики. Ваши сотрудники начинают продавать больше на следующий же день после тренинга.&nbsp;&nbsp;<span style="font-family: arial,helvetica,sans-serif;">&nbsp;<span style="color: #800000; font-family: ''arial black'', sans-serif;"><strong><a class="modal" style="color: #800000;" href="#call_me" rel="{size:{x:460,y:130}}">ОТПРАВИТЬ ЗАЯВКУ</a></strong></span></span></p>\r\n<p style="text-align: justify;"><span style="font-family: arial,helvetica,sans-serif;"><strong>Продолжительность</strong></span>&nbsp;2 дня &nbsp;с 10 до 18.00.&nbsp;</p>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 15px;">\r\n<td style="width: 10%; text-align: right; height: 15px;">&nbsp;</td>\r\n<td style="width: 34%; height: 15px;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 10%; background-color: #f5f5f5; height: 15px; text-align: center;">\r\n<p style="text-align: center;"><strong><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">ВЕДУЩИЙ ТРЕНИНГА:</span></strong></p>\r\n</td>\r\n<td style="width: 34%; background-color: #f5f5f5; height: 15px; text-align: left;">\r\n<p><strong><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">ПОНАМАРЕВА ОЛЬГА ВЛАДИМИРОВНА</span></strong></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 215.188px;">\r\n<td style="width: 10%; background-color: #f5f5f5; height: 215.188px; text-align: right;">\r\n<p style="text-align: center;"><img src="images/IMG_0727---.JPG" alt="" width="111" height="146" /><img src="images/ponamareva.JPG" alt="тренинг для администраторов" width="105" height="138" /></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n</td>\r\n<td style="width: 34%; background-color: #f5f5f5; height: 215.188px;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><span style="text-align: justify;">- один из</span><span style="text-align: justify;"></span><b style="font-family: arial, helvetica, sans-serif; font-size: 10pt; text-align: justify;">ведущих бизнес-тренеров</b><span style="text-align: justify;"></span><span style="text-align: justify;">Екатеринбурга, практикующий специалист в области продаж, деловой коммуникации и переговоров.</span></span></p>\r\n<p class="MsoNormal" style="text-align: justify;"><span style="line-height: 115%; font-family: arial, helvetica, sans-serif; font-size: 10pt;"></span></p>\r\n<p class="MsoNormal" style="text-align: justify;"><span style="line-height: 115%; font-family: arial, helvetica, sans-serif; font-size: 10pt;">Более&nbsp;<b>10 лет</b>&nbsp;практического опыта в продажах.</span></p>\r\n<p class="MsoNormal" style="text-align: justify;"><span style="line-height: 115%; font-family: arial, helvetica, sans-serif; font-size: 10pt;">Более&nbsp;<b>1000 часов</b>&nbsp;проведенных тренингов.</span></p>\r\n<p class="MsoNormal" style="text-align: justify;"><span style="line-height: 115%; font-family: arial, helvetica, sans-serif; font-size: 10pt;"></span></p>\r\n<p class="MsoNormal" style="text-align: justify;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><b><span style="line-height: 115%;">В числе клиентов:</span></b> </span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><span style="line-height: 115%;">оптовая компания "ОптТекстиль</span><span lang="PT" style="line-height: 115%;">", "</span><span style="line-height: 115%;">ЛЮКС-сервис"</span>,«Перина Перони»</span>,&nbsp;<span style="line-height: 115%;">консалтинговая компания "Формат”, транспортная компания "Автопоезд", турагенство&nbsp;</span><span lang="ES-TRAD" style="line-height: 115%;">"TourLine" , "</span><span style="line-height: 115%;">Автоэкспертиза</span><span lang="ES-TRAD" style="line-height: 115%;">", , "</span><span style="line-height: 115%;">Печатный дом", продажи бурового оборудования "Промстрой", оптовая компания "Стройлит" веб- студия "Артсофте", строительная компания "Новотех</span><span lang="PT" style="line-height: 115%;">", "1000&nbsp;</span><span style="line-height: 115%;">Мелочей", Смирнов Бэттериз</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p style="text-align: justify;">&nbsp;</p>', '', 1, 18, '2017-04-19 06:13:34', 42, '', '2019-04-16 04:58:26', 42, 0, '0000-00-00 00:00:00', '2017-04-19 06:21:40', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 29, 12, 'Тренинг для администраторов, обучение администраторов', 'Обучение  продажам администраторов Продолжительность 2 дня. Стоимость 10.000 руб. УЦ ЭмМенеджмент', 1, 2403, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(143, 241, 'Обучение на главного бухгалтера', 'обучение-главный-бухгалтер', '<h1 style="box-sizing: inherit; margin: 20px 0px; padding: 0px; font-size: 15px; text-align: center; font-family: verdana; color: #1d4e77; background-color: #fefefe;"><span style="font-family: Pro;">Обучение на главного бухгалтера в {city_d}. Диплом о переподготовке</span></h1>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>Преподаватели:</strong></span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><a href="http://xn--d1ababe6aaeff9c5g.xn--p1ai/2-uncategorised/53-biznes-trener-nasonova-nadezhda-yurevna">Насонова Надежда Юрьевна&nbsp;</a>- финансовый директор, практикующий главный бухгалтер.</span><br /><span style="font-size: 10pt; font-family: Pro;"><a href="http://xn--d1ababe6aaeff9c5g.xn--p1ai/2-uncategorised/105-%D1%81%D1%83%D0%B1%D0%B1%D0%BE%D1%82%D0%B8%D0%BD%D0%B0-%D1%8E%D0%BB%D0%B8%D1%8F-%D0%BE%D0%BB%D0%B5%D0%B3%D0%BE%D0%B2%D0%BD%D0%B0">Поплавская Юлия Олеговна</a>&nbsp;-&nbsp; практикующий главный бухгалтер, финансовый директор</span><br /><span style="font-size: 10pt; font-family: Pro;"><a href="index.php?option=com_content&amp;view=article&amp;id=159&amp;catid=11&amp;Itemid=170">Сокол Маргарита Геннадьевна</a> - главный государственный налоговый инспектор</span><br /><span style="font-size: 10pt; font-family: Pro;"><a href="index.php?option=com_content&amp;view=article&amp;id=160&amp;catid=11&amp;Itemid=170">Прокопьева Зоя Александровна </a> - главный государственный налоговый инспектор</span><br /><span style="font-size: 10pt; font-family: Pro;"><a href="index.php?option=com_content&amp;view=article&amp;id=210&amp;catid=23">Макарова Юлия Олеговна</a> - тренер по управленческим компетенциям</span></p>\r\n<p>&nbsp;</p>\r\n<p style="text-align: center;"><span style="font-family: Pro;"><strong>ВЫ НАУЧИТЕСЬ:</strong></span></p>\r\n<table>\r\n<tbody>\r\n<tr>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Разрешать сложные&nbsp;вопросы&nbsp;НКРФ, понимать критерии налоговых проверок&nbsp;&nbsp;</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Предупреждать типичные ошибки при ведении налогового учета</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Инструментам работы в&nbsp;условиях легализации доходов и расходов</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Разбираться в&nbsp; сложностях налоговой&nbsp; и бухгалтерской отчетности</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Управлять коллективом и трудовыми отношениями</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Составлять управленческую отчетность, финансовый анализ, бюджетирование</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>Модули обучения:</strong> </span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">1. Финансовый менеджмент, анализ, бюджетирование. Инвестиции.</span><br /><span style="font-size: 10pt; font-family: Pro;">2. Налоги, бух. отчетность, МСФО, аудит.</span><br /><span style="font-size: 10pt; font-family: Pro;">3.&nbsp;Трудовое право, трудовые правоотношения.</span><br /><span style="font-size: 10pt; font-family: Pro;">4. Управленческие компетенции.</span></p>\r\n<p>&nbsp;</p>\r\n<p style="text-align: center;"><span style="font-family: Pro; font-size: 10pt;"><a onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<p>&nbsp;</p>\r\n<p>Выдаётся диплом о переподготовке</p>\r\n<p><a href="#"><img src="images/slider/shablon_diploma.jpg" alt="курсы главного бухгалтера" width="30%" height="245" />&nbsp;&nbsp;</a> <a href="#"><img src="images/slider/shablon_diploma_vnutri.jpg" alt="обучение главного бухгалтера" width="30%" height="245" />&nbsp;&nbsp;</a> <a href="#"><img src="images/slider/бухгалтер.jpg" alt="переподготовка главного бухгалтера" width="30%" height="245" /></a></p>\r\n<hr />\r\n<p style="text-align: left;"><span style="font-family: Pro;"><strong><span style="font-size: 12pt;">Фрагмент курса:</span></strong> </span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro;"><iframe style="display: block; margin-left: auto; margin-right: auto;" src="https://www.youtube.com/embed/mLFi-_O0quE" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture"></iframe></span></p>\r\n<hr />\r\n<p style="text-align: center;"><span style="font-family: Pro; font-size: 12pt;"><strong>Программа обучения на главного бухгалтера:</strong></span></p>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 49%; height: 15px;" colspan="2">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong><span style="color: #a22521;">МОДУЛЬ 1. ФИНАНСОВЫЙ МЕНЕДЖМЕНТ</span> </strong> </span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.0299%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>1. Экономика предприятия</strong></span></p>\r\n</td>\r\n<td style="width: 36.9701%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong>&nbsp;Точка безубыточности. Анализ безубыточности.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong>&nbsp;Ключевой расчет маржинальной прибыли, чистой прибыли.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>3)</strong>&nbsp;Ключевые показатели эффективности предприятия,&nbsp; EBITDA, ROE.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>4)</strong>&nbsp;Анализ финансовых результатов деятельности.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 12.0299%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 36.9701%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.0299%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2. Организация аналитического учета затрат</strong></span></p>\r\n</td>\r\n<td style="width: 36.9701%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>1)</strong>&nbsp;Бухгалтерский план счетов, с использованием которых осуществляется учет затрат на производство. Группировка балансовых статей, баланс предприятия,&nbsp; строение балансовых счетов.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>2)</strong>&nbsp;Затраты по статьям калькуляции. Учет отдельных видов затрат. Система " Директ - костинг".</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>3)</strong>&nbsp;Специфика и области применения различных методов учета производственных затрат: позаказного, котлового, попередельного.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 12.0299%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 36.9701%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.0299%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">3. Финансовая отчетность. Основные методы финансового анализа</span></strong> </span></p>\r\n</td>\r\n<td style="width: 36.9701%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>1)</strong>&nbsp;Финансовый анализ, как метод оценки текущего и перспективного финансового состояния предприятия: трендовый, факторный, метод цепных подстановок, горизонтальный, вертикальный.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>2)</strong>&nbsp;Анализируем бухгалтерский баланс, в чем отличие от управленческого баланса.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>3)</strong>&nbsp;Особенности составления отчета о прибылях и убытках, отличие от Бюджета доходов и расходов.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>4)</strong>&nbsp;Коэффициенты финансового анализа: платежеспособность и&nbsp;ликвидность, &nbsp;коэффициент инвестирования, коэффициенты финансовой устойчивости, деловой активности.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 12.0299%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 36.9701%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.0299%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">4. Управление инвестициями</span></strong> </span></p>\r\n</td>\r\n<td style="width: 36.9701%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>1)</strong>&nbsp;Основные показатели, используемые для расчетов эффективности инвестиционного проекта.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>2)</strong>&nbsp;Чистый дисконтированный доход (NPV), индекс рентабельности инвестиций, внутренняя норма доходности.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>3)</strong>&nbsp;Срок окупаемости инвестиций. Резерв безопасности проекта.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>4)</strong>&nbsp;Управление заемным капиталом. Эффект финансового рычага.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>5)</strong>&nbsp;Стоимость капитала: ее составляющие и методы оценки.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>6)</strong>&nbsp;Ликвидность и способы ее оценки.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 12.0299%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 36.9701%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.0299%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>5. Бизнес-план – первый план компании.&nbsp;Как получить желаемый результат и не потерять вложенные средства, при реализации нового инвестиционного проекта</strong></span></p>\r\n</td>\r\n<td style="width: 36.9701%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>1)</strong>&nbsp;Производственный план. Общий подход к организации производства.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>2)</strong>&nbsp;Финансовый план. Бюджетирование, как составная часть финансового планирования.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>3)</strong>&nbsp;Оценка рисков.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 12.0299%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 36.9701%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.0299%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>6. Бюджетирование – как часть системы управления предприятием</strong></span></p>\r\n</td>\r\n<td style="width: 36.9701%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>1)</strong>&nbsp;Постановка системы бюджетного управления:&nbsp; определение участников процесса бюджетного управления,&nbsp; определение центров финансовой ответственности, учета (ЦФО, ЦФУ).</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>2)</strong>&nbsp;Бюджетная система:&nbsp; Система бюджетов на предприятии: Бюджет продаж, бюджет производства, бюджет накладных расходов, бюджет доходов и расходов, бюджет движения денежных средств.&nbsp; Взаимосвязь основных плановых и отчетных форм между собой. Контроль исполнения бюджетов – ключевая функция системы бюджетного управления.&nbsp; Анализ исполнения бюджета.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 12.0299%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 36.9701%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.0299%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>7. Практические примеры построения&nbsp; бюджетов в программе Excel – программа для управленческого учета и системы бюджетирования на предприятии</strong></span></p>\r\n</td>\r\n<td style="width: 36.9701%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>1)</strong>&nbsp;Изучение наиболее востребованных формул и функций Excel для построения бюджетов.&nbsp;</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>2)</strong>&nbsp;Практические задания в Excel и 1С "Бухгалтерия".</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 49%; height: 15px;" colspan="2">\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><b style="color: #a22521;">МОДУЛЬ&nbsp;2. ПРАВО, НАЛОГИ, БУХ.ОТЧЕТНОСТЬ, МСФО, АУДИТ</b> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.0299%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>1. Новшества в бухгалтерском и налоговом законодательстве</strong> </span></p>\r\n</td>\r\n<td style="width: 36.9701%; height: 15px;">\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;"><strong>1)</strong>&nbsp;Новое в законодательстве о бухгалтерском учете, сложности и требования к бухгалтерской отчетности,&nbsp;профстандарт бухгалтера<br /></span><span style="font-size: 10pt;"><strong>2)</strong>&nbsp;Новое в налоговом законодательстве на 2018 год<br /></span><span style="font-size: 10pt;"><strong>3)</strong>&nbsp;Учетная политика в целях бухгалтерского и налогового учета<br /></span><span style="font-size: 10pt;"><strong>4)</strong>&nbsp;Налоговые проверки налогоплательщиков, прогнозы и критерии для проверки</span></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 12.0299%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 36.9701%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.0299%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>2. Налог на добавленную стоимость</strong> </span></p>\r\n</td>\r\n<td style="width: 36.9701%; height: 15px;">\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;"><strong>1)</strong>&nbsp;Сложности вопросы, льготы и оптимизация Налога на добавленную стоимость,<br /></span><span style="font-size: 10pt;"><strong>2)</strong>&nbsp;Выгодные и невыгодные поправки&nbsp; по НДС &nbsp;<br /></span><span style="font-size: 10pt;"><strong>3)</strong>&nbsp;Порядок начисления НДС при выполнении работ, условия принятия импортного НДС к вычету, раздельный учет НДС, &nbsp;НДС и утрата имущества<br /></span><span style="font-size: 10pt;"><strong>4)</strong>&nbsp;Арбитражная практика по НДС от Верховного суда РФ</span></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 12.0299%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 36.9701%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.0299%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>3. Налог на прибыль организаций</strong></span></p>\r\n</td>\r\n<td style="width: 36.9701%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1)&nbsp;Обоснованность расходов. Налоговая выгода. Методы и сложные вопросы.</span><br /><span style="font-family: Pro; font-size: 10pt;">2) Налоговые проверки. Критерии и сложные ситуации</span><br /><span style="font-family: Pro; font-size: 10pt;">3)&nbsp;Налоговые риски при работе с взаимозависимым лицам</span><br /><span style="font-family: Pro; font-size: 10pt;">4)&nbsp;Льготы по налогу на прибыль, легальная оптимизация</span><br /><span style="font-family: Pro; font-size: 10pt;">5)&nbsp;Внереализационные доходы и расходы. Безвозмездно полученное имущество, списание кредиторской&nbsp; задолженности, излишки и недостачи ТМЦ</span><br /><span style="font-family: Pro; font-size: 10pt;">6)&nbsp;Объекты основных средств, спорные и актуальные вопросы учета</span><br /><span style="font-family: Pro; font-size: 10pt;">7)&nbsp;Сложные вопросы и Арбитражная практика по налогу на прибыль от Верховного суда РФ</span><br /><span style="font-family: Pro; font-size: 10pt;">- &nbsp;Сложные&nbsp;и спорные вопросы налогового учета</span><br /><span style="font-family: Pro; font-size: 10pt;">- &nbsp;Заполнение налоговых деклараций</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 12.0299%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 36.9701%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.0299%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>4. Налог на имущество организаций</strong></span></p>\r\n</td>\r\n<td style="width: 36.9701%; height: 15px;">\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;"><strong>1)</strong>&nbsp;Новое в налогообложении по налогу на имущество организаций<br /></span><span style="font-size: 10pt;"><strong>2)</strong>&nbsp;Спорные вопросы налогообложения по налогу на имущество<br /></span><span style="font-size: 10pt;"><strong>3)</strong>&nbsp;Порядок уплаты налога, исчисляемого исходя из кадастровой стоимости<br /></span><span style="font-size: 10pt;"><strong>4)</strong>&nbsp;Разъяснения Минфина РФ, ФНС РФ по налогу на имущество<br /></span><span style="font-size: 10pt;"><strong>5)</strong>&nbsp;Сложные вопросы и Арбитражная практика по налогу на имущество от Верховного суда РФ&nbsp;</span></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 12.0299%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 36.9701%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.0299%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>5.Налог на доходы физических лиц</strong> </span></p>\r\n</td>\r\n<td style="width: 36.9701%; height: 15px;">\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;"><strong>1)</strong>&nbsp;Новое в налогообложении по&nbsp;НДФЛ<br /></span><span style="font-size: 10pt;"><strong>2)</strong>&nbsp;Льготы по налогообложению&nbsp;<br /></span><span style="font-size: 10pt;"><strong>3)</strong>&nbsp;Спорные вопросы налогообложения,&nbsp;уплаты налога<br /></span><span style="font-size: 10pt;"><strong>4)</strong>&nbsp;Разъяснения Минфина РФ, ФНС РФ по налогу&nbsp;<br /></span><span style="font-size: 10pt;"><strong>5)</strong>&nbsp;Арбитражная практика по налогу от Верховного суда РФ&nbsp;<br /></span><span style="font-size: 10pt;"><strong>6)</strong>&nbsp;Стандартные, социальные и имущественные вычеты</span></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 12.0299%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 36.9701%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.0299%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>6.Транспортный налог, Акциз, НДПИ, Водный налог<br />7.Страховые взносы<br /></strong></span></p>\r\n</td>\r\n<td style="width: 36.9701%; height: 15px;">\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;"><strong>1)</strong>&nbsp;Изменения, льготы, легальные схемы оптимизации, типичные ошибки по налогам&nbsp;<br /></span><span style="font-size: 10pt;"><strong>2)&nbsp;</strong>Оптимизация и льготы по страховым взносам.&nbsp;Спорные вопросы<br /></span><span style="font-size: 10pt;"><strong>3)&nbsp;</strong>Страховые взносы с индивидуальных предпринимателей</span></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 12.0299%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 36.9701%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.0299%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>8.Налоговое планирование</strong> </span></p>\r\n</td>\r\n<td style="width: 36.9701%; height: 15px;">\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;"><strong>1)</strong>&nbsp;Налоговое планирование как часть бизнеса. Задачи, цели, этапы налогового планирования. &nbsp;Налоговая схема и налоговая выгода<br /></span><span style="font-size: 10pt;"><strong>2)</strong>&nbsp;Расходы, связанные с реализацией товаров, работ, услуг. Транспортные расходы. Внереализационные расходы. Аренда. Рекламные расходы. Цена договора. Взаимозависимость<br /></span><span style="font-size: 10pt;"><strong>3)</strong>&nbsp;Оптимизация на специальных налоговых режимах. Разделение расходов, НДС при совмещение со спецрежимом. Плюсы и минусы индивидуальных предпринимателей</span></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 12.0299%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 36.9701%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.0299%; height: 15px;"><span style="font-size: 10pt; font-family: Pro;"><b>9. Анализ финансовой отчётности&nbsp;</b></span></td>\r\n<td style="width: 36.9701%; height: 15px;">\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;"><strong>1)</strong>&nbsp;Анализ бухгалтерского баланса&nbsp;<br /></span><span style="font-size: 10pt;"><strong>2)</strong>&nbsp;Анализ доходов, расходов и финансовых результатов деятельности организации&nbsp;&nbsp;<br /></span><span style="font-size: 10pt;"><strong>3)</strong>&nbsp;Анализ изменения капитала и оценка финансовой устойчивости организации&nbsp;&nbsp;<br /></span><span style="font-size: 10pt;"><strong>4)</strong>&nbsp;Анализ движения денежных средств и оценка платежеспособности организации&nbsp;<br /></span><span style="font-size: 10pt;"><strong>5)</strong>&nbsp;Анализ консолидированной финансовой отчётности&nbsp;&nbsp;</span><span style="font-size: 10pt;"><br /></span><span style="font-size: 10pt;"><strong>6)</strong>&nbsp;Состав пояснений и дополнений к отчётности&nbsp;&nbsp;</span></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 12.0299%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 36.9701%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.0299%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>10. МСФО, Международные стандарты финансовой отчетности</strong> </span></p>\r\n</td>\r\n<td style="width: 36.9701%; height: 15px;">\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;"><strong>1)</strong>&nbsp;Основные принципы учета и составления финансовой отчетности предприятий по МСФО.<br /></span><span style="font-size: 10pt;"><strong>2)</strong>&nbsp;Новшества&nbsp;&nbsp;в МСФО&nbsp;<br /></span><span style="font-size: 10pt;"><strong>3)</strong>&nbsp;Учет выручки.&nbsp;Учет отдельных видов активов, обязательств и капитала<br /></span><span style="font-size: 10pt;"><strong>4)</strong>&nbsp;Составление отчета о финансовом положении, отчета о совокупном доходе, отчета о движении денежных средств.&nbsp;<br /></span><span style="font-size: 10pt;"><strong>5)</strong>&nbsp;Трансформация финансовой отчетности.</span></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 12.0299%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 36.9701%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 19.9375px; background-color: #f5f5f5;">\r\n<td style="width: 12.0299%; height: 19.9375px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>11. АУДИТ И ГРАЖДАНСКОЕ ПРАВО<span style="box-sizing: inherit; margin: 0px; padding: 0px;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-weight: bold;"></span></span> </strong> </span></p>\r\n</td>\r\n<td style="width: 36.9701%; height: 19.9375px;">\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;"><strong>1)</strong>&nbsp;Критерии проведения аудиторских проверок<br /></span><span style="font-size: 10pt;"><strong>2)</strong>&nbsp;Методология проверок,&nbsp;аудиторское заключение<br /></span><span style="font-size: 10pt;"><strong>3)</strong>&nbsp;Основы составления &nbsp;договоров, обязательные условия</span></span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 16px;">\r\n<td style="width: 94%; height: 16px;" colspan="2">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt; color: #a22521;">МОДУЛЬ 3. &nbsp;ТРУДОВОЕ ПРАВО И КАДРОВОЕ ДЕЛОПРОИЗВОДСТВО</span> </strong> </span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n</td>\r\n</tr>\r\n<tr style="background-color: #f5f5f5; height: 311px;">\r\n<td style="width: 23%; height: 311px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">1.&nbsp;Прием на работу (установление трудовых правоотношений)</span></strong> </span></p>\r\n</td>\r\n<td style="width: 71%; height: 311px;">\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;"><strong>1)&nbsp;</strong>Поэтапная процедура оформления приема сотрудника на работу. Типичные ошибки при трудоустройстве.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;"><strong>2)</strong>&nbsp;Штатное расписание и штатная расстановка,&nbsp; назначение, отличия, корректность заполнения?</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;"><strong>3)&nbsp;</strong>Трудовой договор - содержание, порядок и сроки заключения.&nbsp; Перечень документов, предъявляемые работником в целях заключения трудового договора. Совместители. Испытательный срок.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;"><strong>4)&nbsp;</strong>Гражданско-правовой договор. Отличие от трудового договора и документальное обеспечение.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;"><strong>5)</strong>&nbsp;Особенности оформления договоров о материальной ответственности работников. Обязательность&nbsp; их заключения.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;"><strong>6)&nbsp;</strong>Срочные и бессрочные договора. Сроки трудовых договоров. Ограничения заключения «срочных» договоров. Особенности срока трудовых отношений с совместителями. Особенности оформления трудовых договоров с руководителями.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;"><strong>7)</strong>&nbsp;Документооборот приема. Особенности оформления документов с генеральными директорами нескольких компаний. Особенности оформления на работу иностранцев, инвалидов, несовершеннолетних. Кому нельзя отказать в приеме на работу.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-size: 10pt; font-family: Pro;"><em>- Практические задания: оформление на работу, разработка трудового договора.</em></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 23%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 71%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="background-color: #f5f5f5; height: 143px;">\r\n<td style="width: 23%; height: 143px;">\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>2.&nbsp;Функции кадровой службы организации. Ключевые нормативные правовые акты (положения), регулирующие трудовые правоотношения</strong></span></p>\r\n</td>\r\n<td style="width: 71%; height: 143px;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong>&nbsp;Правила внутреннего трудового распорядка, как основной регламент.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong>&nbsp;Положение об охране труда и технике безопасности.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>3)</strong>&nbsp;Положение о работе с персональными данными.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>4)</strong>&nbsp;Должностные инструкции работников -&nbsp; разработка корректных инструкций.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><em>- Практические задания по разработке должностных инструкций, правил и положений.</em></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 23%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 71%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="background-color: #f5f5f5; height: 89px;">\r\n<td style="width: 23%; height: 89px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">3.&nbsp;Изменение трудового договора</span></strong> </span></p>\r\n</td>\r\n<td style="width: 71%; height: 89px;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong>&nbsp;Перевод и перемещение: в чем отличие перевода от перемещения.&nbsp;</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong>&nbsp;Схематичное документирование переводов.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>3)</strong>&nbsp;Предназначение: докладных записок, служебных записок, заявлений, дополнительного соглашения, приказов.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 23%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 71%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 23%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">4.&nbsp;Правовое регулирование рабочего времени, режима рабочего времени. Отпуска</span></strong> </span></p>\r\n</td>\r\n<td style="width: 71%; height: 15px;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong>&nbsp;Рабочее время и время отдыха (нормальная и сокращенная продолжительность рабочего времени, неполное рабочее время; сверхурочная работа; ненормированный рабочий день; суммированный учет рабочего времени).</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong>&nbsp;Табель учета и график рабочего времени,&nbsp; в чем разница?&nbsp;</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>3)</strong>&nbsp;Отпуска. Виды, оформление графика, приказов, заявлений, отзывов из отпуска. Льготные категории по времени предоставления отпуска. Особенности оформления отпусков льготным категориям работников. Спорные вопросы предоставления отпуска новым сотрудникам. Больничный во время отпуска. Перенос отпуска. Какие части и каких отпусков можно получить деньгами. Особенности расчета отпускных у работников, которые часто берут «отпуск за свой счет». Учебные отпуска.&nbsp;</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro;"></span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>4)</strong>&nbsp;Служебная командировка:&nbsp;</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">- Порядок направления в служебную командировку - докладная записка, служебное задание и отчет о служебном задании; - приказ о направлении в командировку; - командировочное удостоверение; - ведение журналов учета.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">- Какие возмещаются расходы работнику; подтверждающие документы; сроки предоставления документов и отчетность.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">- Положение о служебных командировках и служебных поездках.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 23%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 71%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 23%; height: 15px;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>5.&nbsp;Система нормирования – технология управления производительностью труда</strong></span></p>\r\n</td>\r\n<td style="width: 71%; height: 15px;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong>&nbsp;Структура системы нормирования на предприятии. Документы, регламентирующие процесс нормирования.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong>&nbsp;Классификация норм труда. Нормативы затрат труда и методы нормирования. Нормируемая величина денежных средств, направляемых на оплату труда.&nbsp;</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>3)</strong>&nbsp;Фотография рабочего дня и хронометраж – основные инструменты каждого руководителя.&nbsp;</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>4)</strong>&nbsp;Потери рабочего времени. По организационно-техническим причинам, связанные с нарушением трудовой дисциплины.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>5)</strong>&nbsp;Особенности ненормированного труда:</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">- ненормированный рабочий день; цель установления и основание для использования;&nbsp;порядок компенсации;&nbsp;ненормированный рабочий день и сверхурочная работа.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>6)</strong>&nbsp;Заработная плата при сменном режиме труда. Особенности суммированного учета:</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">- особенность повременной оплаты при сменном режиме труда;</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">- заработная плата за согласованную продолжительность работы в смене и ее превышение над федеральной нормой рабочего времени;</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">- вахта; продолжительность вахты; междусменный и междувахтовый отдых.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 23%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 71%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 23%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">6. Правовое поле системы вознаграждений в организации</span></strong> </span></p>\r\n</td>\r\n<td style="width: 71%; height: 15px;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong>&nbsp;Постоянная и переменная часть. Взаимосвязь штатного расписания, норм труда и должностных обязанностей. Принципы и ограничения при необходимости изменений.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong>&nbsp;Условия оплаты труда, включаемые в трудовой договор. Положение об оплате труда, премировании.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>3)</strong>&nbsp;Поощрение работников. Дисциплинарные взыскания:</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">- поощрение работников - основание;</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">- поэтапная инструкция и документирование поощрения (формы представления, приказа);</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">- дисциплинарные взыскания - виды в соответствии с действующим законодательством;</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;">- вопросы законности наложения штрафа на работников.&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 23%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 71%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 23%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">7. Ответственность работодателя (кадровика, руководителя отдела персонала, бухгалтера, генерального директора) и трудовые споры</span></strong> </span></p>\r\n</td>\r\n<td style="width: 71%; height: 15px;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>1)&nbsp;</strong>Дисциплинарная ответственность. Особенности оформления дисциплинарных взысканий. Документы, наделяющие полномочиями расследовать факты нарушения дисциплины.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong>&nbsp;Материальная ответственность. Судебная практика взыскания ущерба в полном объеме. Взыскание затрат на дорогостоящее обучение.&nbsp;</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>3)</strong>&nbsp;Административная и уголовная ответственность. Проверки Государственной инспекции труда. Минимизация рисков обращения работников в надзорно-контрольные органы.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>4)</strong>&nbsp;Предупреждение конфликтов, приводящих к обращениям граждан в надзорно-контрольные органы. Этика поведения специалистов HR при спорных и конфликтных ситуациях.&nbsp;</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><em>- Обзор судебной практики по вопросам расторжения трудовых договоров по инициативе работодателя.</em></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 23%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 71%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 23%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">8. Прекращение трудовых правоотношений, документирование. Сокращение</span></strong> </span></p>\r\n</td>\r\n<td style="width: 71%; height: 15px;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong>&nbsp;Прекращение трудового договора по - инициативе работника; - инициативе работодателя; - по соглашению сторон; - обстоятельствам, не зависящим от воли сторон.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong>&nbsp;Процедура&nbsp; увольнения в зависимости от оснований прекращения трудового договора.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>3)</strong>&nbsp;Сокращение численности и сокращение штата:&nbsp; - процедура уведомления работников о сокращении; - процедуры предложения вакансий; - гарантии работника при увольнении по сокращению численности или штата работников.&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 23%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 71%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 23%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">9.&nbsp;Трудовая книжка,&nbsp; организация кадрового делопроизводства</span></strong> </span></p>\r\n</td>\r\n<td style="width: 71%; height: 15px;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong>&nbsp;Трудовая книжка работника: учет, ведение, хранение.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong>&nbsp;Личная карточка работника: - обязательность заполнения&nbsp;&nbsp; - внесение записей в период работы и при увольнении - порядок учета и хранения.</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>3)</strong>&nbsp;Личное дело работника.</span></p>\r\n<p style="font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><em>- Практические задания заполнение трудовой книжки и личного дела.</em></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 23%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n<td style="width: 71%; height: 15px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 23%; height: 15px;">\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">10. Текущее и архивное хранение кадровой документации</span></strong> </span></p>\r\n</td>\r\n<td style="width: 71%; height: 15px;">\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>1)</strong>&nbsp;Требования к формированию дел в делопроизводстве организации и подготовка передачи дел в ведомственный архив.&nbsp;</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>2)</strong>&nbsp;Особенности сроков хранения дел по личному составу организаций.&nbsp;</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>3)</strong>&nbsp;Требования к заполнению формы номенклатуры дел.&nbsp;</span></p>\r\n<p style="text-align: justify;"><span style="font-family: Pro; font-size: 10pt;"><strong>4)</strong>&nbsp;Порядок составления и утверждения номенклатуры дел организации.&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr style="background-color: #ffffff;">\r\n<td style="width: 23%; height: 15px;">&nbsp;</td>\r\n<td style="width: 71%; height: 15px;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 23%; height: 15px;" colspan="2">\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong style="color: #a22521;">МОДУЛЬ 4.&nbsp;УПРАВЛЕНЧЕСКИЕ КОМПЕТЕНЦИИ</strong> </span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15.5938px; background-color: #f5f5f5;">\r\n<td style="width: 23%; height: 15.5938px;"><span style="font-size: 10pt; font-family: Pro;">&nbsp;<strong>Управленческие компетенции, организационный менеджмент</strong></span></td>\r\n<td style="width: 71%; height: 15.5938px;"><span style="font-family: Pro;"></span>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>1)</strong>&nbsp;Личная эффективность. Целеполагание в «SMART» - формате. Методы планирования. Инструменты тайм-менеджмента. Инвентаризация рабочего времени.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>2)</strong>&nbsp;Лидерство и команда. Групповая динамика и&nbsp;сплочение коллектива.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>3)</strong>&nbsp;Делегирование полномочий. Цели и барьеры делегирования. Алгоритм делегирования. Правила предоставления обратной связи.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>4)</strong>&nbsp;Конфликтология. Управление организационным конфликтом. Виды, причины, стадии развития конфликта. Стили поведения в конфликте. Этапы разрешения и способы урегулирования конфликта. Методы профилактики конфликтов.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>5)</strong>&nbsp;Стресс-менеджмент. Причины и симптомы стрессового напряжения. Способы сохранения и восстановления эмоционального равновесия и работоспособности. Антистресс - профилактика. Организационный стресс и результативность команды.</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><strong><span style="font-family: Pro; font-size: 12pt;">Формат курсов на главного бухгалтера</span></strong></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p><span style="font-family: Pro;">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;•&nbsp;<strong>Очное обучение.</strong> Продолжительность - 4-5 месяцев по<span style="color: inherit; font-size: 13.3333px;">&nbsp;понедельникам, средам с 18:30 до 21:30 и в субботу с 09.00 до 13.45. &nbsp;Дни недели могут изменяться.&nbsp;</span></span></p>\r\n<p><span style="font-family: Pro;">&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;•&nbsp;<strong>Дистанционное обучение:</strong> видео-лекции, аттестационные работы</span></p>\r\n<hr />\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 12pt;">Акции и скидки:</span></strong> </span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit; color: inherit; font-size: 1rem;">•&nbsp;</span>Скидка 10%&nbsp;при оплате за 4 недели до обучения.&nbsp;&nbsp;</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit; color: inherit; font-size: 1rem;">•&nbsp;</span>Скидка 5%&nbsp;при оплате за 2 недели до обучения.</span></p>\r\n<p>&nbsp;</p>\r\n<p style="text-align: center;"><span style="font-family: Pro;"><a onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<hr />\r\n<p style="text-align: left;"><span style="color: #333333; font-family: Pro;"><span style="font-size: 16px;"><b>О нас</b></span></span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro;"><iframe style="background-image: url(''img/iframe.png''); display: block; margin-left: auto; margin-right: auto;" src="https://www.youtube.com/embed/yx3VnN5bh2k" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture"></iframe></span></p>', '', 1, 11, '2016-12-12 07:27:29', 42, '', '2019-04-30 05:26:15', 42, 0, '0000-00-00 00:00:00', '2016-12-12 07:27:29', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 80, 20, 'Курсы главного бухгалтера, обучение главных бухгалтеров, курсы главного бухгалтера', 'Курсы главного бухгалтера в Екатеринбурге. Очно и дистанционно. Обучение от экспертов-практиков. Переподготовка. Скидки до 15% – Звоните', 1, 7985, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(144, 242, 'программа повышения квалификации Главный бухгалтер  (2)', 'главный-бухгалтер-программа-повышения-квалификации-2', '<h1 style="box-sizing: inherit; margin: 20px 0px; padding: 0px; font-size: 15px; text-align: center; font-family: verdana; color: #1d4e77; background-color: #fefefe;">Программа повышения квалификации&nbsp;Главный бухгалтер</h1>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>Целевая аудитория:</strong></span>&nbsp;бухгалтер, зам. гл. бухгалтера, &nbsp;главный бухгалтер, экономист, финансовый директор</p>\r\n<p><a href="http://xn--d1ababe6aaeff9c5g.xn--p1ai/2-uncategorised/53-biznes-trener-nasonova-nadezhda-yurevna">Насонова Надежда Юрьевна&nbsp;</a>- финансовый директор, практикующий главный бухгалтер.<br /><a href="http://xn--d1ababe6aaeff9c5g.xn--p1ai/2-uncategorised/105-%D1%81%D1%83%D0%B1%D0%B1%D0%BE%D1%82%D0%B8%D0%BD%D0%B0-%D1%8E%D0%BB%D0%B8%D1%8F-%D0%BE%D0%BB%D0%B5%D0%B3%D0%BE%D0%B2%D0%BD%D0%B0">Поплавская Юлия Олеговна</a>&nbsp;-&nbsp; практикующий главный бухгалтер, финансовый директор<br />Сокол Маргарита Геннадьевна - главный государственный налоговый инспектор<br />Прокопьева Зоя Александровна - главный государственный налоговый инспектор<br /><a href="http://xn--d1ababe6aaeff9c5g.xn--p1ai/2-uncategorised/71-trener-putilova-marina">Путилова Марина Владимировна</a>&nbsp;- тренер, руководитель службы Управления персоналом&nbsp;<br /><a href="http://xn--d1ababe6aaeff9c5g.xn--p1ai/obrazovanie/kursy-obucheniya-po-personalu/2-uncategorised/52-biznes-trener-khabirova-tatyana" rel="alternate">Хабирова Татьяна Валерьевна</a>&nbsp;-&nbsp;тренер по стратегическому развитию и управленческим компетенциям</p>\r\n<p><strong><span style="font-family: arial, helvetica, sans-serif;">Модули обучения:</span></strong></p>\r\n<p>1. Финансовый менеджмент, анализ, бюджетирование. Инвестиции.<br />2. Налоги, бух. отчетность, МСФО, аудит.<br />3.&nbsp;Трудовое право, трудовые правоотношения<br />4. Управление персоналом, управленческие компетенции</p>\r\n<p style="font-size: 12.16px;"><br /><b style="color: #333333; font-family: arial, helvetica, sans-serif; font-size: 13.3333px; text-align: start; background-color: #ffffff;"><span style="color: #000000;">МОДУЛЬ 1. &nbsp;НАЛОГИ, БУХГАЛТЕРСКАЯ ОТЧЕТНОСТЬ, МСФО, АУДИТ</span> &nbsp;</b></p>\r\n<p style="box-sizing: inherit; margin: 0px 0px 10px; padding: 0px; text-align: justify; color: #351e07; font-family: Pro; font-size: 14px; background-color: #fefefe;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-family: arial, helvetica, sans-serif;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-weight: bold;">Новшества в бухгалтерском и налоговом законодательстве</span></span></p>\r\n<ul>\r\n<li>Новое в законодательстве о бухгалтерском учете, сложности и требования к бухгалтерской отчетности,&nbsp;профстандарт бухгалтера</li>\r\n<li>Новое в налоговом законодательстве на 2016 год, планы нововведений на 2017 год</li>\r\n<li>Учетная политика в целях бухгалтерского и налогового учета</li>\r\n<li>Налоговые проверки налогоплательщиков, прогнозы и критерии для проверки</li>\r\n</ul>\r\n<p style="box-sizing: inherit; margin: 0px 0px 10px; padding: 0px; text-align: justify; color: #351e07; font-family: Pro; font-size: 14px; background-color: #fefefe;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-family: arial, helvetica, sans-serif;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-weight: bold;">Налог на добавленную стоимость</span></span></p>\r\n<ul dir="ltr">\r\n<li>Сложности вопросы, льготы и оптимизация Налога на добавленную стоимость,</li>\r\n<li>Выгодные и невыгодные поправки&nbsp; по НДС &nbsp;</li>\r\n<li>Порядок начисления НДС при выполнении работ, условия принятия импортного НДС к вычету, раздельный учет НДС, &nbsp;НДС и утрата имущества</li>\r\n<li>Арбитражная практика по НДС от Верховного суда РФ</li>\r\n</ul>\r\n<p style="box-sizing: inherit; margin: 0px 0px 10px; padding: 0px; text-align: justify; color: #351e07; font-family: Pro; font-size: 14px; background-color: #fefefe;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-family: arial, helvetica, sans-serif;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-weight: bold;">Налог на прибыль организаций</span></span></p>\r\n<ul dir="ltr">\r\n<li>Особенности налогообложения в связи с вступлением в силу новых налоговых актов а 2016 году</li>\r\n<li>Способы сближения&nbsp; бухгалтерского&nbsp; и налогового учета в 2016 году</li>\r\n<li>Налоговые риски при работе с взаимозависимым лицам</li>\r\n<li>Льготы по налогу на прибыль, легальная оптимизация</li>\r\n<li>Методы признания расходов,&nbsp;признание обоснованности расходов&nbsp;</li>\r\n<li>Объекты основных средств, спорные и актуальные вопросы учета</li>\r\n<li>Сложные вопросы и Арбитражная практика по налогу на прибыль от Верховного суда РФ</li>\r\n</ul>\r\n<p style="box-sizing: inherit; margin: 0px 0px 10px; padding: 0px; text-align: justify; color: #351e07; font-family: Pro; font-size: 14px; background-color: #fefefe;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-family: arial, helvetica, sans-serif;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-weight: bold;">Налог на имущество организаций</span></span></p>\r\n<ul dir="ltr">\r\n<li>Новое в налогообложении по налогу на имущество организаций</li>\r\n<li>Льготы по налогообложению по движимым основным средствам</li>\r\n<li>Спорные вопросы налогообложения по налогу на имущество</li>\r\n<li>Порядок уплаты налога, исчисляемого исходя из кадастровой стоимости</li>\r\n<li>Разъяснения Минфина РФ, ФНС РФ по налогу на имущество</li>\r\n<li>Сложные вопросы и Арбитражная практика по налогу на имущество от Верховного суда РФ&nbsp;</li>\r\n</ul>\r\n<p style="box-sizing: inherit; margin: 0px 0px 10px; padding: 0px; text-align: justify; color: #351e07; font-family: Pro; font-size: 14px; background-color: #fefefe;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-family: arial, helvetica, sans-serif;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-weight: bold;">Налог на доходы физических лиц</span></span></p>\r\n<ul>\r\n<li>Новое в налогообложении по&nbsp;НДФЛ</li>\r\n<li>Льготы по налогообложению&nbsp;</li>\r\n<li>Спорные вопросы налогообложения,&nbsp;уплаты налога</li>\r\n<li>Разъяснения Минфина РФ, ФНС РФ по налогу&nbsp;</li>\r\n<li>Арбитражная практика по налогу от Верховного суда РФ&nbsp;</li>\r\n<li>Стандартные, социальные и имущественные вычеты</li>\r\n</ul>\r\n<p dir="ltr" style="box-sizing: inherit; margin: 0px 0px 10px; padding: 0px; text-align: justify; color: #351e07; font-family: Pro; font-size: 14px; background-color: #fefefe;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-family: arial, helvetica, sans-serif;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-weight: bold;">Налоговое планирование</span></span></p>\r\n<ul>\r\n<li>Налоговое планирование как часть бизнеса. Задачи, цели, этапы налогового планирования. &nbsp;Налоговая схема и налоговая выгода выгода</li>\r\n<li>Расходы, связанные с реализацией товаров, работ, услуг. Транспортные расходы. Внереализационные расходы. Аренда. Рекламные расходы. &nbsp;Цена договора. Скидки. Взаимозависимость</li>\r\n<li>Оптимизация на специальных налоговых режимах. Разделение расходов, НДС при совмещение спецрежимов. Плюсы и минусы индивидуальных предпринимателей</li>\r\n<li>Эффективная защита налогоплательщика. Ошибки проверяющих. Как вести себя во время проверки. Когда стоит писать возражения на акт. Как правильно обжаловать решение налогового органа. Цель налогового спора. Тактика и стратегия защиты. Психология налогового спора</li>\r\n</ul>\r\n<p style="box-sizing: inherit; margin: 0px 0px 10px; padding: 0px; text-align: justify; color: #351e07; font-family: Pro; font-size: 14px; background-color: #fefefe;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-family: arial, helvetica, sans-serif;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-weight: bold;">Транспортный налог, Акциз, НДПИ, Водный налог</span></span></p>\r\n<ul style="box-sizing: inherit; margin: 20px 0px 20px 40px; padding: 0px; color: #0a0a0a; font-family: Pro; font-size: 14px; background-color: #fefefe;">\r\n<li style="box-sizing: inherit; margin: 10px 0px; padding: 0px; text-align: justify;">Изменения, льготы, легальные схемы оптимизации, типичные ошибки</li>\r\n</ul>\r\n<p style="box-sizing: inherit; margin: 0px 0px 10px; padding: 0px; text-align: justify; color: #351e07; font-family: Pro; font-size: 14px; background-color: #fefefe;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-family: arial, helvetica, sans-serif;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-weight: bold;">Страховые взносы</span></span></p>\r\n<ul>\r\n<li>Оптимизация и льготы по страховым взносам</li>\r\n<li>Страховые взносы с индивидуальных предпринимателей</li>\r\n<li>Критерии и плановые проверки внебюджетных фондов.&nbsp;</li>\r\n<li>Спорные вопросы</li>\r\n</ul>\r\n<p style="box-sizing: inherit; margin: 0px 0px 10px; padding: 0px; text-align: justify; color: #351e07; font-family: Pro; font-size: 14px; background-color: #fefefe;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-family: arial, helvetica, sans-serif;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-weight: bold;">МСФО, Международные стандарты финансовой отчетности</span></span></p>\r\n<ul>\r\n<li>Основные принципы учета и составления финансовой отчетности предприятий по МСФО.</li>\r\n<li>Новшества&nbsp;&nbsp;в МСФО&nbsp;</li>\r\n<li>Учет выручки.&nbsp;Учет отдельных видов активов, обязательств и капитала</li>\r\n<li>Составление отчета о финансовом положении, отчета о совокупном доходе, отчета о движении денежных средств.&nbsp;</li>\r\n<li>Трансформация финансовой отчетности.</li>\r\n</ul>\r\n<p style="box-sizing: inherit; margin: 0px 0px 10px; padding: 0px; text-align: justify; color: #351e07; font-family: Pro; font-size: 14px; background-color: #fefefe;"><span style="font-family: arial, helvetica, sans-serif;"><strong>АУДИТ И ГРАЖДАНСКОЕ ПРАВО</strong></span><span style="box-sizing: inherit; margin: 0px; padding: 0px;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-weight: bold;">&nbsp;</span></span></p>\r\n<ul>\r\n<li>Критерии проведения аудиторских проверок</li>\r\n<li>Методология проверок,&nbsp;аудиторское заключение</li>\r\n<li>Основы составления гражданского договора, обязательные условия</li>\r\n</ul>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>МОДУЛЬ 2. ЭКОНОМИКА,</strong><span style="color: #351e07; font-weight: bold; line-height: 21px; text-align: justify; background-color: #fefefe;">&nbsp;БЮДЖЕТИРОВАНИЕ, ФИНАНСОВЫЙ АНАЛИЗ</span></span></p>\r\n<p style="font-size: 12.16px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>1. Экономика предприятия</strong></span></p>\r\n<ul style="font-size: 12.16px; line-height: 15.808px;">\r\n<li><span style="font-size: 10pt;">Точка безубыточности. Анализ безубыточности</span></li>\r\n<li><span style="font-size: 10pt;">&nbsp;Ключевой расчет маржинальной прибыли, чистой прибыли</span></li>\r\n<li><span style="font-size: 10pt;">&nbsp;Ключевые показатели эффективности предприятия,&nbsp; EBITDA, ROE</span></li>\r\n<li><span style="font-size: 10pt;">&nbsp;Анализ финансовых результатов деятельности</span></li>\r\n<li><span style="font-size: 10pt;">Анализ эффективности использования&nbsp; оборотных средств (оборачиваемость, материалоемкость). Нормирование.</span></li>\r\n<li><span style="font-size: 10pt;">Анализ &nbsp;эффективности использования трудовых ресурсов (выработка, трудоемкость)</span></li>\r\n</ul>\r\n<p style="font-size: 12.16px;"><span style="font-size: 10pt;">&nbsp;&nbsp;<span style="font-family: arial,helvetica,sans-serif;">-&nbsp;Практические задания точки безубыточности и валовой маржи. Определение наиболее рентабельных проектов, видов деятельности, продукции</span></span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>2. Организация аналитического учета затрат</strong></span></p>\r\n<ul style="font-size: 12.16px; line-height: 15.808px;">\r\n<li style="text-align: justify;"><span style="font-size: 10pt;">Бухгалтерский план счетов, с использованием которых осуществляется учет затрат на производство. Группировка балансовых статей, баланс предприятия,&nbsp; строение балансовых счетов.</span></li>\r\n<li style="margin-top: 0cm; margin-right: 0cm; margin-bottom: 0.0001pt; text-indent: 0cm; text-align: justify;"><span style="font-size: 10pt;">Затраты по статьям калькуляции. Учет отдельных видов затрат. Система " Директ - костинг"</span></li>\r\n<li style="margin-top: 0cm; margin-right: 0cm; margin-bottom: 0.0001pt; text-indent: 0cm; text-align: justify;"><span style="font-size: 10pt;">Специфика и области применения различных методов учета производственных затрат: позаказного, котлового, попередельного.</span></li>\r\n<li style="margin-top: 0cm; margin-right: 0cm; margin-bottom: 0.0001pt; text-align: justify;"><span style="font-size: 10pt;">Классификация расходов и затрат,&nbsp; формирующих себестоимость продукции,&nbsp; их отличия</span></li>\r\n</ul>\r\n<p style="font-size: 12.16px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">-&nbsp;Практические задания по расчету себестоимости и цены. Оптимизация затрат.</span></p>\r\n<p style="font-size: 12.16px;"><span style="font-family: arial, helvetica, sans-serif;"><strong><span style="font-size: 10pt;">&nbsp;</span></strong></span><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>3. Финансовая отчетность. Основные методы финансового анализа<em><br /></em></strong></span></p>\r\n<ul style="font-size: 12.16px;">\r\n<li><span style="font-size: 10pt;">Финансовый анализ, как метод оценки текущего и перспективного финансового состояния предприятия: трендовый, факторный, метод цепных подстановок, горизонтальный, вертикальный</span></li>\r\n<li><span style="font-size: 10pt;">анализируем бухгалтерский баланс, в чем отличие от управленческого баланса</span></li>\r\n<li><span style="font-size: 10pt;">особенности составления отчета о прибылях и убытках, отличие от Бюджета доходов и расходов</span></li>\r\n<li><span style="font-size: 10pt;">Коэффициенты финансового анализа: платежеспособность и&nbsp;ликвидность, &nbsp;коэффициент инвестирования, коэффициенты финансовой устойчивости, деловой активности.</span></li>\r\n</ul>\r\n<p style="font-size: 12.16px;"><span style="font-size: 10pt;"><span style="font-family: arial, helvetica, sans-serif;">- Кейс по анализу финансовой отчетности</span></span></p>\r\n<p style="font-size: 12.16px;"><span style="font-size: 10pt;">4<span style="font-family: arial,helvetica,sans-serif;"><strong>.&nbsp; Управление инвестициями</strong></span></span></p>\r\n<ul style="font-size: 12.16px;">\r\n<li><span style="font-size: 10pt;">Основные показатели, используемые для расчетов эффективности инвестиционного проекта.</span></li>\r\n<li><span style="font-size: 10pt;">Чистый дисконтированный доход (NPV), индекс рентабельности инвестиций, внутренняя норма доходности</span></li>\r\n<li><span style="font-size: 10pt;">Срок окупаемости инвестиций. Резерв безопасности проекта</span></li>\r\n<li><span style="font-size: 10pt;">Управление заемным капиталом. Эффект финансового рычага.</span></li>\r\n<li><span style="font-size: 10pt;">Стоимость капитала: ее составляющие и методы оценки.</span></li>\r\n<li><span style="font-size: 10pt;">Ликвидность и способы ее оценки</span></li>\r\n</ul>\r\n<p style="font-size: 12.16px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">- Практические задания по расчету оценки инвестиционных проектов</span>&nbsp;<span style="font-size: 10pt;">&nbsp;</span></p>\r\n<p style="font-size: 12.16px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>5. Эффективная финансово &ndash; экономическая служба</strong></span></p>\r\n<ul style="font-size: 12.16px;">\r\n<li><span style="font-size: 10pt;">Требования к финансовой отчетности для руководителей.</span></li>\r\n<li class="MsoNormal" style="text-align: justify;"><span style="font-size: 10pt;">Принципы учетной политики управленческого учета.</span></li>\r\n<li class="MsoNormal" style="text-align: justify;"><span style="font-size: 10pt;">Чтение и интерпретации финансовых отчетов.&nbsp;</span></li>\r\n<li class="MsoNormal" style="text-align: justify;"><span style="font-size: 10pt;">Функции финансового управляющего.</span></li>\r\n<li class="MsoNormal" style="text-align: justify;"><span style="font-size: 10pt;">Распределение функций финансово-экономической службы.</span></li>\r\n<li class="MsoNormal" style="text-align: justify;"><span style="font-size: 10pt;">Показатели эффективности финансовой службы.</span></li>\r\n</ul>\r\n<p style="font-size: 12.16px;"><span style="font-size: 10pt;"><strong><span style="font-family: arial,helvetica,sans-serif;">6. Бизнес-план &ndash; первый план компании.</span></strong>&nbsp;Как получить желаемый результат и не потерять вложенные средства, при реализации нового инвестиционного проекта.</span></p>\r\n<ul style="font-size: 12.16px;">\r\n<li><span style="font-size: 10pt;">Описание продукции и предприятия</span></li>\r\n<li><span style="font-size: 10pt;">Анализ рынка и маркетинговая стратегия. Выбор сегмента рынка. Анализ конкурентных преимуществ.&nbsp;Прогнозы объемов продаж - план продаж.</span></li>\r\n<li><span style="font-size: 10pt;">Производственный план. Общий подход к организации производства</span></li>\r\n<li><span style="font-size: 10pt;">Финансовый план. Бюджетирование, как составная часть финансового планирования</span></li>\r\n<li><span style="font-size: 10pt;">Оценка рисков.</span></li>\r\n</ul>\r\n<p style="font-size: 12.16px;"><span style="font-size: 10pt;"><strong><span style="font-family: arial,helvetica,sans-serif;">7. Бюджетирование &ndash; как часть системы управления предприятием.</span></strong></span></p>\r\n<ul style="font-size: 12.16px; line-height: 15.808px;">\r\n<li><span style="font-size: 10pt;">Сущность бюджетного управления, бюджет в системе планов предприятия;</span></li>\r\n<li><span style="font-size: 10pt;">Постановка системы бюджетного управления:&nbsp; определение участников процесса бюджетного управления,&nbsp; определение центров финансовой ответственности, учета (ЦФО, ЦФУ);</span></li>\r\n<li><span style="font-size: 10pt;">Подходы к построению системы бюджетирования на предприятии;</span></li>\r\n<li><span style="font-size: 10pt;">Регламентация системы бюджетирования на предприятии. Бюджетная система:&nbsp; Система бюджетов на предприятии: Бюджет продаж, бюджет производства, бюджет накладных расходов, бюджет доходов и расходов, бюджет движения денежных средств.&nbsp; Взаимосвязь основных плановых и отчетных форм между собой. Контроль исполнения бюджетов &ndash; ключевая функция системы бюджетного управления.&nbsp; Анализ исполнения бюджета.</span></li>\r\n</ul>\r\n<p style="margin: 0cm 0cm 0.0001pt;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">&nbsp;-&nbsp;Практические задания по разработке бюджетов, контроль и анализ. Причины невыполнения бюджетов.</span></p>\r\n<p style="font-size: 12.16px;"><span style="font-family: arial, helvetica, sans-serif;"><strong>8. Практические примеры построения&nbsp; бюджетов в программе Excel &ndash; программа для управленческого учета и системы бюджетирования на предприятии.</strong></span></p>\r\n<ul>\r\n<li>Изучение&nbsp;наиболее востребованных&nbsp;формул и функций Excel&nbsp;для построения бюджетов.</li>\r\n<li style="margin-top: 0cm; margin-right: 0cm; margin-bottom: 0.0001pt;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Практические задания в&nbsp;Excel&nbsp;и 1 С &laquo;Бухгалтерия&raquo;.</span></li>\r\n</ul>\r\n<p><span style="font-family: arial, helvetica, sans-serif; color: #000000;"><strong>МОДУЛЬ 3. ТРУДОВОЕ ПРАВО</strong></span></p>\r\n<p style="font-size: 12.16px;"><span style="font-size: 10pt;"><strong>1. Установление трудовых правоотношений</strong></span></p>\r\n<ul>\r\n<li>Поэтапная процедура оформления приема сотрудника на работу. Типичные ошибки при трудоустройстве.</li>\r\n<li>Штатное расписание и штатная расстановка,&nbsp; назначение, отличия, корректность заполнения?</li>\r\n<li>Трудовой договор - содержание, порядок и сроки заключения.&nbsp; Перечень документов, предъявляемые работником в целях заключения трудового договора. Совместители. Испытательный срок</li>\r\n<li>Гражданско-правовой договор. Отличие от трудового договора и документальное обеспечение</li>\r\n<li>Особенности оформления договоров о материальной ответственности работников. Обязательность&nbsp; их заключения.</li>\r\n<li>Срочные и бессрочные договора. Сроки трудовых договоров. Ограничения заключения &laquo;срочных&raquo; договоров. Особенности срока трудовых отношений с совместителями. Особенности оформления трудовых договоров с руководителями</li>\r\n<li>Документооборот приема. Особенности оформления документов с генеральными директорами нескольких компаний. Особенности оформления на работу иностранцев, инвалидов, несовершеннолетних. Кому нельзя отказать в приеме на работу.</li>\r\n</ul>\r\n<p>- Практические задания: оформление на работу, разработка трудового договора</p>\r\n<p style="font-size: 12.16px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>2. Функции кадровой службы организации. Ключевые нормативные правовые акты (положения), регулирующие трудовые правоотношения</strong></span></p>\r\n<ul>\r\n<li>Правила внутреннего трудового распорядка, как основной регламент.</li>\r\n<li>Положение об охране труда и технике безопасности.</li>\r\n<li>Положение о работе с персональными данными</li>\r\n<li>Должностные инструкции работников -&nbsp; разработка корректных инструкций</li>\r\n</ul>\r\n<p>- Практические задания по разработке должностных инструкций, правил и положений</p>\r\n<p style="font-size: 12.16px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>3. Изменение трудового договора</strong></span></p>\r\n<ul style="font-size: 12.16px;">\r\n<li><span style="font-size: 10pt;">Перевод и перемещение: в чем отличие перевода от перемещения; -</span></li>\r\n<li><span style="font-size: 10pt;">Схематичное документирование переводов</span></li>\r\n<li><span style="font-size: 10pt;">Предназначение: докладных записок, служебных записок; заявлений; дополнительного соглашения; приказов).</span></li>\r\n</ul>\r\n<p style="font-size: 12.16px;"><span style="font-size: 10pt;"><strong><span style="font-family: arial,helvetica,sans-serif;">4. Правовое регулирование рабочего времени, режима рабочего времени. Отпуска</span></strong></span></p>\r\n<ul>\r\n<li>Рабочее время и время отдыха (нормальная и сокращенная продолжительность рабочего времени, неполное рабочее время; сверхурочная работа; ненормированный рабочий день; суммированный учет рабочего времени).</li>\r\n<li>Табель учета и график рабочего времени,&nbsp; в чем разница? .</li>\r\n<li>\r\n<p>Отпуска. Виды, оформление графика, приказов, заявлений, отзывов из отпуска. Льготные категории по времени предоставления отпуска. Особенности оформления отпусков льготным категориям работников. Спорные вопросы предоставления отпуска новым сотрудникам. Больничный во время отпуска. Перенос отпуска. Какие части и каких отпусков можно получить деньгами. Особенности расчета отпускных у работников, которые часто берут &laquo;отпуск за свой счет&raquo;. Учебные отпуска</p>\r\n<p><span style="font-size: 10pt;">- Практические задания по расчету графиков, отпусков и больничных</span>&nbsp;<span style="font-size: 10pt;">&nbsp; Служебная командировка</span></p>\r\n</li>\r\n</ul>\r\n<ul style="font-size: 12.16px;">\r\n<li><span style="font-size: 10pt;">Порядок направления в служебную командировку - докладная записка, служебное задание и отчет о служебном задании; - приказ о направлении в командировку; - командировочное удостоверение; - ведение журналов учета.</span></li>\r\n<li><span style="font-size: 10pt;">Какие возмещаются расходы работнику; подтверждающие документы; сроки предоставления документов и отчетность.</span></li>\r\n<li><span style="font-size: 10pt;">Положение о служебных командировках и служебных поездках.</span></li>\r\n</ul>\r\n<p class="MsoNormal" style="font-size: 12.16px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>&nbsp;5. Система нормирования &ndash; технология управления производительностью труда</strong></span></p>\r\n<ul style="font-size: 12.16px;">\r\n<li class="MsoNormal"><span style="font-size: 10pt;">Структура системы нормирования на предприятии. Документы, регламентирующие процесс нормирования</span></li>\r\n<li class="MsoNormal"><span style="font-size: 10pt;">Классификация норм труда. Нормативы затрат труда и методы нормирования. Нормируемая величина денежных средств, направляемых на оплату труда</span></li>\r\n<li class="MsoNormal"><span style="font-size: 10pt;">Фотография рабочего дня и хронометраж &ndash; основные инструменты каждого руководителя</span></li>\r\n<li class="MsoNormal"><span style="font-size: 10pt;">Потери рабочего времени. По организационно-техническим причинам, связанные с нарушением трудовой дисциплины</span></li>\r\n</ul>\r\n<p style="font-size: 12.16px;"><span style="font-size: 10pt;">&nbsp;Особенности ненормированного труда</span></p>\r\n<ul style="font-size: 12.16px;">\r\n<li class="MsoNormal"><span style="font-size: 10pt;">&nbsp;Ненормированный труд и его свойства</span></li>\r\n<li class="MsoNormal"><span style="font-size: 10pt;">&nbsp;Ненормированный рабочий день. Цель установления и основание для использования. Порядок компенсации. Ненормированный рабочий день и сверхурочная работа</span></li>\r\n</ul>\r\n<p style="font-size: 12.16px;"><span style="font-size: 10pt;">Заработная плата при сменном режиме труда. Особенности суммированного учета</span></p>\r\n<ul style="font-size: 12.16px;">\r\n<li class="MsoNormal"><span style="font-size: 10pt;">&nbsp;Особенность повременной оплаты при сменном режиме труда.</span></li>\r\n<li class="MsoNormal"><span style="font-size: 10pt;">&nbsp;Заработная плата за согласованную продолжительность работы в смене и ее превышение над федеральной нормой рабочего времени</span></li>\r\n<li class="MsoNormal"><span style="font-size: 10pt;">&nbsp;Вахта. Продолжительность вахты. Междусменный и междувахтовый отдых</span></li>\r\n</ul>\r\n<p style="font-size: 12.16px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>6. Правовое поле системы вознаграждений в организации</strong></span></p>\r\n<ul style="font-size: 12.16px;">\r\n<li class="MsoNormal"><span style="font-size: 10pt;">Постоянная и переменная часть. Взаимосвязь штатного расписания, норм труда и должностных обязанностей. Принципы и ограничения при необходимости изменений</span></li>\r\n<li class="MsoNormal"><span style="font-size: 10pt;">Условия оплаты труда, включаемые в трудовой договор. Положение об оплате труда, премировании</span></li>\r\n</ul>\r\n<p style="font-size: 12.16px;"><span style="font-size: 10pt;">Поощрение работников. Дисциплинарные взыскания</span></p>\r\n<ul style="font-size: 12.16px;">\r\n<li><span style="font-size: 10pt;">Поощрение работников - основание; - поэтапная инструкция и документирование поощрения (формы представления, приказа).</span></li>\r\n<li><span style="font-size: 10pt;">Дисциплинарные взыскания - виды в соответствии с действующим законодательством; - вопросы законности наложения штрафа на работников;</span></li>\r\n</ul>\r\n<p style="font-size: 12.16px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>7. Ответственность работодателя (кадровика, руководителя отдела персонала, бухгалтера, генерального директора) и трудовые споры</strong></span></p>\r\n<ul style="font-size: 12.16px;">\r\n<li><span style="font-size: 10pt;">&nbsp;Дисциплинарная ответственность. Особенности оформления дисциплинарных взысканий. Документы, наделяющие полномочиями расследовать факты нарушения дисциплины</span></li>\r\n<li><span style="font-size: 10pt;">Материальная ответственность. Судебная практика взыскания ущерба в полном объеме. Взыскание затрат на дорогостоящее обучение</span></li>\r\n<li><span style="font-size: 10pt;">Административная и уголовная ответственность. Проверки Государственной инспекции труда. Минимизация рисков обращения работников в надзорно-контрольные органы.</span></li>\r\n<li><span style="font-size: 10pt;">Предупреждение конфликтов, приводящих к обращениям граждан в надзорно-контрольные органы. Этика поведения специалистов HR при спорных и конфликтных ситуациях</span></li>\r\n</ul>\r\n<p style="font-size: 12.16px;"><span style="font-size: 10pt;">&nbsp;- Обзор судебной практики по вопросам расторжения трудовых договоров по инициативе работодателя.</span></p>\r\n<p style="font-size: 12.16px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>8. Прекращение трудовых правоотношений, документирование. Сокращение</strong></span></p>\r\n<ul style="font-size: 12.16px;">\r\n<li><span style="font-size: 10pt;">Прекращение трудового договора по - инициативе работника; - инициативе работодателя; - по соглашению сторон; - обстоятельствам, не зависящим от воли сторон.</span></li>\r\n<li><span style="font-size: 10pt;">&nbsp;Процедура&nbsp; увольнения в зависимости от оснований прекращения трудового договора.</span></li>\r\n<li><span style="font-size: 10pt;">Сокращение численности и сокращение штата:&nbsp; - процедура уведомления работников о сокращении; - процедуры предложения вакансий; - гарантии работника при увольнении по сокращению численности или штата работников</span></li>\r\n</ul>\r\n<p style="font-size: 12.16px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>9. Трудовая книжка,&nbsp; организация кадрового делопроизводства</strong></span></p>\r\n<ul style="font-size: 12.16px; line-height: 15.808px;">\r\n<li><span style="font-size: 10pt;">Трудовая книжка работника: учет, ведение, хранение.</span></li>\r\n<li><span style="font-size: 10pt;">Личная карточка работника: - обязательность заполнения&nbsp;&nbsp; - внесение записей в период работы и при увольнении - порядок учета и хранения.</span></li>\r\n<li><span style="font-size: 10pt;">Личное дело работника.</span></li>\r\n</ul>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="font-size: 10pt;">- Практические задания заполнение трудовой книжки и личного дела.</span></p>\r\n<p style="font-size: 12.16px; line-height: 15.808px;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-family: arial, helvetica, sans-serif; font-size: 10pt;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-weight: bold;">МОДУЛЬ 4. УПРАВЛЕНИЕ ПЕРСОНАЛОМ. ЛИЧНАЯ ЭФФЕКТИВНОСТЬ.</span></span></p>\r\n<p style="font-size: 12.16px;"><span style="font-size: 10pt;">1. Актуальные методики подбора и оценки потенциала кандидатов</span></p>\r\n<p style="font-size: 12.16px;"><span style="font-size: 10pt;">2. Коучинг и адаптация персонала</span></p>\r\n<ul style="font-size: 12.16px;" type="disc">\r\n<li><span style="font-size: 10pt;">&nbsp;Система и оценка управления адаптацией в организации.</span></li>\r\n<li><span style="font-size: 10pt;">&nbsp;Коучинг и наставничество как основные инструменты адаптации.&nbsp;Коучинг - правильные вопросы для развития потенциала сотрудников</span></li>\r\n</ul>\r\n<p style="font-size: 12.16px;"><span style="font-size: 10pt;">3. Обучение и развитие персонала&nbsp; - затраты или вложение в развитие организации?</span></p>\r\n<p style="font-size: 12.16px;"><span style="font-size: 10pt;">4. Мотивация. Как увеличивать прибыль предприятия, внедряя эффективную мотивационную систему персонала?</span></p>\r\n<ul style="font-size: 12.16px;">\r\n<li><span style="font-size: 10pt;">Трудовая мотивация персонала. Внешние и внутренние мотиваторы. Мотивационные механизмы. Демотивация персонала, устранение демотивирующих факторов.</span></li>\r\n<li><span style="font-size: 10pt;">Различная мотивация и циклы развития организации. Принципы эффективной компенсационной политики. Что необходимо для создания успешной системы оплаты труда. Недостатки денег в качестве основного мотиватора.</span></li>\r\n</ul>\r\n<p style="font-size: 12.16px;"><span style="font-size: 10pt;">5.Оценка персонала или поддерживаем в тонусе квалификацию персонала</span></p>\r\n<p style="font-size: 12.16px;"><span style="font-size: 10pt;">6. Корпоративная культура, как она влияет на рост и развитие компании?</span></p>\r\n<p style="font-size: 12.16px;"><span style="font-size: 10pt;">7. Управленческие компетенции</span></p>\r\n<ul style="font-size: 12.16px;">\r\n<li><span style="font-size: 10pt;">Личная эффективность. Целеполагание в &laquo;SMART&raquo; - формате. Методы планирования. Инструменты тайм-менеджмента. Инвентаризация рабочего времени.</span></li>\r\n<li><span style="font-size: 10pt;">Лидерство и команда. Групповая динамика и&nbsp;сплочение коллектива</span></li>\r\n<li><span style="font-size: 10pt;">Делегирование полномочий. Цели и барьеры делегирования. Алгоритм делегирования. Правила предоставления обратной связи.</span></li>\r\n<li><span style="font-size: 10pt;">Конфликтология. Управление организационным конфликтом. Виды, причины, стадии развития конфликта. Стили поведения в конфликте. Этапы разрешения и способы урегулирования конфликта. Методы профилактики конфликтов.</span></li>\r\n<li><span style="font-size: 10pt;">Стресс-менеджмент. Причины и симптомы стрессового напряжения. Способы сохранения и восстановления эмоционального равновесия и работоспособности. Антистресс - профилактика. Организационный стресс и результативность команды.</span></li>\r\n</ul>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>Продолжительность</strong></span>&nbsp;- 5&nbsp;месяцев &nbsp;<span style="font-family: arial, helvetica, sans-serif;"><strong>Расписание:</strong></span> &nbsp;понедельник, среда с 18.30 до 19.30, суббота с 09.00 до 13.45. &nbsp;Дни недели могут изменяться</p>\r\n<p style="box-sizing: inherit; margin: 0px 0px 10px; padding: 0px; text-align: justify; color: #351e07; font-family: Pro; font-size: 14px; background-color: #fefefe;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-weight: bold;"><span style="color: #800000;"><a style="box-sizing: inherit; margin: 0px; padding: 0px; background-color: transparent; color: #800000;" href="#call_me" rel="alternate">ОТПРАВИТЬ ЗАЯВКУ</a></span>&nbsp;</span>&nbsp;<span style="box-sizing: inherit; margin: 0px; padding: 0px; font-family: arial, helvetica, sans-serif;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-weight: bold;">Скидка 10 %</span></span>&nbsp;при оплате &nbsp;<span style="box-sizing: inherit; margin: 0px; padding: 0px; font-weight: bold;">&nbsp;за 4&nbsp;недели до обучения</span>&nbsp;&nbsp;&nbsp;<span style="box-sizing: inherit; margin: 0px; padding: 0px; font-weight: bold;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-family: arial, helvetica, sans-serif;">Скидка 5%&nbsp;&nbsp;</span></span>при оплате за 2&nbsp; недели до начала обучения<span style="box-sizing: inherit; margin: 0px; padding: 0px; font-weight: bold;">.</span>&nbsp;<span style="box-sizing: inherit; margin: 0px; padding: 0px; font-family: arial, helvetica, sans-serif;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-weight: bold;">Выдается удостоверение о повышении квалификации. &nbsp;</span></span></p>', '', -2, 11, '2016-12-12 08:29:36', 42, '', '2016-12-12 08:29:36', 0, 0, '0000-00-00 00:00:00', '2016-12-12 08:29:59', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 1, 72, '', '', 1, 0, '{}', 0, '*', '');
INSERT INTO `j7_content` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(145, 243, 'Специалист по маркетингу. Диплом о переподготовке', 'специалист-по-маркетингу-диплом-о-переподготовке', '<h1 style="text-align: center;"><span style="font-family: Pro;">Специалист по маркетингу. Диплом о переподготовке</span></h1>\r\n<p><span style="font-family: Pro;"><strong>Целевая аудитория</strong><span style="font-size: 10pt;"><strong>:&nbsp;</strong>специалисты и руководители подразделений и организаций, менеджеры по развитию, предприниматели</span></span></p>\r\n<p><span style="font-family: Pro;"><strong><span style="margin: 0px; padding: 0px;">Ведущие курса:</span></strong> </span></p>\r\n<p><span style="font-family: Pro;"><!-- noindex --></span></p>\r\n<p><span style="font-family: Pro;"><a href="index.php?option=com_content&amp;view=article&amp;id=175&amp;catid=26">Иванова Татьяна Владимировна</a>&nbsp;-&nbsp;специалист по разработке маркетинговых стратегий, директор по маркетингу</span><br /><span style="font-family: Pro;"><a href="index.php?option=com_content&amp;view=article&amp;id=149&amp;catid=26">Попов Дмитрий Павлович</a> - специалист в области интернет-коммуникаций</span><br /><span style="font-family: Pro;"><a href="index.php?option=com_content&amp;view=article&amp;id=210&amp;catid=23" rel="nofollow">Макарова Юлия Олеговна</a> - бизнес тренер в области продаж и коммуникаций</span></p>\r\n<p><br /><span style="font-family: Pro;"><strong>Обучение на специалиста по маркетингу состоит из 2 модулей:</strong><span style="font-size: 10pt;"><strong><br /></strong></span></span></p>\r\n<p><span style="font-family: Pro;">1. Эффективный маркетинг и продвижение в интернете</span></p>\r\n<p><span style="font-family: Pro;">2. Продажи и переговоры в маркетинге</span><br /><br /></p>\r\n<p style="text-align: center;"><span style="font-family: Pro;"><a onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<p>&nbsp;</p>\r\n<p><a href="#"><img src="images/slider/shablon_diploma.jpg" alt="обучение маркетолога" width="30%" height="250" />&nbsp; &nbsp;</a><a href="#"><img src="images/slider/shablon_diploma_vnutri.jpg" alt="курсы по маркетингу" width="30%" height="250" />&nbsp;&nbsp;</a><a href="#"><img src="images/slider/специалист_по_маркетингу.jpg" alt="специалист по маркетингу обучение" width="30%" height="250" /></a></p>\r\n<hr />\r\n<p><span style="font-family: Pro;">&nbsp;<span style="font-size: 12pt;"><strong>Программа курса:</strong></span></span></p>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 16px; background-color: #ffffff;">\r\n<td style="height: 16px;" colspan="2"><span style="font-family: Pro; font-size: 12pt;"><strong style="color: #a22521;">Модуль 1. Эффективный маркетинг и&nbsp;продвижение</strong></span></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 16px; background-color: #ffffff;">\r\n<td style="height: 16px;" colspan="2"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n</tbody>\r\n<tbody>\r\n<tr style="height: 191.587px;">\r\n<td style="background-color: #f7f7f7; height: 191.587px; width: 20.5084%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>1. Маркетинговый аудит положения компании на рынке</strong></span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 191.587px; width: 75.4916%;">\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;">1) Как определить место компании на рынке?&nbsp;</span><span style="font-size: 10pt;">Ресурсы и способности вашей компании</span></span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Целевая аудитория и сегментирование клиентов. Определение основных сегментов аудитории.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) Позиционирование&nbsp;товара. Определяем конкурентные преимущества.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4) Анализ конкурентов и бенчмаркетинг. Как использовать конкурентов в достижении собственных целей.&nbsp;&nbsp;SWOT- анализ.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">5) Инновационный маркетинг - как непрерывное совершенствование продуктов, услуг</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><em>П<em>ра</em>ктика: проводим маркетинговый аудит положения компании на рынке и сегментируем клиентов. </em> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 20.5084%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 75.4916%; height: 14px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 137px;">\r\n<td style="background-color: #f7f7f7; height: 137px; width: 20.5084%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>2.&nbsp;Маркетинговые исследования. Взаимосвязь стратегии компании с маркетинговыми исследованиями</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 137px; width: 75.4916%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1) Для чего именно нам нужно проведение исследований? Анализ и эффективные стратегии</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Выбираем инструменты исследований: количественные и качественные исследования, полевые и кабинетные. Социологические и маркетинговые. Где искать данные, чтобы сэкономить на исследованиях и повысить их эффективность?</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) Использование маркетинговых исследований и маркетинговой информации в компании. Как сэкономить на исследованиях и включить в маркетинг каждого сотрудника компании?</span></p>\r\n<p><span style="font-family: Pro;"><em><span style="font-size: 10pt;">Практика: проводим исследования и определяем маркетинговую стратегию&nbsp; </span></em> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 20.5084%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 75.4916%; height: 14px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 151px;">\r\n<td style="background-color: #f7f7f7; height: 151px; width: 20.5084%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong><span lang="EN-US">3.&nbsp;Торговый маркетинг&nbsp;</span></strong> </span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 151px; width: 75.4916%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1) Категорийный менеджмент&nbsp;и прибыльность товаров. Принцип Паретто. АВС анализ и матрица БКГ</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Принципы управления ассортиментной матрицей.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) УТП (уникальное торговое предложение). Как правильно определить свою уникальность? Какие признаки могут стать преимуществом вашего товара или услуги, а какие нет. &nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4) Ассортиментная политика компании. &nbsp;Как заработать на расширении ассортимента?&nbsp;</span></p>\r\n<p><span style="font-family: Pro;"><em><span style="font-size: 10pt;">Практика: формируем&nbsp; ассортиментную матрицу </span></em> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 20.5084%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 75.4916%; height: 14px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 134px;">\r\n<td style="background-color: #f7f7f7; height: 134px; width: 20.5084%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>4.&nbsp;Ценообразование и управление ассортиментом</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 134px; width: 75.4916%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1)&nbsp;Ценообразование и ценовая стратегия. Как сформировать стоимость товара при разных позициях на рынке?&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2)&nbsp;Управление товарным ассортиментов на промышленных рынках и в сфере услуг</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">Практика: Формируем&nbsp;УТП&nbsp;вашей компании с рыночным обоснованием&nbsp; и &nbsp;продвижением.</span></p>\r\n<p><span style="font-family: Pro;"><em><span style="font-size: 10pt;">Практика: Определяем способы повышения клиентоориентированности вашей компании. </span></em> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 20.5084%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 75.4916%; height: 14px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 243px;">\r\n<td style="background-color: #f7f7f7; height: 243px; width: 20.5084%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;"><strong>5.&nbsp;Интегрированные маркетинговые коммуникации. Реклама и продвижение</strong></span></p>\r\n</td>\r\n<td style="background-color: #f7f7f7; height: 243px; width: 75.4916%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1) Инструменты продвижения. Их возможности и недостатки. Современные технологии управления взаимоотношениями с клиентами.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Нейромаркетинг. Прямой маркетинг. &nbsp;Ивент-маркетинг. Public Relations.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) Понятия «бренд» и «брендинг». &nbsp;Чем бренд отличается от товара. Как создать бренд.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4) Подходы к оценке эффективности рекламных кампаний.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">5) Элементы бренда: как управлять популярностью торговой марки.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">6) Определение точек контакта с существующими и потенциальными клиентами.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">7) CRM. &nbsp;Как выстраивать взаимоотношения с клиентами с помощью современных автоматизированных систем.<br /></span></p>\r\n<p><span style="font-family: Pro;"><em><span style="font-size: 10pt;">Практика: считаем эффективность рекламных компаний </span></em> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 20.5084%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 75.4916%; height: 14px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 120px;">\r\n<td style="background-color: #f7f7f7; height: 120px; width: 20.5084%;"><span style="font-family: Pro; font-size: 10pt;"><strong>6.&nbsp;Медиапланирование</strong></span></td>\r\n<td style="background-color: #f7f7f7; height: 120px; width: 75.4916%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1)&nbsp;Медиапланирование. Эффективная частота размещения рекламы по разным каналам продвижения.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2)&nbsp;Бюджетирование рекламных кампаний. &nbsp;Как эффективно распределять бюджеты, чтобы получать максимальный результат.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3)&nbsp;Подходы к оценке эффективности рекламных кампаний.</span></p>\r\n<p><span style="font-family: Pro;"><em><span style="font-size: 10pt;">Практика: составляем медиа-план </span></em> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 20.5084%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 75.4916%; height: 14px;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 96%; background-color: #f7f7f7; height: 14px;" colspan="2"><span style="font-family: Pro; font-size: 10pt;"><strong>7.&nbsp;Формирование маркетингового плана вашей компании.</strong></span></td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 20.5084%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n<td style="width: 75.4916%; height: 14px;"><span style="font-family: Pro; font-size: 10pt;"><strong>&nbsp;</strong></span></td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="width: 96%; height: 14px; text-align: center;" colspan="2"><span style="font-size: 10pt; font-family: Pro;"><strong>ИНТЕРНЕТ-МАРКЕТИНГ</strong> </span></td>\r\n</tr>\r\n<tr style="height: 10px;">\r\n<td style="background-color: #f7f7f7; height: 10px; width: 20.5084%;"><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">8.&nbsp;SEO: базовые основы и практические инструменты</span></strong> </span></td>\r\n<td style="background-color: #f7f7f7; height: 10px; width: 75.4916%;">\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: Pro;"><strong><span style="color: #800000;">Что&nbsp; изучите:</span> </strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Алгоритмы работы поисковых систем. Анализ поисковых запросов. Факторы, влияющие на ранжирование сайтов</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Сбор семантического ядра и его кластеризация. Изучение сервиса Wordstat.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Размещение контента на сайте: текстов, инфографика, заполнение метатегов, подбор изображений, видео.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">SEO-копирайтинг: правила написания продающих текстов в соответствии с алгоритмами поисковых систем.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Внутренняя перелинковка страниц. Схемы перелинковки.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Внешняя оптимизация сайта. Подбор площадок для размещения ссылок.</span></li>\r\n</ol>\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Какие навыки получите:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Сбор семантического ядра, кластеризация ключевых фраз.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Работа с сервисом Wordstat.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Подготовка технических заданий на SEO-копирайтинг.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Выбор подходящих площадок для внешней оптимизации.</span></li>\r\n</ol></td>\r\n</tr>\r\n<tr style="height: 14px;">\r\n<td style="background-color: #ffffff; height: 14px; width: 20.5084%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; height: 14px; width: 75.4916%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 10px;">\r\n<td style="background-color: #f7f7f7; height: 10px; width: 20.5084%;"><span style="font-family: Pro; font-size: 10pt;"><strong>9.&nbsp;</strong><strong>Контекстная реклама: основы размещения рекламы в Яндекс и&nbsp;</strong><strong>Google</strong></span></td>\r\n<td style="background-color: #f7f7f7; height: 10px; width: 75.4916%;">\r\n<p style="text-align: justify;"><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Что освоите:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Виды рекламных кампаний.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Использование ключевых фраз: подбор подходящих, фильтрация минус-фраз.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Создание рекламных кампаний в Яндекс Директ и Google Adwords: регистрация в личном кабинете, базовые настройки, создание рекламных объявлений.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Изучение факторов, влияющих на стоимость клика.</span></li>\r\n</ol>\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Какие навыки&nbsp; получите:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Грамотный подбор ключевых фраз и составление эффективных объявлений.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Настройка рекламной кампании в личном кабинете Яндекс Директ и Google Adwords.</span></li>\r\n</ol></td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="background-color: #ffffff; height: 13px; width: 20.5084%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; height: 13px; width: 75.4916%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 10px;">\r\n<td style="background-color: #f7f7f7; height: 10px; width: 20.5084%;"><span style="font-family: Pro;"><strong><span style="font-size: 10pt;"><span lang="EN-US">10. Системы аналитики. Изучение Яндекс Метрики.</span></span> </strong> </span></td>\r\n<td style="background-color: #f7f7f7; height: 10px; width: 75.4916%;">\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Что&nbsp; проработаете:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Показатели, которые необходимо отслеживать.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Регистрация в Яндекс Метрике, знакомство с личным кабинетом.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Изучение отчетов в системе аналитики.</span></li>\r\n</ol>\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Какие&nbsp; навыки получите:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Понимание основных отчетов и показателей.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Настройка целей системе аналитики.</span></li>\r\n</ol></td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="background-color: #ffffff; height: 13px; width: 20.5084%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; height: 13px; width: 75.4916%;"><span style="font-family: Pro;">&nbsp;&nbsp;</span></td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="background-color: #f7f7f7; height: 13px; width: 20.5084%;"><span style="font-family: Pro;"><strong><span style="font-size: 10pt;"><span lang="EN-US">11.&nbsp;SMM. Работа в социальных сетях: Facebook, ВКонтакте, Instagram.</span></span> </strong> </span></td>\r\n<td style="background-color: #f7f7f7; height: 13px; width: 75.4916%;">\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Что изучите:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-size: 10pt; font-family: Pro;">Обзор возможностей социальных сетей.</span></li>\r\n<li><span style="font-size: 10pt; font-family: Pro;">Стратегии позиционирования.</span></li>\r\n<li><span style="font-size: 10pt; font-family: Pro;">Виды сообществ в каждой из социальных сетей.</span></li>\r\n<li><span style="font-size: 10pt; font-family: Pro;">Формирование контент-плана.</span></li>\r\n<li><span style="font-size: 10pt; font-family: Pro;">Знакомство с сервисами автопостинга (SMM Planner), сбора целевой аудитории (Церебро Таргет).</span></li>\r\n<li><span style="font-size: 10pt; font-family: Pro;">Бесплатные методы продвижения.</span></li>\r\n<li><span style="font-size: 10pt; font-family: Pro;">Запуск таргетированной рекламы в Facebook, ВКонтакте, Instagram.</span></li>\r\n</ol>\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Какие навыки&nbsp; получите:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-size: 10pt; font-family: Pro;">Создание сообщества для Вашего бизнеса.&nbsp;</span></li>\r\n<li><span style="font-size: 10pt; font-family: Pro;">Работа в программах автопостинга и сбора целевой аудитории.</span></li>\r\n<li><span style="font-size: 10pt; font-family: Pro;">Настройка таргетированной рекламы в каждой из социальных сетей: Facebook, ВКонтакте, Instagram.</span></li>\r\n</ol></td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="background-color: #ffffff; height: 13px; width: 20.5084%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; height: 13px; width: 75.4916%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="background-color: #f7f7f7; height: 13px; width: 20.5084%;"><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">12.&nbsp;Продвижение видео-канала на You-Tube.</span></strong> </span></td>\r\n<td style="background-color: #f7f7f7; height: 13px; width: 75.4916%;">\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Что&nbsp; рассмотрите:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Виды видео-контента и особенности его подготовки.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Запуск видео-канала на You-Tube, базовые настройки.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Разработка стратегии ведения канала.&nbsp;</span></li>\r\n</ol>\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Какие практические навыки:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Запуск видео-канала на You-Tube.</span></li>\r\n<li style="text-align: left;"><span style="font-family: Pro; font-size: 10pt;">Базовые настройки канала для эффективного продвижения.</span></li>\r\n</ol></td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="background-color: #ffffff; height: 13px; width: 20.5084%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; height: 13px; width: 75.4916%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 13px;">\r\n<td style="background-color: #f7f7f7; height: 13px; width: 20.5084%;"><span style="font-family: Pro;"><strong><span style="font-size: 10pt;">13.&nbsp;E-mail маркетинг: основы работы и запуск продающих рассылок.</span></strong> </span></td>\r\n<td style="background-color: #f7f7f7; height: 13px; width: 75.4916%;">\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Что&nbsp; освоите:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Сбор базы подписчиков – основные инструменты и сервисы.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Обзор основных инструментов для рассылок: плюсы и минусы.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Типы рассылок и выбор эффективной стратегии.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Создание цепочки писем и особенности формирования контента.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Знакомство с сервисом для рассылок Send Pulse.</span></li>\r\n</ol>\r\n<p><span style="font-size: 10pt; color: #800000; font-family: Pro;"><strong>Какие навыки получите:</strong> </span></p>\r\n<ol>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Создание продающего электронного письма.</span></li>\r\n<li><span style="font-family: Pro; font-size: 10pt;">Настройка сервиса Send Pulse.</span></li>\r\n</ol></td>\r\n</tr>\r\n</tbody>\r\n<tbody>\r\n<tr style="height: 15px;">\r\n<td style="height: 15px;"><span style="font-family: Pro;">&nbsp;<strong>Проектная работа</strong></span></td>\r\n<td style="height: 15px;"><span style="font-family: Pro;">&nbsp;Разработка и совершенствование маркетинговой стратегии на предприятии</span></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="height: 15px; width: 28.3823%;"><span style="font-family: Pro;"></span></td>\r\n<td style="height: 15px; width: 70.4705%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 16px; background-color: #ffffff;">\r\n<td style="height: 16px; width: 98.8528%;" colspan="2"><span style="font-family: Pro; font-size: 12pt;"><strong style="color: #a22521;">Модуль 2.&nbsp; Продажи и переговоры в маркетинге</strong></span></td>\r\n</tr>\r\n<tr style="height: 190px; background-color: #f5f5f5;">\r\n<td style="height: 190px; width: 28.3823%;">\r\n<p><span style="font-family: Pro;"><strong>1. Поиск клиентов. Как искать клиентов?</strong>&nbsp;</span></p>\r\n</td>\r\n<td style="height: 190px; width: 70.4705%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1) Взаимосвязь отдела продаж и отдела маркетинга.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Сбор информации о бизнесе клиента и конкурентах.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) "Холодные" и "теплые" звонки (ключевые фразы). Правильная постановка целей, сценарии звонка.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4) Контакт с клиентом. Универсальные приемы установления контакта. Практика установления контакта.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">5) Как управлять воронкой продаж. Воронка как инструмент анализа эффективности работы менеджера.&nbsp;</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">6) Лучшие способы поиска новых клиентов.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">ПРАКТИКА&nbsp;разработки коммерческих предложений, скриптов продаж, "продающих" текстов.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="height: 15px; width: 28.3823%;"><span style="font-family: Pro;"></span></td>\r\n<td style="height: 15px; width: 70.4705%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 87px; background-color: #f5f5f5;">\r\n<td style="height: 87px; width: 28.3823%;">\r\n<p><span style="font-family: Pro;"><strong>2. Правильные вопросы,&nbsp;выявление потребностей</strong></span></p>\r\n</td>\r\n<td style="height: 87px; width: 70.4705%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">1) Правильные вопросы для выявления потребности, зачем задавать вопросы?</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">2) Развитие диалога: управляем беседой и клиентом при помощи вопросов.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="height: 15px; width: 28.3823%;"><span style="font-family: Pro;"></span></td>\r\n<td style="height: 15px; width: 70.4705%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 101px; background-color: #f5f5f5;">\r\n<td style="height: 101px; width: 28.3823%;">\r\n<p><span style="font-family: Pro;"><strong>3. Презентация компании, товара</strong></span></p>\r\n</td>\r\n<td style="height: 101px; width: 70.4705%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">1) Покупательские мотивы, модель перевода свойств в выгоду.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">2) Способы обоснования цены, аргументируем цена&nbsp;&nbsp;- выгода.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">3) 6 лучших способов для выгодной презентации цены.&nbsp;</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">ПРАКТИКА выявления мотивов и формирования выгод клиента.&nbsp;</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">ПРАКТИКА разработки презентационных материалов.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="height: 15px; width: 28.3823%;"><span style="font-family: Pro;"></span></td>\r\n<td style="height: 15px; width: 70.4705%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 130px; background-color: #f5f5f5;">\r\n<td style="height: 130px; width: 28.3823%;">\r\n<p><span style="font-family: Pro;"><strong>4.&nbsp;Преодоление реакций клиента. Работа с возражениями</strong>&nbsp;</span></p>\r\n</td>\r\n<td style="height: 130px; width: 70.4705%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1)&nbsp;Причины возникновения возражений:&nbsp;&nbsp;цена, отговорки.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2) Модель обработки возражений, применение тактики аргументации.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3) 10 правил работы с возражениями клиентов.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">4) Скрипты на главные возражение «дорого», «я подумаю», «нет денег».&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="height: 15px; width: 28.3823%;"><span style="font-family: Pro;"></span></td>\r\n<td style="height: 15px; width: 70.4705%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 101px; background-color: #f5f5f5;">\r\n<td style="height: 101px; width: 28.3823%;">\r\n<p><span style="font-family: Pro;"><strong>5. Завершение сделки, диалога.&nbsp;Как завершить диалог, чтобы &nbsp;клиент купил товар?</strong></span></p>\r\n</td>\r\n<td style="height: 101px; width: 70.4705%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">1)&nbsp;Сигналы готовности клиента к покупке приемы.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">2) Этап завершения сделки, тонкости доведения сделки до результата.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">3) Скрипты на завершение сделки.&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="height: 15px; width: 28.3823%;"><span style="font-family: Pro;"></span></td>\r\n<td style="height: 15px; width: 70.4705%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 101px; background-color: #f5f5f5;">\r\n<td style="height: 101px; width: 28.3823%;">\r\n<p><span style="font-family: Pro;"><strong>6. Формирование потребностей – СПИН</strong></span></p>\r\n</td>\r\n<td style="height: 101px; width: 70.4705%;">\r\n<p><span style="font-family: Pro; font-size: 10pt;">1)&nbsp;Модель СПИН как гибкая система продаж.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">2)&nbsp;Вопросы – СПИН.</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">3)&nbsp;Как работает СПИН?</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="height: 15px; width: 28.3823%;"><span style="font-family: Pro;"></span></td>\r\n<td style="height: 15px; width: 70.4705%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 72px; background-color: #f5f5f5;">\r\n<td style="height: 72px; width: 28.3823%;">\r\n<p><span style="font-family: Pro;"><strong>7. Алгоритм продажи с крупными клиентами, важные этапы ведения деловой беседы</strong></span></p>\r\n</td>\r\n<td style="height: 72px; width: 70.4705%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">1) Как вести себя с крупными клиентами, особенности продажи.</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">2) Умение правильно строить отношения.&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="height: 15px; width: 28.3823%;"><span style="font-family: Pro;"></span></td>\r\n<td style="height: 15px; width: 70.4705%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 44px; background-color: #f5f5f5;">\r\n<td style="height: 44px; width: 28.3823%;">\r\n<p><span style="font-family: Pro;"><strong>8. Кросс-продажи</strong></span></p>\r\n</td>\r\n<td style="height: 44px; width: 70.4705%;">\r\n<p><span style="font-size: 10pt; font-family: Pro;">Как они повышают прибыль?&nbsp;</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;">ПРАКТИКА разработки дополнительных предложений для клиентов.</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 16px; background-color: #f5f5f5;">\r\n<td style="background-color: #ffffff; height: 16px; width: 28.3823%;"><span style="font-family: Pro;"></span></td>\r\n<td style="background-color: #ffffff; height: 16px; width: 70.4705%;"><span style="font-family: Pro;"></span></td>\r\n</tr>\r\n<tr style="height: 17px; background-color: #f5f5f5;">\r\n<td style="height: 17px; width: 28.3823%;">\r\n<p><span style="font-family: Pro;"><strong>9. Постановка целей, личная эффективность</strong></span></p>\r\n</td>\r\n<td style="height: 17px; width: 70.4705%;"><span style="font-size: 10pt; font-family: Pro;">Личная эффективность. Целеполагание в «SMART»- формате.&nbsp;</span></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<hr />\r\n<p><strong><span style="font-family: Pro; font-size: 12pt;">Формат курса</span></strong></p>\r\n<p>&nbsp;</p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro; font-size: 10pt;">•&nbsp;<strong style="color: #a22521;">Очное обучение.</strong> Продолжительность: 3 месяца</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="font-size: 10pt; background-color: inherit; color: inherit;">•&nbsp;</span><strong style="color: #a22521;">Дистанционное обучение.</strong><span style="font-size: 10pt; background-color: inherit; color: inherit;"> Продолжительность: 3 месяца. видео-лекции, аттестационные работы с обратной связью от преподавателя</span></span></p>\r\n<p><span style="font-family: Pro;">Формы обучения &nbsp;включают&nbsp; в себя: информационные модули, дискуссии и мозговые штурмы, ролевые игры и упражнения, «разбор полетов» (моделирование и анализ реальных ситуаций взаимодействия)</span></p>\r\n<hr />\r\n<p><span style="font-family: Pro;"><strong><span style="font-size: 12pt;">Акции и скидки:</span></strong> </span></p>\r\n<p>&nbsp;</p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit; color: inherit; font-size: 1rem;">•&nbsp;</span>Скидка 10%&nbsp;при оплате за 4 недели до обучения.&nbsp;&nbsp;</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit; color: inherit; font-size: 1rem;">•&nbsp;</span>Скидка 5%&nbsp;при оплате за 2 недели до обучения.</span></p>\r\n<p>&nbsp;</p>\r\n<p style="text-align: center;"><span style="font-family: Pro;"><a onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<hr />\r\n<p><span style="color: #333333; font-family: Pro;"><span style="font-size: 16px;"><b>О нас</b></span></span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p><span style="font-family: Pro;"><iframe style="background-image: url(''img/iframe.png''); display: block; margin-left: auto; margin-right: auto;" src="https://www.youtube.com/embed/yx3VnN5bh2k" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture"></iframe></span></p>', '', 1, 26, '2016-12-12 16:22:57', 42, '', '2019-04-30 05:55:10', 42, 0, '0000-00-00 00:00:00', '2016-12-12 16:43:09', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 85, 11, 'диплом маркетолога, обучение маркетологов, переподготовка на маркетолога', 'Переподготовка маркетологов на диплом. Очно и дистанционно. От экспертов практиков. Обучение маркетингу. Скидки до 15%', 1, 6908, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(189, 293, 'Брагина Светлана Сергеевна', 'bragina-svetlana-sergeevna', '<p style="text-align: center;">&nbsp;</p>\r\n<table style="color: #333333; font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; font-weight: normal; text-align: start; width: 773px; height: 609px;">\r\n<tbody>\r\n<tr style="height: 185.958px;">\r\n<td style="width: 140px; height: 185.958px;"><img src="images/Bragina10.jpg" alt="" width="108" height="153" /></td>\r\n<td style="width: 656px; height: 185.958px;">\r\n<h1 style="text-align: left;">Брагина Светлана Сергеевна</h1>\r\n<p><span style="font-size: 10pt;"><strong>Преподаватель&nbsp;- практик &nbsp;в области&nbsp;государственных и коммерческих закупок</strong></span></p>\r\n<p><span style="font-size: 10pt;">- Более 7 лет опыта&nbsp;работы по специализации&nbsp;</span></p>\r\n<p><span style="font-size: 10pt;">- Более 3&nbsp;лет опыта работы преподавателем</span></p>\r\n<p><span style="font-size: 10pt;">&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="height: 15px; width: 796px;" colspan="2">\r\n<p><span style="font-size: 10pt;"><strong>О</strong><strong>бразование Высшее:</strong></span></p>\r\n<p><span style="font-size: 10pt;">2003 - 2008 гг. - Уральский Федеральный Университет имени первого Президента России Б.Н.Ельцина, экономика и управление.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-size: 10pt;"><strong>Образование Дополнительное:</strong></span></p>\r\n<p><span style="font-size: 10pt;">2016 г. - Педагогика и методика обучения, повышение квалификации г. Екатеринбург</span></p>\r\n<p><span style="font-size: 10pt;">2016 - 2013 гг. - повышении квалификации в сфере закупок по нормам Федерального закона № 223-ФЗ от 18.07.2011г. г. Москва</span></p>\r\n<p><span style="font-size: 10pt;">2015 г.&nbsp;- повышение квалификации "Практика применения 44-ФЗ"&nbsp;г. Москва</span></p>\r\n<p><span style="font-size: 10pt;">2014 г. - повышении квалификации "Организация работы контрактной службы, контрактного управляющего в сфере закупок для государственных и муниципальных нужд"&nbsp;г. Москва</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-size: 10pt;"><strong>Трудовая деятельность:</strong></span></p>\r\n<p><span style="font-size: 10pt;">2013 г. - по настоящее время - руководитель группы закупок по 44-ФЗ и 223-ФЗ НПП "Старт"</span></p>\r\n<p><span style="font-size: 10pt;">2011&nbsp;- 2013 гг. - руководитель отдела по работе с тендерами ОАО "Птицефабрика "Рефтинская"</span></p>\r\n<p><span style="font-size: 10pt;">2010&nbsp;- 2011 гг. -&nbsp;специалист отдела закупок ОАО "МРСК Урала"</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-size: 10pt;"><strong>Разработаны и проведены программы:</strong></span></p>\r\n<p><span style="font-size: 10pt;">- Базовые учебные программы для Заказчиков и Участников по 44-ФЗ&nbsp;</span></p>\r\n<p><span style="font-size: 10pt;">- Проведение аудита закупочной деятельности и последующее обучение сотрудников отдела закупок</span></p>\r\n<p><span style="font-size: 10pt;">- Тендер - менеджер, закупки по 223 ФЗ&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span style="font-size: 10pt;">&nbsp;</span></p>\r\n<p>&nbsp;</p>', '', 0, 16, '2017-05-16 12:53:54', 42, '', '2017-08-08 06:32:30', 42, 42, '2017-08-08 06:32:30', '2017-05-16 18:29:27', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 35, 15, '', '', 1, 619, '{}', 0, '*', ''),
(153, 254, 'Образовательные стандарты', 'образовательные-стандарты', '<h1><span style="font-family: arial, helvetica, sans-serif;">Образовательные стандарты</span></h1>\r\n<p><span style="font-family: arial, helvetica, sans-serif;">Дополнительное профессиональное образование осуществляется с учетом федеральных государственных образовательных стандартов ФГОС. &nbsp;Обязательное применение ФГОС &nbsp;в нормативных законодательных &nbsp;актах дополнительного&nbsp;&nbsp;образования&nbsp;отсутствует.</span></p>', '', 1, 2, '2017-01-22 15:31:47', 42, '', '2017-01-22 10:45:01', 42, 42, '2019-04-15 12:48:28', '2017-01-22 10:44:56', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 3, 5, '', '', 1, 6094, '', 0, '*', ''),
(154, 255, 'Материально-техническое обеспечение  ', 'материально-техническое-обеспечение', '<h1><span style="font-family: arial, helvetica, sans-serif;">Сведения о Материально-техническом обеспечении&nbsp;</span></h1>\r\n<table style="width: 509px;">\r\n<tbody>\r\n<tr style="height: 37px;">\r\n<td style="width: 401px; height: 37px;">\r\n<p class="MsoNormal" style="text-align: center;" align="center">Учебные аудитории, оргтехника, выход в Интернет и т.д.</p>\r\n</td>\r\n<td style="width: 130px; height: 37px;">количество</td>\r\n</tr>\r\n<tr style="height: 9px;">\r\n<td style="width: 401px; height: 9px;">Проектор</td>\r\n<td style="width: 130px; height: 9px;">&nbsp;1</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 401px; height: 15px;">Доска</td>\r\n<td style="width: 130px; height: 15px;">&nbsp;1</td>\r\n</tr>\r\n<tr style="height: 16px;">\r\n<td style="width: 401px; height: 16px;">Ноутбук</td>\r\n<td style="width: 130px; height: 16px;">&nbsp;12</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 401px; height: 15px;">Столы</td>\r\n<td style="width: 130px; height: 15px;">&nbsp;12</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 401px; height: 15px;">Стулья</td>\r\n<td style="width: 130px; height: 15px;">&nbsp;12</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 401px; height: 15px;">Шкаф</td>\r\n<td style="width: 130px; height: 15px;">&nbsp;1</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 401px; height: 15px;">Огнетушитель</td>\r\n<td style="width: 130px; height: 15px;">&nbsp;2</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 401px; height: 15px;">Кондиционер</td>\r\n<td style="width: 130px; height: 15px;">&nbsp;1</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 401px; height: 15px;">Кулер для воды</td>\r\n<td style="width: 130px; height: 15px;">&nbsp;1</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 401px; height: 15px;">Выход в интернет</td>\r\n<td style="width: 130px; height: 15px;">&nbsp;12</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 401px; height: 15px;">Учебное програмное обеспечение: Гранд- Смета, 1 С "Бухгалтерия"</td>\r\n<td style="width: 130px; height: 15px;">12</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 401px; height: 15px;">Нормативная Законодательная база, кодексы: НКРФ, ТКРФ, О контрактной системе</td>\r\n<td style="width: 130px; height: 15px;">12</td>\r\n</tr>\r\n<tr style="height: 15.4375px;">\r\n<td style="width: 401px; height: 15.4375px;">Рабочая тетрадь, методические материалы слушателя</td>\r\n<td style="width: 130px; height: 15.4375px;">12</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 401px; height: 15px;">Канцтовары: тетрадь, ручка,&nbsp;текстовыделитель</td>\r\n<td style="width: 130px; height: 15px;">12</td>\r\n</tr>\r\n</tbody>\r\n</table>', '', 1, 2, '2017-01-22 16:08:23', 42, '', '2017-03-02 08:47:17', 42, 42, '2019-04-16 04:52:39', '2017-01-22 11:10:28', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 6, 8, '', '', 1, 3283, '', 0, '*', ''),
(150, 251, 'Основные сведения об организации', 'основные-сведения-об-организации', '<h1>Основные сведения&nbsp;об организации</h1>\r\n<table style="width: 724px;">\r\n<tbody>\r\n<tr style="height: 15px;">\r\n<td style="width: 313px; height: 15px;">Полное наименование организации</td>\r\n<td style="width: 427px; height: 15px;">Частное учреждение дополнительного профессионального образования "ЭмМенеджмент"</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 313px; height: 15px;">Сокращенное наименование организации</td>\r\n<td style="width: 427px; height: 15px;">ЧУДПО &laquo;ЭмМенеджмент&raquo;</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 313px; height: 15px;">Дата создания</td>\r\n<td style="width: 427px; height: 15px;">14.02.2012 г.</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 313px; height: 15px;">Учредитель</td>\r\n<td style="width: 427px; height: 15px;"><span style="line-height: 15.808px;">Тимофеева Ирина Аркадьевна</span></td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 313px; height: 15px;">Наименование исполнительного органа</td>\r\n<td style="width: 427px; height: 15px;">Директор</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 313px; height: 15px;">Имя директора</td>\r\n<td style="width: 427px; height: 15px;">Тимофеева Ирина Аркадьевна, на основании Устава</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 313px; height: 15px;">Юридически адрес</td>\r\n<td style="width: 427px; height: 15px;">620142 г. Екатеринбург, Степана Разина дом 16 офис 412</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 313px; height: 15px;">Фактический, почтовый адрес:</td>\r\n<td style="width: 427px; height: 15px;">620142 г. Екатеринбург, Степана Разина дом 16 офис 412</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 313px; height: 15px;">ОГРН</td>\r\n<td style="width: 427px; height: 15px;">1126600000570</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 313px; height: 15px;">ИНН / КПП</td>\r\n<td style="width: 427px; height: 15px;">6679996150 / 667101001</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 313px; height: 15px;">Код по ОКВЭД - основной вид деятельности</td>\r\n<td style="width: 427px; height: 15px;">80.42 &ndash; образование для взрослых</td>\r\n</tr>\r\n<tr style="height: 15.4375px;">\r\n<td style="width: 313px; height: 15.4375px;">Банковские реквизиты</td>\r\n<td style="width: 427px; height: 15.4375px;">\r\n<p class="MsoNormal">Расчетный счет 40703810100210001549 Банк &laquo;НЕЙВА&raquo; ООО<br />кор./счет 30101810400000000774 БИК 046577774</p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 313px; height: 15px;">Контактные данные</td>\r\n<td style="width: 427px; height: 15px;">Тел. факс: +7 (343) 266-79-85, +7 (343)&nbsp;328-46-62</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 313px; height: 15px;">Адрес электронной почты</td>\r\n<td style="height: 15px;">ammanagment@yandex.ru</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td>Время работы&nbsp;</td>\r\n<td>понедельник - пятница с 09.00 до 18.00</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class="MsoNormal" style="text-align: center;" align="center">&nbsp;</p>', '', 1, 2, '2017-01-17 23:29:28', 42, '', '2017-02-22 11:17:00', 42, 42, '2019-04-15 12:57:52', '2017-01-17 18:41:28', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 7, 7, '', '', 1, 4950, '', 0, '*', ''),
(182, 286, 'Практические вопросы и новшества в налогообложении ', 'аттестат-профессионального-бухгалтера-2', '<h1>Практические вопросы и новшества в налогообложении 40 часов</h1>\r\n<p style="margin: 10px 0px 20px; padding: 0px; text-align: justify; color: #351e07; font-family: Pro; font-size: 14px; line-height: normal;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong style="margin: 0px; padding: 0px;"><span style="margin: 0px; padding: 0px;">Целевая аудитория:&nbsp;</span></strong>бухгалтер, зам. гл. бухгалтера, &nbsp;главный бухгалтер, экономист, финансовый директор</span></p>\r\n<p class="MsoNormal" style="color: #333333; font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; line-height: 15.808px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><b>Ведущие:</b></span></p>\r\n<p class="MsoNormal" style="color: #333333; font-family: Tahoma, Helvetica, Arial, sans-serif; font-size: 12.16px; line-height: 15.808px;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><a href="index.php?option=com_content&amp;view=article&amp;id=159&amp;catid=11&amp;Itemid=170">Сокол Маргарита Геннадьевна</a> - главный государственный налоговый инспектор<br /></span><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><a href="index.php?option=com_content&amp;view=article&amp;id=160&amp;catid=11&amp;Itemid=170">Прокопьева Зоя Александровна </a> - главный государственный налоговый инспектор</span></p>\r\n<p style="text-align: center;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><a href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<p class="MsoNormal" style="text-align: center;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><b>В ПРОГРАММЕ:</b></span></p>\r\n<p class="MsoNormal" style="text-align: justify;">&nbsp;</p>\r\n<h1 style="text-align: center;">&nbsp;</h1>\r\n<p style="text-align: center;"><iframe width="560" height="315" src="https://www.youtube.com/embed/JJsXO-DpAh0" frameborder="0" allowfullscreen="allowfullscreen" data-link="https://www.youtube.com/watch?v=JJsXO-DpAh0"></iframe></p>\r\n<p style="text-align: center;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>ВЫ НАУЧИТЕСЬ:</strong></span></p>\r\n<table style="width: 812px;">\r\n<tbody>\r\n<tr>\r\n<td style="width: 433px;">\r\n<ul>\r\n<li>Разрешать&nbsp;и понимать&nbsp;сложные&nbsp;вопросы&nbsp;НКРФ, критерии налоговых проверок&nbsp;&nbsp;</li>\r\n</ul>\r\n</td>\r\n<td style="width: 365px;">\r\n<ul>\r\n<li>Предупреждать типичные ошибки при ведении налогового учета</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 433px;">\r\n<ul>\r\n<li>&nbsp;Инструменты работы с руководителем,&nbsp; в&nbsp;условиях легализации доходов и расходов. Как нельзя оптимизировать?</li>\r\n</ul>\r\n</td>\r\n<td style="width: 365px;">\r\n<ul>\r\n<li>Научитесь&nbsp;разбираться в&nbsp; сложностях налоговой&nbsp; и бухгалтерской отчетности</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p style="text-align: center;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><a href="#zakaz" rel="alternate">СОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 49%; height: 15px;" colspan="2"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><b>В ПРОГРАММЕ&nbsp;&nbsp;</b></span></td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.0299%; height: 15px;">\r\n<p><span style="font-size: 10pt;"><strong><span style="font-family: arial, helvetica, sans-serif;">1. Новшества в бухгалтерском и налоговом законодательстве</span></strong></span></p>\r\n</td>\r\n<td style="width: 36.9701%; height: 15px;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>1)</strong>&nbsp;Новое в законодательстве о бухгалтерском учете, сложности и требования к бухгалтерской отчетности,&nbsp;профстандарт бухгалтера<br /></span><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>2)</strong>&nbsp;Новое в налоговом законодательстве&nbsp;<br /></span><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>3)</strong>&nbsp;Учетная политика в целях бухгалтерского и налогового учета<br /></span><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>4)</strong>&nbsp;Налоговые проверки налогоплательщиков, прогнозы и критерии для проверки</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 12.0299%; height: 15px;">&nbsp;</td>\r\n<td style="width: 36.9701%; height: 15px;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.0299%; height: 15px;">\r\n<p><span style="font-size: 10pt;"><strong><span style="font-family: arial, helvetica, sans-serif;">2. Налог на добавленную стоимость</span></strong></span></p>\r\n</td>\r\n<td style="width: 36.9701%; height: 15px;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>1)</strong>&nbsp;Сложности вопросы, льготы и оптимизация Налога на добавленную стоимость,</span><br /><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>2)</strong>&nbsp;Выгодные и невыгодные поправки&nbsp; по НДС &nbsp;</span><br /><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>3)</strong>&nbsp;Порядок начисления НДС при выполнении работ, условия принятия импортного НДС к вычету, раздельный учет НДС, &nbsp;НДС и утрата имущества, вычеты СМР и капитальное строительство</span><br /><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>4)&nbsp;</strong>Арбитражная практика по НДС от Верховного суда РФ</span><br /><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">- &nbsp;Сложные&nbsp;и спорные вопросы налогового учета</span><br /><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">- &nbsp;Заполнение налоговых деклараций</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 12.0299%; height: 15px;">&nbsp;</td>\r\n<td style="width: 36.9701%; height: 15px;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.0299%; height: 15px;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>3. Налог на прибыль организаций</strong></span></p>\r\n</td>\r\n<td style="width: 36.9701%; height: 15px;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>1)</strong>&nbsp;Обоснованность расходов. Налоговая выгода. Методы и сложные вопросы.<br /><strong>2) Налоговые проверки. Критерии и сложные ситуации</strong><br /><strong>3)</strong>&nbsp;Налоговые риски при работе с взаимозависимым лицам<br /><strong>4)</strong>&nbsp;Льготы по налогу на прибыль, легальная оптимизация<br /><strong>5)</strong>&nbsp;Внереализационные доходы и расходы. Безвозмездно полученное имущество, списание кредиторской&nbsp; задолженности, излишки и недостачи ТМЦ<br /><strong>6)</strong>&nbsp;Объекты основных средств, спорные и актуальные вопросы учета<br /><strong>7)</strong>&nbsp;Сложные вопросы и Арбитражная практика по налогу на прибыль от Верховного суда РФ<br /><i>- &nbsp;Сложные&nbsp;и спорные вопросы налогового учета<br />- &nbsp;Заполнение налоговых деклараций</i></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 12.0299%; height: 15px;">&nbsp;</td>\r\n<td style="width: 36.9701%; height: 15px;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.0299%; height: 15px;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>4. Налог на имущество организаций</strong></span></p>\r\n</td>\r\n<td style="width: 36.9701%; height: 15px;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>1)</strong>&nbsp;Новое в налогообложении по налогу на имущество организаций<br /></span><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>2)</strong>&nbsp;Спорные вопросы налогообложения по налогу на имущество<br /></span><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>3)</strong>&nbsp;Порядок уплаты налога, исчисляемого исходя из кадастровой стоимости<br /></span><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>4)</strong>&nbsp;Разъяснения Минфина РФ, ФНС РФ по налогу на имущество<br /></span><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>5)</strong>&nbsp;Сложные вопросы и Арбитражная практика по налогу на имущество от Верховного суда РФ&nbsp;<br /><i>- &nbsp;Сложные&nbsp;и спорные вопросы налогового учета<br />- &nbsp;Заполнение налоговых деклараций</i>&nbsp;<br /></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 12.0299%; height: 15px;">&nbsp;</td>\r\n<td style="width: 36.9701%; height: 15px;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.0299%; height: 15px;">\r\n<p><span style="font-size: 10pt;"><strong><span style="font-family: arial, helvetica, sans-serif;">5.Налог на доходы физических лиц</span></strong></span></p>\r\n</td>\r\n<td style="width: 36.9701%; height: 15px;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>1)</strong>&nbsp;Новое в налогообложении по&nbsp;НДФЛ<br /></span><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>2)</strong>&nbsp;Льготы по налогообложению&nbsp;<br /></span><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>3)</strong>&nbsp;Спорные вопросы налогообложения,&nbsp;уплаты налога<br /></span><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>4)</strong>&nbsp;Разъяснения Минфина РФ, ФНС РФ по налогу&nbsp;<br /></span><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>5)</strong>&nbsp;Арбитражная практика по налогу от Верховного суда РФ&nbsp;<br /></span><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>6)</strong>&nbsp;Стандартные, социальные и имущественные вычеты<br /><i>- &nbsp;Сложные&nbsp;и спорные вопросы налогового учета<br />- &nbsp;Заполнение налоговых деклараций</i>&nbsp;<br /></span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 12.0299%; height: 15px;">&nbsp;</td>\r\n<td style="width: 36.9701%; height: 15px;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.0299%; height: 15px;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>6.Транспортный налог, Акциз, НДПИ, Водный, Земельный<br />7.Страховые взносы<br /></strong></span></p>\r\n</td>\r\n<td style="width: 36.9701%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>1)</strong>&nbsp;Изменения, льготы, легальные схемы оптимизации, типичные ошибки по налогам&nbsp;<br /></span><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>2)&nbsp;</strong>Оптимизация и льготы по страховым взносам.&nbsp;Спорные вопросы<br /></span><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>3)&nbsp;</strong>Страховые взносы с индивидуальных предпринимателей</span></p>\r\n<p><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><i>- &nbsp;Сложные&nbsp;и спорные вопросы налогового учета<br />- &nbsp;Заполнение налоговых деклараций</i>&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #ffffff;">\r\n<td style="width: 12.0299%; height: 15px;">&nbsp;</td>\r\n<td style="width: 36.9701%; height: 15px;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.0299%; height: 15px;">\r\n<p><span style="font-size: 10pt;"><strong><span style="font-family: arial, helvetica, sans-serif;">8.Налоговое планирование</span></strong></span></p>\r\n</td>\r\n<td style="width: 36.9701%; height: 15px;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>1)</strong>&nbsp;Налоговое планирование как часть бизнеса. Задачи, цели, этапы налогового планирования. &nbsp;Налоговая схема и налоговая выгода выгода<br /></span><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>2)</strong>&nbsp;Расходы, связанные с реализацией товаров, работ, услуг. Транспортные расходы. Внереализационные расходы. Аренда. Рекламные расходы. Цена договора. Взаимозависимость<br /></span><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>3)</strong>&nbsp;Оптимизация на специальных налоговых режимах. Разделение расходов, НДС при совмещение со спецрежимом. Плюсы и минусы индивидуальных предпринимателей</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 12.0299%; height: 15px;">&nbsp;</td>\r\n<td style="width: 36.9701%; height: 15px;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.0299%; height: 15px;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><b>9. Анализ финансовой отчётности&nbsp;</b></span></td>\r\n<td style="width: 36.9701%; height: 15px;">\r\n<p><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>1)</strong>&nbsp;Анализ бухгалтерского баланса&nbsp;<br /></span><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>2)</strong>&nbsp;Анализ доходов, расходов и финансовых результатов деятельности организации&nbsp;&nbsp;<br /></span><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>3)</strong>&nbsp;Анализ изменения капитала и оценка финансовой устойчивости организации&nbsp;&nbsp;<br /></span><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>4)</strong>&nbsp;Анализ движения денежных средств и оценка платежеспособности организации&nbsp;<br /></span><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>5)</strong>&nbsp;Анализ консолидированной финансовой отчётности&nbsp;&nbsp;</span><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">&nbsp;<br /></span><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>6)</strong>&nbsp;Состав пояснений и дополнений к отчётности&nbsp;&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 12.0299%; height: 15px;">&nbsp;</td>\r\n<td style="width: 36.9701%; height: 15px;">&nbsp;</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 12.0299%; height: 15px;">\r\n<p><span style="font-size: 10pt;"><strong><span style="font-family: arial, helvetica, sans-serif;">10. АУДИТ И ГРАЖДАНСКОЕ ПРАВО<span style="box-sizing: inherit; margin: 0px; padding: 0px;"><span style="box-sizing: inherit; margin: 0px; padding: 0px; font-weight: bold;">&nbsp;</span></span></span></strong></span></p>\r\n</td>\r\n<td style="width: 36.9701%; height: 15px;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>1)</strong>&nbsp;Критерии проведения аудиторских проверок<br /></span><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>2)</strong>&nbsp;Методология проверок,&nbsp;аудиторское заключение<br /></span><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>3)</strong>&nbsp;Основы составления &nbsp;договоров, обязательные условия</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>Продолжительность</strong>&nbsp;- 6 недель.&nbsp;&nbsp; Расписание: воскресенье с 09.00 до 13.45.&nbsp;</span><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">Для иногородних есть возможность пройти курсы дистанционного обучения.&nbsp;&nbsp;<span style="color: #800000; font-family: ''arial black'', sans-serif;"><a style="color: #800000;" href="#call_me" rel="{size:{x:460,y:130}}"><strong>ОТПРАВИТЬ ЗАЯВКУ</strong></a></span></span></p>\r\n<p style="margin: 10px 0px 20px; padding: 0px; text-align: justify; color: #351e07; font-family: Pro; font-size: 14px; line-height: normal;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><span style="margin: 0px; padding: 0px;"><strong style="margin: 0px; padding: 0px;">Скидка 10 %</strong></span>&nbsp;при оплате<strong style="margin: 0px; padding: 0px;">&nbsp;за 4&nbsp;недели до обучения.</strong>&nbsp; &nbsp;</span><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong style="margin: 0px; padding: 0px;"><span style="margin: 0px; padding: 0px;">Скидка 5%&nbsp;&nbsp;</span></strong>при оплате&nbsp;<strong>за 2&nbsp; недели до начала обучения. Зачет 40 часов для профессиональных бухгалтеров.</strong></span>&nbsp;</p>', '', 1, 11, '2017-03-28 11:09:47', 42, '', '2018-06-20 06:59:23', 42, 0, '0000-00-00 00:00:00', '2017-03-28 11:13:21', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 5, 23, 'новшества в налогообложении, новости в налогах 2018, новации налоги 2018', 'Новшества в налогообложении на 2018 год, Программа повышения квалификации по налогам 40 часов', 1, 2537, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(204, 401, 'Дистанционные курсы интернет - маркетинга', 'дистанционные-курсы-интернет-маркетинга', '<h1 style="text-align: center;">Дистанционные курсы интернет - маркетинга и продвижения сайтов</h1>\r\n<p>Дистанционное обучение интернет-маркетингу ориентировано на&nbsp;предпринимателей, владельцев и со-владельцев малого&nbsp;бизнеса, фрилансеров, начинающих маркетологов, pr- и smm-специалистов.&nbsp;</p>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>Формат обучения:</strong></span> видео-лекции с живых занятий, практические задания, обратная связь от преподавателя.</p>\r\n<p style="text-align: center;"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>В&nbsp;РЕЗУЛЬТАТЕ ОБУЧЕНИЯ ВЫ:</strong></span></p>\r\n<table style="width: 96.2687%;">\r\n<tbody>\r\n<tr style="height: 60px;">\r\n<td style="width: 44.778%; height: 60px;">\r\n<ul>\r\n<li>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Научитесь&nbsp;<strong>самостоятельно</strong>&nbsp;работать со всеми наиболее&nbsp;<strong>востребованными инструментами интернет-маркетинга</strong></span></p>\r\n</li>\r\n</ul>\r\n</td>\r\n<td style="width: 47.222%; height: 60px;">\r\n<ul>\r\n<li>\r\n<p><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">Узнаете,&nbsp;<strong>как сделать ваш сайт "продающим"</strong>, а также&nbsp;<strong>поднять его в ТОП</strong>&nbsp;поисковых систем&nbsp;Яндекс и Google</span></p>\r\n</li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr style="height: 60px;">\r\n<td style="width: 44.778%; height: 60px;">\r\n<ul>\r\n<li>\r\n<p><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><strong>Оптимизируйте расходы</strong>&nbsp;на интернет-продвижение</span></p>\r\n</li>\r\n</ul>\r\n</td>\r\n<td style="width: 47.222%; height: 60px;">\r\n<ul>\r\n<li><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Научитесь грамотно настраивать<strong>&nbsp;эффективные рекламные кампании в Яндекс Директ и&nbsp;<span lang="EN-US">Google</span>&nbsp;<span lang="EN-US">Adwords</span></strong><br /></span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr style="height: 76px;">\r\n<td style="width: 44.778%; height: 76px;">\r\n<ul>\r\n<li><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">Освоите&nbsp;<strong>бесплатные</strong>&nbsp;и&nbsp;<strong>малобюджетные способы продвижения</strong>&nbsp;в интернете</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 47.222%; height: 76px;">\r\n<ul>\r\n<li><span style="font-family: arial, helvetica, sans-serif;"><span style="font-size: 13.3333px;">Узнаете, как пользоваться системами&nbsp;<strong>Яндекс Метрика&nbsp;</strong>и<strong>&nbsp;Google Analytics</strong>&nbsp;&nbsp;и использовать их данные для эффективного продвижения</span></span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr style="height: 20.3438px;">\r\n<td style="width: 44.778%; height: 20.3438px;">\r\n<ul>\r\n<li><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">Узнаете, что такое<strong>&nbsp;ретаргетинг</strong>&nbsp;и как его использовать</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 47.222%; height: 20.3438px;">\r\n<ul>\r\n<li><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">Научитесь настраивать т<strong>аргетированную рекламу в социальных сетях VKontakte, Facebook</strong>, а также запускать рекламу в&nbsp;<strong>Instagram</strong></span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="width: 44.778%; height: 15px;">\r\n<ul>\r\n<li><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;">Получите советы по&nbsp;<strong>продвижению вашего бизнеса</strong>&nbsp;от одного из ведущих экспертов-практиков Екатеринбурга</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 47.222%; height: 15px;">&nbsp;</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p style="text-align: center;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><a onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<p style="text-align: center;"><iframe src="https://www.youtube.com/embed/D_xXNiGbTlA" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen" data-link="https://www.youtube.com/watch?v=D_xXNiGbTlA"></iframe></p>\r\n<p style="text-align: center;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>ПРОГРАММА КУРСА</strong></span></p>\r\n<table>\r\n<tbody>\r\n<tr>\r\n<td style="background-color: #f3f3f3;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>1. SEO&nbsp;(поисковое) продвижение</strong></span></p>\r\n</td>\r\n<td style="background-color: #f3f3f3;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>1)</strong>&nbsp;Базовые аспекты интернет-маркетинга.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">- Аудитория интернета. Тенденции поведения пользователей в Интернете.</span><br /><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">- Обзор направлений интернет-маркетинга.</span><br /><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">- Что такое целевая аудитория в интернет-маркетинге. &nbsp;Ее определение. Использование основных сервисов аналитики и статистики.&nbsp;</span><br /><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">- Сайт компании как основной инструмент продвижения. Виды сайтов и их отличия. Необходимые элементы структуры сайта.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>2)</strong>&nbsp;Индексация сайта.&nbsp;Семантическое ядро сайта. Написание контента и ключевых слов</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>3)</strong>&nbsp;Как вывести сайт на ведущие позиции: поисковое ранжирование, грамотное составление текстов.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>4)</strong>&nbsp;Работа со&nbsp;статьями и биржами ссылок.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>5)</strong>&nbsp;Как избежать блокировки со стороны поисковых систем. Особенности Яндекс и&nbsp;Google&nbsp;Adwords.</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"></span></td>\r\n<td><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"></span></td>\r\n</tr>\r\n<tr>\r\n<td style="background-color: #f3f3f3;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>2. Контекстная реклама</strong></span></p>\r\n</td>\r\n<td style="background-color: #f3f3f3;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>1)</strong>&nbsp;Работа с системами Яндекс Директ и&nbsp;Google. Контекстная, тематическая и медийная реклама. Их достоинства и недостатки.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>2)</strong>&nbsp;Подбор эффективных ключевых слов.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>3)</strong>&nbsp;Грамотное составление рекламной кампании. Работа с дополнительными возможностями.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Настройка реальной рекламной кампании для вашей компании.</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"></span></td>\r\n<td><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"></span></td>\r\n</tr>\r\n<tr>\r\n<td style="background-color: #f3f3f3;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>3. Веб-аналитика. Работа с Яндекс Метрикой</strong></span></p>\r\n</td>\r\n<td style="background-color: #f3f3f3;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>1)&nbsp;</strong>Основные принципы веб-аналитики.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>2) &nbsp;</strong>Изучение счетчика Яндекс Метрики.&nbsp;</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Практика построения отчетов в Яндекс Метрика.</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"></span></td>\r\n<td><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"></span></td>\r\n</tr>\r\n<tr>\r\n<td style="background-color: #f3f3f3;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>4.SMM-продвижение</strong></span></p>\r\n</td>\r\n<td style="background-color: #f3f3f3;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>1)</strong>&nbsp;Социальные сети: основные тенденции развития. В каких случая стоит использовать для продвижения.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>2)</strong>&nbsp;Facebook: возможности продвижения. Настройка разных типов рекламных кампаний.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>3)</strong>&nbsp;VKontakte: возможности продвижения. &nbsp;Работа с дополнительными возможностями.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>4)</strong>&nbsp;Instagram:&nbsp; возможности продвижения. Настройка рекламной кампании. &nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"></span></td>\r\n<td><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"></span></td>\r\n</tr>\r\n<tr>\r\n<td style="background-color: #f3f3f3;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>5. E-mail-маркетинг</strong></span></p>\r\n</td>\r\n<td style="background-color: #f3f3f3;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>1)</strong>&nbsp;Как сформировать базу электронных рассылок. Способы сбора данных, законодательная база. Стратегии сегментирования клиентской базы.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>2)</strong>&nbsp;Основные сервисы электронных рассылок. Их преимущества и недостатки.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>3)</strong>&nbsp;Создание и отправка&nbsp; электронных рассылок. Грамотный подбор контента.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>4)</strong>&nbsp;Повышение открываемости и читаемости электронных рассылок.</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"></span></td>\r\n<td><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"></span></td>\r\n</tr>\r\n<tr>\r\n<td style="background-color: #f3f3f3;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>6. Продвижение видео-контента</strong></span></p>\r\n</td>\r\n<td style="background-color: #f3f3f3;">\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>1)</strong>&nbsp;Основные виды видео-контента и их предназначение.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>2)</strong>&nbsp;Работа с видео-каналом Youtube.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>3)</strong>&nbsp;Особенности работы с видео-контентом на&nbsp;Facebook&nbsp;и в VKontakte.</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>Продолжительность: </strong>3 недели.</span></p>\r\n<table style="width: 932px;">\r\n<tbody>\r\n<tr>\r\n<td style="text-align: left; width: 922px;" colspan="2"><span style="font-size: 10pt; color: #800000;"><strong><span style="font-family: arial, helvetica, sans-serif;">ВЕДУЩИЙ КУРСА: &nbsp; ЛОПАТИН ВИТАЛИЙ ВЯЧЕСЛАВОВИЧ</span></strong> </span></td>\r\n</tr>\r\n<tr>\r\n<td style="width: 134px;">\r\n<p>&nbsp;<img style="display: block; margin-left: auto; margin-right: auto;" src="images/Lopatin_VV.jpg" alt="" width="94" height="120" /></p>\r\n</td>\r\n<td style="width: 788px;">\r\n<p><span style="font-size: 10pt;"><strong><span style="font-family: arial, helvetica, sans-serif;">Специалист в области интернет-коммуникаций&nbsp;</span></strong> </span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">- Более 8 лет опыта работы в интернет-маркетинге и IT-технологиях, реализовано более 300 успешных проектов по поисковой оптимизации, контекстной рекламе и smm-продвижению.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">- Более 10 лет опыта работы в маркетинге.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">- Более 7&nbsp;лет&nbsp;- руководитель компании, предоставляющей услуги в сфере интернет-маркетинга и IT.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><strong>В числе клиентов:</strong>&nbsp;Уральский банк реконструкции и развития, West Call, Региональная трубная компания, Гардиан, Урал Шталь, служба доставки "Пицца Сан", группа компаний "Элеком", УралПак, строительная компания "АСК-Строй", дачный поселок "Красная поляна", ДИА-Строй.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"></span></p>\r\n<p><span style="font-size: 10pt;"><strong><span style="font-family: arial, helvetica, sans-serif;">Высшее образование:</span></strong> </span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">2005 г. - УГТУ-УПИ, "Экономика и управление предприятием"</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Дополнительное образование:&nbsp;</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">2008 - 2016 гг. - вебинары и семинары по продвижению Яндекс - Директ,&nbsp;Google AdWords и другие</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">2009 г.&nbsp;- Повышение квалификации&nbsp;«HTML программирование»</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">2008&nbsp;г. - Тренинг «Малобюджетное продвижение товаров и услуг»&nbsp;</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">2007 г. - Тренинг «Лидер продаж»</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">2006 г. - Повышение квалификации&nbsp;«Маркетинг и организационно-у<wbr />правленческое планирование»</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"></span></p>\r\n<p><span style="font-size: 10pt;"><strong><span style="font-family: arial, helvetica, sans-serif;">Трудовая деятельность:</span></strong> </span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">С&nbsp;2009 г. - по настоящее время - руководитель компании&nbsp;"Апдейт", специализирующейся на интернет-продвижении и it-технологиях.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">2008 - 2009 гг. - специалист по маркетингу ООО “Стройгеотехника<wbr />”, реклама и маркетинг в сегменте B2B.</span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">2006 - 2008 гг. - руководитель отдела маркетинга ГП “ПромСредМаш”. Маркетинговые исследования, реклама, разработка стратегии и планирование маркетинговой деятельности машиностроительн<wbr />ых предприятий, входящих в группу.</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>', '', 1, 26, '2017-10-25 07:29:47', 42, '', '2019-04-12 11:35:11', 42, 0, '0000-00-00 00:00:00', '2017-10-25 07:29:47', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 15, 4, 'Дистанционное обучение интернет-маркетингу, онлайн курсы продвижения сайтов', 'Обучение интернет-маркетингу дистанционно по доступной цене за 7 занятий. Стоимость 13 900 руб.', 1, 2639, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(156, 257, 'Финансово - хозяйственная деятельность', 'финансово-хозяйственная-деятельность', '<p>Финансово - хозяйственная деятельность</p>\r\n<p><a href="images/finan-hoz.pdf" rel="alternate">Отчет о целевом использовании за 2015 год</a></p>', '', 1, 2, '2017-01-23 23:46:22', 42, '', '2017-01-23 18:50:13', 42, 42, '2019-04-16 04:52:29', '2017-01-23 18:50:13', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 2, 4, '', '', 1, 3299, '', 0, '*', ''),
(159, 260, 'Сокол Маргарита Геннадьевна', 'сокол-маргарита-геннадьевна', '<h1 style="text-align: center;"><span style="font-family: Pro;">Сокол Маргарита Геннадьевна</span></h1>\r\n<table style="width: 93.177%;">\r\n<tbody>\r\n<tr style="height: 136.438px;">\r\n<td style="height: 136.438px; width: 10.2294%;"><span style="font-family: Pro;"><img src="images/Sokol_Margarita-min.jpg" alt="преподаватель по налогообложению" width="93" height="122" /></span></td>\r\n<td style="height: 136.438px; width: 75.7706%;">\r\n<p><span style="font-family: Pro;">Главный государственный налоговый инспектор.</span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;"><strong>Более 10 лет </strong></span>преподавательской деятельности.</span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;"><strong>25 летний опыт</strong></span> работы по специализации&nbsp;</span></p>\r\n<p><span style="font-family: Pro;">Автор программ и методических материалов по налогообложению.&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="height: 15px; width: 86%;" colspan="2">\r\n<p><span style="font-family: Pro; color: #800000;"><strong>Образование высшее:</strong></span></p>\r\n<p><span style="font-family: Pro;">2001 г. - Российская экономическая академия им. Плеханова, Финансы и кредит, экономист.&nbsp;</span></p>\r\n<p><span style="font-family: Pro;">1984 г. - Уральский ордена Трудового Красного Знамени&nbsp; политехнический институт им.С.М.Кирова, &nbsp;инженер.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro; color: #800000;"><strong>Образование дополнительное:&nbsp;</strong></span></p>\r\n<p><span style="font-family: Pro;">2016 г. Педагогика и методика обучения, повышение квалификации г. Екатеринбург</span></p>\r\n<p><span style="font-family: Pro;">2016 г. Возмещение НДС. Доказательство отказов при возмещении НДС, Приволжский институт повышения квалификации ФНС России. &nbsp; &nbsp; &nbsp;</span></p>\r\n<p><span style="font-family: Pro;">2014 г. Налогообложение прибыли организаций,&nbsp;Северо-Западный институт повышения квалификации ФНС России.&nbsp;</span></p>\r\n<p><span style="font-family: Pro;">2009 г. Основы налогового администрирования. Администрирование налогов, исчисляемых налоговыми органами (Транспортный налог с организаций. Земельный налог с организаций. Налог на имущество организаций), Центр подготовки персонала ФНС России в г. Санкт-Петербург.</span></p>\r\n<p><span style="font-family: Pro;">2011 г. Налогообложение юридических лиц,&nbsp;Центр подготовки персонала ФНС России в г. Санкт-Петербург.&nbsp;</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro; color: #800000;"><strong>Трудовая деятельность:</strong></span></p>\r\n<p><span style="font-family: Pro;">1994 г. - по настоящее время - главный государственный&nbsp;налоговый инспектор Отдела выездных проверок ФНС.</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>', '', 1, 11, '2017-02-03 11:12:53', 42, '', '2019-04-26 09:53:49', 42, 0, '0000-00-00 00:00:00', '2017-02-21 04:35:09', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 30, 21, '', '', 1, 3816, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(158, 259, 'Образование', 'образование', '<h1>Образовательные программы</h1>\r\n<p>Образовательная программа Финансы предприятия<a href="images/op_finans.pdf" rel="alternate"> скачать</a>&nbsp;</p>\r\n<p>Образовательная программа Экономика предприятия, финансовый анализ<a href="images/op_ekonomica_finans.pdf" rel="alternate">&nbsp;скачать</a>&nbsp;</p>\r\n<p>Образовательная программа Бюджетирование, как система управления +&nbsp;Excel&nbsp;<a href="images/op_budget.pdf" rel="alternate">скачать</a>&nbsp;</p>\r\n<p>Образовательная программа Бизнес - планирование инвестиционных проектов &nbsp;<a href="images/op_bisnes_plan.pdf" rel="alternate">скачать</a>&nbsp;</p>\r\n<p>Образовательная программа Бухгалтерский учет, налоги +1 С: Бухгалтерия 8.3&nbsp;<a href="images/op_buhgalter.pdf" rel="alternate">&nbsp;скачать</a></p>\r\n<p>Образовательная программа Налоги, бухгалтерская и налоговая отчетность, 1: С Бухгалтерия 8.3&nbsp;<a href="images/nalogi_otchetnost_1C.pdf" rel="alternate">&nbsp;скачать</a></p>\r\n<p>Образовательная программа Контрактная система в сфере закупок, 44 ФЗ&nbsp;<a href="images/op_44fz.pdf" rel="alternate">скачать</a></p>\r\n<p>Образовательная программа Контрактная система в сфере закупок, 44 ФЗ, 223 ФЗ&nbsp;<a href="images/op_44223fz.pdf" rel="alternate">скачать</a></p>\r\n<p>Образовательная программа Сметное дело, Гранд - Смета <a href="images/op_smeta.pdf" rel="alternate">скачать</a></p>\r\n<p>Образовательная программа Специалист по кадрам&nbsp;<a href="images/op_kadry1.pdf" rel="alternate">скачать</a></p>\r\n<p>Образовательная программа HR менеджмент&nbsp;<a href="images/op_HR.pdf" rel="alternate">скачать</a>&nbsp;</p>\r\n<p>Образовательная программа Маркетинг и продвижение&nbsp;<a href="images/up_marketing.pdf" rel="alternate">скачать</a>&nbsp;</p>\r\n<p>Образовательная программа Стратегия, тактика и операционное управление&nbsp;<a href="images/op_strateg.pdf" rel="alternate">скачать</a>&nbsp;</p>\r\n<p>Образовательная программа Управление закупками и запасами&nbsp;<a href="images/op_zakupki_u_zapas.pdf" rel="alternate">скачать</a>&nbsp;</p>\r\n<p>Образовательная программа Транспортная и складская логистика&nbsp;<a href="images/op_logistika.pdf" rel="alternate">скачать</a>&nbsp;</p>\r\n<p>Образовательная программа Специалист по документационному и организационному обеспечению&nbsp;<a href="images/op_sekretar.pdf" rel="alternate">скачать</a>&nbsp;</p>\r\n<p>Образовательная программа Менеджер по продажам&nbsp;<a href="images/op_prodazhi.pdf" rel="alternate">скачать</a></p>\r\n<p>Образовательная программа диплом Контрактная система в сфере закупок, 44 ФЗ&nbsp;<a href="images/specialist_po_zakupkam_44fz.pdf" rel="alternate">скачать</a></p>\r\n<p>Образовательная программа диплом Бухгалтер&nbsp;- экономист&nbsp;<a href="images/diplom_buhgalter.pdf" rel="alternate">&nbsp;скачать</a></p>\r\n<p>Образовательная программа диплом Управление экономикой на предприятии</p>\r\n<p>Образовательная программа диплом Трудовое право и кадровое делопроизводство на предприятии&nbsp;<a href="images/diplom_kadry.pdf" rel="alternate">скачать</a></p>\r\n<p>Образовательная программа диплом Специалист по документационному и организационному обеспечению&nbsp;<a href="images/diplom_sekretar1.pdf" rel="alternate">скачать</a>&nbsp;</p>\r\n<p>Образовательная программа диплом Менеджер по персоналу&nbsp;<a href="images/diplom_upravlenie_personall.pdf" rel="alternate">скачать</a>&nbsp;</p>\r\n<p>&nbsp;</p>', '', 1, 17, '2017-02-02 21:11:25', 42, '', '2018-11-27 13:47:47', 42, 0, '0000-00-00 00:00:00', '2017-02-02 16:13:40', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 51, 6, '', '', 1, 7401, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(148, 247, 'Курсы транспортной логистики. Грузоперевозки обучение', 'обучение-на-логиста-по-транспорту', '<h1 class="MsoNormal"><span style="font-family: Pro;">Обучение транспортной логистике в {city_d}. Курсы по грузоперевозкам</span></h1>\r\n<p style="text-align: center;"><span style="font-family: Pro;">{img; /images/obuchenie_transportnaya_logistika3.jpg; /images/obuchenie_transportnaya_logistika2.jpg; /images/obuchenie_transportnaya_logistika.jpg; Обучение по транспорту, курсы транспортной логистики}</span></p>\r\n<p><span style="font-family: Pro;"><span style="font-size: 10pt;"><strong>Целевая аудитория:</strong>&nbsp;</span>логист, специалист организации перевозок, специалисты по закупкам, &nbsp;руководители отделов&nbsp;закупок, коммерческие директора.</span></p>\r\n<h2 style="text-align: center;"><span style="font-family: Pro; font-size: 10pt;"><strong>Пройдя наши курсы транспортной логистики, вы:</strong></span></h2>\r\n<table>\r\n<tbody>\r\n<tr>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Повысите доходность и конкурентоспособность бизнеса</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Оптимизируете общие затраты в цепи поставок и уровень запасов</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Сократите время поставок и повысите точность поставок</span></li>\r\n</ul>\r\n</td>\r\n<td style="width: 50%;">\r\n<ul>\r\n<li><span style="font-family: Pro;">Улучшите использование логистических мощностей</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p style="text-align: center;"><span style="font-family: Pro; font-size: 10pt;"><a onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro;">Выдается удостоверение по программе: "Транспортная логистика. Организация транспортно-логистической деятельности"</span></p>\r\n<p><span style="font-family: Pro;"><strong style="background-color: inherit; color: inherit; font-family: inherit; font-size: 1rem;"><a href="#"><img src="images/Udostoverenie_oblozhka.jpg" alt="обучение транспортная логистика" width="45%" height="261" />&nbsp;&nbsp;<img src="images/udostoverenie_transportnaya_logistika.jpg" alt="курсы по грузоперевозкам" width="45%" height="261" /></a></strong></span></p>\r\n<hr />\r\n<p><span style="font-family: Pro; font-size: 12pt;"><strong>Фрагмент обучения</strong></span></p>\r\n<p>&nbsp;</p>\r\n<p style="text-align: center;"><span style="font-family: Pro;"><iframe src="https://www.youtube.com/embed/UhFoP9AqCmQ" width="560" height="315" frameborder="0" allowfullscreen="allowfullscreen" data-link="https://www.youtube.com/watch?v=UhFoP9AqCmQ"></iframe></span></p>\r\n<hr />\r\n<p style="text-align: left;"><span style="font-family: Pro; font-size: 12pt;"><strong>Программа курса:</strong></span></p>\r\n<table>\r\n<tbody>\r\n<tr>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;"><b>1. Управление грузоперевозками</b></span></p>\r\n</td>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;">1) Показатели эффективности транспортной Службы. Практика</span></p>\r\n<p><span style="font-family: Pro;">2) Влияние целевых показателей транспортной Службы на операционные цели Компании.</span></p>\r\n<p><span style="font-family: Pro;">3) Выбор способа транспортировки и перевозчика грузов, ATI - инфосистема по грузоперевозкам.</span></p>\r\n<p><span style="font-family: Pro;">4) Критерии и методы оценки&nbsp; выбора перевозчика груза.</span></p>\r\n<p><span style="font-family: Pro;"><em>Практика</em></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 200px;">&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;"><b>2. Расчет, анализ, планирование, оптимизация транспортных расходов</b></span></p>\r\n</td>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;">1) Транспортные тарифы. Методы формирования цены и тарифа перевозки. Расчет маржинального дохода. Практика</span></p>\r\n<p><span style="font-family: Pro;">2) Основы типов и параметров: грузоподъемность, грузовместимость, габаритные размеры грузового отсека.</span></p>\r\n<p><span style="font-family: Pro;">3) Маршрутизация перевозок грузов</span></p>\r\n<p><span style="font-family: Pro;">4) Кросс-докинг, как путь оптимизации транспортных расходов.</span></p>\r\n<p><span style="font-family: Pro;">5) Плюсы и минусы перевозки на различных видах транспорта: морской, авиа, ж.д, авто</span></p>\r\n<p><span style="font-family: Pro;"></span></p>\r\n<p><span style="font-family: Pro;"><em>Практика: Определение потребности в транспорте и размеров транспорта&nbsp;</em></span></p>\r\n<p><span style="font-family: Pro;"><em>Практика:&nbsp; Маршрутизация перевозок грузов</em></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 200px;">&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;"><b>3. Организация грузовых перевозок в логистической системе</b></span></p>\r\n</td>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;">1) Организация грузовых перевозок собственным автотранспортом компании.</span></p>\r\n<p><span style="font-family: Pro;">2) Передача автомобильных перевозок грузов на аутсорсинг.&nbsp;</span></p>\r\n<p><span style="font-family: Pro;">3) Преимущества и недостатки собственного и наемного транспорта.&nbsp;</span></p>\r\n<p><span style="font-family: Pro;">4) Правовое регулирование транспортно-экспедиционной деятельности.</span></p>\r\n<p><span style="font-family: Pro;">5) Договорные правоотношения транспортно-экспедиционной деятельности. Твердые условия оформления договоров.</span></p>\r\n<p><span style="font-family: Pro;"><em>Практика</em></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 200px;">&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;"><b>4. Показатели эффективности транспортно - логистической деятельности</b></span></p>\r\n</td>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;">1) Контроль финансовых показателей:рентабельность перевозок, выполнение плана по прибыли.</span></p>\r\n<p><span style="font-family: Pro;">2) Система показателей эффективности работы автотранспортной службы компании, применение KPI для специалистов по логистике</span></p>\r\n<p><span style="font-family: Pro;">3) Бюджетирование транспортных расходов. Планирование бюджета. Практика</span></p>\r\n<p><span style="font-family: Pro;"><em>Практика:&nbsp; Рассчитываем показатели эффективности&nbsp;&nbsp;</em></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 200px;">&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;"><b>5. Развитие логистической деятельности</b></span></p>\r\n</td>\r\n<td style="background-color: #f5f5f5;">\r\n<p><span style="font-family: Pro;">1) Коммерческая политика и клиентский сервис в области оказания логистических услуг</span></p>\r\n<p><span style="font-family: Pro;">2) SWOT - анализ. Улучшение качества логистических услуг по перевозке груза&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<hr />\r\n<p><span style="font-size: 12pt; font-family: Pro;"><strong>Формат курса:</strong> </span></p>\r\n<p>&nbsp;</p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">•&nbsp;<strong>Очное обучение</strong>.&nbsp;Продолжительность -&nbsp;2&nbsp;дня: суббота-воскресенье&nbsp;с 09.00 до 17.00 + 2&nbsp;недели на выполнение самостоятельных работ на закрепление очного обучения, обратная связь от преподавателя. &nbsp;&nbsp;</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;">•&nbsp;<strong>Дистанционное обучение:</strong>&nbsp;Продолжительность: 3 недели,&nbsp;видео-лекции, аттестационные работы с обратной связью от преподавателя</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro;">Формы обучения:&nbsp;информационные модули, дискуссии, моделирование и анализ реальных ситуаций взаимодействия, практика.</span></p>\r\n<hr />\r\n<p><span style="font-family: Pro;">&nbsp;<strong><span style="font-size: 12pt;">Акции и скидки:</span></strong> </span></p>\r\n<p>&nbsp;</p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit; color: inherit; font-size: 1rem;">•&nbsp;</span>Скидка 10%&nbsp;при оплате за 4 недели до обучения.&nbsp;&nbsp;</span></p>\r\n<p style="padding-left: 30px;"><span style="font-family: Pro;"><span style="background-color: inherit; color: inherit; font-size: 1rem;">•&nbsp;</span>Скидка 5%&nbsp;при оплате за 2 недели до обучения.</span></p>\r\n<p>&nbsp;</p>\r\n<p style="text-align: center;"><span style="font-family: Pro;"><a onclick="ga(''send'', ''event'', ''knopka'', ''otpravit''); yaCounter15669946.reachGoal (''ostavitzayavky'');return true;" href="#zakaz" rel="alternate">ОСТАВИТЬ ЗАЯВКУ</a></span></p>\r\n<hr />\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 24.359%; height: 15px; text-align: center;"><span style="font-family: Pro;"><strong><span style="color: #800000;">ВЕДУЩИЙ&nbsp;</span></strong> </span></td>\r\n<td style="width: 71.641%; height: 15px;">\r\n<p style="text-align: center;"><span style="font-family: Pro;">&nbsp;<strong><span style="color: #800000;">НИКОЛАЕВ ВЛАДИМИР АРКАДЬЕВИЧ</span></strong> </span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px; background-color: #f5f5f5;">\r\n<td style="width: 24.359%; height: 15px; text-align: center;"><span style="font-family: Pro;"><img src="images/Nikolaev_VA.jpg" alt="" width="95" height="124" /></span></td>\r\n<td style="width: 71.641%; height: 15px;">\r\n<p><span style="font-family: Pro;">&nbsp;<span style="font-size: 10pt;"><strong>Эксперт-практик в сфере логистики&nbsp;</strong></span></span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">-&nbsp;Более 15 лет&nbsp;опыта работы в сфере управления транспортно - логистической деятельностью</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">-&nbsp;Более&nbsp;3&nbsp;лет&nbsp;преподавательской деятельности.&nbsp;</span></p>\r\n<p><span style="font-size: 10pt; font-family: Pro;"><strong>Директор по логистике, автор программ обучения:&nbsp;</strong></span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">- Управление закупками, оптимизация товарного ассортимента, складская логистика</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">- Управление и организация транспортно - логистической деятельности</span></p>\r\n<p><span style="font-family: Pro; font-size: 10pt;">- Переговоры с поставщиками</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>', '', 1, 27, '2016-12-27 08:18:14', 42, '', '2019-04-26 09:05:09', 42, 0, '0000-00-00 00:00:00', '2016-12-27 10:18:09', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 174, 10, 'курсы логистов, обучение на логиста, логист обучение, транспортная логистика обучение курсы', 'Курсы транспортной логистики. Очно и дистанционно. От эксперта практика. Грузоперевозки обучение. Скидки до 15% ', 1, 10546, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(149, 249, 'Попов Дмитрий Павлович', 'попов-дмитрий-павлович', '<h1><span style="font-family: Pro;">Попов Дмитрий Павлович</span></h1>\r\n<table style="width: 100%;">\r\n<tbody>\r\n<tr style="height: 106.594px;">\r\n<td style="width: 10%; height: 106.594px;">\r\n<p><span style="font-family: Pro;">&nbsp;<img src="images/popov_dmitri-2.jpg" alt="преподаватель по интернет маркетингу" width="104" height="137" /></span></p>\r\n</td>\r\n<td style="width: 82%; height: 106.594px;">\r\n<p><span style="font-family: Pro;"><strong><br />ЭКСПЕРТ ПРАКТИК&nbsp;В ОБЛАСТИ ИНТЕРНЕТ КОММУНИКАЦИЙ</strong></span></p>\r\n<p><span style="font-family: Pro;">- <strong>Более&nbsp;8 лет</strong> опыта работы в интернет-маркетинге</span></p>\r\n<p><span style="font-family: Pro;">- <strong>Более&nbsp;5&nbsp;лет</strong> опыта работы&nbsp; преподавателем и бизнес - тренером.</span></p>\r\n<p><span style="font-family: Pro;">- <strong>Более 3 лет&nbsp;</strong>- руководитель проектов&nbsp;в сфере интернет-маркетинга и it-технологий.&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 15px;">\r\n<td style="height: 15px; width: 92%;" colspan="2">\r\n<p><span style="font-family: Pro; color: #800000;"><strong>Высшее образование:</strong></span></p>\r\n<p><span style="font-family: Pro;">2005 - 2010&nbsp;г. - УАГС, Экономика и управление предприятием</span></p>\r\n<p><span style="font-family: Pro;">2010 - 2013 г. -&nbsp;УАГС, кандидат социологических наук</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro; color: #800000;"><strong>Дополнительное образование:&nbsp;</strong></span></p>\r\n<p><span style="font-family: Pro;">2010 - 2018 гг. - вебинары, семинары, блоги по продвижению SEO, Яндекс Директ,&nbsp;Google AdWords, SMM, копирайтинг</span></p>\r\n<p><span style="font-family: Pro;">2014 г. - Повышение квалификации&nbsp;«SEO для бизнеса»</span></p>\r\n<p><span style="font-family: Pro;">2013 г. - Тренинги «ТОП-Эксперт»&nbsp;</span></p>\r\n<p><span style="font-family: Pro;">2012 г. - Тренинги продаж&nbsp; и коммуникаций</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: Pro; color: #800000;"><strong>Трудовая деятельность:</strong></span></p>\r\n<p><span style="font-family: Pro;">С&nbsp;2017 г. по настоящее время -&nbsp; Руководитель Web-студии федеральной компании Первый Бит,&nbsp; специализирующейся на интернет-продвижении и it-технологиях.</span></p>\r\n<p><span style="font-family: Pro;">2015 - 2016 гг. - руководитель проектов создания с нуля интернет - магазинов: строительство, косметика, продукты</span></p>\r\n<p><span style="font-family: Pro;">2011&nbsp;- 2014&nbsp;гг. - предпринимательская деятельность&nbsp; в интернет маркетинге и продажах.&nbsp;Руководитель, интернет-маркетолог, SEO - специалист, копирайтер</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>', '', 1, 26, '2017-01-01 16:16:48', 42, '', '2019-04-26 09:55:54', 42, 0, '0000-00-00 00:00:00', '2017-01-01 16:30:44', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_tags":"","show_intro":"","info_block_position":"","info_block_show_title":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_associations":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","urls_position":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 106, 10, '', '', 1, 6608, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(161, 262, 'Изменения контрактная система 44 ФЗ с 2017 года ', 'изменения-с-2017-года-контрактная-система', '<h1>Изменения в контрактной системе с 2017 года контрактная система</h1>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>1.&nbsp;С 09.01.2017 ГОДА ИЗМЕНЕНЫ ЕДИНЫЕ ТРЕБОВАНИЯ К УЧАСТНИКАМ ЗАКУПКИ И, СООТВЕТСТВЕННО, ТРЕБОВАНИЯ К ПРЕДСТАВЛЯЕМОЙ УЧАСТНИКОМ ДЕКЛАРАЦИИ О СООТВЕТСТВИИ ТАКИМ ТРЕБОВАНИЯМ</strong></span></p>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>- &nbsp;Изложен в новой редакции пункт 7 части 1 статьи 31 Закона № 44-ФЗ о контрактной системе в сфере закупок.</strong></span></p>\r\n<p>Указанной нормой закона установлены требования к участникам закупок, в частности об отсутствии у них (их должностных лиц) судимости за преступления в сфере экономики (за исключением лиц, у которых такая судимость погашена или снята), а также о неприменении в отношении указанных лиц наказания в виде лишения права занимать определённые должности или заниматься определённой деятельностью, которые связаны с поставкой товара, выполнением работы, оказанием услуги, являющихся объектом осуществляемой закупки, и административного наказания в виде дисквалификации.</p>\r\n<p>Этим федеральным законом&nbsp;устанавливается также требование об отсутствии у указанных лиц судимости за незаконное участие в предпринимательской деятельности, получение взятки, дачу взятки и посредничество во взяточничестве (статьи 289&ndash;291.1 Уголовного кодекса Российской Федерации).</p>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>- &nbsp;Вводится новое требование об участии в закупке только юридических лиц, ранее не привлекавшихся к административной ответственности за незаконное вознаграждение от имени юридического лица (статья 19.28 Кодекса Российской Федерации об административных правонарушениях).</strong></span></p>\r\n<p>Данное требование установлено путём включения &nbsp;в Закон № 44-ФЗ о контрактной системе&nbsp;пункта 71&nbsp;&nbsp;части 1 статьи 31.</p>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>Последствия:</strong></span></p>\r\n<p>Утверждением заказчиком, уполномоченным органом или уполномоченным учреждением документации о закупке без учёта указанных изменений законодательства РФ о контрактной системе образует состав административного правонарушения, предусмотренного частью 4.2 статьи 7.30 Кодекса РФ об административных правонарушениях,<span style="font-family: arial, helvetica, sans-serif;"><strong> и влечёт наложение административного штрафа на должностное лицо, утвердившее&nbsp; такую документацию о закупке в размере 3000 рублей.</strong></span></p>\r\n<p>Рекомендации для специалистов в сфере закупок:</p>\r\n<p>Заказчикам, уполномоченным органам и уполномоченным учреждениям &nbsp;необходимо привести формируемую и размещаемую документацию о закупке (в части требований к участникам закупки) в соответствии с новыми требованиями законодательства РФ о контрактной системе.</p>\r\n<p>При этом необходимо обратить внимание на &nbsp;то, что&nbsp;федеральный закон от 28.12.2016 № 489-ФЗ вступает в силу&nbsp;с&nbsp;09 января 2017 года, то есть уже в первый рабочий день 2017 года.&nbsp;</p>\r\n<p>Также необходимо учитывать&nbsp;&nbsp;то, что указанная информация должна декларироваться участниками закупки (в т.ч. участниками закупки &ndash; юридическими лицами) при подаче заявок на участие в конкурсах и аукционах&nbsp;&nbsp;(см. пункт 2 части 5 статьи 66, подп.&nbsp; г.) пункта 1 части 2 статьи 51 Закона № 44-ФЗ о контрактной системе).</p>\r\n<p>Поэтому во избежание в начале 2017 года массовых отклонений&nbsp; заявок участников закупок, не ознакомленных с этими изменениями законодательства, рекомендуется разработать &nbsp;примерную (рекомендуемую) форму декларации&nbsp; участника закупки о соответствии&nbsp; требованиям, установленным в соответствии с пунктами 3 &mdash; 9 части 1 статьи 31 Закона № 44-ФЗ о контрактной системе для включения её в документацию о закупке.</p>\r\n<table style="height: 818px; width: 791px;" border="1" cellspacing="0" cellpadding="0">\r\n<tbody>\r\n<tr style="height: 841.75px;">\r\n<td style="width: 787px; height: 841.75px;">\r\n<p>ОБРАЗЕЦ ДЕКЛАРАЦИИ О СООТВЕТСТВИИ ЕДИНЫМ ТРЕБОВАНИЯМ</p>\r\n<p>(ПРИМЕРНАЯ ФОРМА):</p>\r\n<p>Декларация о соответствии участника аукциона требованиям, установленным пунктами 3 - 9 части 1 статьи 31 Закона № 44-ФЗ</p>\r\n<p>Декларирую соответствие участника аукциона __________________________________________</p>\r\n<p align="center">(наименование участника аукциона - юридического лица, ф.и.о. физического лица, в т.ч. индивидуального предпринимателя)</p>\r\n<p>указанным требованиям, а именно:</p>\r\n<p>- непроведение ликвидации участника закупки - юридического лица и отсутствие решения арбитражного суда о признании участника закупки - юридического лица или индивидуального предпринимателя несостоятельным (банкротом) и об открытии конкурсного производства;</p>\r\n<p>- неприостановление деятельности участника закупки в порядке, установленном Кодексом Российской Федерации об административных правонарушениях, на дату подачи заявки на участие в закупке;</p>\r\n<p>- отсутствие у участника закупки недоимки по налогам, сборам, задолженности по иным обязательным платежам в бюджеты бюджетной системы Российской Федерации (за исключением сумм, на которые предоставлены отсрочка, рассрочка, инвестиционный налоговый кредит в соответствии с законодательством Российской Федерации о налогах и сборах, которые реструктурированы в соответствии с законодательством Российской Федерации, по которым имеется вступившее в законную силу решение суда о признании обязанности заявителя по уплате этих сумм исполненной или которые признаны безнадежными к взысканию в соответствии с законодательством Российской Федерации о налогах и сборах) за прошедший календарный год, размер которых превышает двадцать пять процентов балансовой стоимости активов участника закупки, по данным бухгалтерской отчетности за последний отчетный период;</p>\r\n<p>- отсутствие у участника закупки - физического лица либо у руководителя, членов коллегиального исполнительного органа, лица, исполняющего функции единоличного исполнительного органа, или главного бухгалтера юридического лица - участника закупки судимости за преступления в сфере экономики и (или) преступления, предусмотренные статьями 289, 290, 291, 291.1 Уголовного кодекса Российской Федерации (за исключением лиц, у которых такая судимость погашена или снята), а также неприменение в отношении указанных физических лиц наказания в виде лишения права занимать определенные должности или заниматься определенной деятельностью, которые связаны с поставкой товара, выполнением работы, оказанием услуги, являющихся объектом осуществляемой закупки, и административного наказания в виде дисквалификации;</p>\r\n<p>- участник закупки - юридическое лицо*, которое в течение двух лет до момента подачи заявки на участие в закупке не было привлечено к административной ответственности за совершение административного правонарушения, предусмотренного статьей 19.28 Кодекса Российской Федерации об административных правонарушениях;</p>\r\n<p>- отсутствие между участником закупки и заказчиком конфликта интересов, под которым понимаются случаи, при которых руководитель заказчика, член комиссии по осуществлению закупок, руководитель контрактной службы заказчика, контрактный управляющий состоят в браке с физическими лицами, являющимися выгодоприобретателями, единоличным исполнительным органом хозяйственного общества (директором, генеральным директором, управляющим, президентом и другими), членами коллегиального исполнительного органа хозяйственного общества, руководителем (директором, генеральным директором) учреждения или унитарного предприятия либо иными органами управления юридических лиц - участников закупки, с физическими лицами, в том числе зарегистрированными в качестве индивидуального предпринимателя, - участниками закупки либо являются близкими родственниками (родственниками по прямой восходящей и нисходящей линии (родителями и детьми, дедушкой, бабушкой и внуками), полнородными и неполнородными (имеющими общих отца или мать) братьями и сестрами), усыновителями или усыновленными указанных физических лиц.</p>\r\n<p>&nbsp;_________________</p>\r\n<p>* Информация о соответствии требованиям, установленным пунктом 71&nbsp;части&nbsp; 1 статьи 31 Закона № 44-ФЗ о контрактной системе указывается только участниками закупки-юридическими лицами.</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>2.&nbsp;С 01.01.2017 ГОДА &nbsp;В ИЗВЕЩЕНИИ ОБ ОСУЩЕСТВЛЕНИИ ЗАКУПКИ, ДОКУМЕНТАЦИИ О ЗАКУПКЕ И В ПРОЕКТЕ КОНТРАКТА ДОЛЖЕН УКАЗЫВАТЬСЯ 36-ЗНАЧНЫЙ ИДЕНТИФИКАЦИОННЫЙ КОД ЗАКУПКИ</strong></span></p>\r\n<p>Суть изменений:</p>\r\n<p>В соответствии с положениями части 3 статьи 114 Закона № 44-ФЗ о контрактной системе с 01.01.2017 г.&nbsp; в извещении об осуществлении закупки должна указываться информация об идентификационном коде закупки,&nbsp; так как вступил в силу пункт 3 статьи 42 данного Федерального закона.</p>\r\n<p>Обращаем внимание на то, что пункт 3 статьи 42 Закона № 44-ФЗ о контрактной системе корреспондирует с нормами&nbsp; данного Федерального закона, устанавливающими требования к содержанию&nbsp; извещения и документации о закупке&nbsp; для различных способов определения поставщика (подрядчика, исполнителя).</p>\r\n<p>Так, в силу требований части 5&nbsp; статьи 63, части&nbsp; 1 и 4&nbsp; статьи 64 Закона № 44-ФЗ о контрактной системе информация, предусмотренная статьей 42 указанного закона, должна содержаться в документации об аукционе, в том числе в проекте контракта, являющемся её неотъемлемой частью.</p>\r\n<p>Аналогичная ситуация&nbsp; имеет место в отношении конкурсной документации и документации о проведении запроса предложений (см. пункт&nbsp; 1 части 3 статьи&nbsp; 49, часть 1 и 2 статьи 50, пункт 1 части 4, пункт 1 части 6, часть 7 статьи 83 Закона № 44-ФЗ о контрактной системе).</p>\r\n<p>Таким образом,&nbsp;в 2017 году указание&nbsp;идентификационного кода закупки является обязательным,&nbsp;как извещении, так и в документации о закупке, в том числе в проекте контракта, прилагаемом к документации о закупке.</p>\r\n<p>Идентификационный код закупки обеспечивает взаимосвязь плана закупок, плана-графика, извещения об осуществлении закупки, приглашении принять участие в определении поставщика (подрядчика, исполнителя), осуществляемом закрытым способом, документации о закупке, а также контракта.</p>\r\n<p>Основное назначение идентификационного кода закупки &ndash; обеспечение возможности &nbsp;осуществления контроля, предусмотренного частью 5 статьи 99 Закона № 44-ФЗ о контрактной системе,&nbsp; Федеральным казначейством, финансовыми органами субъектов РФ и муниципальных образований, органами &nbsp;управления государственными внебюджетными фондами.</p>\r\n<p>Предметом такого контроля в отношении&nbsp; извещения об осуществлении закупки, документации о закупке, проекта контракта является контроль за соответствием информации об идентификационном коде закупки и об объеме финансового обеспечения для осуществления данных закупок.</p>\r\n<p>Идентификационный код закупки призван обеспечить автоматизацию и удобный поиск информации&nbsp; в отношении всех формируемых документов закупки от плана-графика до заключения контракта.</p>\r\n<p>После указания в идентификационном коде закупки информации о порядковом номере записи в плане-графике, такой код остаётся &nbsp;неизменным вплоть до завершения периода хранения информации и документов о такой закупке, установленного законодательством РФ об архивном деле.</p>\r\n<p>Указанный идентификационный код закупки формируется заказчиком в соответствии с приказом Минэкономразвития России от 29.06.2015 № &nbsp;422 &laquo;Об утверждении Порядка формирования идентификационного кода закупки&raquo; (Зарегистрировано в Минюсте России 21.07.2015 № 38100).</p>\r\n<p>Данным приказом утверждён Порядок формирования идентификационного кода закупки (далее &ndash; Порядок), а также&nbsp; определены правила формирования идентификационного кода закупки, в том числе его состав и структура.</p>\r\n<p>Порядком установлена 36-значная структура идентификационного кода, представляющего собой цифровой машиночитаемый код:</p>\r\n<p>1-2 разряды &ndash; год размещения извещения;</p>\r\n<p>3-22 разряды &ndash; идентификационный код заказчика (ИКУ), присвоенный заказчику Федеральным казначейством в целях ведения реестра банковских гарантий, реестра контрактов, заключенных заказчиками, и реестра контрактов, содержащего сведения, оставляющие государственную тайну;</p>\r\n<p>23-26 &ndash; порядковый номер закупки по плану закупок;</p>\r\n<p>27-29 &ndash; порядковый номер закупки по плану-графику;</p>\r\n<p>30-33 &ndash; код объекта закупки по каталогу товаров, работ, услуг;</p>\r\n<p>34-36 &ndash; код вида расходов по бюджетной классификации РФ.</p>\r\n<p>Идентификационный код формируется заказчиком в 2017 году для каждой закупки отдельно, за исключением&nbsp; закупок, осуществляемых на основании пунктов 4, 5, 26 и 33 части 1 статьи 93 Закона № 44-ФЗ о контрактной системе. В указанных случаях формируется общий (единый) код для всех закупок по каждому из перечисленных оснований закупок, без определения кода объекта закупки по каталогу товаров, работ, услуг (примечание: в разрядах 30-33 указывается значение &laquo;0&raquo;).</p>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>Последствия:</strong></span></p>\r\n<p>Утверждение заказчиком, уполномоченным органом или уполномоченным учреждением документации о закупке без&nbsp; указания 36-ти разрядного идентификационного кода закупки образует состав административного правонарушения, предусмотренного частью 4.2 статьи 7.30 Кодекса РФ об административных правонарушениях, и влечёт наложение административного штрафа на должностное лицо, утвердившее&nbsp; такую документацию о закупке в размере 3000 рублей.</p>\r\n<p>При этом заказчики по состоянию на 09.01.2017 года&nbsp; по объективным причинам не могут&nbsp; указать 36-ти разрядный идентификационный код закупки в соответствии с приказом Минэкономразвития России от 29.06.2015 №&nbsp; 422 &laquo;Об утверждении Порядка формирования идентификационного кода закупки&raquo;, так как в настоящее время утверждённый каталог товаров, работ, услуг отсутствует, то есть невозможно заполнить значения в разрядах 30-33 идентификационного кода закупки.</p>\r\n<p>Рекомендации для специалистов в сфере закупок:</p>\r\n<p>Необходимо ознакомиться&nbsp; с этими изменениями и осуществлять формирование извещений и документаций о закупках, в том числе проектов контрактов, &nbsp;с учётом&nbsp; приведённых изменений в законодательство РФ о контрактной системе в части &nbsp;указания идентификационного кода закупки.</p>\r\n<p>Также в связи с тем, что документация о закупке формируется не в автоматизированном &nbsp;режиме, а, как правило, вручную в виде отдельного электронного документа, то целесообразно сформировать шаблон документации о закупке с обязательным указанием сведений об идентификационном коде закупке.</p>\r\n<p>При формировании документации о закупке&nbsp; необходимо обязательно указывать в ней&nbsp; идентификационный код закупки, содержащийся в плане-графике закупок и извещении об осуществлении закупки.</p>\r\n<p>С учётом отсутствия в настоящее время утверждённого каталога товаров, работ, услуг в разрядах 30-33 идентификационного кода закупки целесообразно указывать коды из действующего Общероссийского классификатора продукции по видам экономической деятельности ОК 034-2014 (КПЕС 2008) &nbsp;(далее &ndash; ОКПД2) вплоть до внесения соответствующих изменений в приказ Минэкономразвития России от 29.06.2015 №&nbsp; 422 или утверждения каталога товаров, работ, услуг.</p>\r\n<p>Основание &ndash; часть 2 статьи 23 Закона № 44-ФЗ о контрактной системе.</p>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>3. С 01.01.2017 ГОДА НАИМЕНОВАНИЕ ОБЪЕКТА ЗАКУПКИ В СЛУЧАЯХ, ПРЕДУСМОТРЕННЫХ ЗАКОНОМ № 44-ФЗ О КОНТРАКТНОЙ СИСТЕМЕ, УКАЗЫВАЕТСЯ В СООТВЕТСТВИИ С КАТАЛОГОМ ТОВАРОВ, РАБОТ, УСЛУГ ДЛЯ ОБЕСПЕЧЕНИЯ ГОСУДАРСТВЕННЫХ И МУНИЦИПАЛЬНЫХ НУЖД</strong></span></p>\r\n<p>Суть изменений:</p>\r\n<p>В соответствии с положениями части 3 статьи 114 Закона № 44-ФЗ о контрактной системе с 01.01.2017 г. &nbsp;с 01.01.2017 г. &nbsp;наименование объекта закупки в случаях, предусмотренных настоящим Федеральным законом, указывается в соответствии с каталогом товаров, работ, услуг для обеспечения государственных и муниципальных нужд (далее &ndash; Каталог). Данный Каталог должен быть сформирован и вестись в единой информационной системе Минэкономразвития России (см. ч. 5 ст. 23 Закона 44-ФЗ о контрактной системе) .</p>\r\n<p>Таким образом, в случаях, предусмотренных приказом Минэкономразвития России об утверждении каталога товаров, работ, услуг для обеспечения государственных и муниципальных нужд, заказчик обязан указывать наименование объекта закупки в соответствии с&nbsp; данным Каталогом.</p>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>Последствия:</strong></span></p>\r\n<p>Закон № 44-ФЗ о контрактной системе предполагает, что с 2017 года вместо ОКПД2 в рамках контрактной системы будет использоваться сформированный на его основе каталог товаров, работ, услуг для обеспечения государственных и муниципальных нужд, который будет формироваться и вестись Минэкономразвития России.</p>\r\n<p>Предполагается, что Каталог будет состоять состоит из распределённых по классификационным группировкам позиций номенклатуры Каталога (стандартных объектов закупки), связанных с ними конкретных товаров, работ, услуг и ценовых предложений о товарах, работах, услугах.</p>\r\n<p>При этом в настоящее время&nbsp; соответствующий приказ Минэкономразвития России об утверждении данного Каталога отсутствует, что делает объективно невозможным исполнение&nbsp; данного требования закона.</p>\r\n<p>Рекомендации для специалистов в сфере закупок:</p>\r\n<p>В течение 2017 года отслеживать изменения действующего законодательства РФ о контрактной системе в части утверждения каталога товаров, работ, услуг для обеспечения государственных и муниципальных нужд.</p>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>4.&nbsp; &nbsp;С 31.12.2016 Г.&nbsp; ЗАКАЗЧИКИ, УПОЛНОМОЧЕННЫЕ ОРГАНЫ, УПОЛНОМОЧЕННЫЕ УЧРЕЖДЕНИЯ ВПРАВЕ ПРОВОДИТЬ ЭЛЕКТРОННЫЕ АУКЦИОНЫ НЕ НА 5-ТИ, А НА 6-ТИ ЭЛЕКТРОННЫХ ПЛОЩАДКАХ</strong></span></p>\r\n<p>Суть изменений:</p>\r\n<p>6 января 2017 года на официальном интернет-портале правовой информации &mdash; pravo.gov.ru было опубликовано&nbsp; распоряжение Правительства РФ от 31.12.2016 № 2933-р.</p>\r\n<p>Согласно тексту распоряжения Правительство РФ приняло предложение Минэкономразвития России о проведении электронных аукционов в соответствии с Федеральным законом &laquo;О контрактной системе в сфере закупок товаров, работ, услуг для обеспечения государственных и муниципальных нужд&raquo; на ранее прошедших отбор электронных торговых площадках, указанных в&nbsp; перечне юридических лиц для организации продажи государственного и муниципального имущества в электронной форме, утверждённом распоряжением Правительства РФ от 04 декабря 2015 г. № 2488-р, до начала функционирования операторов электронных торговых площадок, прошедших отбор в соответствии с частью 4 статьи 59 указанного Федерального закона.</p>\r\n<p>Распоряжением Правительства РФ от&nbsp; 04.12.2015 г. № 2488-р утверждено 6-ть юридических лиц:</p>\r\n<p>1. Государственное унитарное предприятие &laquo;Агентство по государственному заказу, инвестиционной деятельности и межрегиональным связям Республики Татарстан&raquo;.</p>\r\n<p>2. Акционерное общество &laquo;Электронные торговые системы&raquo;.</p>\r\n<p>3. Закрытое акционерное общество &laquo;Сбербанк &mdash; Автоматизированная система торгов&raquo;.</p>\r\n<p>4. Общество с ограниченной ответственностью &laquo;РТС &mdash; тендер&raquo;.</p>\r\n<p>5. Акционерное общество &laquo;Единая электронная торговая площадка&raquo;.</p>\r\n<p>6. Открытое акционерное общество &laquo;Российский аукционный дом&raquo;.</p>\r\n<p>Таким образом, с даты вступления в силу указанного распоряжения Правительства РФ, то есть с 31 декабря 2016 г. (примечание: распоряжения Правительства вступают в силу с даты их подписания &mdash; см. статью 23 Федерального конституционного закона от 17.12.1997 N 2-ФКЗ (ред. от 28.12.2016) &laquo;О Правительстве Российской Федерации&raquo;), заказчики в рамках Закона № 44-ФЗ о контрактной системе вправе проводить электронные аукционы не на 5-ти, а на 6-ти электронных торговых площадках.</p>\r\n<p>6-й электронной площадкой для проведения электронных аукционов в рамках Закона № 44-ФЗ о контрактной системе стала электронная площадка ОАО &laquo;Российский аукционный дом&raquo;.</p>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>Последствия</strong></span></p>\r\n<p>Появляется возможность проведения электронных аукционов на новой электронной площадке ОАО &laquo;Российский аукционный дом&raquo;.</p>\r\n<p>Рекомендации для специалистов в сфере закупок:</p>\r\n<p>Целесообразно ознакомиться с функционалом и возможностями новой электронной площадки для проведения электронных аукционов в рамках Закона № 44-ФЗ о контрактной системе.</p>\r\n<p>При этом при объявлении процедур аукционов на данной площадке следует учитывать, что большинство участников закупок на указанной площадке не аккредитовано, что может привести к снижению количества участников закупки&nbsp; при проведении электронных аукционов на площадке.</p>\r\n<p><strong><span style="font-family: arial, helvetica, sans-serif;">5. &nbsp; ВОЗМОЖНОСТЬ ПОДАЧИ ЗАЯВОК УЧАСТНИКАМИ ЗАКУПОК В ФОРМЕ ЭЛЕКТРОННЫХ ДОКУМЕНТОВ ЧЕРЕЗ ЕДИНУЮ ИНФОРМАЦИОННУЮ СИСТЕМУ ПЕРЕНЕСЕНА ДО 2018 ГОДА</span></strong></p>\r\n<p>Суть изменений:</p>\r\n<p>06 января 2017 года на официальном интернет-портале правовой информации &mdash; pravo.gov.ru было опубликовано постановление Правительства Российской Федерации от 31.12.2016 № 1588 &laquo;О внесении изменения в постановление Правительства Российской Федерации от 23 января 2015 г. № 36&raquo;.</p>\r\n<p>Данным постановлением Федеральному казначейству предписывается обеспечить участникам закупок возможность подачи через&nbsp; единую информационную систему в сфере закупок (далее по тексту &mdash; ЕИС) заявок на участие в определении поставщика (подрядчика, исполнителя) и окончательных предложений не позднее 1 января 2018 года.</p>\r\n<p>В соответствии с частью 1 статьи 5 Закона № 44-ФЗ о контрактной системе допускается обмен электронными документами, предусмотренными законодательством Российской Федерации и иными нормативными правовыми актами о контрактной системе в сфере закупок, между участниками контрактной системы в сфере закупок, в том числе подача заявок на участие в определении поставщика (подрядчика, исполнителя), окончательных предложений. При этом указанные заявки, окончательные предложения и документы должны быть подписаны усиленной электронной подписью и поданы с использованием&nbsp; ЕИС.</p>\r\n<p>Таким образом, участники закупок смогут воспользоваться своим правом на подачу заявок для участия в конкурентных процедурах закупок в форме электронных документов через ЕИС&nbsp;&nbsp; только после доработки в течение 2017 года функционала ЕИС в этой части.</p>\r\n<p>С 01.01.2017 года и до внесения соответствующих изменений в функционал единой информационной системы в сфере закупок такая возможность у участников закупок по прежнему отсутствует.</p>\r\n<p><span style="font-family: arial, helvetica, sans-serif;"><strong>Последствия</strong></span></p>\r\n<p>Заказчики, уполномоченные органы, уполномоченные учреждения в 2017 году, как и ранее в 2016 году, не вправе принимать заявки в форме электронных документов на участие в конкурсе, запросе предложений, запросе котировок, поданные участниками закупки без использования единой информационной системы.</p>\r\n<p>Рекомендации для специалистов в сфере закупок:</p>\r\n<p>Во избежание необоснованных жалоб от участников закупок включать в извещение и (или) документацию о закупке положения части 1 статьи 5 Закона № 44-ФЗ о контрактной системе о порядке подачи заявок&nbsp; на участие в определении поставщика (подрядчика, исполнителя)&nbsp; в форме электронных документов с обязательным использованием единой информационной системы в сфере закупок.</p>\r\n<table border="1" width="866" cellspacing="0" cellpadding="0">\r\n<tbody>\r\n<tr>\r\n<td>\r\n<p>ОБРАЗЕЦ ФОРМУЛИРОВКИ ИЗ ДОКУМЕНТАЦИИ О ЗАКУПКЕ</p>\r\n<p>(ПРИМЕРНАЯ ФОРМА):</p>\r\n<p>В соответствии с требованиями части 1 статьи 5 Закона № 44-ФЗ о контрактной системе заявка в форме электронного документа подается в составе документов и по форме, предусмотренной для заявки в письменной форме, с использованием единой информационной системы.</p>\r\n<p>В соответствии с пунктом 2 постановления Правительства РФ от 23.01.2015 г. № 36 &laquo;О порядке и сроках ввода в эксплуатацию единой информационной системы в сфере закупок&raquo; возможность подачи через указанную единую информационную систему заявок на участие в определении поставщика (подрядчика, исполнителя) и окончательных предложений должна быть обеспечена участникам закупок Федеральным казначейством не позднее 1 января 2018 года.</p>\r\n<p>В связи с этим заявки на участие в определении поставщика (подрядчика, исполнителя)&nbsp; до обеспечения указанной возможности участникам закупки Федеральным казначейством&nbsp; подаются участниками закупки в письменной форме.</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>', '', -2, 16, '2017-02-06 17:02:48', 42, '', '2017-02-06 12:50:18', 42, 42, '2018-06-04 05:09:27', '2017-02-06 12:17:10', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 6, 3, '', '', 1, 1851, '', 0, '*', '');
INSERT INTO `j7_content` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(162, 263, 'Изменения в налогообложении с 01.01.2017 г.', 'изменения-с-2017-года-контрактная-система-2', '<h1 style="text-align: center;">Изменения в налогообложении и нововведения по страховым взносам&nbsp;с 01.01.2017 г.</h1>\r\n<table class="MsoTableGrid" style="margin-left: 5.4pt; border-collapse: collapse; border: none; width: 796.188px;" border="1" cellspacing="0" cellpadding="0">\r\n<tbody>\r\n<tr>\r\n<td style="width: 109px; border: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><b>ЧТО </b></span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><b>ИЗМЕНИЛОСЬ</b></span></p>\r\n</td>\r\n<td style="width: 76px; border-top: 1pt solid windowtext; border-right: 1pt solid windowtext; border-bottom: 1pt solid windowtext; border-image: initial; border-left: none; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><b>ВСТУПАЕТ В СИЛУ</b></span></p>\r\n</td>\r\n<td style="width: 194px; border-top: 1pt solid windowtext; border-right: 1pt solid windowtext; border-bottom: 1pt solid windowtext; border-image: initial; border-left: none; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><b>ДО</b></span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><b>ИЗМЕНЕНИЙ</b></span></p>\r\n</td>\r\n<td style="width: 186px; border-top: 1pt solid windowtext; border-right: 1pt solid windowtext; border-bottom: 1pt solid windowtext; border-image: initial; border-left: none; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><b>ПОСЛЕ </b></span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><b>ИЗМЕНЕНИЙ</b></span></p>\r\n</td>\r\n<td style="width: 161.188px; border-top: 1pt solid windowtext; border-right: 1pt solid windowtext; border-bottom: 1pt solid windowtext; border-image: initial; border-left: none; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><b>НОРМАТИВНЫЙ </b></span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10pt; font-family: arial, helvetica, sans-serif;"><b>ДОКУМЕНТ</b></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 109px; border-right: 1pt solid windowtext; border-bottom: 1pt solid windowtext; border-left: 1pt solid windowtext; border-image: initial; border-top: none; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;"><b>Администратор страховых взносов</b></span></p>\r\n</td>\r\n<td style="width: 76px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">с</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">01.01.2017</span></p>\r\n</td>\r\n<td style="width: 194px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Контроль за уплатой пенсионных и медицинских взносов осуществляет ПФР. Администрированием взносов на случай временной нетрудоспособности и в связи с материнством, взносов на случай травматизма занимается ФСС РФ</span></p>\r\n</td>\r\n<td style="width: 186px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Контролировать страховые взносы будет ФНС (кроме взносов &laquo;на травматизм&raquo;). Они останутся в ведении ФСС РФ</span></p>\r\n</td>\r\n<td style="width: 161.188px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">Федеральный закон от 03.07.2016 </span><span style="font-family: arial, helvetica, sans-serif; font-size: 10pt;">№ 243-ФЗ</span></p>\r\n</td>\r\n</tr>\r\n<tr style="mso-yfti-irow: 2; height: 70.4pt;">\r\n<td style="width: 109px; border-right: 1pt solid windowtext; border-bottom: 1pt solid windowtext; border-left: 1pt solid windowtext; border-image: initial; border-top: none; padding: 0cm 5.4pt; height: 70.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><b><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Отчетность по страховым взносам</span></b></p>\r\n</td>\r\n<td style="width: 76px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt; height: 70.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">с</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">01.01.2017</span></p>\r\n</td>\r\n<td style="width: 194px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt; height: 70.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><b><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Три отчета:</span></b></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">1. Ежеквартальный РСВ-1 (сводный отчет по пенсионным и медицинским взносам) &ndash; в ПФР. Сроки сдачи такие: электронный &ndash; не позднее 20-го числа второго месяца, бумажный &ndash; не позднее 15-го. </span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">&nbsp;</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">2. Ежемесячный СЗВ-М (сведения о застрахованных лицах) &ndash; в ПФР. Представлять надо не позднее 10-го числа следующего месяца. </span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">&nbsp;</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">3. Ежеквартальный 4-ФСС (сводный отчет по взносам на случай болезни и материнства и на травматизм) &ndash; в ФСС РФ. Срок сдачи электронного отчета</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">&ndash; не позднее 25-го числа следующего месяца, бумажного &ndash; не позднее 20-го</span></p>\r\n</td>\r\n<td style="width: 186px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt; height: 70.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><b><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Четыре отчета:</span></b></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">1. Единый расчет по взносам &ndash; в ИФНС. Сдавать его нужно ежеквартальное по всем взносам, кроме взносов на травматизм. Форма расчета</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">утверждена&nbsp; Приказом ФНС России от 10.10.2016 № ММВ-7-11/551@. </span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Срок сдачи &ndash; не позднее 30 числа месяца, следующего за отчетным периодом (впервые отчёт надо сдать за 1 квартал 2017 г. не позднее 02.05.2017)</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">&nbsp;</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">4. Отчет по форме СЗВ-М &ndash; в ПФР. Сдавать его также надо будет каждый месяц. Отправлять СЗВ-М потребуется не позднее 15 числа следующего месяца. </span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">&nbsp;</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">3. Сведения о страховом стаже сотрудников &ndash; в ПФР. Это новый отчет. Его бланк появится позднее. Сдавать отчет нужно будет раз в год &ndash; не позднее 1 марта (впервые отчёт надо сдать за 2017 г. не позднее 01.03.2018).</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">&nbsp;</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">4. Расчет по взносам на травматизм &ndash; в ФСС. Отчет будет выглядеть как раздел II формы 4-ФСС. Отчитываться надо будет ежеквартально. Сроки сдачи такие: на бумаге &ndash; не позднее 20 числа месяца, следующего за отчетным периодом, электронно &ndash; не позже 25-го)</span></p>\r\n</td>\r\n<td style="width: 161.188px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt; height: 70.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Федеральный закон от 03.07.2016 </span><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">№ 243-ФЗ</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">&nbsp;</span><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Федеральный закон от 03.07.2016&nbsp;</span><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">№ 250-ФЗ</span></p>\r\n</td>\r\n</tr>\r\n<tr style="mso-yfti-irow: 3; height: 91.6pt;">\r\n<td style="width: 109px; border-right: 1pt solid windowtext; border-bottom: 1pt solid windowtext; border-left: 1pt solid windowtext; border-image: initial; border-top: none; padding: 0cm 5.4pt; height: 91.6pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><b><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">КБК по страховым взносам</span></b></p>\r\n</td>\r\n<td style="width: 76px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt; height: 91.6pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">с</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">01.01.2017</span></p>\r\n</td>\r\n<td style="width: 194px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt; height: 91.6pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Надо составлять отдельные платежки для пенсионных взносов (обычных и дополнительных), медицинских, по нетрудоспособности и по травматизму. В самих платежках надо проставлять такие КБК: 392 1 02 02010 06 1000 160 - страховые взносы на обязательное пенсионное страхование;</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">392 1 02 02101 08 1011 160 -</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">страховые взносы в бюджет</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">ФФОМС за работников;</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">393 1 02 02090 07 1000 160 &ndash;</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">страховые взносы в ФСС на</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">обязательное социальное страхование на случай временной нетрудоспособности и в связи с материнством;</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">393 1 02 02050 07 1000 160 -</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">страховые взносы в ФСС от</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">несчастных случаев на производстве и профессиональных заболеваний за работников;</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">392 1 02 02131 06 1000 160 -</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">страховые взносы в ПФР по</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">дополнительному тарифу за застрахованных лиц, занятых на</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">соответствующих видах работ, по списку 1;</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">392 1 02 02132 06 1000 160 -</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">страховые взносы в ПФР по</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">дополнительному тарифу за застрахованных лиц, занятых на соответствующих видах работ,</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">по списку 2</span></p>\r\n</td>\r\n<td style="width: 186px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt; height: 91.6pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Минфин утвердил новые КБК по взносам.</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">&nbsp;</span><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">На эти КБК платите страховые взносы за периоды с 2017 года &mdash; взносы за январь 2017 года и далее:</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Взносы на пенсионное страхование</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">182 1 02 02010 06 1010 160 </span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">&nbsp;</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Взносы на соцстрах </span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">182 1 02 02090 07 1010 160 </span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">&nbsp;</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Медицинские взносы </span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">182 1 02 02101 08 1013 160 </span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">&nbsp;</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Взносы на травматизм </span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">393 1 02 02050 07 1000 160 </span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">&nbsp;</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Дополнительные пенсионные взносы по тарифу 1</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">182 1 02 02131 06 1010 160 &ndash; если тариф не зависит от спецоценки; </span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">182 1 02 02131 06 1020 160 &ndash; если тариф зависит от спецоценки.</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">&nbsp;</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Дополнительные пенсионные взносы по тарифу 2 </span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">182 1 02 02132 06 1010 160 &ndash; если тариф не зависит от спецоценки; </span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">182 1 02 02132 06 1020 160 &ndash; если тариф зависит от спецоценки.</span></p>\r\n</td>\r\n<td style="width: 161.188px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt; height: 91.6pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Приказ Минфина от 17.12.2016 </span><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">№ 230н</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 109px; border-right: 1pt solid windowtext; border-bottom: 1pt solid windowtext; border-left: 1pt solid windowtext; border-image: initial; border-top: none; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Лимиты по взносам</span></p>\r\n</td>\r\n<td style="width: 76px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">с</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">01.01.2017</span></p>\r\n</td>\r\n<td style="width: 194px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Лимит по взносам составлял:</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">- 796 000 руб. &ndash; пенсионные взносы;</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">- 718 000 руб. &ndash; взносы по временной нетрудоспособности.</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">(Медицинские взносы начисляются независимо от того, сколько за год получил сотрудник)</span></p>\r\n</td>\r\n<td style="width: 186px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Лимит по взносам составляет:</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">- 876 000 руб. - по пенсионным взносам;</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">- 755 000 руб. - по взносам по временной нетрудоспособности.</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">&nbsp;</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">(Медицинские взносы начисляются независимо от того, сколько за год получил сотрудник)</span></p>\r\n</td>\r\n<td style="width: 161.188px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Федеральный закон от 03.07.2016 №</span> <span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">243-ФЗ</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 109px; border-right: 1pt solid windowtext; border-bottom: 1pt solid windowtext; border-left: 1pt solid windowtext; border-image: initial; border-top: none; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Прописаны новые правила рас-чета и уплаты взносов на травматизм</span></p>\r\n</td>\r\n<td style="width: 76px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">с</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">01.01.2017</span></p>\r\n</td>\r\n<td style="width: 194px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Эти положения не прописаны в Законе</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">№ 125-ФЗ.</span></p>\r\n</td>\r\n<td style="width: 186px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Теперь расчетный и отчетный периоды, а также порядок расчета и сроки уплаты страховых взносов прописаны в Законе</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">№ 125-ФЗ.</span></p>\r\n</td>\r\n<td style="width: 161.188px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">П. 7 ст. 3 Закона</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">от 3 июля 2016 г.</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">№ 250-ФЗ</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 109px; border-right: 1pt solid windowtext; border-bottom: 1pt solid windowtext; border-left: 1pt solid windowtext; border-image: initial; border-top: none; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Порядок установления тарифа взносов на случай травматизма</span></p>\r\n</td>\r\n<td style="width: 76px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">с</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">01.01.2017</span></p>\r\n</td>\r\n<td style="width: 194px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Четкого порядка в законодательстве не прописано</span></p>\r\n</td>\r\n<td style="width: 186px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Если компания не подтвердит основной вид деятельности (до 15 апреля), ФСС установит тариф по самому рискованному виду деятельности, указанному в ЕГРЮЛ. Причем неважно, ведет компания этот вид деятельности или нет.</span></p>\r\n</td>\r\n<td style="width: 161.188px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Постановление Правительства РФ от 17.06.2016&nbsp;</span><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">№ 551</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 109px; border-right: 1pt solid windowtext; border-bottom: 1pt solid windowtext; border-left: 1pt solid windowtext; border-image: initial; border-top: none; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Появится требование к доходам компаний на УСН для применения пониженных тарифов</span></p>\r\n</td>\r\n<td style="width: 76px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">с</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">01.01.2017</span></p>\r\n</td>\r\n<td style="width: 194px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Законодательством никаких требований не установлено</span></p>\r\n</td>\r\n<td style="width: 186px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Пониженным тарифом смогут воспользоваться лишь те организации, у которых доходы за текущий год не превысили 79 млн. руб.</span></p>\r\n</td>\r\n<td style="width: 161.188px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Федеральный закон от 03.07.2016 №</span> <span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">243-ФЗ</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 109px; border-right: 1pt solid windowtext; border-bottom: 1pt solid windowtext; border-left: 1pt solid windowtext; border-image: initial; border-top: none; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Порядок урегулирования споров по взносам</span></p>\r\n</td>\r\n<td style="width: 76px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">с</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">01.01.2017</span></p>\r\n</td>\r\n<td style="width: 194px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">В спорах по решениям специалистов Пенсионного фонда и ФСС, сами решаете, куда обратиться. </span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Обязательного досудебного порядка нет.</span></p>\r\n</td>\r\n<td style="width: 186px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">В отношении взносов начал действовать обязательный досудебный порядок решения споров, установленный НК РФ.</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Т.о. обжаловать решения по страховым взносам нужно будет сначала в вышестоящей инстанции &ndash; региональном налоговом управлении (УФНС России). А только потом в суде.</span></p>\r\n</td>\r\n<td style="width: 161.188px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Федеральный закон от 03.07.2016 №</span> <span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">243-ФЗ</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 109px; border-right: 1pt solid windowtext; border-bottom: 1pt solid windowtext; border-left: 1pt solid windowtext; border-image: initial; border-top: none; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Добавлены правила проверок ФСС</span></p>\r\n</td>\r\n<td style="width: 76px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">с</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">01.01.2017</span></p>\r\n</td>\r\n<td style="width: 194px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">-</span></p>\r\n</td>\r\n<td style="width: 186px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Новые статьи 26.14&ndash;26.21 в Законе № 125- ФЗ позволят ФСС эффективнее проверять компании.</span></p>\r\n</td>\r\n<td style="width: 161.188px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">П. 10 ст. 3 Закона&nbsp;</span><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">от 3 июля 2016 г. </span><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">№ 250-ФЗ</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 109px; border-right: 1pt solid windowtext; border-bottom: 1pt solid windowtext; border-left: 1pt solid windowtext; border-image: initial; border-top: none; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Меняется порядок возврата излишне уплаченных страховых взносов за периоды до</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">1 января 2017 года</span></p>\r\n</td>\r\n<td style="width: 76px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">с</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">01.01.2017</span></p>\r\n</td>\r\n<td style="width: 194px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Решение о возврате, и сам возврат осуществляли фонды.</span></p>\r\n</td>\r\n<td style="width: 186px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Решение о возврате излишне уплаченных сумм с 2017 года теперь будут принимать Пенсионный фонд и ФСС. </span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Возврат переплаты будет осуществлять налоговая инспекция.</span></p>\r\n</td>\r\n<td style="width: 161.188px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Ст. 21 Закона от 3 июля 2016 г. № 250-ФЗ</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 109px; border-right: 1pt solid windowtext; border-bottom: 1pt solid windowtext; border-left: 1pt solid windowtext; border-image: initial; border-top: none; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Расширены полномочия ФСС</span></p>\r\n</td>\r\n<td style="width: 76px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">с</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">01.01.2017</span></p>\r\n</td>\r\n<td style="width: 194px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">-</span></p>\r\n</td>\r\n<td style="width: 186px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Новые права ФСС России с 2017 года:</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">&ndash; вызывать страхователей и требовать пояснений по поводу начисления и уплаты взносов;</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">&ndash; определять суммы страховых взносов расчетным путем;</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">&ndash; получать доступ к банковской тайне для контроля за взносами;</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">&ndash; начать процедуру банкротства страхователя, который не платит взносы;</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">&ndash; запрашивать сведения с грифом &laquo;налоговая тайна&raquo;</span></p>\r\n</td>\r\n<td style="width: 161.188px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Подп. &laquo;а&raquo; п. 3 ст. 3 Закона от 3 июля 2016 г. № 250-ФЗ</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 109px; border-right: 1pt solid windowtext; border-bottom: 1pt solid windowtext; border-left: 1pt solid windowtext; border-image: initial; border-top: none; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Новый порядок взыскания долгов по взносам</span></p>\r\n</td>\r\n<td style="width: 76px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">с</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">01.01.2017</span></p>\r\n</td>\r\n<td style="width: 194px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">-</span></p>\r\n</td>\r\n<td style="width: 186px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">С 2017 года закон от 24 июля 1998 г. № 125- ФЗ дополнили статьями 26.1&ndash;26.13, в которых прописали:</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">&ndash; как взыскивать недоимку;</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">&ndash; как предоставлять отсрочку (рассрочку);</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">&ndash; как выставлять требования об уплате взносов;</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">&ndash; как начислять пени;</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">&ndash; как вернуть и зачесть излишне уплаченные взносы</span></p>\r\n</td>\r\n<td style="width: 161.188px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">П. 10 ст. 3 Закона&nbsp;</span><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">от 3 июля 2016 г.&nbsp;</span><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">№ 250-ФЗ</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 109px; border-right: 1pt solid windowtext; border-bottom: 1pt solid windowtext; border-left: 1pt solid windowtext; border-image: initial; border-top: none; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Суточные сверх установленных НК норм попадают под обложение страховыми взносами</span></p>\r\n</td>\r\n<td style="width: 76px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">с</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">01.01.2017</span></p>\r\n</td>\r\n<td style="width: 194px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">В 2016 году от взносов освобождалась вся величина суточных, указанная в коллективном договоре или в локальном нормативном акте</span></p>\r\n</td>\r\n<td style="width: 186px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Взносы (кроме взносов &laquo;на травматизм&raquo;) необходимо уплачивать с сумм более 700 рублей для внутрироссийских командировок, и с суммы более 2 500 рублей для загранкомандировок.</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Т.о. с 2017 года для суточных действуют те же лимиты, как для НДФЛ (п. 3 ст. 217 НК РФ).</span></p>\r\n</td>\r\n<td style="width: 161.188px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Пункт 2 статьи 422 НК РФ</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 109px; border-right: 1pt solid windowtext; border-bottom: 1pt solid windowtext; border-left: 1pt solid windowtext; border-image: initial; border-top: none; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">ТРЕТЬИ ЛИЦА СТАЛИ ВПРАВЕ ПЛАТИТЬ ЗА ДРУГИХ НАЛОГИ, СБОРЫ И СТРАХОВЫЕ ВЗНОСЫ</span></p>\r\n</td>\r\n<td style="width: 76px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">с</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">01.01.2017</span></p>\r\n</td>\r\n<td style="width: 194px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Ранее налоговое законодательство обязывало налогоплательщиков уплачивать налоги и сборы самостоятельно (п.1 ст. 45 НК РФ).</span></p>\r\n</td>\r\n<td style="width: 186px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Уплачивать налоги, сборы и страховые взносы за организации, индивидуальных предпринимателей или физических лиц смогут третьи лица.</span></p>\r\n</td>\r\n<td style="width: 161.188px; border-top: none; border-left: none; border-bottom: 1pt solid windowtext; border-right: 1pt solid windowtext; padding: 0cm 5.4pt;" valign="top">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">Федеральный закон от 30.11.2016 № 401-ФЗ &nbsp;</span><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif'';">(п.1, статья 13)</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class="MsoNormal" style="text-align: center;"><span style="font-size: 14pt; font-family: arial, helvetica, sans-serif;">&nbsp;<b style="text-align: center; font-size: 12.16px;"><span style="line-height: 115%;">Ставки страховых взносов в 2017 году</span></b></span></p>\r\n<p class="MsoNormal" style="text-align: center;"><b><span style="font-size: 10.0pt; line-height: 115%; font-family: ''Arial'',''sans-serif'';">Стандартные тарифы страховых взносов на 2017 год (ст. 426 НК РФ в ред., действ. с 01.01.2017)</span></b></p>\r\n<table class="MsoNormalTable" style="margin-left: 2.75pt; border: 1pt solid windowtext; width: 800.656px;" border="1" cellpadding="0">\r\n<thead>\r\n<tr>\r\n<td style="width: 339px; border: 1pt solid windowtext; padding: 0.75pt;" colspan="2">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><b><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">в ПФР на обязательное пенсионное страхование</span></b></p>\r\n</td>\r\n<td style="width: 362px; border: 1pt solid windowtext; padding: 0.75pt;" colspan="2">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><b><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">в ФСС на страхование на случай временной нетрудоспособности и материнства (ВНиМ)</span></b></p>\r\n</td>\r\n<td style="width: 116.656px; border: 1pt solid windowtext; padding: 0.75pt;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><b><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">в ФФОМС на ОМС</span></b></p>\r\n</td>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td style="width: 172px; border: 1pt solid windowtext; padding: 0.75pt;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">С суммы выплат в пределах установленной предельной величины базы</span></p>\r\n</td>\r\n<td style="width: 167px; border: 1pt solid windowtext; padding: 0.75pt;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">С суммы превышения установленной предельной величины базы </span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">(свыше </span><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: Arial; color: #221f1f; letter-spacing: -.05pt;">87</span><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: Arial; color: #221f1f;">6 <span style="letter-spacing: -.05pt;">00</span>0 <span style="letter-spacing: -.05pt;">р</span><span style="letter-spacing: -.1pt;">у</span><span style="letter-spacing: -.05pt;">б</span>.</span><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">)</span></p>\r\n</td>\r\n<td style="width: 173px; border: 1pt solid windowtext; padding: 0.75pt;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">С суммы выплат в пределах установленной предельной величины базы</span></p>\r\n</td>\r\n<td style="width: 189px; border: 1pt solid windowtext; padding: 0.75pt;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">С суммы превышения установленной предельной величины базы</span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">(свыше </span><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: Arial; color: #221f1f; letter-spacing: -.05pt;">75</span><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: Arial; color: #221f1f;">5 <span style="letter-spacing: -.05pt;">00</span>0 <span style="letter-spacing: -.2pt;">р</span><span style="letter-spacing: -.1pt;">у</span><span style="letter-spacing: -.05pt;">б.</span></span><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">)</span></p>\r\n</td>\r\n<td style="width: 116.656px; border: 1pt solid windowtext; padding: 0.75pt;" rowspan="2">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">5,1%</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="width: 172px; border: 1pt solid windowtext; padding: 0.75pt;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">22%</span></p>\r\n</td>\r\n<td style="width: 167px; border: 1pt solid windowtext; padding: 0.75pt;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">10%</span></p>\r\n</td>\r\n<td style="width: 173px; border: 1pt solid windowtext; padding: 0.75pt;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">2,9%</span></p>\r\n</td>\r\n<td style="width: 189px; border: 1pt solid windowtext; padding: 0.75pt;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">Не начисляются</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class="MsoNormal"><span style="font-size: 10.0pt; line-height: 115%; font-family: ''Arial'',''sans-serif'';">Пониженные тарифы взносов на 2017 год (п. 4-10 ст. 427 НК РФ в ред., действ. с 01.01.2017)</span></p>\r\n<p class="MsoNormal" style="text-align: justify;"><span style="font-size: 10.0pt; line-height: 115%; font-family: ''Arial'',''sans-serif'';">Ставки пониженных тарифов в 2017 остались прежними, но условия, которым должен соответствовать плательщик взносов, чтобы иметь право на пониженные тарифы, в НК РФ прописаны более четко и подробно. Для некоторых льготников установили новые (дополнительные) требования.</span></p>\r\n<p class="MsoNormal" style="text-align: justify;"><span style="font-size: 10.0pt; line-height: 115%; font-family: ''Arial'',''sans-serif'';">!!! В отношении некоторых категорий плательщиков в НК РФ прямо указано, что при несоблюдении указанных условий организация или ИП утрачивает право на применение пониженных тарифов с начала расчетного периода, т. е. Календарного года.</span></p>\r\n<table class="MsoNormalTable" style="border: 1pt solid windowtext; width: 803px;" border="1" cellpadding="0">\r\n<thead>\r\n<tr style="height: 52px;">\r\n<td style="width: 879px; border: 1pt solid windowtext; padding: 0.75pt; height: 104.531px; background-color: #ffffff;" rowspan="2">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><b><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">Категория&nbsp;</span></b><b><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">страхователя</span></b></p>\r\n</td>\r\n<td style="width: 177px; border: 1pt solid windowtext; padding: 0.75pt; height: 104.531px; background-color: #ffffff;" rowspan="2">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><b><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">Коды ОКВЭД2 видов деятельности*</span></b></p>\r\n</td>\r\n<td style="width: 770px; border: 1pt solid windowtext; padding: 0.75pt; height: 52px; background-color: #ffffff;" colspan="3">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><b><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">Тариф для расчета взносов</span></b></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 52.5313px;">\r\n<td style="width: 282px; border: 1pt solid windowtext; padding: 0.75pt; height: 52.5313px; background-color: #ffffff;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><b><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">в ПФР</span></b></p>\r\n</td>\r\n<td style="width: 261px; border: 1pt solid windowtext; padding: 0.75pt; height: 52.5313px; background-color: #ffffff;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><b><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">в ФСС на ВНиМ</span></b></p>\r\n</td>\r\n<td style="width: 227px; border: 1pt solid windowtext; padding: 0.75pt; height: 52.5313px; background-color: #ffffff;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><b><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">в ФФОМС</span></b></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 52px;">\r\n<td style="width: 879px; border: 1pt solid windowtext; padding: 0.75pt; height: 52px; background-color: #ffffff;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU; mso-bidi-font-weight: bold;">Организации и ИП на УСН, ведущие льготируемый вид деятельности, доход от которого составляет</span></p>\r\n</td>\r\n<td style="width: 177px; border: 1pt solid windowtext; padding: 0.75pt; height: 52px; background-color: #ffffff;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU; mso-bidi-font-weight: bold;">13, 14, 15, 16 и др.</span></p>\r\n</td>\r\n<td style="width: 282px; border: 1pt solid windowtext; padding: 0.75pt; height: 52px; background-color: #ffffff;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU; mso-bidi-font-weight: bold;">20</span></p>\r\n</td>\r\n<td style="width: 261px; border: 1pt solid windowtext; padding: 0.75pt; height: 52px; background-color: #ffffff;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU; mso-bidi-font-weight: bold;">0</span></p>\r\n</td>\r\n<td style="width: 227px; border: 1pt solid windowtext; padding: 0.75pt; height: 52px; background-color: #ffffff;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU; mso-bidi-font-weight: bold;">0</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 52px;">\r\n<td style="width: 879px; border: 1pt solid windowtext; padding: 0.75pt; height: 52px; background-color: #ffffff;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU; mso-bidi-font-weight: bold;">Не менее 70% в общем объеме доходов упрощенца. При этом годовой доход упрощенца не должен превышать 79 млн. руб. При превышении данного лимита право на пониженные тарифы плательщик взносов теряет с начала расчетного периода (пп. 5 п. 1, пп. 3 п. 2, п. 6 ст. 427 НК РФ в ред., действ. с 01.01.2017)</span></p>\r\n</td>\r\n<td style="width: 177px; border: 1pt solid windowtext; padding: 0.75pt; height: 52px; background-color: #ffffff;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU; mso-bidi-font-weight: bold;">&nbsp;</span></p>\r\n</td>\r\n<td style="width: 282px; border: 1pt solid windowtext; padding: 0.75pt; height: 52px; background-color: #ffffff;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU; mso-bidi-font-weight: bold;">&nbsp;</span></p>\r\n</td>\r\n<td style="width: 261px; border: 1pt solid windowtext; padding: 0.75pt; height: 52px; background-color: #ffffff;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU; mso-bidi-font-weight: bold;">&nbsp;</span></p>\r\n</td>\r\n<td style="width: 227px; border: 1pt solid windowtext; padding: 0.75pt; height: 52px; background-color: #ffffff;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU; mso-bidi-font-weight: bold;">&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 52px;">\r\n<td style="width: 879px; border: 1pt solid windowtext; padding: 0.75pt; height: 52px; background-color: #ffffff;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU; mso-bidi-font-weight: bold;">Аптечные организации, а также ИП, имеющие лицензию на ведение фармацевтической деятельности, на ЕНВД. Пониженные тарифы взносов применяются только в отношении работников, занятых в фармацевтической деятельности (пп. 6 п. 1, пп. 3 п. 2 ст. 427 НК РФ в ред., действ. с 01.01.2017)</span></p>\r\n</td>\r\n<td style="width: 177px; border: 1pt solid windowtext; padding: 0.75pt; height: 52px; background-color: #ffffff;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU; mso-bidi-font-weight: bold;">46.18.1, 46.46.1, 47.73</span></p>\r\n</td>\r\n<td style="width: 282px; border: 1pt solid windowtext; padding: 0.75pt; height: 52px; background-color: #ffffff;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU; mso-bidi-font-weight: bold;">20</span></p>\r\n</td>\r\n<td style="width: 261px; border: 1pt solid windowtext; padding: 0.75pt; height: 52px; background-color: #ffffff;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU; mso-bidi-font-weight: bold;">0</span></p>\r\n</td>\r\n<td style="width: 227px; border: 1pt solid windowtext; padding: 0.75pt; height: 52px; background-color: #ffffff;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU; mso-bidi-font-weight: bold;">0</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 52px;">\r\n<td style="width: 879px; border: 1pt solid windowtext; padding: 0.75pt; height: 52px; background-color: #ffffff;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU; mso-bidi-font-weight: bold;">ИП, применяющие патентную систему налогообложения, &ndash; в отношении выплат и вознаграждений работников, которые заняты в патентном виде деятельности. При некоторых видах деятельности данная &laquo;льгота&raquo; не применяется (пп. 9 п. 1, пп. 3 п. 2 ст. 427 НК РФ в ред., действ. с 01.01.2017)</span></p>\r\n</td>\r\n<td style="width: 177px; border: 1pt solid windowtext; padding: 0.75pt; height: 52px; background-color: #ffffff;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU; mso-bidi-font-weight: bold;">31.0, 74.20, 75.0, 96.01, 96.02 и др.</span></p>\r\n</td>\r\n<td style="width: 282px; border: 1pt solid windowtext; padding: 0.75pt; height: 52px; background-color: #ffffff;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU; mso-bidi-font-weight: bold;">20</span></p>\r\n</td>\r\n<td style="width: 261px; border: 1pt solid windowtext; padding: 0.75pt; height: 52px; background-color: #ffffff;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU; mso-bidi-font-weight: bold;">0</span></p>\r\n</td>\r\n<td style="width: 227px; border: 1pt solid windowtext; padding: 0.75pt; height: 52px; background-color: #ffffff;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: center; line-height: normal;" align="center"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU; mso-bidi-font-weight: bold;">0</span></p>\r\n</td>\r\n</tr>\r\n<tr style="height: 52px;">\r\n<td style="width: 879px; border: 1pt solid windowtext; padding: 0.75pt; height: 52px; background-color: #ffffff;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU; mso-bidi-font-weight: bold;">Некоммерческие организации на УСН, кроме государственных и муниципальных учреждений, ведущие деятельность в сфере социального обслуживания граждан, научных исследований и разработок, образования, здравоохранения, культуры, искусства и массового спорта (пп. 7 п. 1, пп. 3 п. 2, п. 7 ст. 427 НК РФ в ред., действ. с 01.01.2017)</span></p>\r\n</td>\r\n<td style="width: 177px; border: 1pt solid windowtext; padding: 0.75pt; height: 52px; background-color: #ffffff;">\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; line-height: normal;"><span style="font-size: 10.0pt; font-family: ''Arial'',''sans-serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU; mso-bidi-font-weight: bold;">37, 86, 87, 88, 93 и др.</span></p