INSERT INTO `j7_content_v3` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(1, 33, 'Новости', 'novosti', '<h1><span style="color: #174f3b;"><strong><span style="font-family: arial black,avant garde; font-size: 14pt;">&nbsp;</span></strong><span style="font-family: times new roman,times; color: #0000ff;"><strong><span style="font-size: 14pt;">Новости</span></strong></span></span></h1>\r\n<p><span style="color: #3366ff;">\r\n<table border="0">\r\n<tbody>\r\n<tr>\r\n<td><span style="color: #000000;"><span style="font-size: 12pt; font-family: times new roman,times;"><a href="images/2323.doc"><span style="color: #000000;">Отмена вмененного налога начнется с 2018 года</span></a></span><span style="font-size: 12pt; font-family: times new roman,times;">&nbsp;</span></span></td>\r\n</tr>\r\n<tr>\r\n<td><a href="images/%20%20%20.doc"><span style="color: #000000; font-size: 12pt; font-family: times new roman,times;"><span style="color: #000000;">Новый закон о бухучёте с 2013 года – дополнительная финансовая нагрузка на малый бизнес</span></span></a></td>\r\n</tr>\r\n<tr>\r\n<td><a href="images/21.doc"><span style="color: #000000; font-size: 12pt; font-family: times new roman,times;"><span class="l"><span style="color: #000000;">Измененная счет-фактура со 2 квартала 2012</span></span></span></a></td>\r\n</tr>\r\n<tr>\r\n<td><a href="images/212.doc"><span style="color: #000000; font-size: 12pt; font-family: times new roman,times;"><span class="l"><span style="color: #000000;">Снижение ставки страховых взносов в 2012 году</span></span></span></a></td>\r\n</tr>\r\n<tr>\r\n<td><span style="font-family: times new roman,times;"><a href="images/373.doc"><span style="font-size: 12pt; color: #000000;"><span class="l">Новые правила кассовой дисциплины с 2012 года</span></span></a><a href="http://base.consultant.ru/cons/cgi/online.cgi?req=doc;base=LAW;n=122311"><span style="color: #000000; font-size: 12pt;"><span class="l"><span style="color: #000000;"><br data-mce-bogus="1" /></span></span></span></a></span></td>\r\n</tr>\r\n<tr>\r\n<td><span style="font-family: times new roman,times;"><a href="images/030408.doc"><span style="color: #000000; font-size: 12pt;"><span class="l"><span style="color: #000000;">Вычеты по НДФЛ</span></span></span></a><a href="http://base.consultant.ru/cons/cgi/online.cgi?req=doc;base=LAW;n=124020"><span style="color: #000000; font-size: 12pt;"><span class="l"><span style="color: #000000;"><br data-mce-bogus="1" /></span></span></span></a></span></td>\r\n</tr>\r\n<tr>\r\n<td><span style="font-family: times new roman,times;"><a href="images/1111.doc"><span style="color: #000000; font-size: 12pt;"><span class="l"><span style="color: #000000;">Новые формы бухгалтерской отчетности</span></span></span></a><a href="http://base.consultant.ru/cons/cgi/online.cgi?req=doc;base=LAW;n=123561"><span style="color: #000000; font-size: 12pt;"><span class="l"><span style="color: #000000;"><br data-mce-bogus="1" /></span></span></span></a></span></td>\r\n</tr>\r\n<tr>\r\n<td><span style="font-family: times new roman,times;"><a href="images/182.doc"><span style="color: #000000; font-size: 12pt;"><span class="l"><span style="color: #000000;">Новые КБК</span></span></span></a><a href="http://base.consultant.ru/cons/cgi/online.cgi?req=doc;base=LAW;n=124620"><span style="color: #000000; font-size: 12pt;"><span class="l"><span style="color: #000000;"><br data-mce-bogus="1" /></span></span></span></a></span></td>\r\n</tr>\r\n<tr>\r\n<td><span style="font-family: times new roman,times; font-size: 12pt; color: #000000;"><a href="images/4.XLS"><span style="color: #000000;">Новая форма отчета в ФСС за 1 квартал 2012</span></a></span></td>\r\n</tr>\r\n<tr>\r\n<td><span style="font-family: times new roman,times; font-size: 12pt; color: #000000;"><a href="images/prikaz_4_fss_2012_pril_1.doc"><span style="color: #000000;"> ФСС новые шифры страхователей</span></a></span></td>\r\n</tr>\r\n<tr>\r\n<td><span style="font-family: times new roman,times; font-size: 14pt;"><span style="color: #000000;"><a href="images/0107121.doc"><span style="font-size: 12pt; color: #000000;">Патентная система с 2013 г.</span></a></span> <br /></span></td>\r\n</tr>\r\n<tr>\r\n<td><span style="font-family: arial black,avant garde; font-size: 14pt;"><span style="color: #000000; font-family: times new roman,times;"><a href="images/0107122.doc"><span style="font-size: 12pt; color: #000000;">Переход на ЕНВД&nbsp; с 2013г. в добровольном порядке</span></a></span><br /></span></td>\r\n</tr>\r\n<tr>\r\n<td><span style="font-family: times new roman,times;"><a href="images/0107213.doc"><span style="font-size: 14pt;"><span style="color: #000000;"><span style="font-size: 12pt; color: #000000;">Упрощенная система с 2013 г.</span></span></span></a></span></td>\r\n</tr>\r\n<tr>\r\n<td></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</span></p>\r\n<p><span style="color: #3366ff;">&nbsp;</span></p>', '', 1, 2, '2012-02-25 07:35:09', 42, '', '2012-09-13 16:04:34', 42, 0, '0000-00-00 00:00:00', '2012-02-25 07:35:09', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":null,"urlatext":"","targeta":"","urlb":null,"urlbtext":"","targetb":"","urlc":null,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 36, 67, 'Новости налогообложение 2012, изменения в налоговом учете, новый закон о бухгалтерском учете', 'Новости налогообложение', 1, 1027, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(2, 34, 'Аутсорсинг бухучета, юридические услуг', 'autsorsing-bukhucheta-yuridicheskie-uslugi', '<h1 style="text-align: left;"><span style="color: #333399; font-size: 14pt; font-family: times new roman,times;"><strong><span style="color: #0000ff;"><span style="font-size: 12pt;">Преимущества</span> <span style="font-size: 12pt;">о<span style="color: #333399; font-family: times new roman,times;"><strong><span style="color: #0000ff;"><span style="color: #000000; font-family: times new roman,times;"><span style="color: #0000ff;"><span style="color: #000000;"><strong style="color: #0000ff; font-size: 12pt;">рганизации - аутсорсера</strong></span></span></span></span></strong></span></span></span><br /></strong></span></h1>\r\n<div style="text-align: justify;"><span style="font-size: 10pt;"><span style="color: #000000; font-family: times new roman,times;">Смысл аутсорсинга сводится к следующему&nbsp; →&nbsp; сосредоточьте все ресурсы на том виде деятельности, который является основным для вашей организации, и передайте остальные поддерживающие или сопутствующие функции профессиональному партнеру.</span><span style="color: #000000; font-family: times new roman,times;"><img style="margin: 6px 8px 5px 5px; border-image: none; float: right;" alt="images6" src="images/images6.jpg" height="71" width="164" /></span></span></div>\r\n<div style="text-align: justify;">\r\n<div style="text-align: justify;"><span style="color: #000000; font-size: 10pt; font-family: times new roman,times;"><span style="color: #0000ff;"><span style="color: #000000;"><strong>Привлечение организации-аутсорсера имеет ряд преимуществ:</strong></span></span></span></div>\r\n<div style="text-align: justify;">\r\n<ul>\r\n<li style="color: #000000; font-size: 12pt; font-family: arial black,avant garde;"><span style="font-size: 10pt;"><span style="font-family: times new roman,times;"><span style="color: #000000;">п</span>оскольку организация- заказчик передает аутсорсеру часть функций, то он имеет возможность сконцентрировать все внимание на основной деятельности организации. Кроме т</span><span style="color: #000000; font-family: times new roman,times;"></span><span style="font-family: times new roman,times;">ого, ранее задействованные ресур</span><span style="font-family: times new roman,times;">сы организации можно перераспределить и инвестировать в поддержку основного бизнеса.</span></span></li>\r\n<li style="color: #000000; font-size: 12pt; font-family: arial black,avant garde;"><span style="font-size: 10pt;"><span style="font-family: times new roman,times;">нередко услуги организации-аутсорсера обходятся дешевле, чем работы своими силами. В рыночных условиях успех обеспечен тем организациям, которые ведут свой бизнес наиболее эффек</span><span style="color: #000000; font-family: times new roman,times;"></span><span style="font-family: times new roman,times;">тивным способом, при этом снижая затраты и сохраняя высокое качество товаров и услуг.</span></span></li>\r\n<li style="color: #000000; font-size: 12pt; font-family: arial black,avant garde;"><span style="font-family: times new roman,times; font-size: 10pt;">возможность сокращения штата организации.</span></li>\r\n<li style="color: #000000; font-size: 12pt; font-family: arial black,avant garde;"><span style="color: #000000; font-size: 10pt; font-family: times new roman,times;">более качественное выполнение отдельных функций организации специализированными фирмами.</span><span style="color: #000000; font-size: 10pt; font-family: times new roman,times;">&nbsp;&nbsp;&nbsp; <br /></span></li>\r\n</ul>\r\n</div>\r\n</div>\r\n<div style="text-align: justify;"><span style="font-size: 10pt;"><span style="color: #000000; font-family: times new roman,times;"> Для успешного ведения бизнеса вовсе не обязательно, выполнять все непрофильные функции, связанные с основным видом деятельности организации, или с управлением компанией, своим персонал</span><span style="color: #000000; font-family: times new roman,times;">ом, можно возложить ведение этих процессов и на специализированную организацию. Под аутсорсингом понимается передача на договорной основе непрофильных функций субъекта внешним исполнителям, </span><span style="color: #000000; font-family: times new roman,times;">специализирующимся в конкретной области и обладающим знаниями, опытом, техническим оснащением.&nbsp;&nbsp;&nbsp;&nbsp;</span></span></div>\r\n<div style="text-align: justify;"><span style="color: #000000; font-size: 10pt; font-family: times new roman,times;">&nbsp; &nbsp;&nbsp; </span></div>\r\n<div style="text-align: justify;"><span style="font-size: 10pt;"><span style="color: #000000; font-family: times new roman,times;">Передача части работ на аутсорсинг позволяет сократить издержки, так как зачастую услуги аутсорсера стоят намного дешевле, чем содержание собственного персонала. Исходя</span><span style="color: #000000; font-family: times new roman,times;"></span><span style="color: #000000; font-family: times new roman,times;"> из своих целей и имеющихся ресу</span><span style="color: #000000; font-family: times new roman,times;">рсов, каждая организация сама решает отдавать ту или иную часть собственного бизнеса на аутсорсинг, или выполнять ее самостоятельно.</span><span style="color: #000000; font-family: times new roman,times;"><span style="color: #0000ff;"><br /></span></span></span></div>', '', 1, 2, '2012-02-25 07:35:28', 42, '', '2014-10-11 06:29:18', 42, 0, '0000-00-00 00:00:00', '2012-02-25 07:35:28', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":null,"urlatext":"","targeta":"","urlb":null,"urlbtext":"","targetb":"","urlc":null,"urlctext":"","targetc":""}', '{"show_title":"0","link_titles":"0","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 56, 66, 'бухгалтерский учет ведение Екатеринбург, консультация по бухучету, налогам, юридическая консультация, юридическая помощь', 'Преимущества аутсорсинга бухгалтерского учета', 1, 2184, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(3, 35, 'ОБУЧЕНИЕ - ТРЕНИНГИ  и КУРСЫ повышения квалификации В ЕКАТЕРИНБУРГЕ', 'kursy-povysheniya-kvalifikatsii-bukhgaltera', '<h1 style="text-align: justify;"><span style="color: #333399;"><span style="color: #333399;"><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;"><strong>ОБУЧЕНИЕ - ТРЕНИНГИ и КУРСЫ повышения квалификации В ЕКАТЕРИНБУРГЕ&nbsp; открывают новые возможности&nbsp;</strong> </span><br /></span></span></h1>\r\n<div style="text-align: justify;"><img style="margin-right: 6px; float: left;" alt="images2" src="images/images2.jpg" height="136" width="210" /><span style="font-family: times new roman,times; font-size: 12pt;"> А также дает&nbsp; возможность получения&nbsp; смежной профессии, усовершенствование своих знаний в конкретном вопросе,&nbsp; решение наболевших вопросов. Кроме того, тренинги и курсы повышение квалификации - это зачастую обязательное требование не только работодателя, но и конкретных сфер деятельности. Ежегодное изменение законодательства в&nbsp; курсе которых Вам необходимо быть, чтобы оставаться профессионально востребованным. Сегоднешнее время требует непрерывного обучения и пополнения Ваших знаний. Именно для этого разрабатываются программы повышения квалификации, семинары, круглые столы.&nbsp;</span><span style="color: #9d206e;"><strong><span style="text-align: center; font-family: times new roman,times; font-size: 12pt;"></span></strong></span><span style="color: #9d206e;"><strong><span style="text-align: center; font-family: times new roman,times; font-size: 12pt;">&nbsp; <br /></span></strong></span></div>\r\n<div style="text-align: left;"><span style="font-family: times new roman,times; font-size: 12pt;">&nbsp;</span></div>\r\n<div style="text-align: left;"><span style="font-family: times new roman,times; font-size: 12pt;">Виды программ: </span><br />\r\n<div>\r\n<ul>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">программы повышение квалификации </span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">программы подготовки специальностям </span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">курсы профессиональной переподготовки</span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">семинары и круглые столы</span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">тренинги </span></li>\r\n</ul>\r\n</div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;">&nbsp;</span></div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;">&nbsp;</span></div>\r\n&nbsp;</div>\r\n<p>&nbsp;</p>\r\n<div style="text-align: left;"><span style="font-family: times new roman,times; font-size: 14pt; color: #000080;">&nbsp;</span></div>', '', 1, 2, '2012-02-25 07:36:09', 42, '', '2014-01-29 09:42:24', 42, 0, '0000-00-00 00:00:00', '2012-02-25 07:36:09', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":null,"urlatext":"","targeta":"","urlb":null,"urlbtext":"","targetb":"","urlc":null,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 228, 65, 'программы обучения, курсы повышения квалификации, семинары в Екатеринбурге. ОБУЧЕНИЕ - ТРЕНИНГИ  и КУРСЫ повышения квалификации В ЕКАТЕРИНБУРГЕ', 'ОБУЧЕНИЕ - ТРЕНИНГИ  и КУРСЫ повышения квалификации В ЕКАТЕРИНБУРГЕ. Курсы обучения от ЭмМенеджмент - доступные и эффективные программы. ', 1, 3665, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(4, 36, 'Карьера', 'karera', '<h1 style="text-align: justify;"><code style="text-align: justify;"><span style="font-family: arial black,avant garde; font-size: 10pt;"><strong><span style="font-size: 14pt; font-family: times new roman,times;">&nbsp;&nbsp;&nbsp;&nbsp;<span style="color: #0000ff; font-size: 12pt;"> Карьера</span></span></strong><br /></span></code></h1>\r\n<div style="text-align: justify;"><span style="font-size: 12pt;"><code style="text-align: justify;"><span style="font-family: arial black,avant garde;">&nbsp;&nbsp;&nbsp; <span style="font-family: times new roman,times;">Мы&nbsp;убеждены, что люди способны к&nbsp;постоянному совершенствованию и&nbsp;развитию, и&nbsp;именно эта способность представляет собой наиболее важный и&nbsp;долговременный источник повышения эффективности. Поэтому вы всегда рады целеустремленным кандидатам, готовым к постоянному профессиональному и личностному росту.</span></span><span style="font-family: times new roman,times;"> В&nbsp;коллективе нашей Компании преуспевают те,&nbsp;кто, обладая нетривиальным мышлением, умеет выделить главное, расставить приоритеты в&nbsp;своей работе и&nbsp;качественно реализовать поставленные задачи, т.е.&nbsp;— является настоящим профессионалом своего дела</span>.</code></span></div>\r\n<div style="text-align: justify;"><span style="font-size: 12pt;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><span style="font-family: times new roman,times; font-size: 12pt;"> </span></div>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt; color: #003366;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <span style="color: #000000;">Открытые вакансии</span></span></div>\r\n<p>\r\n<table border="0">\r\n<tbody>\r\n<tr>\r\n<td><span style="font-family: times new roman,times;"><span style="font-size: 12pt;">Менеджер по продажам</span> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; &nbsp; <br /></span></td>\r\n<td style="text-align: left;"><span style="font-family: times new roman,times;"><span style="font-size: 12pt;">35 000 &nbsp;</span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span></td>\r\n</tr>\r\n<tr>\r\n<td><span style="font-family: times new roman,times; font-size: 12pt;">Преподаватель по&nbsp; 1 С<br data-mce-bogus="1" /></span></td>\r\n<td><span style="font-family: times new roman,times; font-size: 12pt;">&nbsp;</span></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</p>\r\n<p><span style="font-family: arial black,avant garde; font-size: 10pt;">&nbsp;</span></p>', '', 1, 2, '2012-02-25 07:36:36', 42, '', '2014-05-08 08:07:39', 42, 0, '0000-00-00 00:00:00', '2012-02-25 07:36:36', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":null,"urlatext":"","targeta":"","urlb":null,"urlbtext":"","targetb":"","urlc":null,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 19, 64, '', '', 1, 1761, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(5, 37, 'Компания', 'kompaniya', '<h1 style="margin-top: 0px; margin-right: 0px; margin-bottom: 0.7em; margin-left: 0px; line-height: 1.4em; font-size: 2em; color: #dc2d21; font-family: Arial, Geneva, sans-serif; text-align: left; background-color: #f3f3f3; padding: 0px;">Компания</h1>', '', 1, 2, '2012-02-25 07:36:46', 42, '', '0000-00-00 00:00:00', 0, 0, '0000-00-00 00:00:00', '2012-02-25 07:36:46', '0000-00-00 00:00:00', '', '', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":""}', 1, 63, '', '', 1, 95, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(6, 38, 'Контакты', 'kontakty', '<h1><span style="color: #333399;"><strong>&nbsp;&nbsp;</strong> </span><strong><span style="color: #000080; font-family: times new roman,times; font-size: 12pt;">Контакты</span></strong></h1>\r\n<table style="width: 521px; height: 226px;" border="1">\r\n<tbody>\r\n<tr>\r\n<td class="readmore">\r\n<div><strong>+</strong><span style="color: #000000; font-family: times new roman,times; font-size: 12pt;">7(343)266-79-85&nbsp; <span><strong>+</strong><span style="color: #000000; font-family: times new roman,times; font-size: 12pt;">7(343)328-46-62 </span></span></span><span style="color: #000000; font-family: times new roman,times; font-size: 12pt;">будни с 09.00 до 18.00 </span><span style="color: #000000; font-family: times new roman,times; font-size: 12pt;"><span><span style="color: #000000; font-family: times new roman,times; font-size: 12pt;"></span><br /></span></span></div>\r\n<div><span style="color: #000000; font-family: times new roman,times; font-size: 12pt;">г. Екатеринбург, ул. Степана Разина 16 офис 412 </span><span style="color: #000000; font-family: times new roman,times;"><span style="font-size: 12pt;"><span data-action="dropdown.toggle" data-params="counter=71266:head.login" class="daria-action b-mail-dropdown__handle b-mail-dropdown__handle_user"><a href="mailto:ammanagment@yandex.ru">ammanagment@yandex.ru</a></span></span></span></div>\r\n<div><span style="font-family: times new roman,times;">&nbsp;</span></div>\r\n<div class="readmore"><span style="color: #000000; font-family: times new roman,times; font-size: 12pt;">Реквизиты <br /></span></div>\r\n<span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"><span style="font-size: 12pt; font-family: ''Times New Roman'';">ЧУДПО "ЭмМенеджмент" ОГРН <span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">1126600000570</span></span></span><br /></span></span>\r\n<di