INSERT INTO `j7_content_v3` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(7, 39, 'Главная', 'glavnaya', '<p style="margin: 0px 0px 0.5em; font-style: inherit; font-variant: inherit; font-size: inherit; font-size-adjust: inherit; font-stretch: inherit; -moz-font-feature-settings: inherit; -moz-font-language-override: inherit; vertical-align: baseline; font-weight: normal; color: #111111; line-height: 1; font-family: ''Helvetica Neue'',Arial,Helvetica,sans-serif; border-width: 0px; padding: 0px; text-align: center;"><span style="color: #000080; font-size: 10pt;">&nbsp;<img style="float: left;" src="data:image/png;base64," alt="" height="368" width="736" /></span></p>\r\n<p style="margin: 0px 0px 0.5em; font-style: inherit; font-variant: inherit; font-size: inherit; font-size-adjust: inherit; font-stretch: inherit; -moz-font-feature-settings: inherit; -moz-font-language-override: inherit; vertical-align: baseline; font-weight: normal; color: #111111; line-height: 1; font-family: ''Helvetica Neue'',Arial,Helvetica,sans-serif; border-width: 0px; padding: 0px; text-align: justify;"><span style="color: #000080; font-size: 10pt;"><br /></span></p>\r\n<p style="margin: 0px 0px 0.5em; font-style: inherit; font-variant: inherit; font-size: inherit; font-size-adjust: inherit; font-stretch: inherit; -moz-font-feature-settings: inherit; -moz-font-language-override: inherit; vertical-align: baseline; font-weight: normal; color: #111111; line-height: 1; font-family: ''Helvetica Neue'',Arial,Helvetica,sans-serif; border-width: 0px; padding: 0px; text-align: left;"><span style="color: #000080; font-size: 10pt;"><br /></span></p>\r\n<p style="margin: 0px 0px 0.5em; font-style: inherit; font-variant: inherit; font-size: inherit; font-size-adjust: inherit; font-stretch: inherit; -moz-font-feature-settings: inherit; -moz-font-language-override: inherit; vertical-align: baseline; font-weight: normal; color: #111111; line-height: 1; font-family: ''Helvetica Neue'',Arial,Helvetica,sans-serif; border-width: 0px; padding: 0px; text-align: left;"><span style="color: #000080; font-size: 10pt;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span></p>\r\n<p style="text-align: justify;"><span style="color: #000080; font-size: 12pt;"><span style="font-family: arial,helvetica,sans-serif;"><span style="color: #003366;">Добро пожаловать на сайт группы <strong>ЭмМенеджмент</strong>. Наша компания создана в 2010 году и является одной из профильном на&nbsp; рынке услуг. Все&nbsp; время мы сохраняем наш главный принцип работы — <strong>своевременость, достоверность, независимость, гибкий новационный подход</strong> к поставленным задачам.</span></span></span></p>\r\n<p style="text-align: justify;"><span style="color: #003366; font-size: 12pt; font-family: arial,helvetica,sans-serif;"><strong>Эммнеджмент</strong> оказывает <strong>весь спектр&nbsp; услуг</strong> — от дополнительного образования&nbsp; до многоэтапных консалтинговых проектов. <br /></span></p>\r\n<p style="text-align: justify;"><span style="color: #003366; font-size: 12pt; font-family: arial,helvetica,sans-serif;">Наша команда высококвалифицированных специалистов в области управления, бухгалтерского, налогового и правового консультирования, разрабатывает высокоэффективные решения для успешного ведения бизнеса. Дополнительное образование осуществляется только преподавателями практиками, специализирующими&nbsp; в области преподаваемых&nbsp; предметов.</span></p>\r\n<p style="text-align: justify;"><span style="color: #003366; font-size: 12pt; font-family: arial,helvetica,sans-serif;">Работа&nbsp; с нашей компанией&nbsp; станет для вас по-настоящему профессиональной деятельностью, приносящей удовлетворение и прибыль.</span></p>\r\n<p style="text-align: justify;"><span style="color: #003366; font-size: 12pt; font-family: arial,helvetica,sans-serif;"><strong>Консалтинговая группа «ЭмМенеджмент» специализируется на основных направлениях:</strong></span></p>\r\n<p style="text-align: justify;"><span style="font-size: 12pt;"><a href="index.php?option=com_content&amp;view=article&amp;id=8">Бухгалтерские, аудиторские услуги:</a></span></p>\r\n<ul style="list-style-type: circle; text-align: justify;">\r\n<li><span style="color: #003366; font-size: 12pt; font-family: arial,helvetica,sans-serif;">Ведение и восстановление бухгалтерского учета</span></li>\r\n<li><span style="color: #003366; font-size: 12pt; font-family: arial,helvetica,sans-serif;">Консультации в области бухгалтерского учета и налогообложения</span></li>\r\n<li><span style="color: #003366; font-size: 12pt; font-family: arial,helvetica,sans-serif;">Аудит</span></li>\r\n</ul>\r\n<p style="text-align: justify;"><span style="color: #003366; font-size: 12pt; font-family: arial,helvetica,sans-serif;"><strong>&nbsp;&nbsp;&nbsp;&nbsp; Финансовые услуги:</strong></span></p>\r\n<ul style="list-style-type: circle; text-align: justify;">\r\n<li>\r\n<div><span style="color: #003366; font-size: 12pt; font-family: arial,helvetica,sans-serif;">Со<span class="joomla-footer">ставление бизнес-планов</span></span></div>\r\n</li>\r\n<li>\r\n<div><span style="color: #003366; font-size: 12pt; font-family: arial,helvetica,sans-serif;">Проведение анализа финансово-хозяйственной деятельности предприятия</span></div>\r\n</li>\r\n<li>\r\n<div><span style="color: #003366; font-size: 12pt; font-family: arial,helvetica,sans-serif;">Помощь в пол<span class="readmore">учении финанс</span>ирования деятельности (кредитный брокеридж)</span></div>\r\n</li>\r\n<li>\r\n<div><span style="color: #003366; font-size: 12pt; font-family: arial,helvetica,sans-serif;">Управление рисками (налоговыми, административными)</span></div>\r\n</li>\r\n</ul>\r\n<p style="text-align: justify;"><span style="color: #003366; font-size: 12pt; font-family: arial,helvetica,sans-serif;"><strong>&nbsp;&nbsp;&nbsp;&nbsp; Образовательные услуги:</strong></span></p>\r\n<ul style="list-style-type: circle; text-align: justify;">\r\n<li><span style="color: #003366; font-size: 12pt; font-family: arial,helvetica,sans-serif;">&nbsp; Поэтапное повышение квалификации бухгалтеров</span></li>\r\n<li><span style="color: #003366; font-size: 12pt; font-family: arial,helvetica,sans-serif;">&nbsp; Освоение бухгалтерского и налогового учета "для не&nbsp;&nbsp;&nbsp; бухгалтеров"&nbsp;</span></li>\r\n<li><span style="color: #003366; font-size: 12pt; font-family: arial,helvetica,sans-serif;">&nbsp; Разовые&nbsp; семинары</span></li>\r\n</ul>\r\n<p style="text-align: justify;"><span style="color: #003366; font-size: 12pt; font-family: arial,helvetica,sans-serif;"><strong>&nbsp;&nbsp;&nbsp;&nbsp;<a href="index.php?option=com_content&amp;view=article&amp;id=14"> Юридические услуги:</a></strong></span></p>\r\n<ul style="list-style-type: circle;">\r\n<li style="text-align: justify;"><span style="color: #003366; font-size: 12pt; font-family: arial,helvetica,sans-serif;">Регистрация предприятий</span></li>\r\n<li style="text-align: justify;"><span style="color: #003366; font-size: 12pt; font-family: arial,helvetica,sans-serif;">Абонентское обслуживание</span></li>\r\n<li style="text-align: justify;"><span style="color: #003366; font-family: arial,helvetica,sans-serif; font-size: 12pt;">Представительство в судебных органах</span></li>\r\n</ul>', '', -2, 2, '2012-02-25 07:41:08', 42, '', '2012-03-01 19:27:39', 42, 0, '0000-00-00 00:00:00', '2012-02-25 07:41:08', '0000-00-00 00:00:00', '', '', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":""}', 20, 4, '', '', 1, 284, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content_v3` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(8, 41, 'Бухгалтерские  услуги Екатеринбург', 'malyj-biznes-i-ego-problemy-v-sfere-bukhucheta', '<h1 style="text-align: justify;"><span style="font-size: 12pt; font-family: times new roman,times; color: #0000ff;">&nbsp;Бухгалтерские услуги</span><span style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #0000ff;"><strong style="font-size: 14pt; font-family: times new roman,times; color: #000080;"> </strong></span><span style="color: #800080;"><strong><span style="color: #0000ff;"> и вопросы связанные с ведением</span></strong><span style="color: #0000ff;"> </span></span><span style="color: #0000ff;">бухгалтерского и налогового учета </span><span style="color: #800080;"><strong> </strong></span><span style="color: #800080;"><strong><span style="color: #0000ff;"></span></strong></span></span><span style="color: #800080; font-size: 12pt;"><strong><span style="font-family: times new roman,times;"><br style="color: #0000ff;" /></span></strong></span></h1>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: times new roman,times; color: #000000;">&nbsp; Любая, даже очень небольшая компания сталкивается с вопросом постановки и ведения бухгалтерского и налогового учета. В связи с этим возникает определенный круг вопросов:</span></p>\r\n<ul>\r\n<li style="text-align: justify;"><span style="font-size: 10pt; font-family: times new roman,times; color: #000000;">Руководитель не может оценить уровень профессионализма бухгалтера. Очень распространено заблуждение о том, что можно дать оценку специалисту, оценив его личные качества. А ведь любой руководитель, не владея навыками hr-специалиста, опирается, в первую очередь, на свою личностную, очень субъективную оценку.</span></li>\r\n<li style="text-align: justify;"><span style="font-size: 10pt; font-family: times new roman,times; color: #000000;">Часто у предпринимателя нет возможностей нанять в свою компанию высококвалифицированного бухгалтера, поскольку грамотный и опытный бухгалтер, особенно в Екатеринбурге, стоит недешево. Соответственно, руководитель принимает решение о том, что наймет бухгалтера позже, а пока будет вести бухгалтерский учет сам, либо наймет бухгалтера с более низкими требованиями к заработной плате. И в том, и в другом случае придется восстанавливать бухгалтерский учет спустя какое-то время, но это будет стоит в два, а то и в три раза дороже «сэкономленных денег».</span></li>\r\n<li style="text-align: justify;"><span style="font-size: 10pt; font-family: times new roman,times; color: #000000;">Более того, владелец малого бизнеса не всегда готов выложить&nbsp; сумму за специализированное бухгалтерское программное обеспечение. По большому счету, такая ситуация возникает от недопонимания того насколько важно грамотно вести бухгалтерский, налоговый учет. А также от неспособности разобраться в ассортименте и определиться в выборе программных средств.</span></li>\r\n</ul>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: times new roman,times; color: #000000;">&nbsp;&nbsp;&nbsp; &nbsp;&nbsp; Все эти аргументы говорят только в пользу <strong>Аутсорсинга бухгалтерского учета</strong>.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: times new roman,times; color: #000000;">Однако отметим, что немало компаний, перейдя на бухгалтерский аутсорсинг, остались им недовольны. Необходимо тщательно и внимательно выбирать бухгалтерскую компанию. И вот именно здесь следует обратить внимание не только на профессионализм, но и на личностное отношение к делу. Основной критерий здесь — это качество и своевременность необходимой Вам информации, запрашиваемой у сотрудника.</span></p>\r\n<p style="text-align: justify;"><span style="font-size: 10pt; font-family: times new roman,times; color: #000000;">&nbsp;В целом взаимоотношения Бухгалтерской компании и компании-Клиента строятся на основании договора на оказание услуг. Подробно прописанные положения договора и доброжелательные профессиональные отношения&nbsp; со своими Клиентами значительно снижают риски и повышают прозрачность деятельности, что, естественно, самым наилучшим образом сказывается на Вашем бизнесе&nbsp;&nbsp; </span></p>\r\n<p><span style="font-size: 12pt; font-family: times new roman,times; color: #000000;"><span style="font-size: 10pt;"><strong>БУХГАЛТЕРСКИЕ УСЛУГИ</strong>&nbsp;</span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; &nbsp; <br /></span></p>\r\n<p style="text-align: justify;"><span style="color: #000000; font-size: 10pt; font-family: times new roman,times;">Стоимость обслуживания определяется индивидуально (по результатам экспертизы).Факторов влияющих на стоимость обслуживания очень много, это количество: операций, первичных документов, сотрудников для которых необходим расчет заработной платы, кто занимается первичной документаций: мы или заказчик, система налогообложения и т.д. Мы разработали удобную и эффективную схему обслуживания наших клиентов позволяющую максимально просто определить систему и стоимость наших услуг&nbsp;&nbsp;&nbsp; &nbsp;&nbsp; &nbsp;&nbsp; </span></p>\r\n<p style="text-align: justify;"><span style="font-family: times new roman,times; color: #000000; font-size: 10pt;">Консультации осуществляются в форме беседы. Перед встречей между специалистом и заказчиком, последнему необходимо представить письменный запрос с указанием ситуации и с перечнем вопрос для обсуждения.&nbsp;</span></p>\r\n<p><span style="color: #000000; font-size: 12pt; font-family: times new roman,times;"></span><span style="color: #000000; font-size: 12pt; font-family: arial black,avant garde;">\r\n<table style="width: 631px; height: 150px;" border="0">\r\n<tbody>\r\n<tr>\r\n<td><span style="font-family: times new roman,times; color: #000000; font-size: 10pt;">Бухгалтерский аутсорсинг</span></td>\r\n<td style="text-align: center;"><span style="font-family: times new roman,times; color: #000000; font-size: 10pt;">от 5000&nbsp; <br /></span></td>\r\n</tr>\r\n<tr>\r\n<td><span style="color: #000000; font-size: 10pt; font-family: times new roman,times;">Восстановление бухгалтерского учета</span></td>\r\n<td><span style="font-family: times new roman,times; color: #000000; font-size: 10pt;">от 10000</span></td>\r\n</tr>\r\n<tr>\r\n<td><span style="color: #000000; font-size: 10pt; font-family: times new roman,times;">Абонентское консультирование по вопросам бухгалтерского и налогового учета</span></td>\r\n<td><span style="color: #000000; font-size: 10pt; font-family: times new roman,times;">от 3000</span></td>\r\n</tr>\r\n<tr>\r\n<td><span style="color: #000000; font-size: 10pt; font-family: times new roman,times;">Устные консультации по вопросам бухгалтерского, налогового учета, праву</span></td>\r\n<td><span style="color: #000000; font-size: 10pt; font-family: times new roman,times;">&nbsp;от 1200</span></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</span></p>', '', 1, 2, '2012-02-26 08:07:01', 42, '', '2014-05-08 10:48:03', 42, 0, '0000-00-00 00:00:00', '2012-02-26 08:07:01', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":null,"urlatext":"","targeta":"","urlb":null,"urlbtext":"","targetb":"","urlc":null,"urlctext":"","targetc":""}', '{"show_title":"0","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 40, 61, 'Бухгалтерские услуги, консультация по налогам, консультация по бухгалтерскому учету, ведение бухгалтерского учета, восстановление бухгалтерского учета', 'Бухгалтерские услуги в Екатеринбурге и ведение бухгалтерского учета ', 1, 1881, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(9, 46, 'Курсы  Бухгалтерские  - бухгалтерский учет, обучение налоги 1 С Бухгалтерия 8  - базовый курс бухгалтера', 'kursy-nachinayushchikh-bukhgalterov-ekaterinburg', '<h1 style="text-align: justify;"><span style="font-family: times new roman,times; color: #3d5200;"><span style="color: #0000ff; font-size: 12pt;"><strong>Бухгалтерские курсы&nbsp; - обучение бухгалтерскому учету, налогам и 1 С 8.2 8.3 Бухгалтерии + 1&nbsp; С 8 </strong></span><span style="font-size: 12pt; color: #0000ff;"><strong><span style="font-family: times new roman,times; font-size: 12pt;">Зарплата (</span></strong></span><span style="color: #0000ff; font-size: 12pt;"><strong style="font-family: times new roman,times; font-size: 12pt;">базовый курс)</strong></span><span style="font-size: 14pt;"><strong style="color: #8c2223;"><br style="color: #8c2223;" /></strong></span></span></h1>\r\n<p><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-size: 12pt; font-family: times new roman,times;"><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';"><strong>Целевая аудитория</strong>: бухгалтер, главный бухгалтер, экономист, финансовый директор, руководитель, предприниматель<br /></span></span></span></p>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #800080;"><span style="color: #000000;"><strong>Ведущие: </strong></span><span style="color: #000000;"><span style="font-family: times new roman,times;">Насонова Надежда Юрьевна</span> -</span> <span style="color: #000000;">финансовый директор, пратикующий бухгалтер</span></span> </span></div>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: times new roman,times;"> Прокопьева Зоя Александровна- главный госналогинспектор</span></span></div>\r\n<div><span style="font-family: times new roman,times; color: #3d5200; font-size: 12pt;"><span style="color: #0000ff;"><span style="font-family: times new roman,times; color: #000000;">Тимофеева Ирина Аркадьевна - практикующий главный бухгалтер &nbsp;</span><strong><br /></strong></span></span></div>\r\n<p><span style="font-family: times new roman,times; font-size: 12pt; color: #800080;"><span style="color: #000000;"><strong style="font-family: times new roman,times; font-size: 12pt;">После окончания курса вы сможете</strong></span> <br /></span></p>\r\n<ul style="list-style-type: disc;">\r\n<li>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt; color: #000000;"><span style="font-family: times new roman,times;"><span style="font-family: times new roman,times;">работать как бухгалтером, так и&nbsp; бухгалтером со сдачей отчетности&nbsp; предприятия.</span></span></span></div>\r\n</li>\r\n<li style="text-align: justify;">\r\n<div><span style="font-family: times new roman,times; font-size: 12pt; color: #000000;">как руководитель - разбираться в тонкостях и оптимизации налогообложения </span></div>\r\n</li>\r\n<li style="text-align: justify;">\r\n<div><span style="font-family: times new roman,times; font-size: 12pt; color: #000000;">как предприниматель -&nbsp; сдавать и вести налоговую и бухгалтерскую отчетность</span></div>\r\n</li>\r\n<li>\r\n<div style="text-align: justify;"><span style="font-size: 12pt;"><span style="font-family: times new roman,times; color: #000000;"></span><span style="font-family: times new roman,times; color: #800080;"><span style="color: #000000;">как управленец&nbsp; - подбирать квалифицированных бухгалтеров </span></span><span style="color: #000000; font-family: times new roman,times;"><a href="index.php?option=com_content&amp;view=article&amp;id=19:kursy-bukhgalterskogo-ucheta&amp;catid=8:obrazovanie&amp;Itemid=170"><span style="font-family: times new roman,times; background-color: #ffffff;"><span style="color: #0000ff;"><span style="background-color: #ffffff; color: #0000ff;">Расписание курсов</span></span></span></a></span><span style="font-family: times new roman,times; color: #800080;"><span style="color: #000000;"></span> </span></span></div>\r\n</li>\r\n</ul>\r\n<div><span style="font-size: 12pt;"><span style="font-family: times new roman,times; color: #800080;"><span style="color: #000000;">&nbsp;</span></span><strong><span style="font-family: times new roman,times; color: #000000;">В программе</span></strong></span></div>\r\n<p><span style="font-size: 12pt;"><span style="font-family: times new roman,times; color: #800080;"></span><span style="color: #000000; font-family: times new roman,times;">Методика бухучета на примерах +&nbsp; бухгалтерская, налоговая отчетность: ОСНО, УСНО, ЕНВД </span><span style="color: #000000; font-family: times new roman,times;">+&nbsp; 1: С "Бухгалтерия" + 1 С "</span></span><span style="font-family: times new roman,times; color: #000000;"><span style="font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;">Зарплата и Управление персоналом"</span></span></span></p>\r\n<p><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;">1. Методика бухгалтерского учета:</span><br /><span style="font-family: times new roman,times; font-size: 12pt;">•&nbsp;&nbsp; &nbsp;понятия, виды хозяйственного учета, правовая основа бухучета, балансовый метод отражения информации, группировка балансовых статей, баланс предприятия,&nbsp; строение балансовых счетов, счета аналитические и синтетические, план счетов; </span><br /><span style="font-family: times new roman,times; font-size: 12pt;">•&nbsp;&nbsp;&nbsp; <strong>Новый закон о Бухгалтерском учете 402 ФЗ:</strong> бухгалтерские документы, классификация документов, требования, предъявляемые к составлению документов; </span><br /><span style="font-family: times new roman,times; font-size: 12pt;">•&nbsp;&nbsp; &nbsp;инвентаризация (понятие, случаи проведения, сроки, виды); </span><br /><span style="font-family: times new roman,times; font-size: 12pt;">•&nbsp;&nbsp; &nbsp;Законодательная база о Бухгалтерском учете, <strong>ПБУ (положения&nbsp; о бухучете), учетная политика в целях налогового и бухгалтерского учета.</strong></span><br /><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;">2. Порядок ведения объектов бухгалтерского учета:</span></p>\r\n<div style="text-align: left;"><span style="font-family: times new roman,times; font-size: 12pt;">•&nbsp;&nbsp; &nbsp;учет уставного капитала. Минимальный уставный капитал</span><br /><span style="font-family: times new roman,times; font-size: 12pt;">•&nbsp;&nbsp; &nbsp;учет денежных средств, учет операций по расчетному счету</span><br /><span style="font-size: 12pt;"><span style="font-family: times new roman,times;">•&nbsp;&nbsp; &nbsp;учет расчетов с подотчетными лицами, покупателями и поставщиками. </span><strong><span style="font-family: times new roman,times;">Нормируемые подотчетные суммы</span></strong></span><br /><span style="font-family: times new roman,times; font-size: 12pt;">•&nbsp;&nbsp; &nbsp;учет материально - производственных запасов </span><br /><span style="font-family: times new roman,times; font-size: 12pt;">•&nbsp;&nbsp; &nbsp;учет и оценка основных средств и нематериальных активов. <strong>Новые критерии НМА и ОС, отличия.</strong></span><br /><span style="font-size: 12pt;"><span style="font-family: times new roman,times;">•&nbsp;&nbsp; &nbsp;учет оплаты труда и страховых взносов. <strong>Системы оплаты труда, премии, удержания</strong></span>. <span style="font-family: times new roman,times;">Пособия. </span></span><span style="font-size: 12pt; font-family: times new roman,times;">Расчет больничных</span><br /><span style="font-size: 12pt;"><span style="font-family: times new roman,times;">•&nbsp;&nbsp; &nbsp;учет затрат на производство. </span><strong><span style="font-family: times new roman,times;">Методы оптимизации затрат</span></strong></span><br /><span style="font-family: times new roman,times; font-size: 12pt;">•&nbsp;&nbsp; &nbsp;учет готовой продукции и операций по ее реализации. <strong>Определение финансового результата.</strong><br /></span></div>\r\n<div style="text-align: left;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: times new roman,times;">•</span>&nbsp;&nbsp;&nbsp; учет будущих периодов, сомнительной задолженности (нормируемой)<br /></span></div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;">&nbsp; </span><br /><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;">3. Расчет финансового результата и составление бухгалтерской отчетности:</span><br /><span style="font-family: times new roman,times; font-size: 12pt;">•&nbsp;&nbsp; &nbsp;учет финансовых результатов; </span><br /><span style="font-family: times new roman,times; font-size: 12pt;">•&nbsp;&nbsp; &nbsp;бухгалтерская отчетность (баланс, отчет о прибылях и убытках).</span></div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;">- Практические задачи и заполнение бухгалтерской отчетности</span></div>\r\n<div style="text-align: justify;"><br /><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;">4. Налоги, налоговая отчетность:</span><br /><span style="font-size: 12pt;"><strong><span style="font-family: times new roman,times;">Общая система налогообложения</span></strong></span><br /><span style="font-family: times new roman,times; font-size: 12pt;"> •&nbsp;&nbsp; &nbsp;налог на добавленную стоимость</span><br /><span style="font-family: times new roman,times; font-size: 12pt;"> •&nbsp;&nbsp; &nbsp;налог на прибыль</span>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: times new roman,times;">•&nbsp;&nbsp; &nbsp;налог на имущество</span> </span><br /><span style="font-family: times new roman,times; font-size: 12pt;"> Страховые взносы, отчетность в Пенсионный фонд, Фонд социального страхования</span><br /><span style="font-family: times new roman,times; font-size: 12pt;">Налог на доходы физических лиц, вычеты стандартные и имущественные</span></div>\r\n<div><br /><span style="font-family: times new roman,times; font-size: 12pt;"> </span>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;">- Льготы по налогообложению, пониженные ставки по страховым взносам<br /></span></div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;">- Выбор оптимальных систем налогообложения<br /></span></div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;">- Нормируемые расходы в целях налогообложения<br /></span></div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;"><i> - Практические задачи и составление деклараций в ИФНС</i></span></div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;"><i>- Типичные ошибки&nbsp; при составление отчетности</i></span></div>\r\n<br /><span style="font-size: 12pt;"><strong><span style="font-family: times new roman,times;"> Специальные режимы налогообложения:</span></strong></span><br /><span style="font-family: times new roman,times; font-size: 12pt;"> УСНО, <span style="font-family: times new roman,times;">ЕНВД, </span>патентная система</span></div>\r\n</div>\r\n<ul style="list-style-type: disc;">\r\n<li>\r\n<div><span style="color: #000000; font-family: times new roman,times; font-size: 12pt;">смена налогового режима, порядок перехода</span></div>\r\n</li>\r\n<li>\r\n<div><span style="color: #000000; font-family: times new roman,times; font-size: 12pt;">порядок ведения книги учета доходов и расходов</span></div>\r\n</li>\r\n<li>\r\n<div><span style="color: #000000; font-family: times new roman,times; font-size: 12pt;"> совмещение спецрежимов</span></div>\r\n</li>\r\n<li>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #ff0000;"><span style="color: #000000;"> преимущества и недостатки УСНО</span></span>&nbsp;</span></div>\r\n</li>\r\n</ul>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;">5. Практические занятия в программе 1 С:</span>\r\n<ul>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">работа с программой 1С: «Бухгалтерия&nbsp; 8» в компьютерном классе<strong> по каждому объекту учета</strong>: денежные средства, расчеты с подотчетными лицами, расчеты с персоналом организации, учет основных средств и их амортизация, сырье, материалы,&nbsp; учет товаров, услуг, НДС, операции по завершению месяца, регламентированная отчетность - бухгалтерская и налоговая отчетность); <br /></span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">расчет заработной платы в <span style="color: #000000;"> 1: С&nbsp; Зарплата и Управление персоналом (ЗУП) или&nbsp;&nbsp;<span style="font-family: times new roman,times; font-size: 12pt;">1С: Бухгалтерия&nbsp; 8</span> по выбору слушателя</span><br /></span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">решение практических задач по бухгалтерскому&nbsp; и налоговому&nbsp; учету в учебной версии 1С: Бухгалтерия&nbsp; 8 на домашнем рабочем месте.</span><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;"> <br /></span></li>\r\n</ul>\r\n<p><span style="font-size: 12pt; font-family: times new roman,times; color: #0000ff;">6. Расчет оплаты труда. Основы кадрового делопроизводства. Типичные ошибки и штрафы.+ работа в 1:С ЗУП<br /></span></p>\r\n<ul>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times; color: #000000;">Прием, увольнение, карточка сотрудника</span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Трудовой договор, штатное расписание. </span></li>\r\n<li style="font-family: times new roman,times; font-size: 12pt;">Исчисление среднего заработка. 922 Постановление РФ.</li>\r\n<li style="font-family: times new roman,times; font-size: 12pt;">Учёт премий, сверхурочных, совместительства и совмещения, неполной занятости</li>\r\n<li style="font-family: times new roman,times; font-size: 12pt;">Отпуска. Основной отпуск: порядок предоставления, продолжительность, перенос отпуска, разделение отпуска на части, замена денежной компенсацией. Дополнительные и учебные отпуска. Применение Трудового кодекса РФ.</li>\r\n<li style="font-family: times new roman,times; font-size: 12pt;">Пособие по временной нетрудоспособности и в связи с материнством. 212 - ФЗ,&nbsp; 255 - ФЗ, 375 Постановление</li>\r\n<li style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;"> Расчёт командировочных </span></li>\r\n</ul>\r\n</div>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;">7.&nbsp; Основы составления договоров и&nbsp; основы аудиторской деятельности</span><br /><br /><span style="color: #0000ff; font-size: 12pt;"><span style="font-family: times new roman,times;">По итогу курса выполняется сдача зачета</span><span style="font-family: times new roman,times;">, на закрепление знаний и навыков</span></span><br /><span style="font-family: times new roman,times; font-size: 12pt; color: #008080;"></span></div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt; color: #008080;"><span style="font-family: times new roman,times; color: #008080;"></span></span>\r\n<div style="text-align: left;"><span style="color: #000000; font-size: 12pt;"><span style="font-family: times new roman,times;"><span style="color: #000000;"><strong>&nbsp; <br /></strong></span></span></span></div>\r\n</div>\r\n<div style="text-align: justify;"><span style="font-size: 12pt;"><span style="font-family: times new roman,times;">Продолжительность: 1.5 - 2 месяца, 3 раза в неделю, </span><span style="font-family: times new roman,times;">выдается методическая литература</span></span>.</div>\r\n<div style="text-align: justify;"><span style="font-size: 12pt; color: #000000;"><span style="font-family: times new roman,times;"><strong style="font-family: ''times new roman'',times; font-size: 16px; line-height: 24px; text-align: justify;"><span style="margin: 0px; padding: 0px; border: 0px none; font-family: inherit; font-size: inherit; font-style: inherit; font-variant: inherit; font-weight: inherit; line-height: inherit; vertical-align: baseline;"><span style="font-size: 12pt;"><span style="font-family: times new roman,times;">В случае отсутствия на занятиях по уважительным причинам предоставляются <span style="font-size: 12pt; color: #000000;"><span style="font-family: times new roman,times;"><strong style="font-family: ''times new roman'',times; font-size: 16px; line-height: 24px; text-align: justify;"><span style="margin: 0px; padding: 0px; border: 0px none; font-family: inherit; font-size: inherit; font-style: inherit; font-variant: inherit; font-weight: inherit; line-height: inherit; vertical-align: baseline;">Видео - лекции.</span></strong></span></span>&nbsp;</span><span style="font-family: times new roman,times;">&nbsp; </span></span></span></strong></span></span><br /><span style="font-size: 12pt;"><span style="font-family: times new roman,times;">Стоимость: 16500 рублей. <strong>Количество мест в группе ограничено! (до 12 слушателей)</strong></span><span style="font-family: times new roman,times;"><span style="font-family: times new roman,times;">&nbsp;<span style="color: #0000ff;"> <strong><a class="modal" href="#call_me" rel="{size:{x:460,y:130}}"><span style="color: #0000ff; background-color: #ffffff;">Отправить заявку</span></a></strong></span></span></span></span></div>\r\n<div style="text-align: justify;"><span style="font-size: 12pt; color: #000000;"><span style="font-family: times new roman,times;">Расписание: </span><span style="font-family: times new roman,times;"><strong>вечерние группы</strong> (вторник, четверг, пятница с 19.00 до 21.30) или <strong>"по выходным"</strong> - суббота воскресенье с 10.00 до 14.00 или с 14.00 до 18.00&nbsp; <br /></span></span></div>\r\n<div style="text-align: justify;"><span style="font-size: 12pt; color: #000000;"><span style="font-family: times new roman,times;"><strong style="font-family: ''times new roman'', times; font-size: 16px; line-height: 24px; text-align: justify;"><span style="margin: 0px; padding: 0px; border: 0px; font-family: inherit; font-size: inherit; font-style: inherit; font-variant: inherit; font-weight: inherit; line-height: inherit; vertical-align: baseline;">Для иногородних есть возможность пройти курсы дистанционного обучения. Видео - лекции.<br /></span></strong></span></span></div>\r\n<p style="font-family: times new roman,times; font-size: 12pt;"><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"><span style="color: #800080;">Скидка 5% </span>при оплате за 2&nbsp; недели до начала обучения, скидки от&nbsp; 2 - х слушателей </span><span style="font-family: times new roman,times; color: #800080;">10%</span></span><br /><br /><span style="font-size: 12pt;"><span style="font-family: times new roman,times;">Данный курс позволит вам повысить квалификацию, найти&nbsp; достойную работу, повысит свой личный доход за счет знаний и умений в различных объектах бухгалтерского налогового учета, минимизация налоговых рисков,&nbsp; оптимизация налогообложения</span>. </span><br /><span style="font-family: times new roman,times; font-size: 12pt;">Курсы проводятся в центре города в оснащенной компьютерами&nbsp; и проекторам аудитории.</span></p>\r\n<p><span style="font-family: times new roman,times; font-size: 12pt;"><a href="index.php?option=com_content&amp;view=article&amp;id=13:kursy-praktikuyushchij-bukhgalter-glavnyj-bukhgalter&amp;catid=2:uncategorised"><span style="color: #0000ff;"><span style="color: #0000ff;">Курсы главных бухгалтеров, практикующих бухгалтеров</span></span></a><br /></span></p>\r\n<p><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"><span style="font-family: times new roman,times;"><em> <span style="font-family: ''times new roman'',times;"><strong>Ключевые составляющие уффективных программ</strong></span></em><br /><span style="font-family: ''times new roman'',times;">Залог успеха&nbsp; − комплексное</span>&nbsp;<span style="font-family: ''times new roman'',times;">освещение всех аспектов финансового учета. Именно поэтому при составлении программы</span>&nbsp;<span style="font-family: ''times new roman'',times;">преподаватели традиционно уделяют внимание следующим вопросам:</span><br /><span style="font-family: ''times new roman'',times;">− бухгалтерский учет и аудит;</span><br /><span style="font-family: ''times new roman'',times;">− налоги, налоговая отчетность, системы налогообложения;</span><br /><span style="font-family: ''times new roman'',times;">− правовое регулирование деятельности физических и юридических лиц;</span><br /><span style="font-family: ''times new roman'',times;">− основы экономики предприятия.</span></span></span>&nbsp;</span></p>\r\n<div style="text-align: justify;"><span style="color: #000000; font-size: 12pt; font-family: times new roman,times;"> &nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;<span style="font-family: times new roman,times; font-size: 12pt; color: #000080;"><a class="modal" href="#call_me" rel="{size:{x:460,y:130}}"><span style="color: #000080;"></span></a></span><br /></span></div>', '', 1, 8, '2012-02-27 14:47:14', 42, '', '2014-11-28 07:54:02', 42, 0, '0000-00-00 00:00:00', '2012-02-27 14:47:14', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":null,"urlatext":"","targeta":"","urlb":null,"urlbtext":"","targetb":"","urlc":null,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 130, 0, 'курсы начинающих бухгалтеров, курсы бухгалтерский учет, курсы налоги, 1 с, Екатеринбург, бухгалтерские курсы, бухгалтерские курсы екатеринбург, бухгалтерия обучение, курсы бухгалтерского учета, 1 С бухгалтерия обучение', 'Бухгалтерские курсы -  обучение бухгалтерскому учету налогам  1 С Бухгалтерии  Эффективные бухгалтерские курсы.', 1, 4398, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(10, 48, 'Образование (2)', 'obrazovanie-2', '<p><a href="index.php?option=com_content&amp;view=article&amp;id=9:kursy-nachinayushchikh-bukhgalterov&amp;catid=11:kursy-nachinayushchikh-bukhgalterov"><span style="text-decoration: underline;"><span style="color: #000080;"><strong><span style="font-size: 12pt;"><span style="color: #000080; text-decoration: underline;">Курсы начинающих бухгалтеров</span></span></strong></span></span></a></p>\r\n<p>&nbsp;</p>\r\n<h3><a href="index.php?option=com_content&amp;view=article&amp;id=13:1&amp;catid=10:kursy-praktikuyushchikh-bukhgalterov"><span style="text-decoration: underline;"><span style="color: #000080; text-decoration: underline;"><span style="color: #000080; font-size: 12pt; text-decoration: underline;"><strong>Курсы&nbsp; практикующих бухгалтеров</strong></span></span></span></a></h3>\r\n<p><a href="index.php?option=com_content&amp;view=category&amp;id=9">&nbsp;</a></p>\r\n<h3 style="text-align: justify;"><a href="index.php?option=com_content&amp;view=article&amp;id=12:kursy-1s-qbukhgalteriya-8q&amp;catid=9:kursy-1s-qbukhgalteriya-8q">Курсы 1С: "Бухгалтерия 8"</a></h3>', '', -2, 2, '2012-02-25 07:36:09', 42, '', '2012-02-27 19:29:48', 42, 0, '0000-00-00 00:00:00', '2012-02-25 07:36:09', '0000-00-00 00:00:00', '', '', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":""}', 4, 1, '', '', 1, 0, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(11, 49, 'Курсы  практикующих бухгалтеров', 'kursy-praktikuyushchikh-bukhgalterov', '<h3><span style="color: #000080; font-size: 12pt;"><strong><br /></strong></span></h3>\r\n<h3><span style="color: #000080; font-size: 12pt;"><strong>Курсы&nbsp; практикующих бухгалтеров</strong></span></h3>\r\n<p style="text-align: justify;"><span style="color: #000080; font-size: 10pt;">Курс направлен на закрепление практических навыков в бухгалтерском, налоговом учете на 2012 год, практика применения 1 С</span></p>\r\n<p style="text-align: justify;"><span style="color: #000080; font-size: 10pt;">Программа</span></p>\r\n<p><span style="color: #000080; font-size: 10pt;">·&nbsp;&nbsp;&nbsp; Нововведения&nbsp; в законе&nbsp; о Бухгалтерском учете, практика применения</span></p>\r\n<p><span style="color: #000080; font-size: 10pt;">·&nbsp;&nbsp;&nbsp; Изменения в Налоговом законодательстве на&nbsp; 2012. (НДС, НДФЛ, налог на прибыль)</span></p>\r\n<p><span style="color: #000080; font-size: 10pt;">·&nbsp;&nbsp;&nbsp; Практические примеры&nbsp; в&nbsp; 1: С «Бухгалтерия»</span></p>\r\n<p><span style="color: #000080; font-size: 10pt;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Курс&nbsp; 40 часов,&nbsp; продолжительность 3 недели</span><br /><span style="color: #000080; font-size: 10pt;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Оплата&nbsp; 8000 руб.</span></p>', '', -2, 10, '2012-02-27 16:56:33', 42, '', '2012-02-27 18:41:44', 42, 0, '0000-00-00 00:00:00', '2012-02-27 16:56:33', '0000-00-00 00:00:00', '', '', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":""}', 4, 0, '', '', 1, 0, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content_v3` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(12, 51, 'Курсы 1С Бухгалтерия 8.2 в Екатеринбурге', 'kursy-1s-qbukhgalteriya-8q', '<h1><span style="color: #000080; font-family: times new roman,times; font-size: 14pt;"><strong><span style="font-size: 12pt;"><span style="color: #0000ff;">Курсы 1С: Бухгалтерия 8.2,&nbsp; 8.3&nbsp; + 1 С&nbsp; Зарплата и Управление персоналом (ЗУП) </span> <br /></span></strong></span></h1>\r\n<div style="text-align: justify;"><span style="color: #000000; font-family: times new roman,times; font-size: 14pt;"><span style="font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-size: 12pt; font-family: times new roman,times;"><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';"><strong>Целевая аудитория:</strong> бухгалтер, главный бухгалтер,&nbsp; финансист, менеджер.</span></span></span></span></span></div>\r\n<div style="text-align: justify;"><span style="color: #000000; font-family: times new roman,times; font-size: 14pt;"><span style="font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-size: 12pt; font-family: times new roman,times;"><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';"> </span></span></span></span></span><span style="color: #000000; font-family: times new roman,times; font-size: 12pt;">Курс полезен как для начинающих, так и для специалистов с опытом работы, решивших повысить квалификацию и изучить новые возможности программы. <span style="font-family: times new roman,times; font-size: 12pt;"><a href="http://эмменеджмент.рф/obrazovanie/kursy-bukhgalterskogo-ucheta"><span style="font-family: times new roman,times; font-size: 12pt; background-color: #ffffff;"><span style="color: #0000ff;"><span style="background-color: #ffffff; color: #0000ff;">Расписание курсов</span></span></span></a><span style="font-family: times new roman,times; font-size: 12pt;"> </span></span><br /></span></div>\r\n<div><strong><span style="font-family: times new roman,times; font-size: 12pt;">В программе</span></strong></div>\r\n<div style="text-align: left;"><span style="color: #0000ff;"><span style="font-family: times new roman,times; font-size: 12pt;">Настройка параметров учета. <br /></span></span></div>\r\n<ul>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Учетная политика (бухгалтерский учет)</span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Учетная политика (налоговый учет)</span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Настройка программы</span></li>\r\n</ul>\r\n<div style="text-align: left;"><span style="color: #0000ff;"><span style="font-family: times new roman,times; font-size: 12pt;">Справочник «номенклатура» и </span><span style="font-family: times new roman,times; font-size: 12pt;">«контрагенты». Для чего нужны справочники?<br /></span></span></div>\r\n<ul>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Регистр сведений «счета учета номенклатуры»</span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Регистр сведений «счета учета расчетов с контрагентами»</span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Ввод начальных остатков</span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Документ «операция (бухгалтерский и налоговый учет)»</span></li>\r\n</ul>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;">Учет кассовых операций. Расчеты с подотчетными лицами. Правильность оформления.<br /></span></div>\r\n<ul>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Поступление наличных денежных средств</span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Расход наличных денежных средств</span><span style="font-family: times new roman,times; font-size: 12pt;"><br /></span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Кассовая книга<br /></span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Авансовый отчет. <br /></span></li>\r\n</ul>\r\n<div style="text-align: left;"><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;">Учет торговых и банковских операций</span></div>\r\n<ul>\r\n<li style="text-align: left;"><span style="font-family: times new roman,times; font-size: 12pt;">Поступление товаров и услуг. Счет - фактура. Вычет НДС.<br /></span></li>\r\n<li style="text-align: left;"><span style="font-family: times new roman,times; font-size: 12pt;">Поступление доп. расходов</span></li>\r\n<li style="text-align: left;"><span style="font-family: times new roman,times; font-size: 12pt;">Поступление наличных денежных средств</span><span style="font-family: times new roman,times; font-size: 12pt;"><br /></span></li>\r\n<li style="text-align: left;"><span style="font-family: times new roman,times; font-size: 12pt;">Списание безналичных денежных средств</span></li>\r\n<li style="text-align: left;"><span style="font-family: times new roman,times; font-size: 12pt;">Платежное поручение, выгрузка и интернет-банк<br /></span></li>\r\n<li style="text-align: left;"><span style="font-family: times new roman,times; font-size: 12pt;">Реализация товаров и услуг</span></li>\r\n<li style="text-align: left;"><span style="font-family: times new roman,times; font-size: 12pt;">Учет основных средств, начисление амортизации</span></li>\r\n<li style="text-align: left;"><span style="font-family: times new roman,times; font-size: 12pt;">Расходы будущих периодов<br /></span></li>\r\n</ul>\r\n<div><span style="color: #0000ff; font-family: times new roman,times; font-size: 12pt;"><span style="color: #0000ff;">Учет производства</span></span></div>\r\n<ul>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Учет материалов и производства. Списание в производство.<br /></span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Передача материалов в производство. Калькулирование.<br /></span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Выпуск продукции. Плановая цена.<br /></span></li>\r\n</ul>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;"><span style="font-family: times new roman,times; font-size: 12pt;">Зарплата и кадровый учет, отчетность в Пенсионный фонд и ФСС (ЗУП)<br /></span></span></div>\r\n<ul>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Прием на работу в организацию. Трудовые аспекты приема на работу.<br /></span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Начисление зарплаты: табель рабочего времени, премия. Отпуска<br /></span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Выплата зарплаты</span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 14pt;"><span style="color: #000000; font-size: 12pt;">НДФЛ, социальные, стандартные, имущественные вычеты</span><br /></span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 14pt;"><span style="color: #000000; font-size: 12pt;">Больничные. Расчет всех видов социальных выплат<br /></span></span></li>\r\n</ul>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;">Закрытие месяца, финансовые результаты. Павильно формируем отчетность в соответствии с НКРФ<br /></span></div>\r\n<div>\r\n<ul>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Бухгалтерская отчетность.</span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Отчетность&nbsp; налоговая: НДС книга покупок и продаж. Начисление авансовых Счетов - фактур</span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Декларация по Прибыли, Имущество, УСНО.&nbsp;</span></li>\r\n</ul>\r\n</div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;"><strong>Вы получите навыки:</strong><br /></span></div>\r\n<ul>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">работа с программой 1С: «Бухгалтерия&nbsp; 8» в компьютерном классе по каждому объекту учета (денежные средства, расчеты с подотчетными лицами, расчеты с персоналом организации, учет основных средств и их амортизация, сырье, материалы,&nbsp; учет товаров, услуг, НДС, операции по завершению месяца, регламентированная отчетность - бухгалтерская и налоговая отчетность); </span></li>\r\n<li style="text-align: justify;" class="_mce_tagged_br"><span style="font-family: times new roman,times; font-size: 12pt;">расчет заработной платы в <span style="color: #000000;"> 1 С&nbsp; Зарплата и Управление персоналом (ЗУП) и отчетность в Пенсионный фонд и ФСС<br /></span></span></li>\r\n<li style="text-align: justify;" class="_mce_tagged_br">\r\n<div><span style="color: #000000;"><span style="font-family: times new roman,times; font-size: 12pt;">а также решение практических задач по бухгалтерскому</span><span style="font-family: times new roman,times;"><span style="font-size: 12pt;">&nbsp; и налог</span><span style="font-size: 12pt;">овому&nbsp; учету в учебной версии 1С: Бухгалтерия&nbsp; 8 на домашнем рабочем месте.</span></span></span><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;"> </span></div>\r\n</li>\r\n</ul>\r\n<p>&nbsp;<span style="font-size: 12pt; color: #000000;"><span style="font-family: times new roman,times;">Расписание: </span><span style="font-family: times new roman,times;"><strong>вечерние группы</strong> (вторник, пятница с 19.00 до 21.30) и <strong>"по выходным"</strong> - суббота воскресенье с 10.00 до 14.00 или с 14.00 до 18.00&nbsp; </span></span><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;"><br /></span></p>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;">&nbsp;<span style="color: #000000; font-family: times new roman,times; font-size: 12pt;">Целью курса является практическое освоение программы "1С:Бухгалтерия 8" с использованием конкретных примеров.</span>&nbsp;</span></div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;">Продолжительность&nbsp; 3 недели часов. Cтоимость 7 500&nbsp; </span><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #ffffff; background-color: #ffffff;"><span style="color: #0000ff;"><strong><a class="modal" href="#call_me" rel="{size:{x:460,y:130}}"><span>Отправить заявку</span></a></strong></span></span></span></span><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #ffffff; background-color: #ffffff;"><span style="color: #0000ff;"><strong><a class="modal" href="#call_me" rel="{size:{x:460,y:130}}"><span style="color: #0000ff; background-color: #ffffff;"></span></a></strong></span></span></span><br /></span></div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt; color: #000000;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="background-color: #ffffff;"><strong>&nbsp;</strong></span></span></span></div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #ff0000;"></span><br style="color: #ff0000;" /></span></span></div>', '', 1, 9, '2012-02-27 17:25:24', 42, '', '2014-11-23 18:52:56', 42, 0, '0000-00-00 00:00:00', '2012-02-27 17:25:24', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":null,"urlatext":"","targeta":"","urlb":null,"urlbtext":"","targetb":"","urlc":null,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 49, 0, 'Курсы 1 С 8.2, обучение 1 С Бухгалтерия, 1С обучение Екатеринбург, курсы 1 С, обучение программы  1 С', 'Курс 1С: "Бухгалтерия 8.2"', 1, 1468, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(13, 55, 'Курсы повышения квалификации  практикующий бухгалтер, главный бухгалтер', 'kursy-praktikuyushchij-bukhgalter-glavnyj-bukhgalter', '<h1 style="text-align: justify;" dir="ltr"><span style="font-family: times new roman,times;"><strong><span style="font-size: 14pt; color: blue;"><span style="font-family: times new roman,times; font-size: 12pt;">Курс повышения квалификации: главный бухгалтер, практикующий бухгалтер</span></span></strong><b><span style="font-size: 14pt; color: blue;"><span style="font-size: 14pt; color: blue;"><br /></span></span></b></span></h1>\r\n<div style="text-align: left;">\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: blue;"><span style="color: #000000;"><strong>Целевая аудитория: </strong><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-size: 12pt; font-family: times new roman,times;"><span style="font-size: 12pt; line-height: 115%; font-family: ''Times New Roman'';">бухгалтер, главный бухгалтер, экономист, финансовый директор</span></span></span></span><b><br /></b></span></span></div>\r\n<span style="font-family: times new roman,times; font-size: 12pt; color: #000000;"><b></b></span></div>\r\n<div style="text-align: left;"><span style="font-family: times new roman,times; font-size: 12pt; color: #000000;"><b>Ведущие</b></span><span style="font-family: times new roman,times; font-size: 12pt;">: Нижник Мария Геннадьевна - главный госналогинспектор, автор программ по налогообложению.</span></div>\r\n<div style="text-align: left;"><span style="font-family: times new roman,times; font-size: 12pt;">Долматова Любовь Анатольевна - практикующий адвокат по налоговым спорам</span></div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;"><strong>В программе</strong><span style="color: #993366;"></span><br /></span></div>\r\n<div style="text-align: left;" dir="ltr"><strong><span style="color: #000000; font-family: times new roman,times; font-size: 12pt;">Практические вопросы применения налогового законодательства</span></strong></div>\r\n<ul style="list-style-type: square;">\r\n<li style="text-align: justify;"><span><em>&nbsp;<span style="font-family: times new roman,times; font-size: 12pt;">Изменения&nbsp; в&nbsp;&nbsp; Налоговом законодательстве&nbsp;</span></em><span style="font-family: times new roman,times; font-size: 12pt;"> 2014 года</span><strong>. </strong><span style="font-family: times new roman,times; font-size: 12pt;">Новые льготы в спецрежимах&nbsp; в 2014 г. <em>Оптимальное налогообложение на спецрежимах.</em></span></span></li>\r\n<li style="text-align: justify;"><span><span style="font-family: times new roman,times; font-size: 12pt;"><em><span><strong> </strong><span style="font-family: times new roman,times; font-size: 12pt;"><em>Типичные ошибки при налоговых проверках НДС, НДФЛ, налог на прибыль</em></span></span></em></span></span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"><i> Спорные впросы восстановления и вычетов НДС. </i></span><span><span style="font-family: times new roman,times; font-size: 12pt;">Корректировочные счета-фактуры</span>.</span><span><span style="font-size: 12pt; font-family: times new roman,times;">&nbsp; Исчисление и уплата НДС с авансовых&nbsp;&nbsp;&nbsp; платежей.&nbsp;&nbsp;</span>&nbsp;</span><span style="font-family: times new roman,times; font-size: 12pt;"> Последствия ошибок в оформлении счетов-фактур.</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">&nbsp;Налоговый учет скидок и премий. Чем может обернуться заниженная цена сделки?&nbsp; <strong>Трансфертные цены. Нововведения взаимозависимости.</strong> </span></li>\r\n</ul>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;"><strong>Практические вопросы защиты налогоплательщиком своих интересов</strong><span style="color: blue;"></span></span></div>\r\n<ul style="list-style-type: square;">\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"><i><strong style="text-align: justify;">Налоговые проверки: спорные вопросы назначения</strong>,<strong> проведения проверки.</strong></i> Как налогоплательщику действовать, если налоговый орган вынес решение по результатам выездной налоговой проверки после даты рассмотрения материалов проверки.<i>&nbsp; <strong>Как налогоплательщику избежать переквалификации договоров налоговым органом.</strong></i> </span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"><em>Какие аргументы налогоплательщику выдвигать при обвинениях в <strong>необоснованной налоговой выгоде. </strong></em></span><span style="font-family: times new roman,times; font-size: 12pt;">Последствия сделок, заключенных с фирмами – «однодневками».</span></li>\r\n</ul>\r\n<div style="text-align: justify;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <span style="font-family: times new roman,times; font-size: 12pt;"><i><span style="text-decoration: underline;">Практикум:</span></i> Анализ выигрышной арбитражной практики по защите интересов налогоплательщиков в случае обвинения налоговым органом в контактах с «фирмами-однодневками».</span></div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;"><strong><span style="color: #000000;">&nbsp;Причины налоговых споров</span></strong><span style="color: blue;"></span></span></div>\r\n<ul style="list-style-type: square;">\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"><i style="text-align: justify;">Почему случаются<strong> налоговые споры</strong>?</i> Действия (бездействие) налогоплательщика (заблуждения и <strong>ошибки налогоплательщика</strong>, небрежность к документам, <strong>детские и взрослые налоговые схемы,</strong> изменение правоприменительной практики и пр.)&nbsp; Действия (бездействие), акты налогового органа (налоговые проверки, иные мероприятия налогового контроля, ) </span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Управление налоговыми рисками<i>. Опции для защиты нарушенных прав в арбитражном суде. Тенденции в разрешении налоговых споров.</i></span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"><i> </i></span><span style="font-family: times new roman,times; font-size: 12pt;">Оспаривание действий налогового органа. Обращения с имущественными требованиями (возврат&nbsp; излишне уплаченных&nbsp; налогов, подлежащего возмещению НДС, начисление процентов и пр.) Взыскание судебных расходов (виды возмещаемых расходов, процедура возмещения, разумность расходов). </span><span style="font-family: times new roman,times; font-size: 12pt;">Сроки взыскания по налогам и сборам, сроки обращения и последствия пропуска сроков обращения.&nbsp;</span></li>\r\n</ul>\r\n<div style="text-align: justify;"><span style="color: #000000;"><strong><span style="font-family: times new roman,times; font-size: 12pt;">Налоговые риски при заключении договоров</span></strong></span></div>\r\n<ul style="list-style-type: square;">\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">&nbsp;</span><span style="font-family: times new roman,times; font-size: 12pt;"><strong><span style="color: #333333;">Обязан ли налогоплательщик проверять контрагента</span></strong>.<span style="color: blue;"> </span>Соотношение презумпции добросовестности участников договора и <em>необходимости проявления <strong>"разумной осмотрительности"</strong></em>.&nbsp; Проблема "свободы договора" по Гражданскому кодексу и так называемой "необоснованной налоговой выгоды". Позиция Высшего Арбитражного Суда. Подходы Минфина и Федеральной налоговой службы. Проблема соотношения ст. 434 Гражданского кодекса и ст.252 Налогового кодекса: анализ типичных ошибок. Применение факса, факсимиле, электронной подписи и его налоговые последствия.&nbsp;&nbsp;&nbsp; Правовой статус "рамочного договора", "предварительного договора", "протокола разногласий". Всегда ли нужна государственная регистрация сделок?</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"><strong style="font-family: times new roman,times; font-size: 12pt;">Значение предмета договора для целей налогообложения.</strong> Налоговые последствия при определении существенных и иных условий договора.&nbsp; Значение правильного применения ст.452 Гражданского кодекса для целей налогообложения. Налоговые последствия прощения долга, новации, зачета и т.п. форм прекращения договора. Случаи одностороннего прекращения договора и связанные с этим&nbsp; налоговые риски.</span></li>\r\n</ul>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #0000ff;">Тестирование после прохождения&nbsp; курса &nbsp; &nbsp;<span style="font-size: 12pt; font-family: times new roman,times;"><span style="font-size: 14pt; font-family: ''Times New Roman'',''serif'';"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: ''times new roman'',times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #ffffff; background-color: #ffffff;"><span style="color: #0000ff;"><strong><a class="modal" href="http://%D1%8D%D0%BC%D0%BC%D0%B5%D0%BD%D0%B5%D0%B4%D0%B6%D0%BC%D0%B5%D0%BD%D1%82.%D1%80%D1%84/obrazovanie/kursy-yurista/2-uncategorised/26-kurs-pravovye-aspekty-sostavleniya-i-analiza-dogovora#call_me" rel="{size:{x:460,y:130}}"><span style="color: #0000ff; background-color: #ffffff;">Отправить заявку</span></a></strong></span></span></span></span></span></span></span></span></span> <br /></span></div>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #0000ff;">&nbsp;</span></span></div>\r\n<div style="text-align: justify;"><span style="text-align: justify; font-family: times new roman,times; font-size: 12pt;">Курс направлен на обновление&nbsp; и пополнение профессиональных знаний&nbsp; в бухгалтерском, налоговом учете на 2014 год, практика налоговых проверок и налоговые риски, оптимизация налогообложения.&nbsp;&nbsp; На курсе ВЫ ПОЛУЧИТЕ ОТВЕТЫ НА ВСЕ ВАШИ ВОПРОСЫ.</span></div>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">&nbsp;</span></div>\r\n<div style="text-align: justify;"><span style="font-size: 12pt; font-family: times new roman,times;"><span style="color: black;">Курс&nbsp; 25 часов.</span> <span style="color: #000000;">Оплата&nbsp; 10900 руб. </span><span class="punktname"><span style="color: #000000;">Скидка 5%</span><span style="color: black;"> при оплате за 2&nbsp; недели до начала обучения&nbsp; </span></span></span></div>\r\n<p><span style="color: blue; font-family: times new roman,times; font-size: 12pt;"><i>&nbsp;</i></span></p>\r\n<div><span style="font-family: times new roman,times;">&nbsp;</span></div>\r\n<div><span style="color: #174f3b; font-family: times new roman,times; font-size: 12pt;"><span style="color: #1684a2;"><strong>&nbsp;</strong></span></span></div>', '', 1, 2, '2012-02-27 19:18:58', 42, '', '2014-08-08 09:21:45', 42, 0, '0000-00-00 00:00:00', '2012-02-27 19:18:58', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":null,"urlatext":"","targeta":"","urlb":null,"urlbtext":"","targetb":"","urlc":null,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 83, 57, 'курсы семинары практикующих бухгалтеров, семинары Изменения в Налоговом законодательстве  семинары НДС, семинары налог на добавленную стоимость, курсы налог на прибыль, курсы нововведения  в законе  о Бухгалтерском учете, курсы семинары оптимизация налогообложения курсы налоговое право, налоговые споры семинары, налоговые проверки семинары', 'Курсы повышения квалификации практикующий бухгалтер, главный бухгалтер', 1, 2980, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(14, 57, 'Юридические услуги', 'yuridicheskie-uslugi', '<h1 style="text-align: left;"><span style="color: #0000ff; font-family: times new roman,times; font-size: 12pt;"><strong>Юридические услуги</strong></span></h1>\r\n<div style="text-align: left;"><span style="color: #000000; font-size: 10pt; font-family: times new roman,times;">Доступная и оперативная правовая поддержка&nbsp; юристов поможет&nbsp; Вашей компании минимизировать налоговые, гражданско-правовые, и административные риски,&nbsp; риски,&nbsp; вытекающие из трудовых отношений.</span></div>\r\n<div style="text-align: justify;"><br /><span style="color: #000000; font-size: 10pt; font-family: times new roman,times;"><span style="color: #832a72;"><span style="color: #0000ff;">Преимущество&nbsp; юристов группы:</span> </span></span></div>\r\n<div style="text-align: justify;">\r\n<ul>\r\n<li><span style="color: #000000; font-size: 10pt; font-family: times new roman,times;">работают на стыке областей гражданского и налогового права;</span></li>\r\n<li><span style="color: #000000; font-size: 10pt; font-family: times new roman,times;">имеют возможность&nbsp; привлекать&nbsp; к своей работе&nbsp; специалистов смежных областей:&nbsp; аудиторов, бухгалтеров, экспертов по управленческому и бизнес консалтингу;</span></li>\r\n<li><span style="color: #000000; font-size: 10pt; font-family: times new roman,times;">обладают объемным информационным банком потенциальных&nbsp; налоговых, гражданско-правовых и административных рисков;</span></li>\r\n<li><span style="color: #000000; font-size: 10pt; font-family: times new roman,times;">имеют успешный опыт правового обеспечения деятельности предприятий различных сфер бизнеса, опыт досудебного и судебного решения налоговых и гражданско-правовых споров, обжалования действий государственных органов и должностных лиц.</span></li>\r\n</ul>\r\n</div>\r\n<div style="text-align: justify;"><span style="font-size: 10pt;"><span style="color: #000000; font-family: times new roman,times;">&nbsp;</span><span style="color: #000000; font-family: times new roman,times;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <span style="color: #000000;">Юридические услуги &nbsp; </span></span></span></div>\r\n<table style="width: 613px; height: 144px;" _mce_new="1" cellpadding="2" border="0">\r\n<tbody>\r\n<tr>\r\n<td><span style="font-family: times new roman,times; font-size: 10pt; color: #000000;">Единовременная консультация&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; </span></td>\r\n<td><span style="font-family: times new roman,times; font-size: 10pt; color: #000000;"></span></td>\r\n</tr>\r\n<tr>\r\n<td><span style="color: #000000; font-size: 10pt; font-family: times new roman,times;">Составление претензий, жалоб, заявлений и др.</span></td>\r\n<td><span style="font-family: times new roman,times; font-size: 10pt; color: #000000;"> </span></td>\r\n</tr>\r\n<tr>\r\n<td><span style="font-family: times new roman,times; font-size: 10pt; color: #000000;">Подготовка искового заявления <br /></span></td>\r\n<td><span style="color: #000000; font-size: 10pt; font-family: times new roman,times;"></span></td>\r\n</tr>\r\n<tr>\r\n<td><span style="color: #000000; font-size: 10pt; font-family: times new roman,times;">Представительство в Арбитражном суде&nbsp; <br /></span></td>\r\n<td><span style="color: #000000; font-size: 10pt; font-family: times new roman,times;"></span></td>\r\n</tr>\r\n<tr>\r\n<td><span style="color: #000000; font-size: 12pt; font-family: times new roman,times;"><span style="font-size: 10pt;">Лицензия &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span> <br /></span></td>\r\n<td><span style="color: #000000; font-size: 12pt; font-family: times new roman,times;"> </span></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span style="font-size: 10pt; font-family: times new roman,times;">&nbsp;</span></p>\r\n<p><br /><span style="color: #000000; font-size: 10pt; font-family: times new roman,times;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span><br /><span style="color: #000000; font-size: 10pt; font-family: times new roman,times;">&nbsp; &nbsp; &nbsp; &nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; </span><br /><span style="color: #000000; font-size: 10pt; font-family: times new roman,times;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span><br /><span style="color: #000000; font-size: 10pt;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; </span><br /><span style="color: #000000; font-size: 10pt;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp; </span><br /><span style="color: #000000; font-size: 10pt;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span><br /><span style="color: #000000; font-size: 10pt;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span><br /><span style="color: #333399; font-size: 10pt;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <br /></span></p>', '', 1, 2, '2012-03-01 16:35:39', 42, '', '2014-05-08 10:54:55', 42, 0, '0000-00-00 00:00:00', '2012-03-01 16:35:39', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":null,"urlatext":"","targeta":"","urlb":null,"urlbtext":"","targetb":"","urlc":null,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 25, 60, 'юридические услуги, Юридическая консультация, юридическая помощь, представительство  в суде, регистрация ООО, готовая фирма', '  Юридические услуги', 1, 890, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content_v3` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(15, 59, 'Курс бухгалтеров малого бизнеса: Упрощенная система, ЕНВД', 'envd-usno-patentnaya-sistema', '<h1 style="text-align: justify;"><span style="color: #333399; font-family: times new roman,times;"><strong><span style="font-size: 12pt;"><span style="font-size: 14pt;"><span style="color: #000080; font-size: 12pt;"><span style="color: #0000ff;">Бухгалтерские курсы Упрощенная система налогообложения (УСНО), ЕНВД+ 1С.</span></span><br /></span></span></strong></span></h1>\r\n<p><span style="color: #000000; font-size: 12pt; font-family: times new roman,times;">Курсы для бухгалтеров малого бизнеса, с 2013 года вступил в силу новый закон о Бухгалтерском учете № 402-ФЗ, обязывающий вести бухгалтерский учет предприятия, применяющие спецрежимы.<br /></span><span style="color: #ff0000;"><strong><span style="color: #000000; font-size: 12pt; font-family: times new roman,times;">В программе:</span></strong><span style="font-size: 12pt; font-family: times new roman,times; color: #800080;"></span><span style="font-size: 12pt; font-family: times new roman,times;"><br /> <span style="color: #000000;">В процессе обучения вам даются практические примеры и задачи для полного понимания бухгалтерии малого бизнеса.</span><br /><span style="color: #0000ff;"> </span></span></span></p>\r\n<p><span style="color: #ff0000;"><span style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #000000;"><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;">1.Методика бухгалтерского учета:</span></span></span></span></p>\r\n<ul>\r\n<li style="color: #000000;">&nbsp;<span style="color: #ff0000;"><span style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #000000;"><span style="font-family: times new roman,times; font-size: 12pt;">понятия, виды хозяйственного учета, правовая основа бухучета</span></span></span></span></li>\r\n<li><span style="color: #ff0000;"><span style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #000000;"><span style="font-family: times new roman,times; font-size: 12pt;">балансовый метод отражения информации, группировка балансовых статей</span></span></span></span></li>\r\n<li><span style="color: #ff0000;"><span style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #000000;"><span style="font-family: times new roman,times; font-size: 12pt;"></span></span></span></span><span style="color: #ff0000;"><span style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #000000;"><span style="font-family: times new roman,times; font-size: 12pt;">баланс предприятия,&nbsp; строение балансовых счетов, счета аналитические и синтетические, план счетов </span></span></span></span></li>\r\n</ul>\r\n<p style="text-align: justify;" class="readmore">&nbsp;<span style="color: #ff0000;"><span style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #0000ff;">2.Учет объектов бухгалтерского учета:</span></span></span></p>\r\n<ul>\r\n<li style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #000000;"> учет денежных средств, учет операций по расчетному счету; </span></li>\r\n<li style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #000000;"> учет расчетов с подотчетными лицами, прочими дебиторами и кредиторами; </span></li>\r\n<li style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #000000;"> учет производственных запасов; </span></li>\r\n<li style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #000000;"> учет и оценка основных средств и нематериальных активов; </span></li>\r\n<li style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #000000;"> учет оплаты труда и страховых взносов; </span></li>\r\n<li style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #ff0000;"><span style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #000000;"> учет готовой продукции и операций по ее реализации. </span> </span></span></li>\r\n</ul>\r\n<p style="text-align: justify;" class="readmore">&nbsp;<span style="color: #ff0000;"><span style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #0000ff;">3.Расчет налогов и страховых взносов, отчетность</span></span></span></p>\r\n<ul>\r\n<li style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #000000;"> страховые взносы, ФСС и ПФ;</span></li>\r\n<li style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #000000;"></span><span style="color: #ff0000;"><span style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #000000;">налог на доходы физических лиц;</span><span style="color: #000000;"> </span></span></span></li>\r\n</ul>\r\n<p style="text-align: justify;" class="readmore">&nbsp;<span style="color: #ff0000;"><span style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #0000ff;">4.УСНО, ЕНВД, патентная система</span></span></span></p>\r\n<ul>\r\n<li style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #000000;"> объекты налогообложения, налоговая база, налоговые ставки</span></li>\r\n<li style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #000000;"> смена налогового режима, порядок перехода</span></li>\r\n<li style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #000000;"> порядок ведения книги учета доходов и расходов</span></li>\r\n<li style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #000000;"> совмещение спецрежимов</span></li>\r\n<li style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #000000;"> преимущества и недостатки УСНО</span></li>\r\n<li style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #ff0000;"><span style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #000000;">патентная система для индивидуальных предпринимателей</span> </span></span></li>\r\n</ul>\r\n<div>&nbsp;<span style="font-family: times new roman,times; font-size: 12pt;">- <em>Льготы по налогообложению, пониженные ставки по страховым взносам</em><br /></span></div>\r\n<div><em><span style="font-family: times new roman,times; font-size: 12pt;">- Выбор оптимальных систем налогообложения<br /></span></em></div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;"><em>- Нормируемые расходы в целях налогообложения</em><br /></span></div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;"><i> - Практические задачи и составление деклараций в ИФНС</i></span></div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;"><i>- Типичные ошибки&nbsp; при составление отчетности</i></span></div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;"><i>&nbsp;</i></span></div>\r\n<div style="text-align: justify;" class="readmore"><span style="font-size: 12pt; font-family: times new roman,times; color: #0000ff;">&nbsp;5. Практическое занятие:</span></div>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;"></span>\r\n<ul style="list-style-type: disc;">\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">работа с программой 1С: «Бухгалтерия&nbsp; 8» в компьютерном классе по каждому объекту учета (денежные средства, расчеты с подотчетными лицами, расчеты с персоналом организации, учет основных средств и их амортизация, сырье, материалы,&nbsp; учет товаров, услуг, НДС, операции по завершению месяца, регламентированная отчетность - бухгалтерская и налоговая отчетность); <br /></span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">расчет заработной платы в <span style="color: #000000;"> 1 С&nbsp; Зарплата и Управление персоналом (ЗУП) или&nbsp;&nbsp;<span style="font-family: times new roman,times; font-size: 12pt;">1С: Бухгалтерия&nbsp; 8</span> по выбору слушателя</span><br /></span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">решение практических задач по бухгалтерскому&nbsp; и налоговому&nbsp; учету в учебной версии 1С: Бухгалтерия&nbsp; 8 на домашнем рабочем месте.</span><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;"> <br /></span></li>\r\n</ul>\r\n</div>\r\n<p style="text-align: justify;" class="readmore"><span style="color: #ff0000;"><span style="font-size: 12pt; font-family: times new roman,times;"><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;">6.&nbsp; Основы составления договоров и&nbsp; основы аудиторской деятельности</span><br /><br /><span style="color: #0000ff; font-size: 12pt;"><span style="font-family: times new roman,times;">По итогу курса выполняется сдача зачета</span><span style="font-family: times new roman,times;">, на закрепление знаний и навыков</span></span><br /> <span style="color: #000000;">Вы получите практическую базу, необходимую для работы со специальными налоговыми режимами, практические рекомендации по вопросам ведения налогового учета. Также типичные ошибки, возникающие при применении специальных налоговых режимов.</span><br /> <br /> </span></span><span style="color: #ff0000;"><span style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #000000;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #ffffff; background-color: #ffffff;"><span style="color: #0000ff;"><strong><a class="modal" href="#call_me" rel="{size:{x:460,y:130}}"><span style="color: #0000ff; background-color: #ffffff;">Отправить заявку</span></a></strong></span></span></span></span></span></span><span style="color: #ff0000;"><span style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #000000;"> Слушателям выдается раздаточный материал</span><br /><span style="color: #000000;"> Продолжительность - 1,5 месяца. Стоимость 15400 руб.&nbsp;&nbsp;<span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #ffffff; background-color: #ffffff;"><span style="color: #0000ff;"></span></span></span><br /></span></span></span></p>\r\n<div style="text-align: justify;" class="readmore"><span style="color: #000000;"><span style="font-family: ''times new roman'', times; font-size: 12pt; text-align: left;"><span style="margin: 0px; padding: 0px; border: 0px; font-family: inherit; font-size: inherit; font-style: inherit; font-variant: inherit; line-height: inherit; vertical-align: baseline;"><span style="margin: 0px; padding: 0px; border: 0px; font-family: ''times new roman'', times; font-size: 16px; line-height: 24px; vertical-align: baseline;">Расписание:&nbsp;</span><span style="margin: 0px; padding: 0px; border: 0px; font-family: ''times new roman'', times; font-size: 16px; line-height: 24px; vertical-align: baseline;">вечерние группы&nbsp;(вторник, четверг, пятница с 19.00 до 21.30) и&nbsp;"по выходным"&nbsp;- суббота воскресенье с 10.00 до 14.00 или с 14.00 до 18.00&nbsp;&nbsp;</span></span></span></span></div>\r\n<div style="text-align: justify;" class="readmore"><span style="color: #000000;"><span style="font-family: ''times new roman'', times; font-size: 12pt; text-align: left;"><span style="margin: 0px; padding: 0px; border: 0px; font-family: inherit; font-size: inherit; font-style: inherit; font-variant: inherit; line-height: inherit; vertical-align: baseline;"><span style="margin: 0px; padding: 0px; border: 0px; font-family: ''times new roman'', times; font-size: 16px; line-height: 24px; vertical-align: baseline;"></span>Для иногородних есть возможность пройти курсы дистанционного обучения.</span></span></span></div>\r\n<p style="text-align: justify;" class="readmore"><span style="color: #800080; font-family: times new roman,times; font-size: 10pt;">Скидка 5%</span><span style="font-family: ''times new roman'', times; font-size: 12pt; text-align: left;"> при оплате за 2&nbsp; недели до начала обучения&nbsp;</span></p>\r\n<div style="text-align: left;" class="readmore"><span style="color: #000000; font-size: 12pt; font-family: times new roman,times;"> Потенциальная группа: бухгалтер, главный бухгалтер, финансовый директор, предприниматель, руководитель</span></div>', '', 1, 12, '2012-03-01 18:34:13', 42, '', '2014-11-13 05:56:27', 42, 0, '0000-00-00 00:00:00', '2012-03-01 18:34:13', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":null,"urlatext":"","targeta":"","urlb":null,"urlbtext":"","targetb":"","urlc":null,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 58, 0, 'курсы бухгалтера  упрощенная система налогообложения, курсы енвд', 'Курсы бухгалера для малого бизнеса Упрощенная система налогообложения, ЕНВД.', 1, 1151, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(16, 60, 'ЭмМенеджмент  - бухгалтерские курсы Екатеринбург', 'glavnaya-1', '<h1 style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;">Тренинги по продажам и управлению персоналом. Программы дополнительного профессионального образования. Курсы и семинары повышения квалификации.<span style="font-size: 12pt; color: #0000ff;"></span></span></h1>\r\n<p><span style="font-family: arial,helvetica,sans-serif; font-size: 12pt;"><span style="font-size: 12pt;"><span style="font-size: 12pt;"><span style="font-size: 10pt;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style="font-size: 10pt; font-family: times new roman,times;"> <a href="index.php?option=com_content&amp;view=article&amp;id=38:kursy-obucheniya-prodazham-v-ekaterinburge&amp;catid=2:uncategorised&amp;Itemid=189">ПРОДАЖИ, ПЕРЕГОВОРЫ</a></span></span></span></span></span></p>\r\n<p>&nbsp;<span style="font-family: ''times new roman'',times; font-size: 12pt;"><span style="font-family: ''times new roman'',times; font-size: 12pt;"><span style="font-size: 12pt;"><span style="font-size: 10pt;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <a href="index.php?option=com_content&amp;view=article&amp;id=42:treningi-i-kursy-upravlenie-personalom-menedzher-po-personalu-spetsialist-po-kadram&amp;catid=2:uncategorised&amp;Itemid=188">УПРАВЛЕНИЕ ПЕРСОНАЛОМ</a></span></span></span></span></p>\r\n<p>&nbsp;<span style="font-family: ''times new roman'',times; font-size: 10pt;"><span style="font-family: ''times new roman'',times;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <a href="index.php?option=com_content&amp;view=article&amp;id=25:kursy-yurista&amp;catid=8:obrazovanie&amp;Itemid=187">ГРАЖДАНСКОЕ, ТЕНДЕРНОЕ ПРАВО</a></span></span></p>\r\n<p>&nbsp;<span style="font-family: ''times new roman'',times; font-size: 10pt;"><span style="font-family: ''times new roman'',times;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <a href="index.php?option=com_content&amp;view=article&amp;id=20:ekonomicheskie-kursy&amp;catid=8:obrazovanie&amp;Itemid=171">ЭКОНОМИКА&nbsp; И ФИНАНСЫ</a></span></span></p>\r\n<p>&nbsp;<span style="font-family: ''times new roman'',times; font-size: 10pt;"><span style="font-family: ''times new roman'',times;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <a href="index.php?option=com_content&amp;view=article&amp;id=19:kursy-bukhgalterskogo-ucheta&amp;catid=8:obrazovanie&amp;Itemid=170">БУХУЧЕТ, НАЛОГИ, 1 </a><a href="index.php?option=com_content&amp;view=article&amp;id=19:kursy-bukhgalterskogo-ucheta&amp;catid=8:obrazovanie&amp;Itemid=170">С</a></span></span></p>\r\n<p>&nbsp;<span style="font-family: ''times new roman'',times; font-size: 10pt;"><span style="font-family: ''times new roman'',times;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <a href="index.php?option=com_content&amp;view=article&amp;id=32:kursy-kadrovika-spetsialist-po-kadram-obuchenie-trudovoe-pravo-kadrovoe-deloproizvodstvo-1-s&amp;catid=2:uncategorised&amp;Itemid=201">ТРУДОВОЕ ПРАВО, КАДРЫ</a></span></span></p>\r\n<div style="text-align: justify;"><span style="font-family: ''times new roman'',times; font-size: 10pt;"><span style="font-family: ''times new roman'',times;"><span style="color: #9d206e;"><strong><span style="text-align: center; font-family: times new roman,times; font-size: 14pt;"> </span></strong></span><span style="font-family: ''times new roman'',times; font-size: 12pt;">Центр эффективного обучения "ЭмМенеджмент"&nbsp; является одним из лучших на рынке образовательных услуг. Наш главный принцип работы - эффективность, доступность,</span></span></span><span style="font-family: ''times new roman'',times; font-size: 10pt;"><span style="font-family: ''times new roman'',times;"><span style="font-family: ''times new roman'',times; font-size: 12pt;"> гибкий новационный подход к обучению<br /></span></span></span></div>\r\n<div style="text-align: justify;"><span style="font-family: ''times new roman'',times; font-size: 10pt;"><span style="font-family: ''times new roman'',times;"><span style="font-family: ''times new roman'',times; font-size: 12pt;">&nbsp;</span></span></span></div>\r\n<div style="text-align: left;"><span style="font-family: ''times new roman'',times; font-size: 10pt;"><span style="font-family: ''times new roman'',times;">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; </span></span><strong><span style="font-family: arial,helvetica,sans-serif; font-size: 12pt;"><span style="font-size: 12pt;"><span style="font-size: 12pt;"><span style="color: #000000;"><span style="background-color: #ffffff; color: #800080;">ПРЕИМУЩЕСТВА</span></span></span></span></span></strong><span style="color: #800080;"><span style="background-color: #800080;"><span style="background-color: #ffffff;"><strong></strong></span></span></span><span style="font-family: ''times new roman'',times; font-size: 12pt;"><span style="font-family: ''times new roman'',times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;"></span></span></span></div>\r\n<ul>\r\n<li style="text-align: justify;"><span style="font-family: ''times new roman'',times; font-size: 12pt;"><span style="font-family: ''times new roman'',times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;">Занятия проводят преподаватели-практики, имеющие востребованный и серьезный практический опыт</span></span></span></li>\r\n<li style="text-align: justify;"><span style="font-family: ''times new roman'',times; font-size: 12pt;"><span style="font-family: ''times new roman'',times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;"></span></span></span><span style="font-family: times new roman,times; font-size: 12pt;">Поскольку весь процесс обучения построен на индивидуальном контакте преподавателя и слушателей, занятия проводятся в группах до 12 человек.</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"></span><span style="font-family: times new roman,times; font-size: 12pt;">Обратная связь&nbsp; от преподователя по время проведения информационных лекций и самостоятельных практических работ обучающихся.</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"></span><span style="font-family: times new roman,times; font-size: 12pt;">Центр «ЭмМенеджмент» расположен в центре Екатеринбурга, а обучение&nbsp; проводится в удобное для слушателей время. График обучения построен таким образом, чтобы ваши знания стали навыками для самостоятельной работы в организации.</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"></span><span style="font-family: times new roman,times; font-size: 12pt;">Отличные отзывы по каждой программе</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"></span><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;">Помещения оборудованы всем необходимым для обучения, в том числе современными компьютерами и проекторами. Каждому слушателю выдается удобный методический материал. Кофе - брейки.</span></span></li>\r\n</ul>\r\n<p><span style="font-family: ''times new roman'',times; font-size: 12pt;">&nbsp;&nbsp;&nbsp;&nbsp; Приобретите высокооплачиваемую и престижную профессию − запишитесь на тренинги и курсы от компании «ЭмМенеджмент»! <br /></span></p>\r\n<p style="text-align: justify;"><span style="font-family: ''times new roman'',times; font-size: 12pt;">&nbsp;&nbsp; О курсах:<br /></span></p>\r\n<div style="text-align: justify;"><span style="font-size: 12pt; font-family: times new roman,times;"><span style="text-align: justify;">Очень важно, чтобы <a href="index.php?option=com_content&amp;view=article&amp;id=19:kursy-bukhgalterskogo-ucheta&amp;catid=8:obrazovanie&amp;Itemid=170"><span style="color: #3366ff;"><span style="color: #0000ff;">курсы</span> <span style="color: #0000ff;">бухгалтеров, повышения квалификации главных</span> <span style="color: #0000ff;">бухгалтеров</span></span></a> совмещали</span> практические занятия предметов бухгалтерского и налогового учета, но и также гражданское, административное право, экономический анализ предприятия, актуальные арбитражные налоговые споры − так слушатели быстрее усвоят новый материал, выявят ошибки в системе учета своего предприятия, выработают систему принятия решений в спорных ситуациях налогообложения и бухгалтерского учета.&nbsp; Важной частью курсов повышения квалификации бухгалтера будет&nbsp;минимизация финансовых, налоговых и гражданских рисков, избежание распространенных ошибок в повседневной&nbsp; работе,&nbsp;подготовка к налоговой проверке. </span></div>\r\n<p style="text-align: justify;"><span style="font-family: ''times new roman'',times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;">Пройдя курсы повышения квалификации главных бухгалтеров в Екатеринбурге&nbsp;<span style="font-family: times new roman,times; font-size: 12pt;"> вы станете востребованными специалистами&nbsp; в бухгалтерском учете, </span><span style="font-family: ''times new roman'',times; font-size: 12pt;">налогах, гражданском праве. Примените полученные знания в профессиональной и предпринимательской деятельности&nbsp;&nbsp;&nbsp; и сможете рассчитывать на увеличение материального вознаграждения и карьерный рост.</span></span></span><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: ''times new roman'',times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #ffffff; background-color: #ffffff;"><span style="color: #0000ff;"> <strong><a class="modal" href="#call_me" rel="{size:{x:460,y:130}}"><span style="color: #0000ff; background-color: #ffffff;">Отправить заявку</span></a></strong></span></span></span></span></span></p>\r\n<p style="text-align: justify;"><span style="font-family: ''times new roman'',times; font-size: 12pt;"><span style="color: #0000ff;"><a href="index.php?option=com_content&amp;view=article&amp;id=21:kurs-qnalogooblozhenie-planirovanie-i-optimizatsiyaq&amp;catid=2:uncategorised"><span style="color: #0000ff;">Курсы по налогам и оптимизации&nbsp; налогобложения</span>:</a></span> для руководителей, предпринимателей&nbsp; - являются оптимальным изложением налогового кодекса на практических примерах. С какими проблемами сталкиваются предприниматели при регистрации предприятия и дальнейшей организации бухгалтерского и налогового учета на предприятии, порядка ведения кассовой дисциплины. Как платить налоги и "не переплачивать", и кто "владеет информацией", тот" владеет ситуацией".<br /></span></p>\r\n<p style="text-align: justify;"><span style="font-family: ''times new roman'',times; font-size: 12pt;">Пройдя курсы по налогам и&nbsp; и оптимизации налогообложения&nbsp; разработанные опытными<span><span><span><span>&nbsp;</span></span></span></span><span style="font-family: ''times new roman'',times; font-size: 12pt;">специалистами компании «ЭмМенеджмент»</span><span style="font-family: ''times new roman'',times; font-size: 12pt;">&nbsp; вы сможете разбираться в тонкостях налогового права, самостоятельно рассчитывать налоги, научитесь подбирать оптимальную систему налогообложения и минимизируете риск от&nbsp; неожиданных налоговых проверок.<span><span><span><span>&nbsp;</span></span></span></span> </span></span></p>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: ''times new roman'',times; font-size: 12pt;"><span><span><span><span><span style="color: #0000ff;"><a href="index.php?option=com_content&amp;view=article&amp;id=29:kurs-finansy-predpriyatiya&amp;catid=2:uncategorised&amp;Itemid=191"><span style="color: #0000ff;">Курсы повышения квалификации экономистов</span></a></span> &nbsp; </span></span></span></span></span></span><span style="font-family: times new roman,times;"><span style="font-family: ''times new roman'',times;"><span style="font-family: ''times new roman'',times; font-size: 10pt; color: #000000;"><span style="font-family: times new roman,times;"><span style="font-family: ''times new roman'',times;"><span style="font-family: ''times new roman'',times;"><span style="font-size: 12pt;">состоит из двух базовых курсов экономики и бюджетирования предприятия. После прохождения курса по финансам вы п<span style="font-family: ''times new roman'',times;">олучите комплекс практических инструментов по разработке и оптимизации систем управленческого учета, бюджетированию, управления инвестициями. Разберете и закрепите на практических примерах процессы управления экономикой компании. <br /></span></span></span></span></span></span></span></span><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: ''times new roman'',times;"></span></span><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: ''times new roman'',times; font-size: 12pt;"><span><span><span><span></span></span></span></span></span></span><span><span><span><span>&nbsp;&nbsp;</span></span></span></span><em> </em></div>\r\n<div style="text-align: justify;"><em><span style="font-family: ''times new roman'',times; font-size: 12pt;"><strong>Ключевые составляющие учебных программ</strong></span></em></div>\r\n<p style="text-align: justify;"><span style="font-family: ''times new roman'',times; font-size: 12pt;">Залог успеха любых курсов повышения квалификации&nbsp; − комплексное</span><span><span><span><span>&nbsp;</span></span></span></span><span style="font-family: ''times new roman'',times; font-size: 12pt;">освещение всех аспектов финансового учета. Именно поэтому при составлении программы</span><span><span><span><span>&nbsp;</span></span></span></span><span style="font-family: ''times new roman'',times; font-size: 12pt;">преподаватели традиционно уделяют внимание следующим вопросам:</span><br /><span style="font-family: ''times new roman'',times; font-size: 12pt;">− бухгалтерская отчетность и аудит;</span><br /><span style="font-family: ''times new roman'',times; font-size: 12pt;">− системы налогообложения;</span><br /><span style="font-family: ''times new roman'',times; font-size: 12pt;">− управление финансами;</span><br /><span style="font-family: ''times new roman'',times; font-size: 12pt;">− правовое регулирование деятельности физических и юридических лиц;</span><br /><span style="font-family: ''times new roman'',times; font-size: 12pt;">− экономический анализ.</span></p>\r\n<p style="text-align: justify;"><span><span>&nbsp;</span></span></p>\r\n<p><img style="position: absolute; left: -9999px;" src="//mc.yandex.ru/watch/15669946" alt="" /></p>\r\n<!-- /Yandex.Metrika counter -->', '', 1, 2, '2012-03-04 09:09:58', 42, '', '2014-09-07 08:43:25', 42, 0, '0000-00-00 00:00:00', '2012-03-04 09:09:58', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":null,"urlatext":"","targeta":"","urlb":null,"urlbtext":"","targetb":"","urlc":null,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 309, 59, 'курсы повышения квалификации для бухгалтеров, курсы и семинары для юристов, курсы и семинары для экономистов, ЭмМенеджмент центр эффективного обучения, курсы бухгалтеров в Екатеринбурге, курс обучения налоги, курсы по налогам, семинары по налогообложению, курсы по налоговой отчетности, Тренинги по продажам, тренинги управления персоналом', 'Курсы и семинары для бухгалтеров, юристов, экономистов. Тренинги по продажам и управлению персоналом\r\n', 1, 6891, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(17, 61, 'Финансовые услуги', 'finansovye-uslugi', '<h1><span style="font-size: 14pt; color: #8c2223; font-family: times new roman,times;"><span style="color: #0000ff; font-size: 12pt;">Эффективная система управления экономикой предприятия</span><strong><br /></strong></span></h1>\r\n<div style="text-align: justify;"><span style="font-size: 10pt; font-family: times new roman,times;">Услуга по&nbsp;организации системы управленческого учета состоит в&nbsp;методологическом обеспечении и&nbsp;постановке управленческого учета клиента. Объективность и&nbsp;оперативность принятия управленческих решений повышает эффективность менеджмента в&nbsp;компании.</span></div>\r\n<div style="text-align: justify;"><span style="font-size: 10pt; font-family: times new roman,times; color: #0000ff;">Цель предоставления услуги:</span></div>\r\n<ul style="text-align: justify;">\r\n<li><span style="font-size: 10pt; font-family: times new roman,times;">Предоставление достаточной информации, необходимой для принятия управленческих решений (достаточность информации определяется той учетной информацией, которая необходима для менеджмента в&nbsp;целях максимально эффективного управления деятельностью предприятия).</span></li>\r\n<li><span style="font-size: 10pt; font-family: times new roman,times;">Определение эффективности бизнеса в&nbsp;целом, каждого структурного подразделения.</span></li>\r\n<li><span style="font-size: 10pt; font-family: times new roman,times;">Контроль за финансовыми потоками, планирование и контроль бюджета организации<br /></span></li>\r\n<li><span style="font-size: 10pt; font-family: times new roman,times;">Управление (минимизация) затратами предприятия.</span></li>\r\n</ul>\r\n<div style="text-align: justify;"><span style="font-size: 10pt; font-family: times new roman,times;"><img style="margin: 8px 10px 0px 0px; float: left;" alt="0 505f0 95fc01f xl" src="images/0_505f0_95fc01f_xl.jpg" height="98" width="157" /></span><span style="font-size: 10pt; font-family: times new roman,times;">Поставленная цель достигается диагностикой существующей системы бухгалтерского учета, анализа хозяйственной деятельности, контроля, принятия управленческих решений; разработкой и&nbsp;внедрением системы управленческого учета, бюджетирования.</span></div>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 10pt;"><strong><span style="color: #0000ff;">&nbsp;</span></strong></span></div>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 10pt;"><strong><span style="color: #0000ff;">&nbsp;</span></strong></span></div>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 10pt;"><strong><span style="color: #0000ff;">Задачи системы управленческого учета:</span></strong></span></div>\r\n<ul>\r\n<li><span style="font-size: 10pt; font-family: times new roman,times;">Обеспечение контроля над наличием, движением, эффективным распределением имущества, материальных, денежных и&nbsp;трудовых ресурсов для достижения целей предприятия.</span></li>\r\n<li><span style="font-size: 10pt; font-family: times new roman,times;">Разработка системы бюджетирования на предприятиии: выявление центров финансовой ответственности, регламентация бюджетного процесса</span></li>\r\n<li><span style="font-size: 10pt; font-family: times new roman,times;">Применение современных методов калькуляции себестоимости продукции</span></li>\r\n<li><span style="font-size: 10pt; font-family: times new roman,times;">Оптимизация расходов методами Директ-кост, Стандарт-кост</span></li>\r\n<li><span style="font-size: 10pt; font-family: times new roman,times;">Определение эффективности функционирования подразделений организации и&nbsp;их&nbsp;вклада в&nbsp;формировании прибыли предприятия.</span></li>\r\n</ul>\r\n<p>&nbsp;</p>', '', 1, 2, '2012-03-04 09:50:19', 42, '', '2014-06-06 21:00:37', 42, 0, '0000-00-00 00:00:00', '2012-03-04 09:50:19', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":null,"urlatext":"","targeta":"","urlb":null,"urlbtext":"","targetb":"","urlc":null,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 31, 58, 'финансовые услуги, Управление затратами, директ костинг, бизнес планирование, управленческий учет, анализ хозяйственной деятельности', 'Финансовые услуги', 1, 857, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content_v3` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(18, 64, 'Курсы Экономика предприятия, управленческий учет, Excel', 'upravlencheski-uchet', '<h1 style="text-align: left;"><span style="color: #174f3b;"><strong><span style="font-family: times new roman,times; font-size: 14pt;"></span></strong><span style="font-size: 12pt; color: #000080;"><strong><span style="font-family: times new roman,times;"><span style="color: #0000ff;">Курсы Экономика предприятия, управление затратами</span><br /></span></strong></span></span></h1>\r\n<div style="text-align: justify;"><span style="color: #174f3b;"><span style="font-size: 12pt; color: #000080;"><span style="font-family: times new roman,times;"><span style="color: #0000ff;"><span style="color: #000000;"><strong><span style="font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;"><strong><span style="color: #000000;">Целевая аудитория: </span></strong></span></span></strong><span style="font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;"><span style="color: #000000;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;">руководители подразделений, финансовые менеджеры, работники планово-экономического отдела, бухгалтер, главный бухгалтер</span></span></span></span></span></span></span></span></span></span></div>\r\n<div style="text-align: justify;"><span style="color: #174f3b;"><span style="font-size: 12pt; color: #000080;"><span style="font-family: times new roman,times;"><span style="color: #0000ff;"><span style="color: #000000;"><strong><span style="font-size: 12pt;">Ведущий</span></strong></span><span style="font-size: 12pt; color: #000000;"><span style="font-family: times new roman,times;"><strong><span style="color: #000000;">:</span> </strong><a href="index.php?option=com_content&amp;view=article&amp;id=53:biznes-trener-nasonova-nadezhda-yurevna&amp;catid=2:uncategorised">Насонова Надежда Юрьевна </a></span></span></span></span></span></span></div>\r\n<div><span style="color: #174f3b;"><span style="font-size: 12pt; color: #000080;"><strong><span style="font-family: times new roman,times; color: #000000;">В программе</span><span style="font-family: times new roman,times;"><br /></span></strong></span></span></div>\r\n<div><span style="font-family: ''times new roman'',times; color: #0000ff; font-size: 12pt;">1.Основы экономики предприятия</span></div>\r\n<ul>\r\n<li><span style="font-size: 12pt;"><span style="font-family: ''times new roman'',times;">Точка безубыточности. Анализ безубыточности</span></span></li>\r\n<li><span style="font-family: ''times new roman'',times; font-size: 12pt;">&nbsp;Ключевой расчет маржинальной прибыли, чистой прибыли </span></li>\r\n<li><span style="font-size: 12pt;"><span style="font-family: ''times new roman'',times;">&nbsp;Ключевые показатели эффективности предприятия,&nbsp; </span><span style="font-family: ''times new roman'',times;"><span style="font-family: ''times new roman'',times;"><span style="font-family: ''times new roman'',times;"><span class="mw-headline">EBITDA, ROE</span></span></span></span></span></li>\r\n<li><span style="font-family: ''times new roman'',times; font-size: 12pt;">&nbsp;Анализ финансовых результатов деятельности</span></li>\r\n<li><span style="font-family: ''times new roman'',times; font-size: 12pt; color: #0000ff;"><span style="color: #000000;">Анализ эффективности использования&nbsp; оборотных средств (оборачиваемость, материалоемкость). Нормирование.</span></span></li>\r\n<li><span style="font-size: 12pt;"><span style="font-family: ''times new roman'',times; color: #0000ff;"><span style="color: #000000;">Анализ &nbsp;<span style="font-family: ''times new roman'',times; color: #0000ff;"><span style="color: #000000;">эффективности использования трудовых ресурсов </span></span></span></span><span style="font-style: normal; font-variant: normal; font-weight: normal; line-height: normal; font-family: ''times new roman'',times;">(выработка, трудоемкость)</span></span></li>\r\n</ul>\r\n<div style="margin: 0cm 0cm 0.0001pt 14.25pt; text-indent: -14.25pt; text-align: justify;"><span style="font-family: ''times new roman'',times; font-size: 12pt;">&nbsp; - <b><i><span style="font-family: ''Times New Roman'';">Практические задания точки безубыточности и валовой маржи. Определение наиболее рентабельных проектов, видов деятельности, продукции</span></i></b></span></div>\r\n<div style="margin: 0cm 0cm 0.0001pt 14.25pt; text-indent: -14.25pt; text-align: justify;"><span style="font-family: ''times new roman'',times; font-size: 12pt;"><b><i><span style="font-family: ''Times New Roman'';">&nbsp;</span></i></b></span></div>\r\n<div style="margin: 0cm 0cm 0.0001pt 14.25pt; text-indent: -14.25pt; text-align: justify;"><span style="font-family: ''times new roman'',times; font-size: 12pt;"><b><i><span style="font-family: ''Times New Roman'';"></span></i></b></span><span style="color: blue; font-family: times new roman,times; font-size: 12pt;">2. Эффективная финансово – экономическая служба<b><i><span style="border: 1pt none windowtext; padding: 0cm;"></span></i></b></span></div>\r\n<ul>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Требования к финансовой отчетности для руководителей.</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Принципы учетной политики управленческого учета. </span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Чтение и интерпретации финансовых отчетов. Практикум по подготовке и использованию финансовой отчетности</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Функции финансового управляющего. </span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Распределение функций финансово-экономической службы. </span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Показатели эффективности финансовой службы.</span></li>\r\n</ul>\r\n<p>&nbsp;<span style="font-family: ''times new roman'',times; font-size: 12pt; color: #0000ff;">3. Организация аналитического учета затрат</span></p>\r\n<ul>\r\n<li style="text-align: justify;"><span style="font-family: ''times new roman'',times; font-size: 12pt;"><span style="font-family: ''times new roman'',times;"></span>Бухгалтерский план счетов, с использованием которых осуществляется учет затрат на производство. <span style="font-family: ''times new roman'',times;">Группировка балансовых статей, баланс предприятия,&nbsp; строение балансовых счетов.</span></span></li>\r\n<li style="margin-top: 0cm; margin-right: 0cm; margin-bottom: 0.0001pt; text-indent: 0cm; text-align: justify;"><span style="font-style: normal; font-variant: normal; font-weight: normal; font-size: 12pt; line-height: normal; font-family: ''times new roman'',times;">Затраты по статьям калькуляции. Учет отдельных видов затрат. Система " Директ - костинг"</span></li>\r\n<li style="margin-top: 0cm; margin-right: 0cm; margin-bottom: 0.0001pt; text-indent: 0cm; text-align: justify;"><span style="font-style: normal; font-variant: normal; font-weight: normal; font-size: 12pt; line-height: normal; font-family: ''times new roman'',times;">Специфика и области применения различных методов учета производственных затрат: позаказного, котлового, попередельного.</span></li>\r\n<li style="margin-top: 0cm; margin-right: 0cm; margin-bottom: 0.0001pt; text-align: justify;"><span style="font-size: 12pt;"><span style="font-family: times new roman,times; font-style: normal; font-variant: normal; font-weight: normal; line-height: normal;"><span style="font-family: times new roman,times; font-style: normal; font-variant: normal; font-weight: normal; line-height: normal;">Классификация расходов и затрат,&nbsp; формирующих себестоимость продукции,&nbsp;</span></span><span style="font-family: times new roman,times; font-style: normal; font-variant: normal; font-weight: normal; line-height: normal;"> их отличия</span></span></li>\r\n</ul>\r\n<div><span style="font-size: 12pt; font-family: times new roman,times;">Продолжительность: 15 часов - 2 недели , 2 раза в неделю, среда с 18.30 до 21.30, &nbsp;суббота с 14.00 до 18.00 . Выдается методическая литература.<span style="font-style: inherit; font-variant: inherit; font-weight: inherit; line-height: inherit; color: #222222; text-align: left; margin: 0px; padding: 0px; border: 0px none; vertical-align: baseline;"><span style="margin: 0px; padding: 0px; border: 0px none; font-style: inherit; font-variant: inherit; font-weight: inherit; line-height: inherit; vertical-align: baseline;">&nbsp;&nbsp;</span></span></span></div>\r\n<div style="text-align: justify;"><span style="font-size: 12pt; font-family: times new roman,times;">Для иногородних есть возможность пройти курсы дистанционного обучения.</span><span style="font-family: ''times new roman'', times; font-size: 10pt; font-style: inherit; font-variant: inherit; font-weight: inherit; line-height: inherit; color: #222222; text-align: left;">&nbsp;</span><span style="text-align: justify; font-size: 12pt; font-family: ''times new roman'', times;"><span style="font-size: 12pt;"><span style="color: #ffffff;"><span style="color: #0000ff;">&nbsp;<a class="modal" href="#call_me" rel="{size:{x:460,y:130}}"><span style="color: #0000ff;">Отправить заявку</span></a></span></span></span></span><span style="text-align: justify; font-family: ''times new roman'', times; font-size: 12pt;">&nbsp;&nbsp;<span style="font-size: 12pt;"><span style="color: #0000ff;"><a href="index.php?option=com_content&amp;view=article&amp;id=20:ekonomicheskie-kursy&amp;catid=8:obrazovanie&amp;Itemid=171"><span style="color: #0000ff;">Расписание курса</span></a></span></span></span></div>\r\n<p style="text-align: justify;"><span style="color: #333333;"><span style="font-family: times new roman,times; font-size: 12pt;">&nbsp;</span></span><span style="font-family: ''times new roman'', times; font-size: 12pt; color: #333333;">Стоимость 7900 рублей. </span><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #993366;">Скидка 5%</span> при оплате за 2&nbsp; недели до начала обучения&nbsp;</span></span></p>', '', 1, 8, '2012-05-05 12:22:26', 42, '', '2014-10-20 08:18:59', 42, 0, '0000-00-00 00:00:00', '2012-05-05 12:22:26', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":null,"urlatext":"","targeta":"","urlb":null,"urlbtext":"","targetb":"","urlc":null,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 66, 0, 'курсы оптимизация налогообложения, курсы управленческий учет, семинар финансовое планирование, Екатеринбург, экономика предприятия, управление затратами + Excel', 'Экономические курсы Управление затратами + Excel"', 1, 1828, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(19, 65, 'Курсы бухучета. Налоги. 1С', 'kursy-bukhgalterskogo-ucheta', '<p style="text-align: left;" align="center">Курсы бухгалтера сейчас крайне востребованы, так как бухучет обязано вести любой предприятие независимо от сферы деятельности и размеров.</p>\r\n', '\r\n<p style="text-align: left;" align="center"> </p>\r\n<h1 style="text-align: justify;" align="center"><span style="color: #1b6779;"><strong><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;"><span style="font-family: arial,helvetica,sans-serif;"><span style="font-family: times new roman,times;">Курсы бухгалтера <span style="color: #1b6779;"><span style="color: #0000ff;">в Екатеринбурге -</span></span> обучение бухгалтерский учет, налоги, отчетность и 1: С. Оптимальные бухгалтерские курсы.</span> </span></span><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;"><br /></span></strong></span></h1>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"><img style="margin-right: 5px; float: left;" src="images/Girl-on-Phone-at-Computer.jpg" alt="Girl-on-Phone-at-Computer" width="162" height="87" />Курсы бухгалтера</span><span style="font-family: times new roman,times; font-size: 12pt;"> сейчас<em style="font-family: times new roman,times; font-size: 12pt;"> крайне востребованы</em>, так как бухгалтер или штат бухгалтеров, сегодня есть на каждом предприятие и не зависимо от сферы его деятельности и размера обязаны предоставлять<em> бухгалтерскую и налоговую отчетность, и как правило ведут бухгалтерский, налоговый учет в программе 1 С Бухгалтерия.</em> БУХГАЛТЕРСКИЕ КУРСЫ с нуля будут полезны и для людей, которые  планируют или уже  <em>открыли собственное дело</em>: ведь только разобравшись во всех тонкостях на обучении бухучету, налогообложению можно определиться с лучшей организационно-правовой формой и оптимальной системой налогообложения будущей компании, а также самостоятельно  сдавать бухгалтерскую и налоговую отчетность.  <span style="font-size: 12pt; font-family: times new roman,times; color: #000000;">Ваши  вложения на курсах бухгалтеров  окупятся в сотни раз!</span></span></div>\r\n<table style="width: 606px; height: 99px;" border="0">\r\n<tbody>\r\n<tr>\r\n<td dir="ltr">\r\n<div dir="ltr"><span style="font-family: times new roman,times; font-size: 14pt;"><a href="index.php?option=com_content&amp;view=article&amp;id=9:kursy-nachinayushchikh-bukhgalterov-ekaterinburg&amp;catid=8:obrazovanie">Б<span style="font-size: 12pt;">ухгалтерский учет</span>, <span style="font-size: 12pt;">налоги</span> +<span style="font-size: 12pt;">1С  (базовый курс)</span> <span style="font-size: 12pt;">вечерние</span></a></span></div>\r\n</td>\r\n<td><span style="color: #0000ff;"> <span style="font-size: 12pt; font-family: times new roman,times;">10.02.15</span></span></td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<div><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"><span style="font-family: terminal,monaco;"><a href="index.php?option=com_content&amp;view=article&amp;id=9:kursy-nachinayushchikh-bukhgalterov-ekaterinburg&amp;catid=8:obrazovanie"><span style="font-family: times new roman,times;">Бухгалтерский</span> <span style="font-family: times new roman,times;">учет, налоги + 1С  (базовый курс)</span> <span style="font-family: times new roman,times;">выходного дня</span></a></span></span></span></div>\r\n</td>\r\n<td><span style="color: #0000ff;"><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"><span style="color: #0000ff;"><span style="font-family: arial,helvetica,sans-serif;"><span style="font-family: times new roman,times; font-size: 12pt; color: #000000;"><span style="color: #0000ff;"> <span style="font-size: 12pt;"><span style="font-family: times new roman,times;"><span style="color: #0000ff;"><span style="font-size: 12pt; font-family: times new roman,times;">31.01.15</span></span></span></span></span></span></span></span></span></span></span></span></span></td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<div dir="ltr"><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"><span style="font-size: 12pt; font-family: times new roman,times;"><a href="index.php?option=com_content&amp;view=article&amp;id=35:kurs-nalogi-bukhgalterskaya-i-nalogovaya-otchetnost&amp;catid=2:uncategorised">Налоги, бухгалтерская и налоговая отчетность + 1 С</a></span></span></span></div>\r\n</td>\r\n<td>\r\n<div><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"><span style="color: #0000ff;"><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"><span style="color: #0000ff;"><span style="font-family: arial,helvetica,sans-serif;"><span style="font-family: times new roman,times; font-size: 12pt; color: #000000;"><span style="color: #0000ff;"> 13.01.15<br /></span></span></span></span></span></span></span></span></span></span></span></span></span></div>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<div><span style="color: #0000ff;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-size: 12pt; font-family: times new roman,times;"><a href="index.php?option=com_content&amp;view=article&amp;id=13:1&amp;catid=10:kursy-praktikuyushchikh-bukhgalterov"><span style="color: #0000ff;">Курс Г</span></a></span></span><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-size: 12pt; font-family: times new roman,times;"><a href="index.php?option=com_content&amp;view=article&amp;id=13:1&amp;catid=10:kursy-praktikuyushchikh-bukhgalterov"><span style="color: #0000ff;">лавный бухгалтер, практикующий бухгалтер</span></a></span></span></span></div>\r\n</td>\r\n<td><span style="color: #0000ff; font-family: times new roman,times;"><span style="font-size: 12pt;"> <span style="font-size: 12pt;"><span style="font-family: times new roman,times;"><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"><span style="color: #0000ff;"><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"><span style="color: #0000ff;"><span style="font-family: arial,helvetica,sans-serif;"><span style="font-family: times new roman,times; font-size: 12pt; color: #000000;"><span style="color: #0000ff;">12.12.14</span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<div><span style="color: #0000ff;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-size: 12pt; font-family: times new roman,times;"><a href="index.php?option=com_content&amp;view=article&amp;id=15:envd-usno-patentnaya-sistema&amp;catid=12:envd-usno-patentnaya-sistema"><span style="color: #0000ff;">Упрощенная система, ЕНВД, патентная система +1С</span></a></span></span></span></div>\r\n</td>\r\n<td><span style="color: #0000ff;"><span style="font-family: arial,helvetica,sans-serif;"> <span style="font-size: 12pt; font-family: times new roman,times;">10.02.15</span></span><span style="font-size: 12pt;"><span style="font-family: arial,helvetica,sans-serif;"><br /></span></span></span></td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<div><span style="color: #0000ff;"><a href="index.php?option=com_content&amp;view=article&amp;id=12:kursy-1s-qbukhgalteriya-8q&amp;catid=9:kursy-1s-qbukhgalteriya-8q"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #0000ff;">1 С Бухгалтерия 8</span></span></span></a><span style="font-family: arial,helvetica,sans-serif;"><a href="index.php?option=com_content&amp;view=article&amp;id=12:kursy-1s-qbukhgalteriya-8q&amp;catid=9:kursy-1s-qbukhgalteriya-8q"><span style="font-family: times new roman,times; font-size: 12pt; color: #000000;"><span style="color: #0000ff;"> +</span><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #000000;"><span style="color: #0000ff;"> 1 С  Зарплата и Управление персоналом (ЗУП)</span> </span></span></span></a></span></span></div>\r\n</td>\r\n<td><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"><span style="color: #0000ff;"><span style="font-family: arial,helvetica,sans-serif;"><span style="font-family: times new roman,times; font-size: 12pt; color: #000000;"> <span style="color: #0000ff;">23</span><span style="color: #0000ff;">.</span><span style="color: #0000ff;">12.14</span></span></span></span></span></span></td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<div><span style="color: #0000ff;"><a href="index.php?option=com_content&amp;view=article&amp;id=34:seminar-po-nalogovym-proverkam&amp;catid=2:uncategorised"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #0000ff;">Семинар Налоговые проверки, типичные ошибки</span></span></span></a></span></div>\r\n</td>\r\n<td><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"><span style="color: #0000ff;"><span style="font-family: arial,helvetica,sans-serif;"><span style="font-family: times new roman,times; font-size: 12pt; color: #000000;"> </span></span></span></span></span></td>\r\n</tr>\r\n<tr>\r\n<td><span style="font-family: times new roman,times; font-size: 12pt;"><a href="index.php?option=com_content&amp;view=article&amp;id=21:kurs-qnalogooblozhenie-planirovanie-i-optimizatsiyaq&amp;catid=2:uncategorised">Налоги для руководителей, оптимизации налогобложения</a></span></td>\r\n<td> </td>\r\n</tr>\r\n<tr>\r\n<td><a href="index.php?option=com_content&amp;view=article&amp;id=75:kursy-obuchenie-zarabotnaya-plata-otchetnost-v-pensionnyj-fond-i-fond-sotsialnogo-strakhovaniya-1-s-zarplata-i-upravlenie-personalom-zup&amp;catid=2:uncategorised"><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;">Заработная плата, отчетность в ПФ, ФСС + 1 С ЗУП</span></a></td>\r\n<td><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"><span style="color: #0000ff;"><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"><span style="color: #0000ff;"><span style="font-family: arial,helvetica,sans-serif;"><span style="font-family: times new roman,times; font-size: 12pt; color: #000000;"><span style="color: #0000ff;"> 13.01.15</span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<h2 dir="ltr" style="text-align: justify; text-indent: 35.4pt;"><img src="data:image/jpeg;base64," alt="" width="26" height="20" /><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #000000;"><a href="index.php?option=com_content&amp;view=article&amp;id=19:kursy-bukhgalterskogo-ucheta&amp;catid=8:obrazovanie&amp;Itemid=170"><span style="color: #000000;"><strong><span style="color: #0000ff;">о Бухгалтерских курсах </span></strong></span></a><span style="color: #0000ff;"><a href="index.php?option=com_content&amp;view=article&amp;id=19:kursy-bukhgalterskogo-ucheta&amp;catid=8:obrazovanie&amp;Itemid=170"><span style="color: #0000ff;"><strong><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"><span style="color: #0000ff;"> (базовый курс) </span></span></span></strong></span></a></span></span></span></span></h2>\r\n<p style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt; color: #000000;">Если вы ищете курсы бухгалтера в Екатеринбурге, оптимальным выбором будет обратиться в образовательный центр «ЭмМенеджмент». Мы предлагаем простую и эффективную программу освоения финансового учета для специалистов, которая позволит в течение нескольких месяцев приобрести все необходимые знания с самостоятельного ведения бухучета и сдачи налоговой отчетности.</span></p>\r\n<p><span style="color: #000000;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;">Программа  </span>курсов бухгалтеров  Екатеринбурге <strong><em> - </em> </strong>базовый  курс преимущественно рассчитан  </span><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"> на людей c любым  образованием. Чтобы полноценно освоить все теоретические знания и практические навыки, слушателям потребуется 1,5 месяца. Чтобы эффективно провести обучение на курсах бухгалтера вам будут даваться<strong> практические самостоятельные задания</strong>.</span></span></span></p>\r\n<h3 style="text-align: justify;" align="center"><span style="color: #000000;"><strong><span style="font-family: times new roman,times; font-size: 12pt;">Курсы  бухгалтерии - налогам - отчетности  -  1: С </span></strong><span style="font-family: times new roman,times; font-size: 12pt;">включают:</span></span></h3>\r\n<ul>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #000000;">изучение нормативно-правовой базы, которая регулирует  сферу деятельности бухгалтерии: <em>Закон о бухгалтерском учете, ПБУ, налоговый кодекс</em>.</span></span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #000000;">чтобы облегчить будущим специалистам ведение учета, преподаватели «ЭмМенеджмент» подробно останавливаются на каждом объекте бухгалтерского учета.</span></span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #000000;">тщательнейшим образом на примерах разбирается</span><em><span style="color: #000000;"> налог</span>ообложение: общая, ЕНВД, УСНО, патентная система</em>. На обучение по налоговой отчетности вы будете заполнять декларации по всем основным налогам, а также отчетность по страховым взносам (ФСС, ПФ, ФФОМС).</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">важной частью обучения на курсах бухгалтерского учета и налогообложения являются практические занятия, в частности,  программа <em>1С: «Бухгалтерия»</em>. </span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">уникальность предлагаемой центром «ЭмМенеджмент» программы заключается в особой подаче материала. Наши специалисты описывают материал очень емко и последовательно, отдельно останавливаются на самых важных или сложных аспектах ведения бухгалтерии и всегда готовы ответить на вопросы слушателей. Именно поэтому даже люди, которые прежде никогда не имели дела с финансовым учетом, по завершении курса <em>становятся квалифицированными специалистами</em>.</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;">если вы предприниматель, то<em> <span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;">полученные навыки на курсах бухгалтера  позволят </span></span></span>сэкономить</em> на услугах наемного специалиста и быть полностью уверенным, что бухгалтерия фирмы находится в полном порядке, а с налоговыми или другими контролирующими органами впоследствии не возникнет никаких проблем.</span></span></span></li>\r\n<li style="text-align: justify;">\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #000000; font-family: times new roman,times; font-size: 12pt;"><span style="font-family: ''times new roman'',times; font-size: 12pt;"><span style="font-size: 12pt; line-height: 115%; font-family: times new roman,times;">и что очень важно, будете получать обратную связь от преподавателя по результатам проведенной вами работы. </span></span></span></span></span></div>\r\n</li>\r\n<li class="_mce_tagged_br" style="text-align: justify;">\r\n<div><span style="font-size: 12pt; line-height: 115%; font-family: times new roman,times;">для облегчения процесса обучения: вам будет даваться удобный раздаточный материал. Вам нужно тратить время только на получение знаний и отработку практических навыков. </span></div>\r\n</li>\r\n<li class="_mce_tagged_br" style="text-align: justify;"><span style="font-size: 12pt; line-height: 115%; font-family: times new roman,times;"> <span style="font-family: times new roman,times;">количество  человек в группе ограничено! до 12 слушателей. </span><span style="font-family: times new roman,times;"><span style="color: #ffffff; background-color: #ffffff;"> <span style="color: #0000ff;"> <strong><a class="modal" href="http://%D1%8D%D0%BC%D0%BC%D0%B5%D0%BD%D0%B5%D0%B4%D0%B6%D0%BC%D0%B5%D0%BD%D1%82.%D1%80%D1%84/obrazovanie/kursy-bukhgalterskogo-ucheta/8-obrazovanie/9-kursy-nachinayushchikh-bukhgalterov-ekaterinburg#call_me" rel="{size:{x:460,y:130}}"><span style="color: #0000ff; background-color: #ffffff;">Отправить заявку</span></a></strong></span></span></span></span></li>\r\n</ul>\r\n<p><span style="font-size: 12pt;"><span style="line-height: 115%; font-family: times new roman,times;">Рады будем вас видеть на обучение. До встречи в центре эффективного</span><span style="font-family: ''Times New Roman'',''serif'';"><span style="font-family: times new roman,times;"> обучения «ЭмМенеджмент».</span> </span></span></p>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;">Если Вы уже практикующий главный бухгалтер, Вам будут интересны <a href="index.php?option=com_content&amp;view=article&amp;id=13:kursy-praktikuyushchij-bukhgalter-glavnyj-bukhgalter&amp;catid=10:kursy-praktikuyushchikh-bukhgalterov">курсы повышения квалификации бухгалтера.</a><br /></span></span>\r\n<h1 style="margin: 0px 0px 0.5em; padding: 0px; border: 0px none; font-style: inherit; font-variant: inherit; font-size: inherit; font-size-adjust: inherit; font-stretch: inherit; -moz-font-feature-settings: inherit; -moz-font-language-override: inherit; vertical-align: baseline; font-weight: normal; color: #000080; line-height: 1; font-family: Tahoma,Arial; text-align: justify;"> </h1>\r\n</div>', 1, 8, '2012-06-03 13:53:33', 42, '', '2014-12-29 13:43:23', 42, 0, '0000-00-00 00:00:00', '2012-06-03 13:53:32', '0000-00-00 00:00:00', '{"image_intro":"images\\/icons\\/1-buh-uchet.jpg","float_intro":"","image_intro_alt":"\\u041a\\u0443\\u0440\\u0441\\u044b \\u0431\\u0443\\u0445\\u0433\\u0430\\u043b\\u0442\\u0435\\u0440\\u0441\\u043a\\u043e\\u0433\\u043e \\u0443\\u0447\\u0435\\u0442\\u0430 \\u0432 \\u0415\\u043a\\u0430\\u0442\\u0435\\u0440\\u0438\\u043d\\u0431\\u0443\\u0440\\u0433\\u0435","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 324, 4, 'бухгалтерские курсы в Екатеринбурге, курсы бухгалтерского учета, курсы бухгалтера Екатеринбург, курсы бухгалтерия, повышение квалификации бухгалтеров, курсы повышения квалификации бухгалтера, обучение бухгалтеров, курсы  1 С Бухгалтерия', 'Курсы бухгалтера в Екатеринбурге: бухгалтерский учет, налоги,  1С Бухгалтерия - оптимальные бухгалтерские курсы ', 1, 4032, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content_v3` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(20, 66, 'Экономика и финансы', 'ekonomicheskie-kursy', '<p style="text-align: left;" align="center">Курсы по экономике и финансам в областях бюджетирования, управленческого учета и финансового менеджмента.</p>\r\n', '\r\n<p style="text-align: left;" align="center"> </p>\r\n<h1 style="text-align: justify;" align="center"><span style="color: #0000ff; font-size: 12pt;"><span style="font-family: times new roman,times;"><strong>Курсы экономика - Управление финансами: бюджетирование и <span style="color: #0000ff; font-size: 12pt;"><span style="font-family: times new roman,times;"><strong>управленческий учет  </strong></span></span>+ </strong><span style="color: #0000ff;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #0000ff;">Excel. Управление инвестициями.  Курсы повышения квалификации  экономистов<strong>.</strong></span></span></span></span></span><span style="font-family: times new roman,times; font-size: 14pt; color: #8c2223;"><strong><span style="color: #000080;"><br /></span></strong></span></h1>\r\n<div style="text-align: justify;" align="center"><span style="font-family: times new roman,times; font-size: 12pt;">Успех компании во многом зависит от эффективности управления экономикой  компании и инвестирования. Курсы экономики -  это обучение  бюджетированию, управленческому учету и финансовому менеджменту, ответят на такие вопросы:</span></div>\r\n<ul dir="ltr">\r\n<li style="text-align: justify;">\r\n<div style="text-align: left;"><span style="font-family: times new roman,times; font-size: 12pt;">  С чего начинается экономика предприятия: основные необходимые  показатели управленческого учета</span></div>\r\n</li>\r\n<li style="text-align: left;">\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;">  Бюджетирование - действительная необходимость? от плана до факта.  </span></div>\r\n</li>\r\n<li style="text-align: left;">\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;">  <span style="font-family: times new roman,times; font-size: 12pt;">Для чего нужны ЦФО (центры финансовой ответственности). </span>Как? и кого? контролировать  чтобы планируемые показатели прибыли стали фактическими</span></div>\r\n</li>\r\n<li style="text-align: justify;">\r\n<div style="text-align: left;"><span style="font-family: times new roman,times; font-size: 12pt;">  Как  и какие инвестиции привлекать в свою компанию?</span></div>\r\n</li>\r\n</ul>\r\n<table style="width: 614px; height: 95px;" border="0">\r\n<tbody>\r\n<tr>\r\n<td><span style="color: #0000ff;"><span style="font-family: times new roman,times; font-size: 12pt;"><a href="http://эмменеджмент.рф/obrazovanie/ekonomicheskie-kursy/13-obrazovanie/upravlenie-zatratami/18-upravlenie-zatratami"><span style="color: #0000ff;">Курсы Экономика  предприятия, управленческий учет </span></a></span></span></td>\r\n<td>\r\n<div dir="ltr"><strong><span style="font-size: 10pt; font-family: symbol; color: #0000ff;"> </span></strong><span style="font-size: 10pt; font-family: symbol; color: #0000ff;">21.01.15</span></div>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td><span style="color: #0000ff;"><span style="font-family: times new roman,times; font-size: 12pt;"><a href="obrazovanie/ekonomicheskie-kursy/finansy-predpriyatiya"><span style="color: #0000ff;">Курсы Финансы предприятия (управленческий учет + бюджетирование)</span></a></span></span></td>\r\n<td>\r\n<div dir="ltr"> <span style="font-size: 10pt; font-family: symbol; color: #0000ff;">21.01.15</span></div>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td><span style="color: #0000ff;"><span style="font-family: times new roman,times; font-size: 12pt;"><a href="index.php?option=com_content&amp;view=article&amp;id=22:kurs-byudzhetirovanie-planirovanie-i-uchet&amp;catid=14:kurs-qbyudzhetirovanie-planirovanie-i-uchet"><span style="color: #0000ff;">Курсы Бюджетирование, как система управления + Excel</span></a></span></span></td>\r\n<td>\r\n<div dir="ltr"><strong> </strong><span style="color: #000080;"><span style="font-family: symbol; font-size: 10pt;"><span style="color: #0000ff;">31.01.15</span></span><br /></span></div>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td><a href="index.php?option=com_content&amp;view=article&amp;id=74:kurs-prodvinutyj-excel-obuchenie-excel&amp;catid=2:uncategorised"><span style="font-family: times new roman,times; font-size: 14pt;"><span style="color: #0000ff;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #0000ff;">Продвинутый <span style="font-family: times new roman,times; font-size: 14pt;"><span style="color: #0000ff;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #0000ff;">Excel, востребованные функции</span></span></span></span></span></span></span></span></a></td>\r\n<td><span style="color: #000080;"><span style="font-family: symbol; font-size: 10pt;"><span style="color: #0000ff;"> 07.02.15</span></span></span></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;"><strong>Экономические курсы,</strong> предлагаемые центром обучения «ЭмМенеджмент», <strong>помогут руководителям, финансовым менеджерам, работникам планово-экономического отдела</strong> предприятий глубже понять закономерности функционирования компании, сформировать финансовую стратегию предприятия с учетом тенденций развития экономики компании.</span></span></div>\r\n<div style="text-align: justify;"><strong><span style="color: #0000ff;"><span style="font-family: times new roman,times; font-size: 12pt;">Курсы  </span></span><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #0000ff;">экономики - </span></span><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #0000ff;"> эффективный инструмент  поддержки и роста вашей организации</span></span><span style="font-family: times new roman,times; font-size: 12pt;"><em><br /></em></span></strong></div>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Главная цель обучения<strong><em>:</em></strong></span></div>\r\n<ul>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">формирование у слушателей системного подхода в принятии управленческих решений, связанных с бюджетированием </span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">корректный расчет себестоимости </span></li>\r\n<li style="text-align: justify;">\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;">оптимизация затрат<br /></span></div>\r\n</li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">точный запланированный финансовый результат</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">плановое и системное поступление денежных средств</span><span style="font-family: times new roman,times; font-size: 12pt;"><br /></span></li>\r\n<li style="text-align: justify;">\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;">определение наиболее рентабельных проектов</span></div>\r\n</li>\r\n<li style="text-align: justify;">\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;">резервы увеличения прибыли</span></div>\r\n</li>\r\n</ul>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">    Уникальность курсов <span style="color: #000000; font-size: 12pt;"><span style="font-family: times new roman,times;"><span style="font-family: times new roman,times; font-size: 12pt;">повышения квалификации  экономистов </span></span></span> заключается в ее практической финансовой направленности. В ходе обучения высококвалифицированные преподаватели нашей компании помогают провести диагностику хозяйственной деятельности и бюджетирования предприятий слушателей и вместе с ними подбирают оптимальную финансовую стратегию и систему управления затратами.</span></div>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">    Обучение экономики, финансовому менеджменту в Екатеринбурге проводятся в отлично оборудованн</span><span style="font-family: times new roman,times; font-size: 12pt;">ом помещении в центре города. Программы рассчитаны на 20-40 часов.  <span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #ffffff; background-color: #ffffff;"><span style="color: #0000ff;"> <strong><a class="modal" href="#call_me" rel="{size:{x:460,y:130}}"><span style="color: #0000ff; background-color: #ffffff;">Отправить заявку</span></a></strong></span></span></span><br /></span></div>', 1, 8, '2012-06-03 18:53:08', 42, '', '2014-12-29 13:49:08', 42, 0, '0000-00-00 00:00:00', '2012-06-03 18:53:08', '0000-00-00 00:00:00', '{"image_intro":"images\\/icons\\/2-economika-finansy.jpg","float_intro":"","image_intro_alt":"\\u041a\\u0443\\u0440\\u0441\\u044b \\u043f\\u043e \\u0443\\u043f\\u0440\\u0430\\u0432\\u043b\\u0435\\u043d\\u0447\\u0435\\u0441\\u043a\\u043e\\u043c\\u0443 \\u0443\\u0447\\u0435\\u0442\\u0443 \\u0438 \\u0444\\u0438\\u043d\\u0430\\u043d\\u0441\\u043e\\u0432\\u043e\\u043c\\u0443 \\u043c\\u0435\\u043d\\u0435\\u0434\\u0436\\u043c\\u0435\\u043d\\u0442\\u0443","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 158, 3, 'экономические курсы, курсы экономистов, курсы повышения квалификации экономистов, курсы экономика екатеринбург, курсы управленческий учет, бдр, бддс, курсы бюджетирование, планирование доходов курсы, планирование расходов, оперативный учет, обучение бюджет движения денежных средств, маржинальная прибыль, директ - костинг', 'Курсы управленческого учета и бюджетирование ответят на такие вопросы.', 1, 2875, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(21, 67, 'Курс, обучения Налоги и налогообложение: планирование и оптимизация', 'kurs-qnalogooblozhenie-planirovanie-i-optimizatsiyaq', '<h1 dir="ltr"><span style="color: #0000ff;"><span style="font-family: times new roman,times; font-size: 12pt;"><strong>Курс обучения "Налоги: планирование и оптимизация"</strong></span> </span><span style="color: #0000ff;"><b><span style="font-size: 14pt;"><span style="font-family: times new roman,times; font-size: 12pt;">или</span> "<span style="font-family: times new roman,times; font-size: 12pt;">Все о налогах" для руководителей и предпринимателей</span></span></b></span></h1>\r\n<h1 dir="ltr"><span style="color: #0000ff;"><b><span style="font-size: 14pt;"><span style="font-family: times new roman,times; font-size: 12pt;"></span></span></b></span><span style="font-family: times new roman,times; font-size: 12pt;"><b>С него нужно начинать? «от регистрации предприятия до налогового кодекса» </b></span></h1>\r\n<ul>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">Почему Мы платим налоги?</span></li>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">О налогах, Налоговом кодексе и налоговом учете;</span></li>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">Мои права и обязанности как налогоплательщика;</span></li>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">Что такое НДС, налог на прибыль, НДФЛ, страховые взносы и УСН?</span></li>\r\n<li><span style="font-size: 12pt;"><span style="font-family: times new roman,times;">Основные критерии&nbsp;&nbsp; малого предпринимательства, нормативные документы, регламентирующие малый бизнес;</span><span style="font-family: times new roman,times;"><br /></span></span></li>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">Регистрация организаций малого бизнеса: порядок подачи заявления, открытие расчетных счетов, порядок работы с кассовой наличностью, регистрации ККМ.&nbsp;&nbsp; <br /></span></li>\r\n</ul>\r\n<p><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"></span><span style="font-family: times new roman,times;"><b>Налогообложение организаций и индивидуальных предпринимателей.</b></span></span></p>\r\n<ul>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">Общая система налогообложения: планирование налога на прибыль, налога на добавленную стоимость;</span></li>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">Упрощенная система налогообложения, Патентная система. Достоинства и недостатки УСН. Единый налог на вмененный доход. Оптимизация. <i>Какую систему налогообложения лучше выбрать для вашего предприятия</i></span></li>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">Сравнительный анализ систем налогообложения ОСНО и УСН</span></li>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">Порядок исчисления страховых взносов для разных систем налогообложения. Оптимизация страховых взносов </span></li>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">Возможность использования различных систем налогообложения для организаций, занимающимися разными видами деятельности.</span></li>\r\n</ul>\r\n<p><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"></span><span style="font-family: times new roman,times;"> </span><span style="font-family: times new roman,times;"><b>Налоговые риски и как их избежать </b></span></span></p>\r\n<ul>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">Что такое налоговые проверки, какими они бывают</span></li>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">Налоговые правонарушения и ответственность за их совершения</span></li>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">Часто встречающиеся нарушения в Арбитражной практике субъектов малого предпринимательства, практика Арбитражных судов</span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: black;">Примеры «серых» схем в малом бизнесе (как нельзя «оптимизировать»!). «Недобросовестные налогоплательщики» и контактирующие с ними риск-структуры («белая» - «серая» - «черная» фирмы). Как не стать «недобросовестным».</span></span></li>\r\n</ul>\r\n<p><span style="font-family: times new roman,times; font-size: 12pt;"><b><i>Практические занятия: </i></b></span></p>\r\n<ul>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">Построение модели малого предприятия с разными системами налогообложения. </span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Ответы на вопросы<br />&nbsp; <b>15 часов стоимость 6900 рублей</b></span></li>\r\n</ul>\r\n<p><span style="font-size: 12pt;">&nbsp;</span></p>\r\n<p><span style="font-family: times new roman,times;"><b><span style="font-size: 14pt; color: navy;">&nbsp;</span></b></span></p>\r\n<p><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;"></span></span><span style="font-family: times new roman,times; font-size: 12pt;"><b><br style="font-size: 14pt;" /></b></span></p>', '', 1, 2, '2012-06-05 12:19:32', 42, '', '2014-04-28 14:51:15', 42, 0, '0000-00-00 00:00:00', '2012-06-05 12:19:32', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":null,"urlatext":"","targeta":"","urlb":null,"urlbtext":"","targetb":"","urlc":null,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 27, 56, 'Обучения курс Налогообложение: планирование и оптимизация для руководителей и предпринимателей, налоговое право, курсы налоговый учет для руководителей, менеджеров, предпринимателей, курсы по налогам, курсы обучения налоговая отчетность, курсы по налогообложению в екатеринбурге', 'Курс Налогообложение: планирование и оптимизация', 1, 1575, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content_v3` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(22, 68, ' Обучение Бюджетирование, как система управления. Курс продвинутый Excel ', 'kurs-byudzhetirovanie-planirovanie-i-uchet', '<h1><span style="font-size: 12pt;"><strong><span style="color: #333399; font-family: times new roman,times;"><span style="color: #0000ff;">Обучение </span></span></strong></span><span style="font-size: 12pt; color: #0000ff;"><strong><span style="font-family: times new roman,times;">Бюджетирование, как система управления. Продвинутый Excel </span></strong></span></h1>\r\n<p><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;"><strong><span style="color: #000000;">Целевая аудитория: </span></strong><span style="color: #000000;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;">руководители подразделений, финансовые менеджеры, работники планово-экономического отдела, бухгалтер, главный бухгалтер</span></span></span></span></p>\r\n<div><strong><span style="font-size: 12pt;"><span style="font-family: times new roman,times;">Ведущий</span></span></strong><span style="font-size: 12pt; color: #000000;"><span style="font-family: times new roman,times;"><strong>:</strong> <a href="index.php?option=com_content&amp;view=article&amp;id=53:biznes-trener-nasonova-nadezhda-yurevna&amp;catid=2:uncategorised">Насонова Надежда Юрьевна </a><br /></span></span></div>\r\n<div style="text-align: justify;"><strong><span style="font-family: times new roman,times; font-size: 12pt;">Вы получите: </span></strong></div>\r\n<ul>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">практические методы</span><span style="font-family: times new roman,times; font-size: 12pt;"> планирования и оценки финансовой деятельности компании.</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"></span><span style="font-family: times new roman,times; font-size: 12pt;">современные инструменты бюджетирования и контроллинга</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"><strong></strong>изучите виды,&nbsp; методы и порядок формирования бюджета.&nbsp; </span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">востребованные функции в </span><span style="font-size: 12pt; color: #000000;"><span style="font-family: times new roman,times;">Excel для построения управленческого учета и бюджетирования.&nbsp; </span></span><span style="font-family: times new roman,times; font-size: 12pt;"></span><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #0000ff;"><a href="index.php?option=com_content&amp;view=article&amp;id=20:ekonomicheskie-kursy&amp;catid=8:obrazovanie&amp;Itemid=171"><span style="color: #0000ff;">Расписание курса</span></a></span></span><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #0000ff;"></span></span></li>\r\n</ul>\r\n<div><strong><span style="font-family: times new roman,times; font-size: 12pt; color: #000000;">В программе:</span></strong><br /><span style="color: #0000ff; font-size: 12pt;"><span style="font-family: times new roman,times;">Управленческий учет</span></span></div>\r\n<ul>\r\n<li><span style="font-size: 12pt;"><span style="font-family: times new roman,times;">Управление как система.</span><span style="font-family: times new roman,times;">&nbsp; Управленческий цикл организации, его этапы;&nbsp; </span><strong><span style="font-family: times new roman,times;">Контроллинг – система управления</span></strong><span style="font-family: times new roman,times;">,</span><span style="font-family: times new roman,times;"> охватывающая планирование и контроль;</span></span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Необходимость управленческого учета в развитие предприятия. Отличие управленческого и бухгалтерского учетов;</span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Принципы организации управленческого учета и подготовки отчетности, характеристики управленческой информации;</span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Связь управленческого учета и бюджетирования на предприятии.</span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Точка безубыточности. Анализ безубыточности</span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Определение маржинальной прибыли. Определение рентабельных проектов<em></em></span></li>\r\n</ul>\r\n<div style="text-align: justify;"><span style="color: #0000ff; font-size: 12pt;"><span style="font-family: times new roman,times;">Бюджетирование – как часть системы управления предприятием</span></span></div>\r\n<ul>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Сущность бюджетного управления, бюджет в системе планов предприятия;</span></li>\r\n<li style="text-align: justify;"><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"><span style="font-family: times new roman,times;">Постановка системы бюджетного управления</span>:</span><span style="font-family: times new roman,times;">&nbsp; определение участников процесса бюджетного управления,&nbsp; определение центров финансовой ответственности (ЦФО);</span></span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Подходы к построению системы бюджетирования на предприятии;</span></li>\r\n<li style="text-align: justify;"><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"></span><span style="font-family: times new roman,times;">Регламентация системы бюджетирования на предприятии. Бюджетная система:&nbsp; Система бюджетов на предприятии: Бюджет продаж, бюджет производства, бюджет накладных расходов, бюджет доходов и расходов, бюджет движения денежных средств.&nbsp; Взаимосвязь основных плановых и отчетных форм между собой. Контроль исполнения бюджетов – ключевая функция системы бюджетного управления.&nbsp; Анализ исполнения бюджета.</span></span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Автоматизация системы бюджетирования на предприятии:&nbsp; Какие существуют системы автоматизации управленческого учета; Тех.задания по автоматизации управленческого учета;&nbsp; Практические примеры автоматизации бюджетирования в 1С на производственном предприятии; </span></li>\r\n<li style="text-align: justify;"><span style="font-size: 12pt; font-family: ''Times New Roman'';">Бухгалтерские счета, оборотно-сальдовая ведомость, как регистры для получения информации для составления бюджетов. Практические задания в 1 С «Бухгалтерия»</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: times new roman,times;">Основные проблемы функционирования управленческого учета и системы бюджетирования на предприятиях. </span></span></li>\r\n</ul>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;">Excel – программа для управленческого учета и системы бюджетирования на предприятии </span>\r\n<ul>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Использование программного продукта для управленческого учета. Практические примеры форм бюджетов в формате Excel. </span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Возможности программного продукта: изучения <em><strong>наиболее востребованных</strong> <strong>формул и функций Excel</strong></em> для построения бюджетов.</span></li>\r\n</ul>\r\n</div>\r\n<p style="text-align: justify;"><span style="font-size: 12pt;"><!--[if gte mso 9]><xml>\r\n <w:WordDocument>\r\n  <w:View>Normal</w:View>\r\n  <w:Zoom>0</w:Zoom>\r\n  <w:PunctuationKerning/>\r\n  <w:ValidateAgainstSchemas/>\r\n  <w:SaveIfXMLInvalid>false</w:SaveIfXMLInvalid>\r\n  <w:IgnoreMixedContent>false</w:IgnoreMixedContent>\r\n  <w:AlwaysShowPlaceholderText>false</w:AlwaysShowPlaceholderText>\r\n  <w:Compatibility>\r\n   <w:BreakWrappedTables/>\r\n   <w:SnapToGridInCell/>\r\n   <w:WrapTextWithPunct/>\r\n   <w:UseAsianBreakRules/>\r\n   <w:DontGrowAutofit/>\r\n  </w:Compatibility>\r\n  <w:BrowserLevel>MicrosoftInternetExplorer4</w:BrowserLevel>\r\n </w:WordDocument>\r\n</xml><![endif]--></span></p>\r\n<p style="text-align: justify;"><span style="font-size: 12pt;"><!--[if gte mso 9]><xml>\r\n <w:LatentStyles DefLockedState="false" LatentStyleCount="156">\r\n </w:LatentStyles>\r\n</xml><![endif]--><!--[if gte mso 10]>\r\n\r\n<![endif]--></span></p>\r\n<p><span style="font-size: 12pt;"><!--[if gte mso 9]><xml>\r\n <w:LatentStyles DefLockedState="false" LatentStyleCount="156">\r\n </w:LatentStyles>\r\n</xml><![endif]--><!--[if gte mso 10]>\r\n\r\n<![endif]--></span></p>\r\n<div><span style="font-size: 12pt; font-family: terminal,monaco;"><!--[if gte mso 9]><xml>\r\n <w:WordDocument>\r\n  <w:View>Normal</w:View>\r\n  <w:Zoom>0</w:Zoom>\r\n  <w:PunctuationKerning/>\r\n  <w:ValidateAgainstSchemas/>\r\n  <w:SaveIfXMLInvalid>false</w:SaveIfXMLInvalid>\r\n  <w:IgnoreMixedContent>false</w:IgnoreMixedContent>\r\n  <w:AlwaysShowPlaceholderText>false</w:AlwaysShowPlaceholderText>\r\n  <w:Compatibility>\r\n   <w:BreakWrappedTables/>\r\n   <w:SnapToGridInCell/>\r\n   <w:WrapTextWithPunct/>\r\n   <w:UseAsianBreakRules/>\r\n   <w:DontGrowAutofit/>\r\n  </w:Compatibility>\r\n  <w:BrowserLevel>MicrosoftInternetExplorer4</w:BrowserLevel>\r\n </w:WordDocument>\r\n</xml><![endif]--> </span></div>\r\n<div class="MsoNormal"><span style="font-size: 12pt; font-family: ''times new roman'',times;">Работа с данными</span></div>\r\n<ul>\r\n<li><span style="font-size: 12pt; font-family: ''times new roman'',times;">поиск и замена данных</span></li>\r\n<li class="_mce_tagged_br"><span style="font-family: ''times new roman'',times; font-size: 12pt;">сортировка по значениям одного столбца, формату, нескольким столбцам, части диапазона</span></li>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: ''times new roman'',times;">установка фильтра и работа с ним</span></li>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: ''times new roman'',times;">отбор по значению, формату, условию, по ячейке</span></li>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: ''times new roman'',times;">отбор наибольших и наименьших значений</span></li>\r\n</ul>\r\n<div class="MsoNormal"><span style="font-size: 12pt; font-family: ''times new roman'',times;">Сводные таблицы</span></div>\r\n<ul>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: ''times new roman'',times;">Создание сводной таблицы</span></li>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: ''times new roman'',times;">Форматирование сводной таблицы</span></li>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: ''times new roman'',times;">Модификация таблицы</span></li>\r\n</ul>\r\n<p><span style="font-family: ''times new roman'',times; font-size: 12pt;">Защита информации</span></p>\r\n<ul>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: ''times new roman'',times;">Скрытие строк и столбцов, их отображение</span></li>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: ''times new roman'',times;">Скрытие и отображение формул </span></li>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: ''times new roman'',times;">защита всех ячеек листа</span></li>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: ''times new roman'',times;">снятие защиты листа</span></li>\r\n</ul>\r\n<div><span style="font-size: 12pt;"><span style="font-family: terminal,monaco;"> </span><!--[if gte mso 9]><xml>\r\n <w:LatentStyles DefLockedState="false" LatentStyleCount="156">\r\n </w:LatentStyles>\r\n</xml><![endif]--><!--[if gte mso 10]>\r\n\r\n<![endif]--></span></div>\r\n<div class="MsoNormal"><span style="font-size: 12pt;"><span style="font-family: times new roman,times;">Поисковые, справочные и информационные функции. </span><span style="font-family: times new roman,times;">Базовые поисковые функции:</span></span></div>\r\n<div class="MsoNormal">\r\n<ul>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">вертикальный поиск ВПР() и горизонтальный поиск ГПР()</span></li>\r\n</ul>\r\n</div>\r\n<div class="MsoNormal"><span style="font-size: 12pt;"><span style="font-family: times new roman,times;">&nbsp;Создание сложных формул и выявление ошибок. </span><span style="font-family: times new roman,times;">Условия в формулах:</span></span></div>\r\n<ul>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: times new roman,times;">построение условных формул: ЕСЛИ()</span></li>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: times new roman,times;">подсчет только указанных ячеек: СЧЕТЕСЛИ()</span></li>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: times new roman,times;">расчет условных сумм с одним критерием СУММЕСЛИ()</span></li>\r\n</ul>\r\n<div class="MsoNormal"><span style="font-size: 12pt; font-family: times new roman,times;">Описательные имена для ссылок на ячейки:</span></div>\r\n<ul>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: times new roman,times;">создание и использование именованного диапазона</span></li>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: times new roman,times;">управление именованными диапазонами</span></li>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: times new roman,times;">автоматическое создание именованных диапазонов</span></li>\r\n</ul>\r\n<div class="MsoNormal"><span style="font-size: 12pt; font-family: times new roman,times;">Работа с текстом</span></div>\r\n<div class="MsoNormal">\r\n<ul>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">Объединение строк текста: СЦЕПИТЬ()</span></li>\r\n</ul>\r\n</div>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"> На курсе обучения бюджетирование вы разберете и закрепите на практических примерах процессы бюджетного управления компанией.&nbsp; Ваши вложения окупятся в разы!<br /></span></div>\r\n<div style="text-align: justify;"><span style="font-size: 12pt;">&nbsp;</span></div>\r\n<div style="text-align: justify;"><span style="font-size: 12pt;"><span style="font-family: times new roman,times;">Стоимость&nbsp; 13600,&nbsp; 3 недели&nbsp;&nbsp; <span style="color: #ffffff; background-color: #ffffff;"><span style="color: #0000ff;"> <strong></strong></span></span></span><span style="font-family: times new roman,times;"><strong><span style="color: #0000ff; background-color: #ffffff;"><a class="modal" href="#call_me" rel="{size:{x:460,y:130}}">Отправить заявку</a>&nbsp;&nbsp;</span></strong></span><span style="font-family: times new roman,times;"><span style="color: #800080;">Скидка 5%&nbsp;</span><span style="text-align: left;">при оплате за 2&nbsp; недели до начала обучения</span></span></span></div>\r\n<div style="text-align: justify;"><span style="font-size: 10pt;"><span style="font-family: times new roman,times;">\r\n<div style="margin: 0px; padding: 0px; border: 0px; font-family: ''Times New Roman''; font-size: 12px; line-height: 18px; vertical-align: baseline; color: #222222;"><span style="margin: 0px; padding: 0px; border: 0px; font-family: inherit; font-size: 12pt; font-style: inherit; font-variant: inherit; font-weight: inherit; line-height: inherit; vertical-align: baseline;"><span style="margin: 0px; padding: 0px; border: 0px; font-family: ''times new roman'', times; font-size: inherit; font-style: inherit; font-variant: inherit; font-weight: inherit; line-height: inherit; vertical-align: baseline; text-align: left;">2 раза в неделю, среда с 18.30 до 21.30, &nbsp;суббота с 14.00 до 18.00 . Выдается методическая литература.</span><span style="margin: 0px; padding: 0px; border: 0px; font-family: ''times new roman'', times; font-size: inherit; font-style: inherit; font-variant: inherit; font-weight: inherit; line-height: inherit; vertical-align: baseline; text-align: left;"><span style="margin: 0px; padding: 0px; border: 0px; font-family: Verdana, Arial, Helvetica, sans-serif; font-size: inherit; font-style: inherit; font-variant: inherit; font-weight: inherit; line-height: inherit; vertical-align: baseline;">&nbsp;&nbsp;</span></span></span></div>\r\n<p style="margin: 0px 0px 1.5em; padding: 0px; border: 0px; font-family: ''Times New Roman''; font-size: 12px; line-height: 18px; vertical-align: baseline; color: #222222;"><span style="font-family: inherit; font-size: 12pt; font-style: inherit; font-variant: inherit; font-weight: inherit; line-height: inherit; text-align: left;">Для иногородних есть возможность пройти курсы дистанционного обучения.</span></p>\r\n</span></span></div>\r\n<p><a href="http://эмменеджмент.рф/obrazovanie/ekonomicheskie-kursy/13-obrazovanie/upravlenie-zatratami/18-upravlenie-zatratami" style="font-family: ''times new roman'', times; font-size: 12pt;"><span style="color: #0000ff;">Курс - Эффективное управление затратами</span></a></p>\r\n<p><span style="font-family: times new roman,times; font-size: 12pt;">&nbsp;</span></p>\r\n<div style="position: absolute; left: -40px; top: -25px; width: 1px; height: 1px; overflow: hidden;" data-mce-bogus="1" class="mcePaste" id="_mcePaste">\r\n<h1 dir="ltr"><span style="color: #0000ff;"><span style="font-family: times new roman,times; font-size: 12pt;"><strong>Курс "Налоги: планирование и оптимизация"</strong></span> </span><span style="color: #0000ff;"><b><span style="font-size: 14pt;"><span style="font-family: times new roman,times; font-size: 12pt;">или</span> "<span style="font-family: times new roman,times; font-size: 12pt;">Все о налогах" для руководителей и предпринимателей</span></span></b></span></h1>\r\n<h1 dir="ltr"><span style="color: #0000ff;"><b><span style="font-size: 14pt;"><span style="font-family: times new roman,times; font-size: 12pt;"></span></span></b></span><span style="font-family: times new roman,times; font-size: 12pt;"><b>С него нужно начинать? «от регистрации предприятия до налогового кодекса» </b></span></h1>\r\n<ul>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">Почему Мы платим налоги?</span></li>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">О налогах, Налоговом кодексе и налоговом учете;</span></li>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">Мои права и обязанности как налогоплательщика;</span></li>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">Что такое НДС, налог на прибыль, НДФЛ, страховые взносы и УСН?</span></li>\r\n<li><span style="font-size: 12pt;"><span style="font-family: times new roman,times;">Основные критерии&nbsp;&nbsp; малого предпринимательства, нормативные документы, регламентирующие малый бизнес;</span><span style="font-family: times new roman,times;"><br /></span></span></li>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">Регистрация организаций малого бизнеса: порядок подачи заявления, открытие расчетных счетов, порядок работы с кассовой наличностью, регистрации ККМ.&nbsp;&nbsp; <br /></span></li>\r\n</ul>\r\n<p><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"></span><span style="font-family: times new roman,times;"><b>Налогообложение организаций и индивидуальных предпринимателей.</b></span></span></p>\r\n<ul>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">Общая система налогообложения: планирование налога на прибыль, налога на добавленную стоимость;</span></li>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">Упрощенная система налогообложения, Патентная система. Достоинства и недостатки УСН. Единый налог на вмененный доход. Оптимизация. <i>Какую систему налогообложения лучше выбрать для вашего предприятия</i></span></li>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">Сравнительный анализ систем налогообложения ОСНО и УСН</span></li>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">Порядок исчисления страховых взносов для разных систем налогообложения. Оптимизация страховых взносов </span></li>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">Возможность использования различных систем налогообложения для организаций, занимающимися разными видами деятельности.</span></li>\r\n</ul>\r\n<p><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"></span><span style="font-family: times new roman,times;"> </span><span style="font-family: times new roman,times;"><b>Налоговые риски и как их избежать </b></span></span></p>\r\n<ul>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">Что такое налоговые проверки, какими они бывают</span></li>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">Налоговые правонарушения и ответственность за их совершения</span></li>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">Часто встречающиеся нарушения в Арбитражной практике субъектов малого предпринимательства, практика Арбитражных судов</span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: black;">Примеры «серых» схем в малом бизнесе (как нельзя «оптимизировать»!). «Недобросовестные налогоплательщики» и контактирующие с ними риск-структуры («белая» - «серая» - «черная» фирмы). Как не стать «недобросовестным».</span></span></li>\r\n</ul>\r\n<p><span style="font-family: times new roman,times; font-size: 12pt;"><b><i>Практические занятия: </i></b></span></p>\r\n<ul>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">Построение модели малого предприятия с разными системами налогообложения. </span></li>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">Ответы на вопросы<br /> <br /> </span></li>\r\n</ul>\r\n<p style="margin-left: 45pt; text-indent: -18pt;"><span style="font-size: 12pt; font-family: times new roman,times;">&nbsp;</span></p>\r\n<ul>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;"><b>Всего - 15 часов стоимость 8&nbsp;000 рублей</b></span></li>\r\n</ul>\r\n</div>', '', 1, 14, '2012-06-05 12:27:08', 42, '', '2014-12-17 06:39:29', 42, 0, '0000-00-00 00:00:00', '2012-06-05 12:27:08', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":null,"urlatext":"","targeta":"","urlb":null,"urlbtext":"","targetb":"","urlc":null,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 67, 0, 'Бюджетирование, планирование, учет, курсы экономистов в екатеринбурге, контроллинг, курсы Excel Екатеринбург, эксель, ексэль, курсы БДДС, курсы БДиР, обучение бюджет денежных средств', 'Обучение Бюджетирование, как система управления. Курс продвинутый Excel ', 1, 2020, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(23, 71, 'Курсы повышения квалификации бухгалтера ', 'kursy-povysheniya-kvalifikatsii-bukhgaltera', '<h1 style="text-align: left; font-family: Tahoma, Arial; color: #000080;"><span style="font-size: 12pt; color: #0000ff;"><strong><span style="font-family: times new roman,times;">Курсы повышения квалификации бухгалтера</span></strong></span></h1>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">&nbsp;&nbsp; &nbsp;Периодическое прохождение курсов повышения квалификации бухгалтеров — это необходимое условие для профессионального роста работников финансовой сферы. Законодательные акты и экономические реалии в нашей стране меняются постоянно, и далеко не всегда в них можно разобраться самостоятельно. Курсы повышения квалификации бухгалтера позволят на практике познакомиться с нововведениями в налоговом учете, углубить понимание развития учетно - экономических процессов предприятий как тенденции к развитию экономики, росту прибыли компании, разобраться в работе актуальных изменений программы 1С: «Бухгалтерия».</span></div>\r\n<table style="width: 617px; height: 58px;" border="0">\r\n<tbody>\r\n<tr>\r\n<td>\r\n<div><span style="color: #0000ff;"><span style="font-family: times new roman,times; font-size: 12pt;"><a href="index.php?option=com_content&amp;view=article&amp;id=13:1&amp;catid=10:kursy-praktikuyushchikh-bukhgalterov"><span style="color: #0000ff;"><span style="color: #000080;"><span style="color: #159994;"><span style="color: #0000ff;">Курс&nbsp; практикующий бухгалтер, главный бухгалтер</span></span></span></span></a></span></span></div>\r\n</td>\r\n<td>\r\n<div><span style="color: #0000ff;"><span style="font-family: times new roman,times; font-size: 12pt;">&nbsp;27.05.13 </span></span></div>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<div><span style="color: #0000ff;"><a href="index.php?option=com_content&amp;view=article&amp;id=24:kruglye-stoly-i-seminary-po-bukhgalterskomu-i-nalogovomu-uchetu&amp;catid=8:obrazovanie"><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;">Круглые столы и&nbsp; семинары по бухгалтерскому и налоговому учету</span></a></span></div>\r\n</td>\r\n<td>\r\n<p><span style="color: #0000ff;">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; &nbsp;</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<div style="text-align: justify;">&nbsp;<em> <span style="font-family: ''times new roman'',times; font-size: 12pt;"><strong>Ключевые составляющие учебных программ</strong></span></em><br /><span style="font-family: ''times new roman'', times; font-size: 12pt;">Залог успеха любых курсов повышения квалификации бухгалтера − комплексное</span>&nbsp;<span style="font-family: ''times new roman'', times; font-size: 12pt;">освещение всех аспектов финансового учета. Именно поэтому при составлении программы</span>&nbsp;<span style="font-family: ''times new roman'', times; font-size: 12pt;">преподаватели традиционно уделяют внимание следующим вопросам:</span><br /><span style="font-family: ''times new roman'', times; font-size: 12pt;">− бухгалтерская отчетность и аудит;</span><br /><span style="font-family: ''times new roman'', times; font-size: 12pt;">− системы налогообложения;</span><br /><span style="font-family: ''times new roman'', times; font-size: 12pt;">− управление финансами;</span><br /><span style="font-family: ''times new roman'', times; font-size: 12pt;">− правовое регулирование деятельности физических и юридических лиц;</span><br /><span style="font-family: ''times new roman'', times; font-size: 12pt;">− экономический анализ.</span></div>\r\n<div style="text-align: justify;"><span style="font-family: ''times new roman'', times; font-size: 12pt;"></span><br /><span style="font-family: ''times new roman'', times; font-size: 12pt;">Очень важно, чтобы курсы повышения квалификации бухгалтера совмещали </span><span style="font-family: ''times new roman'', times; font-size: 12pt;">теоретические и практические занятия − так слушатели быстрее научатся работать со</span>&nbsp;<span style="font-family: ''times new roman'', times; font-size: 12pt;">специализированным программным обеспечением, заполнять новые формы, разрабатывать</span>&nbsp;<span style="font-family: ''times new roman'', times; font-size: 12pt;">налоговые схемы.</span><br /><br /><span style="color: #0000ff;"><strong><span style="font-family: ''times new roman'',times; font-size: 12pt;">Курсы повышения квалификации бухгалтера от компании «ЭмМенеджмент»:</span></strong></span><br /><span style="color: #0000ff;"><strong><span style="font-family: ''times new roman'',times; font-size: 12pt;">быстро, эффективно, выгодно!</span></strong></span><br /><span style="font-family: ''times new roman'', times; font-size: 12pt;">Компания «ЭмМенеджмент» предлагает специалистам Екатеринбурга эффективные</span>&nbsp;<span style="font-family: ''times new roman'', times; font-size: 12pt;">курсы повышения квалификации бухгалтера. Занятия в нашем центре не отнимут много</span>&nbsp;<span style="font-family: ''times new roman'', times; font-size: 12pt;">времени и сил, ведь мы разработали уникальную программу, позволяющую в кратчайшие</span>&nbsp;<span style="font-family: ''times new roman'', times; font-size: 12pt;">сроки закрепить новые знания на базе уже имеющихся. Наши лекторы подскажут, как</span>&nbsp;<span style="font-family: ''times new roman'', times; font-size: 12pt;">минимизировать налоговые риски, избежать распространенных ошибок в ведении бухучета,</span>&nbsp;<span style="font-family: ''times new roman'', times; font-size: 12pt;">подготовиться к проверке.</span></div>\r\n<div style="text-align: justify;"><span style="font-family: ''times new roman'', times; font-size: 12pt;">&nbsp;</span></div>\r\n<div style="text-align: justify;"><span style="font-family: ''times new roman'', times; font-size: 12pt;"></span><span style="font-family: ''times new roman'', times; font-size: 12pt;">Пройдя курсы повышения квалификации бухгалтеров, разработанные опытными</span>&nbsp;<span style="font-family: ''times new roman'', times; font-size: 12pt;">специалистами компании «ЭмМенеджмент», Вы будете намного лучше ориентироваться в</span>&nbsp;<span style="font-family: ''times new roman'', times; font-size: 12pt;">системе налогообложения и сможете рассчитывать на повышение оклада и карьерный рост.&nbsp; <span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #ffffff; background-color: #ffffff;"><span style="color: #0000ff;"> <strong><a class="modal" href="#call_me" rel="{size:{x:460,y:130}}"><span style="color: #0000ff; background-color: #ffffff;">Отправить заявку</span></a></strong></span></span></span><br /></span></div>', '', 1, 8, '2012-06-05 15:52:22', 42, '', '2013-06-13 11:34:43', 42, 0, '0000-00-00 00:00:00', '2012-06-05 15:52:22', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":null,"urlatext":"","targeta":"","urlb":null,"urlbtext":"","targetb":"","urlc":null,"urlctext":"","targetc":""}', '{"show_title":"0","link_titles":"0","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 43, 2, 'Курсы повышения квалификации бухгалтера в Екатеринбурге, курсы профессиональных бухгалтеров, курсы главных бухгалтеров', 'Курсы повышения квалификации бухгалтера в Екатеринбурге, ', 1, 1395, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(24, 73, 'Круглые столы и  семинары по бухгалтерскому и налоговому учету', 'kruglye-stoly-i-seminary-po-bukhgalterskomu-i-nalogovomu-uchetu', '<h1><span style="font-family: times new roman,times; font-size: 14pt; color: #000080;">Круглые столы и&nbsp; семинары по бухгалтерскому и налоговому учету</span></h1>\r\n<div style="text-align: justify;">Д<span style="font-family: times new roman,times; font-size: 12pt;">ля специалистов по бухгалтерскому&nbsp; и налоговому учету&nbsp; очень важно поддерживать&nbsp; свою квалификацию, так как законодательные акты меняются ежеквартально, получая новую информацию, вы можете во время минимизировать налоговые риски, освободится от сдачи уточненных деклараций, получить информацию по законной оптимизации налогообложения.</span><br /><span style="font-family: times new roman,times; font-size: 12pt;">Наша компания организует семинары и круглые столы по актуальным вопросам налогообложения и бухгалтерского учета:</span><br /><span style="font-family: times new roman,times; font-size: 12pt;">-&nbsp; текущие изменения в бухгалтерском и налогом законодательстве</span><br /><span style="font-family: times new roman,times; font-size: 12pt;">-&nbsp; планирование и оптимизация налогообложения</span><br /><span style="font-family: times new roman,times; font-size: 12pt;">-&nbsp; специальные режимы налогообложения</span><br /><span style="font-family: times new roman,times; font-size: 12pt;">-&nbsp; как правильно анализировать арбитражную практику, примеры противоречий</span><br /><span style="font-family: times new roman,times; font-size: 12pt;">-&nbsp; критерии налоговых проверок</span><br /><span style="font-family: times new roman,times; font-size: 12pt;">-&nbsp; как подготовиться к плановой проверки</span><br /><span style="font-family: times new roman,times; font-size: 12pt;">Расписание и темы семинаров составляются с учетом пожеланий пользователей.</span><br /><span style="font-family: times new roman,times; font-size: 12pt;">Пожелания&nbsp; и вопросы по актуальным темам семинара просим&nbsp; присылать по электронной почте на адрес: <a href="mailto:ammanagment@yandex.ru">ammanagment@yandex.ru</a></span></div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;">Потенциальная группа: экономист, бухгалтер, главный бухгалтер, финансовый менеджер, руководитель, предприниматель.</span><br /><span style="font-family: times new roman,times; font-size: 12pt;">Семинары проводятся в центре города в оснащенной компьютерами&nbsp; и проекторам аудитории.&nbsp; <br /></span></div>\r\n<div><br /><span style="font-family: times new roman,times; font-size: 12pt;">Стоимость: 2000 руб. </span><br /><span style="font-family: times new roman,times; font-size: 12pt;">Продолжительность 6 часов</span></div>', '', 1, 8, '2012-06-06 10:33:10', 42, '', '2012-09-16 21:39:44', 42, 0, '0000-00-00 00:00:00', '2012-06-06 10:33:10', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":null,"urlatext":"","targeta":"","urlb":null,"urlbtext":"","targetb":"","urlc":null,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 7, 1, 'семинары по налогам екатеринбург, повышение квалификации бухгалтера, курсы главный бухгалтер, курсы ндс, курсы налог на прибыль', 'Круглые столы и  семинары по бухгалтерскому и налоговому учету', 1, 851, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content_v3` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(25, 74, 'Гражданское, тендерное право', 'kursy-yurista', '<p>Юридические курсы и семинары по гос закупкам в Екатеринбурге и области.</p>\r\n', '\r\n<p> </p>\r\n<h1 style="text-align: justify;"><span style="font-family: times new roman,times;"><span style="font-size: 12pt;"><span style="color: blue;">Обучение 44-ФЗ  курсы 223-ФЗ  семинары по госзакупкам в Екатеринбурге.  </span></span></span><span style="font-family: times new roman,times;"><span style="font-size: 12pt;"><span style="color: blue;">Юридические курсы, семинары по договорному и гражданскому праву. </span></span></span></h1>\r\n<div style="text-align: justify;"><span style="font-size: 12pt; font-family: times new roman,times;">Курсы </span><span style="font-size: 12pt; font-family: times new roman,times;"><span style="font-size: 12pt; font-family: times new roman,times;">44-ФЗ  обучение 223-ФЗ</span> направлены на то, чтобы эффективно пополнить новые знания в быстро меняющемся законодательстве. Порой убытки от незнания новшеств и нововведений в законодательстве по закупкам, гораздо больше чем затраты на  обучение </span><span style="font-size: 12pt; font-family: times new roman,times;"><span style="font-size: 12pt; font-family: times new roman,times;"><span style="font-size: 12pt; font-family: times new roman,times;">44-ФЗ и курсы 223-ФЗ</span></span>. </span></div>\r\n<table style="width: 619px; height: 157px;" border="0">\r\n<tbody>\r\n<tr>\r\n<td>\r\n<div><span style="font-family: times new roman,times;"><span style="font-size: 12pt;"><span class="temaname"><span style="color: #800080;">    Программа   </span><b><span style="color: #800080;"><br /></span></b></span></span></span></div>\r\n</td>\r\n<td><span style="font-family: times new roman,times;"><span style="font-size: 12pt;"><span class="temaname"><b><span style="color: blue;"> </span></b></span></span></span></td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<div><a href="index.php?option=com_content&amp;view=article&amp;id=54:44-fz-novaya-kontraktnaya-sistema-obuchenie-seminar-kurs&amp;catid=2:uncategorised"><span style="color: #0000ff;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #0000ff;">Семинар по госзакупкам </span></span><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #0000ff;">44-ФЗ и 223-ФЗ</span></span> <span style="font-family: times new roman,times; font-size: 12pt;">. Новое и актуальное в контрактной системе (8 часов)</span></span></a></div>\r\n</td>\r\n<td>\r\n<div><span style="font-family: times new roman,times; color: #0000ff; font-size: 12pt;"> </span></div>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<div><a href="index.php?option=com_content&amp;view=article&amp;id=80:kursy-obucheniya-223-fz-ot-18-07-2011-obuchenie-zakupkam-32-chasa&amp;catid=2:uncategorised"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; color: blue; mso-font-kerning: 18.0pt; mso-ansi-language: RU; mso-fareast-language: RU; mso-bidi-language: AR-SA;">Курсы  223-ФЗ, обучение  по закупкам (16 часов)</span></a></div>\r\n</td>\r\n<td>\r\n<div><span style="font-family: times new roman,times; color: #0000ff; font-size: 12pt;">24-25.12.14<br /></span></div>\r\n<div><span style="font-family: times new roman,times; color: #0000ff; font-size: 12pt;">26-27.01.15<br /></span></div>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<div>\r\n<div>\r\n<div dir="ltr"><span style="font-size: 12pt;"><a href="index.php?option=com_content&amp;view=article&amp;id=78:44-fz-40-chasov-dnevnoe-obuchenie&amp;catid=2:uncategorised"><span style="color: blue;"><span style="font-family: times new roman,times;">Курсы 44-ФЗ, обучение госзакупкам.</span></span></a><span style="font-family: times new roman,times;"><a href="index.php?option=com_content&amp;view=article&amp;id=78:44-fz-40-chasov-dnevnoe-obuchenie&amp;catid=2:uncategorised"><span style="font-family: times new roman,times;"> Контрактная система в сфере закупок </span></a><span style="color: blue;"><a href="index.php?option=com_content&amp;view=article&amp;id=78:44-fz-40-chasov-dnevnoe-obuchenie&amp;catid=2:uncategorised">(40-72 часа) <span style="color: #000000;">Дневное обучение</span></a><br /></span></span></span></div>\r\n</div>\r\n</div>\r\n</td>\r\n<td>\r\n<div><span style="font-family: times new roman,times; color: #0000ff; font-size: 12pt;">23-30.01.15</span></div>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<div>\r\n<div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;"><a href="index.php?option=com_content&amp;view=article&amp;id=79:44-fz-kursy-obuchenie-72-chasa-dnevnoe&amp;catid=2:uncategorised">Курсы 44-ФЗ, 223- ФЗ обучение госзакупкам. Контрактная система в сфере закупок (72 -120 часов) <span style="color: #000000;">Дневное обучение</span></a></span></div>\r\n</div>\r\n</div>\r\n</td>\r\n<td>\r\n<div><span style="font-family: times new roman,times; color: #0000ff; font-size: 12pt;">23-30.01.15</span></div>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<div>\r\n<div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;"><a href="index.php?option=com_content&amp;view=article&amp;id=81:kursy-obucheniya-44-fz-zaochno-obuchenie-goszakupkam-40-72-chasa-kontraktnaya-sistema-v-sfere-zakupok-44-fz-ot-05-04-2013-g&amp;catid=2:uncategorised">Курсы обучения 44-ФЗ <span style="color: #000000;">(заочно)</span>, обучение госзакупкам (72 часа). </a></span></div>\r\n</div>\r\n</div>\r\n</td>\r\n<td><span style="font-family: times new roman,times; color: #0000ff; font-size: 12pt;">2</span><span style="font-family: times new roman,times; color: #0000ff; font-size: 12pt;">2.01.15</span></td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<div><a href="index.php?option=com_content&amp;view=article&amp;id=76:obuchenie-goszakupkam-32-chasa&amp;catid=2:uncategorised"><span style="font-size: 12pt;"><span style="color: blue;"><span style="font-family: times new roman,times;">Курсы 44-ФЗ, обучение госзакупкам. </span></span><span style="font-family: times new roman,times;"><span style="color: blue;">Контрактная система в сфере закупок </span><span style="color: blue;">(40-72 часа) <span style="color: #000000;">Вечернее обучение</span></span></span></span></a></div>\r\n</td>\r\n<td>\r\n<div><span style="font-family: times new roman,times; color: #0000ff; font-size: 12pt;">21.01.15<br /></span></div>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<div><a href="index.php?option=com_content&amp;view=article&amp;id=69:44-fz-kursy-kursy-po-goszakupkam-obuchenie-kontraktnaya-sistema&amp;catid=2:uncategorised"><span style="font-size: 12pt;"><span style="color: blue;"><span style="font-family: times new roman,times;">Курсы 44-ФЗ, 223 - ФЗ обучение госзакупкам. </span></span><span style="font-family: times new roman,times;"><span style="color: blue;">Контрактная система в сфере закупок </span> <span style="color: blue;">(72 -120 часов) <span style="color: #000000;">Вечернее обучени</span></span><span style="color: #000000;">е</span></span></span></a></div>\r\n</td>\r\n<td>\r\n<div><span style="font-family: times new roman,times; color: #0000ff; font-size: 12pt;">21.01.15<br /></span></div>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<div><span style="font-size: 12pt; font-family: times new roman,times;"><a href="index.php?option=com_content&amp;view=article&amp;id=30:kursy-seminary-po-trudovomu-pravu-privlechenie-i-ispolzovanie-inostrannykh-rabotnikov&amp;catid=2:uncategorised">Особенности оформления отношений с иностранными работникам</a></span></div>\r\n</td>\r\n<td> </td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<div><span style="font-family: symbol;"><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"><a href="index.php?option=com_content&amp;view=article&amp;id=26:kurs-pravovye-aspekty-sostavleniya-i-analiza-dogovora&amp;catid=2:uncategorised"><span class="temaname">Как составить оптимальный договор. Договорное право.</span></a></span></span> </span></div>\r\n</td>\r\n<td>\r\n<div><span style="color: blue;"><span style="font-size: 12pt;"><span class="temaname"><span style="color: blue;"> </span></span></span> <br /></span></div>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<div><span class="temaname0" style="font-family: symbol;"><span style="font-size: 12pt;"><span style="color: navy;"><span style="font-family: times new roman,times;"><a href="index.php?option=com_content&amp;view=article&amp;id=28:kursy-pravo-i-yuridicheskie-aspekty-predprinimatelskoj-deyatelnosti&amp;catid=8:obrazovanie">Право и юридические аспекты предпринимательской деятельности</a></span> <br /></span></span></span></div>\r\n</td>\r\n<td>\r\n<div><span style="font-family: times new roman,times;"> <span class="temaname0"><span style="font-size: 12pt;"> <b><span style="color: navy;"> <br /></span></b></span></span></span></div>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<div><a href="index.php?option=com_content&amp;view=article&amp;id=27:pravovye-voprosy-raboty-s-personalom&amp;catid=2:uncategorised"><span style="color: #0000ff;"><span style="font-size: 12pt;"><span style="font-family: times new roman,times;">Правовые вопросы работы с персоналом. Трудовое право</span></span></span></a></div>\r\n</td>\r\n<td><span style="font-family: times new roman,times; color: #0000ff;">  <br /></span></td>\r\n</tr>\r\n<tr>\r\n<td><a href="index.php?option=com_content&amp;view=article&amp;id=31:novatsii-v-trudovom-zakonodatelstve&amp;catid=2:uncategorised"><span style="font-family: symbol;"><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"><span style="font-size: 12pt; line-height: 107%; font-family: ''Times New Roman''; color: #0000ff;">Новации в трудовом законодательстве и кадровом делопроизводстве. Судебная и правоприменительная практика.</span></span></span></span></a></td>\r\n<td>\r\n<div><span style="font-family: times new roman,times; color: #0000ff; font-size: 12pt;"> </span></div>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p style="text-align: justify;"> <span style="font-size: 12pt; font-family: times new roman,times;"> Реалии современного общества <em>регламентированы</em> огромным количеством<em> законов, постановлений, правил</em>, в которых не всегда можно разобраться самостоятельно. Порой мы самостоятельно принимаем решение, <span style="font-size: 12pt; font-family: times new roman,times;">разрешая конфликтную ситуацию</span>, не имея знаний по гражданскому праву (будь то отказ организации платить по договору поставки, некачественный и не вовремя поставленный товар. И как всегда говорим сами себе «если б я знал» со мной бы такого не случилось.</span></p>\r\n<div style="text-align: justify;"><span style="font-size: 12pt; font-family: times new roman,times;">   Обучение госзакупкам 44-ФЗ и курсы - семинары 223-ФЗ  помогут слушателям, опираясь на действующие законы, получить  практические знания и навыки работы на контрактной системе. Определить оптимальную линию поведения в той или иной ситуации, а при необходимости самостоятельно составить оптимальный договор, разработать техническую документацию.</span></div>\r\n<h2 style="text-align: justify;"><span style="font-size: 12pt; font-family: times new roman,times;">  </span></h2>\r\n<p style="text-align: justify;"><span style="font-size: 12pt; font-family: times new roman,times;"> </span></p>\r\n<!-- [if !mso]>\r\n\r\n<![endif]-->\r\n<h1 style="text-align: justify;"><span style="font-size: 14.0pt; color: blue;"><span style="mso-spacerun: yes;">        </span>Контрактная система - новый этап реформирования торгов. ФЗ-44 от 05.04.2013 года - новая система закупок в РФ. </span></h1>\r\n<p><strong>1. Контрактная система - новый этап реформирования государственного (муниципального) заказа. Основные положения Закона № 44-ФЗ от 05.04.2013 года «О контрактной системе в сфере закупок товаров, работ и услуг для обеспечения государственных и муниципальных нужд».</strong></p>\r\n<p><strong>2. Основные принципы нового Закона № 44-ФЗ от 05.04.2013 года « О контрактной системе в сфере закупок товаров, работ и услуг для обеспечения государственных и муниципальных нужд».</strong></p>\r\n<ul type="disc">\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l4 level1 lfo1; tab-stops: list 36.0pt;">Предмет регулирования, основные понятия, новые термины и определения, отличия от ФЗ-94</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l4 level1 lfo1; tab-stops: list 36.0pt;">Единая информационная система, ее элементы</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l4 level1 lfo1; tab-stops: list 36.0pt;">Регламентация работы по прогнозированию и планированию обеспечения государственных нужд</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l4 level1 lfo1; tab-stops: list 36.0pt;">Планы закупок товаров, работ, услуг для обеспечения государственных и муниципальных нужд</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l4 level1 lfo1; tab-stops: list 36.0pt;">Особенности планирования закупок товаров, работ, услуг на переходный период 2014-2015гг в соответствии с Приказом Министерства экономического развития, Федерального Казначейства № 544/18н от 20.09.2013г.</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l4 level1 lfo1; tab-stops: list 36.0pt;">Планирование закупок товаров, работ, услуг для обеспечения государственных и муниципальных нужд на 2016 год и далее</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l4 level1 lfo1; tab-stops: list 36.0pt;">Планы-графики осуществления закупок товаров, работ, услуг для государственных и муниципальных нужд</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l4 level1 lfo1; tab-stops: list 36.0pt;">Обоснование закупок товаров, работ, услуг</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l4 level1 lfo1; tab-stops: list 36.0pt;">Нормирование в федеральной контрактной системе</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l4 level1 lfo1; tab-stops: list 36.0pt;">Начальная (максимальная) цена контракта- новые методики расчета стоимости</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l4 level1 lfo1; tab-stops: list 36.0pt;">Приказ Министерства экономического развития РФ от 02 октября 2013 года № 567 «Об утверждении методических рекомендаций по определению НМЦК»</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l4 level1 lfo1; tab-stops: list 36.0pt;">Комиссии заказчиков. Контрактная службы (контрактный управляющий). Функции. Обязанности. Ответственность. Письмо МЭР РФ от 23 сентября 2013 Д28и-1070 г «О разъяснении отдельных положений ФЗ-44</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l4 level1 lfo1; tab-stops: list 36.0pt;">Централизация закупочной деятельности. Роль уполномоченного органа в обеспечении централизации закупок</li>\r\n</ul>\r\n<p><strong>3: Способы осуществления закупок по контрактной системе. Новое в процедурах по сравнению с 94-ФЗ. Порядок работы заказчика и участника по новым правилам:</strong></p>\r\n<ul type="disc">\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l0 level1 lfo2; tab-stops: list 36.0pt;">открытый конкурс</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l0 level1 lfo2; tab-stops: list 36.0pt;">конкурс с ограниченным участием</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l0 level1 lfo2; tab-stops: list 36.0pt;">двухэтапный конкурс</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l0 level1 lfo2; tab-stops: list 36.0pt;">электронный аукцион</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l0 level1 lfo2; tab-stops: list 36.0pt;">запрос котировок</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l0 level1 lfo2; tab-stops: list 36.0pt;">запрос предложений</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l0 level1 lfo2; tab-stops: list 36.0pt;">закрытые процедуры</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l0 level1 lfo2; tab-stops: list 36.0pt;">закупки у единственного поставщика</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l0 level1 lfo2; tab-stops: list 36.0pt;">Участие субъектов малого предпринимательства в процедуре закупок, новый подход, порядок применения, ответственность (Постановление Правительства РФ от 13 ноября 2013 года)</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l0 level1 lfo2; tab-stops: list 36.0pt;">Антидемпинговые меры при проведении конкурентных торгов</li>\r\n</ul>\r\n<p><strong>3.1. Открытый конкурс.</strong></p>\r\n<ul type="disc">\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l6 level1 lfo3; tab-stops: list 36.0pt;">Порядок опубликования извещения, конкурсной документации, изменений, разъяснений</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l6 level1 lfo3; tab-stops: list 36.0pt;">Структура конкурсной документации</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l6 level1 lfo3; tab-stops: list 36.0pt;">Порядок подачи заявок на участие в конкурсе</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l6 level1 lfo3; tab-stops: list 36.0pt;">Вскрытие конкурсных заявок, рассмотрение и их оценка</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l6 level1 lfo3; tab-stops: list 36.0pt;">Новые критерии оценки конкурсных заявок, значения, методика расчета в соответствии с Постановлением Правительства РФ № 1085 от 28 ноября 2013 года</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l6 level1 lfo3; tab-stops: list 36.0pt;">Новый подход законодателей к схемам и срокам заключения контракта по результатам проведения конкурсных процедур, признание конкурса несостоявшимся, новые правовые последствия</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l6 level1 lfo3; tab-stops: list 36.0pt;">Особенности проведения конкурса с ограниченным участием (Постановление Правительства № 1089 от 28 ноября 2013 года)</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l6 level1 lfo3; tab-stops: list 36.0pt;">Особенности проведения двухэтапного конкурса</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l6 level1 lfo3; tab-stops: list 36.0pt;">Постановление Правительства РФ № 1088 от 28 ноября 2013 г «Об утверждении правил совместных конкурсов и аукционов»</li>\r\n</ul>\r\n<p><strong>3.2. Электронный аукцион в контрактной системе.</strong></p>\r\n<ul type="disc">\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l9 level1 lfo4; tab-stops: list 36.0pt;">Порядок проведения электронного аукциона – отличия от 94-ФЗ</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l9 level1 lfo4; tab-stops: list 36.0pt;">Новые требования к содержанию заявок</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l9 level1 lfo4; tab-stops: list 36.0pt;">Порядок опубликования извещений, изменений, разъяснений</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l9 level1 lfo4; tab-stops: list 36.0pt;">Структура аукционной документации</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l9 level1 lfo4; tab-stops: list 36.0pt;">Новые правила в обеспечении заявки и обеспечении исполнения контракта</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l9 level1 lfo4; tab-stops: list 36.0pt;">Состав заявки участника размещения заказа</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l9 level1 lfo4; tab-stops: list 36.0pt;">Заключение контракта по результатам электронного аукциона</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l9 level1 lfo4; tab-stops: list 36.0pt;"><strong>Новое в законодательстве!</strong> Антидемпинговые меры при проведении конкурентных закупок</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l9 level1 lfo4; tab-stops: list 36.0pt;">Распоряжение Правительства РФ от 31 октября 2013 года № 2019-р, регламентирующее новый аукционный перечень товаров, работ, услуг</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l9 level1 lfo4; tab-stops: list 36.0pt;">Порядок опубликования извещения, аукционной документации, изменений, разъяснений, итогов аукциона, структура аукционной документации, аукцион с одним участником. Схема заключения контракта по итогам аукциона. Выплата процентов по обеспечению!</li>\r\n</ul>\r\n<p><strong>3.3. Запрос котировок в контрактной системе.</strong></p>\r\n<ul type="disc">\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l1 level1 lfo5; tab-stops: list 36.0pt;">Порядок проведения запроса котировок – отличия от 94-ФЗ</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l1 level1 lfo5; tab-stops: list 36.0pt;">Требования, предъявляемые к запросу котировок</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l1 level1 lfo5; tab-stops: list 36.0pt;">Порядок подачи котировочных заявок, формы подачи котировочных заявок</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l1 level1 lfo5; tab-stops: list 36.0pt;">Рассмотрение и оценка котировочных заявок</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l1 level1 lfo5; tab-stops: list 36.0pt;">Новые правовые последствия несостоявшихся процедур</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l1 level1 lfo5; tab-stops: list 36.0pt;">Запрос предложения – новая процедура в контрактной системе</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l1 level1 lfo5; tab-stops: list 36.0pt;">Особенности показания и применения запроса предложений</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l1 level1 lfo5; tab-stops: list 36.0pt;">Порядок проведения запроса предложений</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l1 level1 lfo5; tab-stops: list 36.0pt;">Возможность применения запроса предложений</li>\r\n</ul>\r\n<p><strong>3.4. Закрытые процедуры в контрактной системе, закупки у единственного поставщика.</strong></p>\r\n<ul type="disc">\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l5 level1 lfo6; tab-stops: list 36.0pt;">Виды закрытых процедур, особенности их проведения</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l5 level1 lfo6; tab-stops: list 36.0pt;">Порядок подачи заявок на закрытые процедуры</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l5 level1 lfo6; tab-stops: list 36.0pt;">Порядок размещения заказа у единственного поставщика</li>\r\n</ul>\r\n<p><strong>4. Возможность выбора Заказчиками способов закупок по ФЗ-223 в рамках контрактной системы (ст. 15 ФЗ-44)</strong></p>\r\n<ul type="disc">\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l7 level1 lfo7; tab-stops: list 36.0pt;">Практические вопросы применения Федерального закона от 18 июля 2011 г. №223-ФЗ «О закупках товаров, работ, услуг отдельными видами юридических лиц»</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l7 level1 lfo7; tab-stops: list 36.0pt;">Информационное осуществление закупочной деятельности. Взаимодействие с официальными сайтом по размещению информации, предусмотренным Федеральным законом от 18 июля 2011 г. №223-ФЗ</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l7 level1 lfo7; tab-stops: list 36.0pt;">Способы закупок, условия их выбора. Типичные нарушения при выборе способа закупки</li>\r\n<li class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l7 level1 lfo7; tab-stops: list 36.0pt;">Последовательность, продолжительность и содержание процедур, оформляемые документы</li>\r\n</ul>\r\n<p><strong>5. Особенности заключения (расторжения) государственных контрактов, порядок приемки товаров, работ и услуг. Контрактный аудит. Надзор и контроль.</strong></p>\r\n<p style="margin-left: 36.0pt; text-indent: -18.0pt; mso-list: l3 level1 lfo10; tab-stops: list 36.0pt;"><span style="font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;"><span style="mso-list: Ignore;">·<span style="font: 7.0pt ''Times New Roman'';">         </span></span></span>Способы обеспечения исполнения обязательств из государственных (муниципальных) контрактов.</p>\r\n<p style="margin-left: 36.0pt; text-indent: -18.0pt; mso-list: l3 level1 lfo10; tab-stops: list 36.0pt;"><span style="font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;"><span style="mso-list: Ignore;">·<span style="font: 7.0pt ''Times New Roman'';">         </span></span></span>Установление требований к содержанию и сроку действия банковской гарантии <br /> (Постановление Правительства РФ № 1005 от 08 ноября 2013 года «О банковских гарантиях, используемых для целей ФЗ-44).</p>\r\n<p style="margin-left: 36.0pt; text-indent: -18.0pt; mso-list: l3 level1 lfo10; tab-stops: list 36.0pt;"><span style="font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;"><span style="mso-list: Ignore;">·<span style="font: 7.0pt ''Times New Roman'';">         </span></span></span>Новшество! Одностороннее расторжение контрактов Заказчиками и Поставщиками.</p>\r\n<p style="margin-left: 36.0pt; text-indent: -18.0pt; mso-list: l3 level1 lfo10; tab-stops: list 36.0pt;"><span style="font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;"><span style="mso-list: Ignore;">·<span style="font: 7.0pt ''Times New Roman'';">         </span></span></span>Порядок исполнения, изменения существенных условий контрактов.</p>\r\n<p style="margin-left: 36.0pt; text-indent: -18.0pt; mso-list: l3 level1 lfo10; tab-stops: list 36.0pt;"><span style="font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;"><span style="mso-list: Ignore;">·<span style="font: 7.0pt ''Times New Roman'';">         </span></span></span>Порядок приёмки товаров, работ и услуг по качеству. Проведение экспертизы. Требования к экспертам. Отчет об исполнении контрактов.</p>\r\n<p><strong>6. Порядок осуществления контроля за закупочной деятельностью в рамках контрактной системы.</strong></p>\r\n<p><strong>Контрольные органы. Их полномочия. Виды контроля:</strong></p>\r\n<p class="MsoNormal" style="margin-left: 53.4pt; text-indent: -18.0pt; mso-list: l8 level1 lfo9; tab-stops: list 53.4pt;"><span style="font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;"><span style="mso-list: Ignore;">·<span style="font: 7.0pt ''Times New Roman'';">         </span></span></span>Внешний и внутренний контроль в контрактной системе.</p>\r\n<p class="MsoNormal" style="margin-left: 53.4pt; text-indent: -18.0pt; mso-list: l8 level1 lfo9; tab-stops: list 53.4pt;"><span style="font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;"><span style="mso-list: Ignore;">·<span style="font: 7.0pt ''Times New Roman'';">         </span></span></span>Организация внутреннего аудита.</p>\r\n<p class="MsoNormal" style="margin-left: 53.4pt; text-indent: -18.0pt; mso-list: l8 level1 lfo9; tab-stops: list 53.4pt;"><span style="font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;"><span style="mso-list: Ignore;">·<span style="font: 7.0pt ''Times New Roman'';">         </span></span></span>Новое - система общественного контроля.</p>\r\n<p class="MsoNormal" style="margin-left: 53.4pt; text-indent: -18.0pt; mso-list: l8 level1 lfo9; tab-stops: list 53.4pt;"><span style="font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;"><span style="mso-list: Ignore;">·<span style="font: 7.0pt ''Times New Roman'';">         </span></span></span>Обжалование и досудебное разрешение споров.</p>\r\n<p class="MsoNormal" style="margin-left: 53.4pt; text-indent: -18.0pt; mso-list: l8 level1 lfo9; tab-stops: list 53.4pt;"><span style="font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;"><span style="mso-list: Ignore;">·<span style="font: 7.0pt ''Times New Roman'';">         </span></span></span>Обжалование действий (бездействий) заказчика, комиссии, должностного лица контрактной службы, контрактного управляющего, оператора электронной площадки.</p>\r\n<p class="MsoNormal" style="margin-left: 53.4pt; text-indent: -18.0pt; mso-list: l8 level1 lfo9; tab-stops: list 53.4pt;"><span style="font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;"><span style="mso-list: Ignore;">·<span style="font: 7.0pt ''Times New Roman'';">         </span></span></span>Порядок рассмотрения жалоб.</p>\r\n<p><strong>7. Практика осуществления контроля антимонопольными органами</strong> (нормативные акты и административные процедуры). Ответственность должностных лиц Заказчика по КоАП.</p>\r\n<p style="margin-left: 36.0pt; text-indent: -18.0pt; mso-list: l2 level1 lfo8; tab-stops: list 36.0pt;"><strong><span style="font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol; font-weight: normal; mso-bidi-font-weight: bold;"><span style="mso-list: Ignore;">·<span style="font: 7.0pt ''Times New Roman'';">         </span></span></span></strong><strong>Полномочия и порядок осуществления антимонопольным органом контроля за размещением государственного/муниципального заказа в соответствии с Законом</strong> (плановые и внеплановые проверки).<strong> Особенности осуществления контроля и надзора в соответствии с Законом 44-ФЗ (о контрактной системе).</strong></p>\r\n<p style="margin-left: 36.0pt; text-indent: -18.0pt; mso-list: l2 level1 lfo8; tab-stops: list 36.0pt;"><span style="font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;"><span style="mso-list: Ignore;">·<span style="font: 7.0pt ''Times New Roman'';">         </span></span></span>Обжалование действий Заказчика, Уполномоченного органа, оператора ЭТП. <strong>Практика ФАС, территориальных органов ФАС России по рассмотрению жалоб на действия заказчиков.</strong></p>\r\n<p style="margin-left: 36.0pt; text-indent: -18.0pt; mso-list: l2 level1 lfo8; tab-stops: list 36.0pt;"><span style="font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;"><span style="mso-list: Ignore;">·<span style="font: 7.0pt ''Times New Roman'';">         </span></span></span><strong>Анализ типичных ошибок Заказчиков, Уполномоченных органов, Специализированных организаций, Комиссий при проведении закупочных процедур: позиция ФАС России и арбитражных судов по нарушениям</strong>, связанным с выбором способа закупки, формированием предмета контракта (лотов), документации о закупке, информационным обеспечением размещения заказа, порядком рассмотрения заявок, заключением контракта</p>\r\n<p style="margin-left: 36.0pt; text-indent: -18.0pt; mso-list: l2 level1 lfo8; tab-stops: list 36.0pt;"><span style="font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;"><span style="mso-list: Ignore;">·<span style="font: 7.0pt ''Times New Roman'';">         </span></span></span>Соблюдение требований антимонопольного законодательства (ФЗ-135) при закупках для государственных и муниципальных нужд.</p>\r\n<p style="margin-left: 36.0pt; text-indent: -18.0pt; mso-list: l2 level1 lfo8; tab-stops: list 36.0pt;"><span style="font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;"><span style="mso-list: Ignore;">·<span style="font: 7.0pt ''Times New Roman'';">         </span></span></span><strong>Ответственность за нарушение законодательства о размещении заказов, предусмотренная действующим законодательством.</strong> Практика применения административных санкций.</p>\r\n<p style="margin-left: 36.0pt; text-indent: -18.0pt; mso-list: l2 level1 lfo8; tab-stops: list 36.0pt;"><span style="font-family: Symbol; mso-fareast-font-family: Symbol; mso-bidi-font-family: Symbol;"><span style="mso-list: Ignore;">·<span style="font: 7.0pt ''Times New Roman'';">         </span></span></span>Пресечение недобросовестных действий участников закупки (антимонопольная и судебная практика по сговорам, недобросовестной конкуренции, ведению <strong>Реестра недобросовестных поставщиков</strong>).</p>\r\n<p class="MsoNormal" style="text-align: justify;"><span style="font-size: 11.0pt;"><span style="mso-spacerun: yes;">    </span><span style="mso-spacerun: yes;">  </span></span><span style="color: black;">Автор программы<strong> Шарунова Ирина Юрьевна,</strong>  практикующий юрист, руководитель юридического отдела СпецГазПроект, автор программ по гражданскому и трудовому законодательству.</span><span style="font-size: 11.0pt;"><span style="mso-spacerun: yes;">   </span></span></p>\r\n<p class="MsoNormal"><span style="font-size: 11.0pt;"><span style="mso-spacerun: yes;">      </span><span style="mso-spacerun: yes;"> </span><b style="mso-bidi-font-weight: normal;">Продолжительность 16 часов. </b></span><b style="mso-bidi-font-weight: normal;">Стоимость 14600.  </b><b style="mso-bidi-font-weight: normal;"><span style="font-size: 11.0pt;">Расписание 08-09.02.2014</span> с 10 до 17.00. </b></p>\r\n<p class="MsoNormal"><b style="mso-bidi-font-weight: normal;"><span style="mso-spacerun: yes;"> </span>При оплате<span style="mso-spacerun: yes;">  </span>до 31.12.2013 Скидка 10%</b></p>\r\n<p class="MsoNormal"><span style="mso-spacerun: yes;">     </span>г. Екатеринбург, Степана<span style="mso-spacerun: yes;">  </span>Разина 16 офис 412<span style="mso-spacerun: yes;">  </span>т. +7 (343) 266-79-85<span style="mso-spacerun: yes;">  </span><span style="color: purple;"><a href="http://эмменеджмент.рф/">http://эмменеджмент.рф/</a><span style="mso-spacerun: yes;">  </span></span>почта<span style="color: purple;"><span style="mso-spacerun: yes;">  </span></span><span class="daria-action"><span style="color: black;"><a href="mailto:ammanagment@yandex.ru">ammanagment@yandex.ru</a></span></span></p>\r\n<p class="MsoNormal"><span style="font-size: 11.0pt;"> </span></p>\r\n<p class="MsoNormal"> </p>\r\n<!-- [if gte mso 9]><xml>\r\n <w:WordDocument>\r\n  <w:View>Normal</w:View>\r\n  <w:Zoom>0</w:Zoom>\r\n  <w:PunctuationKerning/>\r\n  <w:ValidateAgainstSchemas/>\r\n  <w:SaveIfXMLInvalid>false</w:SaveIfXMLInvalid>\r\n  <w:IgnoreMixedContent>false</w:IgnoreMixedContent>\r\n  <w:AlwaysShowPlaceholderText>false</w:AlwaysShowPlaceholderText>\r\n  <w:Compatibility>\r\n   <w:BreakWrappedTables/>\r\n   <w:SnapToGridInCell/>\r\n   <w:WrapTextWithPunct/>\r\n   <w:UseAsianBreakRules/>\r\n   <w:DontGrowAutofit/>\r\n  </w:Compatibility>\r\n  <w:BrowserLevel>MicrosoftInternetExplorer4</w:BrowserLevel>\r\n </w:WordDocument>\r\n</xml><![endif]--><!-- [if gte mso 9]><xml>\r\n <w:LatentStyles DefLockedState="false" LatentStyleCount="156">\r\n </w:LatentStyles>\r\n</xml><![endif]--><!-- [if !mso]><object\r\n classid="clsid:38481807-CA0E-42D2-BF39-B33AF135CC4D" id=ieooui></object>\r\n\r\n<![endif]--><!-- [if gte mso 10]>\r\n\r\n<![endif]-->', 1, 8, '2012-09-14 19:35:00', 42, '', '2014-12-29 13:52:53', 42, 0, '0000-00-00 00:00:00', '2012-09-14 19:35:00', '0000-00-00 00:00:00', '{"image_intro":"images\\/icons\\/3-tendernoe-pravo.jpg","float_intro":"","image_intro_alt":"\\u041a\\u0443\\u0440\\u0441\\u044b \\u043f\\u043e \\u0442\\u0435\\u043d\\u0434\\u0435\\u0440\\u0430\\u043c \\u0438 \\u0433\\u0440\\u0430\\u0436\\u0434\\u0430\\u043d\\u0441\\u043a\\u043e\\u043c\\u0443 \\u043f\\u0440\\u0430\\u0432\\u0443","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 185, 0, 'Курсы юриста в Екатеринбурге, Юридические курсы, Курсы семинары по праву, курсы повышения квалификации юриста, административное право курсы и семинары, гражданское право краткий курс, гражданское право курсы и семинары, процессуальное право курсы и семинары, курсы  и семинары трудовое право, семинары юридические в Екатеринбурге, семинары для юриста в Екатеринбурге, обучение юридическое, обучение гражданское, обучение 44 фз, семинар 223 фз, курсы 44 фз, семинар по госзакупкам, семинар  44 фз, курсы 223 - фз, 223 фз курсы, обучение 223 фз', ' Курсы и семинары по госзакупкам 44-ФЗ и 223-ФЗ  направлены на то, чтобы эффективно пополнить новые знания в быстро меняющемся законодательстве.', 1, 2384, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content_v3` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(26, 75, 'Курсы  по договорному праву, семинары по договорной работе. Обучение договорное и гражданское право. Как составить оптимальный договор', 'kurs-pravovye-aspekty-sostavleniya-i-analiza-dogovora', '<p style="text-align: justify;"><span style="color: purple;"></span><span style="color: purple;"><span style="font-size: 14pt;"><strong style="color: purple;"></strong></span></span><span style="font-size: 12pt; color: #000080;"><strong><span><span style="font-family: times new roman,times;">Семинар по договорной работе:</span></span></strong> </span><span style="font-size: 12pt;"><span style="font-family: times new roman,times;" class="temaname"></span></span><span style="color: #0000ff;"><span style="font-size: 12pt; font-family: times new roman,times;"><span style="font-size: 14pt;"><span style="font-size: 12pt;">Как составить оптимальный договор, застраховаться от риска невыполнения условий договора.</span></span> Нововведения в гражданском законодательстве&nbsp; 2013 -2014 года</span><span style="font-size: 12pt; font-family: times new roman,times;"><span style="font-size: 14pt;">.</span></span><span style="font-size: 12pt; font-family: times new roman,times;"><br /></span></span></p>\r\n<p><span style="font-family: times new roman,times;"><span style="font-size: 12pt; color: #000000;">Дата проведения</span><span style="font-size: 12pt; color: #000080;"> 24.05 -25.05.14 <span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #000000;">&nbsp;&nbsp;&nbsp; <span style="color: #000000;">Ведущий&nbsp; <span style="color: #0000ff;"><a href="index.php?option=com_content&amp;view=article&amp;id=56:sharunova-irina-yurevna-prepodavatel&amp;catid=2:uncategorised">Шарунова Ирина Юрьевна </a></span></span></span></span></span><span style="font-size: 12pt; color: #000080;"><br /></span></span></p>\r\n<div style="text-align: justify;"><span style="font-size: 12pt; font-family: times new roman,times;"><span style="font-size: 12pt; font-family: times new roman,times;">Семинар&nbsp; по договорной работе <strong>предназначен</strong> <span style="color: #000000;">для специалистов по договорной работе,&nbsp; юристов, бухгалтерских служб</span></span><span style="color: #17365d;"><span style="color: #000000;">, <span style="font-size: 12pt; font-family: times new roman,times;"><span style="font-size: 12pt; font-family: times new roman,times;">предпринимателей, менеджеров.</span></span> После прохождения курса вы &nbsp;&nbsp;&nbsp;&nbsp;</span> </span></span></div>\r\n<ul style="list-style-type: square;">\r\n<li style="text-indent: 9pt;">\r\n<div><span style="font-family: times new roman,times; font-size: 12pt; color: #000000;">получите знания и навыки составления и проверки договоров любой сложности</span></div>\r\n</li>\r\n<li style="text-indent: 9pt;">\r\n<div><span style="font-family: times new roman,times; font-size: 12pt; color: #000000;">минимизируете риски невыплаты по договорам</span></div>\r\n</li>\r\n<li>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt; color: #000000;">&nbsp;&nbsp; <span style="font-family: times new roman,times; font-size: 12pt;">сократите дебиторскую задолженность</span> </span></div>\r\n</li>\r\n<li>\r\n<div><span style="color: #000000;"><span style="font-size: 12pt; font-family: times new roman,times;">&nbsp;&nbsp; обретете юридическую самостоятельность и&nbsp; правовую защиту вашего предприятия<span style="font-size: 14pt; font-family: ''Times New Roman'',''serif'';"><span style="font-family: times new roman,times; font-size: 12pt;">&nbsp;</span></span></span></span><span style="font-size: 12pt; font-family: times new roman,times;"><span style="font-size: 14pt; font-family: ''Times New Roman'',''serif'';"><span style="font-family: times new roman,times; font-size: 12pt;">&nbsp;<span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: ''times new roman'',times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #ffffff; background-color: #ffffff;"><span style="color: #0000ff;"><strong><span style="color: #0000ff; background-color: #ffffff;"><a class="modal" href="#call_me" rel="{size:{x:460,y:130}}">Отправить заявку</a>&nbsp;</span></strong><span style="color: #000000;"><span style="background-color: #ffffff;"><span style="text-align: justify; text-indent: 36px; font-size: 12pt; font-family: ''times new roman'', times;">Возможно&nbsp;</span></span><span style="background-color: #ffffff;"><span style="text-align: justify; text-indent: 27pt; font-family: ''times new roman'', times; font-size: 16px; line-height: 24px;">Онлайн обучение *ВЕБИНАРЫ*</span></span><strong><span style="background-color: #ffffff;"><span style="text-align: justify; text-indent: 27pt; font-family: ''times new roman'', times; font-size: 16px; line-height: 24px;">&nbsp;</span></span></strong></span></span></span></span></span></span></span></span></span></div>\r\n</li>\r\n</ul>\r\n<div style="text-indent: 9pt;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;"><strong><span style="font-size: 14pt; font-family: ''Times New Roman'',''serif''; color: #000000;"><span style="font-family: times new roman,times; font-size: 12pt;">В программе</span></span></strong></span></span></div>\r\n<div style="text-indent: 9pt;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;"><strong><span style="font-size: 14pt; font-family: ''Times New Roman'',''serif''; color: #000000;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #000000;"><span style="color: #000000;"><span style="color: #0000ff;"><strong style="color: #000000;"></strong></span></span></span></span></span></span></strong></span></span><span style="color: blue; font-family: times new roman,times; font-size: 12pt;"><span style="color: blue;">Договорное регулирование хозяйственных правоотношений. <span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;"><strong><span style="font-size: 14pt; font-family: ''Times New Roman'',''serif''; color: #000000;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #0000ff;"><b><span style="font-family: times new roman,times; font-size: 12pt;">Новеллы в гражданском законодательстве в 2013-2014 г.</span></b></span></span></span></strong></span></span></span><br /> <span style="color: #000000;">•&nbsp;&nbsp;</span> &nbsp;<span style="color: #000000;">Основные принципы заключения договоров.</span><br /><span style="color: #000000;"> •&nbsp;&nbsp; &nbsp;Обязательное заключение договоров.</span><br /><span style="color: #000000;"> •&nbsp;&nbsp; &nbsp;Толкование договоров: примеры разночтений в договорах на основе судебной практики.</span><br /> <span style="color: blue;">Актуальные вопросы заключения, изменения, расторжения договора</span></span></div>\r\n<div><span style="font-size: 12pt; font-family: times new roman,times;">•&nbsp;&nbsp; &nbsp;Проверка полномочий лица, заключающего договор.<br /> •&nbsp;&nbsp; &nbsp;Последствия заключения договора неуполномоченным лицом.</span></div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;">•&nbsp;&nbsp;&nbsp; Процедура проверки благонадежности контрагента</span></div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;">•&nbsp;&nbsp; &nbsp;Определение существенных условий договора и правовые последствия: примеры судебной практики.<br /> •&nbsp;&nbsp; &nbsp;Актуальные вопросы заключения предварительного договора (протокол о намерениях) на примерах судебных дел.</span></div>\r\n<div><span><span style="font-family: times new roman,times; font-size: 12pt;">•&nbsp;&nbsp; &nbsp;Практические проблемы внесения изменений в договор: согласование, одностороннее внесение изменений, изменение по судебному решению.</span><br /><span style="font-family: times new roman,times; font-size: 12pt;"> •&nbsp;&nbsp; &nbsp;Проблемы расторжения договоров в случае существенного нарушения условий договора и в случае существенного изменения обстоятельств.</span><br /><span style="font-family: times new roman,times; font-size: 12pt;"> •&nbsp;&nbsp; &nbsp;Односторонний отказ от исполнения договора (аренда, подряд, услуги).</span><br /><span style="font-family: times new roman,times; font-size: 12pt;"> •&nbsp;&nbsp; &nbsp;Построен</span><span style="font-family: times new roman,times; font-size: 12pt;">ие регламента ведения договорной работы с целью минимизации судебных рисков. </span></span></div>\r\n<div>&nbsp;<span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: blue;">Способы обеспечения и исполнения договорных обязательств</span><br /> •&nbsp;&nbsp; &nbsp;Аванс, залог, задаток: особенности применения, различия, налогообложение.<br /> •&nbsp;&nbsp; &nbsp;Удержание, поручительство и неустойка: судебная практика.<br /> <span style="color: blue;">Особенности гражданско-правовой ответственности по договору:</span></span></div>\r\n<div>&nbsp;<span style="font-size: 12pt; font-family: times new roman,times;">• &nbsp; Штраф, пени, упущенная выгода. Как рассчитать свои выгоды и риски?<br /></span></div>\r\n<div>&nbsp;<span style="font-size: 12pt; font-family: times new roman,times;">• &nbsp; Законная и договорная неустойка</span></div>\r\n<div>&nbsp;<span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: blue;">Организация эффективной претензионной и исковой работы</span></span></div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: blue;"></span></span> <span style="font-size: 12pt; font-family: times new roman,times;">•&nbsp;&nbsp; Как организовать претензионную работу, для снижения рисков</span></div>\r\n<div><span style="font-size: 12pt; font-family: times new roman,times;"> <span style="font-size: 12pt; font-family: times new roman,times;">•&nbsp;&nbsp; Т</span>ипы дебиторов, методика работы по взысканию долгов<br /> •&nbsp;&nbsp; Перспективы и инструменты внесудебного урегулирования спора.</span></div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;">•&nbsp;&nbsp; Регламентация работы с&nbsp;дебиторской задолженностью компании</span></div>\r\n<div><span>•&nbsp; &nbsp;<span style="font-size: 12pt;"><span style="font-family: times new roman,times;">Медиация</span></span></span></div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #0000ff;"><span style="color: blue;">Практические советы по прекращению договорных обязательств</span><br /> <span style="color: #000000;">•&nbsp;&nbsp; &nbsp;</span><span style="color: #000000;">Вопросы прекращения обязательств путем их исполнения.</span><br /><span style="color: #000000;"> •&nbsp;&nbsp; &nbsp;Прекращение обязательства зачетом.</span><br /><span style="color: #000000;"> •&nbsp;&nbsp; &nbsp;Новация, как способ прекращения обязательств.</span><br /><span style="color: #000000;"> •&nbsp;&nbsp; &nbsp;Прощение долга – практические советы и налоговый аспект.</span><br /><span style="color: #000000;"> •&nbsp;&nbsp; &nbsp;Прекращение обязательств отступным.</span><br /><span style="color: #000000;"> •&nbsp;&nbsp; &nbsp;Судебная практика относительно перемены лиц в обязательстве.</span><br /> <em><span style="color: blue;">Договор поставки, договор аренды</span></em><br /> <span style="color: #000000;">•&nbsp;&nbsp; &nbsp;</span><span style="color: #000000;">Правовая позиция судов об исполнении договора как факте его заключения.</span><br /><span style="color: #000000;"> •&nbsp;&nbsp; &nbsp;Приложения к договору: могут ли они содержать существенные условия.</span><br /><span style="color: #000000;"> •&nbsp;&nbsp; &nbsp;Последствия неурегулированности разногласий между сторонами при заключении договора поставки.</span><br /><span style="color: #000000;"> •&nbsp;&nbsp; &nbsp;Проблемы<span style="font-family: times new roman,times;"> отгрузки товара. </span></span><br /><span style="font-family: times new roman,times;"><span style="color: #000000;"> </span><span style="color: #000000;">•&nbsp;&nbsp; &nbsp;Судебная практика по вопросам оплаты товара, несвоевременная оплата, неустойка.</span></span><br /><span style="color: #000000; font-family: times new roman,times;"> •&nbsp;&nbsp; </span><span style="font-family: times new roman,times;">&nbsp;<span style="color: #000000;">Доказательства и доказывание отгрузки товаров ненадлежащего качества</span></span></span></span></div>\r\n<div><span style="font-size: 12pt; font-family: times new roman,times; color: #000000;"><span style="font-size: 12pt;">•&nbsp;&nbsp;&nbsp; </span>Судебная <b><span style="font-family: times new roman,times;">пра</span>ктика по вопросам аренды</b>, скользкие вопросы арендных отношений</span></div>\r\n<div><span style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #000000;"><span style="font-size: 12pt;">•&nbsp;&nbsp;&nbsp; </span>Особенности заключения до</span>говоров по результатам проведения закупок: сроки, споры (контрактная система)</span></div>\r\n<div><b><span>&nbsp;</span></b></div>\r\n<div style="text-align: justify;"><span style="font-size: 12pt; font-family: times new roman,times;">Выдается методическая литература. Скидка 5% при оплате за 2&nbsp; недели до начала обучения. </span></div>\r\n<div><span style="font-size: 12pt; font-family: times new roman,times;">Длительность&nbsp; 15 часов&nbsp; 7 900 рублей.&nbsp;<span style="text-align: justify; text-indent: 36px; font-size: 12pt; font-family: ''times new roman'', times;">Возможно&nbsp;</span><span style="text-align: justify; text-indent: 27pt; font-family: ''times new roman'', times; font-size: 16px; line-height: 24px;">Онлайн обучение *ВЕБИНАРЫ*&nbsp;</span></span></div>', '', 1, 16, '2013-02-08 15:49:10', 42, '', '2014-05-13 12:19:06', 42, 0, '0000-00-00 00:00:00', '2013-02-08 15:49:10', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":null,"urlatext":"","targeta":"","urlb":null,"urlbtext":"","targetb":"","urlc":null,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 73, 20, 'Курсы  семинары Договорное право, курсы семинары Гражданское право. Курсы и семинары Процессуальное законодательство, курсы семинары анализ договоров, структура договора', ' Курсы по праву. Договорное и гражданское право. Как составить оптимальный договор, застраховаться от риска невыполнения условий договора. Эффективная претензионная и исковая работа. ', 1, 2353, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', ''),
(27, 76, 'Курсы, семинары по трудовому праву. Правовые   вопросы    работы  с  персоналом. ', 'pravovye-voprosy-raboty-s-personalom', '<h1 style="text-align: justify;"><span style="font-size: 14pt;" class="temaname0"><span style="font-family: times new roman,times;"><span style="color: navy;"><span style="color: #0000ff;"><span style="font-family: ''Times New Roman'';"><strong><span style="font-size: 12pt;">&nbsp;&nbsp; &nbsp;&nbsp; Курсы, семинары по трудовому праву. </span></strong><span style="font-size: 12pt;">Правовые</span><span style="font-size: 12pt;">&nbsp; вопросы работы&nbsp; с&nbsp;</span><span style="font-size: 12pt;"> персоналом. Новации трудового законодательства</span><strong><span style="font-size: 12pt;"><br /></span></strong></span></span></span></span></span></h1>\r\n<p style="text-align: justify;"><span style="font-size: 14pt;" class="temaname0"><span style="font-family: times new roman,times;"><span style="color: navy;"><span style="color: #0000ff;"><span style="font-family: ''Times New Roman'';"><span style="color: #000000;"><span style="font-size: 12pt;"><span style="font-size: 12pt; font-family: times new roman,times;">&nbsp;<span style="font-size: 12pt; font-family: times new roman,times;">&nbsp;&nbsp; Семинар по трудовому праву предназначен <span style="color: #0000ff;">д</span><span style="color: #0000ff;">ля юристов, менеджеров по персоналу,&nbsp; специалистов по кадровой работе,&nbsp; бухгалтерских служб</span></span>.</span></span><span style="font-size: 12pt;"><span style="font-size: 12pt; font-family: times new roman,times;"> После прохождения&nbsp; вы &nbsp;</span></span></span><strong><span style="font-size: 12pt;"><span style="font-size: 12pt; font-family: times new roman,times;"><span style="color: #17365d;"><span style="color: #000000;"> <br /></span></span></span></span></strong></span></span></span></span></span></p>\r\n<ul style="list-style-type: square;">\r\n<li>\r\n<div>&nbsp;<span style="font-family: times new roman,times; font-size: 12pt; color: #000000;">&nbsp; получите знания и навыки составления и проверки трудовых договоров, должностных инструкций </span></div>\r\n</li>\r\n<li>\r\n<div>&nbsp;&nbsp;<span style="font-family: times new roman,times; font-size: 12pt;"> узнаете&nbsp; новации трудового законодательства<span style="color: #000000;"><br /></span></span></div>\r\n</li>\r\n<li class="_mce_tagged_br">\r\n<div><span style="font-family: times new roman,times; font-size: 12pt; color: #000000;"><span style="font-size: 12pt; color: #000000;"><span style="font-size: 12pt; color: #000000;">&nbsp;&nbsp; сократите типичные ошибки при приемах и увольнениях</span></span></span></div>\r\n</li>\r\n<li>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt; color: #000000;">&nbsp;&nbsp; минимизируете судебные риски и санкции по трудовым отношениям</span></div>\r\n</li>\r\n<li>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt; color: #000000;">&nbsp;&nbsp; сможете&nbsp; провести эффективный аудит вашей кадровой службы</span></div>\r\n</li>\r\n<li class="_mce_tagged_br">\r\n<div><span style="color: #000000; font-family: times new roman,times;"><span style="font-size: 12pt;">&nbsp;&nbsp; обретете юридическую самостоятельность и&nbsp; правовую защиту вашего предприятия<span style="font-size: 14pt;"><span style="font-size: 12pt;">&nbsp;</span></span></span></span><span style="font-size: 12pt; font-family: times new roman,times;"><span style="font-size: 14pt; font-family: ''Times New Roman'',''serif'';"><span style="font-family: times new roman,times; font-size: 12pt;">&nbsp;<span style="font-family: times new roman,times; font-size: 12pt;"><span style="font-family: ''times new roman'',times; font-size: 12pt;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #ffffff; background-color: #ffffff;"><span style="color: #0000ff;"><strong><a class="modal" href="http://%D1%8D%D0%BC%D0%BC%D0%B5%D0%BD%D0%B5%D0%B4%D0%B6%D0%BC%D0%B5%D0%BD%D1%82.%D1%80%D1%84/obrazovanie/kursy-yurista/2-uncategorised/26-kurs-pravovye-aspekty-sostavleniya-i-analiza-dogovora#call_me" rel="{size:{x:460,y:130}}"><span style="color: #0000ff; background-color: #ffffff;">Отправить заявку</span></a></strong></span></span></span></span></span> </span></span></span></div>\r\n</li>\r\n</ul>\r\n<p>&nbsp; &nbsp;&nbsp; <span style="font-family: times new roman,times; font-size: 12pt; color: #800080;">Программа</span></p>\r\n<p style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;">Локальные нормативные акты и должностные инструкции</span></p>\r\n<ul>\r\n<li style="text-align: justify;">&nbsp;<span style="font-family: times new roman,times; font-size: 12pt;">Особенности утверждения, согласования и ознакомления локально нормативных актов<br /></span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Взаимосвязь штатного расписания и должностных инструкций. Должностная инструкция как неотъемлемая часть трудового договора. Ответственность за выполнение отдельных трудовых функций, регламентируемых в локальных нормативных актах. Современный формат должностной инструкции</span></li>\r\n</ul>\r\n<p style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;">&nbsp;Трудовой договор. Оформление, изменение. Типичные ошибки и судебная практика</span></p>\r\n<ul>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Трудовой договор или гражданско-правовой. Ограничения и риски применения ГПД. Типичные ошибки в оформлении. Судебная практика признания трудовых отношений при формально составленных ГПД. Типичные ошибки, приводящие в суд после налоговых проверок</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Срочные и бессрочные договора. Сроки трудовых договоров. Ограничения заключения «срочных» договоров. Особенности срока трудовых отношений с совместителями. Особенности оформления трудовых договоров с руководителями</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Обязательные условия. Общий порядок внесения изменений в трудовой договор, варианты, ограничения, типовые нарушения. Временные и постоянные изменения</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Переводы и перемещения работников на другую работу. Добровольность работника и административные права работодателя. Легитимный документооборот увольнения&nbsp; при несогласии или невозможности перевода</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Варианты оформления и изменения трудовых отношений при реорганизации. Изменения должностных инструкций, переводы увольнением, сокращение штата, увольнение руководителей при смене собственника, слияние и раздeление структурных подразделений. Правовой и психологический аспекты</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Договора о материальной ответственности, обучении и неразглашения коммерческой тайны</span></li>\r\n</ul>\r\n<p style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;">&nbsp;Кадровый документооборот</span></p>\r\n<ul>\r\n<li>&nbsp;<span style="font-family: times new roman,times; font-size: 12pt;">Документооборот приема. Особенности оформления документов с генеральными директорами нескольких компаний. Особенности оформления на работу иностранцев, инвалидов, несовершеннолетних. Кому нельзя отказать в приеме на работу. Документооборот легитимного отказа. Отказы кандидатам от государственной службы занятости</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Испытательный срок. Оценка исполнения трудовых обязанностей. Оформление заработной платы новичка на испытательном сроке ниже «ключевого сотрудника». Варианты схем. Кому не устанавливается испытательный срок. Легитимный документооборот увольнения работников, не прошедших испытательный срок. Адаптация – как фильтр корпоративной культуры. Судебная практика «неприменимости» ст. 71</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Трудовая книжка. Типичные ошибки оформления. Страховой стаж и периоды работы, споры при их несовпадении</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Отпуска. Виды, оформление графика, приказов, заявлений, отзывов из отпуска. Льготные категории по времени предоставления отпуска. Особенности оформления отпусков льготным категориям работников. Спорные вопросы предоставления отпуска новым сотрудникам. Больничный во время отпуска. Перенос отпуска. Какие части и каких отпусков можно получить деньгами. Особенности расчета отпускных у работников, которые часто берут «отпуск за свой счет». Учебные отпуска</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Несчастный случай на производстве. Что должен знать кадровик</span></li>\r\n</ul>\r\n<p style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #0000ff;">&nbsp;Особенности увольнения сотрудников</span> </span></p>\r\n<ul>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Основания увольнения. Легитимный документооборот. Риски и типичные ошибки</span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Увольнение «по собственному желанию» - формулировка не из Трудового кодекса</span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Взаимодействие с профсоюзами</span></li>\r\n</ul>\r\n<p><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;">&nbsp; Ответственность работодателя (кадровика, руководителя отдела персонала, бухгалтера, генерального директора) и трудовые споры</span></p>\r\n<ul>\r\n<li>&nbsp;<span style="font-family: times new roman,times; font-size: 12pt;">Дисциплинарная ответственность. Особенности оформления дисциплинарных взысканий. Документы, наделяющие полномочиями расследовать факты нарушения дисциплины</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Материальная ответственность. Судебная практика взыскания ущерба в полном объеме. Взыскание затрат на дорогостоящее обучение</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Административная и уголовная ответственность. Проверки Государственной инспекции труда. Минимизация рисков обращения работников в надзорно-контрольные органы. Практика «отзыва заявлений». Особенности перекрестных проверок по вопросам, связанным с трудовыми отношениями (налоговая, Роскомнадзор, Ростехнадзор, др.) с учетом изменений&nbsp; ФЗ «О персональных данных». Ограничения получения информации о работнике из сторонних организаций</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Предупреждение конфликтов, приводящих к обращениям граждан в надзорно-контрольные органы. Этика поведения специалистов HR при спорных и конфликтных ситуациях</span></li>\r\n</ul>\r\n<p><span style="font-family: times new roman,times; font-size: 12pt;">&nbsp;<i>Обзор судебной практики по вопросам расторжения трудовых договоров по инициативе работодателя.</i></span></p>\r\n<p><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;">&nbsp;Правовое поле системы вознаграждений в организации</span></p>\r\n<ul>\r\n<li style="text-align: justify;">&nbsp;<span style="font-family: times new roman,times; font-size: 12pt;">Постоянная и переменная часть. Взаимосвязь штатного расписания, норм труда и должностных обязанностей. Принципы и ограничения при необходимости изменений</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Условия оплаты труда, включаемые в трудовой договор. Положение об оплате труда, премировании</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Коллективный договор. Порядок изменений</span></li>\r\n</ul>\r\n<p style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;">&nbsp; Система нормирования – технология управления производительностью труда</span></p>\r\n<ul>\r\n<li style="text-align: justify;">&nbsp;<span style="font-family: times new roman,times; font-size: 12pt;">Структура системы нормирования на предприятии. Документы, регламентирующие процесс нормирования</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Классификация норм труда. Нормативы затрат труда и методы нормирования. Нормируемая величина денежных средств, направляемых на оплату труда</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Фотография рабочего дня и хронометраж – основные инструменты каждого руководителя</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Потери рабочего времени. По организационно-техническим причинам, связанные с нарушением трудовой дисциплины</span></li>\r\n</ul>\r\n<p><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;">&nbsp;Особенности ненормированного труда</span></p>\r\n<ul>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Нормированный и Ненормированный труд. Ненормированный труд и его свойства</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Ненормированный рабочий день. Цель установления и основание для использования. Порядок компенсации. Ненормированный рабочий день и сверхурочная работа</span></li>\r\n</ul>\r\n<p><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;">&nbsp;Заработная плата при сменном режиме труда. Особенности суммированного учета</span></p>\r\n<ul>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Особенность повременной оплаты при сменном режиме труда.</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Заработная плата за согласованную продолжительность работы в смене и ее превышение над федеральной нормой рабочего времени</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Вахта. Продолжительность вахты. Междусменный и междувахтовый отдых</span></li>\r\n</ul>\r\n<div style="text-align: justify; text-indent: 27pt;"><span style="font-family: times new roman,times; font-size: 12pt;" class="punktname0"><span style="color: #993366;">Скидка 5% </span>при оплате за 2&nbsp; недели до начала обучения&nbsp;<br /></span></div>\r\n<div style="text-align: justify; text-indent: 27pt;"><span style="font-size: 12pt;" class="punktname0"><span style="font-family: times new roman,times;">Курс длится&nbsp; 15&nbsp; часов&nbsp; Стоимость 7900.</span> </span></div>\r\n<p><span style="font-family: times new roman,times; font-size: 12pt;" class="temaname0"><b><span style="color: navy;"><span style="color: #0000ff;"><b>&nbsp;</b></span></span></b></span></p>', '', 1, 2, '2013-04-29 14:30:08', 42, '', '2014-05-13 12:19:46', 42, 0, '0000-00-00 00:00:00', '2013-04-29 14:30:08', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":null,"urlatext":"","targeta":"","urlb":null,"urlbtext":"","targetb":"","urlc":null,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 40, 55, '', '', 1, 1023, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content_v3` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(28, 77, 'Курсы Право и юридические аспекты предпринимательской деятельности', 'kursy-pravo-i-yuridicheskie-aspekty-predprinimatelskoj-deyatelnosti', '<h1 style="text-align: justify;"><span class="temaname0"><b><span style="color: navy;"><span style="font-family: times new roman,times; font-size: 12pt;">&nbsp;</span></span></b></span><span class="temaname0"><b><span style="color: navy;"><span style="font-family: times new roman,times; font-size: 12pt;">Курсы&nbsp; Право и юридические аспекты предпринимательской деятельности</span> <br /></span></b></span></h1>\r\n<div style="text-align: justify;"><span class="temaname0"><b><span style="color: navy;"></span></b></span><span style="font-family: times new roman,times; font-size: 12pt;"><span class="temaname0"><b><span style="color: navy;">&nbsp; </span></b></span><b><span style="color: navy;"></span></b><span style="color: #800080;"><span class="temaname0">Программа курса</span><a href="index.php?option=com_content&amp;view=article&amp;id=26:kurs-pravovye-aspekty-sostavleniya-i-analiza-dogovora&amp;catid=2:uncategorised"><span style="color: #800080; text-decoration: none;"></span></a></span></span></div>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"><b><span style="color: blue;">Гражданское право.</span></b><span class="punktname"><span style="font-family: times new roman,times;">&nbsp;&nbsp;</span> </span></span></div>\r\n<div style="text-align: justify;">\r\n<ul>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;" class="punktname">&nbsp;Физические лица: правоспособность и дееспособность. Юридические лица: создание, реорганизация, ликвидация ЮЛ. Вещи как объекты гражданских прав. Государственная регистрация недвижимости. Приостановление и перерыв течения срока исковой давности. Приобретение&nbsp; права собственности и основания прекращения.&nbsp; Сделки, основания и последствия признания сделок недействительными. Доверенность. <br style="font-family: times new roman,times; font-size: 12pt;" class="punktname" /></span></li>\r\n</ul>\r\n</div>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">&nbsp;<strong><i><span style="color: black;">Теория и практика составления и проверки договора</span></i></strong></span></div>\r\n<div style="text-align: justify;">\r\n<ul>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;" class="punktname">Алгоритм составления договора. &nbsp; Структура договора. &nbsp; Практические рекомендации по составлению договора купли - продажи. Договор аренды. Практические рекомендации по составлению договора аренды. Определение существенных условий договора и правовые последствия: примеры судебной практики.</span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;" class="punktname">Обязательное заключение договоров</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;" class="punktname">Толкование договоров: примеры разночтений в договорах на основе судебной практики.</span></li>\r\n</ul>\r\n<span style="font-family: times new roman,times; font-size: 12pt;" class="temaname"><b><span style="color: blue;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Трудовое право.</span></b></span></div>\r\n<div>\r\n<ul>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;" class="temaname"><b><span style="color: blue;"></span></b></span><span style="font-family: times new roman,times; font-size: 12pt;" class="punktname">Трудовой договор. Заключение. Рабочее время. Отпуск.&nbsp; Дисциплинарный процесс. Порядок наложения дисциплинарных санкций. <i>Практика трудовых споров.</i></span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;" class="punktname">Трудовой договор или гражданско-правовой. Ограничения и риски применения ГПД. Типичные ошибки в оформлении. Судебная практика признания трудовых отношений при формально составленных ГПД. Типичные ошибки, приводящие в суд после налоговых проверок</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;" class="punktname"></span><span style="font-family: times new roman,times; font-size: 12pt;" class="punktname">Переводы на другую работу. Увольнение работников. Виды увольнений. Основания увольнения. Легитимный документооборот. Риски и типичные ошибки</span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;" class="punktname">Материальная ответственность. Судебная практика взыскания ущерба в полном объеме. </span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;" class="punktname">Проверки Государственной инспекции труда. Минимизация рисков обращения работников в надзорно-контрольные органы. Практика «отзыва заявлений».</span></li>\r\n</ul>\r\n</div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;" class="temaname"><b><span style="color: blue;">Налоговое право.</span></b></span></div>\r\n<div>\r\n<ul>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"><span class="punktname">Законодательство о налогах и сборах. Понятие налога. Виды налогов. Право и обязанности налогоплательщиков. Объекты налогообложения. Права и обязанности налоговых органов. Способы обеспечения исполнения обязанности по уплате налогов. Налоговый контроль. Виды и порядок проведения налоговых проверок. Ответственность за нарушения налоговых правонарушений.<b><span style="color: blue;"> </span></b></span><i>Практика защиты налогоплательщиком своих интересов.</i> <i>Налоговые проверки: спорные вопросы назначения, проведения проверки</i></span></li>\r\n<li style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;"><i> </i>Объекты, ставки, налогооблогаемая база основных налогов. Практика расчетов по налогу на добавленную стоимость,&nbsp; налог на прибыль,&nbsp; налог на имущество. Специальные режимы налогообложения: ЕНВД, УСНО, патентная система</span></li>\r\n</ul>\r\n</div>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;" class="temaname"><b><span style="color: blue;">Жилищное право.</span></b></span></div>\r\n<div style="text-align: justify;">\r\n<ul>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;" class="punktname">Найм жилых помещений, находящихся в государственной и муниципальной собственности. Выселение из жилых помещений. Жилые помещения, принадлежащие гражданам на праве собственности.</span></li>\r\n</ul>\r\n</div>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;" class="temaname"><b><span style="color: blue;">Гражданский процесс.</span></b></span></div>\r\n<div style="text-align: justify;">\r\n<ul>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;" class="punktname">Участники гражданского процесса. Сроки рассмотрения гражданских дел. Судебные доказательства. Производство в суде первой инстанции. Кассационное обжалование судебных решений. Надзорное производство. Исполнительное производство.<b> </b><i>Эффективное рассмотрение дел в арбитражных судах: практические проблемы и новеллы законодательства</i></span></li>\r\n</ul>\r\n</div>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;" class="temaname"><b><span style="color: blue;">Административная ответственность.</span></b></span></div>\r\n<div style="text-align: justify;">\r\n<ul>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;" class="punktname">Административные правонарушения. Административные взыскания и сроки их выполнения.</span></li>\r\n</ul>\r\n</div>\r\n<div style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;" class="punktname">&nbsp;Обучение построено на основных теоретических аспектах законодательства, актуальных практических - правовых примерах. Выдается методическая литература. После прохождения курса Вы получите: навыки работы с нормативно – правовой базой, научитесь составлять договора любой сложности, обретете юридическую самостоятельность себя как гражданина, правовую защиту вашего предприятия. </span></div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;" class="punktname0"><span style="color: red;">&nbsp;</span></span></div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;" class="punktname0"><span style="color: red;">Скидка 5%</span> при оплате за 2&nbsp; недели до начала обучения&nbsp; </span></div>\r\n<div><span style="font-family: times new roman,times; font-size: 12pt;" class="punktname0">Курс длится&nbsp; 40 часов&nbsp; Стоимость 17 000. </span></div>', '', 1, 8, '2013-05-02 19:19:50', 42, '', '2013-06-13 09:18:13', 42, 0, '0000-00-00 00:00:00', '2013-05-02 19:19:50', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":null,"urlatext":"","targeta":"","urlb":null,"urlbtext":"","targetb":"","urlc":null,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 22, 0, 'Курсы и семинары юридические, курсы и семинары повышения квалификации для юристов в Екатеринбурге, Курсы: Право и юридические аспекты предпринимательской деятельности, основы трудового, налогового, гражданского законодательства', 'Право и юридические аспекты предпринимательской деятельности', 1, 877, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content_v3` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(29, 78, 'Курс Финансы предприятия, управленческий учет', 'kurs-finansy-predpriyatiya', '<h1 style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;">Курс Финансы предприятия: управленческий учет и бюджетирование. <span style="font-family: times new roman,times; font-size: 14pt;"><span style="color: #0000ff;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #0000ff;">Продвинутый <span style="font-family: times new roman,times; font-size: 14pt;"><span style="color: #0000ff;"><span style="font-family: times new roman,times; font-size: 12pt;"><span style="color: #0000ff;">Excel. Управление инвестициями.<br /></span></span></span></span></span></span></span></span></span></h1>\r\n<p><span style="font-family: ''times new roman'',times; font-size: 12pt; color: #000000;"><strong>Целевая аудитория: </strong><span style="font-family: ''times new roman'',times;"><span style="font-family: ''times new roman'',times;">руководители подразделений, финансовые менеджеры, работники планово-экономического отдела, бухгалтер, главный бухгалтер</span></span><br /></span></p>\r\n<div style="text-align: left;"><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;"><span style="color: #000000;"><span style="font-family: times new roman,times;"><strong><span style="font-family: times new roman,times;"><span style="font-family: times new roman,times;">Ведущий</span></span></strong></span><span style="font-family: times new roman,times;"><span style="font-family: times new roman,times;"><strong>:</strong> <span style="color: #0000ff;"><a href="index.php?option=com_content&amp;view=article&amp;id=53:biznes-trener-nasonova-nadezhda-yurevna&amp;catid=2:uncategorised"><span style="color: #0000ff;">Насонова Надежда Юрьевна</span></a></span></span></span></span><span style="color: #000000;"><span style="font-family: times new roman,times;"><br /></span></span></span></div>\r\n<div style="text-align: justify;"><span style="font-family: ''times new roman'',times; font-size: 12pt; color: #000000;"><span style="font-family: times new roman,times;"><span style="font-family: ''times new roman'',times;"><span style="font-family: ''times new roman'',times;">Курс Финансы предприятия состоит из&nbsp; базовых курсов экономики, бюджетирования&nbsp; и управления инвестициями. После прохождения курса по финансам вы п<span style="font-family: ''times new roman'',times;">олучите комплекс практических инструментов по формированию себестоимости, разработке и оптимизации систем управленческого учета, бюджетирования. Разберете и закрепите на практических примерах <strong>все процессы управления экономикой компании</strong>.&nbsp;</span></span> </span></span></span></div>\r\n<div><span style="font-family: ''times new roman'',times; font-size: 12pt; color: #0000ff;"><span style="color: #000000;"><span style="font-family: times new roman,times;"><span style="font-family: ''times new roman'',times; color: #a8053f;">&nbsp;&nbsp;&nbsp;<span style="color: #000000;"><strong> В программе</strong> </span><br /></span></span></span></span></div>\r\n<div><span style="font-family: ''times new roman'',times; color: #0000ff; font-size: 12pt;">1.Основы экономики предприятия</span></div>\r\n<ul>\r\n<li><span style="font-size: 12pt;"><span style="font-family: ''times new roman'',times;">Точка безубыточности. Анализ безубыточности</span></span></li>\r\n<li><span style="font-family: ''times new roman'',times; font-size: 12pt;">&nbsp;Ключевой расчет маржинальной прибыли, чистой прибыли </span></li>\r\n<li><span style="font-size: 12pt;"><span style="font-family: ''times new roman'',times;">&nbsp;Ключевые показатели эффективности предприятия,&nbsp; </span><span style="font-family: ''times new roman'',times;"><span style="font-family: ''times new roman'',times;"><span style="font-family: ''times new roman'',times;"><span id=".D0.A0.D0.B0.D1.81.D1.87.D1.91.D1.82_EBITDA" class="mw-headline">EBITDA, ROE</span></span></span></span></span></li>\r\n<li><span style="font-family: ''times new roman'',times; font-size: 12pt;">&nbsp;Анализ финансовых результатов деятельности</span></li>\r\n<li><span style="font-family: ''times new roman'',times; font-size: 12pt; color: #0000ff;"><span style="color: #000000;">Анализ эффективности использования&nbsp; оборотных средств (оборачиваемость, материалоемкость). Нормирование.</span></span></li>\r\n<li><span style="font-size: 12pt;"><span style="font-family: ''times new roman'',times; color: #0000ff;"><span style="color: #000000;">Анализ &nbsp;<span style="font-family: ''times new roman'',times; color: #0000ff;"><span style="color: #000000;">эффективности использования трудовых ресурсов </span></span></span></span><span style="font-style: normal; font-variant: normal; font-weight: normal; line-height: normal; font-family: ''times new roman'',times;">(выработка, трудоемкость)</span></span></li>\r\n</ul>\r\n<div style="margin: 0cm 0cm 0.0001pt 14.25pt; text-indent: -14.25pt; text-align: justify;"><span style="font-family: ''times new roman'',times; font-size: 12pt;">&nbsp; - <b><i><span style="font-family: ''Times New Roman'';">Практические задания точки безубыточности и валовой маржи. Определение наиболее рентабельных проектов, видов деятельности, продукции</span></i></b></span></div>\r\n<div style="margin: 0cm 0cm 0.0001pt 14.25pt; text-indent: -14.25pt; text-align: justify;"><span style="font-family: ''times new roman'',times; font-size: 12pt;"><b><i><span style="font-family: ''Times New Roman'';">&nbsp;</span></i></b></span></div>\r\n<div style="margin: 0cm 0cm 0.0001pt 14.25pt; text-indent: -14.25pt; text-align: justify;"><span style="font-family: ''times new roman'',times; font-size: 12pt;"><b><i><span style="font-family: ''Times New Roman'';"></span></i></b></span><span style="color: blue; font-family: times new roman,times; font-size: 12pt;">2. Эффективная финансово – экономическая служба<b><i><span style="border: 1pt none windowtext; padding: 0cm;"></span></i></b></span></div>\r\n<ul>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Требования к финансовой отчетности для руководителей.</span></li>\r\n<li class="MsoNormal" style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Принципы учетной политики управленческого учета. </span></li>\r\n<li class="MsoNormal" style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Чтение и интерпретации финансовых отчетов. Практикум по подготовке и использованию финансовой отчетности</span></li>\r\n<li class="MsoNormal" style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Функции финансового управляющего. </span></li>\r\n<li class="MsoNormal" style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Распределение функций финансово-экономической службы. </span></li>\r\n<li class="MsoNormal" style="text-align: justify;"><span style="font-family: times new roman,times; font-size: 12pt;">Показатели эффективности финансовой службы.</span></li>\r\n</ul>\r\n<p>&nbsp;<span style="font-family: ''times new roman'',times; font-size: 12pt; color: #0000ff;">3. Организация аналитического учета затрат</span></p>\r\n<ul>\r\n<li style="text-align: justify;"><span style="font-family: ''times new roman'',times; font-size: 12pt;"><span style="font-family: ''times new roman'',times;"></span>Бухгалтерский план счетов, с использованием которых осуществляется учет затрат на производство. <span style="font-family: ''times new roman'',times;">Группировка балансовых статей, баланс предприятия,&nbsp; строение балансовых счетов.</span></span></li>\r\n<li style="margin-top: 0cm; margin-right: 0cm; margin-bottom: 0.0001pt; text-indent: 0cm; text-align: justify;"><span style="font-style: normal; font-variant: normal; font-weight: normal; font-size: 12pt; line-height: normal; font-family: ''times new roman'',times;">Затраты по статьям калькуляции. Учет отдельных видов затрат. Система " Директ - костинг"</span></li>\r\n<li style="margin-top: 0cm; margin-right: 0cm; margin-bottom: 0.0001pt; text-indent: 0cm; text-align: justify;"><span style="font-style: normal; font-variant: normal; font-weight: normal; font-size: 12pt; line-height: normal; font-family: ''times new roman'',times;">Специфика и области применения различных методов учета производственных затрат: позаказного, котлового, попередельного.</span></li>\r\n<li style="margin-top: 0cm; margin-right: 0cm; margin-bottom: 0.0001pt; text-align: justify;"><span style="font-size: 12pt;"><span style="font-family: times new roman,times; font-style: normal; font-variant: normal; font-weight: normal; line-height: normal; font-size-adjust: none; font-stretch: normal; -moz-font-feature-settings: normal; -moz-font-language-override: normal;"><span style="font-family: times new roman,times; font-style: normal; font-variant: normal; font-weight: normal; line-height: normal; font-size-adjust: none; font-stretch: normal; -moz-font-feature-settings: normal; -moz-font-language-override: normal;">Классификация расходов и затрат,&nbsp; формирующих себестоимость продукции,&nbsp;</span></span><span style="font-family: times new roman,times; font-style: normal; font-variant: normal; font-weight: normal; line-height: normal; font-size-adjust: none; font-stretch: normal; -moz-font-feature-settings: normal; -moz-font-language-override: normal;"> их отличия</span></span></li>\r\n</ul>\r\n<div style="margin: 0cm 0cm 0.0001pt;"><span style="font-size: 12pt;"><span style="font-family: ''times new roman'',times;"><span style="font-family: ''times new roman'',times;"><span style="font-family: ''times new roman'',times;"><span style="color: #0000ff;"><span style="font-family: times new roman,times;">- </span></span></span></span></span><span style="font-family: ''times new roman'',times;"><b><i>Практические задания по расчету себестоимости и цены. Оптимизация затрат.</i></b></span><span style="font-family: ''times new roman'',times;"><span style="font-family: ''times new roman'',times;"><span style="color: #0000ff;"><span style="font-family: times new roman,times;"></span></span></span></span></span></div>\r\n<div style="margin: 0cm 0cm 0.0001pt;"><span style="font-family: ''times new roman'',times; font-size: 12pt;"><b><i>&nbsp;</i></b></span></div>\r\n<div style="margin: 0cm 0cm 0.0001pt;"><span style="font-size: 12pt;"><span style="font-family: ''times new roman'',times;"><b><i></i></b></span><span style="font-family: ''times new roman'',times; color: #0000ff;">4. Бюджетирование – как часть системы управления предприятием.</span></span></div>\r\n<ul>\r\n<li><span style="font-size: 12pt;"><span style="font-family: ''times new roman'',times;">Сущность бюджетного управления, бюджет в системе планов предприятия;</span></span></li>\r\n<li><span style="font-size: 12pt;"><span style="font-family: ''times new roman'',times;"><span style="font-family: ''times new roman'',times;"><span style="font-family: times new roman,times;"><span style="font-family: ''times new roman'',times;">Постановка системы бюджетного управления</span>:</span></span></span><span style="font-family: ''times new roman'',times;">&nbsp; определение участников процесса бюджетного управления,&nbsp; определение центров финансовой ответственности, учета (ЦФО, ЦФУ);</span></span></li>\r\n<li><span style="font-family: ''times new roman'',times; font-size: 12pt;">Подходы к построению системы бюджетирования на предприятии;</span></li>\r\n<li><span style="font-size: 12pt; font-family: ''times new roman'',times;"><span style="font-family: ''times new roman'',times;"><span style="font-family: ''times new roman'',times;">Регламентация системы бюджетирования на предприятии. Бюджетная система:&nbsp; Система бюджетов на предприятии: Бюджет продаж, бюджет производства, бюджет накладных расходов, бюджет доходов и расходов, бюджет движения денежных средств.&nbsp; Взаимосвязь основных плановых и отчетных форм между собой. Контроль исполнения бюджетов – ключевая функция системы бюджетного управления.&nbsp; Анализ исполнения бюджета.</span></span></span></li>\r\n</ul>\r\n<p style="margin: 0cm 0cm 0.0001pt;"><span style="font-size: 12pt; font-family: ''times new roman'',times;"><span style="font-family: ''times new roman'',times;"><span style="font-family: ''times new roman'',times;">&nbsp;- <b><i><span style="font-family: ''Times New Roman'';">Практические задания по разработке бюджетов, контроль и анализ. Причины невыполнения бюджетов.</span></i></b></span></span></span></p>\r\n<p style="margin: 0cm 0cm 0.0001pt;"><span style="font-size: 12pt;">&nbsp;</span></p>\r\n<div style="margin: 0cm 0cm 0.0001pt;"><span style="font-size: 12pt; font-family: ''times new roman'',times; color: #0000ff;"><span style="font-family: ''times new roman'',times;"><span style="color: #0000ff;">5. Финансовая отчетность. Основные методы финансового анализа</span><em><br /></em></span></span></div>\r\n<div style="margin: 0cm 0cm 0.0001pt;">\r\n<ul>\r\n<li><!--[if gte mso 9]><xml>\r\n <w:WordDocument>\r\n  <w:View>Normal</w:View>\r\n  <w:Zoom>0</w:Zoom>\r\n  <w:PunctuationKerning/>\r\n  <w:ValidateAgainstSchemas/>\r\n  <w:SaveIfXMLInvalid>false</w:SaveIfXMLInvalid>\r\n  <w:IgnoreMixedContent>false</w:IgnoreMixedContent>\r\n  <w:AlwaysShowPlaceholderText>false</w:AlwaysShowPlaceholderText>\r\n  <w:Compatibility>\r\n   <w:BreakWrappedTables/>\r\n   <w:SnapToGridInCell/>\r\n   <w:WrapTextWithPunct/>\r\n   <w:UseAsianBreakRules/>\r\n   <w:DontGrowAutofit/>\r\n  </w:Compatibility>\r\n  <w:BrowserLevel>MicrosoftInternetExplorer4</w:BrowserLevel>\r\n </w:WordDocument>\r\n</xml><![endif]--><!--[if gte mso 9]><xml>\r\n <w:LatentStyles DefLockedState="false" LatentStyleCount="156">\r\n </w:LatentStyles>\r\n</xml><![endif]--><!--[if gte mso 10]>\r\n\r\n<![endif]--><span style="font-size: 12.0pt; font-family: ''Times New Roman''; mso-fareast-font-family: ''Times New Roman''; mso-ansi-language: RU; mso-fareast-language: RU; mso-bidi-language: AR-SA;">Финансовый анализ, как метод оценки текущего и перспективного финансового состояния предприятия: трендовый, факторный, метод цепных подстановок, горизонтальный, вертикальный<br /></span></li>\r\n</ul>\r\n</div>\r\n<ul>\r\n<li style="margin-top: 0cm; margin-right: 0cm; margin-bottom: 0.0001pt;">\r\n<div><span style="font-size: 12pt;"><span style="font-family: times new roman,times;">анализируем бухгалтерский баланс, в чем отличие от управленческого баланса</span></span></div>\r\n</li>\r\n<li style="margin-top: 0cm; margin-right: 0cm; margin-bottom: 0.0001pt;"><span style="font-size: 12pt;"><span style="margin: 0cm 0cm 0.0001pt; text-align: left; font-family: ''times new roman'',times;">особенности составления отчета о прибылях и убытках, отличие от Бюджета доходов и расходов</span></span></li>\r\n</ul>\r\n<p><span style="font-size: 12pt;"><span style="margin: 0cm 0cm 0.0001pt; text-align: left; font-family: ''times new roman'',times;"><span style="color: #0000ff;">6. Финансовый менеджмент -</span></span><span style="margin: 0cm 0cm 0.0001pt; text-align: left; font-family: ''times new roman'',times;"><span style="color: #0000ff;"><!--[if gte mso 9]><xml>\r\n <w:WordDocument>\r\n  <w:View>Normal</w:View>\r\n  <w:Zoom>0</w:Zoom>\r\n  <w:PunctuationKerning/>\r\n  <w:ValidateAgainstSchemas/>\r\n  <w:SaveIfXMLInvalid>false</w:SaveIfXMLInvalid>\r\n  <w:IgnoreMixedContent>false</w:IgnoreMixedContent>\r\n  <w:AlwaysShowPlaceholderText>false</w:AlwaysShowPlaceholderText>\r\n  <w:Compatibility>\r\n   <w:BreakWrappedTables/>\r\n   <w:SnapToGridInCell/>\r\n   <w:WrapTextWithPunct/>\r\n   <w:UseAsianBreakRules/>\r\n   <w:DontGrowAutofit/>\r\n  </w:Compatibility>\r\n  <w:BrowserLevel>MicrosoftInternetExplorer4</w:BrowserLevel>\r\n </w:WordDocument>\r\n</xml><![endif]--></span></span><span style="margin: 0cm 0cm 0.0001pt; text-align: left; font-family: ''times new roman'',times;"><span style="color: #0000ff;"> </span></span><span style="font-family: times new roman,times; color: #0000ff;">Управление инвестициями</span></span></p>\r\n<ul>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Основные показатели, используемые для расчетов эффективности инвестиционного проекта.</span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;"> Чистый дисконтированный доход (NPV) </span></li>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">Индекс рентабельности инвестиций </span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Внутренняя норма доходности</span></li>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">Срок окупаемости инвестиций </span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Управление заемным капиталом</span></li>\r\n<li><span style="font-family: times new roman,times; font-size: 12pt;">Стоимость капитала: ее составляющие и методы оценки.</span></li>\r\n<li><span style="font-size: 12pt;"><span style="font-family: times new roman,times;"></span><span style="font-family: times new roman,times;">Ликвидность и способы ее оценки </span></span></li>\r\n</ul>\r\n<div><span style="font-size: 12pt;"><span style="font-family: ''times new roman'',times;"><b><i>- Практические задания по расчету оценки инвестиционных пректов</i></b></span></span></div>\r\n<p><span style="font-size: 12pt; font-family: ''times new roman'',times;"><span style="font-family: ''times new roman'',times;"><span style="font-family: ''times new roman'',times;"><span style="color: #0000ff;">7. Практические примеры построения&nbsp; бюджетов в программе</span> <span style="font-family: ''times new roman'',times; color: #0000ff;">Excel<strong> – </strong><span style="color: #000000;">программа для управленческого учета и системы бюджетирования на предприятии. </span></span></span></span></span></p>\r\n<ul>\r\n<li style="margin-top: 0cm; margin-right: 0cm; margin-bottom: 0.0001pt;"><span style="font-size: 12pt; font-family: ''times new roman'',times;"><span style="font-family: ''times new roman'',times;"><span style="font-family: ''times new roman'',times;"><span style="font-family: ''times new roman'',times; color: #0000ff;"><span style="color: #000000;"><strong><em>Изучение</em></strong> <span style="font-family: ''times new roman'',times;"><em><strong>наиболее востребованных</strong> <strong>формул и функций Excel</strong></em> для построения бюджетов.</span></span></span></span></span></span></li>\r\n<li style="margin-top: 0cm; margin-right: 0cm; margin-bottom: 0.0001pt;"><span style="font-size: 12pt;"><span style="font-family: ''times new roman'',times;"><span style="font-family: ''times new roman'',times;"><span style="font-family: ''times new roman'',times;"><span style="font-family: ''times new roman'',times; color: #0000ff;"><span style="color: #000000;"><span style="font-family: ''times new roman'',times;"><b><i><span style="font-family: ''Times New Roman'';">Практические задания в </span></i></b><strong><i><span style="color: black; font-weight: normal;">Excel</span></i></strong><b><i><span style="font-family: ''Times New Roman'';"> и 1 С «Бухгалтерия».</span></i></b></span></span></span></span></span></span><span style="font-family: times new roman,times; color: #0000ff;"><span style="font-family: times new roman,times;"><span style="color: #000000;"> </span></span></span></span></li>\r\n</ul>\r\n<div class="MsoNormal"><span style="font-size: 12pt; font-family: ''times new roman'',times;">Работа с данными</span></div>\r\n<ul>\r\n<li><span style="font-size: 12pt; font-family: ''times new roman'',times;">поиск и замена данных</span></li>\r\n<li class="_mce_tagged_br"><span style="font-family: ''times new roman'',times; font-size: 12pt;">сортировка по значениям одного столбца, формату, нескольким столбцам, части диапазона</span></li>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: ''times new roman'',times;">установка фильтра и работа с ним</span></li>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: ''times new roman'',times;">отбор по значению, формату, условию, по ячейке</span></li>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: ''times new roman'',times;">отбор наибольших и наименьших значений</span></li>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: ''times new roman'',times;">отказ от отбора</span></li>\r\n</ul>\r\n<div class="MsoNormal"><span style="font-size: 12pt; font-family: ''times new roman'',times;">Сводные таблицы</span></div>\r\n<ul>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: ''times new roman'',times;">Создание сводной таблицы</span></li>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: ''times new roman'',times;">Форматирование сводной таблицы</span></li>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: ''times new roman'',times;">Модификация таблицы</span></li>\r\n</ul>\r\n<p><span style="font-family: ''times new roman'',times; font-size: 12pt;">Защита информации</span></p>\r\n<ul>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: ''times new roman'',times;">Скрытие строк и столбцов, их отображение</span></li>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: ''times new roman'',times;">Скрытие и отображение формул </span></li>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: ''times new roman'',times;">защита всех ячеек листа</span></li>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: ''times new roman'',times;">снятие защиты листа</span></li>\r\n</ul>\r\n<div><span style="font-size: 12pt;"><span style="font-family: times new roman,times;">Поисковые, справочные и информационные функции. </span><span style="font-family: times new roman,times;">Базовые поисковые функции:</span></span></div>\r\n<div class="MsoNormal">\r\n<ul>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">вертикальный поиск ВПР() и горизонтальный поиск ГПР()</span></li>\r\n</ul>\r\n</div>\r\n<div class="MsoNormal"><span style="font-size: 12pt;"><span style="font-family: times new roman,times;">&nbsp;Создание сложных формул и выявление ошибок. </span><span style="font-family: times new roman,times;">Условия в формулах:</span></span></div>\r\n<ul>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: times new roman,times;">построение условных формул: ЕСЛИ()</span></li>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: times new roman,times;">подсчет только указанных ячеек: СЧЕТЕСЛИ()</span></li>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: times new roman,times;">расчет условных сумм с одним критерием СУММЕСЛИ()</span></li>\r\n</ul>\r\n<div class="MsoNormal"><span style="font-size: 12pt; font-family: times new roman,times;">Описательные имена для ссылок на ячейки:</span></div>\r\n<ul>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: times new roman,times;">создание и использование именованного диапазона</span></li>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: times new roman,times;">управление именованными диапазонами</span></li>\r\n<li class="MsoNormal"><span style="font-size: 12pt; font-family: times new roman,times;">автоматическое создание именованных диапазонов</span></li>\r\n</ul>\r\n<div class="MsoNormal"><span style="font-size: 12pt; font-family: times new roman,times;">Работа с текстом</span></div>\r\n<div class="MsoNormal">\r\n<ul>\r\n<li><span style="font-size: 12pt; font-family: times new roman,times;">Объединение строк текста: СЦЕПИТЬ()</span></li>\r\n</ul>\r\n</div>\r\n<div><span style="margin: 0px; padding: 0px; border: 0px none; font-family: inherit; font-size: 12pt; font-style: inherit; font-variant: inherit; font-weight: inherit; line-height: inherit; vertical-align: baseline;"><span style="margin: 0px; padding: 0px; border: 0px none; font-family: ''times new roman'',times; font-style: inherit; font-variant: inherit; font-weight: inherit; line-height: inherit; vertical-align: baseline; text-align: left;">Продолжительность: 40 часов - 1 месяц, 2 раза в неделю, среда с 18.30 до 21.30, &nbsp;суббота с 14.00 до 18.00 . Выдается методическая литература.</span><span style="margin: 0px; padding: 0px; border: 0px none; font-family: ''times new roman'',times; font-style: inherit; font-variant: inherit; font-weight: inherit; line-height: inherit; vertical-align: baseline; text-align: left;"><span style="margin: 0px; padding: 0px; border: 0px none; font-family: Verdana,Arial,Helvetica,sans-serif; font-style: inherit; font-variant: inherit; font-weight: inherit; line-height: inherit; vertical-align: baseline;">&nbsp;&nbsp;</span></span></span></div>\r\n<div style="margin: 0px 0px 1.5em; padding: 0px; border: 0px; font-family: ''Times New Roman''; font-size: 12px; line-height: 18px; vertical-align: baseline; text-align: justify; color: #222222;"><span style="font-size: 12pt;"><span style="font-family: inherit; text-align: left; font-style: inherit; font-variant: inherit; font-weight: inherit; line-height: inherit; margin: 0px; padding: 0px; border: 0px none; vertical-align: baseline;">Для иногородних есть возможность пройти курсы дистанционного обучения.</span></span></div>\r\n<div style="margin: 0px 0px 1.5em; padding: 0px; border: 0px; font-family: ''Times New Roman''; font-size: 12px; line-height: 18px; vertical-align: baseline; text-align: justify; color: #222222;"><span style="font-size: 12pt;"><span style="font-family: inherit; text-align: left; font-style: inherit; font-variant: inherit; font-weight: inherit; line-height: inherit; margin: 0px; padding: 0px; border: 0px none; vertical-align: baseline;"></span><span style="font-family: ''times new roman'',times; text-align: left; font-style: inherit; font-variant: inherit; font-weight: inherit; line-height: inherit;"></span><span style="color: #000000; text-align: left; font-family: ''times new roman'',times;">Стоимость&nbsp; 17500,&nbsp; <span style="color: #0000ff;"><a href="index.php?option=com_content&amp;view=article&amp;id=20:ekonomicheskie-kursy&amp;catid=8:obrazovanie&amp;Itemid=171"><span style="color: #0000ff;">Расписание курса</span></a></span><span style="color: #0000ff;"></span>&nbsp;&nbsp; <span style="color: #ffffff;"><span style="color: #0000ff;"> <strong><a class="modal" href="http://%D1%8D%D0%BC%D0%BC%D0%B5%D0%BD%D0%B5%D0%B4%D0%B6%D0%BC%D0%B5%D0%BD%D1%82.%D1%80%D1%84/obrazovanie/ekonomicheskie-kursy/14-obrazovanie/kurs-qbyudzhetirovanie-planirovanie-i-uchet/22-kurs-byudzhetirovanie-planirovanie-i-uchet#call_me" rel="{size:{x:460,y:130}}"><span style="color: #0000ff;">Отправить заявку</span></a><span class="modal">&nbsp;&nbsp; </span></strong></span></span><span style="color: #800080;">Скидка 5% </span>при оплате за 2&nbsp; недели до начала обучения, обучение </span><span style="color: #000000; text-align: left; font-family: ''times new roman'',times;">1 месяц&nbsp;</span></span></div>\r\n<p style="margin: 0cm 0cm 0.0001pt;"><span style="font-size: 12pt; font-family: times new roman,times;"><span style="font-family: times new roman,times; font-size: 12pt;"><em><span style="font-family: times new roman,times; font-size: 12pt;"><em><span style="font-size: 14pt;"><span style="font-size: 12pt;">&nbsp;</span></span></em></span></em></span></span></p>\r\n<div style="position: absolute; left: -40px; top: 1013px; width: 1px; height: 1px; overflow: hidden;" data-mce-bogus="1" class="mcePaste" id="_mcePaste">\r\n<div class="MsoNormal"><span style="font-size: 10pt; font-family: terminal,monaco;">Работа с данными</span></div>\r\n<ul>\r\n<li><span style="font-size: 10pt; font-family: terminal,monaco;">поиск и замена данных</span></li>\r\n<li class="_mce_tagged_br"><span style="font-family: times new roman,times;">сортировка по значениям одного столбца, формату, нескольким столбцам, части диапазона</span></li>\r\n<li class="MsoNormal"><span style="font-size: 10pt; font-family: terminal,monaco;">установка фильтра и работа с ним</span></li>\r\n<li class="MsoNormal"><span style="font-size: 10pt; font-family: terminal,monaco;">отбор по значению, формату, условию, по ячейке</span></li>\r\n<li class="MsoNormal"><span style="font-size: 10pt; font-family: terminal,monaco;">отбор наибольших и наименьших значений</span></li>\r\n<li class="MsoNormal"><span style="font-size: 10pt; font-family: terminal,monaco;">отказ от отбора</span></li>\r\n</ul>\r\n<div class="MsoNormal"><span style="font-size: 10pt; font-family: terminal,monaco;">Сводные таблицы</span></div>\r\n<ul>\r\n<li class="MsoNormal"><span style="font-size: 10pt; font-family: terminal,monaco;">Создание сводной таблицы</span></li>\r\n<li class="MsoNormal"><span style="font-size: 10pt; font-family: terminal,monaco;">Форматирование сводной таблицы</span></li>\r\n<li class="MsoNormal"><span style="font-size: 10pt; font-family: terminal,monaco;">Модификация таблицы</span></li>\r\n</ul>\r\n<p><span style="font-size: 10pt; font-family: terminal,monaco;">Защита информации</span><span style="font-size: 10pt; font-family: terminal,monaco;"></span></p>\r\n<ul>\r\n<li class="MsoNormal"><span style="font-size: 10pt; font-family: terminal,monaco;">Скрытие строк и столбцов, их отображение</span></li>\r\n<li class="MsoNormal"><span style="font-size: 10pt; font-family: terminal,monaco;">Скрытие и отображение формул </span></li>\r\n<li class="MsoNormal"><span style="font-size: 10pt; font-family: terminal,monaco;">защита всех ячеек листа</span></li>\r\n<li class="MsoNormal"><span style="font-size: 10pt; font-family: terminal,monaco;">снятие защиты листа</span></li>\r\n</ul>\r\n<div>&nbsp;</div>\r\n<div class="MsoNormal"><span style="font-size: 10pt;"><span style="font-family: times new roman,times;">Поисковые, справочные и информационные функции. </span><span style="font-family: times new roman,times;">Базовые поисковые функции:</span></span></div>\r\n<div class="MsoNormal">\r\n<ul>\r\n<li><span style="font-size: 10pt; font-family: times new roman,times;">вертикальный поиск ВПР() и горизонтальный поиск ГПР()</span></li>\r\n</ul>\r\n</div>\r\n<div class="MsoNormal"><span style="font-size: 10pt;"><span style="font-family: times new roman,times;">&nbsp;Создание сложных формул и выявление ошибок. </span><span style="font-family: times new roman,times;">Условия в формулах:</span></span></div>\r\n<ul>\r\n<li class="MsoNormal"><span style="font-size: 10pt; font-family: times new roman,times;">построение условных формул: ЕСЛИ()</span></li>\r\n<li class="MsoNormal"><span style="font-size: 10pt; font-family: times new roman,times;">подсчет только указанных ячеек: СЧЕТЕСЛИ()</span></li>\r\n<li class="MsoNormal"><span style="font-size: 10pt; font-family: times new roman,times;">расчет условных сумм с одним критерием СУММЕСЛИ()</span></li>\r\n</ul>\r\n<div class="MsoNormal"><span style="font-size: 10pt; font-family: times new roman,times;">Описательные имена для ссылок на ячейки:</span></div>\r\n<ul>\r\n<li class="MsoNormal"><span style="font-size: 10pt; font-family: times new roman,times;">создание и использование именованного диапазона</span></li>\r\n<li class="MsoNormal"><span style="font-size: 10pt; font-family: times new roman,times;">управление именованными диапазонами</span></li>\r\n<li class="MsoNormal"><span style="font-size: 10pt; font-family: times new roman,times;">автоматическое создание именованных диапазонов</span></li>\r\n</ul>\r\n<div class="MsoNormal"><span style="font-size: 10pt; font-family: times new roman,times;">Работа с текстом</span></div>\r\n<div class="MsoNormal">\r\n<ul>\r\n<li><span style="font-size: 10pt; font-family: times new roman,times;">Объединение строк текста: СЦЕПИТЬ()</span></li>\r\n</ul>\r\n</div>\r\n<div class="MsoNormal"><span style="font-size: 10pt; font-family: times new roman,times;">Анализ данных и списки</span></div>\r\n<ul>\r\n<li class="MsoNormal"><span style="font-size: 10pt; font-family: times new roman,times;">группировка и структурирование данных</span></li>\r\n<li class="MsoNormal"><span style="font-size: 10pt; font-family: times new roman,times;">создание промежуточных итогов</span></li>\r\n<li class="MsoNormal"><span style="font-size: 10pt; font-family: times new roman,times;">создание и форматирование таблиц</span></li>\r\n<li class="MsoNormal"><span style="font-size: 10pt; font-family: times new roman,times;">сортировка и фильтрация таблицы</span></li>\r\n<li class="MsoNormal"><span style="font-size: 10pt; font-family: times new roman,times;">строка итогов</span></li>\r\n</ul>\r\n<div class="MsoNormal"><span style="font-size: 10pt; font-family: times new roman,times;">Использование сводных таблиц</span></div>\r\n<ul>\r\n<li class="MsoNormal"><span style="font-size: 10pt; font-family: times new roman,times;">Создание и форматирование сводной таблицы</span></li>\r\n<li class="MsoNormal"><span style="font-size: 10pt; font-family: times new roman,times;">Модификация таблицы</span></li>\r\n</ul>\r\n</div>', '', 1, 2, '2013-06-26 18:04:41', 42, '', '2014-10-01 11:07:28', 42, 0, '0000-00-00 00:00:00', '2013-06-26 18:04:41', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":null,"urlatext":"","targeta":"","urlb":null,"urlbtext":"","targetb":"","urlc":null,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 41, 54, 'Курс управленческий учет, обучение управленческий учет, курсы по оптимизации затрат, курсы экономики, обучение экономики, обучение бюджетирование', 'Курс Финансы предприятия -  практическое обучение управленческий учету и бюджетирование', 1, 986, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
INSERT INTO `j7_content_v3` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`) VALUES
(30, 79, 'Курсы, семинары по трудовому праву. Привлечение и использование иностранных работников', 'kursy-seminary-po-trudovomu-pravu-privlechenie-i-ispolzovanie-inostrannykh-rabotnikov', '<h1 style="text-align: justify;"><b><span style="font-size: 14pt; font-family: ''Times New Roman'',''serif'';">&nbsp;&nbsp;&nbsp;&nbsp; </span></b><span style="font-size: 14pt; font-family: ''Times New Roman'',''serif''; color: #0000ff;">&nbsp;<strong><span style="font-size: 12pt;">Новый порядок привлечения и использования иностранной рабочей силы в 2013 году. </span></strong></span><span style="font-size: 14pt; font-family: ''Times New Roman'',''serif''; color: #0000ff;"><span style="font-size: 12pt;">П</span></span><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';"><span style="color: #0000ff;">равовые особенности оформления отношений с иностранными работниками, типичные ошибки и санкции в работе с иностранцами.</span><span style="color: #0000ff;"><br /></span></span></h1>\r\n<p style="line-height: normal; text-align: left;" align="center"><span style="color: #800080;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp; Программа</span><b><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';"><br /></span></b></span></p>\r\n<p style="line-height: normal; text-align: justify;" align="center"><b><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">&nbsp; </span></b><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Обзор изменения законодательства за 2012-2013гг.&nbsp; Новое в законодательстве о регулирование труда иностранных работников в соответствии с ФЗ "О правовом положение иностранных граждан в РФ"</span></p>\r\n<p style="margin-left: 18pt; text-align: justify; text-indent: -18pt; line-height: normal; background: none repeat scroll 0% 0% white;"><strong><span style="font-size: 12pt; font-family: Wingdings; color: #0000ff;">&nbsp;</span></strong><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif''; color: black;"><span style="color: #0000ff;">Правовое положение иностранных работников в&nbsp; РФ</span> </span><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif''; color: black;"></span></p>\r\n<ul>\r\n<li style="color: black; text-align: justify; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Статус иностранных работников - временно пребывающие, временно проживающие, постоянно проживающие.</span></li>\r\n<li style="color: black; text-align: justify; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Документы, подтверждающие статус иностранного работника.</span></li>\r\n<li style="color: black; text-align: justify; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Особенности пребывания на территории РФ каждой категории иностранных работников.</span></li>\r\n<li style="color: black; text-align: justify; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Порядок оформления вида на жительство ВКС и членов его семьи.</span></li>\r\n</ul>\r\n<p style="margin-left: 18pt; text-align: justify; text-indent: -18pt; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="color: #0000ff; font-family: times new roman,times;"><span style="font-size: 12pt;">&nbsp;</span><span style="font-size: 12pt;">Порядок въезда иностранного работника на территорию РФ</span></span><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif''; color: black;"></span></p>\r\n<ul>\r\n<li style="color: black; text-align: justify; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Безвизовый въезд на территорию РФ.&nbsp; Миграционная карта.</span></li>\r\n<li style="color: black; text-align: justify; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Въезд в порядке, требующем получения визы. Виды и категории виз.&nbsp; Продление виз, оформление многократных виз. Порядок оформления виз для ВКС.</span></li>\r\n<li style="color: black; text-align: justify; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Оформление приглашений на въезд. Гарантии материального, медицинского и жилищного обеспечения.</span></li>\r\n</ul>\r\n<p style="margin-left: 18pt; text-align: justify; text-indent: -18pt; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-family: times new roman,times; font-size: 12pt; color: #0000ff;">Особенности миграционного учета</span><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif''; color: black;"></span></p>\r\n<ul>\r\n<li style="color: black; text-align: justify; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Правила постановки и снятия иностранца с миграционного учета.</span></li>\r\n<li style="color: black; text-align: justify; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Какие обязанности возлагаются на &nbsp;принимающую сторону?</span></li>\r\n<li style="color: black; text-align: justify; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Особенности миграционного учета отдельных категорий граждан. Миграционный учет ВКС.</span></li>\r\n<li style="color: black; text-align: justify; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Штраф за нарушение сроков и порядка постановки на миграционный учет.</span></li>\r\n</ul>\r\n<p style="margin-left: 18pt; text-align: justify; text-indent: -18pt; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="color: #0000ff; font-size: 12pt; font-family: times new roman,times;">"Визовые" иностранные работники – пошаговый порядок приёма на работу</span><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif''; color: black;"></span></p>\r\n<ul>\r\n<li style="color: black; text-align: justify; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Правила и сроки подачи работодателем заявки о потребности в иностранной рабочей силе.</span></li>\r\n<li style="color: black; text-align: justify; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Оформление разрешения на привлечения к работе иностранных сотрудников.</span></li>\r\n<li style="color: black; text-align: justify; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Постановка на учет в ФМС и оформление приглашения.</span></li>\r\n<li style="color: black; text-align: justify; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Разрешение на работу.&nbsp;Особенности уплаты и возврата госпошлины.</span></li>\r\n<li style="color: black; text-align: justify; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Трудовой договор: срочный или бессрочный? Какие документы необходимо получить у иностранца при приеме на работу? Договор гражданско-правового характера.</span></li>\r\n<li style="color: black; text-align: justify; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Какие государственные органы необходимо уведомить о приеме на работу иностранцев?&nbsp;Штрафы за нарушения сроков направления уведомления.</span></li>\r\n</ul>\r\n<p style="margin-left: 18pt; text-align: justify; text-indent: -18pt; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-family: times new roman,times;"><span style="font-size: 12pt; color: black;">&nbsp;</span><span style="color: #0000ff;"><span style="font-size: 12pt;">"Безвизовые" иностранные работники – пошаговый порядок приёма на работу</span></span></span><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif''; color: black;"></span></p>\r\n<ul>\r\n<li style="color: black; text-align: justify; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Нужно ли&nbsp;оформлять заявку&nbsp;о потребности в иностранной рабочей силе?</span></li>\r\n<li style="color: black; text-align: justify; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Разрешение на работу. Каким иностранцам разрешения на работу не нужны?</span></li>\r\n<li style="color: black; text-align: justify; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Уведомления в государственные органы: кому и о чем следует сообщить?</span></li>\r\n</ul>\r\n<p style="margin-left: 18pt; text-align: justify; text-indent: -18pt; line-height: normal; background: none repeat scroll 0% 0% white;"><strong><span style="color: #0000ff;"><span style="font-size: 12pt; font-family: Wingdings;"><span style="font-family: ''Times New Roman''; font-style: normal; font-variant: normal; font-size: 7pt; line-height: normal; font-size-adjust: none; font-stretch: normal; -moz-font-feature-settings: normal; -moz-font-language-override: normal;">&nbsp; </span></span></span></strong><span style="color: #0000ff;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Граждане Белоруссии и Казахстана: особенности приема на работу с учётом международного соглашения</span></span></p>\r\n<p style="margin-left: 18pt; text-align: justify; text-indent: -18pt; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="color: #0000ff;"><span style="font-size: 12pt; font-family: Wingdings;"><span style="font-family: ''Times New Roman''; font-style: normal; font-variant: normal; font-size: 7pt; line-height: normal; font-size-adjust: none; font-stretch: normal; -moz-font-feature-settings: normal; -moz-font-language-override: normal;">&nbsp; </span></span><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Высококвалифицированные специалисты: особенности приема на работу</span><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';"></span></span></p>\r\n<ul>\r\n<li style="color: black; text-align: justify; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Изменения в оформлении документов на привлечение ВКС. Новое в переоформлении рабочей визы.&nbsp;</span></li>\r\n<li style="color: black; text-align: justify; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Режим пребывания ВКС и продление сроков действия документов на их пребывание.&nbsp;</span></li>\r\n<li style="color: black; text-align: justify; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Члены семьи ВКС и их права.&nbsp;</span></li>\r\n</ul>\r\n<p style="margin-left: 18pt; text-align: justify; text-indent: -18pt; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="color: #0000ff;"><span style="font-size: 12pt; font-family: Wingdings;"><span style="font-family: ''Times New Roman''; font-style: normal; font-variant: normal; font-size: 7pt; line-height: normal; font-size-adjust: none; font-stretch: normal; -moz-font-feature-settings: normal; -moz-font-language-override: normal;">&nbsp; </span></span><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Ограничения на привлечение к работе иностранных работников</span></span><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif''; color: black;"></span></p>\r\n<ul>\r\n<li style="color: black; text-align: justify; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Запрет использование иностранцев в отдельных видах&nbsp;деятельности.</span></li>\r\n<li style="color: black; text-align: justify; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Квоты на выдачу приглашений и на выдачу разрешений на работу. На кого&nbsp;квотирование&nbsp;не распространяется? Обычные, квалифицированные и высококвалифицированные специалисты.</span></li>\r\n<li style="color: black; text-align: justify; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Наименование должности и фактически выполняемая работа.</span></li>\r\n<li style="color: black; text-align: justify; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Работа иностранцев за пределами субъекта РФ, на территории которого выдано разрешение на работу (разрешено временное проживание). Можно ли направить иностранца в командировку?&nbsp; Разъездной характер работы.</span></li>\r\n<li style="color: black; text-align: justify; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Требования к состоянию здоровья иностранных граждан.</span></li>\r\n<li style="color: black; text-align: justify; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Переход иностранца от одного работодателя к другому.</span></li>\r\n<li style="color: black; text-align: justify; line-height: normal; background: none repeat scroll 0% 0% white;"><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif'';">Штрафы за несоблюдение установленных ограничений.</span></li>\r\n</ul>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: justify; line-height: normal;">&nbsp;<span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Продолжительность семинара<b style="mso-bidi-font-weight: normal;">: </b>1 день&nbsp; Стоимость 3700.&nbsp;&nbsp;</span><span style="font-size: 12pt; font-family: ''Times New Roman'',''serif''; color: #993366;">Скидка</span><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;"><span style="color: #993366;"> 5%</span>&nbsp; при оплате за две недели<b style="mso-bidi-font-weight: normal;"><br /></b></span></p>\r\n<p>&nbsp;</p>\r\n<div style="position: absolute; left: -40px; top: 1599px; width: 1px; height: 1px; overflow: hidden;" data-mce-bogus="1" class="mcePaste" id="_mcePaste"><!--[if gte mso 9]><xml>\r\n <o:OfficeDocumentSettings>\r\n  <o:RelyOnVML/>\r\n  <o:AllowPNG/>\r\n </o:OfficeDocumentSettings>\r\n</xml><![endif]-->\r\n<p class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal;"><b><span style="font-size: 14.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;"><span style="mso-spacerun: yes;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span><span style="mso-spacerun: yes;">&nbsp;&nbsp;</span>Новый порядок привлечения и использования иностранной рабочей силы в<span style="mso-spacerun: yes;">&nbsp; </span>2013 году. Кадровые<span style="mso-spacerun: yes;">&nbsp; </span>и правовые<span style="mso-spacerun: yes;">&nbsp; </span>особенности оформления отношений с иностранными работниками.</span></b></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: justify; line-height: normal;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Семинар проводит: <b style="mso-bidi-font-weight: normal;">Боровиков Владимир Юревич,<span style="mso-spacerun: yes;">&nbsp; </span>доцент кафедры Управления<span style="mso-spacerun: yes;">&nbsp; </span>УрФУ, практикующий юрист, независимый эксперт-консультант ФТС РФ, специалист в области трудового и гражданского законодательства.</b></span></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: justify; line-height: normal;"><b style="mso-bidi-font-weight: normal;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">&nbsp;</span></b></p>\r\n<p class="MsoNormal" style="margin-bottom: .0001pt; text-align: justify; line-height: normal;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Продолжительность семинара<b style="mso-bidi-font-weight: normal;">: 7 ак. часов.</b></span></p>\r\n<p class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: center; line-height: normal;" align="center"><b><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">В программе семинара:</span></b></p>\r\n<p class="MsoNormal" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: center; line-height: normal;" align="center"><b><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Обзор изменения законодательства за 2012-2013гг. Новое в законодательстве о регулирование труда иностранных работников в соответствии с ФЗ О правовом положение иностранных граждан в РФ.</span></b></p>\r\n<p class="MsoListParagraph" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; margin-left: 18.0pt; mso-add-space: auto; text-align: justify; text-indent: -18.0pt; line-height: normal; mso-list: l0 level1 lfo11; background: white;"><span style="font-size: 12.0pt; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings; color: black; mso-fareast-language: RU;"><span style="mso-list: Ignore;">ü<span style="font: 7.0pt ''Times New Roman'';">&nbsp; </span></span></span><b><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">Правовое положение иностранных работников в&nbsp; РФ. </span></b><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;"></span></p>\r\n<ul type="disc">\r\n<li class="MsoNormal" style="color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal; mso-list: l1 level1 lfo1; tab-stops: list 36.0pt; background: white;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Статус иностранных работников - временно пребывающие, временно проживающие, постоянно проживающие.</span></li>\r\n<li class="MsoNormal" style="color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal; mso-list: l1 level1 lfo1; tab-stops: list 36.0pt; background: white;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Документы, подтверждающие статус иностранного работника.</span></li>\r\n<li class="MsoNormal" style="color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal; mso-list: l1 level1 lfo1; tab-stops: list 36.0pt; background: white;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Особенности пребывания на территории РФ каждой категории иностранных работников.</span></li>\r\n<li class="MsoNormal" style="color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal; mso-list: l1 level1 lfo1; tab-stops: list 36.0pt; background: white;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Порядок оформления вида на жительство ВКС и членов его семьи.</span></li>\r\n</ul>\r\n<p class="MsoListParagraph" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; margin-left: 18.0pt; mso-add-space: auto; text-align: justify; text-indent: -18.0pt; line-height: normal; mso-list: l9 level1 lfo10; background: white;"><span style="font-size: 12.0pt; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings; color: black; mso-fareast-language: RU;"><span style="mso-list: Ignore;">ü<span style="font: 7.0pt ''Times New Roman'';">&nbsp; </span></span></span><b><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">Порядок въезда иностранного работника на территорию РФ.</span></b><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;"></span></p>\r\n<ul type="disc">\r\n<li class="MsoNormal" style="color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal; mso-list: l5 level1 lfo2; tab-stops: list 36.0pt; background: white;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Безвизовый въезд на территорию РФ.&nbsp; Миграционная карта.</span></li>\r\n<li class="MsoNormal" style="color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal; mso-list: l5 level1 lfo2; tab-stops: list 36.0pt; background: white;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Въезд в порядке, требующем получения визы. Виды и категории виз.&nbsp; Продление виз, оформление многократных виз. Порядок оформления виз для ВКС.</span></li>\r\n<li class="MsoNormal" style="color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal; mso-list: l5 level1 lfo2; tab-stops: list 36.0pt; background: white;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Оформление приглашений на въезд. Гарантии материального, медицинского и жилищного обеспечения.</span></li>\r\n</ul>\r\n<p class="MsoListParagraph" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; margin-left: 18.0pt; mso-add-space: auto; text-align: justify; text-indent: -18.0pt; line-height: normal; mso-list: l6 level1 lfo9; background: white;"><span style="font-size: 12.0pt; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings; color: black; mso-fareast-language: RU;"><span style="mso-list: Ignore;">ü<span style="font: 7.0pt ''Times New Roman'';">&nbsp; </span></span></span><b><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">Особенности миграционного учета.</span></b><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;"></span></p>\r\n<ul type="disc">\r\n<li class="MsoNormal" style="color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal; mso-list: l11 level1 lfo3; tab-stops: list 36.0pt; background: white;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Правила постановки и снятия иностранца с миграционного учета.</span></li>\r\n<li class="MsoNormal" style="color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal; mso-list: l11 level1 lfo3; tab-stops: list 36.0pt; background: white;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Какие обязанности возлагаются на &nbsp;принимающую сторону?</span></li>\r\n<li class="MsoNormal" style="color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal; mso-list: l11 level1 lfo3; tab-stops: list 36.0pt; background: white;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Особенности миграционного учета отдельных категорий граждан. Миграционный учет ВКС.</span></li>\r\n<li class="MsoNormal" style="color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal; mso-list: l11 level1 lfo3; tab-stops: list 36.0pt; background: white;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Штраф за нарушение сроков и порядка постановки на миграционный учет.</span></li>\r\n</ul>\r\n<p class="MsoListParagraph" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; margin-left: 18.0pt; mso-add-space: auto; text-align: justify; text-indent: -18.0pt; line-height: normal; mso-list: l3 level1 lfo8; background: white;"><span style="font-size: 12.0pt; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings; color: black; mso-fareast-language: RU;"><span style="mso-list: Ignore;">ü<span style="font: 7.0pt ''Times New Roman'';">&nbsp; </span></span></span><b><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">"Визовые" иностранные работники – пошаговый порядок приёма на работу.</span></b><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;"></span></p>\r\n<ul type="disc">\r\n<li class="MsoNormal" style="color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal; mso-list: l4 level1 lfo4; tab-stops: list 36.0pt; background: white;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Правила и сроки подачи работодателем заявки о потребности в иностранной рабочей силе.</span></li>\r\n<li class="MsoNormal" style="color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal; mso-list: l4 level1 lfo4; tab-stops: list 36.0pt; background: white;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Оформление разрешения на привлечения к работе иностранных сотрудников.</span></li>\r\n<li class="MsoNormal" style="color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal; mso-list: l4 level1 lfo4; tab-stops: list 36.0pt; background: white;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Постановка на учет в ФМС и оформление приглашения.</span></li>\r\n<li class="MsoNormal" style="color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal; mso-list: l4 level1 lfo4; tab-stops: list 36.0pt; background: white;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Разрешение на работу.&nbsp;Особенности уплаты и возврата госпошлины.</span></li>\r\n<li class="MsoNormal" style="color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal; mso-list: l4 level1 lfo4; tab-stops: list 36.0pt; background: white;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Трудовой договор: срочный или бессрочный? Какие документы необходимо получить у иностранца при приеме на работу? Договор гражданско-правового характера.</span></li>\r\n<li class="MsoNormal" style="color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal; mso-list: l4 level1 lfo4; tab-stops: list 36.0pt; background: white;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Какие государственные органы необходимо уведомить о приеме на работу иностранцев?&nbsp;Штрафы за нарушения сроков направления уведомления.</span></li>\r\n</ul>\r\n<p class="MsoListParagraph" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; margin-left: 18.0pt; mso-add-space: auto; text-align: justify; text-indent: -18.0pt; line-height: normal; mso-list: l3 level1 lfo8; background: white;"><span style="font-size: 12.0pt; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings; color: black; mso-fareast-language: RU;"><span style="mso-list: Ignore;">ü<span style="font: 7.0pt ''Times New Roman'';">&nbsp; </span></span></span><b><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">"Безвизовые" иностранные работники – пошаговый порядок приёма на работу.</span></b><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;"></span></p>\r\n<ul type="disc">\r\n<li class="MsoNormal" style="color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal; mso-list: l7 level1 lfo5; tab-stops: list 36.0pt; background: white;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Нужно ли&nbsp;оформлять заявку&nbsp;о потребности в иностранной рабочей силе?</span></li>\r\n<li class="MsoNormal" style="color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal; mso-list: l7 level1 lfo5; tab-stops: list 36.0pt; background: white;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Разрешение на работу. Каким иностранцам разрешения на работу не нужны?</span></li>\r\n<li class="MsoNormal" style="color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal; mso-list: l7 level1 lfo5; tab-stops: list 36.0pt; background: white;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Уведомления в государственные органы: кому и о чем следует сообщить?</span></li>\r\n</ul>\r\n<p class="MsoListParagraphCxSpFirst" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; margin-left: 18.0pt; mso-add-space: auto; text-align: justify; text-indent: -18.0pt; line-height: normal; mso-list: l3 level1 lfo8; background: white;"><span style="font-size: 12.0pt; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings; color: black; mso-fareast-language: RU;"><span style="mso-list: Ignore;">ü<span style="font: 7.0pt ''Times New Roman'';">&nbsp; </span></span></span><b><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">Граждане Белоруссии и Казахстана: особенности приема на работу с учётом международного соглашения.</span></b><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;"></span></p>\r\n<p class="MsoListParagraphCxSpLast" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; margin-left: 18.0pt; mso-add-space: auto; text-align: justify; text-indent: -18.0pt; line-height: normal; mso-list: l3 level1 lfo8; background: white;"><span style="font-size: 12.0pt; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings; color: black; mso-fareast-language: RU;"><span style="mso-list: Ignore;">ü<span style="font: 7.0pt ''Times New Roman'';">&nbsp; </span></span></span><b><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">Высококвалифицированные специалисты: особенности приема на работу.</span></b><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">&nbsp;</span></p>\r\n<ul type="disc">\r\n<li class="MsoNormal" style="color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal; mso-list: l10 level1 lfo6; tab-stops: list 36.0pt; background: white;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Изменения в оформлении документов на привлечение ВКС. Новое в переоформлении рабочей визы.&nbsp;</span></li>\r\n<li class="MsoNormal" style="color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal; mso-list: l10 level1 lfo6; tab-stops: list 36.0pt; background: white;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Режим пребывания ВКС и продление сроков действия документов на их пребывание.&nbsp;</span></li>\r\n<li class="MsoNormal" style="color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal; mso-list: l10 level1 lfo6; tab-stops: list 36.0pt; background: white;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Члены семьи ВКС и их права.&nbsp;</span></li>\r\n</ul>\r\n<p class="MsoListParagraph" style="mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; margin-left: 18.0pt; mso-add-space: auto; text-align: justify; text-indent: -18.0pt; line-height: normal; mso-list: l2 level1 lfo12; background: white;"><span style="font-size: 12.0pt; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings; color: black; mso-fareast-language: RU;"><span style="mso-list: Ignore;">ü<span style="font: 7.0pt ''Times New Roman'';">&nbsp; </span></span></span><b><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;">Ограничения на привлечение к работе иностранных работников.</span></b><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; color: black; mso-fareast-language: RU;"></span></p>\r\n<ul type="disc">\r\n<li class="MsoNormal" style="color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal; mso-list: l8 level1 lfo7; tab-stops: list 36.0pt; background: white;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Запрет использование иностранцев в отдельных видах&nbsp;деятельности.</span></li>\r\n<li class="MsoNormal" style="color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal; mso-list: l8 level1 lfo7; tab-stops: list 36.0pt; background: white;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Квоты на выдачу приглашений и на выдачу разрешений на работу. На кого&nbsp;квотирование&nbsp;не распространяется? Обычные, квалифицированные и высококвалифицированные специалисты.</span></li>\r\n<li class="MsoNormal" style="color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal; mso-list: l8 level1 lfo7; tab-stops: list 36.0pt; background: white;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Наименование должности и фактически выполняемая работа.</span></li>\r\n<li class="MsoNormal" style="color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal; mso-list: l8 level1 lfo7; tab-stops: list 36.0pt; background: white;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Работа иностранцев за пределами субъекта РФ, на территории которого выдано разрешение на работу (разрешено временное проживание). Можно ли направить иностранца в командировку?&nbsp; Разъездной характер работы.</span></li>\r\n<li class="MsoNormal" style="color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal; mso-list: l8 level1 lfo7; tab-stops: list 36.0pt; background: white;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Требования к состоянию здоровья иностранных граждан.</span></li>\r\n<li class="MsoNormal" style="color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal; mso-list: l8 level1 lfo7; tab-stops: list 36.0pt; background: white;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Переход иностранца от одного работодателя к другому.</span></li>\r\n<li class="MsoNormal" style="color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; text-align: justify; line-height: normal; mso-list: l8 level1 lfo7; tab-stops: list 36.0pt; background: white;"><span style="font-size: 12.0pt; font-family: ''Times New Roman'',''serif''; mso-fareast-font-family: ''Times New Roman''; mso-fareast-language: RU;">Штрафы за несоблюдение установленных ограничений.</span></li>\r\n</ul>\r\n<!--[if gte mso 9]><xml>\r\n <w:WordDocument>\r\n  <w:View>Normal</w:View>\r\n  <w:Zoom>0</w:Zoom>\r\n  <w:TrackMoves/>\r\n  <w:TrackFormatting/>\r\n  <w:PunctuationKerning/>\r\n  <w:ValidateAgainstSchemas/>\r\n  <w:SaveIfXMLInvalid>false</w:SaveIfXMLInvalid>\r\n  <w:IgnoreMixedContent>false</w:IgnoreMixedContent>\r\n  <w:AlwaysShowPlaceholderText>false</w:AlwaysShowPlaceholderText>\r\n  <w:DoNotPromoteQF/>\r\n  <w:LidThemeOther>RU</w:LidThemeOther>\r\n  <w:LidThemeAsian>X-NONE</w:LidThemeAsian>\r\n  <w:LidThemeComplexScript>X-NONE</w:LidThemeComplexScript>\r\n  <w:Compatibility>\r\n   <w:BreakWrappedTables/>\r\n   <w:SnapToGridInCell/>\r\n   <w:WrapTextWithPunct/>\r\n   <w:UseAsianBreakRules/>\r\n   <w:DontGrowAutofit/>\r\n   <w:SplitPgBreakAndParaMark/>\r\n   <w:EnableOpenTypeKerning/>\r\n   <w:DontFlipMirrorIndents/>\r\n   <w:OverrideTableStyleHps/>\r\n  </w:Compatibility>\r\n  <m:mathPr>\r\n   <m:mathFont m:val="Cambria Math"/>\r\n   <m:brkBin m:val="before"/>\r\n   <m:brkBinSub m:val="&#45;-"/>\r\n   <m:smallFrac m:val="off"/>\r\n   <m:dispDef/>\r\n   <m:lMargin m:val="0"/>\r\n   <m:rMargin m:val="0"/>\r\n   <m:defJc m:val="centerGroup"/>\r\n   <m:wrapIndent m:val="1440"/>\r\n   <m:intLim m:val="subSup"/>\r\n   <m:naryLim m:val="undOvr"/>\r\n  </m:mathPr></w:WordDocument>\r\n</xml><![endif]--><!--[if gte mso 9]><xml>\r\n <w:LatentStyles DefLockedState="false" DefUnhideWhenUsed="true"\r\n  DefSemiHidden="true" DefQFormat="false" DefPriority="99"\r\n  LatentStyleCount="267">\r\n  <w:LsdException Locked="false" Priority="0" SemiHidden="false"\r\n   UnhideWhenUsed="false" QFormat="true" Name="Normal"/>\r\n  <w:LsdException Locked="false" Priority="9" S