(52, 103, 'Бизнес тренер Хабирова Татьяна', 'biznes-trener-khabirova-tatyana', '<h1 style="margin-right: 14.15pt; text-align: justify;"><span style="font-size: 12pt; font-family: times new roman,times; color: #0000ff;"><b><span style="font-size: 14pt;">Хабирова Татьяна Валерьевна&nbsp; </span></b></span><strong><span style="font-family: Tahoma; font-size: 12pt;"><span style="font-size: 14pt;"></span></span></strong></h1>\r\n<p style="margin-right: 14.15pt; text-align: justify;"><span style="font-family: Tahoma; font-size: 12pt;"><span style="font-family: times new roman,times;">Бизнес - тренер,&nbsp; коуч</span> </span><span style="font-size: 12pt; font-family: times new roman,times;">с 2009 года. Проведение сборных и корпоративных тренингов по направлениям:<span style="text-decoration: underline;"></span><b><span style="text-decoration: underline;"><br style="font-size: 12pt; font-family: times new roman,times;" /></span></b></span></p>\r\n<p style="margin-right: 14.15pt; text-align: justify;"><!--[if gte mso 9]><xml>\r\n <w:LatentStyles DefLockedState="false" DefUnhideWhenUsed="true"\r\n  DefSemiHidden="true" DefQFormat="false" DefPriority="99"\r\n  LatentStyleCount="267">\r\n  <w:LsdException Locked="false" Priority="0" SemiHidden="false"\r\n   UnhideWhenUsed="false" QFormat="true" Name="Normal"/>\r\n  <w:LsdException Locked="false" Priority="9" SemiHidden="false"\r\n   UnhideWhenUsed="false" QFormat="true" Name="heading 1"/>\r\n  <w:LsdException Locked="false" Priority="9" QFormat="true" Name="heading 2"/>\r\n  <w:LsdException Locked="false" Priority="9" QFormat="true" Name="heading 3"/>\r\n  <w:LsdException Locked="false" Priority="9" QFormat="true" Name="heading 4"/>\r\n  <w:LsdException Locked="false" Priority="9" QFormat="true" Name="heading 5"/>\r\n  <w:LsdException Locked="false" Priority="9" QFormat="true" Name="heading 6"/>\r\n  <w:LsdException Locked="false" Priority="9" QFormat="true" Name="heading 7"/>\r\n  <w:LsdException Locked="false" Priority="9" 