n style="font-size: 18.0pt; line-height: 115%; font-family: ''Century Schoolbook''; mso-bidi-font-family: Tahoma; font-style: normal; mso-bidi-font-style: italic;">ХАБИРОВА ТАТЬЯНА ВАЛЕРЬЕВНА</span></b></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n<!--[if gte mso 9]><xml>\r\n <w:LatentStyles DefLockedState="false" LatentStyleCount="156">\r\n </w:LatentStyles>\r\n</xml><![endif]--><!--[if gte mso 10]>\r\n\r\n<![endif]--></div>', '', 1, 2, '2013-12-24 09:46:12', 42, '', '2014-05-27 06:00:52', 42, 0, '0000-00-00 00:00:00', '2013-12-24 09:46:12', '0000-00-00 00:00:00', '{"image_intro":"","float_intro":"","image_intro_alt":"","image_intro_caption":"","image_fulltext":"","float_fulltext":"","image_fulltext_alt":"","image_fulltext_caption":""}', '{"urla":null,"urlatext":"","targeta":"","urlb":null,"urlbtext":"","targetb":"","urlc":null,"urlctext":"","targetc":""}', '{"show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_layout":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 15, 31, '', '', 1, 501, '{"robots":"","author":"","rights":"","xreference":""}', 0, '*', '');
