(1, 'Blue message', 'blue-message', '  background: none repeat scroll 0 0 #3399ff;\r\n  color: #ffffff;\r\n  text-shadow: none;\r\n  font-size: 14px;\r\n  line-height: 24px;\r\n  padding: 10px;\r\n\r\n', 1, 1),
(2, 'Green message', 'green-message', '\n  background: none repeat scroll 0 0 #8cc14c;\n  color: #ffffff;\n  text-shadow: none;\n  font-size: 14px;\n  line-height: 24px;\n  padding: 10px;\n\n', 1, 2),
(3, 'Orange message', 'orange-message', '\n  background: none repeat scroll 0 0 #faa732;\n  color: #ffffff;\n  text-shadow: none;\n  font-size: 14px;\n  line-height: 24px;\n  padding: 10px;\n\n', 1, 3),
(4, 'Red message', 'red-message', '\n  background: none repeat scroll 0 0 #da4d31;\n  color: #ffffff;\n  text-shadow: none;\n  font-size: 14px;\n  line-height: 24px;\n  padding: 10px;\n\n', 1, 4),
(5, 'Grey message', 'grey-message', '\n  background: none repeat scroll 0 0 #53555c;\n  color: #ffffff;\n  text-shadow: none;\n  font-size: 14px;\n  line-height: 24px;\n  padding: 10px;\n\n', 1, 5),
(6, 'Left block', 'left-block', '\n  background: none repeat scroll 0 0px, radial-gradient(ellipse at center center, #ffffff 0%, #f2f2f2 100%) repeat scroll 0 0 rgba(0, 0, 0, 0);\n  color: #8b8e97;\n  padding: 10px;\n  margin: 10px;\n  float: left;\n\n', 1, 6),
(7, 'Right block', 'right-block', '\n  background: none repeat scroll 0 0px, radial-gradient(ellipse at center center, #ffffff 0%, #f2f2f2 100%) repeat scroll 0 0 rgba(0, 0, 0, 0);\n  color: #8b8e97;\n  padding: 10px;\n  margin: 10px;\n  float: right;\n\n', 1, 7),
(8, 'Blockquotes', 'blockquotes', '\n  background: none;\n  border-left: 5px solid #f1f1f1;\n  color: #8B8E97;\n  font-size: 14px;\n  font-style: italic;\n  line-height: 22px;\n  padding-left: 15px;\n  padding: 10px;\n  width: 60%;\n  float: left;\n\n', 1, 8);
